COPLAS_PIEZA(5, [["frenk_t1-n1248",5,"Ya me despido de mi querida Adela,\nde ti un recuerdo quisiera llevar;\ntu retrato lo llevo en mi pecho,\ncomo escudo que me haga triunfar.",91,2,16,87,"•'I.a Adelita",3,4,"a",21,0,-1,0,213,213,"1248","",0,"","","",1,0,0,[],""],["frenk_t1-n1249",5,"Una dádiva sencilla\nte pido por nuestro amor:\nregálame una sombrilla\npara cubrirme del sol.",75,2,-1,87,"Glosada en décimas",0,4,"o",-1,0,-1,0,213,213,"1249","",0,"","","",1,0,0,[],""],["frenk_t1-n1250",5,"Morena, cuando te vayas,\nme dejarás un recuerdo,\npara limpiarme el sudor\ncon un pañuelito negro.",82,2,7,87,"Estrofa suelta",0,4,"eo",-1,0,-1,0,213,213,"1250","",0,"","","",1,0,0,[],""],["frenk_t1-n1251",5,"Trigueñita de mi vida,\ntrigueñita de mi anhelo,\ntrigueñita de mi amor,\ny si me tienes amor,\nde pena dame un pañuelo,\npara limpiarme el sudor\nque se me incrusta en el pelo.",75,2,-1,87,"‘‘El carpintero",4,7,"eo",10,0,-1,0,213,213,"1251","",0,"","","",3,0,0,[],""],["frenk_t1-n1252",5,"Mariquita, María,\nMaría del Carmen,\npréstame tu peineta\npara peinarme.",75,2,-1,87,"María del Carmen; El pájaro cú",6,4,"ae",-1,0,-1,0,213,213,"1252","",0,"","","",12,0,0,[],""],["frenk_t1-n1253",5,"Mariquita, María,\nMaría del cielo,\npréstame tu peineta\npa asearme el pelo.",83,2,8,87,"María del Carmen",0,4,"eo",10,0,-1,0,213,213,"1253","",0,"","","",12,0,0,[],""],["frenk_t1-n1254",5,"Qué bonita está María,\nMaría del Carmen,\npréstame tu esperanza\npara acordarme.",79,2,4,87,"El pájaro cú",6,4,"ae",-1,0,-1,0,213,213,"1254","",0,"","","",1,0,0,[],""],["frenk_t1-n1255",5,"¡Ah!, qué noche tan serena,\ny las estrellas ralitas.\nRegálame una azucena\ncortada con tus manitas,\npara divertir mis penas\ncontándole las hojitas.",101,2,26,87,"La azucena",9,6,"ia",258,0,-1,0,213,213,"1255","",0,"","","",2,0,0,[],""],["frenk_t1-n1256",5,"No seas ingrata, chiquita,\nde cabello enmadejado:\nregálame esa rosita\nde tu jardín matizado\ny un beso de tu boquita,\nque de ti ando enamorado.",75,2,-1,87,"Áhi viene el agua",9,6,"ao",14,0,-1,0,214,214,"1256","",0,"","","",1,0,0,[],""],["frenk_t1-n1257",5,"Con toda mi alma quisiera\nsuplicarte mi dolor;\nnada tengo, y si tuviera,\nte ofrecería lo mejor,\ntan sólo porque me dieras\nde tu jardín una flor.",75,2,-1,87,"El siquisirí; La morena",9,6,"o",72,0,-1,0,214,214,"1257","",0,"","","",1,0,0,[],""],["frenk_t1-n1259",5,"Preciosa ave lucida,\ntu mirada a mí me encanta;\nsi tú eres compadecida,\nregálame una flor santa\nque en el pelo traes prendida.",79,2,4,87,"El fandanguito",7,5,"ia",37,0,-1,0,214,214,"1259","",0,"","","",1,0,0,[],""],["frenk_t1-n1261",5,"Yo quisiera que un lelito\ntú me estuvieras ofreciendo;\naunque soy un pobrecito,\nte lo estoy agradeciendo.",75,2,-1,87,"El lelito",1,4,"eo",52,0,-1,0,214,214,"1261","",0,"","","",1,0,0,[],""],["frenk_t1-n1265",5,"Si fueres a Coahuayana,\nme traerás una sandía\nde corazón colorado,\nregalo del alma mía.",103,2,28,87,"Coahuayana",0,4,"ia",0,0,-1,0,215,215,"1265","",0,"frenk_t4","","",5,0,0,[],""],["frenk_t1-n1279",5,"Si me muero, me entierras\njunto a tu cama,\nque me sirvan de luces\ntus ojos, mi alma.",75,2,-1,87,"Estrofa suelta",6,4,"aa",-1,0,-1,0,217,217,"1279","",0,"","","",1,0,0,[],""],["frenk_t1-n1281",5,"Pon cuidado cómo vuela\ndel árbol la guacamaya,\npara que así vueles tú\ncuando contigo me vaya.",79,2,4,87,"La guacamaya",0,4,"aa",404,0,-1,0,217,217,"1281","",0,"","","",1,0,0,[],""],["frenk_t1-n1282",5,"Pon cuidado cuando vuele\nla guacamaya del nido,\npara que así vueles tú\ncuando te vayas conmigo.",79,2,4,87,"La guacamaya",0,4,"io",-1,0,-1,0,217,217,"1282","",0,"","","",1,0,0,[],""],["frenk_t1-n1284",5,"En esta carta bonita\nme has de decir la verdad:\n¿qué has pensado, trigueñita?,\n¿cuándo conmigo te vas?\nTe suplico, jovencita,\nno me niegues tu amistad.",79,2,4,87,"Estrofa suelta",9,6,"a",-1,0,-1,0,217,217,"1284","",0,"","","",1,0,0,[],""],["frenk_t1-n1285",5,"Dime si te vas conmigo,\ny la fecha me pondrás,\npara venir con Cupido,\nporque soy hombre capaz\nde sostener lo que digo.",75,2,-1,87,"Estrofa suelta",7,5,"io",-1,0,-1,0,217,217,"1285","",0,"","","",1,0,0,[],""],["frenk_t1-n1287",5,"Quiera Dios, linda de mi alma,\nque yo me la lleve a usted,\nque me ha robado la calma\nsin tener culpa ninguna;\nme dicen que por tunante,\nque me queje a mi fortuna.",75,2,-1,87,"Estrofa suelta",9,6,"ua",56,0,-1,0,218,218,"1287","",0,"","","",1,0,0,[],""],["frenk_t1-n1288",5,"Negra, como bien te portes,\na mi patria vas a dar;\nsi nos quieren criminar\ny si nos ponen exhorte,\npor nosotros no han de dar\nni las águilas del norte.",75,2,-1,87,"Zapateado",9,6,"oe",402,0,-1,0,218,218,"1288","",0,"","","",1,0,0,[],""],["frenk_t1-n1289",5,"Negrita, tú no te cortes,\noye bien lo que te digo:\nque como malo te portes,\ndices si te vas conmigo,\ny las águilas del monte\nvan a poder i’a contigo.",79,2,4,87,"Cuando despedirme fui",9,6,"io",106,0,-1,0,218,218,"1289","",0,"","","",1,0,0,[],""],["frenk_t1-n1291",5,"Soy Eduardo Magallón\nde la nación mexicana;\nsi tú me quieres, morena,\nte llevo, aunque sea mañana",82,2,7,87,"Estrofa suelta",0,4,"aa",4,0,-1,0,218,218,"1291","",0,"","","",1,0,0,[],""],["frenk_t1-n1293",5,"Como gavilán me atrevo\na llevarte, palomita;\nse me hace que me la llevo,\ny a que nadie me la quita,\nsólo que me salga un ciego\npidiéndome limosnita.",81,2,6,87,"La leva",9,6,"ia",50,0,-1,0,218,218,"1293","",0,"","","",1,0,0,[],""],["frenk_t1-n1294",5,"Eres arenita de oro,\nte lleva el agua;\nasí me la llevo yo\ncon una seña que le haga.",75,2,-1,87,"Eres arenita de oro",3,4,"aa",-1,0,-1,0,218,218,"1294","",0,"","","",2,0,0,[],""],["frenk_t1-n1295",5,"—A que no me lleva el río,\npor más crecido que vaya.\n—A que yo sí me la llevo,\ncon una seña que le haga.",75,2,-1,87,"Eres arenita de oro",0,4,"aa",-1,0,-1,0,219,219,"1295","",0,"","","",1,0,0,[],""],["frenk_t1-n1296",5,"Morena, morena,\nmorena del mar,\nme la retellevo,\nme la he de llevar.",82,2,7,87,"La morenita",0,4,"a",21,0,-1,0,219,219,"1296","",0,"","","",1,0,0,[],""],["frenk_t1-n1297",5,"Una guacamaya pinta\nle dijo a una colorada:\n“Vámonos para mi tierra\na pasar la temporada.”",79,2,4,87,"La guacamaya; La cucaracha; Estrofa suelta",0,4,"aa",49,0,-1,0,219,219,"1297","",0,"","","",8,0,0,[],""],["frenk_t1-n1298",5,"Negrita, yo te decía,\ntrae tus naguas coloradas,\npero te sales conmigo\ntodita la temporada.",75,2,-1,87,"La negra",0,4,"aa",-1,0,-1,0,219,219,"1298","",0,"","","",1,0,0,[],""],["frenk_t1-n1299",5,"No más tu palabra aguardo,\nvida mía, pa poderme ir,\ny nos vamos a pasear\nen ese ferrocarril.",89,2,14,87,"Vengo a que me desengañes",0,4,"i",-1,0,-1,0,219,219,"1299","",0,"","","",1,0,0,[],""],["frenk_t1-n1300",5,"Cuando [oigas] silbar el tren\nen el que voy a llegar,\nespérame en el andén,\npara llevarte a pasear.",75,2,-1,87,"El rielero",1,4,"a",21,0,-1,0,219,219,"1300","",0,"","","",1,0,0,[],""],["frenk_t1-n1301",5,"Qué dices, chato, ¿nos vamos?,\nya viene el tren caminando:\nla máquina viene lejos,\npero ya viene silbando;\nvamos a darnos la vuelta,\nchiquito, pues ahora es cuando",75,2,-1,87,"En la mano derecha",9,6,"ao",33,0,-1,0,219,219,"1301","",0,"","","",1,0,0,[],""],["frenk_t1-n1302",5,"Te invito para un paseo\ny en un nuevo dirigible;\nque te niegues, no lo creo,\nque te quedes, imposible;\ncomo es viaje de recreo,\ntenemos el paso libre.",79,2,4,87,"La morena, Zapateado",9,6,"ie",-1,0,-1,0,220,220,"1302","",0,"","","",1,0,0,[],""],["frenk_t1-n1303",5,"Muchas cosas bonitas\nirás a conocer;\ncruzaremos las nubes\nen viaje de placer.",75,2,-1,87,"El amor de mi vida",0,4,"e",20,0,-1,0,220,220,"1303","",0,"","","",1,0,0,[],""],["frenk_t1-n1306",5,"Anda, linda guacamaya,\nte suplico por favor\ny te ruego me acompañes\nal cerrito Mirador.",85,2,10,87,"La guacamaya",0,4,"o",72,0,-1,0,220,220,"1306","",0,"","","",1,0,0,[],""],["frenk_t1-n1308",5,"Cotorra del pico chueco,\nprima hermana del perico,\nsi te pones tu plumita,\nyo te llevo hasta Tampico.",82,2,7,87,"El toro rabón",0,4,"io",141,0,-1,0,220,220,"1308","",0,"","","",2,0,0,[],""],["frenk_t1-n1309",5,"Si quieres ir a saber\nal pueblo de Tlalecoya,\nte llevaré a pasear,\nte llevaré en canoya,\ny te vuelvo a regresar\nen el caballo de Troya.",83,2,8,87,"Zapateado",9,6,"oa",537,0,-1,0,221,221,"1309","",0,"","","",1,0,0,[],""],["frenk_t1-n1310",5,"Soy pájaro que al volar\ndeja formado su nido;\ny te puedo asegurar\nque si tú te vas conmigo,\nte he de llevar a pasear\na los Estados Unidos.",83,2,8,87,"El pájaro cú",9,6,"io",-1,0,-1,0,221,221,"1310","",0,"","","",1,0,0,[],""],["frenk_t1-n1311",5,"Desde Atlixco de las flores\nbien se devisa un vulcán;\nchatita de mis amores,\npor ti éstos me matarán,\npero si tú te vas conmigo\npor el rumbo de Acatlán.",87,2,12,87,"Estrofa suelta",9,6,"a",147,0,-1,0,221,221,"1311","",0,"","","",1,0,0,[],""],["frenk_t1-n1313",5,"¡Ay de mí!, Llorona (Llorona),\nLlorona de azul turquí;\nte llevaré a Juchitán (Llorona),\nque es donde te conocí.",83,2,8,87,"La Llorona; La Zandunga",3,4,"i",23,0,-1,0,221,221,"1313","",0,"","","",4,0,0,[],""],["frenk_t1-n1323",5,"¡Ay de mí!, Llorona,\nLlorona, llévame al río,\na ver si sus aguas juntan (Llorona)\ntu corazón con el mío.",83,2,8,87,"La Llorona",3,4,"io",3,0,-1,0,223,223,"1323","",0,"","","",35,0,0,[],""],["frenk_t1-n1324",5,"Teresita, vamos a la playa,\nTeresita, vamos a la mar,\na pasarnos las horas felices,\nTeresita, en aquel arenal.",82,2,7,87,"Teresita",3,4,"a",-1,0,-1,0,223,223,"1324","",0,"","","",2,0,0,[],""],["frenk_t1-n1325",5,"Teresita, vamos a la playa,\nTeresita, vamos a la mar,\npara decirte lo que yo he sabido:\nque en el mundo no te he de olvidar.",82,2,7,87,"Teresita",3,4,"a",21,0,-1,0,223,223,"1325","",0,"","","",2,0,0,[],""],["frenk_t1-n1326",5,"Si quieres, vamos y en mi barquilla,\nsi quieres, vamos, te llevaré,\nsi quieres, vamos, en la otra orilla\nnuevas canciones te cantaré.",83,2,8,87,"Las gaviotas; Corazón sólido",3,4,"e",77,0,-1,0,223,223,"1326","",0,"","","",1,0,0,[],""],["frenk_t1-n1327",5,"María Chuchena, bótate al agua,\nvente a la proa de mi piragua;\nMaría Chuchena, bótate al río,\nque yo por ti me muero de frío.",75,2,-1,87,"María Chuchena",3,4,"io",3,0,-1,0,223,223,"1327","",0,"","","",1,0,0,[],""],["frenk_t1-n1328",5,"Margarita, Margarita,\nvamos a los caracoles:\ntú cortas de los azules,\ny yo, de todos colores.",86,2,11,87,"Margarita",0,4,"oe",-1,0,-1,0,223,223,"1328","",0,"","","",4,0,0,[],""],["frenk_t1-n1329",5,"Si quieres, vamos al mar\na pescar caracolitos:\ntú pescas de los azules,\ny yo, de los más bonitos.",78,2,3,87,"Si quieres, varaos al mar",0,4,"io",254,0,-1,0,223,223,"1329","",0,"","","",2,0,0,[],""],["frenk_t1-n1330",5,"Conchitas y caracoles\nvide brillar en la mar;\ndame tu mano, morena,\nvámonos a navegar.",75,2,-1,87,"Conchitas y caracoles",0,4,"a",21,0,-1,0,223,223,"1330","",0,"","","",1,0,0,[],""],["frenk_t1-n1331",5,"A la salida del sol\njuntos iremos al mar:\nmientras yo bato los remos (Lolita),\ntú llevarás el timón.",85,2,10,87,"Di si me quieres, Lola",3,4,"o",-1,0,-1,0,223,223,"1331","",0,"","","",1,0,0,[],""],["frenk_t1-n1332",5,"Chinita, vamos al mar,\nallá nos embarcaremos:\nque mi cuerpo será el barco,\ntus brazos serán los remos.",75,2,-1,87,"Las olas de la laguna’’, Si quieres, vamos al mar",0,4,"eo",127,0,-1,0,224,224,"1332","",0,"","","",1,0,0,[],""],["frenk_t1-n1333",5,"Rema y rema, Mariquita,\nrema para el otro lado;\nverás qué revoloteo\nde aguardiente azucarado.",75,2,-1,87,"Estrofa suelta",0,4,"ao",14,0,-1,0,224,224,"1333","",0,"","","",1,0,0,[],""],["frenk_t1-n1334",5,"A la mar que te vayas\nme iré contigo,\npara ver cómo vences\nal enemigo.",79,2,4,87,"La bamba",6,4,"io",106,0,-1,0,224,224,"1334","",0,"","","",3,0,0,[],""],["frenk_t1-n1336",5,"¡Ay!, que le da,\ny vamos a ver,\na ver cómo corre el agua:\nvamos a verla correr.",82,2,7,87,"Mariquita quita, quita",3,4,"e",20,0,-1,0,224,224,"1336","",0,"","","",1,0,0,[],""],["frenk_t1-n1338",5,"Por debajo de la arena\ncorre el agua y nacen flores;\ncamino de Santo Domingo,\npalacio de mis amores.",75,2,-1,87,"Estrofa suelta",0,4,"oe",5,0,-1,0,224,224,"1338","",0,"","","",6,0,0,[],""],["frenk_t1-n1339",5,"Si quieres, conmigo vente,\nque me voy a divertir\na la margen de una fuente,\na ver el agua salir.",79,2,4,87,"El Balajú",1,4,"i",157,0,-1,0,224,224,"1339","",0,"","","",1,0,0,[],""],["frenk_t1-n1340",5,"Madrecita, lléveme usted al baño,\nmadrecita, lléveme usted allá;\nlos calores a mí me consumen (¡ay!),\nmadrecita, qué fuerte es mi mal.",75,2,-1,87,"Estrofa suelta, Los baños",3,4,"a",-1,0,-1,0,225,225,"1340","",0,"","","",1,0,0,[],""],["frenk_t1-n1341",5,"Chaparrita de mi vida,\nsuelta el agua pura\npara que me bañe\nen el mar yo.",75,2,-1,87,"La zamba",6,4,"o",-1,0,-1,0,225,225,"1341","",0,"","","",7,0,0,[],""],["frenk_t1-n1343",5,"Sal a ver el horizonte,\nque ya comienza a alumbrar,\ny tu vestidito ponte,\nporque te llevo a pasear.",75,2,-1,87,"Las mañanitas",1,4,"a",21,0,-1,0,225,225,"1343","",0,"","","",1,0,0,[],""],["frenk_t1-n1344",5,"Sírvame una o dos canelas\nendulzadas con sus manos;\nesta noche nos paseamos\ncomo dos buenos hermanos.",78,2,3,87,"La canelera",0,4,"ao",-1,0,-1,0,225,225,"1344","",0,"","","",1,0,0,[],""],["frenk_t1-n1345",5,"Sírvame otras tres canelas\nendulzadas con su mano,\ny nos las tomamos luego,\nporque en seguida nos vamos.",78,2,3,87,"La canelera",0,4,"ao",-1,0,-1,0,225,225,"1345","",0,"","","",2,0,0,[],""],["frenk_t1-n1347",5,"Sírvame otras tres canelas\nendulzadas con su boca,\ny luego nos las tomamos;\na ver qué suerte nos toca.",78,2,3,87,"La canelera",0,4,"oa",178,0,-1,0,225,225,"1347","",0,"","","",2,0,0,[],""],["frenk_t1-n1348",5,"Que vámonos a pasear,\nde sueño me estoy cayendo;\nque yo llevaré la manta,\nla manta blanca que va cubriendo.",75,2,-1,87,"La manta",3,4,"eo",52,0,-1,0,226,226,"1348","",0,"","","",1,0,0,[],""],["frenk_t1-n1350",5,"Lo digo de esta manera,\nblanca concha del mar,\nque el día que domingo fuera\ndebemos juntos pasear.",83,2,8,87,"El cascabel",1,4,"a",21,0,-1,0,226,226,"1350","",0,"","","",1,0,0,[],""],["frenk_t1-n1351",5,"Usted de azul,\ny yo a su lado;\nusted se descuida,\nyo me voy con usted,\naunque sea un día nublado.",75,2,-1,87,"Estrofa suelta",7,5,"ao",14,0,-1,0,226,226,"1351","",0,"","","",1,0,0,[],""],["frenk_t1-n1354",5,"Ponte alegre, surianita,\ny vámonos a gozar;\neres chilpancingueñita,\ntú lo debes demostrar.",82,2,7,87,"Estrofa suelta",1,4,"a",21,0,-1,0,226,226,"1354","",0,"","","",1,0,0,[],""],["frenk_t1-n1355",5,"En la sombra de un pirú\nme puse a resolanear,\ncuando íbamos yo y tú;\ndigo que te he de llevar\na bailar “El Balajú”\ndonde haya un fandango real.",75,2,-1,87,"El Balajú",9,6,"a",-1,0,-1,0,226,226,"1355","",0,"","","",1,0,0,[],""],["frenk_t1-n1357",5,"Vente, María Jacinta,\nvente, no seas cobarde,\nque el tiempo de las calores\nanda mi corazón que arde.",82,2,7,87,"Estiofa suelta",0,4,"ae",344,0,-1,0,227,227,"1357","",0,"","","",1,0,0,[],""],["frenk_t1-n1358",5,"Anda, niña, anda, niña;\nanda donde, donde,\ndonde la luna sale,\ny el sol se esconde.",75,2,-1,87,"Anda, niña, anda, niña",0,4,"oe",260,0,-1,0,227,227,"1358","",0,"","","",1,0,0,[],""],["frenk_t1-n1359",5,"Dele, dele, dele, mi alma,\nmi vida, pa aquellos ramos,\npa aquellos zanates verdes\nen donde nos abrazamos.",75,2,-1,87,"Estrofa suelta",0,4,"ao",116,0,-1,0,227,227,"1359","",0,"","","",4,0,0,[],""],["frenk_t1-n1360",5,"Eres palomita indiana\ndel palomar de Cupido;\néchate a volar, si sabes,\ny vente al campo conmigo.",102,2,27,87,"El palomo",0,4,"io",-1,0,-1,0,227,227,"1360","",0,"","","",1,0,0,[],""],["frenk_t1-n1361",5,"Ya me retiro veloz\nde las penas que he sufrido\npalomita, vámonos,\nsi te quieres ir conmigo.",79,2,4,87,"La leva",0,4,"io",-1,0,-1,0,227,227,"1361","",0,"","","",2,0,0,[],""],["frenk_t1-n1362",5,"Eres chachalaca mía,\nque no te puedo olvidar;\nvente conmigo a la rama,\npara poderte besar.",83,2,8,87,"La chachalaca",0,4,"a",21,0,-1,0,227,227,"1362","",0,"","","",1,0,0,[],""],["frenk_t1-n1363",5,"Componte, negra, componte,\nporque mañana nos vamos;\nte voy [a) hacer volar\ncomo vuela el aeroplano.",83,2,8,87,"Estrofa suelta",0,4,"ao",-1,0,-1,0,227,227,"1363","",0,"","","",1,0,0,[],""],["frenk_t1-n1364",5,"Vuela, vuela, palomita,\nvuela, paloma del llano,\ny si no puedes volar,\nte llevaré en aeroplano.",79,2,4,87,"La guacamaya",0,4,"ao",81,0,-1,0,228,228,"1364","",0,"","","",3,0,0,[],""],["frenk_t1-n1365",5,"Vuela, palomita,\ncomo yo volé,\ny si no puedes volar,\nharemos el viaje a pie.",79,2,4,87,"La guacamaya",0,4,"e",77,0,-1,0,228,228,"1365","",0,"","","",2,0,0,[],""],["frenk_t1-n1366",5,"—Y vuela, revuela y vuela,\nvuela, pájaro gurrión.\n—¿Y cómo quieres que vuele,\nprenda de mi corazón?",83,2,8,87,"La guacamaya",0,4,"o",31,0,-1,0,228,228,"1366","",0,"","","",2,0,0,[],""],["frenk_t1-n1367",5,"Ya no vueles, guacamaya,\nvente acá pa descansar,\nporque en tu casa se enojan\nsi yo te llevo a pasear.",85,2,10,87,"La guacamaya",0,4,"a",21,0,-1,0,228,228,"1367","",0,"","","",1,0,0,[],""],["frenk_t1-n1368",5,"Mamacita, cita, cita,\ncítame si tú me quieres,\npara ver en el amor\nel querer de las mujeres.",82,2,7,87,"Mariquita, quita, quita",0,4,"ee",55,0,-1,0,228,228,"1368","",0,"","","",1,0,0,[],""],["frenk_t1-n1369c",5,"Como que te chiflo y sales,\ncomo que te hago una seña,\ncomo que te vas por leña\ny te vas por los nopales.",75,2,-1,87,"Estrofa suelta, Las barrancas; El pas telero",11,4,"ae",26,0,-1,0,228,228,"1369c","",0,"","","",2,0,0,[],""],["frenk_t1-n1370",5,"Y en las barrancas te aguardo,\ny a orillas de las laderas;\nensillaré mi caballo,\nme pondré mis chaparreras;\ncon mi sombrero grandote,\nahora sí me voy de veras.",75,2,-1,87,"Las barrancas",9,6,"ea",103,0,-1,0,229,229,"1370","",0,"","","",1,0,0,[],""],["frenk_t1-n1371",5,"Ausente me voy mañana,\nen esos planes te espero;\nentre los cañaverales\noirás cantar el jilguero.",75,2,-1,87,"El durazno",0,4,"eo",38,0,-1,0,229,229,"1371","",0,"","","",2,0,0,[],""],["frenk_t1-n1372",5,"En la ojo de agua te espero\npa acabarnos de arreglar;\nsi esta vez no hacemos trato,\nyo ya no he de regresar.",78,2,3,87,"La ojo de agua",0,4,"a",21,0,-1,0,229,229,"1372","",0,"","","",1,0,0,[],""],["frenk_t1-n1373",5,"Ariles y más ariles,\nariles de la ventana,\nsi acaso bajas al río,\nallá nos vemos mañana.",79,2,4,87,"El Balajú",0,4,"aa",4,0,-1,0,229,229,"1373","",0,"","","",24,0,0,[],""],["frenk_t1-n1374",5,"Yo soy el gavilán chiquito,\npido permiso a tu mama;\npor cortar un clavelito,\ncorté una flor de manzana;\nsi tu amor es paraíso,\naquí te aguardo mañana.",83,2,8,87,"Zapateado",9,6,"aa",4,0,-1,0,229,229,"1374","",0,"","","",1,0,0,[],""],["frenk_t1-n1375",5,"Doncellita linda,\nsi me oyes chiflar,\nven a la canada\npara platicar.",75,2,-1,87,"Mariquita",0,4,"a",21,0,-1,0,230,230,"1375","",0,"","","",1,0,0,[],""],["frenk_t1-n1376",5,"A las once de la noche\nallá te espero en el kiosco,\npa que sepas que te quero\ny el miedo ni lo conozco.",75,2,-1,87,"Yo no vengo a ver si puedo; La higuera; El ramol",0,4,"oo",538,0,-1,0,230,230,"1376","",0,"","","",1,0,0,[],""],["frenk_t1-n1377",5,"Eres Conchita del mar,\nperla fina del Oriente;\nven conmigo a platicar\ndonde no nos vea la gente;\nsi nos llegan a encontrar,\nyo saco mi pecho al frente.",75,2,-1,87,"Las Conchitas",9,6,"ee",15,0,-1,0,230,230,"1377","",0,"","","",4,0,0,[],""],["frenk_t1-n1378",5,"Carmelita, Carmelita,\nquiero que me hagas favor\nde salir a platicar\ndonde no pierdas tu honor.",78,2,3,87,"Carmelita",0,4,"o",72,0,-1,0,230,230,"1378","",0,"","","",1,0,0,[],""],["frenk_t1-n1381",5,"Chinita, ¿por qué no sales,\npues, a platicar conmigo,\npara darte unos besitos,\nojitos color de olivo?",75,2,-1,87,"Ojitos color de olivo",0,4,"io",-1,0,-1,0,230,230,"1381","",0,"","","",1,0,0,[],""],["frenk_t1-n1382",5,"Chula y rechula,\nchula Agustina,\n¿por qué no sales\ncon quien te estima?",75,2,-1,87,"Chula y rechula",6,4,"ia",-1,0,-1,0,230,230,"1382","",0,"","","",1,0,0,[],""],["frenk_t1-n1383",5,"Una naranja madura\nle dijo a la verde, verde:\n“Si es cierto que tú me quieres,\n¿por qué no has venido a verme?",83,2,8,87,"Estrofa suelta",0,4,"ee",-1,0,-1,0,230,230,"1383","",0,"","","",5,0,0,[],""],["frenk_t1-n1388",5,"A la noche voy a verte,\nexpuesto al agua y al frío;\ndime si estarás despierta,\npara cuando yo te haga:\nfío, fío, fío, fío, fío.",86,2,11,87,"E1 amor y el desafío",7,5,"io",3,0,-1,0,231,232,"1388","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t1-n1392",5,"¿Cuándo bajarás al pozo\ncon tu cántaro en la mano?\nTe lo digo presuroso\ndelante de tus hermanos:\nyo nunca he sido miedoso\npara agarrarte la mano.",75,2,-1,87,"El siquisirí",9,6,"ao",-1,0,-1,0,232,232,"1392","",0,"","","",1,0,0,[],""],["frenk_t1-n1393",5,"Quisiera en tus ojos verme\ny en tu mirada extasiarme,\nen tus cejas esconderme\ny en tus brazos arrullarme,\ncomo aquel niño que duerme.",75,2,-1,87,"Estrofa suelta, 1.a azucena; El sombrero",7,5,"ee",245,0,-1,0,232,232,"1393","",0,"","","",1,0,0,[],""],["frenk_t1-n1396",5,"Déjame que vea en tus ojos\nel reflejo de los cielos,\ndéjame que vea en tus labios\nla razón de mis desvelos.",75,2,-1,87,"Rosa María",0,4,"eo",192,0,-1,0,232,232,"1396","",0,"","","",1,0,0,[],""],["frenk_t1-n1397",5,"Deja reclinar mi frente\nen tu pecho seductor;\nquiero darte un beso ardiente\ny confesarte mi amor,\nque te juro para siempre.",81,2,6,87,"Estrofa suelta",7,5,"ee",-1,0,-1,0,233,233,"1397","",0,"","","",1,0,0,[],""],["frenk_t1-n1398",5,"Si quieres desengañarte,\ndeja a tus labios besar,\ndeja en tu pecho regarte\nmis lágrimas al llorar,\ny mi amor así probarte.",81,2,6,87,"Estrofa suelta",7,5,"ae",8,0,-1,0,233,233,"1398","",0,"","","",1,0,0,[],""],["frenk_t1-n1399",5,"Guerra quisiera contigo,\npero una guerra de abrazos,\nfuego nutrido de besos\ny un fusilado en tus brazos.",83,2,8,87,"La Zandunga; La morenita; Estrofa suelta",0,4,"ao",132,0,-1,0,233,233,"1399","",0,"","","",1,0,0,[],""],["frenk_t1-n1400",5,"En la puerta de tu casa\nhay tres letras de color:\nla primera dice “Cielo”,\nla segunda dice “Sol”,\nla tercera dice “Quiero\nlas caricias de tu amor”.",90,2,15,87,"Eres alta y delgadita; Delgadita de cintura; Estrofa suelta",9,6,"o",-1,0,-1,0,233,233,"1400","",0,"","","",13,0,0,[],""],["frenk_t1-n1401",5,"Como gotas de rocío\nen el cáliz de una flor\nte [contempla] el amor mío;\neres un terrón de amor\ncuyas caricias ansio.",81,2,6,87,"La huazanga; Estrofa suelta. Glosada en quintillas",7,5,"ao",-1,0,-1,0,233,233,"1401","",0,"","","",1,0,0,[],""],["frenk_t1-n1402",5,"Yo le suplico al Creador,\ntambién a la Virgen pura,\nque, aunque pobre pecador,\nme deje con tu hermosura\npara gozar de tu amor.",81,2,6,87,"Soy el pájaro platanero",7,5,"o",72,0,-1,0,233,233,"1402","",0,"","","",1,0,0,[],""],["frenk_t1-n1403",5,"Sobre tu nevado seno\npesa la cruz de un rosario;\ncomo humilde nazareno,\nen tan famoso calvario:\n¿moriré de goces lleno?",80,2,5,87,"Estrofa suelta",7,5,"eo",76,0,-1,0,233,233,"1403","",0,"","","",1,0,0,[],""],["frenk_t1-n1404",5,"Eres flor que entre peñas naciste,\ndestinada para el padecer;\nyo no pierdo la dulce esperanza\nde arrullarme en tus brazos, mujer.",75,2,-1,87,"Estrofa suelta",3,4,"e",20,0,-1,0,234,234,"1404","",0,"","","",2,0,0,[],""],["frenk_t1-n1405",5,"Déjame que en tus labios\nhalle siquiera\nel consuelo de esta alma (cielito lindo)\nque desespera;\npuedo jurarte\nque aunque yo muera (cielito lindo),\nquerré besarte.",79,2,4,87,"Cielito lindo",4,7,"ae",8,0,-1,0,234,234,"1405","",0,"","","",1,0,0,[],""],["frenk_t1-n1409",5,"Porque te amo con exceso\ny te adoro con fervor,\ndame de tu boca un beso,\nque es la prueba del amor.",75,2,-1,87,"Estrofa suelta",1,4,"o",72,0,-1,0,234,234,"1409","",0,"","","",1,0,0,[],""],["frenk_t1-n1410",5,"Eres la mujer que adoro,\ny no lo puedo negar;\ncon tu cariño y decoro,\nyo te quisiera besar:\neres mi único tesoro.",77,2,2,87,"El gusto",7,5,"oo",85,0,-1,0,234,234,"1410","",0,"","","",3,0,0,[],""],["frenk_t1-n1412",5,"Ven, cariñito, ven,\nque quiero también tu boca besar,\ny en esta noche callada\nmi pobre alma enamorada\nno hace más que suspirar.",75,2,-1,87,"Mi cajita blanca",7,5,"a",21,0,-1,0,234,234,"1412","",0,"","","",2,0,0,[],""],["frenk_t1-n1413",5,"Con esos tus ojos serios\ny tu agradable sonrisa\ny tu rostro angelical\nes el que me martiriza;\nquisiera tocar los labios\ncomo los toca la brisa.",101,2,26,87,"La azucena",9,6,"ia",68,0,-1,0,235,235,"1413","",0,"","","",2,0,0,[],""],["frenk_t1-n1414c",5,"Mujer de negros cabellos,\nde encantadora sonrisa,\ndéjame jugar con ellos\ncomo los juega la brisa;\nno más de verlos tan bellos\ntodito me martirizan.",81,2,6,87,"La Rosita",9,6,"ia",-1,0,-1,0,235,235,"1414c","",0,"","","",2,0,0,[],""],["frenk_t1-n1415",5,"¡Cómo ondulan tus listones\nen tus sedosos cabellos!\nSi a mi deseo no te opones,\ndeja enlazar a mi cuello (¡ay!, linda Rosa\n[del alma)\nesos rizos juguetones.",76,2,1,87,"del alma) esos rizos juguetones. [La Rosita",9,6,"oe",34,0,-1,0,235,235,"1415","",0,"","","",1,0,0,[],""],["frenk_t1-n1416a",5,"Cuando una rosa te pones\nhaces mi amor delirar;\nquisiera con mis canciones\nel poderte acariciar\nesos rizos juguetones.",75,2,-1,87,"El caimán; La Rosita; Estrofa suelta",7,5,"oe",34,0,-1,0,235,235,"1416a","",0,"","","",2,0,0,[],""],["frenk_t1-n1417",5,"Siento que a vivir empiezo,\nno quiero morir tan joven,\npor eso, niña, por eso\nyo me cause que te robe\ny en tu boca linda un beso.",75,2,-1,87,"Las flores",7,5,"eo",48,0,-1,0,235,235,"1417","",0,"","","",1,0,0,[],""],["frenk_t1-n1419",5,"¡Ay, qué bonito es tener amores\ny en otras tierras que Dios formó!\nDame un abrazo, dame un besito,\npara vivir más contento yo.",83,2,8,87,"Las gaviotas",3,4,"o",2,0,-1,0,236,236,"1419","",0,"","","",1,0,0,[],""],["frenk_t1-n1420",5,"Oyes, vida, no seas así,\nquiero besarte,\nquiero adorarte,\npara vivir.",75,2,-1,87,"La tixtlcca",3,4,"i",-1,0,-1,0,236,236,"1420","",0,"","","",1,0,0,[],""],["frenk_t1-n1421",5,"Si quieres que mi llanto cese\ny mi tristeza acabe,\ndéjame volar como ave\nhasta que tus labios bese.",84,2,9,87,"Estrofa suelta",11,4,"ee",65,0,-1,0,236,236,"1421","",0,"","","",1,0,0,[],""],["frenk_t1-n1422",5,"Ya te canté trer vei sitos\nnacidos del co izón;\nregálame esos besitos\npa calmar esta pasión.",75,2,-1,87,"El mezquite",1,4,"o",31,0,-1,0,236,236,"1422","",0,"","","",1,0,0,[],""],["frenk_t1-n1423",5,"Margarita, Margarita,\ndel cabello encarrujado,\ndale un besito a tu amante,\nquítale lo enamorado.",78,2,3,87,"Margarita; Tus ojitos",0,4,"ao",14,0,-1,0,236,236,"1423","",0,"malaret_americanismos","","",4,0,0,[],""],["frenk_t1-n1425",5,"Un dolor que tengo aquí, quiri, quiri, qui,\nque me traspasa hasta acá, cara, cara, cá;\narrímate junto a mí, quiri, quiri, qui\nque el dolor se calmará, cara, cara, cá.",85,2,10,87,"Un dolor que tengo aquí",3,4,"a",-1,0,-1,0,236,236,"1425","",0,"","","",1,0,0,[],""],["frenk_t1-n1427",5,"Cuando una nube en el cielo\nforma gotas de algodón,\nes un suspiro de tu alma,\nque llega a mi corazón;\nquiero tenerte en mis brazos\npara calmar esta pasión.",75,2,-1,87,"'‘Clavel deshojado",9,6,"o",31,0,-1,0,237,237,"1427","",0,"","","",1,0,0,[],""],["frenk_t1-n1428",5,"Viniendo del otro lado\ncorté una flor de alegría.\nPues le digo: “Vida mía,\ndame un abrazo siquiera,\npara ver si se me quita\nde tu terrible pasión”.",81,2,6,87,"La huazanga",9,6,"o",-1,0,-1,0,237,237,"1428","",0,"","","",3,0,0,[],""],["frenk_t1-n1429",5,"Si hace[s] lo que solicito,\nvas mis penas a calmar;\nyo con honradez te invito\npara con mi amor probar:\nun momento necesito.",75,2,-1,87,"La leva",7,5,"io",119,0,-1,0,237,237,"1429","",0,"","","",1,0,0,[],""],["frenk_t1-n1430",5,"Arrímate, chaparrita,\narrímate junto a mí,\nno te hagas tan orgullosa,\nmira que yo no soy así.",90,2,15,87,"La chaparrita",0,4,"i",23,0,-1,0,237,237,"1430","",0,"","","",1,0,0,[],""],["frenk_t1-n1431",5,"Pit delante son las lástimas,\ncomo dicen los malditos;\npor vida de mis amores,\nhágame usted un cariñito.",92,2,17,87,"El jarabe",0,4,"io",-1,0,-1,0,237,237,"1431","",0,"","","",1,0,0,[],""],["frenk_t1-n1432",5,"Entré en un jardín y la corté,\nuna malvarrosa.\n¿Por qué estás enojada,\nsiendo tú la cariñosa?\nDame un besito tronado\nde esa boquita sabrosa.",83,2,8,87,"Estrofa suelta",9,6,"oa",63,0,-1,0,237,237,"1432","",0,"","","",1,0,0,[],""],["frenk_t1-n1433",5,"Le he comprado su toquilla\ncon sus amarres de plata;\ncuando yo te pida un beso\nno me lo niegues, ingrata.",75,2,-1,87,"El sombrero ancho",0,4,"aa",74,0,-1,0,237,237,"1433","",0,"","","",1,0,0,[],""],["frenk_t1-n1434",5,"Mariquita, quita y quita,\nquítame dolor y pena;\ndebajo de tu rebozo\nme paso la noche buena.",75,2,-1,87,"La huazanga; Cecilia; Mariquita, quita, quita",0,4,"ea",59,0,-1,0,237,237,"1434","",0,"","","",1,0,0,[],""],["frenk_t1-n1435",5,"No me mates eon acero,\nporque el acero es resgoso,\nmátame con un suspiro\ndebajo de tu rebozo.",75,2,-1,87,"Estrofa suelta",0,4,"oo",156,0,-1,0,238,238,"1435","",0,"","","",1,0,0,[],""],["frenk_t1-n1436",5,"No me mates con cuchillo,\nque tiene el acero fuerte,\nmátame con un suspiro,\ny te perdono la muerte.",75,2,-1,87,"El águila real",0,4,"ee",134,0,-1,0,238,238,"1436","",0,"palau_cantares","","",7,0,0,[],""],["frenk_t1-n1437",5,"No me mates con pistola,\nni me mates con puñal,\nmátame con tus ojitos\ny tus labios de coral.",85,2,10,87,"El capotín",0,4,"a",1,0,-1,0,238,238,"1437","",0,"","","",1,0,0,[],""],["frenk_t1-n1438",5,"¡Ay, ay, ay, [ay]!\nSeré dichoso\ncuando me tapes (prieta del alma)\ncon tu rebozo.",75,2,-1,87,"El rebozo",3,4,"oo",156,0,-1,0,238,238,"1438","",0,"","","",3,0,0,[],""],["frenk_t1-n1439",5,"¡Ay de mí!, Llorona,\nLlorona, llévame al río;\ntápame con tu rebozo (Llorona),\nporque me muero de frío.",86,2,11,87,"La Llorona; La Petenera; Estrofa suelta I",3,4,"io",3,0,-1,0,238,238,"1439","",0,"","","",35,0,0,[],""],["frenk_t1-n1440",5,"Yo soy un gavilancillo\nque ando por aquí en el río;\ncobíjame con tus alas,\nque ya me muero de frío.",75,2,-1,87,"El gavilancillo",0,4,"io",3,0,-1,0,238,238,"1440","",0,"frenk_t4","","",12,0,0,[],""],["frenk_t1-n1442",5,"Mariquita se llamaba\nla que vive junto al río;\ntápame con tu rebozo,\nque ya me muero de frío.",92,2,17,87,"Mariquita",0,4,"io",3,0,-1,0,239,239,"1442","",0,"","","",3,0,0,[],""],["frenk_t1-n1443",5,"Cuando te vayas al pozo\ncon tu cántaro vacío,\ntápame con tu rebozo,\nporque me muero de frío.",77,2,2,87,"El gavilán",1,4,"io",3,0,-1,0,239,239,"1443","",0,"","","",1,0,0,[],""],["frenk_t1-n1445",5,"¡Ay!, no quiero, no quiero, no quiero\nla sombra de tu rebozo;\nsólo tu sombrita quiero,\npero saliendo del pozo.",75,2,-1,87,"Ya no quiero",3,4,"oo",156,0,-1,0,239,239,"1445","",0,"","","",2,0,0,[],""],["frenk_t1-n1447",5,"Señora, si usted quisiera\nhacerme una caridad,\npartiera su rebocito,\náhi me diera la mitad,\npara hacerme un cotoncito,\nque ya vergüenza me da.",92,2,17,87,"El cuatro",9,6,"a",-1,0,-1,0,239,239,"1447","",0,"","","",1,0,0,[],""],["frenk_t1-n1448",5,"Cecilia, lindo amorcito,\nte adoro con devoción;\nquisiera darte un besito\ncon fuego de mi pasión\ny estarme recostadito\njuntito a tu corazón.",81,2,6,87,"La Cecilia",9,6,"o",31,0,-1,0,239,239,"1448","",0,"","","",1,0,0,[],""],["frenk_t1-n1450",5,"Callejón del Barrio Alto,\ncerrito del Calabazo,\ntarde con tarde le canto,\na ver si así me hace caso;\nojitos de capulín,\nquisiera estar en tus brazos.",75,2,-1,87,"Ojitos de capulín",9,6,"ao",-1,0,-1,0,240,240,"1450","",0,"","","",1,0,0,[],""],["frenk_t1-n1451",5,"Cada vez que paso y miro,\náhi te veo sentadita;\nquisiera dar un volido\na tus brazos, mamacita.",83,2,8,87,"Estrofa suelta",0,4,"ia",50,0,-1,0,240,240,"1451","",0,"","","",25,0,0,[],""],["frenk_t1-n1454",5,"Las estrellas en el cielo,\nla luna en un carrizal;\nboquita de caña dulce,\n¡quién te pudiera besar!",83,2,8,87,"Estrofa suelta",0,4,"a",-1,0,-1,0,240,240,"1454","",0,"","","",18,0,0,[],""],["frenk_t1-n1455",5,"Ojitos aceitunados (Llorona),\ncolor de paño francés;\nlabios de coral partido (¡ay, Llorona!),\n¡quién los besara otra vez!",75,2,-1,87,"La Llorona",3,4,"e",150,0,-1,0,240,240,"1455","",0,"","","",1,0,0,[],""],["frenk_t1-n1456",5,"Tortolita, la vida mía,\nvamos a misa a la cofradía;\nyo quisiera que juntaras\ntu boquita con la mía,\npara que así me besaras\ny victoria te cantaría.",82,2,7,87,"La tortolita",9,6,"ia",0,0,-1,0,240,240,"1456","",0,"","","",1,0,0,[],""],["frenk_t1-n1457",5,"Qué bien te ves, huastequita,\ncon tus moñitos dorados;\nquisiera darte un besito\nen tus labios colorados.",79,2,4,87,"La vara de mi violínJ",0,4,"ao",18,0,-1,0,241,241,"1457","",0,"","","",1,0,0,[],""],["frenk_t1-n1458",5,"Qué bonito lunarcito\nque tiene mi morenita;\nquisiera darle un besito\ny en esa linda boquita.",77,2,2,87,"El lunarcito I",1,4,"ia",50,0,-1,0,241,241,"1458","",0,"","","",1,0,0,[],""],["frenk_t1-n1459",5,"Yo quisiera ser tu boca\npara ser turrón de azúcar,\npara estar toda la noche\nchupa y chupa, chupa y chupa.",85,2,10,87,"Palomita blanca del pico dorado",3,4,"ua",-1,0,-1,0,241,241,"1459","",0,"","","",1,0,0,[],""],["frenk_t1-n1460",5,"Si tu boquita fuera\nun terrón de azúcar,\ntoda la noche estuviera\nchupa y chupa y chupa.",75,2,-1,87,"Tengo uno, tengo dos, tengo tres",0,4,"ua",-1,0,-1,0,241,241,"1460","",0,"","","",4,0,0,[],""],["frenk_t1-n1461",5,"Si el amor que te tengo\nfuera de azúcar,\ntodo el día estaría\nchupa que chupa.",75,2,-1,87,"La bamba; El trompo",6,4,"ua",-1,0,-1,0,241,241,"1461","",0,"","","",3,0,0,[],""],["frenk_t1-n1462",5,"Si tu boquita fuera\nuna manzana verde,\ntoda la noche estuviera,\nestuviera muerde y muerde.",75,2,-1,87,"Tengo uno, tengo dos, tengo tres",1,4,"ee",154,0,-1,0,241,241,"1462","",0,"","","",4,0,0,[],""],["frenk_t1-n1463",5,"Un beso te quiero dar,\npero de fijo no sé\nni cómo lo he de empezar,\nni cuándo lo acabaré.",75,2,-1,87,"Estrofa suelta",1,4,"e",77,0,-1,0,241,241,"1463","",0,"","","",1,0,0,[],""],["frenk_t1-n1464",5,"Dispénsame, jovencita,\nque aquí me tienes presente;\nquiero besar tu boquita:\ndime si te es consecuente.\nYo no tomo “Coronita”,\nme gusta más la aguardiente.",81,2,6,87,"La pasión",9,6,"ee",15,0,-1,0,241,241,"1464","",0,"","","",1,0,0,[],""],["frenk_t1-n1474",5,"Rosa de Castilla,\nrosa sensual,\ndame un beso, morenita,\nque te quiero abrazar.",86,2,11,87,"Estrofa suelta",3,4,"a",-1,0,-1,0,243,243,"1474","",0,"","","",1,0,0,[],""],["frenk_t1-n1475",5,"Rosa María,\nreina de todas las flores,\ndale un besito\nal que es rey de tus amores.",75,2,-1,87,"Rusa Maria",3,4,"oe",5,0,-1,0,243,243,"1475","",0,"","","",2,0,0,[],""],["frenk_t1-n1476",5,"Soy soldado de levita,\nque conozco la milicia;\narrímate y dame un beso\nhora que no hay malicia;\nyo soy el que parte el queso\ny nada se desperdicia.",81,2,6,87,"La leva",9,6,"ia",391,0,-1,0,243,243,"1476","",0,"","","",7,0,0,[],""],["frenk_t1-n1477",5,"Dame lo que yo te pido,\nque no te pido la vida:\nun besito de tu boca,\nde tu boquita encendida.",86,2,11,87,"La Sanmarqueña; El caballo prieto",0,4,"ia",37,0,-1,0,243,243,"1477","",0,"","","",3,0,0,[],""],["frenk_t1-n1478",5,"De tu casa a la mía\nno hay más que un paso;\ny ahora que estamos solos\ndame un abrazo.",83,2,8,87,"Negra del alma; La bamba; Cielito lindo; Con ésta y no más con ésta; Eres arenita de oro; El jarabe; Estrofa suelta",3,4,"ao",43,0,-1,0,243,243,"1478","",0,"","","",4,0,0,[],""],["frenk_t1-n1479",5,"De tu ventana a la mía\nno hay más que un trecho;\narrímate, vida mía,\ndame uno hecho.",75,2,-1,87,"Eres arenita de oro",6,4,"eo",60,0,-1,0,244,244,"1479","",0,"","","",10,0,0,[],""],["frenk_t1-n1480",5,"Desde lejos tierras vengo,\nde pelear con la sirena;\nahora que vengo rendido,\ndame tus brazos, morena.",100,2,25,87,"Desde lejos tierras vengo",0,4,"ea",59,0,-1,0,244,244,"1480","",0,"","","",1,0,0,[],""],["frenk_t1-n1481",5,"De tierras abajo vengo,\nde rezar una novena;\nahora que vengo santito,\nven, abrázame, morena.",75,2,-1,87,"El maracumbé; El gusano; La Malagueña curreña; El toro",0,4,"ea",59,0,-1,0,244,244,"1481","",0,"","","",1,0,0,[],""],["frenk_t1-n1485",5,"Qué bonitas campanitas\nque se oyen repicar allá;\néchame tus brazos, mi alma,\nsi me tienes voluntad.",75,2,-1,87,"Las campanitas",0,4,"a",-1,0,-1,0,244,244,"1485","",0,"","","",6,0,0,[],""],["frenk_t1-n1486",5,"¡Ay, Cupido, Cupido, Cupido!,\n¡ay, Cupido, Cupido, me muero!\nDame los brazos, mi vida,\nmi vida, que te quiero.",75,2,-1,87,"El Cupido",3,4,"eo",38,0,-1,0,244,244,"1486","",0,"","","",9,0,0,[],""],["frenk_t1-n1487",5,"Este es el celo\nque yo padezco;\néchame tus brazos, mi alma (güerita),\nsi acaso yo [lo] merezco.",92,2,17,87,"f I triste",3,4,"eo",355,0,-1,0,245,245,"1487","",0,"","","",1,0,0,[],""],["frenk_t1-n1488",5,"¡Lázalo, lázalo,\nlázalo que se te fue!\nÉchame los brazos, mi alma,\ny nunca te olvidaré.",79,2,4,87,"El torito",3,4,"e",77,0,-1,0,245,245,"1488","",0,"","","",2,0,0,[],""],["frenk_t1-n1489",5,"Lázala, lázala y lázala,\nlázala que ya se va;\ndame un abrazo, morena,\nde pura casualidad.",75,2,-1,87,"Estrofa suelta",0,4,"a",-1,0,-1,0,245,245,"1489","",0,"","","",1,0,0,[],""],["frenk_t1-n1490",5,"El amor de mi vida\ntú siempre lo serás;\nno más dame un besito\npara querernos más.",75,2,-1,87,"El amor de mi vida",0,4,"a",51,0,-1,0,245,245,"1490","",0,"","","",1,0,0,[],""],["frenk_t1-n1491",5,"¡Ay, morenita!,\nmorenita de los tules,\néchame tus brazos, mi alma,\ncon esas venas azules.",82,2,7,87,"La morenita",3,4,"ue",540,0,-1,0,245,245,"1491","",0,"","","",3,0,0,[],""],["frenk_t1-n1492",5,"China de los ojos negros (¡ay, mamá, por [Dios!),\nlabios de coral partido (cielo de mi corazón),\ndame un abrazo, mi amor (¡ay, mamá, por [Dios!),\npara quedarme dormido (cielo de mi corazón).",83,2,8,87,"Dios!), labios de coral partido (cielo de mi corafzón",3,4,"o",101,0,-1,0,245,245,"1492","",0,"","","",1,0,0,[],""],["frenk_t1-n1493c",5,"Presumida, presumida,\npresumida de allá arriba,\ntú me has quitado la calma\nen todo lo que he querido;\néchame en tus brazos, mi alma,\npara quedarme dormido.",81,2,6,87,"La presumida",9,6,"io",101,0,-1,0,245,245,"1493c","",0,"","","",2,0,0,[],""],["frenk_t1-n1494",5,"Lucero de la mañana,\nestrella de la oración,\néchame los brazos, mi alma,\npor ser la última ocasión,\npara quedarme dormido,\nprenda de mi corazón.",75,2,-1,87,"Estrofa suelta",9,6,"o",31,0,-1,0,246,246,"1494","",0,"","","",22,0,0,[],""],["frenk_t1-n1495",5,"Hasta el pecho se me llena\ncon música de tu alma;\nmientras el final me llega,\nacurrúcame en tus alas.",75,2,-1,87,"Canta, canta, tortolita",0,4,"aa",-1,0,-1,0,246,246,"1495","",0,"","","",1,0,0,[],""],["frenk_t1-n1496",5,"Un beso tuyo es mi anhelo,\nsentir tu cuerpo cerquita,\npara besar tu boquita\ny sentir que me voy al ciclo.",75,2,-1,87,"Ay, ay, ay, ay",5,4,"io",-1,0,-1,0,246,246,"1496","",0,"","","",1,0,0,[],""],["frenk_t1-n1498",5,"Qué bonitos labios tienes,\nlabios color de manzana;\nsi tú me correspondieras,\nyo te probaría mañana.",75,2,-1,87,"Las Isabeles",0,4,"aa",4,0,-1,0,246,246,"1498","",0,"","","",1,0,0,[],""],["frenk_t1-n1500",5,"Eres am ari lli ta\ncomo la cera;\nmantequilla de placer,\n¡quién te comiera!",79,2,4,87,"La bamba’’I",6,4,"ea",44,0,-1,0,247,247,"1500","",0,"","","",1,0,0,[],""],["frenk_t1-n1501",5,"¡Ay, sandía, quién te calara,\naunque me dieran los fríos!\nSoy puro Guadalajara,\ndonde son los tapatíos.",75,2,-1,87,"El jarabe’’",1,4,"io",135,0,-1,0,247,247,"1501","",0,"","","",1,0,0,[],""],["frenk_t1-n1502",5,"Blanca flor de margarita,\n¡quién te pudiera cortar!\nComo eres la más bonita,\nespero me has de besar\ncon tu preciosa boquita.",77,2,2,87,"Las flores; La Rosita",7,5,"ia",50,0,-1,0,247,247,"1502","",0,"","","",1,0,0,[],""],["frenk_t1-n1503",5,"Encantadora morena,\n¡quién te pudiera besar!\nMi dicha no se enajena;\nespero que he de cortar\nesa preciosa azucena.",77,2,2,87,"La azucena",7,5,"ea",59,0,-1,0,247,247,"1503","",0,"","","",1,0,0,[],""],["frenk_t1-n1504",5,"Hermosa flor de azucena,\n¡quién te pudiera cortar!\nTu boquita me envenena,\ntú me has de perfumar,\ny mi dicha se enajena.",77,2,2,87,"La azucena",7,5,"ea",59,0,-1,0,247,247,"1504","",0,"","","",1,0,0,[],""],["frenk_t1-n1505",5,"Eres como la hoja verde,\nhija de una enredadera;\nme dan ganas de cortarte\npara quitarte lo matrera.",75,2,-1,87,"Hojita verde",0,4,"ea",44,0,-1,0,247,247,"1505","",0,"","","",4,0,0,[],""],["frenk_t1-n1507",5,"Voy a echar la despedida,\nla que echó San Pedro en Roma;\n“Entre tantos gavilanes,\n¡quién te comerá, paloma!”.",83,2,8,87,"Que comienzo, que comienzo; La garbosa; El huasteco enamorado; La Lio. roña; María del Carmen; La Sanmar­",0,4,"oa",86,0,-1,0,247,247,"1507","",0,"","","",8,0,0,[],""],["frenk_t1-n1508",5,"Ya parece, ya parece,\nya parece, pero no,\nya parece que te corto,\nrosita de Jericó.",75,2,-1,87,"Ya parece, ya parece",0,4,"o",2,0,-1,0,248,248,"1508","",0,"","","",1,0,0,[],""],["frenk_t1-n1510",5,"Voy a cortar una flor\nde tu huerto muy lucido;\nme he de acostar en tu cama,\nángel divino de amor,\naroma de la manzana.",75,2,-1,87,"La flor",7,5,"aa",-1,0,-1,0,248,248,"1510","",0,"","","",3,0,0,[],""],["frenk_t1-n1513",5,"Me he de cortar una flor\nde esas que hay en tu jardín;\ny aunque me cueste el rigor,\nme he de acostar a dormir,\nángel divino de amor,\naroma de pachulín.",87,2,12,87,"La florl",9,6,"i",-1,0,-1,0,248,248,"1513","",0,"","","",3,0,0,[],""],["frenk_t1-n1514",5,"Para cantarte un sin fin\ny muchos versitos de amor,\ny pasearme en tu jardín\npara cortar una flor;\nde ellas un blanco jazmín,\ny embriagarme con su olor.",75,2,-1,87,"Qué milagro, chaparrita; Estrofa suelta",9,6,"o",72,0,-1,0,248,248,"1514","",0,"","","",1,0,0,[],""],["frenk_t1-n1516c",5,"Soy pariente de la luna,\naunque indito mexicano;\nMéxico es una laguna,\nGuadalajara es un llano;\nme he de comer esa tuna\naunque me espine la mano.",75,2,-1,87,"El indio",9,6,"ao",81,0,-1,0,249,249,"1516c","",0,"","","",1,0,0,[],""],["frenk_t1-n1519",5,"Eres tuna del tunal,\nde esas que están madurando;\nno dejes que te tienten\nni que te anden manoseando:\nsólo yo te he de tentar,\nsupuesto que yo te mando.",83,2,8,87,"Estrofa suelta",9,6,"ao",33,0,-1,0,249,249,"1519","",0,"","","",1,0,0,[],""],["frenk_t1-n1522",5,"Yo soy más fino que un peso:\nantes que me suenen sueno;\ncomo soy un poco necio,\ntambién me gusta lo bueno:-\nmorena, ¿quieres un beso?\nTe lo doy y te lo trueno.",81,2,6,87,"El huerfanito; La Malagueña",9,6,"eo",-1,0,-1,0,250,250,"1522","",0,"","","",2,0,0,[],""],["frenk_t1-n1523",5,"Con esas formas que tienes,\nbien sabes que me enterneces;\nte besaré hasta mil veces\nen el cuerpo y en las sienes.",75,2,-1,87,"Estrofa sucha",11,4,"ee",-1,0,-1,0,250,250,"1523","",0,"","","",1,0,0,[],""],["frenk_t1-n1524",5,"Soy pájaro vilán\nde mi lindo platanal;\nun besito te he de dar\nen ese pico embustero,\nque hasta te has de saborear.",87,2,12,87,"Estrofa suelta",7,5,"a",21,0,-1,0,250,250,"1524","",0,"","","",1,0,0,[],""],["frenk_t1-n1525",5,"Presumida, presumida,\npico de garza morena,\nsi tú me dieras un beso,\nyo te daría una docena,\nporque tengo vicio de eso\nen mi tierra y en la ajena.",81,2,6,87,"La presumida",9,6,"ea",59,0,-1,0,250,250,"1525","",0,"","","",2,0,0,[],""],["frenk_t1-n1528",5,"Yo por ti me estoy muriendo,\npero entre muy duros lazos;\nmejor quisiera morir,\ntrigueñita, entre tus brazos.",100,2,25,87,"Trigueñita",0,4,"ao",132,0,-1,0,251,251,"1528","",0,"","","",1,0,0,[],""],["frenk_t1-n1529",5,"¡Ay!, qué bonito es estar\na punto de medio día,\ny luego dejarse eair\nen tus brazos, vida mía.",83,2,8,87,"La bruja11",0,4,"ia",0,0,-1,0,251,251,"1529","",0,"","","",2,0,0,[],""],["frenk_t1-n1530",5,"Éntrale, negra bonita,\nvente conmigo a bailar\nesta alegre chilenita\nque te voy a dedicar,\npero cuida tu boquita:\nno te la vaya a besar.",83,2,8,87,"La sureña",9,6,"a",21,0,-1,0,251,251,"1530","",0,"","","",1,0,0,[],""],["frenk_t1-n1531",5,"Vuelve, vuelve, duraznito,\na tu rama a madurar;\nme prestaras tu boquita:\nno se me vaya a antojar.",75,2,-1,87,"Vuelve, vuelve, duraznito1'",0,4,"a",21,0,-1,0,251,251,"1531","",0,"","","",1,0,0,[],""],["frenk_t1-n1532",5,"Los besos que tú me das\ntienen un sabor a tuba:\nal que le das a probar\ntoditito lo atarugas:\nen ti lo viene a implorar.",75,2,-1,87,"Atole con el dedo",7,5,"a",21,0,-1,0,251,251,"1532","",0,"","","",1,0,0,[],""],["frenk_t1-n1533",5,"¡Ay, ay, ay, dale durito!,\n¡durito, y no me lo [mates]!,\nque besitos por el aire\nme saben a chocolate.",79,2,4,87,"El cascabel11",0,4,"ae",-1,0,-1,0,251,251,"1533","",0,"","","",2,0,0,[],""],["frenk_t1-n1534",5,"¡Ay, ay, ay, dale durito!,\n¡dale, dale, que ando bailando!,\nque un besito por el aire\nya me lo estoy saboreando.",75,2,-1,87,"El cascabel",0,4,"ao",33,0,-1,0,251,251,"1534","",0,"","","",2,0,0,[],""],["frenk_t1-n1535",5,"¡Ay, ay, dale durito!,\n¡dale, dale, Dolores!,\nque he venido por el aire,\ny me sabe a pan con flores.",83,2,8,87,"El cascabel",0,4,"oe",5,0,-1,0,251,251,"1535","",0,"","","",1,0,0,[],""],["frenk_t1-n1536",5,"¡Ay, dale, dale durito!,\n¡ay, dale [dale] muy recio!,\nque besitos en el aire\nme saben a pan con queso.",79,2,4,87,"El cascabel",0,4,"eo",-1,0,-1,0,251,251,"1536","",0,"","","",1,0,0,[],""],["frenk_t1-n1537",5,"Tapatío guadalajareño,\ndueño de mi corazón,\ndame un besito tronado,\nque me sabe a requesón.",75,2,-1,87,"El tapatío",3,4,"o",31,0,-1,0,252,252,"1537","",0,"","","",1,0,0,[],""],["frenk_t1-n1538",5,"Si me das esa boquita,\nyo me voy a saborear;\ntú no sabes, rancherita,\nlo bonito que es amar.",75,2,-1,87,"La palomita",1,4,"a",21,0,-1,0,252,252,"1538","",0,"","","",1,0,0,[],""],["frenk_t1-n1540",5,"Dame una mano,\ndame las dos,\ndame un besito,\ny anda con Dios.",75,2,-1,87,"Chula y rechula",6,4,"o",87,0,-1,0,252,252,"1540","",0,"","","",1,0,0,[],""],["frenk_t1-n1541",5,"Bailaremos las Pelonas\nagarraditos los dos,\ny si tú me das un beso,\n¡sea por el amor de Dios!",75,2,-1,87,"Ya no lloverá, pelonas",0,4,"o",87,0,-1,0,252,252,"1541","",0,"","","",1,0,0,[],""],["frenk_t1-n1542",5,"Ándale, María Lupe,\ntercíate tu rebozo,\npero antes dame un besito,\ndámelo muy sabroso.",83,2,8,87,"María Lupe",0,4,"oo",160,0,-1,0,252,252,"1542","",0,"","","",2,0,0,[],""],["frenk_t1-n1543",5,"Dime, negra, por qué no me amas,\ntú eres mi vida, mi bienestar;\ndame un abrazo, dame un besito,\nvenga conmigo, vamos a andar.",75,2,-1,87,"Las gaviotas",3,4,"a",21,0,-1,0,252,252,"1543","",0,"","","",1,0,0,[],""],["frenk_t1-n1546",5,"Tú me irás pidiendo,\ny yo te iré dando\nbesitos y abrazos (mi vida)\nque se andan usando.",78,2,3,87,"¡Uy tara la la!",3,4,"ao",-1,0,-1,0,253,253,"1546","",0,"","","",1,0,0,[],""],["frenk_t1-n1548",5,"Refresquerita de Iguala,\nme mata tanto calor;\nsírveme agua de besos\nen el vaso de tu amor.",75,2,-1,87,"Refresquerita de Iguala",0,4,"o",72,0,-1,0,253,253,"1548","",0,"","","",2,0,0,[],""],["frenk_t1-n1549",5,"Eres mi paloma blanca,\ny yo tu pichón azul;\narrima acá tu piquito,\ny haremos “currucucú”.",75,2,-1,87,"El palomo; El pájaro cú; Estrofa suelta",0,4,"u",-1,0,-1,0,253,253,"1549","",0,"","","",1,0,0,[],""],["frenk_t1-n1550",5,"Eres mi prenda querida,\ny yo tu pichón dorado;\narrímame a tu boquita\ny dame un beso chillado.",79,2,4,87,"El pájaro cú",0,4,"ao",14,0,-1,0,254,254,"1550","",0,"","","",9,0,0,[],""],["frenk_t1-n1555",5,"Cupido con su chulona\nen el sueño le decía;\n“Si no me quieres, pelona,\nabrázame, vida mía,\nmuérdeme, no seas chiquiona",75,2,-1,87,"Estrofa suelta",7,5,"oa",7,0,-1,0,254,254,"1555","",0,"","","",1,0,0,[],""],["frenk_t1-n1556",5,"Muévase, viejita linda,\ny véngase a retozar;\nécheme una sonrisita,\nno me haga desatinar.",75,2,-1,87,"La palomita",0,4,"a",21,0,-1,0,255,255,"1556","",0,"","","",1,0,0,[],""],["frenk_t1-n1557",5,"Y vuela, vuela, vuela,\nvuela sin cesar;\néchame los brazos, mi alma,\nvámonos a vacilar.",79,2,4,87,"La guacapiaya",0,4,"a",21,0,-1,0,255,255,"1557","",0,"","","",2,0,0,[],""],["frenk_t1-n1558",5,"A la leva, leva, leva,\na la leva, leva, andando;\néchame los brazos, mi alma,\ny vámonos acostando.",75,2,-1,87,"‘‘La indita",0,4,"ao",33,0,-1,0,255,255,"1558","",0,"","","",4,0,0,[],""],["frenk_t1-n1559",5,"Ándale, güerita,\nvámonos al organal,\na cortar pitayas\nempezando a madurar.",75,2,-1,87,"El pitayero",0,4,"a",-1,0,-1,0,255,255,"1559","",0,"","","",1,0,0,[],""],["frenk_t1-n1560",5,"Chile verde me pediste,\nchile verde te daré:\nvámonos para la huerta,\nque allá te lo cortaré.",75,2,-1,87,"Estrofa suelta, ‘‘Los chiles verdes",0,4,"e",77,0,-1,0,255,255,"1560","",0,"","","",4,0,0,[],""],["frenk_t1-n1561",5,"Chiles verdes me pediste,\nchiles verdes te vo’ a dar;\nvámonos para la huerta,\nallá te lo vo’ a cortar.",87,2,12,87,"‘‘Los chiles verdes",0,4,"a",21,0,-1,0,255,255,"1561","",0,"","","",1,0,0,[],""],["frenk_t1-n1562",5,"Chile verde me pediste,\nchile verde te he de dar,\nchile verde que lo venden\nen las plazas al pasar.",75,2,-1,87,"Los chiles verdesJ",0,4,"a",21,0,-1,0,255,255,"1562","",0,"","","",4,0,0,[],""],["frenk_t1-n1563",5,"Chile verde me pediste,\nchile verde te he de dar;\n¿para qué son chiles verdes,\nsi no son para almorzar?",79,2,4,87,"Los chiles verdes",0,4,"a",21,0,-1,0,255,255,"1563","",0,"","","",4,0,0,[],""],["frenk_t1-n1564",5,"Chile verde me pediste,\nchile verde he de traer;\néstos son los chiles verdes\nque le llevo a mi querer.",75,2,-1,87,"Los chiles verdes",0,4,"e",20,0,-1,0,256,256,"1564","",0,"","","",4,0,0,[],""],["frenk_t1-n1565",5,"llora sí, china del alma,\nvámonos para Tenango,\na vender los chiles verdes,\nporque se están madurando.",87,2,12,87,"Los chiles verdes",0,4,"ao",-1,0,-1,0,256,256,"1565","",0,"","","",1,0,0,[],""],["frenk_t1-n1566",5,"Más alta la vi volar\nuna garza morena.\nSi no me lo quieres dar,\nenséñamelo siquiera,\nno me vaya yo a antojar\ny de ese antojo me muera.",83,2,8,87,"Estrofa suelta",9,6,"ea",44,0,-1,0,256,256,"1566","",0,"","","",1,0,0,[],""],["frenk_t1-n1567",5,"Échale vuelo a tu mano,\ny en la punta una lazada;\ndame un abrazo en el suelo,\nporque la cama me enfada.",83,2,8,87,"Estrofa suelta",0,4,"aa",49,0,-1,0,256,256,"1567","",0,"","","",1,0,0,[],""],["frenk_t1-n1568",5,"Este torito que traigo\nlo traigo desde Campeche;\n¡ay, mamá!, yo estoy queriendo\ndame un vasito de leche.",75,2,-1,87,"El torito",0,4,"ee",180,0,-1,0,256,256,"1568","",0,"","","",10,0,0,[],""],["frenk_t1-n1569",5,"Para quedarme dormido\nen medio de tus bracitos,\ncomo niño consentido,\nmamando los pechitos.",75,2,-1,87,"Estrofa suelta",1,4,"io",-1,0,-1,0,256,256,"1569","",0,"","","",1,0,0,[],""],["frenk_t1-n1570",5,"Ya no quiero, ya no quiero\nbailar “El toro rabón”:\nsólo quiero, chiquita,\nque bailemos este son.",75,2,-1,87,"El toro rabón",0,4,"o",31,0,-1,0,256,256,"1570","",0,"","","",4,0,0,[],""],["frenk_t1-n1571",5,"Ariles y más ariles,\nariles vengo diciendo:\n\"Y ábreme la puerta, cielo,\nno te me andes escondiendo.”",75,2,-1,87,"El Balajú",0,4,"eo",-1,0,-1,0,256,256,"1571","",0,"","","",24,0,0,[],""],["frenk_t1-n1572",5,"Por esta calle me voy\ny por la otra doy la vuelta,\na ver si puedo cortar\nun tulipán de tu huerta;\nno seas ingrata conmigo:\ndéjame la puerta abierta.",79,2,4,87,"La morena; La guacamaya",9,6,"ea",267,0,-1,0,257,257,"1572","",0,"","","",8,0,0,[],""],["frenk_t1-n1573",5,"Yo me vine de Tampico\ny me pasé por Taletla;\nsi tu amor está solito,\ndéjame la puerta abierta:\naquí viene el querrequito\ny en busca de su querreca.",81,2,6,87,"E1 querreque",9,6,"ea",-1,0,-1,0,257,257,"1573","",0,"","","",1,0,0,[],""],["frenk_t1-n1574",5,"Si tu mamá te dice (cielito lindo)\nque cierres la puerta,\nhazle ruido a la puerta (cielito lindo)\ny déjala abierta.",86,2,11,87,"Cielito lindo",3,4,"ea",267,0,-1,0,257,257,"1574","",0,"","","",1,0,0,[],""],["frenk_t1-n1575",5,"Negrita linda,\ncierra esa puerta;\nabre mejor la llave (mi vida)\ny déjala abierta.",78,2,3,87,"La negrita",3,4,"ea",267,0,-1,0,257,257,"1575","",0,"","","",1,0,0,[],""],["frenk_t1-n1576",5,"Dame la mano, morena,\npara subir a tu nido;\nno duermas sola,\nduerme conmigo.",85,2,10,87,"Los barandales",3,4,"io",-1,0,-1,0,257,257,"1576","",0,"","","",1,0,0,[],""],["frenk_t1-n1577",5,"Dame la mano, paloma,\npara subir a tu nido;\nanoche dormiste sola,\nahora dormirás conmigo.",80,2,5,87,"Estrofa suelta, El buscapiés; El palomo",0,4,"io",-1,0,-1,0,257,257,"1577","",0,"","","",3,0,0,[],""],["frenk_t1-n1578",5,"En una barranca abajo\nanda el gavilán perdido\nen busca de una paloma,\nla paloma está en su nido:\n“Anoche dormiste sola,\nahora dormirás conmigo.”",81,2,6,87,"La leva",9,6,"io",-1,0,-1,0,257,257,"1578","",0,"","","",1,0,0,[],""],["frenk_t1-n1579",5,"Gualupita, que ayer tarde\nme cantaste unas coplitas,\nayer cantaste solita,\ny ahora cantarás conmigo.",75,2,-1,87,"E1 turruntuntún",3,4,"io",-1,0,-1,0,257,257,"1579","",0,"","","",2,0,0,[],""],["frenk_t1-n1580",5,"Si tú supieras, mi china,\ncómo me tienes de esclavo,\ndespertarías a mi lado\ntoditas las mañanas.",75,2,-1,87,"Más allá tic la frontera",5,4,"aa",-1,0,-1,0,258,258,"1580","",0,"","","",3,0,0,[],""],["frenk_t1-n1581",5,"Negrita, cuerpo de urraca,\nbello relicario de oro,\nsi a mí me sueltan la vaca,\npor Dios que te suelto el toro.",75,2,-1,87,"Estrofa suelta",1,4,"oo",85,0,-1,0,258,258,"1581","",0,"","","",1,0,0,[],""],["frenk_t1-n1582",5,"Y vámonos a la cama\ny vámonos a dormir:\ntú llevarás la manta,\nyo llevaré el candil.",79,2,4,87,"La manta",0,4,"i",-1,0,-1,0,258,258,"1582","",0,"","","",1,0,0,[],""],["frenk_t1-n1583",5,"Y vámonos a dormir\ny vámonos a acostar,\nque tú llevarás la manta,\nla manta, manta que he de cortar.",75,2,-1,87,"La manta",3,4,"a",21,0,-1,0,258,258,"1583","",0,"","","",1,0,0,[],""],["frenk_t1-n1585",5,"¡Ay sí, Mariquita, sí!.\n¡ay sí, Mariquita, no!,\nque tú llevarás la manta,\nht manta, manta que mido yo.",75,2,-1,87,"La mantal",0,4,"o",2,0,-1,0,258,258,"1585","",0,"","","",1,0,0,[],""],["frenk_t1-n1586",5,"Y esta noche te vas,\nte vas a quedar conmigo;\nmañana madrugarás,\npasajero de mi vida.",75,2,-1,87,"El pasajero",5,4,"ia",-1,0,-1,0,258,258,"1586","",0,"","","",1,0,0,[],""],["frenk_t1-n1590",5,"Mira, ya cantan los gallos:\n¡cómo suspiro por ti!\nDame un besito, morena;\nyo vengo en la madrugada,\na despedirme de ti.",79,2,4,87,"La morena",7,5,"i",-1,0,-1,0,259,259,"1590","",0,"","","",1,0,0,[],""],["frenk_t1-n1592",5,"—Ya los gallos ya cantaron,\nchiquitita, ya me voy.\n—No se va, mi trigueñito,\nhasta que no raye el sol.",75,2,-1,87,"La sandía; Ya me voy, chaparrita; Estrofa suelta",0,4,"o",-1,0,-1,0,259,259,"1592","",0,"","","",1,0,0,[],""],["frenk_t1-n1593",5,"Eres rosa colorada\ndel jardín de Pueblo Viejo;\nsi te quedas enojada,\nporque me voy y te dejo,\n¡ay!, vente en la madrugada,\ncuando ya se duerma el viejo.",79,2,4,87,"El huasteco",9,6,"eo",264,0,-1,0,259,259,"1593","",0,"","","",1,0,0,[],""],["frenk_t1-n1595",5,"En el portal de una venta\nal pasar corté un clavel.\nHermosa flor de pimienta,\nsólo a ti te he de querer;\ncuando tú vivas contenta,\ndéjame a mí padecer.",83,2,8,88,"Estrofa suelta",9,6,"e",20,0,-1,0,260,260,"1595","",0,"","","",1,0,0,[],""],["frenk_t1-n1596",5,"En la rama de un pirul\nte he de formar una copa;\nte he de amar con amplitud\nhasta que te nombre propia;\nnegrita, de no ser tú,\nde mi gusto ya no hay otra",75,2,-1,88,"Est rol a suelta",9,6,"oa",-1,0,-1,0,260,260,"1596","",0,"","","",1,0,0,[],""],["frenk_t1-n1598",5,"En la cumbre de un pirú\nme gusta porque ventea.\nMi vida, si no eres tú,\n¿quién otra quieres que sea?\nLas aves con su virtud\nme llevan adonde sea.",75,2,-1,88,"La leva",9,6,"ea",-1,0,-1,0,260,260,"1598","",0,"","","",1,0,0,[],""],["frenk_t1-n1599",5,"En la sombra de un pirul\nme gusta porque ventea.\nSi me correspondes tú,\nes lo que mi alma desea;\nmi vida, de no ser tú,\n¡quién otra quieres que sea!",75,2,-1,88,"La huazanga; El bejuquito",9,6,"ea",54,0,-1,0,260,260,"1599","",0,"","","",1,0,0,[],""],["frenk_t1-n1600",5,"Si volvieras a nacer,\nyo te mecería en la cuna,\npara darte a comprender\notra como tú, ninguna:\nsin ti no hay ningún placer.",75,2,-1,88,"El ausente’’, La azucenal",7,5,"e",20,0,-1,0,261,261,"1600","",0,"","","",1,0,0,[],""],["frenk_t1-n1601",5,"Yo sé que hay muchas mujeres\ny que sobra quien me quiera,\npero ninguna me importa:\nsólo pienso en ti, morena.",75,2,-1,88,"Serenata huasteca’’",0,4,"ea",-1,0,-1,0,261,261,"1601","",0,"","","",1,0,0,[],""],["frenk_t1-n1602",5,"Más hermosa es que el sol\ny más blanca que la espuma;\nhay por áhi muchas mujeres,\npero como tú, ninguna.",75,2,-1,88,"¡Viva quien sabe querer!",0,4,"ua",-1,0,-1,0,261,261,"1602","",0,"","","",1,0,0,[],""],["frenk_t1-n1605",5,"Por áhi va la despedida\ndeshojando una rosita;\naquí se acaban cantando\nversos de “La delgadita”.\nNo te cambiaría por otra,\nni aunque sea la más bonita.",75,2,-1,88,"Eres alta y delgadita",9,6,"ia",50,0,-1,0,261,261,"1605","",0,"","","",3,0,0,[],""],["frenk_t1-n1606",5,"Zenaida, ingrata, me traes rendido\ndesde el momento en que te conocí\ndistintas flores he conseguido,\npero ninguna que se iguale a ti.",75,2,-1,88,"Zenaida",3,4,"i",23,0,-1,0,261,261,"1606","",0,"","","",1,0,0,[],""],["frenk_t1-n1607",5,"Yo en el mundo no he querido\notra mujer como a ti;\npero vivo agradecido\nque se acordarán de mí\nlos que como yo han sufrido.",75,2,-1,88,"El sacamandú",7,5,"io",101,0,-1,0,261,261,"1607","",0,"","","",1,0,0,[],""],["frenk_t1-n1609",5,"Más quisiera contigo\nvivir en guerra,\nque estar con otra\nque me quisiera.",75,2,-1,88,"Estrofa suelta",6,4,"ea",-1,0,-1,0,262,262,"1609","",0,"","","",3,0,0,[],""],["frenk_t1-n1610",5,"De todas a ti te quiero\ny por eso lo repito:\nmorena mía,\ndame un besito.",86,2,11,88,"Los barandales",3,4,"io",119,0,-1,0,262,262,"1610","",0,"","","",3,0,0,[],""],["frenk_t1-n1611",5,"De todas a ti te quiero,\nde las demás no hago caso:\nchinita mía,\ndame un abrazo.",75,2,-1,88,"Los barandales",3,4,"ao",43,0,-1,0,262,262,"1611","",0,"","","",3,0,0,[],""],["frenk_t1-n1613",5,"¿Cómo quieres que una luz\nalumbre dos aposentos?\n¿Cómo quieres que yo quiera\ndos corazones a un tiempo?",75,2,-1,88,"Estrofa suelta",0,4,"eo",-1,0,-1,0,262,262,"1613","",0,"murciano_antiguo","","",7,0,0,[],""],["frenk_t1-n1615",5,"Un año termina hoy,\npero comienza otro nuevo,\nen cambio para tu amoï-\nno puedo hallar el relevo.",75,2,-1,88,"La nube",0,4,"eo",240,0,-1,0,262,262,"1615","",0,"","","",1,0,0,[],""],["frenk_t1-n1616",5,"No debes dudar, criatura,\nde mi amor y su firmeza;\ninterroga a la natura,\ny verás que te confiesa\nmi amor, cariño y ternura.",81,2,6,88,"Estrofa suelta",7,5,"ua",17,0,-1,0,263,263,"1616","",0,"","","",1,0,0,[],""],["frenk_t1-n1617",5,"Dentro de mi alma vivirás,\nsi Dios me lo concediera;\nyo nunca te olvidaré,\ntú serás mi compañera,\ntú de mí te acordarás.",77,2,2,88,"Estrofa suelta",7,5,"a",51,0,-1,0,263,263,"1617","",0,"","","",1,0,0,[],""],["frenk_t1-n1618",5,"Arroyito cristalino\ndonde se bañó mi amor;\nyo te he de seguir amando\ncomo el pájaro a la flor.",75,2,-1,88,"Estrofa suelta",0,4,"o",72,0,-1,0,263,263,"1618","",0,"","","",1,0,0,[],""],["frenk_t1-n1619",5,"Yo no pienso abandonarte,\ndonde estés te he de encontrar;\nmientras que en el mundo viva\nte he de amar y te he de amar.",75,2,-1,88,"Te he de amar y te he de amar",0,4,"a",21,0,-1,0,263,263,"1619","",0,"","","",1,0,0,[],""],["frenk_t1-n1620",5,"En el océano Pacífico\nse me perdió un alfiler;\nel día que yo lo encuentre\nte dejaré de querer.",75,2,-1,88,"Estrofa suelta",0,4,"e",20,0,-1,0,263,263,"1620","",0,"","","",1,0,0,[],""],["frenk_t1-n1621",5,"Cuando yo iba en una lancha\ntiré un alfiler al mar;\nel día que tú lo encuentres\nte dejaré de adorar.",84,2,9,88,"Estrofa suelta",0,4,"a",21,0,-1,0,263,263,"1621","",0,"","","",1,0,0,[],""],["frenk_t1-n1622",5,"El invierno llegó,\nla primavera se irá,\npero mi estimación por ti\nnunca se acabará.",86,2,11,88,"Estrofa suelta",0,4,"a",9,0,-1,0,263,263,"1622","",0,"","","",1,0,0,[],""],["frenk_t1-n1623",5,"En un bejuquito anteado,\nmi bien, te quisiera ver,\ny vive con el cuidado\nque siempre te he de querer,\ngajito del verde prado.",80,2,5,88,"Estrofa suelta",7,5,"ao",14,0,-1,0,263,263,"1623","",0,"","","",1,0,0,[],""],["frenk_t1-n1624",5,"Te prometo, mientras que yo viva,\nen el mundo no hacerte traición,\nporque eres la mujer consentida\ny la dueña de mi corazón.",82,2,7,88,"Hoy es el día",3,4,"o",31,0,-1,0,263,263,"1624","",0,"","","",1,0,0,[],""],["frenk_t1-n1625",5,"Rosa de Castilla en rama,\npriende y se vuelve a secar;\ndende aquí te estoy mirando;\n¡cómo te he de abandonar!",92,2,17,88,"Rosa de Castilla",0,4,"a",21,0,-1,0,263,263,"1625","",0,"","","",1,0,0,[],""],["frenk_t1-n1626",5,"Ya vine, ya estoy aquí,\ndame un abrazo siquiera;\nya sabes que te he querido\ny siempre te he de querer;\nno te he de echar en olvido,\naunque sienta el padecer.",75,2,-1,88,"Estrofa suelta",9,6,"e",20,0,-1,0,264,264,"1626","",0,"","","",4,0,0,[],""],["frenk_t1-n1627",5,"Cuando quiere amanecer\nse quiere acabar mi vida (oye);\ny te doy a comprender\nque el que te ama no te olvida (mi bien)\nni te deja de querer (mi bien).",75,2,-1,88,"La madrugada",7,5,"e",20,0,-1,0,264,264,"1627","",0,"","","",2,0,0,[],""],["frenk_t1-n1630",5,"La azucena es una flor\nde las que te regalé\ncon mocedad y con fe;\npor eso digo, mujer,\nque nunca te olvidaré.",75,2,-1,88,"La azucena",7,5,"e",-1,0,-1,0,264,264,"1630","",0,"","","",2,0,0,[],""],["frenk_t1-n1634",5,"A mí me cuadran los hombres\nporque por ellos nací;\nasí no temas, mi vida,\nque yo me olvide de ti.",75,2,-1,88,"La chaparrita",0,4,"i",23,0,-1,0,265,265,"1634","",0,"","","",1,0,0,[],""],["frenk_t1-n1635",5,"Nunca olvido un corazón,\naunque no esté en mi presencia;\nmira que tengo intenciones\nde guardarte consecuencias\ny darte satisfacción\nhasta la alta providencia.",84,2,9,88,"Estrofa suelta",9,6,"ea",-1,0,-1,0,265,265,"1635","",0,"","","",1,0,0,[],""],["frenk_t1-n1636",5,"No pienses que por no verte\nmi amor se ha desvanecido;\nyo soy costeño constante,\ny cuando quiero no olvido.",83,2,8,88,"Estrofa suelta",0,4,"io",101,0,-1,0,265,265,"1636","",0,"","","",1,0,0,[],""],["frenk_t1-n1639",5,"Amores a la batalla,\nque te quiero preguntar,\nque aunque a otras tierras te vayas,\nyo firme te he de adorar.",83,2,8,88,"La guacamaya",0,4,"a",21,0,-1,0,265,265,"1639","",0,"","","",2,0,0,[],""],["frenk_t1-n1640",5,"Tristes los dos padecemos,\npues que penamos los dos;\nestaré sin verte, sí,\npero sin quererte, no.",75,2,-1,88,"Glosada en décimas",0,4,"o",-1,0,-1,0,265,265,"1640","",0,"","","",1,0,0,[],""],["frenk_t1-n1642",5,"Una paloma al llegar\ncantaba con pasión:\n‘\"Morena, si tú te vas,\nllévate mi corazón.”",75,2,-1,88,"El bejuquito",0,4,"o",31,0,-1,0,266,266,"1642","",0,"","","",1,0,0,[],""],["frenk_t1-n1643",5,"Yo siento mucho dejarte\ny no poderte llevar,\npero si tu amor es firme,\nconmigo podrás contar:\n¿qué cosa podrás pedirme\nque yo no te pueda dar?",75,2,-1,88,"El siquisirí",9,6,"a",21,0,-1,0,266,266,"1643","",0,"","","",1,0,0,[],""],["frenk_t1-n1644",5,"Me despido de mi querida Adela,\nya me alejo de mi único placer;\nnunca esperes de mí una cautela,\nni te cambie por otra mujer.",75,2,-1,88,"La Adelita",3,4,"e",20,0,-1,0,266,266,"1644","",0,"","","",1,0,0,[],""],["frenk_t1-n1646",5,"Palomita, ¿de dónde vienes,\ncansada de caminar?\nContemplando tu belleza\nme dan ganas de llorar.",75,2,-1,89,"La palomita",0,4,"a",21,0,-1,0,267,267,"1646","",0,"","","",1,0,0,[],""],["frenk_t1-n1647",5,"Vuela, vuela, palomita,\nvuela, vuela al palomar;\nno te vayas tan solita (palomita),\nyo te quiero acompañar.",89,2,14,89,"Estando amarrando; La palomita",3,4,"a",21,0,-1,0,267,267,"1647","",0,"","","",3,0,0,[],""],["frenk_t1-n1648",5,"Ya te he dicho que al agua no bajes,\ny si bajas, que no sea muy tarde,\nque si bajas, tendrás quien te aguarde;\nya más tarde sabrás quién soy yo.",78,2,3,89,"No bajes al agua",3,4,"o",-1,0,-1,0,267,267,"1648","",0,"","","",1,0,0,[],""],["frenk_t1-n1649",5,"Ya no pases por debajo\nen ese puente tan obscuro;\nahí roban corazones:\nvayan a robarte el tuyo.",75,2,-1,89,"Botón de rosa",0,4,"uo",-1,0,-1,0,267,267,"1649","",0,"","","",1,0,0,[],""],["frenk_t1-n1650",5,"Chiquitita te vas criando\ncomo el zacate en el llano;\nDios te libre de un costeño\ncon su machete en la mano.",83,2,8,89,"Chiquitita te vas criando; La Sanmarqueña; Por lo alto doy cincuenta",0,4,"ao",81,0,-1,0,267,267,"1650","",0,"","","",1,0,0,[],""],["frenk_t1-n1651",5,"Palomita, vete al campo\ny dile a los tiradores\nque no te tiren a ti,\nque eres la reina de amores.",75,2,-1,89,"El palomo; El buscapiés; El tejón",0,4,"oe",5,0,-1,0,267,267,"1651","",0,"","","",1,0,0,[],""],["frenk_t1-n1652",5,"Palomi, palomita, te lo dije,\nque tú al río no bajes a beber agua,\nporque allí están los de Cuaque,\ny éstos sí yo no sé si no te amarran.",75,2,-1,89,"El palomo",3,4,"aa",-1,0,-1,0,268,268,"1652","",0,"","","",1,0,0,[],""],["frenk_t1-n1654",5,"Linda venadita,\nno bajes a Los Dolores,\nte vayan a matar\nlos tiradores de amores.",78,2,3,89,"La venadita",0,4,"oe",5,0,-1,0,268,268,"1654","",0,"","","",1,0,0,[],""],["frenk_t1-n1656",5,"Qué bonito gavilán,\nno te vaya a enamorar;\nqué maldito gavilán,\nno te lo dejes llegar.",75,2,-1,89,"El gavilán",1,4,"a",-1,0,-1,0,268,268,"1656","",0,"","","",2,0,0,[],""],["frenk_t1-n1658",5,"Comadrita de mi vida,\nallá viene el gavilán,\nesconda su polla gira,\nno se la vaya a llevar.",77,2,2,89,"El gavilán del Sur",0,4,"a",-1,0,-1,0,268,268,"1658","",0,"","","",1,0,0,[],""],["frenk_t1-n1660",5,"Cempoatzúchil amarillo,\nno te quisiera cortar,\nporque mi mano es caliente,\nte vayas a marchitar.",75,2,-1,89,"Mi hermanita se casó",0,4,"a",21,0,-1,0,268,268,"1660","",0,"","","",1,0,0,[],""],["frenk_t1-n1661",5,"Cuando vayas por el agua,\nno pases por el nopal,\nque allí está mi corazón,\ny te puedes espinar.",75,2,-1,89,"Estrofa suelta",0,4,"a",-1,0,-1,0,269,269,"1661","",0,"","","",1,0,0,[],""],["frenk_t1-n1662",5,"Que no te hiera el dolor\nque mi corazón respira;\nduerme soñando en mi amor,\nmientras la brisa suspira\nde la luna el resplandor.",75,2,-1,89,"El fandanguito; El aguanieve",7,5,"o",72,0,-1,0,269,269,"1662","",0,"","","",1,0,0,[],""],["frenk_t1-n1663",5,"En la puerta de mi casa\ntengo un palo de romero;\ncuando pasas por la calle\nno agaches el sombrero.",87,2,12,89,"Estrofa suelta",0,4,"eo",38,0,-1,0,269,269,"1663","",0,"","","",24,0,0,[],""],["frenk_t1-n1664",5,"Cuando pases por mi casa\nno te agaches el sombrero,\nporque se me representa\nque te lleven prisionero.",85,2,10,89,"Estrofa suelta",0,4,"eo",38,0,-1,0,269,269,"1664","",0,"","","",3,0,0,[],""],["frenk_t1-n1665",5,"Si no paso por tu casa,\nno es por falta de valor:\npor no echarte un compromiso,\nlinda de mi corazón.",92,2,17,89,"Rosa de Castilla",0,4,"o",-1,0,-1,0,269,269,"1665","",0,"","","",1,0,0,[],""],["frenk_t1-n1666",5,"Si en tu casa te regañan,\néchame la culpa a mí,\ndéjame pasar desaires,\nlo que tú no harás por mí.",89,2,14,89,"Cuando salgo del trabajo",0,4,"i",-1,0,-1,0,269,269,"1666","",0,"","","",4,0,0,[],""],["frenk_t1-n1667",5,"Soy como el vaso al quebrar,\ndel cristal más reluciente;\nsi por mí pasas trabajos,\npronto me verás ausente,\ncon la vista para abajo\ny el cariño como siempre.",83,2,8,89,"Estrofa suelta",9,6,"ee",-1,0,-1,0,269,269,"1667","",0,"","","",1,0,0,[],""],["frenk_t1-n1668",5,"Del cielo cayó una yedra\ny en tu ventana se enredó;\nlos enredos que tú tengas\nésos los compongo yo.",75,2,-1,89,"Amorcito consentido",3,4,"o",2,0,-1,0,269,269,"1668","",0,"","","",2,0,0,[],""],["frenk_t1-n1669",5,"Mi vida, ¿qué se te ofrece?,\nque aquí está tu servidor,\nque te ama y por ti padece,\ny te guarda el honor\nque tu hermosura merece.",75,2,-1,89,"El jarabe",7,5,"ee",64,0,-1,0,269,269,"1669","",0,"","","",1,0,0,[],""],["frenk_t1-n1670",5,"No te levantes descalza,\nno te vayas a resfriar;\nponte tus babuchas viejas,\nyo te las voy a abrochar.",85,2,10,89,"El indio mexicano; Las mañanitas",0,4,"a",21,0,-1,0,270,270,"1670","",0,"","","",1,0,0,[],""],["frenk_t1-n1671",5,"Carolina, Carolina,\nno te vayas a bañar,\nporque el agua está muy fría,\ny no te vayas a resfriar.",75,2,-1,89,"El vacilón",0,4,"a",21,0,-1,0,270,270,"1671","",0,"","","",4,0,0,[],""],["frenk_t1-n1676",5,"¡Ay, virgencita santa!\nte juro ser cumplido.\nNunca vayas a embarcar\nen una lancha podrida\ny te vayas a quedar\ncomo una cosa perdida,\nsin que te pueda encontrar.",85,2,10,89,"La Petenera",4,7,"a",21,0,-1,0,270,270,"1676","",0,"","","",1,0,0,[],""],["frenk_t1-n1678",5,"—¡Ay, qué frío, ay, qué frío!,\ncomo que quiere nevar.\n—¿Cómo dice que tiene frío?\nCobíjese el barragán.",85,2,10,89,"El frío",0,4,"a",-1,0,-1,0,271,271,"1678","",0,"","","",2,0,0,[],""],["frenk_t1-n1680",5,"Adelaida y Adelaida,\nqué sentimiento me da\nde verte tan sumergida,\ny yo sin poderte hablar.",75,2,-1,89,"Adelaida",0,4,"a",-1,0,-1,0,271,271,"1680","",0,"","","",1,0,0,[],""],["frenk_t1-n1681",5,"¡Ay, ay, ay, ay, ay, Llorona!,\nLloroncita, cielo lindo,\nayer te vide penando (Llorona)\ndebajo de un tamarindo.",75,2,-1,89,"La Llorona",3,4,"io",541,0,-1,0,271,271,"1681","",0,"","","",1,0,0,[],""],["frenk_t1-n1682",5,"Al pie de un rosal florido (Llorona)\nte vi llorar la otra tarde,\ny al verte llorar, las flores (Llorona)\nse murieron de pesares.",75,2,-1,89,"La Llorona",3,4,"ae",-1,0,-1,0,271,271,"1682","",0,"","","",1,0,0,[],""],["frenk_t1-n1683",5,"Amorcito consentido,\ndime si estás enojado,\ndime qué te sucedió\npor lo que anoche pasó.",75,2,-1,89,"Amorcito consentido",5,4,"o",2,0,-1,0,271,271,"1683","",0,"","","",5,0,0,[],""],["frenk_t1-n1684",5,"Amorcito consentido,\ndime qué te ha sucedido,\ndime si estás enojado;\ncon eso no pago yo.",75,2,-1,89,"Amorcito consentido",5,4,"o",-1,0,-1,0,271,271,"1684","",0,"","","",5,0,0,[],""],["frenk_t1-n1685",5,"Amorcito consentido,\n¿cómo haré para consolarte?\nTe llevaré a la Alameda,\nal otro lado, a pasearte.",83,2,8,89,"Estrofa suelta",0,4,"ae",8,0,-1,0,271,271,"1685","",0,"","","",5,0,0,[],""],["frenk_t1-n1686",5,"Desde allá te vi venir,\npuse mi amor en derecho;\nven acá, vidita mía,\na refugiarte en mi pecho.",83,2,8,89,"Estrofa suelta",0,4,"eo",60,0,-1,0,271,271,"1686","",0,"","","",1,0,0,[],""],["frenk_t1-n1687",5,"Dime qué significa\ncuando te asomas:\nte paras en la puerta (cielito lindo)\ny luego lloras;\nno llores tanto,\nmira que me atormenta (cielito lindo)\ntu amargo llanto.",77,2,2,89,"Cielito lindo",4,7,"ao",30,0,-1,0,272,272,"1687","",0,"","","",2,0,0,[],""],["frenk_t1-n1688",5,"Va no llores, ya no llores (Llorona),\ndeja de verter tu llanto,\nporque entristeces, Llorona,\nal hombre que te ama tanto.",83,2,8,89,"La Llorona",3,4,"ao",30,0,-1,0,272,272,"1688","",0,"","","",1,0,0,[],""],["frenk_t1-n1690",5,"No me llores, no,\nporque si lloras, me muero;\nen cambio, si tú me cantas,\nyo siempre vivo y nunca muero.",83,2,8,89,"La Martiniana",3,4,"eo",-1,0,-1,0,272,272,"1690","",0,"","","",1,0,0,[],""],["frenk_t1-n1691",5,"Cierra esos ojos, chinita, ya no llores,\ncierra esos ojos chinitos y encantadores,\ncierra esos ojos toditos llenos de amores,\ncierra esos ojos y deja de llorar.",85,2,10,89,"La chinita",3,4,"a",-1,0,-1,0,272,272,"1691","",0,"","","",1,0,0,[],""],["frenk_t1-n1697",5,"Palomita enlutadita,\ndime quién se te murió;\nsi se te murió tu amante,\nno llores, que aquí estoy yo.",75,2,-1,89,"Estrofa suelta, Amorcito consentido; La enlutadita. La tortolita",0,4,"o",2,0,-1,0,273,273,"1697","",0,"","","",1,0,0,[],""],["frenk_t1-n1698",5,"Agua de las Tenerías,\ndonde se regó una flor.\nNo estés triste, vida mía,\naquí tienes a tu amor:\nfirme como el primer día,\nsiempre soy tu Nicanor.",89,2,14,89,"Delgadita de cintura",9,6,"o",72,0,-1,0,273,273,"1698","",0,"","","",1,0,0,[],""],["frenk_t1-n1701",5,"Calla, mujer, calla,\ndeja de tanto llorar,\nmira que ahora sí nos vamos\nhasta cerca del palmar.",75,2,-1,89,"Las campanilas",0,4,"a",21,0,-1,0,273,273,"1701","",0,"","","",2,0,0,[],""],["frenk_t1-n1707",5,"Al pasar por una huerta\nme corté una hermosa sandía,\ny en el corazón le hallé\nun letrero que decía:\n“Trigueñita, si tú me quieres,\nyo estoy como el primer día.”",83,2,8,90,"Estrofa suelta",9,6,"ia",0,0,-1,0,275,275,"1707","",0,"","","",4,0,0,[],""],["frenk_t1-n1708",5,"No había podido venir,\npor estar en mis quehaceres;\nsólo le vengo a decir\nque si todavía me quiere,\nque soy firme hasta el morir,\ncomo bien saben ustedes.",79,2,4,90,"El siquisirí",9,6,"ee",-1,0,-1,0,275,275,"1708","",0,"","","",1,0,0,[],""],["frenk_t1-n1709",5,"Si me llegas a querer\ntanto como yo te quiero,\nen el mundo no ha de haber\nun amor tan verdadero\ncomo el que hemos de tener,\njoven, si yo no me muero.",79,2,4,90,"El pájaro carpintero",9,6,"eo",38,0,-1,0,275,275,"1709","",0,"","","",2,0,0,[],""],["frenk_t1-n1710",5,"Arbolito, arbolito,\nmantente firme,\nque a mí sólo la muerte\npuede rendirme.",79,2,4,90,"El pájaro cú",6,4,"ie",184,0,-1,0,275,275,"1710","",0,"","","",3,0,0,[],""],["frenk_t1-n1711",5,"Corté la flor del maguey\nporque me agradó su olor.\nY si tú me das palabra,\nhe de seguir a tu amor,\naunque muera apuñalado,\nque para mí no es dolor.",83,2,8,90,"El siquisirí",9,6,"o",72,0,-1,0,275,275,"1711","",0,"","","",1,0,0,[],""],["frenk_t1-n1714",5,"En la medianía del mar\nte he de poner tres pilares;\ncomo me sepas amar\ny nunca me desampares,\nyo jamás te he de olvidar,\naunque de otro amor te agarres.",75,2,-1,90,"Estrofa suelta",9,6,"ae",-1,0,-1,0,276,276,"1714","",0,"","","",6,0,0,[],""],["frenk_t1-n1718",5,"Si me llegas a querer,\nescrito te doy mi nombre;\nsi algo te quieren hacer,\nno te asustes, no te asombres,\nque no es la primer mujer\nque su amor pone en un hombre",79,2,4,90,"Me puse en un espiadero",9,6,"oe",-1,0,-1,0,276,276,"1718","",0,"","","",2,0,0,[],""],["frenk_t1-n1719",5,"Ojalá que tú fueras firme:\nal cabo ¿qué me han de hacer?,\nque no soy el primer hombre,\nni tú la primera mujer.",75,2,-1,90,"Trigueñita",0,4,"e",20,0,-1,0,276,276,"1719","",0,"","","",1,0,0,[],""],["frenk_t1-n1720",5,"Allí escríbeme lo que tú quieras,\ny yo te comprenderé;\ncomprendo lo que me quieres,\n¡cómo no he de comprender!\nAntonia de los claveles,\nque el corazón te robé.",75,2,-1,90,"Antonia",9,6,"e",-1,0,-1,0,276,276,"1720","",0,"","","",1,0,0,[],""],["frenk_t1-n1721",5,"Antier tarde que te vi\nen primera vez parada\ndesde luego comprendí\nque tu corazón me amaba;\ntodo tiene su hasta aquí,\nchina, bella, encarrujada.",77,2,2,90,"Estrofa suelta",9,6,"aa",-1,0,-1,0,277,277,"1721","",0,"","","",1,0,0,[],""],["frenk_t1-n1722",5,"Aunque digas otra cosa,\nyo sé bien que tú me quieres,\nsé que soy tu consentido,\nchiquitita, no lo niegues.",75,2,-1,90,"Ojitos color de olivo’’",0,4,"ee",-1,0,-1,0,277,277,"1722","",0,"","","",1,0,0,[],""],["frenk_t1-n1723c",5,"Con los chinos de tu frente\nme mandastes amarrar;\ncomo fui tan inocente,\nno me pude desatar;\nsi tus chinos se revientan,\nen tus brazos iré a dar.",87,2,12,90,"Estrofa suelta, La presumida",9,6,"a",21,0,-1,0,277,277,"1723c","",0,"","","",5,0,0,[],""],["frenk_t1-n1724",5,"Si al dormir puedo ver\ntu boquita sonreír,\nya sabré comprender\nque tu risa es para mí.",86,2,11,90,"Estrofa suelta",0,4,"i",-1,0,-1,0,277,277,"1724","",0,"","","",1,0,0,[],""],["frenk_t1-n1725",5,"De tus labios la sonrisa\nme indica que estás gozando,\ny aunque a mí me martiriza,\nquisiera vivir besando\nhasta la tierra que pisas.",75,2,-1,90,"Estrofa suelta",7,5,"ia",-1,0,-1,0,277,277,"1725","",0,"","","",1,0,0,[],""],["frenk_t1-n1726",5,"Qué linda está la mañana\ncuando el sol viene rayando;\nmas dices que eres mujer\ncuando me estás abrazando.",92,2,17,90,"Los papaquis",0,4,"ao",33,0,-1,0,277,277,"1726","",0,"","","",2,0,0,[],""],["frenk_t1-n1727",5,"¡Ay, qué cañas tan moradas!,\n¡qué jilotes tan güeritos!\n¡Qué señas tan agraciadas\nme haces con esos ojitos!",78,2,3,90,"La chaparrita; A mi chata; Qué milagro, chaparrita",1,4,"io",254,0,-1,0,277,277,"1727","",0,"","","",1,0,0,[],""],["frenk_t1-n1729",5,"A la sombra del mezquite,\ndonde tu amor conocí,\nno tengo quién me lo quite:\nyo solo ando por aquí.",75,2,-1,90,"El mezquite",1,4,"i",23,0,-1,0,278,278,"1729","",0,"","","",1,0,0,[],""],["frenk_t1-n1730",5,"Mariquita, mi alma,\nyo te lo decía:\nque tarde o temprano (mi vida)\ntú habías de ser mía.",75,2,-1,90,"Las abajeñas; La abajeña; La indita , María Chuchcna",0,4,"ia",0,0,-1,0,278,278,"1730","",0,"","","",1,0,0,[],""],["frenk_t1-n1735",5,"Una vez que a misa fui,\nque mis padres me mandaron,\nluego que el sermón oí\nque los curas predicaron\nque yo nací para ti,\ny a ti para mí te criaron.",75,2,-1,90,"La morena",9,6,"ao",41,0,-1,0,278,278,"1735","",0,"","","",1,0,0,[],""],["frenk_t1-n1736",5,"Entre las peñas nací,\nlas aguilillas me criaron;\nporque santos yo vendí,\nmi corazón cautivaron,\ny yo para ti nací,\ny tú, para mí te criaron.",81,2,6,90,"La azucena",9,6,"ao",41,0,-1,0,279,279,"1736","",0,"","","",1,0,0,[],""],["frenk_t1-n1737",5,"La carta que te escribí\nme dicen que te la hallaron,\ny tú les dijistes así\na los que te la encontraron:\nque yo nací para ti,\ny a ti para ipí te criaron.",79,2,4,90,"El Balajú",9,6,"ao",41,0,-1,0,279,279,"1737","",0,"","","",2,0,0,[],""],["frenk_t1-n1739",5,"Corté la flor del acuyo,\npor saber a lo que olía.\nYa no me cabe el orgullo,\nestoy lleno de alegría:\nel saber que yo soy tuyo,\ntú eres enterita mía.",79,2,4,90,"El buscapiés",9,6,"ia",0,0,-1,0,279,279,"1739","",0,"","","",1,0,0,[],""],["frenk_t1-n1740",5,"La chuparrosa y la flor\nse crían como dos amantes;\nmi cariño con tu amor\nson como perlas brillantes\nque mezclan su resplandor.",81,2,6,90,"La rosita",7,5,"o",72,0,-1,0,279,279,"1740","",0,"","","",1,0,0,[],""],["frenk_t1-n1741",5,"Indita, indita,\nindita del verde llano,\nsi tu cariño es el huerto,\nmi amor será el hortelano;\nuna rosa de Castilla\nse me deshizo en la mano.",79,2,4,90,"La indita",9,6,"ao",81,0,-1,0,279,279,"1741","",0,"","","",2,0,0,[],""],["frenk_t1-n1742",5,"Alza los ojos y mira\nlo que está escrito en el cielo:\ntu nombre y el mío formados\npor estrellas y luceros,\npara que si alguien te quiere,\nsepa que yo fui primero.",75,2,-1,90,"Carta abierta",9,6,"eo",-1,0,-1,0,279,279,"1742","",0,"","","",4,0,0,[],""],["frenk_t1-n1743",5,"Dicen que en la mar se juntan\naguas de todos los ríos:\n¡cómo no se han de juntar\ntus amores con los míos!",83,2,8,90,"La Sanmarqueña; El gavilancito",0,4,"io",135,0,-1,0,279,279,"1743","",0,"","","",2,0,0,[],""],["frenk_t1-n1758c",5,"¿Qué dijera tu mamá,\nque nos viera platicando?\nLe dirías que me debías\ny que me estabas pagando\nlos besitos que me debes\ny otro que me estabas liando.",85,2,10,90,"El venadito; El jarabe loco",9,6,"ao",33,0,-1,0,282,282,"1758c","",0,"","","",1,0,0,[],""],["frenk_t1-n1763",5,"En el patio de mi casa\ntengo un palo de cerezo;\ncada ramita que echa, un abrazo,\ncada botoncito, un beso",75,2,-1,90,"Estrofa suelta",3,4,"eo",48,0,-1,0,282,282,"1763","",0,"","","",8,0,0,[],""],["frenk_t1-n1764",5,"Cuando te veo y me besas\ny nos besamos,\nme siento en otro mundo,\nfeliz, gozando.",84,2,9,90,"A cada paso que doy1'",3,4,"ao",-1,0,-1,0,283,283,"1764","",0,"","","",1,0,0,[],""],["frenk_t1-n1765",5,"Bonito Montemorelos\ncon su lindo naranjal,\npero más me gusta, prieta,\ntu caricia angelical.",75,2,-1,90,"Bonito Montemorelos11",0,4,"a",1,0,-1,0,283,283,"1765","",0,"","","",1,0,0,[],""],["frenk_t1-n1766",5,"Yo no sé qué me habrás hecho,\nque al amarte no soy ruin;\npero estoy muy satisfecho\ntenerte como el violín,\nrecargadita en mi pecho.",77,2,2,90,"El taconcito",7,5,"eo",60,0,-1,0,283,283,"1766","",0,"","","",2,0,0,[],""],["frenk_t1-n1767",5,"A que te peino, china,\ny a la madrugada te ato,\ny al amanecer el día\nlos chinos te desbarato.",75,2,-1,90,"La madrugada; El peine; Estrofa suelta",0,4,"ao",19,0,-1,0,283,283,"1767","",0,"","","",2,0,0,[],""],["frenk_t1-n1769",5,"A que yo te peino, china,\ndebajo de los laureles;\nai amanecer el día\n¡ay, qué rebonita eres!",92,2,17,90,"El peine",0,4,"ee",-1,0,-1,0,283,283,"1769","",0,"","","",2,0,0,[],""],["frenk_t1-n1770",5,"Úchile y úchile, que en la calle\nte di un abrazo bajo del talle;\núchile y úchile, que en la villa\nte di dos besos en la mejilla.",75,2,-1,90,"El espinado",3,4,"ia",162,0,-1,0,283,283,"1770","",0,"","","",1,0,0,[],""],["frenk_t1-n1771",5,"Úchile y úchile, que te puse\nla boquita como un dulce;\núchile y úchile, que te pongo\nla boquita como un hongo.",75,2,-1,90,"El espinado11",3,4,"oo",484,0,-1,0,283,283,"1771","",0,"","","",1,0,0,[],""],["frenk_t1-n1772",5,"Por si algún afortunado\nllega a tus labios besar,\nse va a quedar encantado,\nporque le van a gustar\nlos besos que yo te he dado.",77,2,2,90,"La azucenaJ",7,5,"ao",14,0,-1,0,283,283,"1772","",0,"","","",1,0,0,[],""],["frenk_t1-n1782",5,"¡Válgame Dios,\nSanta Lucía!,\npor estar contigo, mi alma,\nya mero me amanecía.",85,2,10,90,"Los luliscs",3,4,"ia",0,0,-1,0,285,285,"1782","",0,"","","",1,0,0,[],""],["frenk_t1-n1783",5,"¡Ah, qué caray!, María Reducinda,\nchatita, ya amaneció,\nya los pajarillos cantan,\nya la luna se metió.",85,2,10,90,"María Reducinda; Ya los pajaritos cantan",3,4,"o",2,0,-1,0,285,285,"1783","",0,"","","",1,0,0,[],""],["frenk_t1-n1785",5,"Dicen que no nos queremos,\nporque no nos ven hablar:\nnosotros nos entendemos\npor el modo de mirar.",79,2,4,90,"La pasión; Estrofa suelta",1,4,"a",21,0,-1,0,285,285,"1785","",0,"","","",11,0,0,[],""],["frenk_t1-n1786",5,"Dicen que no nos queremos,\nporque no nos ven hablar:\nsólo nosotros sabemos\ncon los ojos conversar,\nun rato, cuando podemos,\nsi se nos presta un lugar.",75,2,-1,90,"La Llorona",9,6,"a",21,0,-1,0,285,285,"1786","",0,"","","",11,0,0,[],""],["frenk_t1-n1787",5,"Dicen que no nos queremos,\nportille no nos ven hablar:\nno sernos escandalosos,\nsabemos disimular.",75,2,-1,90,"La chaparrita",0,4,"a",21,0,-1,0,285,285,"1787","",0,"","","",11,0,0,[],""],["frenk_t1-n1788",5,"Con los ojos del alma\nte estoy mirando,\ny con los de la cara\ndisimulando.",75,2,-1,90,"Estrofa suelta",6,4,"ao",33,0,-1,0,285,285,"1788","",0,"andina_t2","","",5,0,0,[],""],["frenk_t1-n1797",5,"Dile que no me eonoees,\nni que me has visto jamás;\nte suplico no me mientes\npara bien ni para mal.",75,2,-1,90,"Glosada en décimasJ",0,4,"a",-1,0,-1,0,287,287,"1797","",0,"","","",1,0,0,[],""],["frenk_t1-n1801",5,"¡Ay, dale, que dale, dale!,\n¡ay, dale, dale, que dale sí!\nNo quiero que sepa el mundo\nque te estoy queriendo a ti.",79,2,4,90,"El trompo",3,4,"i",23,0,-1,0,287,287,"1801","",0,"","","",2,0,0,[],""],["frenk_t1-n1802",5,"El verso que más prefiero (¡ay, Llorona!)\nése no lo digo a nadie:\nen el corazón lo guardo (Llorona)\ny del corazón no sale.",83,2,8,90,"La Llorona''I",3,4,"ae",-1,0,-1,0,287,287,"1802","",0,"","","",1,0,0,[],""],["frenk_t1-n1804",5,"Cupido me enseñó a leer\nun libro de varios modos;\ncuando te empecé a querer\nme lo maliciaron todos:\n¡ay, qué feo es no saber\ncómo se torean los toros!",83,2,8,90,"El Cupido",9,6,"oo",-1,0,-1,0,287,287,"1804","",0,"","","",2,0,0,[],""],["frenk_t1-n1805",5,"Observa, bella mujer,\nqué delirio he percibido;\nyo ya no sé como hacer:\ndisimularlo he querido,\nporque empiezan a saber\nque relacioné contigo.",75,2,-1,90,"La morena",9,6,"io",-1,0,-1,0,288,288,"1805","",0,"","","",1,0,0,[],""],["frenk_t1-n1806",5,"China de los ojos negros,\nsi mi amor te satisface,\nno le des razón a nadie:\ncada uno sabe lo que hace.",75,2,-1,90,"Estrofa suelta, La Zandunga",0,4,"ae",-1,0,-1,0,288,288,"1806","",0,"","","",2,0,0,[],""],["frenk_t1-n1808",5,"Aunque te ame y tú me adores,\nno lo des a conocer;\nmártires hemos de ser\nprimero que confesores.",75,2,-1,90,"Estrofa suelta",11,4,"oe",5,0,-1,0,288,288,"1808","",0,"","","",1,0,0,[],""],["frenk_t1-n1810",5,"Hazme soñar con tus ojos,\npero con formalidad;\nsi te perturba la gente,\ndiles que ésa es tu voluntad:\namarme a mí solamente.",75,2,-1,90,"Estrofa suelta",7,5,"ee",15,0,-1,0,288,288,"1810","",0,"","","",1,0,0,[],""],["frenk_t1-n1818",5,"Mi querer es tan formal\ncomo no lo puedes ver,\ny ni muerto que estuviera\nte dejaría de querer,",75,2,-1,91,"Estrofa suelta",0,4,"e",20,0,-1,0,291,291,"1818","",0,"","","",1,0,0,[],""],["frenk_t1-n1820",5,"Por adorarte, criatura,\nvivo en grande desespero;\nsi la fortuna me ayuda\no si por desgracia muero,\ndespués de mi sepoltura\nallá en la gloria te espero.",79,2,4,91,"Estrofa suelta",9,6,"eo",38,0,-1,0,291,291,"1820","",0,"","","",1,0,0,[],""],["frenk_t1-n1821",5,"Yo vide mi tumba abierta\ndonde me iban a enterrar;\nmorenita, ponte alerta,\nno te vayan a olvidar,\nporque esta alma, ya de muerta,\nte ha de venir a llevar.",77,2,2,91,"La Cecilia",9,6,"a",21,0,-1,0,291,291,"1821","",0,"","","",1,0,0,[],""],["frenk_t1-n1822",5,"Sólo Dios, sólo la muerte\nde tu amor me apartarán,\nporque vivos no podrán\nprivar mi amor de quererte.",75,2,-1,91,"Glosada en décimas",11,4,"ee",134,0,-1,0,291,291,"1822","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t1-n1823",5,"Sólo que pierda la vida\nentonces no volveré;\ntus besos y tus caricias\na mi tumba llevaré.",75,2,-1,91,"Trigueñita",0,4,"e",77,0,-1,0,291,291,"1823","",0,"","","",1,0,0,[],""],["frenk_t1-n1824",5,"En papel blanco te escribo\nporque blanca fue mi suerte;\nno te he de echar en olvido\nni tampoco aborrecerte\nhasta que me veas tendido\ny en los brazos de la muerte.",83,2,8,91,"¡Ay, que cielo tan azul!; Estrofa suelta",9,6,"ee",134,0,-1,0,291,291,"1824","",0,"","","",7,0,0,[],""],["frenk_t1-n1825",5,"Es mentira, no lo creas,\nque mi amor te eche en olvido:\nsolamente que me veas\nen una mesa tendido,\ncon cuatro velas ardiendo,\ndando fe de mi retiro.",75,2,-1,91,"La curreña; La señora",9,6,"io",-1,0,-1,0,291,291,"1825","",0,"","","",1,0,0,[],""],["frenk_t1-n1827",5,"Soy de la tierra florida\ndonde nació la venganza.\nTrigueñita de mi vida,\nlo que te digo no es chanza:\nsólo que te vea tendida\nse me acaba la esperanza.",101,2,26,91,"La azucena",9,6,"aa",163,0,-1,0,292,292,"1827","",0,"","","",1,0,0,[],""],["frenk_t1-n1828",5,"Ya me quitaron el verte,\ntodo ese gusto que trae,\npero dejar de quererte\nno han podido ni podrán:\nsólo que me den la muerte\nde tu amor me apartarán.",75,2,-1,91,"La morena",9,6,"a",147,0,-1,0,292,292,"1828","",0,"","","",1,0,0,[],""],["frenk_t1-n1830",5,"Linda como la mar\nes tu hermosura;\nmira que soy tu amante,\nbella criatura\nQué gran orgullo:\nsólo que yo me muera\nno seré tuyo.",75,2,-1,91,"Cielito lindo",4,7,"uo",78,0,-1,0,292,292,"1830","",0,"","","",1,0,0,[],""],["frenk_t1-n1834",5,"Ayer, que me lleva el agua\nen una viga nadando;\nsólo que la mar se seque\nno me seguiré bañando.",75,2,-1,91,"La Sanniarqueña",0,4,"ao",33,0,-1,0,292,292,"1834","",0,"","","",1,0,0,[],""],["frenk_t1-n1835",5,"Yo tengo mi riqui-riqui,\nyo tengo mi riqui andando;\nsólo que la mar se seque\nno me seguiré bañando.",78,2,3,91,"E! riqui-riqui",0,4,"ao",33,0,-1,0,293,293,"1835","",0,"","","",1,0,0,[],""],["frenk_t1-n1836",5,"Mientras las olas del mar\nse vistan de azul celeste,\nte he de querer, te he de amar,\naunque la vida me cueste.",75,2,-1,91,"Estrofa suelta",1,4,"ee",396,0,-1,0,293,293,"1836","",0,"","","",1,0,0,[],""],["frenk_t1-n1837",5,"Chaparrita, chula linda,\nyo te quiero muy bastante,\nyo seré siempre tu amante,\ny aunque me cueste la vida.",75,2,-1,91,"La caña brava",5,4,"ia",-1,0,-1,0,293,293,"1837","",0,"","","",1,0,0,[],""],["frenk_t1-n1838",5,"Yo soy el diablo tunante\nde la hacienda más lucida;\nhe de ser su fiel amante,\naunque me cueste la vida.",75,2,-1,91,"AI pasar por tu ventana",1,4,"ia",37,0,-1,0,293,293,"1838","",0,"","","",1,0,0,[],""],["frenk_t1-n1840",5,"¡Ay de mí, Llorona!\nLlorona de azul celeste,\naunque la vida me cueste (Llorona),\nno dejaré de quererte.",83,2,8,91,"La Llorona",3,4,"ee",-1,0,-1,0,293,293,"1840","",0,"","","",35,0,0,[],""],["frenk_t1-n1841",5,"¡Ay, morená,\nmorená, la de allá arriba!,\ndesde que dejé de amar,\naunque me cueste la vida,\nte dejé de señalar.",75,2,-1,91,"La moienita",7,5,"a",21,0,-1,0,293,293,"1841","",0,"","","",4,0,0,[],""],["frenk_t1-n1842",5,"Por áhi dicen que la muerte\nme anda siguiendo los pasos\ny yo digo que la muerte\nme ha de llevar a tus brazos:\nentonces podré besarte,\naunque me den de balazos.",75,2,-1,91,"El patas blancas",9,6,"ao",132,0,-1,0,293,293,"1842","",0,"","","",1,0,0,[],""],["frenk_t1-n1848",5,"Dicen que por tus amores\nla vida voy a perder:\nnada me hacen los traidores,\ntan sólo con tu querer.",75,2,-1,91,"La Valentina",1,4,"e",20,0,-1,0,294,294,"1848","",0,"","","",4,0,0,[],""],["frenk_t1-n1849",5,"Se acabaron mis paseadas (bien mío),\npero te he de amar;\nvida mía, por tus amores\ndicen que me han de matar.",75,2,-1,91,"Se acabaron mis paseadas",3,4,"a",21,0,-1,0,294,294,"1849","",0,"","","",1,0,0,[],""],["frenk_t1-n1850",5,"Rosita, por tu cariño,\nla vida me va a costar;\nvale más morir matando,\nque yo dejarte de amar.",75,2,-1,91,"La Rosita; Los ojitos; Estrofa suelta",0,4,"a",21,0,-1,0,294,294,"1850","",0,"","","",1,0,0,[],""],["frenk_t1-n1851",5,"De la flor del cañamazo\nte he de hacer una corona;\ny aunque me tiren balazos,\nno me he de rendir, paloma,\nhasta no verme en tus brazos,\nporque tu amor me apasiona.",79,2,4,91,"María Chuchería",9,6,"oa",-1,0,-1,0,295,295,"1851","",0,"","","",1,0,0,[],""],["frenk_t1-n1852",5,"Me dices que por tu amor\nme han de matar a balazos;\nno le temas al rigor,\nque todos son amenazos;\n¡si a mí me sobra valor\npara morir en tus brazos!",101,2,26,91,"La azucena",9,6,"ao",132,0,-1,0,295,295,"1852","",0,"","","",1,0,0,[],""],["frenk_t1-n1854",5,"Dicen que por tus amores\nme van a quitar la vida;\nson pollas de mala raza,\nque no me dan la medida;\npor ti les doy en la mano\nderecha, que es más que vida",75,2,-1,91,"En la mano derecha",9,6,"ia",37,0,-1,0,295,295,"1854","",0,"","","",4,0,0,[],""],["frenk_t1-n1855",5,"No te creas de lo que dicen,\nque me han de quitar la vida:\nno más quieren asustarnos\ncon puras fanfarronadas;\na mí ni el sueño me quitan:\nyo puedo con la manada.",75,2,-1,91,"En la mano derecha",9,6,"aa",-1,0,-1,0,295,295,"1855","",0,"","","",1,0,0,[],""],["frenk_t1-n1856",5,"Áhi si alguno se disgusta\nporque te traté de amores,\ncon mi máusser no le temo\nni a San Juan de los Dolores.",78,2,3,91,"La canelera",0,4,"oe",5,0,-1,0,295,295,"1856","",0,"","","",1,0,0,[],""],["frenk_t1-n1857",5,"Ni el tiempo ni la distancia\nni el deseo de no verte;\npor ninguna circunstancia\nhe de dejar de quererte,\nporque te amo con constancia\ny soy fiel hasta la muerte.",79,2,4,91,"El Balajú; La morena",9,6,"ee",134,0,-1,0,295,295,"1857","",0,"","","",2,0,0,[],""],["frenk_t1-n1863",5,"Preso estoy, vida mía,\nporque te quiero,\ny yo sigo diciendo\nque por ti muero.",75,2,-1,91,"Estrofa sueltaj",6,4,"eo",-1,0,-1,0,296,296,"1863","",0,"","","",1,0,0,[],""],["frenk_t1-n1864",5,"A los presidios de Europa\nme mandan porque te olvide;\nme han de llevar, me han de traer\n¡qué capaz que yo te olvide!",75,2,-1,91,"Estrofa suelta",0,4,"ie",-1,0,-1,0,296,296,"1864","",0,"","","",1,0,0,[],""],["frenk_t1-n1865",5,"Prisionero por diez años,\nprisionero en un cuartel:\nsi es porque yo la quero,\nnada importa padecer.",75,2,-1,91,"La chaparrita",0,4,"e",-1,0,-1,0,296,296,"1865","",0,"","","",1,0,0,[],""],["frenk_t1-n1868",5,"Vida mía, por tus amores\nme quieren tirar a un fuerte;\nsi me tiran, es lo mismo;\ncompongo y vuelvo a quererte.",92,2,17,91,"Lucero de la mañana",0,4,"ee",134,0,-1,0,299,299,"1868","",0,"","","",1,0,0,[],""],["frenk_t1-n1869",5,"Chatita, por tus amores\nla ronda me lleva preso;\nanda a dormir sin cuidado,\nmañana se arregla eso.",75,2,-1,91,"Trigueñita; El enamorado",0,4,"eo",48,0,-1,0,299,299,"1869","",0,"","","",2,0,0,[],""],["frenk_t1-n1870",5,"Trigueñita, por tus amores\nla ronda me lleva preso;\nvoy, pero con mucho gusto:\nsi es por ti, nada vale eso.",100,2,25,91,"Trigueñita",0,4,"eo",48,0,-1,0,299,299,"1870","",0,"","","",1,0,0,[],""],["frenk_t1-n1871",5,"Güerita, por tus amores\npreso me lleva la ronda;\nno tengas cuidado, mi alma (güerita),\nque yo tengo quien me responda.",92,2,17,91,"El enamorado",3,4,"oa",182,0,-1,0,299,299,"1871","",0,"","","",1,0,0,[],""],["frenk_t1-n1872",5,"A mi corazón le han dado\nhiel y vinagre a beber,\ny con gusto lo ha tomado,\npor no dejar tu querer:\nyo lo que quiero es amarte,\nyo no quiero otra mujer.",75,2,-1,91,"Estrofa suelta",9,6,"e",20,0,-1,0,299,299,"1872","",0,"","","",2,0,0,[],""],["frenk_t1-n1874",5,"¡Ay de mí!, Llorona (Llorona),\nLlorona, te estoy amando;\nme han de quitar la querencia (Llorona)\npero de olvidarte, ¡cuándo!",75,2,-1,91,"La Llorona",3,4,"ao",33,0,-1,0,300,300,"1874","",0,"","","",4,0,0,[],""],["frenk_t1-n1876c",5,"Tengo una manzana de oro,\nmadúramela en el viento.\nDicen que me han de quitar\nde tu amor mi pensamiento:\nsólo que escriban en la agua\ny echen firmas en el viento.",75,2,-1,91,"' La azucena",9,6,"eo",94,0,-1,0,300,300,"1876c","",0,"","","",1,0,0,[],""],["frenk_t1-n1880",5,"Camino Real de Tepeji,\npiedra blanca de la esquina.\nMe aconsejan que te deje,\npero ¡adonde, perla fina!\nConmigo el amor se teje\ncomo la plata en la mina.",87,2,12,91,"La Malagueña; Corrido de Guanajuato, Zapateado; Estrofa suelta",9,6,"ia",11,0,-1,0,301,301,"1880","",0,"","","",1,0,0,[],""],["frenk_t1-n1881",5,"Éstos son los caracoles\nque brillaban en el mar;\nme aconsejan' que te olvide,\ny no te puedo olvidar.",82,2,7,91,"Los caracoles",0,4,"a",21,0,-1,0,301,301,"1881","",0,"","","",1,0,0,[],""],["frenk_t1-n1882",5,"Por andar de enamorado,\nla vida me va a costar;\nme aconsejan que te olvide,\ny no te puedo olvidar.",75,2,-1,91,"Mal correspondido",0,4,"a",21,0,-1,0,301,301,"1882","",0,"","","",1,0,0,[],""],["frenk_t1-n1883",5,"A mí el confesor me dijo (Llorona)\nque te olvide y no te quiera;\nsuspirando yo le dije (Llorona):\n“¡Ay, padre, si usted la viera!”",86,2,11,91,"La Llorona",3,4,"ea",44,0,-1,0,301,301,"1883","",0,"","","",1,0,0,[],""],["frenk_t1-n1884",5,"Dicen que ando muy errado,\nque despierte de mi sueño,\npero se lian equivocado,\nporque yo he de ser tu dueño.",75,2,-1,91,"Serenata huasteca",1,4,"eo",138,0,-1,0,301,301,"1884","",0,"","","",1,0,0,[],""],["frenk_t1-n1885",5,"Del jardín del aire vienes,\ny por eso te escogí;\nhora, aunque el mundo se oponga,\ntienes que ser para mí.",75,2,-1,91,"Del cielo cayó una rosa",0,4,"i",23,0,-1,0,301,301,"1885","",0,"","","",1,0,0,[],""],["frenk_t1-n1886",5,"Yo te seguiré amando (bien mío),\naunque les parezca mal,\nque no me han de hacer un templo\nni un palacio de cristal.",85,2,10,91,"Se acabaron mis paseadas",3,4,"a",1,0,-1,0,301,301,"1886","",0,"","","",1,0,0,[],""],["frenk_t1-n1887",5,"Dicen que estoy de malas\nporque te amo, vida mía;\nmienten los que tal dicen\nsi este gusto me quitaran,\nya no llovería.",75,2,-1,91,"La zamba",7,5,"ia",0,0,-1,0,301,301,"1887","",0,"","","",1,0,0,[],""],["frenk_t1-n1888",5,"Es tu amor el que me mata,\ny quieren que no te vea.\nNunca se irán las urracas,\npor más que las apedre[a]n;\nno le hace que duerman altas:\nechándoles maiz se apean.",75,2,-1,91,"El deseoso",9,6,"ea",-1,0,-1,0,302,302,"1888","",0,"","","",1,0,0,[],""],["frenk_t1-n1889",5,"¡Ay de mí!, Llorona (Llorona),\nLlorona, dame una estrella.\n¿Qué importa que digan (Llorona)\nque tú ya no eres doncella?",75,2,-1,91,"La Llorona",1,4,"ea",6,0,-1,0,302,302,"1889","",0,"","","",4,0,0,[],""],["frenk_t1-n1890",5,"Me dicen que eres casada,\nno importa, yo así te quiero;\nme agrada ser tu segundo,\nya que no fui tu primero.",88,2,13,91,"Estrofa suelta",0,4,"eo",38,0,-1,0,302,302,"1890","",0,"","","",1,0,0,[],""],["frenk_t1-n1891",5,"Blanca flor, azucenita,\nde los jardines de aldea,\nyo te quiero por bonita,\naunque digan que eres fea;\nmi gusto ¿quién me lo quita?,\npues yo he de seguir mi idea.",75,2,-1,91,"Estrofa suelta",9,6,"ea",54,0,-1,0,302,302,"1891","",0,"","","",1,0,0,[],""],["frenk_t1-n1892",5,"Si en mi pecho\nyo escribí tu nombre,\nnadie lo puede borrar,\naunque se sienta muy hombre.",77,2,2,91,"Estrofa suelta",3,4,"oe",220,0,-1,0,302,302,"1892","",0,"","","",1,0,0,[],""],["frenk_t1-n1895",5,"Tu papá será la arena,\ntu mamá será la cal,\ntus hermanos, los ladrillos\npara enladrillar el mar.",75,2,-1,91,"Los carretones; La enlutadita",0,4,"a",-1,0,-1,0,302,302,"1895","",0,"","","",1,0,0,[],""],["frenk_t1-n1896",5,"Y en la cumbre de un ocú\ncantaba una primavera,\ny le respondió el pijul\ndiciendo de esta manera:\n“Joven, queriéndome tú,\naunque tu mamá no quiera.”",79,2,4,91,"El Balajú",9,6,"ea",44,0,-1,0,302,302,"1896","",0,"","","",1,0,0,[],""],["frenk_t1-n1898",5,"Del cielo cayó un pañuelo (Llorona)\nclaveteado de alfileres;\naunque tu mamá no quiera (Llorona),\nmás tarde ha de ser mi suegra.",83,2,8,91,"La Llorona",3,4,"ea",-1,0,-1,0,303,303,"1898","",0,"","","",1,0,0,[],""],["frenk_t1-n1899",5,"Su mamá me dio\npolvos de rapé,\npero yo no puedo\nolvidar a usted.",75,2,-1,91,"El cojo",0,4,"e",-1,0,-1,0,303,303,"1899","",0,"","","",1,0,0,[],""],["frenk_t1-n1900",5,"Y yo sé que tus padres se enojan\nporque vengo a tus puertas a cantar;\nanda, diles que ya no se enojen,\nque a la noche te vengo a llevar.",82,2,7,91,"Vengo a ver unos ojos que tengo",3,4,"a",21,0,-1,0,303,303,"1900","",0,"","","",1,0,0,[],""],["frenk_t1-n1901",5,"Vente conmigo, prietita,\nvámonos a caminar;\naunque tus padres se enojen,\nyo te tengo que llevar.",75,2,-1,91,"La canelera",0,4,"a",21,0,-1,0,303,303,"1901","",0,"","","",1,0,0,[],""],["frenk_t1-n1902",5,"Hora que te vengo [a] ver\nno te vayas a enojar,\ny esta noche nos paseamos\ny aunque les parezca mal.",78,2,3,91,"La canelera",3,4,"a",-1,0,-1,0,303,303,"1902","",0,"","","",1,0,0,[],""],["frenk_t1-n1903",5,"Te lo juro por mi nombre,\nsi no me quieres hablar,\naunque tus padres no quieran,\nte he de amar y te he de amar.",75,2,-1,91,"A los ángeles del cielo",0,4,"a",21,0,-1,0,303,303,"1903","",0,"","","",1,0,0,[],""],["frenk_t1-n1904",5,"Uy, ja, ja,\nqué risa me da,\nporque en tu casa\nno me pueden ver.",75,2,-1,91,"La vieja presumida",3,4,"e",-1,0,-1,0,303,303,"1904","",0,"","","",1,0,0,[],""],["frenk_t1-n1905",5,"¿Hasta cuándo, trigueñita,\nse te mueve el corazón?\nA mí nada me importa\nque en tu casa no me queran;\nese tu papa y tu mama\na mí no me pueden ver.",75,2,-1,91,"Trigueñita",9,6,"e",-1,0,-1,0,303,303,"1905","",0,"","","",2,0,0,[],""],["frenk_t1-n1906",5,"Los de tu casa a mí no me quieren,\nlos de tu casa a mí no me pueden ver.\nElla llorando me dice:\n“Mas adrede lo he de hacer.\n¿Qué dices, nos retevamos\ny nos quitamos de padecer?”",78,2,3,91,"Al pie de un árbol",9,6,"e",20,0,-1,0,303,303,"1906","",0,"","","",1,0,0,[],""],["frenk_t1-n1907",5,"Dicen que los de tu casa\nninguno me puede ver:\ndiles que no batan la agua,\nque al cabo la han de beber.",75,2,-1,91,"Estrofa suelta",0,4,"e",20,0,-1,0,304,304,"1907","",0,"","","",1,0,0,[],""],["frenk_t1-n1908",5,"Anda, avísale a tu mama\nque no te ande regañando,\nque al cabo nos hemos de ir\ny se ha de quedar llorando.",75,2,-1,91,"La suegra",0,4,"ao",33,0,-1,0,304,304,"1908","",0,"","","",1,0,0,[],""],["frenk_t1-n1909",5,"¿De qué le sirve a tu mama\ny echarle tapia al corral,\nsi al cabo nos hemos de ir\npor la puerta principal?",75,2,-1,91,"La suegra",0,4,"a",1,0,-1,0,304,304,"1909","",0,"","","",1,0,0,[],""],["frenk_t1-n1910",5,"Anda y dile a tu mamá\nque por ti rondo en el barrio,\nque si ella pisa en el coro,\nyo bailo en el campanario.",75,2,-1,91,"Estrofa suelta, La suegra; Uy tara la la",0,4,"ao",-1,0,-1,0,304,304,"1910","",0,"","","",1,0,0,[],""],["frenk_t1-n1914",5,"En una hermosa mañana\nte conocí, linda mía,\ncon tus mejillas de grana,\ntus ojos con alegría:\ntú has de ser mi soberana,\naunque se enoje tu tía.",75,2,-1,91,"En una hermosa mañana",9,6,"ia",0,0,-1,0,304,304,"1914","",0,"","","",1,0,0,[],""],["frenk_t1-n1916",5,"Como que no tengo platas,\nno me quiere a mí tu madre;\n¡ay, qué suegras tan ingratas,\nque le hacen a uno desaires!\n¡Ay, qué paredes tan altas!,\n¡cómo no las tumba el aire!",75,2,-1,91,"El indio",9,6,"ae",-1,0,-1,0,305,305,"1916","",0,"","","",1,0,0,[],""],["frenk_t1-n1917",5,"En tu casa no me quieren,\nporque me vivo cantando;\nme dicen que soy mariachi\ny que no tengo pa cuándo\nmercarte el traje de novia,\nque el tiempo te estoy quitando.",75,2,-1,91,"No soy moncdita de oro",9,6,"ao",33,0,-1,0,305,305,"1917","",0,"","","",2,0,0,[],""],["frenk_t1-n1918",5,"En tu casa no me quieren\npor borracho y parrandero;\na nadie le cojo nada,\ngasto mi puro dinero.",75,2,-1,91,"Bonito San Juan del Río",0,4,"eo",38,0,-1,0,305,305,"1918","",0,"","","",2,0,0,[],""],["frenk_t1-n1920",5,"¡Ay!, Soledad, Soledad,\nSoledad para allá abajo,\nestando juntos los dos,\naunque pasemos trabajos.",75,2,-1,92,"La Petenera",0,4,"ao",-1,0,-1,0,306,306,"1920","",0,"","","",18,0,0,[],""],["frenk_t1-n1924",5,"Sentados juntos los dos,\ntenemos un desconsuelo;\nnos hemos de echar el velo,\nsólo que no quiera Dios,\no los ángeles del cielo\nnos dividan a los dos.",75,2,-1,92,"Estrofa suelta",9,6,"o",87,0,-1,0,306,306,"1924","",0,"","","",1,0,0,[],""],["frenk_t1-n1925",5,"Y que vuela, vuela, vuela,\nvuela, vuela, van volando;\nnos dejaremos de ver,\npero de querer, ¡pa cuando!",83,2,8,92,"La guacamaya",0,4,"ao",33,0,-1,0,306,306,"1925","",0,"","","",1,0,0,[],""],["frenk_t1-n1927",5,"Si tú me quieres, mi nena,\naunque no tengo temor,\nque me defiendan, morena,\ntus caricias y tu amor.",75,2,-1,92,"La Valentina",1,4,"o",72,0,-1,0,307,307,"1927","",0,"","","",1,0,0,[],""],["frenk_t1-n1929",5,"Despierta, bella sirena,\nque el agua nos quiere ahogar;\nya nos tiran con cadenas,\nqueriéndonos apartar;\n¡como que la ausencia fuera\nremedio para olvidar!",75,2,-1,92,"Estrofa suelta",9,6,"a",21,0,-1,0,307,307,"1929","",0,"","","",1,0,0,[],""],["frenk_t1-n1930",5,"Ya México está sitiado\nde piezas de artillería;\ntodo el mundo está enojado\nporque dicen que eres mía:\nhe de vivir a tu lado,\naunque les pese, alma mía.",81,2,6,92,"El huerfanito X",9,6,"ia",-1,0,-1,0,307,307,"1930","",0,"","","",1,0,0,[],""],["frenk_t1-n1931",5,"Bajo el volcán del oriente\nsembré una mata de arroz.\nEl que sea tu pretendiente\nsólo le pido a mi Dios;\nno le hace que hable la gente,\nsiendo gusto de los dos.",79,2,4,92,"Estrofa suelta",9,6,"o",87,0,-1,0,307,307,"1931","",0,"","","",1,0,0,[],""],["frenk_t1-n1932",5,"Soy como el agua del río,\nque derrumba paderones;\nsiendo el gusto de los dos,\nque renieguen los mirones.",75,2,-1,92,"El cuervo; El toro palomo",0,4,"oe",34,0,-1,0,307,307,"1932","",0,"","","",6,0,0,[],""],["frenk_t1-n1933",5,"Si porque nos amamos (cielito lindo)\ntienen envidia,\n¡mueran los envidiosos (cielito lindo),\nnuestro amor viva!",75,2,-1,92,"Cielito lindo",3,4,"ia",-1,0,-1,0,307,307,"1933","",0,"","","",1,0,0,[],""],["frenk_t1-n1934",5,"Marcianita encantadora,\nhaz un recuerdo de mí,\nde aquellas felices horas\nque contestamos allí.",90,2,15,93,"Marcianita",0,4,"i",23,0,-1,0,308,308,"1934","",0,"","","",2,0,0,[],""],["frenk_t1-n1935",5,"Si oyeras tocar violín\nen compañía de pistón,\nrecuerda que fui tu amante\npor las orillas de León.",75,2,-1,93,"Las mañanitas",0,4,"o",31,0,-1,0,308,308,"1935","",0,"","","",1,0,0,[],""],["frenk_t1-n1936",5,"Si oyeras tocar en arpa,\nhaz un recuerdo de mí,\nrecuerda que fui tu amante\ny en tus brazos me dormí.",75,2,-1,93,"Las mañanitas",0,4,"i",23,0,-1,0,308,308,"1936","",0,"","","",1,0,0,[],""],["frenk_t1-n1939",5,"El amor que tú me distes\nno digas que lo perdí:\naquí lo cargo presente\npara acordarme de ti.",83,2,8,93,"Estrofa suelta",0,4,"i",23,0,-1,0,308,308,"1939","",0,"","","",1,0,0,[],""],["frenk_t1-n1940",5,"Recuerda, morena mía,\nde aquella fresca mañana\nque en mis brazos te tenía\ncantándote en tu ventana.",75,2,-1,93,"Cielito, cielito azull",1,4,"aa",4,0,-1,0,308,308,"1940","",0,"","","",1,0,0,[],""],["frenk_t1-n1942",5,"Hace un año, ¿qué no recuerdas, Eulalia?,\nque te quise y te amé con locura;\nhace un año, bellísima criatura,\nque ando yo suspirando por ti.",85,2,10,93,"Eulalia",3,4,"i",-1,0,-1,0,309,309,"1942","",0,"","","",1,0,0,[],""],["frenk_t1-n1944",5,"Las mañanitas alegres\nque contigo yo pasé\nmientras Dios me diere vida\nnunca las olvidaré.",75,2,-1,93,"Las mañanitas’’",0,4,"e",77,0,-1,0,309,309,"1944","",0,"","","",1,0,0,[],""],["frenk_t1-n1945",5,"Entré al jardín y corté\nuna naranja madura;\npor Dios santo, que lloré\nlágrimas de sangre pura\ncuando de ti me acordé.",75,2,-1,93,"Estrofa suelta",7,5,"e",77,0,-1,0,309,309,"1945","",0,"","","",3,0,0,[],""],["frenk_t1-n1946",5,"Me ha dado la primavera\nmirtos, claveles y rosas,\ny con sonrisa hechicera\ntú me has dado muchas cosas\nque recordar no quisiera.",75,2,-1,93,"La huazanga",7,5,"ea",44,0,-1,0,309,309,"1946","",0,"","","",1,0,0,[],""],["frenk_t1-n1947",5,"Salías del templo un día (Llorona),\ncuando al pasar yo te vi;\nhermoso huipil llevabas (Llorona),\nque la Virgen te creí.",83,2,8,93,"La Llorona",3,4,"i",23,0,-1,0,309,309,"1947","",0,"","","",1,0,0,[],""],["frenk_t1-n1948",5,"¡Ay de mí, Llorona!,\nprendida llevaste al río\nuna guirnalda de rosas\nque en las ondas se durmió.",86,2,11,93,"La Llorona",5,4,"o",-1,0,-1,0,309,309,"1948","",0,"","","",35,0,0,[],""],["frenk_t1-n1949",5,"Cuán hermosa te vi, morena mía,\nla noche que pasabas para el templo,\ny la luna parece que sonreía,\ncomo yo de placer y de contento.",81,2,6,93,"Estrofa suelta",3,4,"eo",-1,0,-1,0,309,309,"1949","",0,"","","",1,0,0,[],""],["frenk_t1-n1957",5,"Recuerda que te indiqué\nque te amaba tiernamente;\nmi corazón te entregué;\npues debes tener presente\nque mi amor te declaré.",77,2,2,93,"Estrofa suelta",7,5,"e",77,0,-1,0,311,311,"1957","",0,"","","",1,0,0,[],""],["frenk_t1-n1958",5,"Al pie de un verde pirul,\ncuando ya moría el sol,\nte canté ‘’El sacamandú”,\nte juré mi fiel amor,\ny también juraste tú.",81,2,6,93,"El sacamandú",7,5,"u",73,0,-1,0,311,311,"1958","",0,"","","",1,0,0,[],""],["frenk_t1-n1959",5,"Una vez yo vi el infierno (¡ay, Llorona!)\ny otra vez el cielo vi:\ncuando me dijiste no (¡ay, Llorona!)\ny cuando me dijiste sí.",75,2,-1,93,"La Llorona",3,4,"i",23,0,-1,0,311,311,"1959","",0,"","","",1,0,0,[],""],["frenk_t1-n1960",5,"Y aunque cerraste los labios (Llorona)\npor no responder mi adiós,\ntus ojos con su mirar (¡ay Llorona!)\nme prometieron su amor.",83,2,8,93,"La Llorona",3,4,"o",-1,0,-1,0,311,311,"1960","",0,"","","",1,0,0,[],""],["frenk_t1-n1961",5,"Prietita linda, ¿te acuerdas\nque entre naranjos en flor,\npor allá en Montemorelos,\ncomenzamos nuestro amor?",75,2,-1,93,"Bonito Montemorelos",0,4,"o",72,0,-1,0,311,311,"1961","",0,"","","",1,0,0,[],""],["frenk_t1-n1962",5,"Voy a cortar esa rosa\ny a conservar esta flor,\npara acordarme de ti\ncuando me diste tu amor.",98,2,23,93,"Las mañanitas",0,4,"o",72,0,-1,0,311,311,"1962","",0,"","","",1,0,0,[],""],["frenk_t1-n1963",5,"Como reliquia sagrada\nguardo el botón perfumado\nque me diste enamorada\ny que acepté entusiasmado\ncomo prenda idolatrada.",76,2,1,93,"La azucena",7,5,"aa",49,0,-1,0,311,311,"1963","",0,"","","",1,0,0,[],""],["frenk_t1-n1964",5,"Tu retrato, prenda amada,\nes imagen de lo bello,\nque me diste entusiasmada;\npendiente lo traigo al cuello\ncomo reliquia sagrada.",77,2,2,93,"Estrofa suelta",7,5,"aa",49,0,-1,0,311,311,"1964","",0,"","","",1,0,0,[],""],["frenk_t1-n1965",5,"Te conocí en la ribera,\nrecostada entre las flores,\ny abrazados en la arena\nhubo una historia de amores.",86,2,11,93,"La Llorona",0,4,"oe",5,0,-1,0,311,311,"1965","",0,"","","",1,0,0,[],""],["frenk_t1-n1966",5,"Las nubes las lleva el viento,\nmis ilusiones con ellas;\nme siento alegre y contento:\nson testigo las estrellas\nque fuiste mía un momento.",81,2,6,93,"La leva",7,5,"eo",94,0,-1,0,311,311,"1966","",0,"","","",1,0,0,[],""],["frenk_t1-n1967",5,"Cuando a solas me veías\nya no sabías ni qué hacer,\nsin hablar ya me entendías;\nlodo se te iba en poner\ntus manos sobre las mías.",83,2,8,93,"El gavilancito",7,5,"ia",214,0,-1,0,312,312,"1967","",0,"","","",1,0,0,[],""],["frenk_t1-n1969a",5,"Con pasión me arrodillé,\nen la tarde fui hasta el parque;\n¡cómo no fuera a adorarte,\nQue hasta a un santo le recé\noraciones para amarte’",81,2,6,93,"El sacamandú",7,5,"ae",8,0,-1,0,312,312,"1969a","",0,"","","",1,0,0,[],""],["frenk_t1-n1970",5,"La tarde estaba lluviosa,\ntriste me salí pensando;\nme puse a considerar\nsi me estabas esperando,\nque yo no pude llegar\nporque estaba lloviznando.",83,2,8,93,"Estrofa suelta",9,6,"ao",33,0,-1,0,312,312,"1970","",0,"","","",1,0,0,[],""],["frenk_t1-n1971",5,"Dos besos llevo en el alma (Llorona)\nque no se apartan de mí:\nel último de mi madre (Llorona)\ny el primero que te di,",75,2,-1,93,"La Llorona; La Petenera; Petrona",3,4,"i",23,0,-1,0,312,312,"1971","",0,"","","",1,0,0,[],""],["frenk_t1-n1972",5,"Aquel beso que me diste\nno se me puede olvidar;\ncada vez que lo recuerdo\nganas de llorar me dan.",75,2,-1,93,"A los ángeles del cielo",0,4,"a",-1,0,-1,0,312,312,"1972","",0,"","","",1,0,0,[],""],["frenk_t1-n1973",5,"De mi tierra yo me acuerdo\ncuando me ponía a cantar,\ny los besos que me dabas\nen medio del platanar.",75,2,-1,93,"En busca de Margarita",0,4,"a",21,0,-1,0,313,313,"1973","",0,"","","",1,0,0,[],""],["frenk_t1-n1974",5,"Sabrosos los capulines\nque se dan en tu huerta,\ny más sabrosos los besos\nque me dabas en la puerta.",92,2,17,93,"El huizache",0,4,"ea",267,0,-1,0,313,313,"1974","",0,"","","",1,0,0,[],""],["frenk_t1-n1975",5,"En la tierra de Oaxaca,\ncierta tarde encantadora,\nme diste un beso teliuano\nbajo de un palo de rosa.",75,2,-1,93,"La Zandunga",0,4,"oa",-1,0,-1,0,313,313,"1975","",0,"","","",1,0,0,[],""],["frenk_t1-n1976",5,"Con un beso que me diste\nme entregaste el corazón\ny sonriendo me dijiste:\n“Yo seré tu adoración”.",75,2,-1,93,"Un beso de amor",1,4,"o",31,0,-1,0,313,313,"1976","",0,"","","",1,0,0,[],""],["frenk_t1-n1977",5,"Esos labios me besaron,\nlos que adoro de verdad;\nesos ojos me miraron\ndándome felicidad.",75,2,-1,93,"La tixtleca",1,4,"a",16,0,-1,0,313,313,"1977","",0,"","","",1,0,0,[],""],["frenk_t1-n1978",5,"De los besos que me diste\ntodavía tengo el sabor;\nde aquello que me dijiste\nno te he guardado rencor:\naunque no me lo cumpliste,\ntodavía te tengo amor.",77,2,2,93,"La Malagueña",9,6,"o",72,0,-1,0,313,313,"1978","",0,"","","",1,0,0,[],""],["frenk_t1-n1979",5,"Todavía tengo recuerdos\nde nuestra gloria pasada,\nde los besos que me diste\ncon tu boquita agraciada\ny tu palabra sagrada.",77,2,2,93,"Estrofa suelta",7,5,"aa",49,0,-1,0,313,313,"1979","",0,"","","",1,0,0,[],""],["frenk_t1-n1980",5,"Cada vez que cae la tarde,\nen vez de llorar me río,\nrecordando los besitos\nque me dabas junto al río,\ncon la boquita temblando:\npobrecita, tendrías frío.",75,2,-1,93,"Estrofa suelta",9,6,"io",3,0,-1,0,313,313,"1980","",0,"","","",4,0,0,[],""],["frenk_t1-n1981",5,"Yo como niño travieso\nllegué a tu cama esparcida,\ny acomodada en el centro,\nal encontrarte dormida,\nte recordé con un beso.",81,2,6,93,"El triunfo",7,5,"eo",-1,0,-1,0,313,313,"1981","",0,"","","",1,0,0,[],""],["frenk_t1-n1983",5,"Al pasar por tu ventana\nme tirastes un limón,\nel limón me dio en la cara\ny el zumo en el corazón.",75,2,-1,93,"Estrofa suelta, Fermina; Limonci Mariquita; La morenita",0,4,"o",31,0,-1,0,314,314,"1983","",0,"","","",8,0,0,[],""],["frenk_t1-n1984",5,"Una vez que te dije\nque eras bonita\nse te puso la cara\ncolor adi ta.",75,2,-1,93,"La bamba",6,4,"a",-1,0,-1,0,314,314,"1984","",0,"","","",6,0,0,[],""],["frenk_t1-n1986",5,"Te visité, mi vida,\nsalió tu agüela,\nno supo la tontuela\nque iba por verte.",75,2,-1,93,"Estrofa suelta",6,4,"ee",-1,0,-1,0,314,314,"1986","",0,"","","",1,0,0,[],""],["frenk_t1-n1987",5,"A las ocho me dio sueño,\na las nueve me dormí,\ny a las dos de la mañana\ndesperté pensando en ti.",75,2,-1,93,"El frijolito",0,4,"i",23,0,-1,0,314,314,"1987","",0,"","","",1,0,0,[],""],["frenk_t1-n1990",5,"Anoche y anoche\ny al amanecer\nsoñé, vida mía,\nque tú habías de ser.",83,2,8,93,"La Malagueña euricna",0,4,"e",20,0,-1,0,315,315,"1990","",0,"","","",2,0,0,[],""],["frenk_t1-n1991",5,"Anoche y anoche\ny en la madrugada\nsoñé, vida mía,\nque contigo estaba.",75,2,-1,93,"El cuervo; La malagueña curreña",0,4,"aa",-1,0,-1,0,316,316,"1991","",0,"","","",2,0,0,[],""],["frenk_t1-n1992",5,"Yo te soñé recostada\nen una cama de flores,\ny que estabas extasiada\nrecibiendo los olores\nde Ja brisa perfumada.",79,2,4,93,"La Rosita; Estrofa suelta",7,5,"aa",49,0,-1,0,316,316,"1992","",0,"","","",1,0,0,[],""],["frenk_t1-n1996a",5,"Agárrese de la reata,\nque ya el hilo reventó;\nhasta que encontró una chata\ncomo la deseaba yo.",75,2,-1,94,"Costeña; Estrofa suelta",1,4,"o",2,0,-1,0,320,320,"1996a","",0,"","","",1,0,0,[],""],["frenk_t1-n1997",5,"Bonitos son los jardines\ncon sus matizadas flores,\npero más bonita es\nla dueña de mis amores.",75,2,-1,94,"Cuatro esquinas ¡.’ene un catre; Estrofa suelta I",0,4,"oe",5,0,-1,0,320,320,"1997","",0,"","","",1,0,0,[],""],["frenk_t1-n2000",5,"Es mi niñil muy hermosa,\ny de eso no hay que dudar;\nparece una blanca rosa:\nsu aroma quiero aspirar.",75,2,-1,94,"lis in¡ niña muy hermosa",1,4,"a",21,0,-1,0,321,321,"2000","",0,"","","",1,0,0,[],""],["frenk_t1-n2001",5,"Ya los arrieros se van,\ny yo que los voy siguiendo;\n¡ay, qué buena está mi amor,\ny más que se irá poniendo!",75,2,-1,94,"Los arrieiosJ",0,4,"eo",52,0,-1,0,321,321,"2001","",0,"","","",2,0,0,[],""],["frenk_t1-n2002",5,"El toro de mi compadre\ntrae el cuero trasherrao;\n¡ay, qué buena está mi ahijada!,\n¿pa qué la habré bautizao?",86,2,11,94,"El arreo",0,4,"ao",98,0,-1,0,321,321,"2002","",0,"","","",1,0,0,[],""],["frenk_t1-n2004",5,"Es muy bonita mi chaparrita\ncuando ella pasa por aquí;\ntodos le dicen la Virgencita,\nla de los labios de rubí.",75,2,-1,94,"Las alteñitas",3,4,"i",23,0,-1,0,321,321,"2004","",0,"","","",2,0,0,[],""],["frenk_t1-n2005",5,"¡Qué linda la Sanmarqueña!\nquedó niña con honor;\ntiene en sí tan raro encanto,\nque aun con llanto inspira amor.",75,2,-1,94,"La Sanmarqueña",0,4,"o",72,0,-1,0,321,321,"2005","",0,"","","",2,0,0,[],""],["frenk_t1-n2006",5,"Bonitas Conchitas\ncolor de azafrán,\nbonita muchacha\nes Conchita Durán.",85,2,10,94,"Las Conchitas",0,4,"a",147,0,-1,0,321,321,"2006","",0,"frenk_t4","","",12,0,0,[],""],["frenk_t1-n2007",5,"Bonitas Conchitas\ncolor de estandarte,\nbonita muchacha\nes Clotilde Quirarte.",75,2,-1,94,"Las Conchitas",0,4,"ae",8,0,-1,0,321,321,"2007","",0,"frenk_t4","","",12,0,0,[],""],["frenk_t1-n2017",5,"Es delgada y chaparrita,\nde figura angelical,\ntiene un lunar en la boca\npara más atormentar.",75,2,-1,94,"Amorcito consentido",0,4,"a",-1,0,-1,0,323,323,"2017","",0,"","","",1,0,0,[],""],["frenk_t1-n2018",5,"¡Ay, qué bien me huele a lima!\n¡Qué cerca estará la mata!\nA que nadie me adivina\ncuál de éstas será mi chata:\nesa del peinado chulo,\nde los aretes de plata.",75,2,-1,94,"La lima; La sandía; Estrofa suelta",9,6,"aa",74,0,-1,0,323,323,"2018","",0,"","","",1,0,0,[],""],["frenk_t1-n2019",5,"¡Qué bonitos ojos chinos!,\npor ninguno los fereo.\nA que usted no me adivina\ncuál de ésas es mi recreo:\nla que huele a piña fresca,\no la que huele a poleo.",75,2,-1,94,"La sandía",9,6,"eo",66,0,-1,0,323,323,"2019","",0,"","","",1,0,0,[],""],["frenk_t1-n2020",5,"—De las tres que vienen áhi\n¿cuál te gusta, valedor?\n—Esa del vestido rojo\nme parece la mejor.",75,2,-1,94,"De las tres que vienen áhi",0,4,"o",72,0,-1,0,323,323,"2020","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t1-n2021",5,"Cuatro palomas volaron\npara el árbol del pirul;\nvolando ellas decían:\n“La que a mí me trae en pena\nes la del vestido azul.”",77,2,2,94,"Estrofa suelta",7,5,"u",545,0,-1,0,323,323,"2021","",0,"","","",1,0,0,[],""],["frenk_t1-n2022",5,"Soy el gavilán alado,\nhoy me hallo en esta región;\nno soy poeta declarado,\nlo digo sin pretensión;\nla del traje combinado\nme ha robado el corazón.",83,2,8,94,"El siquisirí",9,6,"o",31,0,-1,0,323,323,"2022","",0,"","","",1,0,0,[],""],["frenk_t1-n2023",5,"Cuando oigas cantar el guaco\narriba de ese barranco,\n¡qué bonita señorita\nesa del vestido blanco!",75,2,-1,94,"El guaco",0,4,"ao",303,0,-1,0,323,323,"2023","",0,"","","",2,0,0,[],""],["frenk_t1-n2025",5,"Bonita la Sanmarqueña,\nesa del vestido verde;\nle voy a mandar una carta,\na ver si me la devuelve.",75,2,-1,94,"La Sanmarqueña",0,4,"ee",-1,0,-1,0,324,324,"2025","",0,"","","",1,0,0,[],""],["frenk_t1-n2026c",5,"De las aves del campo\nme gusta el cuervo,\nporque entre los colores\ndistingo el negro;\n¡ay!, eso consiste\nen que el ángel que adoro (cielito lindo)\nde negro viste.",75,2,-1,94,"Cielito lindo",4,7,"ie",153,0,-1,0,324,324,"2026c","",0,"","","",3,0,0,[],""],["frenk_t1-n2031",5,"Las morenas son muy dulces,\nmás dulces que un caramelo,\ny yo, como soy goloso,\npor una morena muero.",83,2,8,94,"Estrofa sueltaj",0,4,"eo",-1,0,-1,0,325,325,"2031","",0,"","","",1,0,0,[],""],["frenk_t1-n2032",5,"La quiero, porque es morena,\nporque es morena la quiero;\nramito de yerbabuena\nque crece bajo mi alero,\npara curarme una pena,\nporque siento que me muero.",86,2,11,94,"El huasteco enamorado",9,6,"eo",38,0,-1,0,325,325,"2032","",0,"","","",1,0,0,[],""],["frenk_t1-n2033",5,"La quiero porque es trigueña,\n¿para qué lo he de negar?\nEs purita tampiqueña,\nde esas que saben amar.",77,2,2,94,"El lunarcito",1,4,"a",21,0,-1,0,325,325,"2033","",0,"","","",1,0,0,[],""],["frenk_t1-n2034",5,"La mujer que yo quiero\nes una morena,\nporque baila “La bamba\"\nque es cosa buena.",79,2,4,94,"La bamba",6,4,"ea",59,0,-1,0,325,325,"2034","",0,"","","",2,0,0,[],""],["frenk_t1-n2035",5,"Mi negrita es muy bonita,\ntrigueña pero rosada,\ncon sus chinos en la frente\ny su lunar en la cara.",75,2,-1,94,"Que comienzo, que comienzo",0,4,"aa",-1,0,-1,0,325,325,"2035","",0,"","","",1,0,0,[],""],["frenk_t1-n2036",5,"Por debajo de la arena\ncorre el agua y se reposa,\npor esa coloradita,\ncachetes color de rosa.",101,2,26,94,"A mi chata",0,4,"oa",63,0,-1,0,325,325,"2036","",0,"","","",6,0,0,[],""],["frenk_t1-n2037",5,"Orilla de un arroyuelo\nme paseaba una bonita;\nésa es alta y delgadita\ny el corazón muy alegre.",83,2,8,94,"San Francisco",5,4,"ee",-1,0,-1,0,325,325,"2037","",0,"","","",1,0,0,[],""],["frenk_t1-n2038",5,"¡Qué vaquita tan bonita\ntiene la de ahí enfrente!\nSu cintura delgadita,\nbien hecho su permanente,\ncomo luz de una estrellita,\nla que sale al Oriente.",83,2,8,94,"La morena",9,6,"ee",15,0,-1,0,325,325,"2038","",0,"","","",1,0,0,[],""],["frenk_t1-n2039",5,"Tiene mi prenda querida\nsus chinitos en la frente:\nparece caña florida\nsembrada en tierra caliente.",75,2,-1,94,"Estrofa suelta",1,4,"ee",15,0,-1,0,326,326,"2039","",0,"","","",1,0,0,[],""],["frenk_t1-n2040",5,"Un pino de los Amóles\nno tiene tantos piñones\ncomo la niña tiene\nen el pelo caracoles.",75,2,-1,94,"Baile de la muñeca",0,4,"oe",-1,0,-1,0,326,326,"2040","",0,"","","",1,0,0,[],""],["frenk_t1-n2041",5,"Dicen que el chile maduro\ntiene dulce la puntita,\ntambién mi chinita tiene\ndulce su bella boquita.",79,2,4,94,"Los chiles verdes",0,4,"ia",50,0,-1,0,326,326,"2041","",0,"","","",2,0,0,[],""],["frenk_t1-n2042",5,"Dicen que el chile maduro\ntiene dulce el corazón,\ntambién mi chinita tiene\ndulce su conversación.",75,2,-1,94,"Los chiles verdes",0,4,"o",31,0,-1,0,326,326,"2042","",0,"","","",2,0,0,[],""],["frenk_t1-n2049",5,"Cuando voy por esos campos\ny me fijo en los laureles,\nparece que estoy mirando\naquellos ojitos verdes.",75,2,-1,94,"Ojitos verdes",0,4,"ee",-1,0,-1,0,327,327,"2049","",0,"","","",1,0,0,[],""],["frenk_t1-n2052",5,"Los ejotes son la vaina\ndel frijol enredador;\nesos ojitos tan negros\npertenecen a mi amor.",75,2,-1,94,"Las chivarras",0,4,"o",72,0,-1,0,327,327,"2052","",0,"","","",1,0,0,[],""],["frenk_t1-n2055",5,"Qué bonita chaparrita\nde ojitos negros chinitos;\nla quiero por seriecita\ny por sus negros ojitos.",75,2,-1,94,"Ojitos negros chinitos",1,4,"io",254,0,-1,0,327,327,"2055","",0,"","","",5,0,0,[],""],["frenk_t1-n2057",5,"Un pintor pintó una rosa\ny en medio dos clavelitos,\npero no hay pintor que pinte\nlo negro de sus ojitos.",75,2,-1,94,"Cielo azul, cielo nublado",0,4,"io",254,0,-1,0,328,328,"2057","",0,"","","",2,0,0,[],""],["frenk_t1-n2059",5,"Por debajo de la arena\ncorre el agua y se detiene;\n¡ay, qué mirar de morena,\ncon esos ojos que tiene!",75,2,-1,94,"Ya no subo a la lomita",1,4,"ee",70,0,-1,0,328,328,"2059","",0,"","","",6,0,0,[],""],["frenk_t1-n2060",5,"Una guacamaya pinta\nle dijo a una verde, verde:\n“¡Ay, qué ojitos de señora,\nparece que ya se duerme!”",75,2,-1,94,"La guacamaya; Estrofa suelta",0,4,"ee",-1,0,-1,0,328,328,"2060","",0,"frenk_t4","","",8,0,0,[],""],["frenk_t1-n2062",5,"Me gustan sus ojos negros\ny su modo de mirar,\npero más loco me vuelvo\ncon su modo de bailar.",75,2,-1,94,"La coculense",0,4,"a",21,0,-1,0,328,328,"2062","",0,"","","",1,0,0,[],""],["frenk_t1-n2063",5,"Esa niña tiene ojos,\ny esos ojos tienen niña,\ny la niña y esos ojos\nson las niñas de mis ojos.",75,2,-1,94,"Estrofa suelta",5,4,"oo",-1,0,-1,0,328,328,"2063","",0,"","","",1,0,0,[],""],["frenk_t1-n2064",5,"Quiero decir y no quiero\ndecir a quién quiero bien,\nporque si digo a quién quiero,\nya van a saber a quién,\ny eso es lo que yo no quiero,\ndecir a quién quiero bien.",79,2,4,94,"El Balajú; La Cecilia; El deseoso; El pajaro carpintero; Estrofa suelta",9,6,"e",242,0,-1,0,328,328,"2064","",0,"","","",1,0,0,[],""],["frenk_t1-n2065",5,"Subí a Ja torre del moro\ncon gran gusto y alegría,\ny ahí me encontré un tesoro\nque de este modo decía:\nera el nombre de María,\ny escrito con letras de oro.",75,2,-1,94,"La tarasca; La morena",9,6,"oo",85,0,-1,0,329,329,"2065","",0,"","","",1,0,0,[],""],["frenk_t1-n2066",5,"Si las flores del campo\nfuesen Marías,\nyo las iría a cortar\ntodos los días.",75,2,-1,94,"Si las flores del campo",6,4,"ia",214,0,-1,0,329,329,"2066","",0,"","","",1,0,0,[],""],["frenk_t1-n2067",5,"El orgullo que yo tengo\nsólo mi Dios me lo quita,\ny pa que acaben de hablar,\nvoy a echarme otra copita\npor una joven que yo amo,\nque se llama Mariquita.",103,2,28,94,"Qué corazón tan alegre",9,6,"ia",50,0,-1,0,329,329,"2067","",0,"","","",1,0,0,[],""],["frenk_t1-n2068",5,"Por esta calle derecha\ntengo un diamante escondido:\nGraciela lleva por nombre\ny Acuña por apellido.",84,2,9,94,"Estrofa suelta",0,4,"io",101,0,-1,0,329,329,"2068","",0,"","","",8,0,0,[],""],["frenk_t1-n2069",5,"Adelita se llama la joven\na quien yo quiero y no puedo olvidar;\nen el mundo yo tengo una rosa,\ny con el tiempo la voy a cortar.",75,2,-1,94,"La Adelita",3,4,"a",21,0,-1,0,329,329,"2069","",0,"","","",1,0,0,[],""],["frenk_t1-n2070",5,"Adelita se llama la ingrata,\nla que era dueña de todo mi querer;\nnunca pienses que llegue a olvidarla\nni a cambiarla por otra mujer.",75,2,-1,94,"La Adelita",3,4,"e",20,0,-1,0,329,329,"2070","",0,"","","",1,0,0,[],""],["frenk_t1-n2071",5,"Traigo en el pecho una hacienda\ncuyo nombre es Esperanza,\ny ha menester sin tardanza\nun mayordomo que entienda.",75,2,-1,94,"Estrofa suelta",11,4,"ea",159,0,-1,0,329,329,"2071","",0,"","","",1,0,0,[],""],["frenk_t1-n2072",5,"Cuatro nombres con R\ntiene mi prenda:\nRosario y Rosalía,\nRosa, Rosen da.",79,2,4,94,"El pájaro cú",6,4,"a",-1,0,-1,0,329,329,"2072","",0,"","","",3,0,0,[],""],["frenk_t1-n2073",5,"Once letras, puras erres,\nlo manifiestan mis sueños:\nRosa, Rosita, Rosaura,\nregaditas de sereno,\neres erre, rey de rubias,\neres Rafaelita de mis sueños.",83,2,8,94,"Estrofa suelta",9,6,"eo",-1,0,-1,0,329,329,"2073","",0,"","","",1,0,0,[],""],["frenk_t1-n2079",5,"Esta casa está medida\ncon cien varas de listón.\nen cada esquina una rosa\ny en medio mi corazón.",75,2,-1,94,"Los papaquis; Las mañanitas; Estrofa suelta",0,4,"o",31,0,-1,0,331,331,"2079","",0,"","","",1,0,0,[],""],["frenk_t1-n2080",5,"Por esta calle derecha\ncorre el agua y nacen flores,\npor eso le tengo puesta\n“calle real de mis amores”.",75,2,-1,94,"María del Carmen; Estrofa suelta",0,4,"oe",5,0,-1,0,331,331,"2080","",0,"","","",8,0,0,[],""],["frenk_t1-n2081",5,"Que Dios bendiga esta casa\ny el albañil que la hizo,\nque por dentro está la gloria\ny por fuera el paraíso.",79,2,4,94,"El siquisirí",0,4,"io",92,0,-1,0,331,331,"2081","",0,"","","",1,0,0,[],""],["frenk_t1-n2082",5,"En la puerta de mi casa\ntengo una maceta de oro:\ntodos dicen que es de albahaca,\ny es el ángel que yo adoro.",85,2,10,94,"Estrofa suelta",0,4,"oo",85,0,-1,0,331,331,"2082","",0,"","","",24,0,0,[],""],["frenk_t1-n2083",5,"En la puerta de esta casa\nestá una vela prendida;\nque aquí está mi corazón\ny adentro está mi prometida.",82,2,7,94,"Los papaquis",3,4,"ia",37,0,-1,0,331,331,"2083","",0,"","","",1,0,0,[],""],["frenk_t1-n2084",5,"Entre a la fuente y corté\nun buqué de bellas flores;\nentre de ellas me encontre\nla dueña de mis amores.",90,2,15,94,"Cuatro esquinas tiene un catre; Estrofa suelta",1,4,"oe",-1,0,-1,0,331,331,"2084","",0,"","","",1,0,0,[],""],["frenk_t1-n2087",5,"La tumba que está en mi pecho\nes promontorio de flores;\nes un primoroso lecho,\nprecioso nido de amores\npara el ángel que yo acecho.",75,2,-1,94,"Estrofa suelta",7,5,"eo",60,0,-1,0,332,332,"2087","",0,"","","",1,0,0,[],""],["frenk_t1-n2088",5,"Ln el cielo hay una estrella\nque me llama la atención,\nen.................................. hay un muchacho\nque me robó el corazón.",75,2,-1,94,"Estrofa suelta",0,4,"o",31,0,-1,0,332,332,"2088","",0,"","","",1,0,0,[],""],["frenk_t1-n2089",5,"¡Policía, policial,\nno se lleve ese ladrón;\nmejor llévese a mi novio,\nque me robó el corazón.",75,2,-1,94,"Estrofa suelta; Autógrafo",0,4,"o",31,0,-1,0,332,332,"2089","",0,"","","",1,0,0,[],""],["frenk_t1-n2092a",5,"Una flecha en el aire\ntiró Cupido;\nél la tiró jugando (cielito lindo),\ny a mí me ha herido.",75,2,-1,94,"Cielito lindo",3,4,"io",101,0,-1,0,332,332,"2092a","",0,"","","",2,0,0,[],""],["frenk_t1-n2093c",5,"Cupido, como traidor,\nquitarme la vida trata;\nyo le pido por favor\nque la espada sea de plata,\npara morirme de amor\nen los brazos de mi chata.",75,2,-1,94,"El Cupido; El Balajú; Los chiles verdes; El pájaro carpintero; Estrofa suelta",9,6,"aa",74,0,-1,0,333,333,"2093c","",0,"","","",2,0,0,[],""],["frenk_t1-n2094a",5,"¡Ay, cielo, con qué dolor\nse queja un aborrecido!\n“En la cárcel del amor\npreso me tiene Cupido.\"",83,2,8,94,"Estrofa suelta",1,4,"io",101,0,-1,0,333,333,"2094a","",0,"","","",2,0,0,[],""],["frenk_t1-n2096",5,"Soy el hombre que decía\nque nunca se apasionaba,\nhasta que por fin un día\nuna mujer se acercaba,\ndespertando el alma mía.",77,2,2,94,"La Malagueña",7,5,"ia",0,0,-1,0,333,333,"2096","",0,"","","",1,0,0,[],""],["frenk_t1-n2097",5,"Al mismo Dios desafío\nque me presente otro ser\ncomo el ser que amor es\ncomo esa hermosa mujer\ncuyas caricias ansio.",76,2,1,94,"Estrofa suelta",7,5,"ao",-1,0,-1,0,333,333,"2097","",0,"","","",2,0,0,[],""],["frenk_t1-n2098",5,"De sostener lo que digo\nse llegará la ocasión;\nque ese amor será testigo\nde este amable corazón,\nque suspira sin abrigo,\nbuscando su salvación.",75,2,-1,94,"Estrofa sueltaj",9,6,"o",31,0,-1,0,334,334,"2098","",0,"","","",1,0,0,[],""],["frenk_t1-n2101",5,"Cuando el sol por el Oriente\nasoma sus rayos de oro,\nse me hace clara y presente\nesa joven que yo adoro,\nque siempre existe en mi mente.",77,2,2,94,"Estrofa sueltaj",7,5,"ee",15,0,-1,0,334,334,"2101","",0,"","","",1,0,0,[],""],["frenk_t1-n2102",5,"Dicen que de tanto amar\nsuele nacer el olvido;\npues digo en particular:\nyo no he podido olvidar\na un amor que yo he querido.",75,2,-1,94,"Estrofa sueltaj",7,5,"io",101,0,-1,0,334,334,"2102","",0,"","","",1,0,0,[],""],["frenk_t1-n2104",5,"Si la prenda que yo estimo\nse me llega a malograr,\nme botaría a los abismos\no me arrojaría a la mar\no me mataría yo mismo\no me mandaría matar.",83,2,8,94,"Zapateado, La morena",9,6,"a",21,0,-1,0,334,334,"2104","",0,"","","",1,0,0,[],""],["frenk_t1-n2105",5,"Pues me gusta la levita,\naunque me cueste morir,\npor una linda güerita,\nque será mi porvenir,\nmi gusto no me lo quita.",77,2,2,94,"La leva",7,5,"ia",50,0,-1,0,334,334,"2105","",0,"","","",1,0,0,[],""],["frenk_t1-n2106",5,"Voj a echar la despedida,\nyo la echara y no la diera;\nen siendo por mi negrita,\naunque me muera, me muera.",75,2,-1,94,"Estrofa suelta",0,4,"ea",44,0,-1,0,334,334,"2106","",0,"","","",1,0,0,[],""],["frenk_t1-n2107",5,"Hay una prenda querida\nque ha de ser de mi familia,\nque ha de ser la consentida,\nporque mi pasión concilia;\ngustoso daría la vida\npor el amor de Cecilia.",76,2,1,94,"La Cecilia’",9,6,"ia",-1,0,-1,0,335,335,"2107","",0,"","","",1,0,0,[],""],["frenk_t1-n2108",5,"Triste, triste\nmi corazón estaría\npor una joven que yo amo,\nque se llama'Rosalía.",75,2,-1,94,"Las campanitas",3,4,"ia",0,0,-1,0,335,335,"2108","",0,"frenk_t4","","",3,0,0,[],""],["frenk_t1-n2109",5,"Siento el alma que se muere\ny el corazón me palpita,\ny es tan sólo por Juanita,\nla que no sé si me quiere.",83,2,8,94,"La Juanita",11,4,"ee",115,0,-1,0,335,335,"2109","",0,"","","",1,0,0,[],""],["frenk_t1-n2110",5,"Una vez no más la vide\ny no la [he] vuelto a mirar;\nno sé si de mí se acuerde\ncomo yo me he de acordar.",95,2,20,94,"La chuparrosa",0,4,"a",21,0,-1,0,335,335,"2110","",0,"","","",1,0,0,[],""],["frenk_t1-n2111",5,"Una potente pasión\ndentro de mi alma se oculta,\ny le dice al corazón:\n“Lo que más se dificulta\nse ama con más atención”.",75,2,-1,94,"Estrofa suelta",7,5,"o",31,0,-1,0,335,335,"2111","",0,"","","",1,0,0,[],""],["frenk_t1-n2112",5,"¡Ay, cascabelito de oro!,\n¡Ay, cascabel ito de plata!\nLa prenda que más adoro\nes la que más me mata.",79,2,4,94,"El cascabel",1,4,"aa",74,0,-1,0,335,335,"2112","",0,"","","",1,0,0,[],""],["frenk_t1-n2114",5,"Dime, hermanito, ¿cómo hiciera yo\npara cuidar un amor (válgame Dios)?\nPresa me tiene el alma,\ncautivo mi corazón.",78,2,3,94,"El brinco",3,4,"o",-1,0,-1,0,335,335,"2114","",0,"","","",1,0,0,[],""],["frenk_t1-n2115",5,"A mis amores persigo\nhasta no ver si los venzo;\ncuando yo busque el abrigo\nsiempre me verás silencio,\nmuy triste y muy pensativo.",75,2,-1,94,"El huerfanito",7,5,"io",-1,0,-1,0,336,336,"2115","",0,"","","",1,0,0,[],""],["frenk_t1-n2116",5,"Untt paloma al volar\nllevaba en el pico un hilo;\nlo pedí para coser\neste corazón herido.",79,2,4,94,"El palomo",0,4,"io",-1,0,-1,0,336,336,"2116","",0,"","","",1,0,0,[],""],["frenk_t1-n2117",5,"Águila que vas volando\ny en el pico llevas hilo,\ndámelo para curar\neste corazón herido.",75,2,-1,94,"Estrofa suelta",0,4,"io",-1,0,-1,0,336,336,"2117","",0,"","","",10,0,0,[],""],["frenk_t1-n2118",5,"El amor es un fuego,\nme ha consumido;\nquiero morir amando\na esta trigueña.",75,2,-1,94,"Estrofa suelta",6,4,"ea",-1,0,-1,0,336,336,"2118","",0,"","","",3,0,0,[],""],["frenk_t1-n2123",5,"Al cortar un girasol\nse me rodeó una ramita;\n¿qué cosa será el amor (chaparrita de mi vida),\nque hasta el sueño se me quita?",75,2,-1,94,"vida), que hasta el sueño se me quita? [Qué milagro, chaparrita",3,4,"ia",50,0,-1,0,336,336,"2123","",0,"","","",1,0,0,[],""],["frenk_t1-n2124",5,"Todos echan despedida,\npero no como la mía;\nen la palma de la mano\ntraigo el amor de María.",83,2,8,94,"La garbosa",0,4,"ia",0,0,-1,0,337,337,"2124","",0,"","","",4,0,0,[],""],["frenk_t1-n2125",5,"Ni como, ni bebo,\nni ceno tampoco,\nporque sus amores\nme traen medio loco.",79,2,4,94,"Los borrachos",0,4,"oo",152,0,-1,0,337,337,"2125","",0,"","","",1,0,0,[],""],["frenk_t1-n2126",5,"Dentro del alma\ntraigo yo un hueco\nde una querencia\nque me trae chueco.",75,2,-1,94,"Mi preferida",6,4,"eo",320,0,-1,0,337,337,"2126","",0,"","","",1,0,0,[],""],["frenk_t1-n2127",5,"El lenguaje de las flores\na los amores auxilia,\ny por sus bellos colores\nme gusta la bugambilia,\npero para mis amores\nsólo me gusta Cecilia.",76,2,1,94,"La Cecilia",9,6,"ia",546,0,-1,0,337,337,"2127","",0,"","","",1,0,0,[],""],["frenk_t1-n2128",5,"Como la casta azucena\nes la joven que yo adoro;\nesa cándida morena\npara mí es un gran tesoro,\nde alma cariñosa y buena.",81,2,6,94,"La azucena",7,5,"ea",59,0,-1,0,337,337,"2128","",0,"","","",1,0,0,[],""],["frenk_t1-n2129",5,"No sé si el corazón peca (¡ay, Llorona!)\nen aras de un tierno amor,\npor una linda tehuana (Llorona),\nmás hermosa que una flor.",83,2,8,94,"La Llorona",3,4,"o",72,0,-1,0,337,337,"2129","",0,"","","",1,0,0,[],""],["frenk_t1-n2131",5,"Bonito Estados Unidos,\nque no me cabe ni duda,\npero más bonito es\nel cariño de mi Julia.",75,2,-1,94,"Estrofa sueltaj",0,4,"ua",-1,0,-1,0,337,337,"2131","",0,"","","",1,0,0,[],""],["frenk_t1-n2132",5,"No quiero peso\nni quiero tostón,\nquiero la muchacha\nque está en el sillón.",79,2,4,94,"Naranjas y limas",6,4,"o",31,0,-1,0,337,337,"2132","",0,"","","",1,0,0,[],""],["frenk_t1-n2137",5,"Estoy herida por la “A”,\npor la culpa de la “M”,\ny el gran golpe de la “O”\npuso en mi pecho una “R”.",75,2,-1,94,"Estrofa suelta",5,4,"",-1,0,-1,0,338,338,"2137","",0,"","","",1,0,0,[],""],["frenk_t1-n2139",5,"Yo no soy de Pinotepa,\npero quiero a ese lugar,\nporque de ahí es mi chatita,\nque está cerquita del mar.",75,2,-1,94,"La Sanmarqueña",0,4,"a",21,0,-1,0,338,338,"2139","",0,"","","",1,0,0,[],""],["frenk_t1-n2140",5,"Yo tengo una chaparrita,\nque me espera en Ejcala,\nde esas de zapato bajo\ny de enaguas de percal.",75,2,-1,94,"La chaparrita",5,4,"a",-1,0,-1,0,339,339,"2140","",0,"","","",1,0,0,[],""],["frenk_t1-n2141",5,"La mujer que yo quiero\nes michoacana,\nporque baila la bamba\nveracruzana.",75,2,-1,94,"La bamba I",6,4,"aa",-1,0,-1,0,339,339,"2141","",0,"","","",2,0,0,[],""],["frenk_t1-n2142",5,"En mi casa me dicen\nEmilio Tuero,\nporque tengo una novia\nque está muy cuero.",79,2,4,94,"La bamba",6,4,"eo",38,0,-1,0,339,339,"2142","",0,"","","",11,0,0,[],""],["frenk_t1-n2143",5,"Qué buena está la hermana\nque tiene Nicolás;\nestá buena por delante\ny está buena por detrás.",79,2,4,94,"El Colas",0,4,"a",51,0,-1,0,339,339,"2143","",0,"","","",1,0,0,[],""],["frenk_t1-n2144",5,"Tengo una pájara sancha\n¡ah, qué pájara tan mona!\nTiene la cola muy ancha,\nde tanto hacerse la moña;\n¡ah, qué pájara carancha!",101,2,26,94,"La azucena",7,5,"aa",446,0,-1,0,339,339,"2144","",0,"","","",1,0,0,[],""],["frenk_t1-n2145",5,"Yo soy el que ando de malas,\npero ya mero compongo.\nEs una jaca bragada,\nmedia retinta del lomo,\nsiendo por mi prenda amada\nque me rezumba el plomo.",79,2,4,94,"El siquisirí",9,6,"oo",349,0,-1,0,339,339,"2145","",0,"","","",1,0,0,[],""],["frenk_t1-n2146",5,"Soy como la yerbabuena:\n[que] donde me planta[n] florezco;\ncon todos platico y río,\npero a ninguno apetezco;\nsólo cuando veo al mío\nparece que me engrandezco.",87,2,12,94,"Estrofa suelta",9,6,"eo",355,0,-1,0,339,339,"2146","",0,"","","",3,0,0,[],""],["frenk_t1-n2147",5,"Una mujer tengo herida\n—qué bonito es el querer—,\ny cuando la voy a ver\nhasta el sueño se me quita:\n¡qué cariños de mujer\ncuando me encuentro solito!",81,2,6,94,"La huazanga",9,6,"io",-1,0,-1,0,339,339,"2147","",0,"","","",1,0,0,[],""],["frenk_t1-n2148",5,"Tengo una novia coqueta\nque vale mucho dinero;\ny ella me abraza y me aprieta\ny me dice: “Mi lucero,\ncómprame una bicicleta,\nquiero darme el vuelo entero.\"",79,2,4,94,"La tarasca",9,6,"eo",38,0,-1,0,339,339,"2148","",0,"","","",1,0,0,[],""],["frenk_t1-n2155",5,"Cuando encuentro a una morena,\nse me salta el corazón;\nyo le canto sin cesar\nmi pasión a una sirena:\nsi es que ella me sale buena,\ntal vez me puedo casar.",75,2,-1,94,"Yo agarro parejo",9,6,"a",21,0,-1,0,340,340,"2155","",0,"","","",1,0,0,[],""],["frenk_t1-n2156",5,"Cuando veo que se baila mi dulce morena\nun alegre huapango — tarango,\nsiento que yo me muero — salero,\nporque mucho la quiero y venero.",75,2,-1,94,"Ya no lloverá, pelonas",3,4,"eo",38,0,-1,0,341,341,"2156","",0,"","","",1,0,0,[],""],["frenk_t1-n2157",5,"La señorita Techí\ncabellos de oro se tupe,\nla estoy viendo dormidita\ncomo Virgen Guadalupe.",82,2,7,94,"Los papaquis",0,4,"ue",271,0,-1,0,341,341,"2157","",0,"","","",1,0,0,[],""],["frenk_t1-n2158",5,"Mi prietita, me parece\nque es la hora del huapango;\nmientras su hamaca se mece,\nyo no más la estoy mirando,\ny al verla que se estremece,\nle pregunto: “¿Qué hubo?, ¿cuándo?\"",75,2,-1,94,"¿Ouihubo?, ¿cuándo?",9,6,"ao",33,0,-1,0,341,341,"2158","",0,"","","",1,0,0,[],""],["frenk_t1-n2159",5,"Soy el hombre más dichoso\ncuando yo estoy a su lado:\nhasta el sueño se me quita,\naunque esté bien desvelado.",75,2,-1,94,"Ciclo azul, ciclo nublado",0,4,"ao",14,0,-1,0,341,341,"2159","",0,"","","",1,0,0,[],""],["frenk_t1-n2160",5,"Ahora sí ya estoy contento\ny también tengo alegría\nporque ya tengo a mi lado\na la joven que yo quería.",83,2,8,94,"Estrofa suelta",0,4,"ia",0,0,-1,0,341,341,"2160","",0,"","","",2,0,0,[],""],["frenk_t1-n2161",5,"¿Quién dice que no es bonito\ny estar junto con su dama,\ndebajo de un arbolito,\nque lo cobije una rama?",83,2,8,94,"La Malagueña curreña; Estrofa suelta",1,4,"aa",90,0,-1,0,341,341,"2161","",0,"","","",2,0,0,[],""],["frenk_t1-n2162",5,"¡Ay!, qué bonito es estar\njunto de lo que uno quiere,\ndarle un beso, si hay lugar,\nun abrazo, si se puede,\ny sin darlo a maliciar,\ncomo aquel que nada debe.",79,2,4,94,"El Ahualulco; La abajeña; La azucena",9,6,"ee",-1,0,-1,0,341,341,"2162","",0,"","","",2,0,0,[],""],["frenk_t1-n2163",5,"¡Ay!, qué bonito es volar\nde medianoche pa el día,\ny luego dejarse caer\nen los brazos de María,\nque hasta quisiera llorar (¡ay, mamá!).",75,2,-1,94,"La bruja",7,5,"a",21,0,-1,0,341,341,"2163","",0,"","","",3,0,0,[],""],["frenk_t1-n2164",5,"¡Ay! que bonito es volar\na las dos de la mañana,\npara venir a quedar\nen los bracitos de Juana;\nbasta quisiera llorar (¡ay, mamá!).",79,2,4,94,"La bruja'1",7,5,"a",21,0,-1,0,342,342,"2164","",0,"","","",3,0,0,[],""],["frenk_t1-n2166",5,"Yo pedí a mi Margarita.\nno me la quisieron dar;\nse la llevaron sus padres\npa el otro lado del mar.",75,2,-1,94,"Margarita; Carmelita; La Juanita",0,4,"a",21,0,-1,0,342,342,"2166","",0,"","","",1,0,0,[],""],["frenk_t1-n2173",5,"Mañana me voy (¡caramba!)\npara Veracruz,\na ver a mi china (¡caramba!),\nMaría de la Luz.",75,2,-1,94,"El caramba",1,4,"u",109,0,-1,0,343,343,"2173","",0,"","","",2,0,0,[],""],["frenk_t1-n2177",5,"Qué bonita chaparrita\nchina de los ojos negros,\npor bonita y cariñosa\nmañana la voy a ver.",101,2,26,94,"Chaparrita de los naranjos",5,4,"e",-1,0,-1,0,343,343,"2177","",0,"","","",5,0,0,[],""],["frenk_t1-n2178",5,"Chaparrita, ya me voy\npara el puerto de Mazatlán,\nvoy a ver a mis amores,\nque me mandaron llamar.",75,2,-1,94,"La chaparrita",0,4,"a",-1,0,-1,0,343,343,"2178","",0,"","","",1,0,0,[],""],["frenk_t1-n2179",5,"Ya me voy, porque ya es tarde:\nme solicita mi amor;\nsi no voy, seré cobarde\ny me faltará valor.",83,2,8,94,"Estrofa suelta",1,4,"o",72,0,-1,0,343,343,"2179","",0,"","","",1,0,0,[],""],["frenk_t1-n2181",5,"Más allá de la frontera\ndejé pendiente un amor,\nmás allá de la frontera\niré a cortar esa flor.",75,2,-1,94,"Más allá de la frontera",1,4,"o",72,0,-1,0,344,344,"2181","",0,"","","",2,0,0,[],""],["frenk_t1-n2183",5,"—Señora, ¿pa dónde va?\n—Me voy yendo pa Colima:\nvoy a ver a mis amores\narriba del pedregal.",75,2,-1,94,"El pedregal",5,4,"a",-1,0,-1,0,344,344,"2183","",0,"","","",1,0,0,[],""],["frenk_t1-n2184",5,"Se va el vapor,\nme voy con él;\nse va mi amor,\nme voy también.",75,2,-1,94,"El sargento",6,4,"e",-1,0,-1,0,344,344,"2184","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t1-n2185",5,"¡Ay!, se va mi amor,\nyo me voy con él;\naunque me canse\n........... en él.",75,2,-1,94,"El Cihuaht/o",6,4,"e",-1,0,-1,0,344,344,"2185","",0,"","","",1,0,0,[],""],["frenk_t1-n2186",5,"Estando de centinela\nen Pinotepa parado,\nme acordé de mis amores\ny me vine desertado,\npor Pinotepa floreado,\nechando fuego graneado.",75,2,-1,94,"Estrofa suelta",9,6,"ao",14,0,-1,0,344,344,"2186","",0,"","","",5,0,0,[],""],["frenk_t1-n2187b",5,"Pues al fin que ya he llegado\nal barrio donde quería,\na devengar un agravio,\na seguir en mi porfía;\na ver si me muerde el perro\nque me mordió el otro día.",75,2,-1,94,"Corrido de Guanajuato",9,6,"ia",0,0,-1,0,344,344,"2187b","",0,"","","",1,0,0,[],""],["frenk_t1-n2189",5,"¡Ay!, cuánto me gusta el súchil\ny las hojas del laurel;\nusted que mira más lejos,\n¿será mi amorcito aquél?",75,2,-1,94,"El súchil",0,4,"e",32,0,-1,0,345,345,"2189","",0,"","","",1,0,0,[],""],["frenk_t1-n2190",5,"Traigo mi botella nueva\nacabada de comprar;\naguardiente traigo en ella,\npero no quiero tomar:\nlo que quiero es ver a aquélla,\na qué horas se va a pasear.",81,2,6,94,"La Cecilia; El huerfanito",9,6,"a",21,0,-1,0,345,345,"2190","",0,"","","",1,0,0,[],""],["frenk_t1-n2191",5,"Cuando voy por la calle (bien de mi vida),\nbusco la sombra;\nvoy siguiéndole los pasos\na una paloma.",86,2,11,94,"El pájaro cú",3,4,"oa",-1,0,-1,0,345,345,"2191","",0,"","","",1,0,0,[],""],["frenk_t1-n2192",5,"Vengo a ver a mi chaparrita,\nque le quiero platicar,\ny decirle muchas cosas\nque todos han de ignorar.",75,2,-1,94,"Capotear por lo lindo",0,4,"a",21,0,-1,0,345,345,"2192","",0,"","","",1,0,0,[],""],["frenk_t1-n2193",5,"La voy a ver,\nla voy a hablar,\npara un asunto\nparticular.",75,2,-1,94,"El café; El durazno",6,4,"a",21,0,-1,0,345,345,"2193","",0,"","","",1,0,0,[],""],["frenk_t1-n2194",5,"La he de decir.\nla he de jurar\nque hasta la muerte\nyo la he de amar.",75,2,-1,94,"El café; El durazno",6,4,"a",21,0,-1,0,345,345,"2194","",0,"","","",1,0,0,[],""],["frenk_t1-n2196",5,"Preso me llevan pa el Norte,\nme llevan a fusilar;\npor el amor de Juanita,\nni cuidado me ha de dar.",75,2,-1,95,"La Juanita",0,4,"a",21,0,-1,0,346,346,"2196","",0,"","","",2,0,0,[],""],["frenk_t1-n2200",5,"Ya se va, ya se la llevan,\nya se la van a llevar;\nsi a México se la llevan,\nhasta allá la iré a buscar.",75,2,-1,95,"Amorcito consentido. La caria",1,4,"a",21,0,-1,0,346,346,"2200","",0,"","","",1,0,0,[],""],["frenk_t1-n2201",5,"Lucero de la mañana,\npréstame tu claridad,\npara seguirle los pasos\na esa joven que se va.",78,2,3,95,"La madrugada; Las campanitas; Cuatro esquinas tiene un catre; La Sanmarqueña; Vuelve, vuelve duraznito; Estrofa",0,4,"a",-1,0,-1,0,347,347,"2201","",0,"","","",22,0,0,[],""],["frenk_t1-n2202",5,"Lucero de la mañana,\npréstame tu lucecita,\npara seguirle los pasos\na esa muchacha bonita.",75,2,-1,95,"La madrugada",0,4,"ia",50,0,-1,0,347,347,"2202","",0,"","","",22,0,0,[],""],["frenk_t1-n2203",5,"Mañana me voy, mañana,\npara San Pedro lucido,\ny en busca de mi morena,\nque ésa me lleva perdido.",83,2,8,95,"La garza",0,4,"io",101,0,-1,0,347,347,"2203","",0,"","","",2,0,0,[],""],["frenk_t1-n2204",5,"Cuando me vine de Puebla,\nde sentimiento y pesar,\nen busca de mi morena,\nque no he podido encontrar.",90,2,15,95,"Estrofa suelta",0,4,"a",21,0,-1,0,347,347,"2204","",0,"","","",2,0,0,[],""],["frenk_t1-n2205",5,"Qué bonita capital,\ndonde me vine a pasear,\nen busca de Margarita,\nque no la pude encontrar.",75,2,-1,95,"En busca de Margarita",0,4,"a",21,0,-1,0,347,347,"2205","",0,"","","",1,0,0,[],""],["frenk_t1-n2206",5,"Yo soy un gavilancillo\nque sale de la prisión,\nen busca de mi morena,\nque me robó el corazón.",75,2,-1,95,"La palomita",0,4,"o",31,0,-1,0,347,347,"2206","",0,"","","",12,0,0,[],""],["frenk_t1-n2207",5,"Yo ya me voy para San Luis,\ndonde se baila el carquís,\nvoy a buscar a mi Juanita,\nque se fue de este país.",75,2,-1,95,"La Juanita",0,4,"i",58,0,-1,0,347,347,"2207","",0,"","","",1,0,0,[],""],["frenk_t1-n2208",5,"Soy marinero de golfo a golfo,\nque ha andado el mundo alrededor,\ny yendo en busca de mi Zenaida,\nque se me vino desde Nueva York.",103,2,28,95,"Zenaida",3,4,"o",-1,0,-1,0,347,347,"2208","",0,"","","",1,0,0,[],""],["frenk_t1-n2209",5,"En Jojutla yo nací\ny en Cuernavaca crecí;\npor buscar a Margarita\nen México me perdí.",75,2,-1,95,"En busca de Margarita",0,4,"i",23,0,-1,0,347,347,"2209","",0,"","","",1,0,0,[],""],["frenk_t1-n2211",5,"De las arcas de la fuente (Llorona)\ncorre el agua y nace la flor.\nSi preguntan quién cantó (¡ay, Llorona!),\nles dices que un desertor,\nque viene de la campaña (¡ay, Llorona!)\nen la busca de su amor.",83,2,8,95,"La Llorona",9,6,"o",72,0,-1,0,348,348,"2211","",0,"","","",1,0,0,[],""],["frenk_t1-n2212",5,"Son los ojitos de la vida mía\nlos que ando buscando;\npor las orillas del agua del mar\nmi amor navegando.",78,2,3,95,"Los ojitos",3,4,"ao",33,0,-1,0,348,348,"2212","",0,"","","",1,0,0,[],""],["frenk_t1-n2213",5,"¿Si el sereno de la esquina\nme quisiera hacer favor\nde apagar su linternita\nmientras que pasa mi amor?",75,2,-1,95,"Estrofa suelta,Las mañanitas",0,4,"o",72,0,-1,0,348,348,"2213","",0,"","","",1,0,0,[],""],["frenk_t1-n2216",5,"A mi indita le he de hacer\nuna casita en el viento,\nlas paredes de cristal,\ny de algodón sus cimientos.",83,2,8,95,"Indita del alma; Estrofa suelta",0,4,"eo",-1,0,-1,0,348,348,"2216","",0,"","","",1,0,0,[],""],["frenk_t1-n2217",5,"Aquí traigo un cascabel\nengarzado en oro y plata,\nque se lo voy a poner\nen el cabello a mi chata;\nsólo te advierto, mujer,\nque no te muestres ingrata.",79,2,4,95,"El cascabel",9,6,"aa",74,0,-1,0,349,349,"2217","",0,"","","",1,0,0,[],""],["frenk_t1-n2218",5,"Yo tenía mi cascabel\ncon una cinta morada,\ny, como era de oropel,\nse lo di a mi prenda amada,\npara que juegue con él,\nallá por la madrugada.",79,2,4,95,"El cascabel",9,6,"aa",49,0,-1,0,349,349,"2218","",0,"","","",10,0,0,[],""],["frenk_t1-n2219",5,"Yo tenía mi cascabel\nentorchadlo de plata,\ny como era de oropel,\nse lo regalé a mi chata,\npa que jugara con él\ny se entretuviera en su casa.",79,2,4,95,"El cascabel",9,6,"aa",-1,0,-1,0,349,349,"2219","",0,"","","",10,0,0,[],""],["frenk_t1-n2220",5,"Yo tenía mi cascabel\nvestido de colorado,\ny como era de oropel,\nse lo di a la de Alvarado,\npara que juegue con él\ncon la que sea de mi agrado.",79,2,4,95,"El cascabel",9,6,"ao",14,0,-1,0,349,349,"2220","",0,"","","",10,0,0,[],""],["frenk_t1-n2221",5,"Yo tenía mi cascabel\ncon una piedra sonora;\n¡ay!, como era de oropel,\nse lo obsequié a una señora,\npara que juegue con él\nallá en el Parque Zamora.",79,2,4,95,"El cascabel",9,6,"oa",107,0,-1,0,349,349,"2221","",0,"","","",10,0,0,[],""],["frenk_t1-n2222",5,"En el cielo está un sillón\nrepleto de margaritas,\nlo voy a mandar bajar\npara sentar a ......",75,2,-1,95,"Estrofa suelta",5,4,"a",-1,0,-1,0,349,349,"2222","",0,"","","",1,0,0,[],""],["frenk_t1-n2223",5,"Yo no soy merecedor\npara que me estén oyendo;\ncuando les pido un favor,\nasí como lo confieso:\ndéjenme echar una flor\na la joven que estoy viendo.",79,2,4,95,"El siquisirí",9,6,"eo",-1,0,-1,0,349,349,"2223","",0,"","","",1,0,0,[],""],["frenk_t1-n2224",5,"Ya se empiezan a afinar\nlas jaranas y el violín,\ny yo me voy a acercar\nal tapete del festín\npara poderle cantar\na la hija de Don Martín.",79,2,4,95,"El huasteco",9,6,"i",211,0,-1,0,350,350,"2224","",0,"","","",1,0,0,[],""],["frenk_t1-n2225",5,"A mí me gusta trovar\ncuando me encuentro solito;\npues me van a dispensar,\ncantándole a mi amorcito,\nque hasta ha de suspirar.",77,2,2,95,"El bejuquito",7,5,"a",21,0,-1,0,350,350,"2225","",0,"","","",1,0,0,[],""],["frenk_t1-n2226",5,"Bejuquito, bejuquito,\nbejuquito enredador;\n¡qué bonito sonecito\npara cantarle a mi amor\ncuando lo encuentre solito!",77,2,2,95,"El bejuquito; El taconcito",7,5,"io",119,0,-1,0,350,350,"2226","",0,"","","",1,0,0,[],""],["frenk_t1-n2227",5,"Taconcito, taconcito,\ntaconcito de madera;\n¡qué bonito sonecito\npara cantarle a mi güera\nen el puerto de Tampico!",77,2,2,95,"El taconcito",7,5,"io",-1,0,-1,0,350,350,"2227","",0,"","","",1,0,0,[],""],["frenk_t1-n2233",5,"Este son que estoy cantando\nye lo quiero dedicar\na la muchacha de enfrente\npor su modo de mirar.",86,2,11,95,"El toro rabón",0,4,"a",21,0,-1,0,350,350,"2233","",0,"","","",2,0,0,[],""],["frenk_t1-n2234",5,"Cuando el sombrero me pongo\ny le hago la pedradita,\ntodos me dicen de pronto,\ncantándole a mi chatita,\ncon el alma y pecho ronco.",81,2,6,95,"El sombrero",7,5,"oo",-1,0,-1,0,351,351,"2234","",0,"","","",5,0,0,[],""],["frenk_t1-n2235",5,"Cuando el sombrero me pongo\ny me lo pongo de lado,\ntodos me dicen de pronto,\ncon mi sombrero de lado,\namanezco el pecho ronco.",81,2,6,95,"El sombrero",7,5,"oo",-1,0,-1,0,351,351,"2235","",0,"","","",5,0,0,[],""],["frenk_t1-n2236",5,"Ya con ésta me despido,\ny el amor no se me quita;\nestos versos yo los canto\na mi linda Mariquita.",78,2,3,95,"Mariquita; La carta que te mandé",0,4,"ia",50,0,-1,0,351,351,"2236","",0,"","","",72,0,0,[],""],["frenk_t1-n2237",5,"Despedida no la doy\nporque no la traigo aquí:\nse la dejé a mi morena\npa que se acuerde de mí.",83,2,8,95,"Que comienzo, que comienzo; ¡Ay, qué cielo tan azul!; La embarcación; La Julia; Marcianita; El muchacho alegre,",0,4,"i",23,0,-1,0,351,351,"2237","",0,"","","",1,0,0,[],""],["frenk_t1-n2238",5,"Gorrioncito de color,\ncanta en este nuevo nido,\npara que despierte mi amor,\nque se ha quedado dormido;\nya se va tu trovador,\nya con ésta me despido.",77,2,2,95,"El aguanieve",9,6,"io",101,0,-1,0,351,351,"2238","",0,"","","",1,0,0,[],""],["frenk_t1-n2239",5,"Tuncuruchú, tuncuruchú,\ntuncuruchú del amor,\nven a cantar y a despertar\na la dueña de mi corazón.",75,2,-1,95,"Estrofa suelta",3,4,"o",-1,0,-1,0,351,351,"2239","",0,"","","",1,0,0,[],""],["frenk_t1-n2240",5,"Allá viene un pajarito,\nque atrás tiene una gran mancha\ny en el piquito le trae\nlos recuerdos a mi Pancha.",75,2,-1,95,"Pancha",0,4,"aa",446,0,-1,0,351,351,"2240","",0,"","","",1,0,0,[],""],["frenk_t1-n2241",5,"Pajarito mañanero,\nque cantas en su balcón,\ncántale como le canta\nmi rendido corazón.",75,2,-1,95,"Estrofa suelta, Las mañanitas",0,4,"o",31,0,-1,0,351,351,"2241","",0,"","","",1,0,0,[],""],["frenk_t1-n2249",5,"Quién hubiera cantado\nun aleluya,\npara ver las estrellas\nuna por una;\npara ver entre todas\nla más bonita,\npara volver al puerto.",79,2,4,95,"La bamba",4,7,"eo",-1,0,-1,0,353,353,"2249","",0,"","","",1,0,0,[],""],["frenk_t1-n2250a",5,"¿Cuándo me traes a mi negra,\nque la quiero ver aquí,\ncon su rebozo de seda\nque le traje de Tepic?",75,2,-1,95,"La negra",0,4,"i",-1,0,-1,0,353,353,"2250a","",0,"","","",2,0,0,[],""],["frenk_t1-n2251",5,"Yo quisiera que volviera\ny que nunca más se fuera,\ny por su linda boquita\nyo de besitos le diera.",95,2,20,95,"La chuparrosa",0,4,"ea",44,0,-1,0,353,353,"2251","",0,"","","",1,0,0,[],""],["frenk_t1-n2252",5,"Qué bonito corre el agua\ndebajo del zacatito:\n¡así corriera mi amor\ncon esa del rebocito!",87,2,12,95,"Estrofa suelta",0,4,"io",119,0,-1,0,353,353,"2252","",0,"","","",5,0,0,[],""],["frenk_t1-n2254",5,"El cuervo, con ser tan negro,\nrelumbra más que el acero;\n¡así relumbrara yo\nen los brazos de mi cuero!",75,2,-1,95,"El cuervo; Conchitas y caracoles",0,4,"eo",38,0,-1,0,353,353,"2254","",0,"","","",3,0,0,[],""],["frenk_t1-n2255",5,"Ojitos negros y chinos,\n¡cuánto me han apasionado!\nNo pierdo las esperanzas\nde tenerlos a mi lado.",102,2,27,95,"Ojitos negros y chinos; Ojitos negros chinitos; Amorcito consentido; Estrofa suelta",0,4,"ao",14,0,-1,0,353,353,"2255","",0,"","","",1,0,0,[],""],["frenk_t1-n2256",5,"¡Ay, qué Severiana\ntan linda y bella!\nQuisiera yo estar\njuntito con ella.",75,2,-1,95,"Yo no sé qué tiene Pancha",0,4,"ea",6,0,-1,0,354,354,"2256","",0,"","","",4,0,0,[],""],["frenk_t1-n2257",5,"Yo no quero eso (caramba),\nyo quiero otra cosa (caramba):\nyo quero un besito\nde mi chata hermosa.",75,2,-1,95,"El quihúbole",5,4,"oa",63,0,-1,0,354,354,"2257","",0,"","","",1,0,0,[],""],["frenk_t1-n2258",5,"Del cielo cayó una coronita,\nllenecita de campanitas;\nno pierdo las esperanzas\nde llevarme a tu hermanita.",87,2,12,95,"Estrofa suelta",3,4,"ia",-1,0,-1,0,354,354,"2258","",0,"","","",1,0,0,[],""],["frenk_t1-n2259",5,"Antenoche tuve un sueño,\nquiera Dios se me conceda;\nsoñé que estaba acostado\neon una viudita nueva.",83,2,8,95,"Estrofa suelta",0,4,"ea",-1,0,-1,0,354,354,"2259","",0,"","","",3,0,0,[],""],["frenk_t1-n2260b",5,"Andando de partideño\nme quedé en Camino Real;\nal echar el primer sueño\nsoñé que me iba a arrendar\npor un amor halagüeño\nque me iban a regalar.",77,2,2,95,"El San Lorenzo; Estrofa suelta",9,6,"a",21,0,-1,0,354,354,"2260b","",0,"","","",2,0,0,[],""],["frenk_t1-n2264",5,"El gorrión sobre el árbol\nle canta a su primavera;\nno se cansa de cantar\npor todita la ladera:\n“¡Qué gusto me había de dar\nsi esa chica yo tuviera!”",75,2,-1,95,"Áhi viene el agua",9,6,"ea",44,0,-1,0,355,355,"2264","",0,"","","",1,0,0,[],""],["frenk_t1-n2265",5,"Soy pájaro carpintero\nque habita en un platanar;\nsi consigo a la que quiero,\ntres besitos le he de dar\nen ese pico chismoso,\nque hasta se ha de saborear.",75,2,-1,95,"El pájaro carpintero; Estrofa suelta",9,6,"a",21,0,-1,0,355,355,"2265","",0,"","","",2,0,0,[],""],["frenk_t1-n2266",5,"Si me encuentro con mi negra,\nyo le digo sin tardar\nque si amor se me logra,\nun altar yo le he de hacer;\nque si me da su querer,\nhasta cargo con la suegra.",75,2,-1,95,"Ya agarro parejo",9,6,"ea",382,0,-1,0,355,355,"2266","",0,"","","",1,0,0,[],""],["frenk_t1-n2267",5,"Si porque me la llevé\nsu mamá se me enojó,\nhora que me lleve a mí:\na ver si me enojo yo.",92,2,17,95,"Mariquita, Glosada en décimas",0,4,"o",2,0,-1,0,355,355,"2267","",0,"","","",1,0,0,[],""],["frenk_t1-n2268",5,"Si en este jardín hubiera\nla rosa que yo corté,\nle anduviera yo diciendo:\n“Yo me caso con usted;\nsi nos ven los envidiosos,\nque nos miren, y hora qué.”",75,2,-1,95,"El venadito",9,6,"e",-1,0,-1,0,355,355,"2268","",0,"","","",2,0,0,[],""],["frenk_t1-n2269",5,"Si en este jardín hubiera\nla yerba que llaman té,\nte anduviera yo diciendo:\n“yo me embriago con tu té”.",75,2,-1,95,"Estrofa suelta",0,4,"e",-1,0,-1,0,355,355,"2269","",0,"","","",2,0,0,[],""],["frenk_t1-n2270",5,"Brindo por ella,\ncual si fuera una estrella,\npor la bonita mujer\nque quiero casarme con ella",75,2,-1,95,"Estrofa suelta",3,4,"ea",6,0,-1,0,355,355,"2270","",0,"","","",1,0,0,[],""],["frenk_t1-n2272",5,"Si Adelita se fuera con otro,\nle seguiría la huella sin cesar:\nsi por mar, en un buque de guerra,\nsi por tierra en un tren militar.",75,2,-1,95,"La Adelita",3,4,"a",21,0,-1,0,356,356,"2272","",0,"","","",1,0,0,[],""],["frenk_t1-n2278",5,"Yo le pregunté a la palma\nque si estaba en el florero,\npa mandarle por correo\ncuatro suspiros del alma.",75,2,-1,95,"La palma",5,4,"aa",125,0,-1,0,356,356,"2278","",0,"","","",1,0,0,[],""],["frenk_t1-n2281",5,"¡Ay, ay, ay!, mi pajarito,\nque vuelas de flor en flor,\nllévale este papelito\na la dueña de mi amor.",75,2,-1,95,"El pájaro cú",1,4,"o",72,0,-1,0,357,357,"2281","",0,"","","",1,0,0,[],""],["frenk_t1-n2283",5,"Pajarito rebonito,\nsi me quisieras hacer un favor\nde llevarle a mi timada\nde llevarle esta cartita,\ny decirle que la quiero,\nque no la puedo olvidar",75,2,-1,95,"Estrofa suelta",9,6,"a",-1,0,-1,0,357,357,"2283","",0,"","","",1,0,0,[],""],["frenk_t1-n2284",5,"Pajarito, eres bonito\ny de bonito color,\npero más bonito fueras\nsi me hicieras el favor\nde llevarle un papelito\na la dueña de mi amor.",75,2,-1,95,"El pájaro cú",9,6,"o",72,0,-1,0,357,357,"2284","",0,"","","",1,0,0,[],""],["frenk_t1-n2288",5,"Vuela, vuela, pajarito,\ndonde está aquella ramita,\ndevisa pa la vereda\ndonde vive mi chatita.",75,2,-1,95,"Mi querencia",0,4,"ia",50,0,-1,0,358,358,"2288","",0,"","","",2,0,0,[],""],["frenk_t1-n2289",5,"Pajarillo, pajarillo,\nPajarillo barranqueño.\nvé a decirle, pajarillo,\nque por su pasión me muero",75,2,-1,95,"Pajarillo barranqueño",0,4,"eo",-1,0,-1,0,358,358,"2289","",0,"","","",9,0,0,[],""],["frenk_t1-n2290",5,"Pajarito rito rito,\npájaro vaquero quero,\nanda, dile a mi negrito\nque yo todavía lo quiero.",79,2,4,95,"El pájaro cú",1,4,"eo",38,0,-1,0,358,358,"2290","",0,"","","",2,0,0,[],""],["frenk_t1-n2291",5,"Águila, que vas volando,\nque vas para Nuevo León,\nle dices a mi negrito\nque me mande el corazón.",75,2,-1,95,"Estrofa suelta",0,4,"o",31,0,-1,0,358,358,"2291","",0,"","","",10,0,0,[],""],["frenk_t1-n2292",5,"Pajarito, hazme favor\nde decirle a mi querida\nque es mi señora y mi vida,\ndueña única de mi amor.",75,2,-1,95,"Glosada en décimas",11,4,"o",72,0,-1,0,358,358,"2292","",0,"","","",1,0,0,[],""],["frenk_t1-n2293",5,"Pajarito rojo,\npájaro mañanero,\nsi quieres que te cante,\nabre tus alitas\npara tender el vuelo:\nve a ver a mi novia,\ndile lo que la quiero.",75,2,-1,95,"María Lupe",4,7,"eo",-1,0,-1,0,358,358,"2293","",0,"","","",1,0,0,[],""],["frenk_t1-n2294",5,"Qué bonitos los ojitos,\nlos ojitos de mi negra;\nanda y dile, pajarillo,\nque no sea tan traicionera.",75,2,-1,95,"Pajarillo barranqueño",0,4,"ea",-1,0,-1,0,359,359,"2294","",0,"","","",1,0,0,[],""],["frenk_t1-n2295",5,"Vuela y dile que me espere,\nque no me deje solito,\nque mi corazón se muere\npor verla, aunque sea un ratito.",75,2,-1,95,"Mi querencia",1,4,"io",119,0,-1,0,359,359,"2295","",0,"","","",1,0,0,[],""],["frenk_t1-n2296",5,"Vuela, vuela, chuparrosa,\ny no dejes de volar,\nanda dile a mi amorcito\nque ya no me haga esperar.",95,2,20,95,"La chuparrosa",0,4,"a",21,0,-1,0,359,359,"2296","",0,"","","",1,0,0,[],""],["frenk_t1-n2297",5,"Palomas que andan volando,\nle dirán a mi cielito\nque no me ande atormentando,\nque mi ausencia no es delito.",82,2,7,95,"La Sanmarqueña",1,4,"io",119,0,-1,0,359,359,"2297","",0,"","","",2,0,0,[],""],["frenk_t1-n2298",5,"Palmero, sube a la palma\ny dile a aquella trigueña\nque me ha robado la calma\ncon su pestaña sedeña.",75,2,-1,95,"El palmero",1,4,"ea",291,0,-1,0,359,359,"2298","",0,"","","",16,0,0,[],""],["frenk_t1-n2299",5,"Palmero, sube a la palma\ny dile a la palmerita\nque se asome a su ventana,\nque mi amor la solicita.",75,2,-1,95,"El palmero",0,4,"ia",50,0,-1,0,359,359,"2299","",0,"","","",16,0,0,[],""],["frenk_t1-n2300",5,"Luna, que alumbras la tierra\ncon misterioso semblante,\ntú le dirás a mi amante\nque no lo puedo olvidar.",75,2,-1,95,"Estrofa suelta",5,4,"a",-1,0,-1,0,359,359,"2300","",0,"","","",3,0,0,[],""],["frenk_t1-n2301",5,"Lucero de la mañana,\npregúntale a la alta estrella\nsi ella se acuerda de mí\ncomo yo me acuerdo de ella.",75,2,-1,95,"Estrofa suelta",0,4,"ea",6,0,-1,0,359,359,"2301","",0,"","","",22,0,0,[],""],["frenk_t1-n2302",5,"Mariquita llora mucho,\nporque no la voy a ver;\nanda, dile que no llore,\nque ella es todo mi querer.",75,2,-1,95,"Mariquita",0,4,"e",-1,0,-1,0,359,359,"2302","",0,"","","",1,0,0,[],""],["frenk_t1-n2303",5,"Pajarito, si te vas,\ndile a mi bien que no llore,\nque los suspiros que das,\nhasta la barranca se oyen\nlos gritos de soledad.",79,2,4,95,"El pájaro cú",7,5,"a",-1,0,-1,0,360,360,"2303","",0,"","","",1,0,0,[],""],["frenk_t1-n2304",5,"Paloma, ve con violencia,\ndile a mi amor que me aguarde,\nque sufra y tenga paciencia,\nque yo volveré, aunque tarde.",75,2,-1,95,"Bonito San Juan del Río",1,4,"ae",344,0,-1,0,360,360,"2304","",0,"","","",1,0,0,[],""],["frenk_t1-n2305",5,"Palomas que andan volando,\nle dirán a mi cielito\nque allá voy, no digo cuándo;\nno más que tenga un campito.",75,2,-1,95,"El palomo; Estrofa suelta",1,4,"io",119,0,-1,0,360,360,"2305","",0,"","","",2,0,0,[],""],["frenk_t1-n2306",5,"Dile que sí, dile que sí,\ndile que se vaya a misa,\nque para pasearnos juntos (negrita)\nempeñaré mi camisa.",75,2,-1,95,"La guacamaya",3,4,"ia",68,0,-1,0,360,360,"2306","",0,"","","",2,0,0,[],""],["frenk_t1-n2308",5,"Palomita mensajera,\ntodo se te va en volar;\nanda avísale a mi amada\nque hoy me la voy a llevar.",75,2,-1,95,"La palomita",0,4,"a",21,0,-1,0,360,360,"2308","",0,"","","",2,0,0,[],""],["frenk_t1-n2309",5,"Palmero, sube a la palma\ny dile a la palmerita\nque del cogollo más tierno\nme ha de hacer mi canastita.",75,2,-1,95,"El palmero",0,4,"ia",50,0,-1,0,360,360,"2309","",0,"","","",16,0,0,[],""],["frenk_t1-n2310",5,"Becerrero, becerrero,\nde la hacienda del Ranchito,\nle dirás a la ranchera\nsi tiene queso chiquito.",75,2,-1,95,"El toro",0,4,"io",119,0,-1,0,360,360,"2310","",0,"frenk_t4","","",7,0,0,[],""],["frenk_t1-n2311",5,"Becerrero, becerrero,\nde la hacienda El Cabezón,\nle dirás a la ranchera\nque si tiene requesón.",75,2,-1,95,"El toro",0,4,"o",31,0,-1,0,361,361,"2311","",0,"frenk_t4","","",7,0,0,[],""],["frenk_t1-n2312",5,"Becerrero, becerrero,\nde la hacienda de Tequila,\nle dirás a la ranchera\nque me guarde mantequilla.",75,2,-1,95,"El toro",0,4,"ia",-1,0,-1,0,361,361,"2312","",0,"frenk_t4","","",7,0,0,[],""],["frenk_t1-n2313",5,"Si por destierro a La Habana\nme manda el gobernador,\nno voy, que no me da gana,\nque está pendiente mi amor\ncon una veracruzana.",75,2,-1,96,"El buscapiés",7,5,"aa",4,0,-1,0,362,362,"2313","",0,"","","",1,0,0,[],""],["frenk_t1-n2316",5,"Arbolito del camino,\n¡qué chula sombra tenés!\nSi pasa mi amor perdido,\nno me lo desamparés.",75,2,-1,96,"Estrofa suelta, Arbolito del camino",0,4,"e",218,0,-1,0,362,362,"2316","",0,"","","",1,0,0,[],""],["frenk_t1-n2317",5,"Calle Real de Pinotepa,\nte he de mandar a empedrar,\npara que pase mi negra\ny no se vaya a tropezar.",75,2,-1,96,"Estrofa suelta",0,4,"a",21,0,-1,0,362,362,"2317","",0,"","","",1,0,0,[],""],["frenk_t1-n2319",5,"Aquel frenito era de oro\ny las espuelas de plata;\nno siento freno ni espuelas,\nlo que siento es a mi chata.",78,2,3,96,"El caballo prieto",0,4,"aa",74,0,-1,0,363,363,"2319","",0,"","","",1,0,0,[],""],["frenk_t1-n2320",5,"No siento caballo prieto,\nni siento silla plateada,\nlo que siento es a mi chata,\nque la dejé abandonada.",75,2,-1,96,"El caballo prieto; El león; Estrofa suelta",0,4,"aa",-1,0,-1,0,363,363,"2320","",0,"","","",1,0,0,[],""],["frenk_t1-n2321",5,"Cupido, llévame a rastras:\nya no puedo andar a pie;\nllévame hasta la barranca,\ny allí solito me iré\na ver a mi rosita blanca,\nque llorando la dejé.",79,2,4,96,"El gusto",9,6,"e",77,0,-1,0,363,363,"2321","",0,"","","",1,0,0,[],""],["frenk_t1-n2322",5,"Cuando llorando la hallé,\ny yo como apasionado (¡ay de mí, Lloro-\na servirle me obligué, [na!)\ny fui poniendo cuidado (¡ay de mí, Lloro-\nadonde puso los pies. [na!)",79,2,4,96,"La Llorona",7,5,"a",-1,0,-1,0,363,363,"2322","",0,"","","",1,0,0,[],""],["frenk_t1-n2323b",5,"El llorar de una mujer\nel corazón me ha partido (mi vida),\nque si por ella he sufrido,\nhe llegado a comprender\nque [es] la fuerza del destino:\nno siento mi padecer.",86,2,11,96,"El llorar",9,6,"e",20,0,-1,0,363,363,"2323b","",0,"","","",2,0,0,[],""],["frenk_t1-n2324",5,"A mí no me espanta el sueño,\nsi me quieren asustar;\nno la consoló su dueño:\nyo la vengo a consolar.",75,2,-1,96,"Por una mujer casada",1,4,"a",21,0,-1,0,363,363,"2324","",0,"","","",1,0,0,[],""],["frenk_t1-n2325",5,"Ahora que me ando paseando\na orillas de esta laguna,\nesperando a mi chatita,\nque siempre sale a la luna.",75,2,-1,90,"Soy de Zacatula",3,4,"ua",56,0,-1,0,364,364,"2325","",0,"","","",1,0,0,[],""],["frenk_t1-n2326",5,"Sentado en un banquillo,\nhe de esperar un torillo,\nque se ha robado\nmi corazoncillo.",75,2,-1,90,"Estrofa suelta",3,4,"io",228,0,-1,0,364,364,"2326","",0,"","","",1,0,0,[],""],["frenk_t1-n2327",5,"¡Oh!, qué noche tan serena\npara salirme a pasear\ncon mi chaparrita al lado\npor las orillas del mar.",75,2,-1,90,"Un dolor que tengo aquí",0,4,"a",21,0,-1,0,364,364,"2327","",0,"","","",1,0,0,[],""],["frenk_t1-n2329",5,"¡Ay!, qué feliz clavelito\ntiene en su huerto mi bien,\npues siempre que cerca pasa\nle da un besito en la sien.",75,2,-1,90,"Estrofa suelta",0,4,"e",242,0,-1,0,364,364,"2329","",0,"","","",1,0,0,[],""],["frenk_t1-n2330",5,"Amarillo es el oro (bien de mi vida),\ny así será;\nla prenda más querida (bien de mi vida),\ny aquí estará.",75,2,-1,90,"El pájaro cú",3,4,"a",9,0,-1,0,364,364,"2330","",0,"","","",2,0,0,[],""],["frenk_t1-n2331",5,"En la puerta de mi casa\nestá una piedra redonda,\ndonde se sienta mi linda chata\ncuando me voy a la ronda.",75,2,-1,90,"Estrofa suelta",3,4,"oa",182,0,-1,0,364,364,"2331","",0,"","","",24,0,0,[],""],["frenk_t1-n2332",5,"En la puerta de mi casa\ntengo una silla dorada,\ndonde se sienta mi novio\ncon la patita cruzada.",75,2,-1,90,"Estrofa suelta",0,4,"aa",49,0,-1,0,364,364,"2332","",0,"","","",24,0,0,[],""],["frenk_t1-n2333",5,"Arriba de aquel cerrito\ntengo un banquito de arena,\ndonde se sienta mi negra,\npico de garza morena.",82,2,7,90,"Costeña",0,4,"ea",-1,0,-1,0,365,365,"2333","",0,"","","",1,0,0,[],""],["frenk_t1-n2334",5,"Esta novia que traigo\nla traigo de Pisaflores\ny la vengo manteniendo\ncon el aroma de las flores.",81,2,6,90,"Estrofa suelta",0,4,"oe",5,0,-1,0,365,365,"2334","",0,"","","",1,0,0,[],""],["frenk_t1-n2335",5,"Con rositas? y claveles\nse formó un ramo de flores,\ny yo con esa güerita\nel mejor nido de amores.",75,2,-1,90,"Con un polvo y otro polvo",0,4,"oe",5,0,-1,0,365,365,"2335","",0,"","","",1,0,0,[],""],["frenk_t1-n2336",5,"En nuevo nido de flores\nvive una linda mujer,\nque no me da sinsabores,\nque me llena de placer\ny me roba mis amores.",75,2,-1,90,"Estrofa suelta",7,5,"oe",5,0,-1,0,365,365,"2336","",0,"","","",1,0,0,[],""],["frenk_t1-n2337",5,"Y estoy amando a umt bella,\nque no hay a quien no le cuadre;\nestoy tan engrido con ella,\nque si la beso me sabe\na la fruta de grosella\nque cogen para un jarabe.",75,2,-1,90,"La Llorona",9,6,"ae",131,0,-1,0,365,365,"2337","",0,"","","",1,0,0,[],""],["frenk_t1-n2338",5,"Del plátano el corazón,\ndel durazno la almendrita,\nde la manzana el sabor,\nde mi negra su boquita,\nque está buena para un dolor:\ncon besarla se me quita.",83,2,8,90,"Estrofa suelta",9,6,"ia",50,0,-1,0,365,365,"2338","",0,"","","",1,0,0,[],""],["frenk_t1-n2340",5,"Si la indita me da gusto,\nyo también se lo he de dar;\nsi ella se acuesta en el suelo,\ntambién yo me he de acostar.",75,2,-1,90,"La indita",0,4,"a",21,0,-1,0,365,365,"2340","",0,"","","",1,0,0,[],""],["frenk_t1-n2341",5,"Por gozar de su belleza\nmereciera yo el infierno;\nmerece la absolución\nese pedazo de cielo.",79,2,4,90,"Glosada en décimas",0,4,"eo",-1,0,-1,0,365,365,"2341","",0,"","","",1,0,0,[],""],["frenk_t1-n2342",5,"Ahora sí ya estoy contento\ny tengo mucha alegría,\nporque ya me está queriendo\nla que a mí me aborrecía.",83,2,8,90,"Estrofa suelta",0,4,"ia",0,0,-1,0,365,365,"2342","",0,"","","",2,0,0,[],""],["frenk_t1-n2344",5,"Alma mía de quien me dijo\nantes de romper la diana:\n“Arrímese, chaparrito,\nsin que lo mire mi mama.”",75,2,-1,90,"Corrido de Guanajuato",0,4,"aa",-1,0,-1,0,366,366,"2344","",0,"","","",1,0,0,[],""],["frenk_t1-n2345",5,"Qué bonito corre el agua\ncuando acaba de llover;\nasí correrá mi chata\ncuando yo la vengo a ver.",75,2,-1,90,"A mi chata",0,4,"e",20,0,-1,0,366,366,"2345","",0,"","","",5,0,0,[],""],["frenk_t1-n2346b",5,"A una mujer he querido\nun grado menos que a Dios;\nella me ha correspondido,\nde la manera que yo\nolvidarla no he podido.",75,2,-1,90,"La morena; El pájaro carpintero, El siquisirí",7,5,"io",101,0,-1,0,366,366,"2346b","",0,"","","",2,0,0,[],""],["frenk_t1-n2348",5,"Debajo de mi ventana\npasa las noches rondeándome\nun charrito muy valiente,\nque a mí me anda enamorando.",79,2,4,90,"Estrofa suelta",5,4,"ao",-1,0,-1,0,366,366,"2348","",0,"","","",1,0,0,[],""],["frenk_t1-n2349",5,"Tengo una mata de anís\ntraspuesta en un macetero;\nme he de hacer de la semilla,\naunque me cueste dinero:\ndel centro, nb de la orilla,\nde las que florean primero.",92,2,17,97,"Eres alta y delgadita",9,6,"eo",38,0,-1,0,367,367,"2349","",0,"","","",1,0,0,[],""],["frenk_t1-n2350",5,"La quiero, porque la quiero,\npoquito más que a mi vida,\ny aunque me la escondan bien,\nyo he de dar con la escondida.",75,2,-1,97,"La escondida",0,4,"ia",37,0,-1,0,367,367,"2350","",0,"","","",1,0,0,[],""],["frenk_t1-n2351",5,"Me gusta, y es un capricho\nque se me ha de conceder:\naunque por ella me maten,\nno le hace, ¿qué hemos de hacer?",75,2,-1,97,"La coculense",0,4,"e",20,0,-1,0,367,367,"2351","",0,"","","",1,0,0,[],""],["frenk_t1-n2352",5,"Esta morena me gusta,\nyo no la dejo soltera:\na capricho ha de ser mía,\ny aunque su madre no quiera",83,2,8,97,"¡Ay, qué cielo tan azul!",0,4,"ea",44,0,-1,0,367,367,"2352","",0,"","","",1,0,0,[],""],["frenk_t1-n2353",5,"Forastero en este pueblo,\nvengo aquí por vez primera;\nesta noche nos paseamos,\naunque su mamá no quiera.",78,2,3,97,"La canelera",0,4,"ea",44,0,-1,0,367,367,"2353","",0,"","","",1,0,0,[],""],["frenk_t1-n2354",5,"Dicen que me han de quitar\nel camino para el pozo:\nmentira, no me hacen nada\ncon mi cuchillo filoso.",78,2,3,97,"María, María",0,4,"oo",160,0,-1,0,367,367,"2354","",0,"","","",12,0,0,[],""],["frenk_t1-n2355",5,"Dicen que me han de matar\npor el amor de María:\nmentira, no me hacen nada,\nson pollos de mala cría.",75,2,-1,97,"María, María",0,4,"ia",0,0,-1,0,367,367,"2355","",0,"","","",20,0,0,[],""],["frenk_t1-n2356",5,"Por una mujer casada\nme dicen que he de morir:\nmentiras, no me hacen nada,\nsi ella me quiere seguir.",75,2,-1,97,"Por una mujer casada",1,4,"i",157,0,-1,0,368,368,"2356","",0,"","","",1,0,0,[],""],["frenk_t1-n2358",5,"Me he de comer un durazno\nde los lugares de Puebla;\nyo a Juanita me la llevo,\naunque a mi tierra no vuelva.",75,2,-1,97,"La Juanita",0,4,"ea",-1,0,-1,0,368,368,"2358","",0,"","","",3,0,0,[],""],["frenk_t1-n2359",5,"Dicen que me han de quitar\nla vereda de la estancia:\nla vereda quitarán,\npero yo me llevo a Pancha.",75,2,-1,97,"Pancha",0,4,"aa",-1,0,-1,0,368,368,"2359","",0,"","","",12,0,0,[],""],["frenk_t1-n2360",5,"Esa prieta me la llevo:\nya tengo la edad cumplida;\nesa prieta me la llevo,\naunque me cueste la vida.",75,2,-1,97,"El somb/emo",1,4,"ia",37,0,-1,0,368,368,"2360","",0,"","","",4,0,0,[],""],["frenk_t1-n2361",5,"¡Qué bonito sombrerito\nque rueda la cuesta abajo!\nÉsa prieta me la llevo,\naunque me cueste trabajo.",75,2,-1,97,"El sombrerito",0,4,"ao",168,0,-1,0,368,368,"2361","",0,"","","",5,0,0,[],""],["frenk_t1-n2365",5,"Principiando el mes de enero\nyo la vengo a enamorar,\ny aunque sus padres no quieran,\nme la tengo que llevar.",75,2,-1,97,"Las campanitas",0,4,"a",21,0,-1,0,368,368,"2365","",0,"","","",1,0,0,[],""],["frenk_t1-n2366",5,"Ya salió la luna hermosa\ncon sus banderas volando;\nyo me he de llevar a Mariquita,\naunque sus padres se queden llorando.",87,2,12,97,"Estrofa suelta",3,4,"ao",33,0,-1,0,369,369,"2366","",0,"","","",3,0,0,[],""],["frenk_t1-n2370",5,"Lo que sí les aseguro\nque me la voy a llevar,\npara que no crean que es yerba\ny se vayan a enyerbar.",101,2,26,97,"Chaparrita de los naranjos’1",0,4,"a",21,0,-1,0,369,369,"2370","",0,"","","",5,0,0,[],""],["frenk_t1-n2371",5,"¡Qué bonito sombrerito,\ncon sus listones por dentro!\nEsa prieta me la llevo\nsi se me logra el intento.",103,2,28,97,"El sombrerito",0,4,"eo",-1,0,-1,0,369,369,"2371","",0,"","","",5,0,0,[],""],["frenk_t1-n2372",5,"¡Qué bonito sombrerito,\ncon su listón carmesí!\nEsa prieta me la llevo\ncuando me vaya de aquí.",103,2,28,97,"El sombrerito",0,4,"i",23,0,-1,0,369,369,"2372","",0,"","","",5,0,0,[],""],["frenk_t1-n2375",5,"El lucero ya ha salido,\nya es hora de platicar;\nhoy me llevo a mi chatita\nal otro lado del mar.",75,2,-1,97,"Las ventanasJ",0,4,"a",21,0,-1,0,370,370,"2375","",0,"","","",1,0,0,[],""],["frenk_t1-n2376",5,"Me voy, mas les aseguro\nque me la voy a llevar,\ny solitos nos iremos\npor el mundo a navegar.",89,2,14,97,"Chaparrita de los naranjos",0,4,"a",21,0,-1,0,370,370,"2376","",0,"","","",1,0,0,[],""],["frenk_t1-n2377",5,"Esa prieta me la llevo\na tirones del rebozo,\npa que me dé muchos besos\ncon ese pico chismoso.",103,2,28,97,"El sombrerito",0,4,"oo",160,0,-1,0,370,370,"2377","",0,"","","",4,0,0,[],""],["frenk_t1-n2382",5,"Qué bonita chaparrita,\nme la tengo que llevar;\nesa linda coculense\nde mí no se ha de burlar.",75,2,-1,97,"La coculense",0,4,"a",21,0,-1,0,370,370,"2382","",0,"","","",5,0,0,[],""],["frenk_t1-n2383",5,"Esa negra chaparrita.\nsi se arrima, me la llevo;\ncon el tiempo lo verán\nsi es que no me la llevo.",75,2,-1,97,"Estrofa suelta",0,4,"eo",-1,0,-1,0,370,370,"2383","",0,"","","",1,0,0,[],""],["frenk_t1-n2384",5,"Mañana estaré en La Habana,\npasado mañana en Rusia,\ny si me pega la gana (¡ay, vida mía!),\nsaliéndome de mi estuche\nme voy a robar a Juana.",79,2,4,97,"El pájaro carpintero",7,5,"aa",4,0,-1,0,371,371,"2384","",0,"","","",1,0,0,[],""],["frenk_t1-n2385",5,"Voy a comprar un caballo,\nun caballo colorado,\npa pasearme con mi china\nde la reja al otro lado.",79,2,4,97,"El caballo",0,4,"ao",14,0,-1,0,371,371,"2385","",0,"","","",1,0,0,[],""],["frenk_t1-n2386",5,"Voy a salir a campear\nhasta San Luis Potosí,\na ver si puedo lazar\nun caballito que vi,\npara llevarme a pasear\nuna muchacha de aquí.",79,2,4,97,"El caballito",9,6,"i",23,0,-1,0,371,371,"2386","",0,"","","",3,0,0,[],""],["frenk_t1-n2387",5,"Voy a comprar mi caballo\npara llevarme a mi prieta\na pasar agua del mar:\n“¿Qué dices, prieta, te vas conmigo?”",84,2,9,97,"Tú sabías que era borracho",3,4,"io",-1,0,-1,0,371,371,"2387","",0,"","","",1,0,0,[],""],["frenk_t1-n2388",5,"Ya tengo listo el caballo\nen que me la he de llevar\ny un par de lindas pistolas\npa el que nos quiera alcanzar.",75,2,-1,97,"La coculense",0,4,"a",21,0,-1,0,371,371,"2388","",0,"","","",1,0,0,[],""],["frenk_t1-n2389",5,"Ensíllenme mi caballo,\ntambién mi yegua alazana;\nsi no me llevo a Teresa,\nsiempre me llevo a su hermana.",75,2,-1,97,"El ranchero afamado; Teresita",0,4,"aa",4,0,-1,0,371,371,"2389","",0,"","","",1,0,0,[],""],["frenk_t1-n2390",5,"En la punta de aquel cerro\ntengo una muía ensillada,\npara llevarme una muchacha\nde las enaguas coloradas.",83,2,8,97,"Estrofa suelta",0,4,"aa",-1,0,-1,0,371,371,"2390","",0,"","","",21,0,0,[],""],["frenk_t1-n2391",5,"La gente por dondequiera\nya sabe que soy matrero,\ny traigo en mi carrillera\ncincuenta balas de acero,\npara llevarme a mi prieta\nen mi caballo lucero.",75,2,-1,97,"El patas blancas",9,6,"eo",38,0,-1,0,371,371,"2391","",0,"","","",1,0,0,[],""],["frenk_t1-n2392",5,"[. Caballo de patas blancas\ncon herraduras de acero,\nhoy vas a brincar las trancas\nantes que salga el lucero\ny vas a llevar en ancas\na la mujer que yo quiero.",75,2,-1,97,"El patas blancas",9,6,"eo",38,0,-1,0,371,371,"2392","",0,"","","",1,0,0,[],""],["frenk_t1-n2394",5,"¡Ay!, por aquí pasó,\npor ahí se fue,\nuna niña hermosa\nasí como usted.",75,2,-1,93,"El pájaro cúl",0,4,"e",-1,0,-1,0,372,372,"2394","",0,"","","",1,0,0,[],""],["frenk_t1-n2397",5,"A orillas de la laguna\nvide el sol, vide la luna,\ny a mi amor que se paseaba\nsin esperanza ninguna.",75,2,-1,93,"Estrofa suelta",3,4,"ua",56,0,-1,0,372,372,"2397","",0,"","","",1,0,0,[],""],["frenk_t1-n2398",5,"Corté la flor de manzano\nporque se había resecado.\nEl sábado en la mañana\na este lugar he llegado.\n¡Ay, qué linda mexicana,\nyo nunca la había mirado!",83,2,8,93,"El siquisirí",9,6,"ao",14,0,-1,0,372,372,"2398","",0,"","","",1,0,0,[],""],["frenk_t1-n2399",5,"Yo nunca había llegado\na esta hermosa capital,\ndonde me hallé a una pelona\nque me invitó a vacilar.",75,2,-1,93,"En busca de Margarita",0,4,"a",-1,0,-1,0,372,372,"2399","",0,"","","",1,0,0,[],""],["frenk_t1-n2400",5,"Me subí a un devisadero\na devisar pa los planes,\ndevisé una trigueñita,\nnaguas negras con olanes.",84,2,9,93,"El tarada’'",0,4,"ae",444,0,-1,0,373,373,"2400","",0,"","","",2,0,0,[],""],["frenk_t1-n2401",5,"Me subí al cerro de Diana\na divisar para el plan;\nme encontré una chaparrita,\nnaguas negras con olán.",75,2,-1,93,"La sandía; La enlutadita",0,4,"a",147,0,-1,0,373,373,"2401","",0,"","","",1,0,0,[],""],["frenk_t1-n2403",5,"Un día encontré a una indita\npor el río camaroneando,\ny de verla tan sólita,\ny hasta me la fui llevando,\ndebajo de una sombrita,\nporque se estaba asoleando.",75,2,-1,93,"La indita",9,6,"ao",33,0,-1,0,373,373,"2403","",0,"","","",1,0,0,[],""],["frenk_t1-n2404",5,"Dicen que el gusto se acaba:\nyo no lo quisiera creer.\nPaseándome por la playa,\nmirando la agua correr,\nacercarte a la muralla,\ny mira qué linda mujer.",77,2,2,93,"El gusto",9,6,"e",20,0,-1,0,373,373,"2404","",0,"","","",1,0,0,[],""],["frenk_t1-n2405",5,"De verme tan arruinado,\na Playa María me fui;\na poco de haber llegado\nse hizo una mujer de mí;\nsería bien arreglado:\nmucho se lo agradecí.",83,2,8,93,"Zapateado",9,6,"i",23,0,-1,0,373,373,"2405","",0,"","","",2,0,0,[],""],["frenk_t1-n2406",5,"Andando en la mar pescando\ny andando en la mar pesqué\nuna niña de quince años,\ny de ella me enamoré.",75,2,-1,93,"El cuervo; Juliana; El pescado nadador",0,4,"e",77,0,-1,0,373,373,"2406","",0,"","","",1,0,0,[],""],["frenk_t1-n2407",5,"De ladrón traigo la fama,\nporque dicen que robé\nel corazón de una dama,\nque de ella me enamoré.",83,2,8,93,"La Sanmarqueña",1,4,"e",77,0,-1,0,373,373,"2407","",0,"","","",2,0,0,[],""],["frenk_t1-n2408",5,"Recuerdo de una mañana\ncuando yo estaba en recreo:\nhablando con una dama,\ntuve algún tiempo recreo\ncon una mujer serrana.",81,2,6,93,"La leva",7,5,"aa",-1,0,-1,0,374,374,"2408","",0,"","","",1,0,0,[],""],["frenk_t1-n2409",5,"Yo enamoré bailando\na una morena,\nle dejé mi capa\nde tierra buena.",75,2,-1,93,"Cielito lindo",6,4,"ea",59,0,-1,0,374,374,"2409","",0,"","","",1,0,0,[],""],["frenk_t1-n2410b",5,"Me enamoré jugando (cielito lindo i\na una Marta.\ncuando quise olvidarla (cielito lindo)\nya no podía.\nTenlo presente:\ndel nombre de María (cielito lindo)\nme acuerdo siempre.",75,2,-1,93,"Cielito lindo",4,7,"ee",-1,0,-1,0,374,374,"2410b","",0,"","","",1,0,0,[],""],["frenk_t1-n2411",5,"Navegando por el mar\nme cogieron prisionero,\nporque me metí a robar\nlas flores a un jardinero\ny no las supe cortar.",75,2,-1,93,"La morena",7,5,"a",21,0,-1,0,374,374,"2411","",0,"","","",1,0,0,[],""],["frenk_t1-n2412",5,"Al poco tiempo de andar,\ncorté la flor del acuyo;\nla corté en el mes de enero\ny lo digo con orgullo:\nsoy un muchacho sincero,\nque está llenito de orgullo:\nlo digo a lo caballero.",75,2,-1,93,"El cascabel",4,7,"eo",38,0,-1,0,374,374,"2412","",0,"","","",1,0,0,[],""],["frenk_t1-n2413",5,"Yo corté una florecita,\nque bastante engrandecía;\ncomo era tan bonita,\ntodo el mundo la quería,\ny nunca la hallé marchita:\nsiempre llena de alegría.",75,2,-1,93,"La morena; El siquisirí",9,6,"ia",-1,0,-1,0,374,374,"2413","",0,"","","",1,0,0,[],""],["frenk_t1-n2414",5,"Entré a la huerta y corté\nuna flor de Alejandría;\nno la corté muy al tronco,\npor los pagos de hoy en día.",84,2,9,93,"Estrofa suelta",0,4,"ia",0,0,-1,0,375,375,"2414","",0,"","","",2,0,0,[],""],["frenk_t1-n2415",5,"Al cortar una rosa\nyo me espiné,\npero el gusto que tuve\nes que la corté.",83,2,8,93,"La bamba",6,4,"e",77,0,-1,0,375,375,"2415","",0,"","","",1,0,0,[],""],["frenk_t1-n2416",5,"¡Ah!, qué aroma de esa flor,\nde esa rosita amarilla;\nel trabajo que me dio\npara verle la semilla;\npero no se me escapó:\nle corté hasta la ramilla.",75,2,-1,93,"Rosita amarilla",9,6,"ia",162,0,-1,0,375,375,"2416","",0,"","","",1,0,0,[],""],["frenk_t1-n2417",5,"Corté una calabacita\ncon la fuerza del verano,\ny como estaba tiernita,\nse me deshizo en las manos.\n¡Qué bonita trigueñita!,\n¡quién fuera su primo hermano!",75,2,-1,93,"Corté una calabacita; La madrugada; El pájaro cú",9,6,"ao",-1,0,-1,0,375,375,"2417","",0,"","","",1,0,0,[],""],["frenk_t1-n2418",5,"Corté las calabacitas\ncon el rocío del creciente,\ny como estaba tiernita,\nse me deshizo en los dientes.\n¡Qué bonita palomita,\nque yo era su pretendiente!",75,2,-1,93,"El siquisirí",9,6,"ee",-1,0,-1,0,375,375,"2418","",0,"","","",1,0,0,[],""],["frenk_t1-n2419",5,"Bonitos son los portales,\ndonde me iba yo a pasear,\ncon una de ojazos negros,\nque ya no puedo olvidar;\ncuando me acuerdo de ellos\nme dan ganas de llorar.",75,2,-1,93,"Bonito Tecalitlán",9,6,"a",21,0,-1,0,375,375,"2419","",0,"","","",1,0,0,[],""],["frenk_t1-n2420",5,"Yo quise una china, china,\nse llamaba Soledad;\nque de que me acuerdo de ella\nni hambre ni sueño me da.",75,2,-1,93,"Yo quise una china, china",0,4,"a",-1,0,-1,0,375,375,"2420","",0,"","","",1,0,0,[],""],["frenk_t1-n2421",5,"Donde quiera que me encuentre,\nsu retrato beso yo,\nporque la traigo presente\ny no la puedo olvidar;\ny aunque se burle la gente,\nno me avergüenzo al llorar.",75,2,-1,93,"Ábranse, que vengo herido",9,6,"a",21,0,-1,0,375,375,"2421","",0,"","","",1,0,0,[],""],["frenk_t1-n2422",5,"El edén que yo soñé\nfue el edén de mis amores;\nla virgen que yo adoré,\nel perfume de mil flores\nque dormido acaricié.",75,2,-1,93,"Estrofa suelta",7,5,"e",77,0,-1,0,376,376,"2422","",0,"","","",1,0,0,[],""],["frenk_t1-n2423",5,"Cuando a México me vine\nno podía reconocer;\nme hizo venir Margarita;\nla que me hace padecer.",75,2,-1,93,"En busca de Margarita",0,4,"e",20,0,-1,0,376,376,"2423","",0,"","","",1,0,0,[],""],["frenk_t1-n2424",5,"Bonitos están los nidos,\nque no me quedó ni duda;\ncuando me vine de allá\nme vine por ver mi Julia.",95,2,20,93,"La Julia",0,4,"ua",-1,0,-1,0,376,376,"2424","",0,"","","",1,0,0,[],""],["frenk_t1-n2425",5,"Qué bonito es el Quelite,\n¡bienhaya quien lo formó!,\nque por sus orillas tiene\nde quien acordarme yo.",75,2,-1,93,"El Quelite",0,4,"o",2,0,-1,0,376,376,"2425","",0,"","","",1,0,0,[],""],["frenk_t1-n2427",5,"Una mañanita alegre,\ndespués de que había llovido,\nme salí con mi chinita\ny al campo más divertido.",75,2,-1,93,"La mañanita alegre",0,4,"io",101,0,-1,0,376,376,"2427","",0,"","","",1,0,0,[],""],["frenk_t1-n2428",5,"De todos estos capires\nmi capire es el mejor,\nque a su sombra con mi chata\nhe platicado de amor.",75,2,-1,93,"El capire",0,4,"o",72,0,-1,0,376,376,"2428","",0,"","","",1,0,0,[],""],["frenk_t1-n2430",5,"Un día me fui a pasear\nhasta los llanos de Apan,\ny me puse a preparar\npara eantarle a mi chata.",75,2,-1,93,"Un día me fui a pasear",0,4,"aa",-1,0,-1,0,377,377,"2430","",0,"","","",1,0,0,[],""],["frenk_t1-n2431",5,"Dan la una, dan las dos,\ndan las tres de la mañana,\ncuando estaba con mi Julia\nplaticando en la ventana.",92,2,17,93,"La Julia; Serían las dos",0,4,"aa",4,0,-1,0,377,377,"2431","",0,"","","",1,0,0,[],""],["frenk_t1-n2432a",5,"Anoche por la ventana,\nplaticando con Carmita,\nme pidió que le cantara\nuna canción muy bonita\ny que no me dilatara.",75,2,-1,93,"El cascabel",7,5,"aa",57,0,-1,0,377,377,"2432a","",0,"","","",6,0,0,[],""],["frenk_t1-n2432b",5,"Anoche por la ventana,\nplaticando a mi chatita,\nme pidió que la cantara\nuna canción muy bonita,\ny que no me demorara\nme decía la pobrecita.",86,2,11,93,"El cascabel",9,6,"ia",50,0,-1,0,377,377,"2432b","",0,"","","",6,0,0,[],""],["frenk_t1-n2433b",5,"Anoche por la ventana,\nplaticando con Leonor,\nme pidió que le cantara\n“El cascabel” por menor\ny que no me demorara,\nme lo pedía por favor.",75,2,-1,93,"El cascabel",9,6,"o",72,0,-1,0,377,377,"2433b","",0,"","","",6,0,0,[],""],["frenk_t1-n2434",5,"Anoche por la ventana,\nplaticando con Leonor,\nquería que le cantara\n—en lugar de que la viera-\nun cantar ahí de noche\ny que no me demorara.",83,2,8,93,"El cascabel",9,6,"aa",57,0,-1,0,377,377,"2434","",0,"","","",6,0,0,[],""],["frenk_t1-n2435",5,"Anoche por la ventana,\nplaticando con Anita,\ny la regañó su mamá:\ny ¡ah, que vieja, tan maldita!\nOue si usted tiene lana,\nyo también tengo lanita.",79,2,4,93,"El cascabel",9,6,"ia",50,0,-1,0,378,378,"2435","",0,"","","",6,0,0,[],""],["frenk_t1-n2436",5,"Paseándome yo en Tampico,\na orillas de Miramar,\nme encontré con mi amorcito\nqueriéndome preguntar\nque si sabía “El taconcito”,\nque lo quería oír cantar.",79,2,4,93,"El taconcito; El bejuquito; El fandanguito",9,6,"a",21,0,-1,0,378,378,"2436","",0,"","","",1,0,0,[],""],["frenk_t1-n2437",5,"Un día salí de Tampico\npor el tren de Magozar;\naquí dejé mi amorcito,\ncuando queriendo llorar\ncantándome “El taconcito”.",75,2,-1,93,"El taconcito",7,5,"io",119,0,-1,0,378,378,"2437","",0,"","","",1,0,0,[],""],["frenk_t1-n2439",5,"En un espejo dorado\nse mira la niña mía,\ny después de haberse peinado,\nme dijo si no tenía\ny un chino mal arreglado.",79,2,4,93,"El bejuquito",7,5,"ao",14,0,-1,0,378,378,"2439","",0,"","","",1,0,0,[],""],["frenk_t1-n2441",5,"Del cielo cayó un pañuelo,\nen cada punta una flor;\nme lo mandó mi morena\npara limpiarme el sudor.",75,2,-1,93,"Estrofa suelta",0,4,"o",72,0,-1,0,378,378,"2441","",0,"","","",17,0,0,[],""],["frenk_t1-n2442",5,"Mi novia me dio una carta\ndonde me manda decir\nque si no la sigo amando,\nella prefiere el morir.",75,2,-1,93,"Tus ojitos",0,4,"i",157,0,-1,0,378,378,"2442","",0,"","","",1,0,0,[],""],["frenk_t1-n2444",5,"Al entrar en Valencia (cielito lindo)\nme corté un dedo;\nuna valencianita (bien de mi vida)\nme dio un pañuelo.",75,2,-1,93,"Cielito lindo",3,4,"eo",-1,0,-1,0,379,379,"2444","",0,"","","",1,0,0,[],""],["frenk_t1-n2445",5,"Al llegar a Tampico\nme corté un dedo;\nuna tampequeñita (cielito lindo)\nme dio un remedio;\ny con acierto;\nsi no me hubiera curado (cielito lindo),\nme hubiera muerto.",81,2,6,93,"Cielito lindo",4,7,"eo",88,0,-1,0,379,379,"2445","",0,"","","",1,0,0,[],""],["frenk_t1-n2446",5,"¡Ay!, qué bonita es la rosa,\nhojita color café,\nme la dio una tan hermosa (y oyes, queri-\npasando por San José. [da del alma),",81,2,6,93,"La rosa",3,4,"aa",-1,0,-1,0,379,379,"2446","",0,"","","",2,0,0,[],""],["frenk_t1-n2447",5,"¡Ay!, qué bonita es la rosa\nparece ser de alelía;\nme la dio una tan hermosa (y oyes, querida del alma),\nque se llamaba María.",75,2,-1,93,"La rosa",3,4,"ia",0,0,-1,0,379,379,"2447","",0,"","","",2,0,0,[],""],["frenk_t1-n2448",5,"Qué bonito frijolito,\ntan pintado y tan galán;\nme lo regaló una indita\nen la feria de San Juan.",75,2,-1,93,"El frijolito",0,4,"a",147,0,-1,0,379,379,"2448","",0,"","","",3,0,0,[],""],["frenk_t1-n2449",5,"Arriba de una garita\ncanta un pájaro mulato.\nY como era tan bonita,\nme dio su bello retrato\nadentro de una cajita,\npa mirarla a cada rato.",75,2,-1,93,"El siquisirí",9,6,"ao",19,0,-1,0,379,379,"2449","",0,"","","",1,0,0,[],""],["frenk_t1-n2450",5,"Una niña en un baile\nme dio su peine,\ny estar a la moda\ncomo una reina.",75,2,-1,93,"La Llorona",6,4,"ea",-1,0,-1,0,379,379,"2450","",0,"","","",6,0,0,[],""],["frenk_t1-n2451",5,"La leva que yo tenía\nde terciopelo morado,\nesa leva no era mía,\nme la regaló un soldado\nde esos de caballería.",77,2,2,93,"La leva",7,5,"ia",0,0,-1,0,379,379,"2451","",0,"","","",1,0,0,[],""],["frenk_t1-n2452",5,"Mi novia me dio un besito (Llorona),\ny en mi paladar quedó;\npero, ¡ay, qué beso tan dulce (Llorona)!,\nsiete días me duró.",83,2,8,93,"La Llorona’'",3,4,"o",2,0,-1,0,380,380,"2452","",0,"","","",1,0,0,[],""],["frenk_t1-n2453",5,"Me besaba en los cachetes\ncon sus labios de coral,\nme brindaba su ternura:\npara mí no hay otra igual.",75,2,-1,93,"Te he de amar y te he de amar",0,4,"a",1,0,-1,0,380,380,"2453","",0,"","","",1,0,0,[],""],["frenk_t1-n2454",5,"Es bonita “La azucena”,\n“La rosa” y “El fandanguito”.\nNo he sentido cosa buena\ncomo los dulces besitos\nque me diera esa morena.",75,2,-1,93,"La azucena; La Rosita; Estrofa suelta",7,5,"ea",59,0,-1,0,380,380,"2454","",0,"","","",1,0,0,[],""],["frenk_t1-n2456",5,"Oiga usted, señor platero,\n¿cuánta plata es menester\npara engarzar un besito\nque me ha dado una mujer?",75,2,-1,93,"Estrofa suelta",0,4,"e",20,0,-1,0,380,380,"2456","",0,"","","",1,0,0,[],""],["frenk_t1-n2460",5,"Buscando dónde acostarme,\nse me apagó la linterna;\nla fortuna, que encontré\nla cama de mi morena.",75,2,-1,93,"El jarabe tapatío",0,4,"ea",-1,0,-1,0,381,381,"2460","",0,"","","",1,0,0,[],""],["frenk_t1-n2461",5,"Una indita muy bonita\nde la mano me agarró,\nme llevó para su casa\ny en su cama me acostó.",75,2,-1,93,"La indita",0,4,"o",2,0,-1,0,381,381,"2461","",0,"","","",2,0,0,[],""],["frenk_t1-n2462",5,"A la orillita del río,\na la sombra de un pirú,\nsu querer fue todo mío\nuna mañanita azul.",75,2,-1,93,"La mujer ladina [",0,4,"u",-1,0,-1,0,381,381,"2462","",0,"","","",3,0,0,[],""],["frenk_t1-n2463",5,"Le regalé fruta de horno,\nun paño y un prendedor,\ny atrás de la nopalera\nle dimos gusto al amor.",86,2,11,93,"La nopalera",0,4,"o",72,0,-1,0,381,381,"2463","",0,"","","",1,0,0,[],""],["frenk_t1-n2464",5,"Detrás de la nopalera\nsu columpio le ponía,\ny acostadita en mis brazos,\n¡con cuánto amor la mecía!",86,2,11,93,"La nopalera",0,4,"ia",0,0,-1,0,381,381,"2464","",0,"","","",1,0,0,[],""],["frenk_t1-n2465",5,"Despedida no les doy,\nporque no la traigo aquí:\nse la di sólo a mi Julia\ncuando en sus brazos me vi.",75,2,-1,93,"La Julia",0,4,"i",23,0,-1,0,381,381,"2465","",0,"","","",3,0,0,[],""],["frenk_t1-n2466",5,"Una linda huachinanga,\nque llevo yo,\nque se vino tras de mí\ncon tierno amor.",75,2,-1,93,"La paloma",6,4,"o",-1,0,-1,0,381,381,"2466","",0,"","","",1,0,0,[],""],["frenk_t1-n2467",5,"El domingo por la noche,\ncuando el baile comenzó,\nyo le hablé a una chaparrita,\ny ella me correspondió.",89,2,14,93,"Chaparrita de los naranjos",0,4,"o",2,0,-1,0,381,381,"2467","",0,"","","",1,0,0,[],""],["frenk_t1-n2468",5,"Mi Juanita me decía\nque nos fuéramos a León,\ny que allí me vestiría\nde chaqueta y pantalón.",75,2,-1,93,"La Juanita",1,4,"o",31,0,-1,0,381,381,"2468","",0,"","","",1,0,0,[],""],["frenk_t1-n2469",5,"“Ya repican las campanas:\n¿no me quieres, vida mía?”\nElla me dijo que sí,\npero yo no lo creía.",75,2,-1,93,"Las campanitas",0,4,"ia",0,0,-1,0,381,381,"2469","",0,"","","",3,0,0,[],""],["frenk_t1-n2470",5,"“¡Ay, qué bonito!”,\nle dije a mi corazón;\n“¿Qué dices, mi alma, nos vamos\npara la Villa de León?”",75,2,-1,93,"El cuervo",3,4,"o",31,0,-1,0,382,382,"2470","",0,"","","",4,0,0,[],""],["frenk_t1-n2471",5,"A la media vuelta\nle dije a una chata:\n“Véngase conmigo,\nque acá está la plata.”",92,2,17,93,"El pasacalle",0,4,"aa",74,0,-1,0,382,382,"2471","",0,"","","",2,0,0,[],""],["frenk_t1-n2472",5,"A la media vuelta\nle dije a una chula:\n“Véngase conmigo,\nque soy de Cocula.”",75,2,-1,93,"El pasacalle",0,4,"ua",547,0,-1,0,382,382,"2472","",0,"","","",2,0,0,[],""],["frenk_t1-n2473",5,"Soy soldado de levita\nde esos de caballería.\nYo le dije a mi negrita:\n“Y abrázame, vida mía,\ny a ver si así se me quita\ny esta terrible agonía.”",79,2,4,93,"La leva’’",9,6,"ia",-1,0,-1,0,382,382,"2473","",0,"","","",7,0,0,[],""],["frenk_t1-n2476",5,"Al pie de una hermosa higuera\nyo hallé mi china lavando:\nle dije que me quisiera,\ny me contestó llorando:\n“¿Qué no ves la polvadera\nde lo que me está pasando?”",79,2,4,93,"Zapateado",9,6,"ao",33,0,-1,0,382,382,"2476","",0,"","","",1,0,0,[],""],["frenk_t1-n2478",5,"Torito de la barranca,\nsi quieres comer salitre,\nsolito brinca las trancas.\n¡Apa, toro!, que allá va;\nmi pecho con gusto se halla;\nyo vivo en una casita\npor fuera de la muralla.",75,2,-1,93,"El toro",4,7,"aa",249,0,-1,0,383,383,"2478","",0,"","","",2,0,0,[],""],["frenk_t1-n2482",5,"Pasó un domingo que iba por agua,\ny me dijo quedo: “Prietito lindo,\nya florecieron los arrayanes,\nahora te cumplo lo que ya sabes.”",75,2,-1,93,"Los arrayanes",3,4,"ae",-1,0,-1,0,383,383,"2482","",0,"","","",1,0,0,[],""],["frenk_t1-n2484",5,"Andando en el mar pescando\nme dio sueño y me dormí;\nentonces pasó mi amor\ny me dijo: “¿Qué haces aquí?\nLevántate, vámonos,\nporque mucho me acuerdo de ti.”",83,2,8,93,"Estrofa suelta",9,6,"i",23,0,-1,0,383,383,"2484","",0,"","","",1,0,0,[],""],["frenk_t1-n2489a",5,"Una paloma al volar\nsu dorado pico abría;\ntodos dicen que me hablaba,\npero yo no le entendía.",75,2,-1,93,"La palomita; El palomo",0,4,"ia",0,0,-1,0,384,384,"2489a","",0,"","","",8,0,0,[],""],["frenk_t1-n2490a",5,"Un cigarro de papel\ny un vasito de agua fría\ny un beso de una mujer\nme mantiene todo el día,\naunque no haiga de comer.",75,2,-1,93,"La presumida1'",7,5,"e",20,0,-1,0,385,385,"2490a","",0,"","","",2,0,0,[],""],["frenk_t1-n2490c",5,"Amigo[s], no lo han de creer\ncon qué me mantuve un día:\ncon cigarros de papel,\nuna cervecita fría\ny besos de una mujer\nque mucho a mí me quería.",77,2,2,93,"El taconcito",9,6,"ia",0,0,-1,0,385,385,"2490c","",0,"","","",1,0,0,[],""],["frenk_t1-n2491",5,"Yo tenía mi totolito,\nantes sí, pero ahora, ¿cuándo?\nMi padre me regañaba\nporque yo estaba adorando.",75,2,-1,93,"El totolito1’",0,4,"ao",33,0,-1,0,385,385,"2491","",0,"","","",1,0,0,[],""],["frenk_t1-n2492",5,"Mi padre a mí me regaña\nporque yo amo a una soltera;\n“¡ay!”, le contesté con maña:\n“¡Ay!, padre, ¡si usted me viera\ncuando la estoy abrazando!\n¡Que hasta usted la quisiera!”",75,2,-1,93,"El querreque",9,6,"ea",44,0,-1,0,385,385,"2492","",0,"","","",1,0,0,[],""],["frenk_t1-n2493",5,"Una morena me dijo\nque la llevara a J amapa,\ny yo le dije: “Morena,\nmejor te llevo a Jalapa;\nallá te compro gardenias\ny tus aretes de plata.”",75,2,-1,93,"La morenaJ",9,6,"aa",-1,0,-1,0,385,385,"2493","",0,"","","",3,0,0,[],""],["frenk_t1-n2496",5,"Me dijo a mí una mujer\nque con ella no me ofenda:\nyo la debo de querer\nel tiempo que me convenga,\nporque es bonito tener\nama, y que otro la mantenga.",79,2,4,93,"La morena",9,6,"ea",407,0,-1,0,386,386,"2496","",0,"","","",1,0,0,[],""],["frenk_t1-n2497",5,"Vo enamoré una morena,\nque era todo mi querer;\nse me sentaba en las piernas\ny me empezaba a morder:\ntodavía traigo las señas,\nsi quieren, vénganme a ver.",75,2,-1,93,"La morena; El Balajú",9,6,"e",20,0,-1,0,386,386,"2497","",0,"","","",1,0,0,[],""],["frenk_t1-n2498",5,"Antes de haber un quebranto,\nme besaba y me mordía;\ny llegó el cariño a tanto,\nque hasta su mamá decía:\n“¿Dónde pondré yo este santo\npara verlo todo el día?”",75,2,-1,93,"Deleadita de cintura; El pájaro carpintero",9,6,"ia",0,0,-1,0,386,386,"2498","",0,"","","",1,0,0,[],""],["frenk_t1-n2501",5,"Yo conocí a una mujer\nque se llamaba Calista;\ntanto me llegó a querer,\nque se pasaba de lista,\nporque ella quería tener\nun chamaco guitarrista.",86,2,11,93,"Estrofa suelta",9,6,"ia",352,0,-1,0,387,387,"2501","",0,"","","",1,0,0,[],""],["frenk_t1-n2502",5,"Yo tuve a una de mujer\nque se llamaba Leonor;\ncuando no la iba yo a ver\nme venía a ver al vapor,\nporque deseaba tener\nun chamaco cantador.",75,2,-1,93,"El pajaro carpintero; El quern e",9,6,"o",72,0,-1,0,387,387,"2502","",0,"","","",1,0,0,[],""],["frenk_t1-n2503",5,"Yo tuve una de mujer\nque se llamaba Tomasa;\ntanto me llegó a querer,\nque me iba a ver a mi casa,\nporque deseaba tener\nun chamaco de mi raza.",75,2,-1,93,"El pájaro carpintero; La morena; El querreque",9,6,"aa",307,0,-1,0,387,387,"2503","",0,"","","",1,0,0,[],""],["frenk_t1-n2504",5,"Yo enamoré una casada\nporque me simpatizó,\ny me dijo entusiasmada:\n“Lo mismo me encuentro yo,\nno más que no diga nada,\nporque entonces sí que no.”",82,2,7,93,"La Malagueña",9,6,"o",2,0,-1,0,387,387,"2504","",0,"","","",2,0,0,[],""],["frenk_t1-n2505",5,"Yo enamoré una casada\ncon un versito de amor,\ny me dijo entusiasmada:\n“Si quiere, le haré el favor,\nno más que no diga nada,\nporque se pierde el honor.”",82,2,7,93,"La Malagueña",9,6,"o",72,0,-1,0,387,387,"2505","",0,"","","",2,0,0,[],""],["frenk_t1-n2506",5,"Le pregunté a una bonita\nsi quería lavarme el paño,\ny contestó la maldita:\n“Si usted quiere, hasta lo baño,\npero muy de mañanita,\nporque tarde le hace daño.”",86,2,11,93,"El venadito; El pájaro carpintero; La rosita arribeña; Estrofa suelta",9,6,"ao",40,0,-1,0,387,387,"2506","",0,"","","",1,0,0,[],""],["frenk_t1-n2508",5,"Yo pretendí a una mujer,\nque era bonita y rica;\nme dijo: “Te he de querer;\nel ser pobre nada indica,\npero deja de beber:\nel beber te perjudica.”",83,2,8,93,"El trompo",9,6,"ia",174,0,-1,0,388,388,"2508","",0,"","","",4,0,0,[],""],["frenk_t1-n2513",5,"Una que yo bien quería\ndondequiera la encontraba;\nella se me resistía\nluego que la enamoraba,\nhasta que, por fin, un día\nme dijo que me lo daba.",75,2,-1,93,"Estrofa suelta",9,6,"aa",28,0,-1,0,388,388,"2513","",0,"","","",1,0,0,[],""],["frenk_t1-n2514",5,"A una linda sanmarqueña\nse le murió su marido,\ny como lo quería tanto,\nse conforma hora conmigo.",75,2,-1,93,"La Sanmarqueña",0,4,"io",-1,0,-1,0,388,388,"2514","",0,"","","",1,0,0,[],""],["frenk_t1-n2516",5,"A mi vecina de enfrente\nse le murió su marido,\ny por mérito accidente\ntuvo que dormir conmigo:\n¡vecina tan buena gente,\ny yo tan compadecido!",86,2,11,93,"El jarabe loco; La morena; Estrofa suelta",9,6,"io",-1,0,-1,0,389,389,"2516","",0,"","","",1,0,0,[],""],["frenk_t1-n2517",5,"Caminito del santuario\nfui al velorio con la viuda,\ny durante el novenario\nle presté toda mi ayuda\n—como soy humanitario—,\ngozando de su hermosura.",81,2,6,93,"La leva",9,6,"ua",-1,0,-1,0,389,389,"2517","",0,"","","",1,0,0,[],""],["frenk_t1-n2518",5,"Una mujer que era hermosa\ncon un puñal se mató,\ny llegó a ser tan piadosa\nque en sus brazos me arrojó.\n¡Qué mujer tan cariñosa,\nque hasta de mamar me dio!",81,2,6,93,"Las flores",9,6,"o",2,0,-1,0,389,389,"2518","",0,"","","",1,0,0,[],""],["frenk_t1-n2519",5,"Me acuerdo cuando nací\ndebajo de un platanar;\ncuando llegó la partera\nyo ya sabía enamorar.",75,2,-1,98,"Estrofa suelta",0,4,"a",21,0,-1,0,392,392,"2519","",0,"","","",1,0,0,[],""],["frenk_t1-n2520",5,"Celoso siempre lo he sido,\nceloso siempre he de ser;\ncuando mi madre me crió\nme enseñó a tener mujer.",75,2,-1,98,"El celoso; Estrofa suelta",0,4,"e",20,0,-1,0,392,392,"2520","",0,"","","",1,0,0,[],""],["frenk_t1-n2521a",5,"Si porque me ves chiquito\npiensas que no sé de amores,\nyo soy como el huizachito:\ncreciendo y echando flores.",75,2,-1,98,"Chaparrita de los naranjos; Uy, la; Estrofa suelta Autógrafo",1,4,"oe",5,0,-1,0,392,392,"2521a","",0,"","","",1,0,0,[],""],["frenk_t1-n2522",5,"Del cielo cayó un pañuelo\nsalpicado de colores;\nno porque me vean chiquito\ndirán que no sé de amores.",75,2,-1,98,"La Sanmarqueña",0,4,"oe",5,0,-1,0,392,392,"2522","",0,"","","",17,0,0,[],""],["frenk_t1-n2523",5,"Nací más libre que el sol,\nmi tierra es el mundo entero,\npa mí onde quiera hay amor,\ny en cada amor yo me muero.",75,2,-1,98,"El mundo es mío",0,4,"eo",38,0,-1,0,393,393,"2523","",0,"","","",1,0,0,[],""],["frenk_t1-n2524",5,"La estrellita voló\na la tumba del maigero;\néchenme tiros de amor,\nde mi corazón los quiero.",78,2,3,98,"El estillero",0,4,"eo",38,0,-1,0,393,393,"2524","",0,"","","",2,0,0,[],""],["frenk_t1-n2525",5,"A la agencia del amor\nsólo a mí me han de llamar;\n..................... del amor he sido:\n¡ay, no me puedo apartar!",75,2,-1,98,"La Malagueña curreña",0,4,"a",21,0,-1,0,393,393,"2525","",0,"","","",1,0,0,[],""],["frenk_t1-n2526",5,"¡Qué bonitas son las flores\ndel palo de residón!\n¡Si vieras a mis amores\nde qué materiales son!\nDe emociones y candores\nse llena mi corazón.",83,2,8,98,"Zapateado",9,6,"o",31,0,-1,0,393,393,"2526","",0,"","","",1,0,0,[],""],["frenk_t1-n2527",5,"Pa el que muere de pasión\nel sepulcro es el descanso;\npor eso yo no me canso:\nle doy gusto al corazón\npa ver si la gloria alcanzo.",81,2,6,98,"La pasión",7,5,"ao",548,0,-1,0,393,393,"2527","",0,"","","",1,0,0,[],""],["frenk_t1-n2528",5,"Aunque en amor no soy nuevo,\ntampoco me estoy pasando;\nyo soy como el pan de huevo:\nen cualquier boca me ablando;\ny al verla sola me atrevo\ny le pregunto: “¿qué hubo?, ¿cuándo?",75,2,-1,98,"¿Quihubo?, ¿cuándo?",9,6,"ao",33,0,-1,0,393,393,"2528","",0,"","","",1,0,0,[],""],["frenk_t1-n2530",5,"Hay cosas en la vida (cielito lindo)\nque son tan bellas:\namar a las mujeres (cielito lindo)\ny es una de ellas.\nYo soy testigo:\ndespués de Dios (cielito lindo),\npara ellas vivo.",79,2,4,98,"Cielito lindo",4,7,"io",-1,0,-1,0,393,393,"2530","",0,"","","",1,0,0,[],""],["frenk_t1-n2531",5,"Cantando yo mis canciones\nles puedo decir aquí\nque de todas mis pasiones\nla más grande es la mujer;\nno necesito escoger\nentre todas mis pasiones.",75,2,-1,98,"Yo agarro parejo",9,6,"oe",-1,0,-1,0,393,393,"2531","",0,"","","",1,0,0,[],""],["frenk_t1-n2532",5,"Tengo una maña maldita:\nes pensar en las mujeres,\npues su amor me solicita,\ny aumentan mis placeres,\nencantada morenita.",77,2,2,98,"El gusto",7,5,"ia",50,0,-1,0,394,394,"2532","",0,"","","",1,0,0,[],""],["frenk_t1-n2533",5,"Yo tengo amor de aumento,\nque crece con gran placeres;\nque con mucho sentimiento\ny crecidos pareceres,\nya se despide un atento\nservidor de las mujeres.",83,2,8,98,"Zapateado",9,6,"ee",55,0,-1,0,394,394,"2533","",0,"","","",1,0,0,[],""],["frenk_t1-n2534",5,"Tengo ganas de placeres\ny también de echar un grito,\npara decir: “¡Qué rebonito\nes el amor de las mujeres!”",75,2,-1,98,"El fandanguero",11,4,"ee",55,0,-1,0,394,394,"2534","",0,"","","",1,0,0,[],""],["frenk_t1-n2535a",5,"Ea llevo en el corazón\ny grabada en la memoria,\nporque las mujeres son\nmás bonitas que la gloria.",75,2,-1,98,"Mis palabras se desatan",1,4,"oa",126,0,-1,0,394,394,"2535a","",0,"","","",1,0,0,[],""],["frenk_t1-n2537",5,"Corté la flor de la vid\nporque la vide en un ramo.\nDe las mujeres nací,\npor eso es que las aclamo;\ny si ellas no ven por mí,\nentonces ¿y a cómo estamos?",75,2,-1,98,"El siquisirí",9,6,"ao",-1,0,-1,0,394,394,"2537","",0,"","","",2,0,0,[],""],["frenk_t1-n2538",5,"Cuánta joven hay aquí,\nreunida en este placer;\naunque no sean para mí,\nyo las debo de querer,\nporque recuerdo que fui\nnacido de una mujer",83,2,8,98,"Zapateado, La guacamaya; El siquisirí",9,6,"e",20,0,-1,0,395,395,"2538","",0,"","","",1,0,0,[],""],["frenk_t1-n2539",5,"El defecto que yo tengo\nes querer a las mujeres,\ny esta canción que yo canto\nse llama “Al cabo no puedes”.",75,2,-1,98,"Soy virgencita",0,4,"ee",-1,0,-1,0,395,395,"2539","",0,"","","",1,0,0,[],""],["frenk_t1-n2540",5,"¡Ay, Dios!, de las Monjas de agua,\nde los Frailes de Belén;\nlas quiero porque me nace,\nno porque me paguen bien.",83,2,8,98,"Estrofa suelta",0,4,"e",242,0,-1,0,395,395,"2540","",0,"","","",1,0,0,[],""],["frenk_t1-n2542",5,"Soy soldado de los verdes,\nguarda de las tres garitas,\nme han puesto de alcabalero\nde las muchachas bonitas.",75,2,-1,98,"Corrido de Guanajuato",0,4,"ia",258,0,-1,0,395,395,"2542","",0,"","","",1,0,0,[],""],["frenk_t1-n2543a",5,"Soy soldado de levita\ndel Ranchito de San Ciro;\ncuando la vista me falla,\nsólo a las muchachas miro.",75,2,-1,98,"Estrofa suelta",0,4,"io",222,0,-1,0,395,395,"2543a","",0,"","","",7,0,0,[],""],["frenk_t1-n2544",5,"Yo a las mujeres bonitas\nlas quiero con devoción,\nque buenas o malas son\nlas dueñas de nuestras cuitas:\nlas buenas por su candor\ny las otras por malditas.",75,2,-1,98,"Las rejegas",9,6,"ia",258,0,-1,0,396,396,"2544","",0,"","","",1,0,0,[],""],["frenk_t1-n2545",5,"Al gallo con espolón\nni la gallina lo quiere;\naquí está mi corazón\npa las ingratas mujeres.",75,2,-1,98,"Estrofa suelta",0,4,"ee",-1,0,-1,0,396,396,"2545","",0,"","","",1,0,0,[],""],["frenk_t1-n2546",5,"Tratándose de mujeres,\ntodas me encantan;\nles regalo mis quereres,,\nque son tan finos—como la manta.",75,2,-1,98,"La manta",3,4,"aa",-1,0,-1,0,396,396,"2546","",0,"","","",1,0,0,[],""],["frenk_t1-n2547",5,"Hora sí, mi primavera,\npara mí todas las que hay;\ntodititas las querencias\npara mí serán primavera.",83,2,8,98,"El cascabel",5,4,"ea",-1,0,-1,0,396,396,"2547","",0,"","","",1,0,0,[],""],["frenk_t1-n2548",5,"Corazón de Santa Anita,\nya de mí no hagas memoria;\ncomo he sido tan maldito,\npor una me gustan todas:\nde todas quiero tantito,\npara quedar como en la gloria",83,2,8,98,"Estrofa suelta",9,6,"oa",-1,0,-1,0,396,396,"2548","",0,"","","",1,0,0,[],""],["frenk_t1-n2549",5,"Todos me murmurarán\nporque quiero a las bonitas;\ny no sé si lo sabrán,\nque yo las quiero a toditas.\nÉste es el mero “caimán”\nde Tampico a Tamaulipas.",81,2,6,98,"El caiman",9,6,"ia",-1,0,-1,0,396,396,"2549","",0,"","","",1,0,0,[],""],["frenk_t1-n2550",5,"Soy como el león de la montaña,\nque siempre anda agradecido,\nque cuando veo gente extraña,\nno la corro, antes la cuido;\nno se me quita la maña\nde querer a cuantas miro.",79,2,4,98,"El aguanieve; Quiéreme, chiquita",9,6,"io",-1,0,-1,0,396,396,"2550","",0,"","","",1,0,0,[],""],["frenk_t1-n2551",5,"Dicen que ya el amor\nya no es pecado,\nporque Nuestro Señor\nlo ha perdonado.\n¡Qué buena vida!\nAsí podré querer\na cuantas vea.",75,2,-1,98,"Cielito lindo",4,7,"ea",-1,0,-1,0,396,396,"2551","",0,"","","",1,0,0,[],""],["frenk_t1-n2552",5,"Ariles, mi bien, ariles,\nariles de mi Alvarado;\ntodo el que tiene hermanas\nhay que decirle cuñado.",79,2,4,98,"El Balajú",0,4,"ao",14,0,-1,0,397,397,"2552","",0,"","","",5,0,0,[],""],["frenk_t1-n2553",5,"Soy del puerto de Alvarado,\nle canto de buena gana;\nyo le toco mi jarana\nporque soy muy ilustrado;\ntodo aquel que tiene hermana\nhay que decirle cuñado.",79,2,4,98,"El pájaro cú",9,6,"ao",14,0,-1,0,397,397,"2553","",0,"","","",1,0,0,[],""],["frenk_t1-n2555",5,"En mi casa me regañan\nporque a las mujeres quiero-,\nyo trabajaré con maña\npara así hacer dinero,\npues las mujeres se hallan\ncomo yeguas en potrero.",76,2,1,98,"Antonia",9,6,"eo",38,0,-1,0,397,397,"2555","",0,"","","",1,0,0,[],""],["frenk_t1-n2556",5,"Si yo fuera marinero,\notra vida yo me diera:\nun amor en cada puerto\npor lo menos yo tuviera.",75,2,-1,98,"El gato",0,4,"ea",44,0,-1,0,397,397,"2556","",0,"","","",1,0,0,[],""],["frenk_t1-n2557",5,"Yo le pregunté a Cupido\nque con cuántas se contenta,\ny me respondió afligido:\n“Amigo, ni con cincuenta:\nson tantas las que he tenido,\nque hasta ya perdí la cuenta.'",83,2,8,98,"El Cupido; La morena",9,6,"",-1,0,-1,0,397,397,"2557","",0,"","","",8,0,0,[],""],["frenk_t1-n2558",5,"Yo le pregunté a Cupido\nque con cuánto se conformaba,\ny me contestó afligido,\ny me dijo: “Ya con nada,\nque de tantas que he tenido,\nno se consigue con nada”",83,2,8,98,"El Cupido",9,6,"aa",-1,0,-1,0,397,397,"2558","",0,"","","",8,0,0,[],""],["frenk_t1-n2559",5,"Yo y todos los zopilotes\nandamos a la deriva:\nellos buscan carne muerta\ny yo busco carne viva.\n¡Ay, Dios! ¿qué tendrán las viejas,\nque sin ellas moriría?\n¡Ay, viejas, viejitas mías!",75,2,-1,98,"El hombre alegre",4,7,"ia",-1,0,-1,0,398,398,"2559","",0,"","","",1,0,0,[],""],["frenk_t1-n2560",5,"Ariles, mi bien, ariles,\nariles de la bajada;\ntambién me gusta beber\ndel agua dulce y salada.",75,2,-1,98,"El Balajú",0,4,"aa",49,0,-1,0,398,398,"2560","",0,"","","",5,0,0,[],""],["frenk_t1-n2561",5,"Me dicen el Chuparrosa\nporque ando de flor en flor:\nme gusta probar las mieles\nde diferentes sabor.",75,2,-1,98,"El Chuparrosa",0,4,"o",72,0,-1,0,398,398,"2561","",0,"","","",1,0,0,[],""],["frenk_t1-n2562",5,"Soy un gato que, maullando\ny recorriendo azoteas,\nando buscando gatitas,\nya sean bonitas o feas.",75,2,-1,98,"Glosada en décimas",0,4,"ea",67,0,-1,0,398,398,"2562","",0,"","","",1,0,0,[],""],["frenk_t1-n2563",5,"Me gustan las españolas\ny también las te La Habana;\ny por áhi and., la bola (¡ay vida nuaí)\nque dicen que quiero a Juana,\ny, mentira, quiero a Lola.",75,2,-1,98,"El pájaro carpintero",7,5,"oa",321,0,-1,0,398,398,"2563","",0,"","","",1,0,0,[],""],["frenk_t1-n2566",5,"No he recibido desengaños\nen las cosas del amor:\nno me importa el tamaño ni el color;\njovencitos de quince años\nme los recetó el doctor.",86,2,11,98,"Estrofa suelta",7,5,"o",72,0,-1,0,398,398,"2566","",0,"","","",1,0,0,[],""],["frenk_t1-n2567",5,"En cuestión de los amores\nyo jamás soy exigente:\nme da igual dos solterones\no también cuatro de a veinte.",75,2,-1,98,"Chiquita, pero picosa",0,4,"ee",-1,0,-1,0,398,398,"2567","",0,"","","",1,0,0,[],""],["frenk_t1-n2568",5,"Yo soy como el gavilán\nque anda por las nopaleras;\nme gustan las jovencitas,\nlas de quince primaveras.",79,2,4,98,"El gavilán",0,4,"ea",103,0,-1,0,399,399,"2568","",0,"","","",2,0,0,[],""],["frenk_t1-n2570",5,"Las solteras idolatro,\nlas casadas me fascinan;\npero para mantenerlas\ncreo que ni una me domina.",86,2,11,98,"Estrofa suelta",0,4,"ia",-1,0,-1,0,399,399,"2570","",0,"","","",1,0,0,[],""],["frenk_t1-n2571",5,"¡Ay, qué bonito es el mundo\npa el que la sabe gozar!\nSi son viudas o solteras,\npara mí que son igual.",75,2,-1,98,"El gallo jaspeado",0,4,"a",-1,0,-1,0,399,399,"2571","",0,"","","",1,0,0,[],""],["frenk_t1-n2572",5,"Aguanieve no me moja\ndebajo de esta enramada.\nMe gusta fumar en hoja\nel amor de una casada;\nlo que teñe se me antoja,\nlo que es lo que la trovada",75,2,-1,98,"La leva",9,6,"aa",49,0,-1,0,399,399,"2572","",0,"","","",1,0,0,[],""],["frenk_t1-n2573a",5,"¡Cuánto me gustan las olas,\nlas solas, no las casadas!\nPero más a mí me gustan\ncuando las tengo abrazadas.",92,2,17,98,"Las olas de la laguna",0,4,"aa",282,0,-1,0,399,399,"2573a","",0,"","","",2,0,0,[],""],["frenk_t1-n2574a",5,"Una noche muy oscura\nme iba a matar un granizo.\nMucho me gustan las viudas\nporque se atrancan macizo\nen la cama de carrizo.",81,2,6,98,"Estrofa suelta",7,5,"io",95,0,-1,0,399,399,"2574a","",0,"","","",4,0,0,[],""],["frenk_t1-n2575",5,"Yo soy como los cuchitos,\nque ya no les cuadra el maiz;\nya no me gustan las gringas:\nhora consumo del pais.",82,2,7,98,"Indita del almal",0,4,"a",58,0,-1,0,400,400,"2575","",0,"","","",1,0,0,[],""],["frenk_t1-n2576",5,"Mucho me gustan las indias\nporque son trabajadoras;\nhacen mi cotón cuyuchi\ny mi calzón a la moda.",83,2,8,98,"Indita del alma; Estrofa suelta",0,4,"oa",-1,0,-1,0,400,400,"2576","",0,"","","",2,0,0,[],""],["frenk_t1-n2579",5,"De las gruesas a las delgadas\nme gustan las delgaditas,\nporque son muy codiciadas,\ncomo el perro a la cuita",83,2,8,98,"Estrofa suelta",0,4,"ia",-1,0,-1,0,400,400,"2579","",0,"","","",1,0,0,[],""],["frenk_t1-n2580",5,"Si es chaparrita,\nsoy chaparrito,\ny si es grandota,\n¡qué más me da!\nMe les hago a la medida\npara mayor facilidad.",75,2,-1,98,"La burra elotera",9,6,"a",-1,0,-1,0,400,400,"2580","",0,"","","",1,0,0,[],""],["frenk_t1-n2581",5,"Me gusta tirar con honda\nporque con flecha varea;\nme gustan las chaparritas\nporque ya les sé la idea.",83,2,8,98,"La Sanmarqueña",0,4,"ea",54,0,-1,0,400,400,"2581","",0,"","","",1,0,0,[],""],["frenk_t1-n2582",5,"Del cielo cayó un pañuelo\nbordado de campanitas;\nyo porque soy soltero\nme gustan las chaparritas.",75,2,-1,98,"Estrofa suelta",0,4,"ia",258,0,-1,0,400,400,"2582","",0,"","","",17,0,0,[],""],["frenk_t1-n2583",5,"De la blanca y la morena\n¿cuál será la más mejor?\nMe gusta agarrar parejo;\n¡ay, qué lindo es el amor!",75,2,-1,98,"Conchitas y caracoles",0,4,"o",72,0,-1,0,401,401,"2583","",0,"","","",1,0,0,[],""],["frenk_t1-n2584",5,"A mí no me gustan las güeras\nporque no quitan las penas,\na mí me gustan las blancas,\nlo mismo que las morenas.",84,2,9,98,"Estrofa suelta",0,4,"ea",62,0,-1,0,401,401,"2584","",0,"","","",1,0,0,[],""],["frenk_t1-n2585",5,"Las blancas son muy bonitas\ny las morenas, hermosas:\nguardan su amor\nentre las rosas.",85,2,10,98,"Los barandales",3,4,"oa",61,0,-1,0,401,401,"2585","",0,"","","",1,0,0,[],""],["frenk_t1-n2586",5,"Las blancas las hizo Dios\ny las morenas, el cielo;\nmorena mía,\ndame un consuelo.",91,2,16,98,"Los barandales",3,4,"eo",10,0,-1,0,401,401,"2586","",0,"","","",1,0,0,[],""],["frenk_t1-n2587",5,"Soy el más enamorado,\nlas güeritas me dislocan,\nlas morenas me han dejado\nsiempre un buen sabor de boca.",75,2,-1,98,"El fandanguero",0,4,"oa",-1,0,-1,0,401,401,"2587","",0,"","","",1,0,0,[],""],["frenk_t1-n2588",5,"Mujeres hay de a montón,\nlas güeras son de mi agrado,\nlas prietas ¡qué chulas son!\nY por ser enamorado\npadezco del corazón.",77,2,2,98,"El sacamandú",7,5,"o",31,0,-1,0,401,401,"2588","",0,"","","",1,0,0,[],""],["frenk_t1-n2589",5,"De los tres colores que hay\nel trigueño es el mejor;\nlo blanco se lleva el agua\ny lo colorado el sol.",83,2,8,98,"Estrofa suelta",0,4,"o",-1,0,-1,0,401,401,"2589","",0,"","","",1,0,0,[],""],["frenk_t1-n2590",5,"En unas balanzas de oro\nvoy a pesar a mi dueña,\na ver si pesan las güeras\nlo que pesan las trigueñas.",75,2,-1,98,"El tejón",0,4,"ea",-1,0,-1,0,401,401,"2590","",0,"","","",1,0,0,[],""],["frenk_t1-n2597",5,"Entre las flores, las azucenas\nson las que llaman a mi atención;\n¡ay!, las muchachas que son morenas\nlas que prefiere mi corazón.",78,2,3,98,"Las morenitas",3,4,"o",31,0,-1,0,403,403,"2597","",0,"","","",1,0,0,[],""],["frenk_t1-n2598",5,"Soy águila real del monte,\ngavilancillo del viento;\nsoy amante de las morenas\ny también a las que encuentro,\ncon dinero, no con señas:\namigos, por áhi va el cuento.",83,2,8,98,"Estrofa suelta, Chiquitita te vas criando’",9,6,"eo",-1,0,-1,0,403,403,"2598","",0,"","","",1,0,0,[],""],["frenk_t1-n2599",5,"Ando cerca de un pretil,\ncantaba yo “La azucena”.\nSe me olvidaba decir:\nqué lindas son las morenas\ncuando se ven de perfil.",79,2,4,98,"La azucena",7,5,"i",-1,0,-1,0,403,403,"2599","",0,"","","",1,0,0,[],""],["frenk_t1-n2600",5,"Las morenitas son muy queridas,\ny por morenas las quiero yo;\nporque las güeras ya no se pintan,\nya no las quiero ni de pilón.",78,2,3,98,"Las morenitas",3,4,"o",-1,0,-1,0,403,403,"2600","",0,"","","",1,0,0,[],""],["frenk_t1-n2601",5,"A las morenas bonitas,\nuna corona imperial,\ny a las güeras revolcadas,\nuna penca de nopal.",75,2,-1,98,"Estrofa suelta, El vacilón",0,4,"a",1,0,-1,0,403,403,"2601","",0,"","","",1,0,0,[],""],["frenk_t1-n2602",5,"¡Ay, qué torres tan delgadas!,\n¡cómo no las tumba el aire!\n¡Cuánta muchacha bonita\npara el hijo de mi madre!",79,2,4,98,"La higuera; Las ventanas",0,4,"ae",-1,0,-1,0,403,403,"2602","",0,"","","",2,0,0,[],""],["frenk_t1-n2603",5,"¡Cuánta muchacha bonita,\nhijas del Eterno Padre!\nDame, Señor, una de ellas,\npara que mi alma se salve.",75,2,-1,98,"Rezos humorísticos",0,4,"ae",-1,0,-1,0,403,403,"2603","",0,"","","",1,0,0,[],""],["frenk_t1-n2604",5,"Ya viene la luna nueva\nrodeada de campanitas,\nla vienen repicando\ncuatro muchachas bonitas.",83,2,8,98,"Estrofa suelta",0,4,"ia",258,0,-1,0,403,403,"2604","",0,"","","",2,0,0,[],""],["frenk_t1-n2614",5,"Àhi se ven las rancheritas\ncomo durazno en sazón;\nde cuando en cuando viuditas\nmás sabrosas que el melón.",79,2,4,98,"El framboyán",1,4,"o",31,0,-1,0,405,405,"2614","",0,"","","",1,0,0,[],""],["frenk_t1-n2615",5,"Que me toquen el violín,\nque me toquen el violón;\n¡qué bonitas son las niñas,\ny qué reteguapas son!",79,2,4,98,"El guapo",0,4,"o",31,0,-1,0,405,405,"2615","",0,"","","",3,0,0,[],""],["frenk_t1-n2616",5,"Que me toquen el violín,\nque me lo sigan tocando;\n¡qué bonitas, qué bonitas\ntodas las que están bailando!",79,2,4,98,"El Ahualulco; El guapo; El tilingolingo",0,4,"ao",33,0,-1,0,405,405,"2616","",0,"","","",3,0,0,[],""],["frenk_t1-n2617",5,"¡Ay!, pollas de Yatipán,\nqué chulas se están poniendo;\nquisiera ser gavilán\npara estármelas comiendo.",77,2,2,98,"El gavilán",1,4,"eo",52,0,-1,0,405,405,"2617","",0,"","","",1,0,0,[],""],["frenk_t1-n2618",5,"¡Ay!, muchachas yatipecas,\n¡ay!, cómo me están gustando;\nque si Dios vida me presta,\nme las llevo hasta Durango.",77,2,2,98,"El gavilán",0,4,"ao",-1,0,-1,0,405,405,"2618","",0,"","","",1,0,0,[],""],["frenk_t1-n2619",5,"Yo quisiera ser arriero\nde la muía de Pomposo;\nquiero ser atajador\nde las que bajan al pozo.",79,2,4,98,"Los arrieros",0,4,"oo",156,0,-1,0,405,405,"2619","",0,"","","",1,0,0,[],""],["frenk_t1-n2620",5,"Yo ya me voy para Taxco,\nvoy a ver a las taxqueñas,\na ver si las desatasco\no me atasco allá con ellas.",82,2,7,98,"La Sanmarqueña",0,4,"ea",-1,0,-1,0,405,405,"2620","",0,"","","",1,0,0,[],""],["frenk_t1-n2622",5,"Mañana me voy pa abajo,\na ver a las abajeñas,\na ver si me hacen corral\no me encorralo con ellas.",75,2,-1,98,"Las abajeñas",0,4,"ea",-1,0,-1,0,406,406,"2622","",0,"","","",2,0,0,[],""],["frenk_t1-n2623",5,"Me vine de las Palmitas\ny pasé por ’1 Algodón;\ndejé muchachas bonitas\nque alegran el corazón;\nlas llevé hasta Tamaulipas.",81,2,6,98,"La Malagueña",7,5,"ia",-1,0,-1,0,406,406,"2623","",0,"","","",1,0,0,[],""],["frenk_t1-n2624",5,"Si te fueras a la Puebla,\nme traerás una poblana;\nno te la pido con trenzas,\nsino con chongo de lana.",75,2,-1,98,"Las calabazas",0,4,"aa",4,0,-1,0,406,406,"2624","",0,"","","",1,0,0,[],""],["frenk_t1-n2625",5,"Del cielo cayó un pañuelo\ntodo lleno de alfileres;\nmuchachas más lindas,\nyo les traigo mis quereres.",77,2,2,98,"Estrofa su ¡ta",0,4,"ee",55,0,-1,0,406,406,"2625","",0,"","","",17,0,0,[],""],["frenk_t1-n2631",5,"Voy a adornar la carreta (mamá)\ncon ramitas de laurel,\npara que bajen a misa (mamá)\nlas hijas del coronel.",87,2,12,98,"El carretero",3,4,"e",32,0,-1,0,407,407,"2631","",0,"","","",2,0,0,[],""],["frenk_t1-n2632",5,"¡Ea!, muchachas salineras,\nvestidas de azul y verde,\n¿qué señas les dejaré\npara que de mí se acuerden?",83,2,8,98,"Estrofa suelta",0,4,"ee",-1,0,-1,0,407,407,"2632","",0,"","","",1,0,0,[],""],["frenk_t1-n2633",5,"Frijolito, frijolito,\nojitos de papel verde;\nyo les canto “El frijolito”,\npara que de mí se acuerden.",75,2,-1,98,"El frijolito",0,4,"ee",-1,0,-1,0,407,407,"2633","",0,"","","",2,0,0,[],""],["frenk_t1-n2634",5,"Cuando me encuentro solito\npaseando allá por la sierra,\ncon un placer infinito\na las muchachas de mi tierra\nles dedico “El bejuquito”.",77,2,2,98,"El bejuquito",7,5,"io",119,0,-1,0,407,407,"2634","",0,"","","",2,0,0,[],""],["frenk_t1-n2635",5,"Invito yo a la función\na viejas y muchachitas,\ny si vienen las bonitas,\nyo las quiero para mí.",93,2,18,98,"Estrofa suelta",5,4,"i",-1,0,-1,0,407,407,"2635","",0,"","","",1,0,0,[],""],["frenk_t1-n2636",5,"Ahora les voy a cantar\na las niñas por bonitas,\na las viejas por viejitas\ny a mi amor por olvidar.",75,2,-1,98,"Maldita sea mi suerte",11,4,"a",21,0,-1,0,407,407,"2636","",0,"","","",1,0,0,[],""],["frenk_t1-n2637",5,"Éstas son las mañanitas\nque cantaba el Rey David,\ny a las muchachas bonitas\nse las cantamos aquí.",75,2,-1,98,"Las mañanitas",0,4,"i",-1,0,-1,0,407,407,"2637","",0,"","","",2,0,0,[],""],["frenk_t1-n2638",5,"Buenas noches, señoritas,\nmuy buenas noches, señores;\na todas las florecitas\nde rostros cautivadores\nvan las trovas más bonitas\nde estos pobres cantadores.",79,2,4,98,"El siquisirí",9,6,"oe",5,0,-1,0,407,407,"2638","",0,"","","",3,0,0,[],""],["frenk_t1-n2647",5,"Que me toquen el violín,\nque me toquen la jarana;\n¡qué bonitas, qué bonitas\nlas hijas de doña Juana!",79,2,4,98,"El Ahualulco; El guapo",0,4,"aa",4,0,-1,0,409,409,"2647","",0,"","","",3,0,0,[],""],["frenk_t1-n2648",5,"¡Ay, tilín, tilín, tilín!\n¡Ay, tolón, tolón, tolón!\n¡Qué bonitas, qué bonitas\nlas hijas de don Simón!",79,2,4,98,"El tilingo-lingo",0,4,"o",31,0,-1,0,409,409,"2648","",0,"","","",1,0,0,[],""],["frenk_t1-n2649",5,"Allá arriba brama un toro,\nabajo lo están oyendo;\nlas hijas del caporal\n¡qué buenas se están poniendo!",82,2,7,98,"La cuera",0,4,"eo",52,0,-1,0,409,409,"2649","",0,"","","",2,0,0,[],""],["frenk_t1-n2650",5,"¿Qué es aquello que relumbra\nen aquel camino real?\nSon las hijas del calero,\nque me vienen a encontrar.",75,2,-1,98,"El calero; Los ojitos de Pancha",0,4,"a",-1,0,-1,0,409,409,"2650","",0,"","","",8,0,0,[],""],["frenk_t1-n2651",5,"Allá vienen bajando\nlas hijas del caporal,\nvienen en briosos caballos\nde la Hacienda del Nopal:\n¡quién pudiera besarles\nsu boquita de coral!\nUn día de primavera\nbajaron al corralón,\nme miraron con sus ojitos\ny destrozaron mi corazón.",75,2,-1,98,"Las hijas del caporal",18,10,"o",31,0,-1,0,409,409,"2651","",0,"","","",1,0,0,[],""],["frenk_t1-n2652a",5,"De esas que están bailando\nlas dos me parecen bien:\nuna parece una rosa\ny la otra parece un clavel.",75,2,-1,98,"Estrofa suelta, Ahora pregunto, pregunto",0,4,"e",-1,0,-1,0,409,409,"2652a","",0,"","","",1,0,0,[],""],["frenk_t1-n2653",5,"De esas dos que andan bailando\n¿cuál le gusta, valedor?\nUna parece una rosa,\nla otra parece un lucero.",75,2,-1,98,"El jarabe",5,4,"eo",-1,0,-1,0,410,410,"2653","",0,"","","",1,0,0,[],""],["frenk_t1-n2654",5,"Como pintor dibujé\ndos florecitas de parra;\ny me dieron de quehacer\ncomo el que de amor se amarra\ncon cariños del querer.",80,2,5,98,"Estrofa suelta",7,5,"e",20,0,-1,0,410,410,"2654","",0,"","","",1,0,0,[],""],["frenk_t1-n2655",5,"Una Juana y otra Juana\ndos Juanitas vi nacer:\nuna que traigo en el alma\ny otra que empecé a querer.",83,2,8,98,"La Juanita",0,4,"e",20,0,-1,0,410,410,"2655","",0,"","","",2,0,0,[],""],["frenk_t1-n2656",5,"Estoy queriendo una rubia\ny una morena también;\nno hallo por cuál decidirme:\nlas dos me quieren muy bien;\nlucero, ¿qué me aconsejas\na mí que me quieres bien?",95,2,20,98,"La rubia y la morena",9,6,"e",-1,0,-1,0,410,410,"2656","",0,"","","",1,0,0,[],""],["frenk_t1-n2659",5,"¡Ay!, dile que sí,\ndile que cuándo se baña,\nque eso de querer a dos\nno se me quita la maña.",75,2,-1,98,"El durazno",0,4,"aa",213,0,-1,0,410,410,"2659","",0,"","","",2,0,0,[],""],["frenk_t1-n2660",5,"Cómo me gusta Mariana\ny me gusta Concepción;\npero les juro que pronto\nyo les daré mi amor\na la que de veras me ame\ncon todo su corazón.",75,2,-1,98,"En una hermosa mañanal",9,6,"o",-1,0,-1,0,411,411,"2660","",0,"","","",1,0,0,[],""],["frenk_t1-n2662",5,"Yo soy el gavilancillo,\nque ando por la nopalera,\na ver si puedo agarrar\nuna paloma hechicera.",75,2,-1,98,"El gavilancillo",0,4,"ea",44,0,-1,0,411,411,"2662","",0,"","","",2,0,0,[],""],["frenk_t1-n2663",5,"Yo soy un gavilancillo\nque ando por entre las peñas,\na ver si puedo agarrar\nel amor de una trigueña.",92,2,17,98,"El gavilancillo",0,4,"ea",-1,0,-1,0,411,411,"2663","",0,"frenk_t4","","",12,0,0,[],""],["frenk_t1-n2664",5,"Este es el gavilancillo\nque anda por aquí volteando,\nporque se quiere llevar\nuna polla del fandango.",78,2,3,98,"El gavilancillo",3,4,"ao",-1,0,-1,0,411,411,"2664","",0,"","","",2,0,0,[],""],["frenk_t1-n2666",5,"Yo les digo a mis amigos,\ny les digo la verdad,\nque a la chica le falta tiempo\ny a la grande le sobra edad;\nsi no quiere la de en medio,\npos me llevo a su mamá.",75,2,-1,98,"Estrofa suelta",9,6,"a",-1,0,-1,0,412,412,"2666","",0,"","","",3,0,0,[],""],["frenk_t1-n2667",5,"Aquí me siento a cantar\ncon ternura y con aplomo,\na ver si puedo lograr\nla mujer del mayordomo.",75,2,-1,98,"Aquí me siento a cantar",1,4,"oo",349,0,-1,0,412,412,"2667","",0,"frenk_t4","","",10,0,0,[],""],["frenk_t1-n2668",5,"Aquí me siento a cantar\nencima de este cuartillo,\na ver si puedo lograr\nla mujer de Ligerillo.",96,2,21,98,"Aquí me siento a cantal",1,4,"io",228,0,-1,0,412,412,"2668","",0,"frenk_t4","","",10,0,0,[],""],["frenk_t1-n2669",5,"Aquí me siento a cantar\nencima de este rasero,\na ver si puedo lograr\nla mujer del cabretero.",96,2,21,98,"Aquí me siento a cantar",1,4,"eo",38,0,-1,0,412,412,"2669","",0,"frenk_t4","","",10,0,0,[],""],["frenk_t1-n2670",5,"Yo ya me voy, ¿para dónde iré?\nVoy a buscar un nuevo amor,\nvoy a buscar una fiel amante;\n¿en dónde la encontraré?",75,2,-1,98,"Los paseos de Santa Anita; La Juanita",3,4,"e",77,0,-1,0,412,412,"2670","",0,"","","",1,0,0,[],""],["frenk_t1-n2672",5,"Voy a ir por los caminos,\npa ver si puedo encontrar\nun amor que sea solito,\npero que no pague mal.",81,2,6,98,"La muía de siete cuartas",0,4,"a",-1,0,-1,0,412,412,"2672","",0,"","","",1,0,0,[],""],["frenk_t1-n2674",5,"Me salí al camino real,\na ver si veía pasar\na un amor que sea solito,\npara poderme casar.",75,2,-1,98,"La muía de siete cuartas",0,4,"a",21,0,-1,0,413,413,"2674","",0,"","","",1,0,0,[],""],["frenk_t1-n2675",5,"Puse mi bandera negra\nen las puertas de un cuartel.\nComo ya no tengo suegra,\ndeseos tengo de tener:\nel corazón se me alegra\ncuando miro a una mujer.",81,2,6,98,"La íeval",9,6,"e",20,0,-1,0,413,413,"2675","",0,"","","",1,0,0,[],""],["frenk_t1-n2676",5,"Tulancingo tengo andado,\nMéxico, tienda por tienda;\nnunca he podido olvidar\namor que no tenga prenda,\npues yo me quiero casar,\nantes que el gustito venga.",81,2,6,98,"El gusto",9,6,"ea",-1,0,-1,0,413,413,"2676","",0,"","","",1,0,0,[],""],["frenk_t1-n2677",5,"Ya sabes que no me rajo:\nni gozar ni padecer;\nquiero mujer y trabajo\ny a quien poder mantener.",75,2,-1,98,"El jarabe",1,4,"e",20,0,-1,0,413,413,"2677","",0,"","","",2,0,0,[],""],["frenk_t1-n2678",5,"Estoy del alma sentido,\nsentido para querer,\nquerer y no ser engrido,\nquerido de una mujer (¡ay, de la Rosa,\npero que sea sin marido. [Rosita!),",76,2,1,98,"La Rosita",7,5,"ia",-1,0,-1,0,413,413,"2678","",0,"","","",1,0,0,[],""],["frenk_t1-n2679",5,"Soy de mero Sinaloa,\ndonde revientan las olas,\ny busco una que ande sola\ny que no tenga marido,\npa no estar comprometido\ncuando reviente la bola.",95,2,20,98,"El sinaloense",9,6,"oa",321,0,-1,0,413,413,"2679","",0,"","","",1,0,0,[],""],["frenk_t1-n2680",5,"Con el corazón contricto\nhe de amar una soltera;\npues ya se va tu negrito,\nhermosa flor extranjera;\nsoy de purito San Juanito,\ny jurisdicción de Llera.",101,2,26,98,"La azucena",9,6,"ea",44,0,-1,0,413,413,"2680","",0,"","","",1,0,0,[],""],["frenk_t1-n2681",5,"Soy como el agua del río,\nque no consiente basura;\nquiero a una muchacha\nque tenga por amor\ntodita la hermosura.",81,2,6,98,"Estrofa suelta",7,5,"ua",17,0,-1,0,413,413,"2681","",0,"","","",6,0,0,[],""],["frenk_t1-n2682",5,"Yo quiero una mariposa\nque se endulce con mis flores;\npobre o rico, será suyo\nel amor de mis amores.",75,2,-1,98,"Uy, uy, mariposa",0,4,"oe",5,0,-1,0,414,414,"2682","",0,"","","",1,0,0,[],""],["frenk_t1-n2683",5,"Ando en busca de una novia\npues mi pecho está vacante,\npero quiero sea pelona\nporque es muy interesante.",75,2,-1,98,"Ya no lloverá, pelonas",0,4,"ae",47,0,-1,0,414,414,"2683","",0,"","","",1,0,0,[],""],["frenk_t1-n2684",5,"Ya me voy al corralero,\nsabe Dios si volveré;\ntengo que traerme una china\nde esas que usan el tupé.",75,2,-1,98,"Válgame Dios de los cielos",0,4,"e",77,0,-1,0,414,414,"2684","",0,"","","",1,0,0,[],""],["frenk_t1-n2685",5,"El primer amor que tenga (mamá)\nha de ser un carbonero;\ny aunque me tizne el vestido (máma),\npero con mucho dinero.",85,2,10,98,"El carbonero",3,4,"eo",38,0,-1,0,414,414,"2685","",0,"","","",1,0,0,[],""],["frenk_t1-n2686",5,"Voy a buscar a una dama,\nque diario me está cuadrando,\nque sea de piernas velludas\ny su frente relumbrona;\nque tenga su empeine grande\npara estárselo palmeando.",83,2,8,98,"Estrofa suelta",9,6,"ao",33,0,-1,0,414,414,"2686","",0,"","","",1,0,0,[],""],["frenk_t1-n2688",5,"La presumida me dio\ncuatro reales pa vivir;\nque me consiguiera yo\nuna muchacha bonita:\nasí la quisiera yo.",79,2,4,98,"La presumida",7,5,"o",-1,0,-1,0,414,414,"2688","",0,"","","",1,0,0,[],""],["frenk_t1-n2690",5,"Yo saqué un cartón de palos\ny arreglado con compás.\nMe dicen que soy muy malo,\ny de eso no soy capaz;\nmi corazón' es regalo\nde las muchachas no más.",75,2,-1,99,"El querreque. Estrofa suelta",9,6,"a",51,0,-1,0,415,415,"2690","",0,"","","",1,0,0,[],""],["frenk_t1-n2691",5,"Corté la flor de residón\nal pasar por la cañada.\nYo soy de una condición,\nque la mujer que me agrada\nle he de dar mi corazón,\naunque me quede sin nada.",83,2,8,99,"El siquisirí",9,6,"aa",49,0,-1,0,415,415,"2691","",0,"","","",2,0,0,[],""],["frenk_t1-n2692",5,"Soy como el maguey frondoso,\ntraspuesto en una ladera;\nal querer soy generoso\ny olvido hasta que me muera;\nmi pecho no es cauteloso,\nni trata de esa manera.",87,2,12,99,"La Malagueña mixteca",9,6,"ea",44,0,-1,0,415,415,"2692","",0,"","","",1,0,0,[],""],["frenk_t1-n2693",5,"Yo soy aquel no traidor,\npor la Calle Real me vivo;\ny a la que le tengo amor\nbien temprano se lo digo,\nporque soy madrugador\ny no me quedo dormido.",75,2,-1,99,"El pájaro cú",9,6,"io",-1,0,-1,0,415,415,"2693","",0,"","","",1,0,0,[],""],["frenk_t1-n2694",5,"Nunca a la mujer desprecio,\nporque la quiero, la adoro,\ny si me titula necio,\nmás le suplico y le lloro,\nhasta conseguir su aprecio.",81,2,6,99,"Estrofa suelta",7,5,"eo",276,0,-1,0,415,415,"2694","",0,"","","",1,0,0,[],""],["frenk_t1-n2695",5,"Buscando voy lo que quiero\npor lagunas y montañas;\nsi una morena prefiero,\nle busco y me doy mis mañas;\nsoy un gavilán cerrero.",77,2,2,99,"El gavilán",7,5,"eo",38,0,-1,0,415,415,"2695","",0,"","","",1,0,0,[],""],["frenk_t1-n2696",5,"Yo soy el aventurero,\nel mundo me importa poco;\ncuando una mujer me gusta,\nme gusta a pesar de todo.",75,2,-1,99,"El aventurero",0,4,"oo",-1,0,-1,0,416,416,"2696","",0,"","","",3,0,0,[],""],["frenk_t1-n2697",5,"Soy como el toro palomo\ncuando estaba en la opulencia;\nno salgo, pero me asomo\nadonde está mi querencia.",75,2,-1,99,"El toro palomo",1,4,"ea",46,0,-1,0,416,416,"2697","",0,"","","",1,0,0,[],""],["frenk_t1-n2698",5,"Soy un gavilán pollero\nque habita por las barrancas;\nsiendo por la que yo quiero,\nhasta me brinco las trancas;\naunque sea yo muy negro,\na mí me gustan las blancas.",79,2,4,99,"El siquisiií",9,6,"aa",443,0,-1,0,416,416,"2698","",0,"","","",1,0,0,[],""],["frenk_t1-n2699",5,"Soy un gavilán del norte\ncon las alas coloradas;\na mí no me asusta el sueño,\nni me hacen las desveladas,\ny por la mujer que quiero,\naunque muera a puñaladas.",75,2,-1,99,"Eres alta y delgadita; Estrofa suelta",9,6,"aa",282,0,-1,0,416,416,"2699","",0,"","","",1,0,0,[],""],["frenk_t1-n2700",5,"Soy el gavilán,\nbusco qué comer,\ny si no me dan,\nyo lo agarraré.",77,2,2,99,"El gavilán del Sur",0,4,"e",-1,0,-1,0,416,416,"2700","",0,"","","",1,0,0,[],""],["frenk_t1-n2703a",5,"Soy torito de alta cumbre,\nchiquito, pero lucido;\ncuando bajo a Pinotepa\nconocido es mi bramido.",75,2,-1,99,"Estrofa suelta",0,4,"io",101,0,-1,0,416,416,"2703a","",0,"","","",2,0,0,[],""],["frenk_t1-n2704",5,"Soy fandanguero sin tambora\ny borrachito perdido;\nde contento me desmayo\ncuando a las mujeres miro;\nsoy becerro que por mayo\nbajo y les echo un bramido.",75,2,-1,99,"Soy fandanguero",9,6,"io",-1,0,-1,0,417,417,"2704","",0,"","","",1,0,0,[],""],["frenk_t1-n2705",5,"Soy torito y soy galán,\nla gente lo disimula;\nmuchachas, bajen al plan,\nahora que vengo en mi muía;\nesto dice mi refrán:\nque este negro no recula.",83,2,8,99,"Estrofa suelta",9,6,"ua",547,0,-1,0,417,417,"2705","",0,"","","",1,0,0,[],""],["frenk_t1-n2707a",5,"Señora, yo soy muy pobre,\npobre, pero generoso;\ny soy como el espinazo:\npelado, pero sabroso.",75,2,-1,99,"El espinado; Estrofa suelta",0,4,"oo",160,0,-1,0,417,417,"2707a","",0,"","","",1,0,0,[],""],["frenk_t1-n2708",5,"Mi vida, ya estoy aquí,\nya vengo muy valoroso;\n¿qué dirán los de mi casa?\n“Ya llegó el escandaloso.”",87,2,12,99,"Estrofa suelta",0,4,"oo",160,0,-1,0,417,417,"2708","",0,"","","",1,0,0,[],""],["frenk_t1-n2709",5,"Soy vaquero del carrizo\ny caporal del cardón;\nla mujer que yo acaricio\nme la recargo en la acción,\nhasta el sombrero me arrisco\ny pa darle tentación.",81,2,6,99,"El toro requesón",9,6,"o",31,0,-1,0,417,417,"2709","",0,"","","",1,0,0,[],""],["frenk_t1-n2710",5,"Yo soy más fino que un peso\nantes que suene [en] el suelo;\nla mujer que me da un beso\nmuy al pronto se lo trueno,\npero luego recio, recio,\nantes que venga su dueño.",75,2,-1,99,"El aguanieve",9,6,"eo",-1,0,-1,0,417,417,"2710","",0,"","","",2,0,0,[],""],["frenk_t1-n2711",5,"Soy colmenero de amor,\nque corto cualquier panal;\npor el aire y por el suelo\nsigo la colmena real.",79,2,4,99,"Glosada en décimas",0,4,"a",1,0,-1,0,418,418,"2711","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t1-n2712",5,"Por una calle me voy\ny por la otra doy la vuelta;\nla muchacha que me quiera\nque deje la puerta abierta.",75,2,-1,99,"Estrofa suelta",0,4,"ea",-1,0,-1,0,418,418,"2712","",0,"","","",1,0,0,[],""],["frenk_t1-n2713",5,"No ruego porque me quieran\nni pago por su amistad;\nla que me quiera deveras\nha de ser por voluntad.",75,2,-1,99,"Estrofa suelta",0,4,"a",16,0,-1,0,418,418,"2713","",0,"","","",1,0,0,[],""],["frenk_t1-n2714",5,"De piedra ha de ser la cama,\nde piedra las cabeceras;\nla mujer que a mí me quiera\nme ha de querer de a de veras.",86,2,11,99,"La cama de piedra",0,4,"ea",-1,0,-1,0,418,418,"2714","",0,"","","",1,0,0,[],""],["frenk_t1-n2715",5,"La niña que a mí me quiera\nha de ser del gusto mío,\nha de salir a la puerta\ncuando yo le haga: “...”",92,2,17,99,"El amor y el desafío",3,4,"aa",-1,0,-1,0,418,418,"2715","",0,"","","",2,0,0,[],""],["frenk_t1-n2716",5,"Me subí al palo sereno\na sacudir el rocío;\nno cuido amores ajenos,\nni ce[ljo lo que no es mío.",78,2,3,99,"La sandía Vasito de agua de coco; Estrofa suelta",0,4,"io",3,0,-1,0,418,418,"2716","",0,"","","",1,0,0,[],""],["frenk_t1-n2717",5,"Ya no quiero amor con dueño,\nque me lo quiten mañana;\nyo quiero amor que dure\nhasta que me dé la gana.",83,2,8,99,"Estrofa suelta",0,4,"aa",4,0,-1,0,418,418,"2717","",0,"","","",1,0,0,[],""],["frenk_t1-n2718",5,"De las cien aventuras\nque el amor tiene\nyo ya llevo vencidas\nnoventa y nueve.",79,2,4,99,"La bamba; Cielito lindo",6,4,"ee",-1,0,-1,0,418,418,"2718","",0,"","","",1,0,0,[],""],["frenk_t1-n2719",5,"¡Ay de mí!, Llorona,\nLlorona de la alta cumbre.\nyo soy como los arrieros (Llorona):\nllegando y haciendo lumbre.",83,2,8,99,"La Llorona; La guarecita; Estrofa suelta",3,4,"ue",181,0,-1,0,419,419,"2719","",0,"","","",35,0,0,[],""],["frenk_t1-n2720",5,"La rosa para brotar,\nno necesita tiempo;\nyo para enamorar,\nprimero les cuento un cuento\ny hasta las hago llorar.",87,2,12,99,"La rosa",7,5,"a",21,0,-1,0,419,419,"2720","",0,"","","",1,0,0,[],""],["frenk_t1-n2721",5,"Soy soltero sin amaño,\nfandanguero divertido;\nparezco un torito de año\ncuando a las muchachas miro;\nhasta el cuerpo les desmayo\ncuando les tiro el bramido.",83,2,8,99,"Estrofa suelta",9,6,"io",-1,0,-1,0,419,419,"2721","",0,"","","",1,0,0,[],""],["frenk_t1-n2722",5,"Soy como el manjar de breva,\nque agüita se me hace la boca;\nla mujer que a mí me prueba\nse muere o se vuelve loca,\no se va para su casa\nmuy calladita la boca.",75,2,-1,99,"Chiquitita te vas criando; Estrofa sucha",9,6,"oa",178,0,-1,0,419,419,"2722","",0,"","","",1,0,0,[],""],["frenk_t1-n2723",5,"Dichosa la chuparrosa,\nque liba flor de poleo,\npero más dichos [o J yo,\nque hasta las hierbas volteo.",101,2,26,99,"La chuparrosa",0,4,"eo",66,0,-1,0,419,419,"2723","",0,"","","",1,0,0,[],""],["frenk_t1-n2724",5,"Desde Navolato vengo,\ndicen que nací en El Roble;\nme dicen que soy arriero,\nporque les chiflo y se paran;\nsi les aviento el sombrero,\nya verán cómo reparan.",95,2,20,99,"El sinaloense",9,6,"aa",435,0,-1,0,419,419,"2724","",0,"","","",1,0,0,[],""],["frenk_t1-n2726",5,"Yo soy un gavilancillo\nque ando por aquí volando,\nla polla que no me llevo\nla dejo cacaraqueando.",75,2,-1,99,"El gavilancillo; La Sanmarqueña; El toro; Estrofa suelta",0,4,"ao",33,0,-1,0,420,420,"2726","",0,"frenk_t4","","",12,0,0,[],""],["frenk_t1-n2728",5,"Soy manganeador y bueno,\nno yerro mangana ni lazo;\npotrancas que hallo sin dueño\nlas lazo y me voy de paso,\nsiempre con aquel empeño,\narriando y echando lazo.",76,2,1,99,"El caballito",9,6,"ao",43,0,-1,0,420,420,"2728","",0,"","","",1,0,0,[],""],["frenk_t1-n2729",5,"Ando vestido de cuero,\nno presumiendo de charro;\nla yegua que hallo sin dueño\nla tumbo y me voy de paso;\n¡qué bonito es el potrero\ny lazar a campo raso!",77,2,2,99,"El cuerudo",9,6,"ao",145,0,-1,0,420,420,"2729","",0,"","","",1,0,0,[],""],["frenk_t1-n2730",5,"Soy el muchacho engreído,\ndueño de las tres garitas,\ndespreciado de las feas,\nquerido de las bonitas.",79,2,4,99,"Glosada en décimas",0,4,"ia",258,0,-1,0,420,420,"2730","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t1-n2731",5,"Soy de todas bien querido,\nsoy un hombre apasionado,\nque en la vida se ha pasado\nsiendo esclavo de Cupido.",75,2,-1,99,"El fandanguero",11,4,"io",101,0,-1,0,420,420,"2731","",0,"","","",1,0,0,[],""],["frenk_t1-n2732",5,"Soy huasteco, y es mi empeño\nel venirles a cantar;\naunque vean que soy fuereño,\nno me les voy a cuartear,\ny hasta las que tengan dueño\nlas haré desatinar.",75,2,-1,99,"El fuereño",9,6,"a",21,0,-1,0,421,421,"2732","",0,"","","",1,0,0,[],""],["frenk_t1-n2733",5,"Yo soy el mozo del cura,\nel que guarda su historia;\nla mujer que me quiera\nderecho se va a la gloria.",83,2,8,99,"Estrofa suelta",0,4,"oa",126,0,-1,0,421,421,"2733","",0,"","","",2,0,0,[],""],["frenk_t1-n2734",5,"Subí al árbol del sereno\na sacudir el rocío;\nque estando en un buen terreno,\nno hay otro amor como el mío.",92,2,17,99,"Estrofa suelta",1,4,"io",3,0,-1,0,421,421,"2734","",0,"","","",2,0,0,[],""],["frenk_t1-n2735",5,"Y una calandria en Madrid\nle dijo al pájaro cuervo:\n“Las palomas que hay aquí\nson las que yo me reservo:\nyo las quiero para mí.”",75,2,-1,99,"El pájaro cú",7,5,"i",23,0,-1,0,421,421,"2735","",0,"","","",1,0,0,[],""],["frenk_t1-n2736",5,"Como me gusta lo bueno\ny con lo bueno me engrío,\nhallándome un buen terreno\nno hay corazón como el mío;\nsólo a Jesucristo temo,\ny de los demás me río.",75,2,-1,99,"El siquisirí",9,6,"io",3,0,-1,0,421,421,"2736","",0,"","","",1,0,0,[],""],["frenk_t1-n2737",5,"En el corral de mis yeguas\nno me relinchan caballos;\nen la puerta del corral\nyo soy el que primero rayo.",83,2,8,99,"Estrofa suelta",0,4,"ao",-1,0,-1,0,421,421,"2737","",0,"","","",1,0,0,[],""],["frenk_t1-n2738",5,"Me he de comer un durazno\ndesde la raíz hasta el hueso;\nno le hace que sea trigueña:\nserá mi gusto y por eso.",75,2,-1,99,"Estrofa suelta, El durazno",0,4,"eo",48,0,-1,0,421,421,"2738","",0,"","","",3,0,0,[],""],["frenk_t1-n2739",5,"Dicen que soy hombre malo,\nmalo y mal averiguado,\nporque me comí un durazno\nde corazón colorado.",78,2,3,99,"Guadalajara en un llano; El novillo despuntado",0,4,"ao",-1,0,-1,0,421,421,"2739","",0,"","","",1,0,0,[],""],["frenk_t1-n2740",5,"Ariles y más ariles,\nariles del carrizal;\nme picaron las abejas,\npero me comí el panal.",79,2,4,99,"El Balajú",0,4,"a",1,0,-1,0,422,422,"2740","",0,"","","",24,0,0,[],""],["frenk_t1-n2745",5,"Ya el águila real voló\nde un jardín de Guanajuato;\na mí me quieren tres chicas\ny a mi compañero cuatro.",83,2,8,99,"Estrofa suelta",0,4,"ao",-1,0,-1,0,423,423,"2745","",0,"","","",5,0,0,[],""],["frenk_t1-n2746",5,"Tengo porción de mujeres,\ny no hallo qué hacer con ellas;\nya me sacan canas verdes\nsolamente por quererlas.",83,2,8,99,"Glosada en décimas",0,4,"ea",-1,0,-1,0,423,423,"2746","",0,"","","",1,0,0,[],""],["frenk_t1-n2747a",5,"De dos amores que tengo,\n¡válgame Dios!, ¿qué haré yo?\nDe dos amores que tengo\ny uno ya se me murió.",81,2,6,99,"La huazanga",1,4,"o",2,0,-1,0,423,423,"2747a","",0,"","","",3,0,0,[],""],["frenk_t1-n2748",5,"En mi casa me dicen\nel inocente,\nporque tengo muchachas\nde quince a veinte.",75,2,-1,99,"La bamba",6,4,"ee",-1,0,-1,0,423,423,"2748","",0,"","","",11,0,0,[],""],["frenk_t1-n2749",5,"Aunque me veas inocente\nen las cosas del amor,\nno me gusta lo corriente,\nconsumo de lo mejor.",75,2,-1,99,"La verdolaga; Estrofa suelta",1,4,"o",72,0,-1,0,423,423,"2749","",0,"","","",1,0,0,[],""],["frenk_t1-n2751",5,"Tengo mi arreglo con Pepa\ny estoy arreglado con Amparo,\ny así me llaman mis padres\na todas horas desarreglado.",75,2,-1,99,"Cielito lindo",3,4,"ao",-1,0,-1,0,423,423,"2751","",0,"","","",1,0,0,[],""],["frenk_t1-n2752",5,"Soñé que estaba en La Habana\ny era profesor de escuela,\nque estaba tocando diana (¡ay, vida mía!),\ny que estaba con Manuela\ny con mi adorada Juana.",75,2,-1,99,"El pajaro carpintero",7,5,"aa",4,0,-1,0,423,423,"2752","",0,"","","",1,0,0,[],""],["frenk_t1-n2757",5,"Alicia se llamaba una,\nla otra, María Cristina,\ny la que más me quería\nme iba a traer a una cantina.",79,2,4,99,"El Balajú",0,4,"ia",-1,0,-1,0,424,424,"2757","",0,"","","",1,0,0,[],""],["frenk_t1-n2758",5,"Rita se llamaba una,\nla otra María Tomasa;\n¡ay!, la que más me quería\nme iba a buscar a mi casa.",79,2,4,99,"El Balajú",0,4,"aa",123,0,-1,0,424,424,"2758","",0,"","","",2,0,0,[],""],["frenk_t1-n2759",5,"En Mochis tengo un cariño,\nlo mismo que en Mazatlán,\nque dejo por los domingos\npa ver los mangos de Culiacán.",75,2,-1,99,"¡Arriba Sinaloa!",3,4,"a",147,0,-1,0,424,424,"2759","",0,"","","",1,0,0,[],""],["frenk_t1-n2760",5,"Qué bonitas, qué bonitas\nson las muchachas de aquí,\ny la que vi más bonita\nes la que yo pretendí.",78,2,3,99,"Soy forastero",0,4,"i",23,0,-1,0,424,424,"2760","",0,"","","",1,0,0,[],""],["frenk_t1-n2762",5,"Tengo un amor en Santana\ny otro en Santanita,\npero el que tengo en Amusgos\nsólo el cielo me lo quita.",75,2,-1,99,"Estrofa suelta",0,4,"ia",50,0,-1,0,424,424,"2762","",0,"","","",1,0,0,[],""],["frenk_t1-n2763",5,"Un amor tengo en Celaya,\notro tengo en Monterrey,\ny otro tengo en este barrio:\ny es el que yo vengo a ver.",100,2,25,99,"Un amor tengo en Celaya",0,4,"e",-1,0,-1,0,425,425,"2763","",0,"","","",1,0,0,[],""],["frenk_t1-n2764",5,"En Salina Cruz hay flores,\nen Juchitán las mejores,\npero las de Xochimilco\nallí están mis amores.",83,2,8,99,"La Zandunga",0,4,"oe",5,0,-1,0,425,425,"2764","",0,"","","",1,0,0,[],""],["frenk_t1-n2765",5,"Ya se juntaron las cuatro,\nque son las que quiero yo;\nAmalia, Amalia, Amalia Rosa,\nésa es la que yo me llevo,\npor ser la más hermosa.",75,2,-1,99,"Amalia Rosa",7,5,"oa",63,0,-1,0,425,425,"2765","",0,"","","",1,0,0,[],""],["frenk_t1-n2766",5,"Desde que estaba en la cuna,\nyo ya le pedía a mi Dios\npues que me diera fortuna\npa poder tener de a dos,\npor si se muriera alguna.",75,2,-1,99,"El querreque",7,5,"ua",56,0,-1,0,425,425,"2766","",0,"","","",1,0,0,[],""],["frenk_t1-n2767",5,"Ya tengo visto el nopal\ndonde he de cortar la tuna;\ncomo soy hombre formal,\nno me gusta tener una:\nme gusta tener de a dos,\npor si se me enoja alguna.",75,2,-1,99,"El venadito; El pájaro carpintero; Estrofa suelta",9,6,"ua",56,0,-1,0,425,425,"2767","",0,"","","",1,0,0,[],""],["frenk_t1-n2768",5,"Así me la voy pasando\ncon la pasión de mi vida:\nsi una vela se me apaga,\notra me queda prendida.",75,2,-1,99,"Yo agarro parejo",0,4,"ia",37,0,-1,0,425,425,"2768","",0,"","","",1,0,0,[],""],["frenk_t1-n2769",5,"Soy como el pájaro prieto:\nen las ramas me mantengo;\nquisiera tener de a dos,\npero, ¿con qué las mantengo?",84,2,9,99,"Estrofa suelta",0,4,"eo",-1,0,-1,0,425,425,"2769","",0,"","","",2,0,0,[],""],["frenk_t1-n2770",5,"En el jardín de la casa\ntengo una mata de arroz;\nno me gusta tener de a uno,\npor eso tengo de a dos.",84,2,9,99,"Estrofa suelta",0,4,"o",87,0,-1,0,425,425,"2770","",0,"","","",1,0,0,[],""],["frenk_t1-n2772",5,"Dos bellas flores tenía\nun amante huitlacoche,\ny así de las dos decía:\n“Una es mi huele de día\ny otra es mi huele de noche.”",75,2,-1,99,"Estrofa suelta",7,5,"oe",337,0,-1,0,426,426,"2772","",0,"","","",1,0,0,[],""],["frenk_t2-n2773b",6,"Triste está mi corazón,\ntriste está, no sé por qué,\ntriste por una ilusión,\ntriste por lo que soñé,\ntriste es la situación:\ntriste de mí, ¿qué haré?",105,2,-1,100,"El jarabe loco",9,6,"e",77,0,-1,0,35,35,"2773b","",0,"","","",5,0,0,[],""],["frenk_t2-n2774",6,"Negrita, no sé por qué,\ntriste está mi corazón,\nsi se para en la ilusión,\nfirme por lo que soñé.",105,2,-1,100,"El carpintero",11,4,"e",77,0,-1,0,35,35,"2774","",0,"","","",1,0,0,[],""],["frenk_t2-n2775a",6,"En una noche, soñando,\nvi que te me apareciste\ny que te estaba contando\nmi vida triste, muy triste,\nlos ojos también llorando.",106,2,4,100,"Estrofa suelta, La azucena",7,5,"ao",33,0,-1,0,35,35,"2775a","",0,"","","",2,0,0,[],""],["frenk_t2-n2776",6,"Era una penalidad\nlo que en sueño me decía;\nte digo que era verdad:\nyo me senté, vida mía,\na llorar mi soledad.",105,2,-1,100,"Chiquita como capullo",7,5,"a",16,0,-1,0,35,35,"2776","",0,"","","",1,0,0,[],""],["frenk_t2-n2777",6,"Sigue, sigue, blanca estrella,\npor el cielo en que naciste;\nsiempre te verás más bella\ny siempre me verás más triste.",107,2,11,100,"Estrofa suelta",1,4,"ie",153,0,-1,0,35,35,"2777","",0,"","","",1,0,0,[],""],["frenk_t2-n2779",6,"Mi amor en un fuego arde\ny a tus pies quiere rendirse;\npor las mañanas y en tarde\nde pasión piensa morirse;\n¿qué tendrá este amor cobarde,\nque no quiere divertirse?",106,2,4,100,"El pájaro cú",9,6,"ie",475,0,-1,0,36,36,"2779","",0,"","","",1,0,0,[],""],["frenk_t2-n2780",6,"Cuando te miro, niña,\nsiento morir,\ny es que más se agiganta\nmi cruel sufrir.",105,2,-1,100,"Estrofa suelta",6,4,"i",157,0,-1,0,36,36,"2780","",0,"","","",1,0,0,[],""],["frenk_t2-n2781",6,"¡Ay!, te miro y te miro,\ny si te vuelvo a mirar,\npara mí será un suspiro,\npara mí será un penar.",108,2,8,100,"El cascabel",1,4,"a",21,0,-1,0,36,36,"2781","",0,"","","",1,0,0,[],""],["frenk_t2-n2782",6,"Vengo a cantarte, mi vida,\na darte mis sufrimientos;\noye, mi prenda querida,\nchaparrita de mi vida,\nde ti traigo un sentimiento.",109,2,7,100,"Vengo a cantarte, mi vida**",7,5,"eo",-1,0,-1,0,36,36,"2782","",0,"","","",1,0,0,[],""],["frenk_t2-n2783",6,"Andándome yo pensando\ncómo haría para tenerte,\ncuatro pájaros volando\nme dijeron que mi suerte\nes andar pena y penando\nhasta que llegue mi muerte.",106,2,4,100,"El siquisirí**",9,6,"ee",134,0,-1,0,36,36,"2783","",0,"","","",1,0,0,[],""],["frenk_t2-n2784",6,"Desde el alto firmamento,\nel que amor mis pasos guía;\npero no es la alegría,\ny para mí es un tormento\npensar en ti, vida mía.",106,2,4,100,"La azucena",7,5,"ia",0,0,-1,0,36,36,"2784","",0,"","","",1,0,0,[],""],["frenk_t2-n2785",6,"Hasta la cama en que duermo\ntiene lástima de mí,\npor los suspiros que doy\ncuando me acuerdo de ti.",105,2,-1,100,"Estrofa suelta",0,4,"i",23,0,-1,0,36,36,"2785","",0,"","","",7,0,0,[],""],["frenk_t2-n2786",6,"La lluvia al salir el sol\nvuelve a convertirse en nube,\nen cambio se hace dolor\ntodo el amor que te tuve.",105,2,-1,100,"La nube*’",0,4,"ue",348,0,-1,0,36,36,"2786","",0,"","","",1,0,0,[],""],["frenk_t2-n2787",6,"Hasta el mar se oirán mis lamentos:\nlos del mundo lo están escuchando,\nlos del cielo lo están escribiendo\nque ande yo suspirando por ti.",110,2,10,100,"Eulalia",3,4,"i",-1,0,-1,0,37,37,"2787","",0,"","","",1,0,0,[],""],["frenk_t2-n2788",6,"Y al pasar por un potrero\na orillas de un encinar,\nahí me puse a llorar,\nen prueba de que te quiero\ny no te puedo olvidar.",105,2,-1,100,"El fanfarrón",7,5,"a",21,0,-1,0,37,37,"2788","",0,"","","",1,0,0,[],""],["frenk_t2-n2789",6,"Al pie de un árbol bendito\nllorando me arrodillé;\nlas lágrimas de mis ojos\nse cuajaban al caer.",108,2,8,100,"La Zandunga; La Llorona",0,4,"e",-1,0,-1,0,37,37,"2789","",0,"","","",1,0,0,[],""],["frenk_t2-n2790",6,"¿Has visto una vela arderse\ny que la consuma el fuego?\nPues así soy, desde luego,\nque me consume el quererte.",105,2,-1,100,"Estrofa suelta",5,4,"ee",-1,0,-1,0,37,37,"2790","",0,"","","",1,0,0,[],""],["frenk_t2-n2791",6,"Como una espina traidora\nse me ha clavado tu amor;\nno puedo más aguantarla:\nme traspasó el corazón.",105,2,-1,100,"Espina traidora",0,4,"o",-1,0,-1,0,37,37,"2791","",0,"","","",1,0,0,[],""],["frenk_t2-n2792",6,"No quieras nunca saber (¡ay, Llorona!)\nde qué tamaño es el cielo;\ndos cosas hay sin medida (¡ay, Llorona!):\nmi amor y mi desconsuelo.",105,2,-1,100,"La Llorona",3,4,"eo",10,0,-1,0,37,37,"2792","",0,"","","",1,0,0,[],""],["frenk_t2-n2793",6,"Pensando en tí desvarío\nde hallarme en tanta congoja;\nsi veo gotas de rocío,\nme figuro que las hojas\nlloran este pesar mío.",111,2,1,100,"El fandanguito",7,5,"io",3,0,-1,0,37,37,"2793","",0,"","","",1,0,0,[],""],["frenk_t2-n2794",6,"Vivo tan apasionado,\nque ya no encuentro sosiego,\ny a tal extremo he llegado,\nque con mis lágrimas riego\nel suelo que tú has pisado.",112,2,6,100,"la pasión",7,5,"ao",14,0,-1,0,37,37,"2794","",0,"","","",2,0,0,[],""],["frenk_t2-n2795",6,"Dicen que no tengo duelo (¡ay, Llorona!)\nporque no me ven llorar:\na tu corazón y al mío (¡ay, Llorona!)\nse lo habían de preguntar.",105,2,-1,100,"La Llorona",3,4,"a",21,0,-1,0,37,37,"2795","",0,"","","",1,0,0,[],""],["frenk_t2-n2796",6,"Dicen que mucho te quiero\nporque me han visto florar,\nsi de esta pasión me muero\ntú de mí te has de acordar.",105,2,-1,100,"Cómo quieres que una luz",1,4,"a",21,0,-1,0,38,38,"2796","",0,"","","",1,0,0,[],""],["frenk_t2-n2797",6,"Y ¡ah, qué patio tan regado!,\nparece que le ha llovido:\nson lágrimas de tu amante,\nque por áhi anda perdido.",108,2,8,100,"Cada vez que cae la tarde; Cuatro esquinas tiene un catre",0,4,"io",101,0,-1,0,38,38,"2797","",0,"","","",1,0,0,[],""],["frenk_t2-n2798",6,"Levántate de mañana:\nverás tu calle regada\ncon lágrimas de tu amante,\nque pasó a la madrugada.",105,2,-1,100,"Las mañanitas; Cuatro esquinas tiene un catre; Estrofa suelta",0,4,"aa",49,0,-1,0,38,38,"2798","",0,"","","",2,0,0,[],""],["frenk_t2-n2800",6,"Sin comparación te quiero,\ny llorando te lo digo;\noirán los rezos del duelo,\ny yo sin sentir alivio;\nsin duda me voy al cielo.",106,2,4,100,"El sombrero",7,5,"eo",10,0,-1,0,38,38,"2800","",0,"","","",1,0,0,[],""],["frenk_t2-n2801",6,"Cuando lloro me parece\nque soy el más desgraciado (¡ay de mí, Lio-\nmi corazón se enternece\nrecordando lo pasado (¡ay de mí, Lloro-\ntodos los días que amanece.",106,2,4,100,"La Llorona",7,5,"ee",64,0,-1,0,39,39,"2801","",0,"","","",1,0,0,[],""],["frenk_t2-n2802",6,"¡Válgame Dios, qué pasión!,\npara mí ya no hay alegría;\nyo nunca he sido llorón,\npero a ti te lloraría\ncon todo mi corazón.",106,2,4,100,"La huazanga; La pasión",7,5,"o",31,0,-1,0,39,39,"2802","",0,"","","",1,0,0,[],""],["frenk_t2-n2803",6,"Al pie de una serranía\ntriste se quejaba un león,\ny en el quejido decía:\n“Yo nunca he sido llorón,\npero por ti lloraría\nlágrimas del corazón.”",112,2,6,100,"La huastequita; Estrofa suelta",9,6,"o",31,0,-1,0,39,39,"2803","",0,"","","",1,0,0,[],""],["frenk_t2-n2804",6,"He de esperar que me digas\nque siempre he sido llorón:\nmi chata, lo que tú digas.\nSoy puro de la Misión,\ndel ranchita de Las Pilas.",113,2,2,100,"El huerfanito",7,5,"ia",-1,0,-1,0,39,39,"2804","",0,"","","",1,0,0,[],""],["frenk_t2-n2805",6,"¡Qué tristes huaraches cargo!,\nprieta de mis pensamientos:\ncada pasito que doy\nme lo llena de lamentos.",107,2,11,100,"La Sanmarqueña] [roña! ) ; [na!",0,4,"eo",234,0,-1,0,39,39,"2805","",0,"","","",1,0,0,[],""],["frenk_t2-n2806",6,"Por ti me olvidé de Dios,\npor ti la gloria perdí,\nahora me voy a quedar\nsin Dios, sin gloria y sin ti.",114,2,17,100,"Dicen que no se siente la despedida",0,4,"i",23,0,-1,0,39,39,"2806","",0,"","","",4,0,0,[],""],["frenk_t2-n2807",6,"Yo tenía mi barca de oro\npara irme a La Habana,\ny por seguirte tus pasos (tesoro),\nperdí mi Guadalupana.",108,2,8,100,"La Llorona",3,4,"aa",4,0,-1,0,39,39,"2807","",0,"","","",1,0,0,[],""],["frenk_t2-n2808",6,"Perdí mi tierra, perdí mi honra,\nperdí a mis padres y todo perdí;\ntan consentido que a mí me criaron,\ntodo he perdido por seguirte a ti.",105,2,-1,100,"Zenaida",3,4,"i",23,0,-1,0,39,39,"2808","",0,"","","",1,0,0,[],""],["frenk_t2-n2809",6,"Tú sabrás lo que es dejar\nun hijo en la sepultura;\nasí, mi madre al pensar,\nencomendando mi vida,\nsólo a ti te ha de culpar.",106,2,4,100,"La azucena",7,5,"a",21,0,-1,0,39,39,"2809","",0,"","","",1,0,0,[],""],["frenk_t2-n2810",6,"Mi madre al morir quería\necharme su bendición,\npero tu amor me impedía\nque yo alcanzara el perdón\nque ella al morir me daría.",107,2,11,100,"El huerfanito",7,5,"ia",0,0,-1,0,40,40,"2810","",0,"","","",1,0,0,[],""],["frenk_t2-n2811",6,"Fui sol que brilló en el cielo\ny el cielo me pertenece,\nno más que por culpa tuya\nel cielo se me oscurece.",105,2,-1,100,"Qué padre es la vida",0,4,"ee",64,0,-1,0,40,40,"2811","",0,"","","",1,0,0,[],""],["frenk_t2-n2812",6,"La lintemita de mi alma\nse me está oscureciendo;\nla culpa la tienes tú,\ndesde que te estoy queriendo.",105,2,-1,100,"Linternas y lintemitas",0,4,"eo",52,0,-1,0,40,40,"2812","",0,"","","",1,0,0,[],""],["frenk_t2-n2813",6,"Chaparrita, chaparrita,\n¡cómo me has sido informal!,\nporque desde que te fuiste\ntodo me ha salido mal.",114,2,17,100,"Chaparrita, chaparrita",0,4,"a",1,0,-1,0,40,40,"2813","",0,"","","",1,0,0,[],""],["frenk_t2-n2814",6,"La noche que tú te fuiste\ntodo se me fue en llorar;\neste corazón cobarde\nno lo puedo consolar.",114,2,17,100,"Chaparrita, chaparrita",0,4,"a",21,0,-1,0,40,40,"2814","",0,"","","",1,0,0,[],""],["frenk_t2-n2815",6,"¿Cómo quieres que tenga (bien de mi vida)\nbuenos colores,\nsi me los has quitado\ncon tus amores?",105,2,-1,100,"El pájaro cú",3,4,"oe",5,0,-1,0,40,40,"2815","",0,"","","",1,0,0,[],""],["frenk_t2-n2816",6,"¿Qué rayos me pasa a mí,\nque quiero, que quiero evitarlo?\n¡Maldito sea tu amor!,\n¡cómo te estoy adorando!",105,2,-1,100,"Que me lleve el diablo’T",0,4,"ao",-1,0,-1,0,40,40,"2816","",0,"","","",1,0,0,[],""],["frenk_t2-n2817",6,"Si porque me miras pasar por tu casa\ncon el sombrero de lado,\ntú tienes la culpa, tú eres la causa\nque yo ande de enamorado.",105,2,-1,100,"La pantera vaciladora",3,4,"ao",14,0,-1,0,40,40,"2817","",0,"","","",3,0,0,[],""],["frenk_t2-n2818",6,"Si porque me miras pasar por tu casa\ncon el sombrero gacho,\ntú tienes la culpa, tú eres la causa\nque yo viva de borracho.",105,2,-1,100,"La pantera vaciladora",3,4,"ao",310,0,-1,0,40,40,"2818","",0,"","","",3,0,0,[],""],["frenk_t2-n2819",6,"Por causa de tus amores\ncrucé las aguas del mar,\npor causa de tus amores\nhoy me voy a emborrachar.",115,2,3,100,"Mañana se va tu prieto",1,4,"a",21,0,-1,0,40,40,"2819","",0,"","","",1,0,0,[],""],["frenk_t2-n2820",6,"Yo te he querido bien,\ntú me has pagado mal;\nahora de sentimiento\nme voy a emborrachar.",105,2,-1,100,"La chaparrita",0,4,"a",-1,0,-1,0,41,41,"2820","",0,"","","",2,0,0,[],""],["frenk_t2-n2821",6,"No te buigas, chaparrita,\nque te voy a retratar,\ny de puro sentimiento\nyo me voy a emborrachar.",110,2,10,100,"Un dolor que tengo aquí",0,4,"a",21,0,-1,0,41,41,"2821","",0,"","","",1,0,0,[],""],["frenk_t2-n2822",6,"Si yo tuviera el pudiente\nde poder contigo hablar,\nno tomaría el aguardiente:\ny me daría mi lugar,\ncomo cualquier decente.",106,2,4,100,"Me puse en un espiadero; Estrofa suelta",7,5,"ee",15,0,-1,0,41,41,"2822","",0,"","","",1,0,0,[],""],["frenk_t2-n2823",6,"¿Quién dice que ando gritando?,\n¿quién dice que ando llorando\ny que muero por tu amor?\nTú sabes que ando tomando,\nque sólo ando navegando\nentre copas de licor.",113,2,2,100,"Dos hojas sin rumbo",9,6,"o",72,0,-1,0,41,41,"2823","",0,"","","",1,0,0,[],""],["frenk_t2-n2824",6,"Para qué me sirve el vino,\nsi no logro aborrecerte;\ntodo se me va en quererte:\n¡qué maldito es mi destino!",105,2,-1,100,"La puntada",11,4,"io",199,0,-1,0,41,41,"2824","",0,"","","",1,0,0,[],""],["frenk_t2-n2825",6,"Las ilusiones llevan al hombre,\nllevan al hombre a la perdición;\nojalá y nunca lo hubiera hecho,\ny un sentimiento en mi corazón.",114,2,17,100,"Las ilusiones",3,4,"o",31,0,-1,0,41,41,"2825","",0,"","","",1,0,0,[],""],["frenk_t2-n2827",6,"Tengo un dolor muy grande,\nque llevo aquí en mi pecho;\nya que me acuerdo de todo\nel mal tan grande que me has hecho.",113,2,2,100,"Estrofa suelta",0,4,"eo",60,0,-1,0,41,41,"2827","",0,"","","",1,0,0,[],""],["frenk_t2-n2828",6,"Quien te puso Petenera\nseguro no estaba en sí,\nque tú te habías de llamar\nla maldición para mí.",106,2,4,100,"La Petenera",0,4,"i",23,0,-1,0,41,41,"2828","",0,"frenk_t4","","",3,0,0,[],""],["frenk_t2-n2830",6,"Al pie de un verde limón\nme senté a llorar por ti,\na llorar eternamente:\nlo que tú no haces por mí.",105,2,-1,100,"Yo ya me voy",0,4,"i",23,0,-1,0,42,42,"2830","",0,"","","",3,0,0,[],""],["frenk_t2-n2831",6,"La pena y la que no es pena\ntodo es penar para mí (¡ay de mí, Lloro-\nayer penaba, penaba por verte,\ny hoy peno porque te vi (¡ay de mí, Llo-",106,2,4,100,"La Zandunga",3,4,"o",-1,0,-1,0,42,42,"2831","",0,"","","",9,0,0,[],""],["frenk_t2-n2831-e2",6,"Eres un granito de oro\nprendido en aquella cima;\n¿cómo pides que te olvide,\nsi a mi corazón lastimas?",106,2,4,100,"La Zandunga",0,4,"ia",-1,0,-1,0,42,42,"2831","",0,"","","",5,0,0,[],""],["frenk_t2-n2832",6,"Ni contigo ni sintigo\ntienen mis males remedio:\ncontigo, porque me matas,\nsintigo, porque me muero.",106,2,4,100,"Estrofa suelta",0,4,"eo",-1,0,-1,0,42,42,"2832","",0,"","","",1,0,0,[],""],["frenk_t2-n2833",6,"La noche le quita al cielo\nsu luz y plata,\ny tú me quitas la vida,\ndejando sangrar la herida\nque por tu amor me mata.",112,2,6,100,"Estrofa suelta] [‘‘La nube",7,5,"aa",74,0,-1,0,42,42,"2833","",0,"","","",1,0,0,[],""],["frenk_t2-n2837",6,"Soñé que en el fuego helaba,\nsoñé que en la nieve ardía,\ny por soñar imposibles,\nsoñé que tú me querías.",107,2,11,100,"La Sahmarqueña’*",0,4,"ia",-1,0,-1,0,42,42,"2837","",0,"","","",1,0,0,[],""],["frenk_t2-n2838",6,"En un sueño yo soñé\nel nido de mis amores,\ny cuando yo desperté\nhallé marchitas las flores\nque en tu altar yo coloqué.",113,2,2,100,"Estrofa suelta",7,5,"e",77,0,-1,0,42,42,"2838","",0,"","","",1,0,0,[],""],["frenk_t2-n2839",6,"Anoche yo soñaba\nque te besaba;\nmentira, no era nada:\nera la almohada\nla que abrazaba.",108,2,8,100,"Anoche yo soñaba",7,5,"aa",-1,0,-1,0,43,43,"2839","",0,"","","",1,0,0,[],""],["frenk_t2-n2840",6,"Hubo noches que soñé\nque tu boquita besaba,\nmas luego que desperté\nvoy viendo que era la almohada\nla que de besos colmé.",108,2,8,100,"El sueño; La leva",7,5,"e",77,0,-1,0,43,43,"2840","",0,"","","",1,0,0,[],""],["frenk_t2-n2841",6,"Se ha secado el floripondio\nque en tu jardín perfumaba;\nya ha quedado enmudecido\nel zarzal que te cantaba.",108,2,8,100,"El bejuco de amor",0,4,"aa",28,0,-1,0,43,43,"2841","",0,"","","",1,0,0,[],""],["frenk_t2-n2842",6,"Ahora llevo aquí en mi pecho\nun puñal triste clavado:\nque has deshojado el bejuco de amor\nque teníamos ya formado.",108,2,8,100,"Bejuco de amor",3,4,"ao",14,0,-1,0,43,43,"2842","",0,"","","",1,0,0,[],""],["frenk_t2-n2843",6,"Hay pesares muy grandes\nque causan pena;\npero al ver tus desdenes\nyo, al fin, me muero.",105,2,-1,100,"Estrofa suelta",6,4,"eo",-1,0,-1,0,43,43,"2843","",0,"","","",1,0,0,[],""],["frenk_t2-n2845",6,"Al pie de un verde limón\nle dije a mi amor: “¡Estáte!”\nDevuélveme el corazón,\nsi no quieres que te mate.",105,2,-1,100,"Estrofa suelta",1,4,"ae",384,0,-1,0,43,43,"2845","",0,"","","",3,0,0,[],""],["frenk_t2-n2846",6,"Yo no vengo a que me quieras\nni a cantarte una canción,\nsólo vengo a reclamarte\nque me des mi corazón.",105,2,-1,100,"Devuélveme el corazón",0,4,"o",31,0,-1,0,43,43,"2846","",0,"","","",1,0,0,[],""],["frenk_t2-n2848",6,"¡Qué suerte me cargo yo!\nQuisiera no haber nacido;\n¿por qué te fui a conocer,\nsi eres un caso perdido?",105,2,-1,100,"Que me lleve el diablo",0,4,"io",101,0,-1,0,44,44,"2848","",0,"","","",1,0,0,[],""],["frenk_t2-n2849",6,"Quisiera verte y no verte,\npara no estar tan engreído;\nquisiera darte la muerte\nen los brazos del olvido,\n¡Valía más haberme muerto\nque no haberte conocido!",105,2,-1,100,"Voy a tirarme a los vicios",9,6,"io",101,0,-1,0,44,44,"2849","",0,"","","",12,0,0,[],""],["frenk_t2-n2850",6,"Porque me voy a un desierto,\ncuando yo te conocí\nvalía más haberme muerto\nantes de haberte querido.",115,2,3,100,"El veinte",5,4,"io",-1,0,-1,0,44,44,"2850","",0,"","","",1,0,0,[],""],["frenk_t2-n2851",6,"Quisiera ser un león,\nuna serpiente, una fiera,\nun animal ponzoñoso,\nque cuenta de mi vida diera;\nquien te mira y no te goza\nvale más que se muriera.",108,2,8,100,"Estrofa suelta",9,6,"ea",44,0,-1,0,44,44,"2851","",0,"","","",1,0,0,[],""],["frenk_t2-n2853",6,"Balajú se va de aquí,\ndizque para no volver;\nsi tú te apartas de mí,\nyo sin ti, ¿qué podré hacer?\nvale más mejor morir\npara no volverte a ver.",106,2,4,100,"El Balajú",9,6,"e",20,0,-1,0,45,45,"2853","",0,"","","",1,0,0,[],""],["frenk_t2-n2854",6,"¿Para qué quiero vivir\nen esta vida prestada,\nsi no llego a conseguir\nque conmigo seas casada (¡ay, de la rosa,\nMejor prefiero morir.",107,2,11,100,"La Rosita",7,5,"i",157,0,-1,0,45,45,"2854","",0,"","","",1,0,0,[],""],["frenk_t2-n2855",6,"Quiero quitarme la vida\npara ya no andar penando;\n¿para qué seguir viviendo\ncon el alma agonizando?\nYo comprendo que esta vida,\npara mí sale sobrando.",105,2,-1,100,"Voy a tirarme a los vicios",9,6,"ao",33,0,-1,0,45,45,"2855","",0,"","","",1,0,0,[],""],["frenk_t2-n2856",6,"Yo planté tres aguacates\npara ver si así me muero:\ndesde el día en que me dejaste\nla vida ya no la quiero.",105,2,-1,100,"Los aguacates",0,4,"eo",38,0,-1,0,45,45,"2856","",0,"","","",1,0,0,[],""],["frenk_t2-n2857",6,"Mis ojos vierten un llanto\nporque no me das tu amor;\npara que no haiga quebranto,\ndame la muerte mejor.",109,2,7,100,"Quiero que sepas, mi vida",1,4,"o",72,0,-1,0,45,45,"2857","",0,"","","",1,0,0,[],""],["frenk_t2-n2858",6,"Pero áhi no más, áhi no más,\ntoda la vida penando;\nacábame de matar,\nque ya estoy agonizando.",105,2,-1,100,"Los arrieros",3,4,"ao",33,0,-1,0,45,45,"2858","",0,"","","",1,0,0,[],""],["frenk_t2-n2859",6,"Sé que te vas a casar,\na mí me lo ha dicho el tiempo;\ndos cosas irán a ser:\nmi entierro y tu casamiento.",115,2,3,100,"El apasionado",0,4,"eo",-1,0,-1,0,45,45,"2859","",0,"frenk_t4","","",4,0,0,[],""],["frenk_t2-n2860",6,"Saucillo del cementerio,\ncaracoles del convento;\ntambién mi muerte ha de ser\njunto con tu casamiento.",116,2,15,100,"El apasionado",0,4,"eo",94,0,-1,0,45,45,"2860","",0,"","","",1,0,0,[],""],["frenk_t2-n2861",6,"Segunda amonestación,\ntu gusto se está cumpliendo:\nte vas a casar con otro\naunque yo me esté muriendo.",105,2,-1,100,"El apasionado",0,4,"eo",52,0,-1,0,45,45,"2861","",0,"","","",2,0,0,[],""],["frenk_t2-n2862",6,"Cuando estés en el cajón,\nque te estén comprando donas,\na mí me estarán comprando\npalmas, cruces y coronas.",105,2,-1,100,"El apasionado",0,4,"oa",549,0,-1,0,46,46,"2862","",0,"","","",1,0,0,[],""],["frenk_t2-n2863",6,"Cuando duermas en tu casa,\nen cama de pabellón,\nverás cuatro cargadores\nque me llevan al panteón.",105,2,-1,100,"El apasionado",0,4,"o",31,0,-1,0,46,46,"2863","",0,"","","",1,0,0,[],""],["frenk_t2-n2864",6,"Cuando a ti te estén poniendo\nel chocolate en la mesa,\na mí me estarán poniendo\nla corona en la cabeza.",115,2,3,100,"El apasionado",1,4,"ea",108,0,-1,0,46,46,"2864","",0,"frenk_t4","","",12,0,0,[],""],["frenk_t2-n2865",6,"Cuando a ti te estén poniendo\nla corona y los azahares,\na mí me estarán poniendo\ncuatro cirios funerales.",107,2,11,100,"El apasionado",3,4,"ae",-1,0,-1,0,46,46,"2865","",0,"","","",12,0,0,[],""],["frenk_t2-n2866",6,"Cuando todas tus hermanas\nestén poniéndote el velo,\noirás las tristes campanas\ndando clamores al cielo.",105,2,-1,100,"El apasionado",1,4,"eo",10,0,-1,0,46,46,"2866","",0,"","","",1,0,0,[],""],["frenk_t2-n2867",6,"Cuando a ti te estén poniendo\nlos anillos en las manos,\nyo me estaré despidiendo\nde toditos mis hermanos.",115,2,3,100,"El apasionado",1,4,"ao",318,0,-1,0,46,46,"2867","",0,"frenk_t4","","",12,0,0,[],""],["frenk_t2-n2868",6,"Cuando a ti te estén poniendo\nlas soguillas y pendientes,\na mí me estarán diciendo\nmisa de cuerpo presente.",117,2,5,100,"El apasionado",0,4,"ee",-1,0,-1,0,46,46,"2868","",0,"","","",12,0,0,[],""],["frenk_t2-n2869",6,"Cuando tú estés en la iglesia,\nque estés rodeada de gente,\na mí me estarán diciendo\nmisa de cuerpo presente.",115,2,3,100,"El apasionado",0,4,"ee",15,0,-1,0,46,46,"2869","",0,"frenk_t4","","",3,0,0,[],""],["frenk_t2-n2870",6,"Cuando vayas para el templo,\nirás con tu vista baja;\na mí me estarán poniendo\npalma, corona y mortaja.",115,2,3,100,"El apasionado",0,4,"aa",393,0,-1,0,46,46,"2870","",0,"frenk_t4","","",3,0,0,[],""],["frenk_t2-n2871",6,"Cuando estés dentro la iglesia,\nque te esté casando el cura,\nvoltearás la vista atrás\ny verás mi sepultura.",116,2,15,100,"El apasionado",0,4,"ua",17,0,-1,0,47,47,"2871","",0,"","","",2,0,0,[],""],["frenk_t2-n2872",6,"Cuando estés dentro la iglesia,\nque te estén poniendo el velo,\nvoltearás la vista a un lado\ny verás ¡qué hermoso suelo!",116,2,15,100,"El apasionado",0,4,"eo",10,0,-1,0,47,47,"2872","",0,"","","",2,0,0,[],""],["frenk_t2-n2873",6,"Cuando salgas de la iglesia,\nal lado de tu madrina,\ncon la punta del botín\nme echarás la tierra encima.",116,2,15,100,"El apasionado",0,4,"ia",-1,0,-1,0,47,47,"2873","",0,"","","",1,0,0,[],""],["frenk_t2-n2874",6,"Cuando tú ya estés saliendo\njuntamente con el cura,\ncon la suela del zapato\nhas de abrir mi sepultura.",117,2,5,100,"El apasionado",0,4,"ua",17,0,-1,0,47,47,"2874","",0,"","","",1,0,0,[],""],["frenk_t2-n2875",6,"Cuando ya estés en la mesa,\nen unión de tus hermanos,\na mí me estarán comiendo\nesos terribles gusanos.",105,2,-1,100,"El apasionado",0,4,"ao",318,0,-1,0,47,47,"2875","",0,"","","",1,0,0,[],""],["frenk_t2-n2876",6,"Entre las copas de vino,\nsentirás remordimiento,\nrecordando que me diste\npalabra de casamiento.",105,2,-1,100,"El apasionado’",0,4,"eo",94,0,-1,0,47,47,"2876","",0,"","","",1,0,0,[],""],["frenk_t2-n2877",6,"Cuando a ti te estén abriendo\nlas puertas del dormitorio,\na mí me estarán abriendo\nlas puertas del purgatorio.",115,2,3,100,"El apasionado",1,4,"oo",551,0,-1,0,47,47,"2877","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n2878",6,"Y cuando estés en tu cama,\ndentro de tu pabellón,\nme rezarás un rosario\ndentro de tu corazón.",105,2,-1,100,"El apasionado",0,4,"o",31,0,-1,0,47,47,"2878","",0,"","","",1,0,0,[],""],["frenk_t2-n2879",6,"Si vas a mi panteón,\nverás escrito:\n“Debe tu corazón (cielito lindo)\neste delito;\naquí descansa\nel hombre que te quiso (cielito lindo)\ndesde su infancia.”",106,2,4,100,"Cielito lindo",4,7,"aa",-1,0,-1,0,47,47,"2879","",0,"","","",1,0,0,[],""],["frenk_t2-n2880",6,"Si la sombra de un sepulcro\nme cubre con su crespón,\nallí estará sepultado\nel que fue tu adorador.",110,2,10,100,"La despedida**",0,4,"o",-1,0,-1,0,48,48,"2880","",0,"","","",1,0,0,[],""],["frenk_t2-n2881",6,"Cuando mi gallo cantaba\ndecía que Cristo nació;\ny hora que se encuentra en traba\ndice que ya falleció\nel que constante te amaba.",106,2,4,100,"El gallo",7,5,"aa",28,0,-1,0,48,48,"2881","",0,"","","",1,0,0,[],""],["frenk_t2-n2882",6,"Cuando de ti me despida\nlas aves han de llorar;\nmuy triste vas a quedar\nal saber que en un suspiro\nla tumba voy a buscar.",113,2,2,100,"Estrofa suelta",7,5,"a",21,0,-1,0,48,48,"2882","",0,"","","",1,0,0,[],""],["frenk_t2-n2883",6,"Adiós, niña hermosa,\ntu amante se va\na la sepultura,\nque abierta ya está.",107,2,11,100,"El apasionado",0,4,"a",9,0,-1,0,48,48,"2883","",0,"","","",1,0,0,[],""],["frenk_t2-n2884",6,"Adiós, ingrata, de ti me ausento\npero consiento en que he de volver;\npero si muero de ti alejado,\ntendrás cuidado de no llorar.",105,2,-1,100,"Las fuentes",3,4,"a",-1,0,-1,0,48,48,"2884","",0,"","","",1,0,0,[],""],["frenk_t2-n2885",6,"No quiero que guardes luto\nsi yo antes que tú me muero;\nno me llores ni un momento,\nde mi muerte no hagas duelo.",106,2,4,100,"Estrofa suelta",0,4,"eo",-1,0,-1,0,48,48,"2885","",0,"","","",1,0,0,[],""],["frenk_t2-n2886",6,"Morena, si yo me muero,\nno me vayas a llorar;\nallá en el cielo te espero;\nme mandas a sepultar\ncon tu bendición primero.",105,2,-1,100,"La azucena",7,5,"eo",38,0,-1,0,48,48,"2886","",0,"","","",1,0,0,[],""],["frenk_t2-n2887",6,"Si acaso oyeres decir\nque yo de pesar he muerto,\nno lo dudes que sea cierto,\nque ya no puedo vivir.\nEntonces oirás decir:\n“Murió el rey de los amores.”\nMe van a enterrar, no llores,\nque ya vas a descansar;\nnunca dejes de regar\nsobre de mi tumba flores.",105,2,-1,100,"Estrofa suelta",18,10,"oe",5,0,-1,0,48,48,"2887","",0,"","","",1,0,0,[],""],["frenk_t2-n2888",6,"Para cuando me muera,\nun favor te pido:\nvayas a mi sepulcro\ny des un suspiro;\nsi eres constante,\nen el suspiro digas (cielito lindo)\n“Murió mi amante.”",105,2,-1,100,"Cielito lindo",4,7,"ae",47,0,-1,0,48,48,"2888","",0,"","","",2,0,0,[],""],["frenk_t2-n2889",6,"Valentina, Valentina,\nte suplico esta vez\nque si me dejan tirado\nme vayas a recoger.",118,2,27,100,"La Valentina",0,4,"e",-1,0,-1,0,49,49,"2889","",0,"","","",3,0,0,[],""],["frenk_t2-n2890",6,"Vida mía, llegó la hora,\nya parto hacia la trinchera;\nsi la muerte me sorprende,\nmírame, mi soldadera.",105,2,-1,100,"Don Juan Soldado",0,4,"ea",44,0,-1,0,49,49,"2890","",0,"","","",1,0,0,[],""],["frenk_t2-n2891",6,"Mi vida, si me muriere,\nno me entierres en sagrario,\nentiérrame en un potrero,\ndonde me trille el ganado.",119,2,12,100,"El caballito",0,4,"ao",-1,0,-1,0,49,49,"2891","",0,"","","",1,0,0,[],""],["frenk_t2-n2892",6,"Un adobe y cuatro velas\nme pondrás cuando me muera;\nvas a echar sobre mi cuerpo\nel primer puño de tierra.",105,2,-1,100,"Un adobe y cuatro velas",0,4,"ea",-1,0,-1,0,49,49,"2892","",0,"","","",1,0,0,[],""],["frenk_t2-n2893",6,"Mi vida, cuando yo muera\nno se te vaya a olvidar\nque me compres una leva,\nvestida de militar,\nmi rifle y mi cabecera,\ncon lo que voy a pelear.",112,2,6,100,"La leva",9,6,"a",21,0,-1,0,49,49,"2893","",0,"","","",2,0,0,[],""],["frenk_t2-n2894",6,"Enredado en un petate,\ny mi cruz de encino roble,\nla pondrás sobre mi tumba\ncon las letras de mi nombre.",105,2,-1,100,"Un adobe y cuatro velas",0,4,"oe",-1,0,-1,0,49,49,"2894","",0,"","","",1,0,0,[],""],["frenk_t2-n2895",6,"Cuando me vaya a la fosa\nllórame con devoción;\n[eres] una mariposa;\ny oríllate a mi panteón\ny llórame como esposa.",112,2,6,100,"La leva; La Malagueña",7,5,"oa",63,0,-1,0,49,49,"2895","",0,"","","",1,0,0,[],""],["frenk_t2-n2896",6,"Y si acaso yo muero en campaña,\ny mi cuerpo en la sierra va a quedar,\nAdelita, por Dios te lo ruego,\ncon tus ojos me vas a llorar.",105,2,-1,100,"La Adelita",3,4,"a",21,0,-1,0,49,49,"2896","",0,"","","",1,0,0,[],""],["frenk_t2-n2897",6,"Si supieras que ha muerto tu amante,\nrezarás por mí una oración,\npor el hombre que supo adorarte\ncon el alma, vida y corazón.",105,2,-1,100,"La Adelita",3,4,"o",31,0,-1,0,49,49,"2897","",0,"","","",1,0,0,[],""],["frenk_t2-n2900",6,"Ya será el último día\nque este perjuicio de dura;\nquedarás libre y segura\nsi yo no llego a morir;\na mi entierro no has de ir,\nsi otro amante te procura;\nvestida de nueva moda,\ntengo esperanza de verte\n............de ponerte\ndiferente a las de todas.",106,2,4,100,"La Llorona",18,10,"oa",-1,0,-1,0,50,50,"2900","",0,"","","",1,0,0,[],""],["frenk_t2-n2901",6,"Adiós, todos mis amigos,\nmi chinita con más razón,\nadiós, prenda querida,\ndueña de mi corazón.",105,2,-1,101,"Ya me voy, chaparrita",0,4,"o",31,0,-1,0,51,51,"2901","",0,"","","",1,0,0,[],""],["frenk_t2-n2902",6,"Ya se llegó mi partida,\nya me voy a retirar.\n¡Adiós, mi alma, adiós, mi vida,\nadiós, perlita del mar!",106,2,4,101,"Estrofa suelta",1,4,"a",21,0,-1,0,51,51,"2902","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n2903",6,"Ya con ésta me despido,\nporque ya me voy mañana;\nquédate con Dios, mi vida,\nlucero de la mañana.",120,2,14,101,"Vengo a que me desengañes",0,4,"aa",-1,0,-1,0,51,51,"2903","",0,"","","",72,0,0,[],""],["frenk_t2-n2904",6,"Mañana cuando amanezca\nte espero entre los nopales;\nallí te daré mi adiós,\nque me voy para Nogales,\ndonde todos los soldados\nnos volvemos generales.",116,2,15,101,"La voltereta",9,6,"ae",26,0,-1,0,51,51,"2904","",0,"","","",2,0,0,[],""],["frenk_t2-n2905",6,"Marcianita encantadora,\nme voy para Veracruz;\nencomiéndame a la Virgen,\n¡oh, Madre mía de la Luz!",116,2,15,101,"Marcianita",0,4,"u",109,0,-1,0,51,51,"2905","",0,"","","",2,0,0,[],""],["frenk_t2-n2906",6,"Por un arroyo me fui,\nen Los Altos me quedé;\nchaparrita de mi vida,\npoco tiempo te duré.",114,2,17,101,"El Cihualteco",0,4,"e",77,0,-1,0,51,51,"2906","",0,"","","",1,0,0,[],""],["frenk_t2-n2907",6,"Voy a echar la despedida\npara mí y para los dos:\n¿qué más despedida quieres?\nYa para mí se acabó.",108,2,8,101,"Estrofa suelta, Jilguero desvanecido",0,4,"o",-1,0,-1,0,51,51,"2907","",0,"","","",8,0,0,[],""],["frenk_t2-n2908",6,"Chaparrita de mi vida,\npara otras tierras me voy;\náhi te mandaré una carta,\ny diciéndote dónde estoy.",113,2,2,101,"‘‘Chaparrita linda",0,4,"o",112,0,-1,0,52,52,"2908","",0,"","","",7,0,0,[],""],["frenk_t2-n2909",6,"Qué milagro, chaparrita,\nya hace días que no nos vemos;\ndentro de poquito tiempo\npor aquí nos miraremos,\no si no, nos escrib[e]mos.",108,2,8,101,"Qué milagro, chaparrita",7,5,"o",-1,0,-1,0,52,52,"2909","",0,"","","",3,0,0,[],""],["frenk_t2-n2910a",6,"Asómate a tu ventana,\nmira lo lejos que va,\ny el que te quiere se va;\nasómate a tu ventana\ny lueguito lo verás.",106,2,4,101,"La morena",7,5,"a",-1,0,-1,0,52,52,"2910a","",0,"","","",4,0,0,[],""],["frenk_t2-n2911",6,"Trigueñita de mi vida,\nme voy a alejar de aquí,\nmas no creas que es porque quiero\nestar ausente de ti.",105,2,-1,101,"Trigueñita",0,4,"i",23,0,-1,0,52,52,"2911","",0,"","","",3,0,0,[],""],["frenk_t2-n2912",6,"¿Cómo quieres que prescinda,\nnegrita, sin tu amistad?\nAntes que el sueño me rinda\nte voy a decir la verdad:\n“Adiós, mamacita linda,\nque tu negrito se va.”",105,2,-1,101,"El gusto",9,6,"a",-1,0,-1,0,52,52,"2912","",0,"","","",1,0,0,[],""],["frenk_t2-n2913",6,"Sabrás, mi bien, que he venido\ntan solamente a avisarte\ncómo me voy y te dejo;\nharto siento no llevarte.",105,2,-1,101,"Estrofa suelta",0,4,"ae",8,0,-1,0,52,52,"2913","",0,"frenk_t4","","",5,0,0,[],""],["frenk_t2-n2914",6,"Ya con ésta me despido,\nya me voy pa la estación;\ndame un abrazo apretado,\nlinda de mi corazón.",120,2,14,101,"Ámame, bien de mi vida",0,4,"o",31,0,-1,0,53,53,"2914","",0,"","","",72,0,0,[],""],["frenk_t2-n2915",6,"Ya me voy penando, triste:\nqué martirio, qué dolor;\nadiós, rosa americana,\nlinda y perfumada flor;\ndame un abrazo, morena,\nen cambio de tanto amor.",108,2,8,101,"Estrofa suelta",9,6,"o",72,0,-1,0,53,53,"2915","",0,"","","",1,0,0,[],""],["frenk_t2-n2916",6,"Dame de despedida (mi vida),\nmi vida, no más un beso;\nhora te doy mi vida (mi vida),\nmi vida te entrego yo.",105,2,-1,101,"Maldita sea mi suerte",3,4,"o",-1,0,-1,0,53,53,"2916","",0,"","","",1,0,0,[],""],["frenk_t2-n2917",6,"Mañana se va tu amante,\nes muy cierto que se va;\ndale un abrazo y un beso,\nsi le tienes voluntad.",105,2,-1,101,"La despedida",0,4,"a",-1,0,-1,0,53,53,"2917","",0,"","","",1,0,0,[],""],["frenk_t2-n2918",6,"Ven, querida ven,\nabraza mi corazón;\ny por mucho que tú me digas,\nno es ninguna satisfacción.",105,2,-1,101,"Las Isabeles",0,4,"o",31,0,-1,0,53,53,"2918","",0,"","","",1,0,0,[],""],["frenk_t2-n2919",6,"Asómate, mi bien,\nal pie de la ventana;\narrúllame en tus brazos,\nporque me voy mañana.",106,2,4,101,"El Colás",0,4,"aa",4,0,-1,0,53,53,"2919","",0,"","","",2,0,0,[],""],["frenk_t2-n2920",6,"Asómate, mi bien,\nal pie de tu balcón;\narrúllame en tus brazos\npor única ocasión.",106,2,4,101,"El Colás",0,4,"o",31,0,-1,0,53,53,"2920","",0,"","","",2,0,0,[],""],["frenk_t2-n2921",6,"Me despido con dolor\nde ti, mi querida dueña;\ndame un abrazo de amor\ny una mordida de seña:\nadiós, mi negrita, adiós,\nme alegro de verte buena.",108,2,8,101,"Estrofa suelta",9,6,"ea",-1,0,-1,0,53,53,"2921","",0,"","","",1,0,0,[],""],["frenk_t2-n2922",6,"Vida mía, pa poderme ir,\ndame un abrazo y besitos;\nla vida me está costando\nlo negro de tus ojitos.",120,2,14,101,"Vengo a que me desengañes",0,4,"io",254,0,-1,0,53,53,"2922","",0,"","","",1,0,0,[],""],["frenk_t2-n2924",6,"Me voy, pero pronto vuelvo,\ntrigueñita de mi amor,\ndame un abrazo apretado:\nya se va tu adorador.",105,2,-1,101,"Trigueñita",0,4,"o",72,0,-1,0,54,54,"2924","",0,"","","",1,0,0,[],""],["frenk_t2-n2925",6,"Échame tus brazos, mi alma (eso sí),\nno me hagas llorar (no, no),\nque al cabo te he de ir a ver\nabajo del pedregal.",105,2,-1,101,"El pedregal",3,4,"a",-1,0,-1,0,54,54,"2925","",0,"","","",1,0,0,[],""],["frenk_t2-n2926",6,"No se te olvide, amorcito,\nque me dejas en la estación;\nregresa pronto a mis brazos\na calmar este dolor.",105,2,-1,101,"Camioncito Flecha Roja",0,4,"o",-1,0,-1,0,54,54,"2926","",0,"","","",1,0,0,[],""],["frenk_t2-n2927",6,"¡Ay!, mi alma, me voy mañana,\nmañana me voy de aquí;\nfrente a tus brazos, mi alma,\npor si me fuera a morir.",111,2,1,101,"La huazanga",0,4,"i",-1,0,-1,0,54,54,"2927","",0,"","","",1,0,0,[],""],["frenk_t2-n2929",6,"Ya con ésta me despido,\nblanca flor de amapolita;\nhoy, por ser la última vez,\ndame a besar tu boquita.",115,2,3,101,"Chinita, no seas así",0,4,"ia",50,0,-1,0,54,54,"2929","",0,"","","",72,0,0,[],""],["frenk_t2-n2930",6,"Al pie de un árbol frondoso\ntriste me senté a llorar;\ncon un llanto lastimoso,\nme voy sin poderte hablar.",121,2,26,101,"La azucena",1,4,"a",21,0,-1,0,54,54,"2930","",0,"","","",1,0,0,[],""],["frenk_t2-n2931",6,"Ya me voy, ya me despido,\nya me ausento del lugar;\nme voy, pero no te olvido,\ntriste y lleno de pesar;\nse va tu amante, querida,\nse va sin poderte hablar.",121,2,26,101,"La azucena",9,6,"a",21,0,-1,0,54,54,"2931","",0,"","","",9,0,0,[],""],["frenk_t2-n2932",6,"Ya me voy con honda pena,\nadiós, princesa gentil,\ncon cantares de sirena,\ndientecitos de marfil,\nencantadora azucena,\nrosita del mes de abril.",105,2,-1,101,"La azucena*’",9,6,"i",290,0,-1,0,55,55,"2932","",0,"","","",1,0,0,[],""],["frenk_t2-n2933",6,"Ya me voy, ¡qué triste pena!,\n¡qué ausente, pues qué dolor!\nAdiós, fragante azucena,\nadiós, encendida flor.",119,2,12,101,"La azucena’’",1,4,"o",72,0,-1,0,55,55,"2933","",0,"","","",1,0,0,[],""],["frenk_t2-n2934",6,"Ya me despido, paloma blanca\nllévate mi alma bajo tus alas;\nyo soy el tigre de Tlalnepantla,\ntú eres paloma de Ixtapalapa.",105,2,-1,101,"Paloma de Ixtapalapa",3,4,"aa",-1,0,-1,0,55,55,"2934","",0,"","","",1,0,0,[],""],["frenk_t2-n2935",6,"Indita del alma,\nyo quisiera, si pudiera.\n¡Adiós, linda del alma,\nqué tristeza y qué dolor!",108,2,8,101,"Indita del alma",5,4,"o",-1,0,-1,0,55,55,"2935","",0,"","","",1,0,0,[],""],["frenk_t2-n2936",6,"Desde aquí te estoy mirando\nsentadita en tu balcón:\n¡qué lejos te vas quedando,\nprenda de mi corazón!",118,2,27,101,"Vasito de agua de coco",1,4,"o",31,0,-1,0,55,55,"2936","",0,"","","",20,0,0,[],""],["frenk_t2-n2937",6,"Yo me subí a un alto pino (¡ay, Llorona!),\npor ver si te divisaba,\ny como el pino era tierno (Llorona),\nde verme llorar, lloraba.",108,2,8,101,"La Llorona; Al pasar por tu ventana",3,4,"aa",28,0,-1,0,55,55,"2937","",0,"","","",1,0,0,[],""],["frenk_t2-n2938",6,"Me subí al pino más alto\npa ver si te devisaba;\ncomo no te devisé,\npensé que me desplomaba.",107,2,11,101,"La Llorona",0,4,"aa",28,0,-1,0,55,55,"2938","",0,"","","",1,0,0,[],""],["frenk_t2-n2939",6,"Ya se va el ausente,\nya se Va de aquí,\ny se va llorando,\nllorando por ti.",107,2,11,101,"El ausente",0,4,"i",23,0,-1,0,55,55,"2939","",0,"","","",4,0,0,[],""],["frenk_t2-n2940",6,"¡Ay sí, ay sí, ay sí!,\nme muero por ti;\n¡ay no, ay no, ay no!,\nllorando me voy por vos.",105,2,-1,101,"Cielito lindo",3,4,"o",-1,0,-1,0,55,55,"2940","",0,"","","",1,0,0,[],""],["frenk_t2-n2942",6,"Me voy, ya no volveré jamás,\nme llevo el alma partida;\nadiós, bien de mi vida,\nme voy, ya no volveré.",114,2,17,101,"Me voy, ya no volveré jamás",3,4,"e",-1,0,-1,0,56,56,"2942","",0,"","","",1,0,0,[],""],["frenk_t2-n2943",6,"Ya voy a agarrar el tren,\nmañana pienso embarcarme;\nte digo con grande pena\nque vengo a declararme,\nporque todavía no hay quien\nen versos pueda ganarme.",106,2,4,101,"Cuando a despedirme fui",9,6,"ae",35,0,-1,0,56,56,"2943","",0,"","","",1,0,0,[],""],["frenk_t2-n2944",6,"Yo cantando me despido,\nporque ya no te voy a ver,\ny por eso con estilo,\nhoy me debes comprender,\ny por eso con sencillo\nyo se lo doy a saber.",106,2,4,101,"La morena",9,6,"e",20,0,-1,0,56,56,"2944","",0,"","","",1,0,0,[],""],["frenk_t2-n2945",6,"Mañana que no te vea\nyo no sé qué voy a hacer:\nno más suspira y suspira,\npensando en tu querer.",105,2,-1,101,"La despedida",0,4,"e",20,0,-1,0,56,56,"2945","",0,"","","",1,0,0,[],""],["frenk_t2-n2946",6,"¿Qué haré yo?, ¿qué haré yo,\nsi tú te vas a embarcar?\nLloraré, lloraré,\ncuando estés en alta mar.",109,2,7,101,"La morenita",0,4,"a",21,0,-1,0,56,56,"2946","",0,"","","",1,0,0,[],""],["frenk_t2-n2947",6,"No lloro porque te vas,\nni lloro porque te alejas,\nlloro porque a mí me dejas\nherido del corazón.",105,2,-1,101,"La embarcación",5,4,"o",-1,0,-1,0,56,56,"2947","",0,"","","",1,0,0,[],""],["frenk_t2-n2948a",6,"Árbol de la esperanza,\nsostente firme,\nque no lloren tus ojos\nal despedirme.",107,2,11,101,"Cielito lindo",6,4,"ie",184,0,-1,0,56,56,"2948a","",0,"","","",2,0,0,[],""],["frenk_t2-n2949",6,"Linda costeñita,\nno llores por mí,\nque voy a embarcarme\npara Guayaquil.",105,2,-1,101,"La costeñita",0,4,"i",-1,0,-1,0,57,57,"2949","",0,"","","",1,0,0,[],""],["frenk_t2-n2950",6,"Qué triste estarás mañana,\nqué triste estará tu amor,\nmañana cuando amanezca,\nmañana al rayar el sol.",110,2,10,101,"La despedida",0,4,"o",-1,0,-1,0,57,57,"2950","",0,"","","",1,0,0,[],""],["frenk_t2-n2951",6,"Que me voy, me voy, me voy,\nque me voy de aquí;\ntú pensando en que me voy,\ny yo pensando en ti.",108,2,8,101,"La yerbabuena",1,4,"i",23,0,-1,0,57,57,"2951","",0,"","","",1,0,0,[],""],["frenk_t2-n2952",6,"Ojitos negros, aquí se quedan,\naquí se quedan a padecer;\na mí me llevan para otras tierras,\ny tú te quedas a padecer.",120,2,14,101,"Las once son",3,4,"e",-1,0,-1,0,57,57,"2952","",0,"","","",1,0,0,[],""],["frenk_t2-n2953",6,"Tus ojos tristes y huerfanitos\nse quedarán, porque yo me voy,\npero más tristes se quedarán\npor los tormentos que yo les doy.",105,2,-1,101,"El buque de más potencia",3,4,"o",112,0,-1,0,57,57,"2953","",0,"","","",1,0,0,[],""],["frenk_t2-n2954",6,"Pasajero de mi vida,\n¿por qué no dices adiós?\nNo te vayas, no te vayas,\náhi nos iremos los dos;\nsi te llevan prisionero,\nsea por el amor de Dios.",105,2,-1,101,"El pasajero",9,6,"o",87,0,-1,0,57,57,"2954","",0,"","","",1,0,0,[],""],["frenk_t2-n2955",6,"Ya no llores, vida mía,\nya voy llegando a Irapuato;\nque en la estación de Palmira\nyo vi tu bello retrato;\nya ves cómo es el amor,\ncorazón, no seas ingrato.",105,2,-1,101,"Ya no llores, vida mía",9,6,"ao",19,0,-1,0,57,57,"2955","",0,"","","",1,0,0,[],""],["frenk_t2-n2956",6,"Te pido, porque es bueno,\nque tú me esperes allá.\nAdiós, estrella de Venus,\nhermosísima deidad;\nme voy para otros terrenos,\npensando en ti nada más.",108,2,8,101,"La morena",9,6,"a",-1,0,-1,0,57,57,"2956","",0,"","","",1,0,0,[],""],["frenk_t2-n2957",6,"Tú, declara, Tonchita querida,\nyo de ti ya me despido;\nadiós, rosa de Castilla,\nadiós, encarnado lirio;\ntú serás la consentida\nmientras Dios fuere servido.",108,2,8,101,"Antonia",9,6,"io",-1,0,-1,0,57,57,"2957","",0,"","","",1,0,0,[],""],["frenk_t2-n2959",6,"En México está lloviendo,\nen Puebla, la nublazón;\nadiós, Juanita querida,\nte llevo en el corazón.",112,2,6,101,"La Juanita",0,4,"o",31,0,-1,0,58,58,"2959","",0,"","","",2,0,0,[],""],["frenk_t2-n2960",6,"¡Ay, ay, ay, ay!,\nyo ya me voy,\nte llevo dentro, mi vida,\ndel corazón.",108,2,8,101,"La chachalaca",6,4,"o",-1,0,-1,0,58,58,"2960","",0,"","","",3,0,0,[],""],["frenk_t2-n2961",6,"Adiós, linda cruceñita,\nya calma[s]te mi calor;\nno olvidaré tu boquita,\nlindo capullo de flor.",105,2,-1,101,"La cruceñita",1,4,"o",72,0,-1,0,58,58,"2961","",0,"","","",1,0,0,[],""],["frenk_t2-n2963",6,"Cuando salgas de esta tierra,\ndonde tanto te he querido,\nno me olvides un momento:\nde por Dios yo te lo pido.",112,2,6,101,"De mañana en ocho días",0,4,"io",101,0,-1,0,58,58,"2963","",0,"","","",1,0,0,[],""],["frenk_t2-n2964",6,"Muy pronto me voy de aquí,\ncomo lo tengo ofrecido,\ny te has de acordar de mí,\nporque lo tengo sabido\nun refrán que dice así:\nque la ausencia causa olvido.",106,2,4,101,"El siquisirí*",9,6,"io",101,0,-1,0,58,58,"2964","",0,"","","",1,0,0,[],""],["frenk_t2-n2965",6,"Cielo azul, cielo estrellado,\ncielo de presentimientos;\nnegrita, cuando te vayas,\nllévame en tus pensamientos.",108,2,8,101,"Estrofa suelta",0,4,"eo",234,0,-1,0,58,58,"2965","",0,"","","",2,0,0,[],""],["frenk_t2-n2966",6,"Chinita, lo que te encargo\nque cuando de mí te acuerdes\n¡ay!, nunca, nunca olvides\nque fui tu adorador.",105,2,-1,101,"Canción del Interior*",5,4,"o",-1,0,-1,0,59,59,"2966","",0,"","","",1,0,0,[],""],["frenk_t2-n2967",6,"Mujercita consentida,\nno me dejes de querer;\ncuando el destino nos junte\nme quitarás de padecer;\nya se despide tu amante,\nque te ofrece su querer.",105,2,-1,101,"La tempranera",9,6,"e",20,0,-1,0,59,59,"2967","",0,"","","",1,0,0,[],""],["frenk_t2-n2968",6,"Ya me despido llorando\nde ti me voy a ausentar;\nnos seguiremos mojando\nmientras pasa el temporal;\nsólo Dios sabrá hasta cuándo\nnos dejaremos de amar.",105,2,-1,101,"Ahí viene el agua",9,6,"a",-1,0,-1,0,59,59,"2968","",0,"","","",2,0,0,[],""],["frenk_t2-n2969",6,"Lo que te encargo, mi bien,\nque no te olvides de mí,\nque yo estaré\npensando en ti.",114,2,17,101,"Me voy, ya no volveré jamás",3,4,"i",23,0,-1,0,59,59,"2969","",0,"","","",1,0,0,[],""],["frenk_t2-n2970",6,"Bomba me pides,\nbomba te doy:\nnunca me olvides,\nporque me voy.",122,2,13,101,"Estrofa suelta",6,4,"o",112,0,-1,0,59,59,"2970","",0,"","","",2,0,0,[],""],["frenk_t2-n2971",6,"Los besos y las caricias\nque me diste y que te di,\nte los dejo, chaparrita,\npa que te acuerdes de mí.",113,2,2,101,"Chaparrita linda**",0,4,"i",23,0,-1,0,59,59,"2971","",0,"","","",1,0,0,[],""],["frenk_t2-n2972",6,"¡Ay, Soledad, Soledad!,\nSoledad del campo verde,\nmi retrato a ti te queda,\npara que de mí te acuerdes.",106,2,4,101,"El cascabel",0,4,"ee",-1,0,-1,0,59,59,"2972","",0,"","","",18,0,0,[],""],["frenk_t2-n2973",6,"Aquí te dejo estas tres canciones,\npa que las cantes, yo ya me voy;\npa que las cantes con tu boquita,\nque son recuerdos que yo te doy.",118,2,27,101,"El buque de más potencia’*",3,4,"o",112,0,-1,0,59,59,"2973","",0,"","","",1,0,0,[],""],["frenk_t2-n2974",6,"Cuando me vaya\nrecordarás mi pasión;\náhi te dejo este recuerdo\nmuy dentro de tu corazón.",105,2,-1,101,"Clavel deshojado",3,4,"o",31,0,-1,0,59,59,"2974","",0,"","","",1,0,0,[],""],["frenk_t2-n2976",6,"Mañana me voy, mañana,\nmañana me voy de aquí,\ny el consuelo que me queda,\nque te has de acordar de mí.",123,2,20,101,"El Quelite; El cascabel; Estrofa suelta",0,4,"i",23,0,-1,0,60,60,"2976","",0,"","","",2,0,0,[],""],["frenk_t2-n2977",6,"Soy soldado, y la patria me llama\na los campos, que vaya a pelear;\nAdelita, Adelita de mi alma,\nno me vayas, por Dios, a olvidar.",124,2,16,101,"La Adelita",3,4,"a",21,0,-1,0,60,60,"2977","",0,"","","",1,0,0,[],""],["frenk_t2-n2978",6,"Lo que te encargo, morena,\ncuando esté lejos de ti,\nque si estás con otro amante,\nno hagas recuerdos de mí.",105,2,-1,101,"La despedida",0,4,"i",23,0,-1,0,60,60,"2978","",0,"","","",1,0,0,[],""],["frenk_t2-n2980",6,"Oyes, indita del alma,\nquisiera decirte adiós,\nporque me voy de pasada\ny vuelvo a los ocho días.",105,2,-1,101,"El maracumbé",5,4,"ia",-1,0,-1,0,60,60,"2980","",0,"","","",1,0,0,[],""],["frenk_t2-n2982",6,"Conque, quédate, Adela querida,\nyo me voy a la guerra a pelear;\nla esperanza no llevo perdida\nde volverte otra vez a abrazar.",105,2,-1,101,"La Adelita",3,4,"a",21,0,-1,0,61,61,"2982","",0,"","","",1,0,0,[],""],["frenk_t2-n2983",6,"Me voy, pero no te olvido,\nte llevo en el pensamiento,\ny espero en Dios y el feliz momento\nque nos volvamos a ver.",119,2,12,101,"Estrofa suelta",3,4,"e",-1,0,-1,0,61,61,"2983","",0,"","","",1,0,0,[],""],["frenk_t2-n2984",6,"Adiós, bien mío, mi dulce bien,\nadiós, no llores, que he de volver,\nadiós, que sólo que yo me muera,\ndulce bien mío, no volveré.",114,2,17,101,"La despedida",3,4,"e",-1,0,-1,0,61,61,"2984","",0,"","","",1,0,0,[],""],["frenk_t2-n2985",6,"Hermosísimo querer,\n¡cuál hermosa suerte mía!\nHe llegado a conocer\nque ya tú me olvidarías:\n¡con la esperanza que llevo\nque he de volver algún día!",108,2,8,101,"Estrofa suelta",9,6,"ia",-1,0,-1,0,61,61,"2985","",0,"","","",1,0,0,[],""],["frenk_t2-n2986",6,"Eres Conchita de mar,\ndel centro del agua fría;\nme voy sin poderte hablar,\nhermosísima alma mía,\npero llevo la esperanza\nque he de volver algún día.",105,2,-1,101,"Estrofa suelta",9,6,"ia",0,0,-1,0,61,61,"2986","",0,"","","",1,0,0,[],""],["frenk_t2-n2987",6,"Ya me voy, ya me despido,\nya me voy a vacilar,\nno llores, chatita linda,\nque algún día he de regresar.",105,2,-1,101,"El maracumbé",0,4,"a",21,0,-1,0,61,61,"2987","",0,"","","",9,0,0,[],""],["frenk_t2-n2988",6,"Fruterita, párate en la puerta,\nque me voy a despedir,\nque aunque me vaya y te deje,\npero no des qué decir,\nque mi amor es una rueda,\ny rodando ha de venir.",108,2,8,101,"Estrofa suelta",9,6,"i",157,0,-1,0,61,61,"2988","",0,"","","",1,0,0,[],""],["frenk_t2-n2989",6,"Cuando me vaya yo\npara la capital\nhe de volver a tus brazos:\n¿qué remedias con llorar?",105,2,-1,101,"Clavel deshojado",0,4,"a",-1,0,-1,0,61,61,"2989","",0,"","","",1,0,0,[],""],["frenk_t2-n2990",6,"Ya viene silbando el tren,\nmi boleto ya compré,\nno te quedes suspirando,\nque muy pronto volveré.",113,2,2,101,"Chaparrita linda",0,4,"e",77,0,-1,0,61,61,"2990","",0,"","","",1,0,0,[],""],["frenk_t2-n2991",6,"No te quedes suspirando,\nmuy pronto vendré por ti,\npara llevarte conmigo\ncomo te lo prometí.",113,2,2,101,"Chaparrita linda**",0,4,"i",23,0,-1,0,62,62,"2991","",0,"","","",1,0,0,[],""],["frenk_t2-n2992",6,"No estés triste, vida mía,\npronto he de volver por ti;\npara seguimos amando,\nque te entierren junto a mí.",105,2,-1,101,"Un adobe y cuatro velas’’",0,4,"i",23,0,-1,0,62,62,"2992","",0,"","","",1,0,0,[],""],["frenk_t2-n2993",6,"Pues a la leva, leva, leva,\ny a la leva me voy,\nque viniendo de la leva\nya sabes que tuyo soy.",106,2,4,101,"La indita",1,4,"o",112,0,-1,0,62,62,"2993","",0,"","","",1,0,0,[],""],["frenk_t2-n2994",6,"Lo supistes que yo era soldado,\nya mi jefe me llamó a pelear;\nsi me toca en la primera batalla,\nTeresita, te vengo a llevar.",105,2,-1,101,"Teresita",3,4,"a",21,0,-1,0,62,62,"2994","",0,"","","",1,0,0,[],""],["frenk_t2-n2995",6,"Nuestras almas se juraron\nel amarse siempre así;\ntrigueñita de mi vida,\npronto volveré por ti.",105,2,-1,101,"Trigueñita",0,4,"i",23,0,-1,0,62,62,"2995","",0,"","","",1,0,0,[],""],["frenk_t2-n2997",6,"Sabe Dios hasta cuándo, alma mía,\nvolveremos los dos a mirarnos;\nfue preciso, por fin, separarnos\ny partir —¡ay!— muy lejos de aquí.",105,2,-1,101,"Estrofa suelta",3,4,"i",-1,0,-1,0,62,62,"2997","",0,"","","",1,0,0,[],""],["frenk_t2-n2998a",6,"Ya me voy adolorido,\nmirando por mi terreno;\nadiós al fin del amor,\nadiós, ojos halagüeños.",105,2,-1,101,"Ahora pregunto, pregunto",0,4,"eo",-1,0,-1,0,62,62,"2998a","",0,"","","",1,0,0,[],""],["frenk_t2-n2999",6,"De tu ventana a la mía\nme aventates un clavel;\npídele a Dios, Marcianita,\nque nos vuélvamos a ver.",116,2,15,101,"Marcianita",0,4,"e",-1,0,-1,0,63,63,"2999","",0,"","","",10,0,0,[],""],["frenk_t2-n3000",6,"Si la suerte quiere,\npronto volveré,\no tal vez me vaya\npara no volver.",105,2,-1,101,"La costeñita",0,4,"e",-1,0,-1,0,63,63,"3000","",0,"","","",1,0,0,[],""],["frenk_t2-n3001",6,"Ya me despido cantando,\nporque así debe de ser;\nahora que estamos gozando,\nun ratito de placer,\nporque quién sabe hasta cuándo\nnos volveremos a ver.",108,2,8,101,"El siquisirí; El Balajú",9,6,"e",20,0,-1,0,63,63,"3001","",0,"","","",1,0,0,[],""],["frenk_t2-n3002",6,"Si te escribo, morena,\nalgún motivo tendré:\npuedes vestirte de luto:\nsabe Dios si volveré.",105,2,-1,101,"La despedida",0,4,"e",77,0,-1,0,63,63,"3002","",0,"","","",1,0,0,[],""],["frenk_t2-n3003",6,"Me despido con gran sentimiento,\nsabe Dios si te vuelva yo a ver;\npero llevo un amargo tormento,\nen el mundo nunca olvidaré.",109,2,7,101,"Hoy es el día",3,4,"e",-1,0,-1,0,63,63,"3003","",0,"","","",1,0,0,[],""],["frenk_t2-n3004",6,"Ahi te dejo estas palabras\nescritas en un papel:\n“Sólo mi Dios lo sabe,\nquién sabe si volveré.”",108,2,8,101,"Todos los días que amanece",0,4,"e",-1,0,-1,0,63,63,"3004","",0,"","","",1,0,0,[],""],["frenk_t2-n3005",6,"Adiós, y dame la mano,\npor si no volviere a verte;\nno digas que soy tirano:\nlo que tengo es mala suerte;\nel remedio está en la mano.",108,2,8,101,"El trompito",7,5,"ao",81,0,-1,0,63,63,"3005","",0,"","","",1,0,0,[],""],["frenk_t2-n3006",6,"Si acaso yo en la guerra\nme llego a desertar,\ncon un querido amigo\nte mandaré avisar.",105,2,-1,101,"El Colás",0,4,"a",21,0,-1,0,63,63,"3006","",0,"","","",2,0,0,[],""],["frenk_t2-n3007",6,"Si acaso yo en la guerra\nme llegara a morir,\ncon un querido amigo\nte mandaría decir.",106,2,4,101,"El Colás",0,4,"i",157,0,-1,0,63,63,"3007","",0,"","","",2,0,0,[],""],["frenk_t2-n3008",6,"Si en medio de la guerra\nme llegan a matar,\ncon un querido amigo\nte mandaré avisar.",105,2,-1,101,"El Colás",0,4,"a",21,0,-1,0,64,64,"3008","",0,"","","",1,0,0,[],""],["frenk_t2-n3010",6,"Corazón, corazón no estés triste,\nporque te amo con crecido amor;\neres ingrata y no sabes amarme,\nyo a la flor de la costa me voy.",118,2,27,101,"Estrofa suelta",3,4,"o",-1,0,-1,0,64,64,"3010","",0,"","","",1,0,0,[],""],["frenk_t2-n3011",6,"Vengo a cantarte, Zenaida ingrata,\nporque mañana me voy de aquí,\ny si algún día de mí te acuerdas,\n¡ay!, nunca digas que quedó por mí.",105,2,-1,101,"Zenaida",3,4,"i",23,0,-1,0,64,64,"3011","",0,"","","",1,0,0,[],""],["frenk_t2-n3013",6,"A los Estados Unidos\nme despacha tu querer;\nsi amor me hubieras tenido,\nno fueran tantas mis penas.",105,2,-1,101,"Viborita de la mar",5,4,"ea",-1,0,-1,0,64,64,"3013","",0,"","","",1,0,0,[],""],["frenk_t2-n3014",6,"Si no me queréis,\n¿qué le voy a hacer?\nIrme pa mi tierra\ny nunca volver.",105,2,-1,101,"Por quién suspiráis",0,4,"e",20,0,-1,0,64,64,"3014","",0,"","","",2,0,0,[],""],["frenk_t2-n3015",6,"Si no me queréis,\nyo me voy de aquí;\nme llevo la rosa\nde mi curaré.",105,2,-1,101,"Por quién suspiráis",5,4,"e",-1,0,-1,0,64,64,"3015","",0,"","","",2,0,0,[],""],["frenk_t2-n3016",6,"Morena la causa fuiste\nde mi triste desventura;\nadiós, mi bella criatura,\nmañana me voy de aquí.",105,2,-1,101,"La despedida",5,4,"i",-1,0,-1,0,64,64,"3016","",0,"","","",1,0,0,[],""],["frenk_t2-n3017",6,"Morena, morena fuiste,\npor mi dicha y desventura;\ntú te quedas en tus gustos,\nyo me voy, bella criatura.",105,2,-1,101,"La despedida",0,4,"ua",17,0,-1,0,65,65,"3017","",0,"","","",1,0,0,[],""],["frenk_t2-n3018",6,"Ya mi corazón heriste\ncon una flecha de luz;\nla culpa tú la tuviste\nestando juntos los dos;\ndame la mano, y adiós,\nsiquiera por lo que fuiste.",112,2,6,101,"El huerfanito",9,6,"ie",153,0,-1,0,65,65,"3018","",0,"","","",1,0,0,[],""],["frenk_t2-n3019",6,"Me voy, si tú me dejaste\ncon el corazón herido;\nchaparrita de mi vida,\nno me eches en el olvido.",109,2,7,101,"Vengo a cantarte, mi vida",0,4,"io",101,0,-1,0,65,65,"3019","",0,"","","",1,0,0,[],""],["frenk_t2-n3020",6,"Voy a ausentarme, mujer,\nporque tú me has despreciado;\nno has sabido comprender\nque a tus pies arrodillado\nte ofrecí un cariño fiel.",105,2,-1,101,"Estrofa suelta",7,5,"e",-1,0,-1,0,65,65,"3020","",0,"","","",2,0,0,[],""],["frenk_t2-n3021",6,"Me voy para Veracruz,\nporque no he podido hallar\nuna que sea como tú\ny que me sepa estimar,\nporque ya la esclavitud\nno la puedo soportar.",106,2,4,101,"El Balajú",9,6,"a",21,0,-1,0,65,65,"3021","",0,"","","",1,0,0,[],""],["frenk_t2-n3022",6,"Voy a ausentarme, mujer,\nde la tierra en que he sufrido;\nausente irá a padecer\nel hombre que te ha querido:\nno lo volverás a ver.",105,2,-1,101,"Estrofa suelta",7,5,"e",20,0,-1,0,65,65,"3022","",0,"","","",2,0,0,[],""],["frenk_t2-n3023",6,"Yo no hallo cómo hacer,\nno encuentro ningún auxilio;\nes tanto mi padecer:\npara calmar mi martirio\nvoy a ausentarme, mujer.",105,2,-1,101,"Estrofa suelta",7,5,"e",20,0,-1,0,65,65,"3023","",0,"","","",1,0,0,[],""],["frenk_t2-n3024",6,"Con coraje y decisión,\nle dije a mi xk’ech así:\n“Me voy muy lejos de aquí,\npara olvidarme de ti;\nno seas cheech, yo sé tus mañas;\nme voy a tierras extrañas,\nno te acuerdes más de mí.”",122,2,13,101,"Estrofa suelta",4,7,"i",23,0,-1,0,65,65,"3024","",0,"","","",1,0,0,[],""],["frenk_t2-n3025",6,"Será la última ocasión\nque en el mundo me verás;\na verme no volverás,\nsolamente el día del juicio;\ny si te causa perjuicio,\nno lo pienses jamás.",106,2,4,101,"Estrofa suelta",9,6,"a",51,0,-1,0,65,65,"3025","",0,"","","",1,0,0,[],""],["frenk_t2-n3026",6,"Soñando soñé un amor,\ny ese amor fue mi consuelo.\nEs tan grande mi dolor,\nporque hay gentes en el suelo\nque me prohíben tu amor.",112,2,6,102,"Estrofa suelta",7,5,"o",72,0,-1,0,66,66,"3026","",0,"","","",1,0,0,[],""],["frenk_t2-n3027",6,"De los chinos de tu frente\nsale el sol maravillando.\n¿Qué me gano con quererte,\nsi no más te están cuidando?\nMe consolaré con verte,\nporque de besarte, ¿cuándo?",112,2,6,102,"Soy pájaro platanero",9,6,"ao",33,0,-1,0,66,66,"3027","",0,"","","",1,0,0,[],""],["frenk_t2-n3029",6,"Hermosa flor de biznaga,\npulido jardín de andemos,\n¿qué quieres, mi bien, que yo haga,\nsi estar juntos no podemos?\nEl corazón se me parte\ncuando por dicha nos vemos.",108,2,8,102,"Estrofa suelta",9,6,"eo",127,0,-1,0,66,66,"3029","",0,"","","",1,0,0,[],""],["frenk_t2-n3030",6,"Siempre al andar advertí\nabrojos en mi camino;\nno puedo acercarme a ti.\nSi era tan cruel mi destino,\ndime, Dios, ¿por qué nací?",111,2,1,102,"La Malagueña; Soy hijo de padecer",7,5,"i",23,0,-1,0,66,66,"3030","",0,"","","",1,0,0,[],""],["frenk_t2-n3031",6,"La pasión que me has dejado\nla sufro y la sufriré;\npara no servir de enfado,\nmejor me despediré:\nadiós, clavel matizado.",105,2,-1,102,"La azucena",7,5,"ao",14,0,-1,0,66,66,"3031","",0,"","","",1,0,0,[],""],["frenk_t2-n3033",6,"Siempre me voy y te dejo\npara no seguirte un mal,\nnos estaremos mirando\ncada vez que haya lugar.",115,2,3,102,"La sandía; Ya me voy, chaparrita; Estrofa suelta",0,4,"a",-1,0,-1,0,67,67,"3033","",0,"","","",1,0,0,[],""],["frenk_t2-n3034",6,"Ya me voy a despedir\npa que no te comprometas;\nyo no sé amar a escondidas:\nyo a bandera descubierta.",125,2,28,102,"Soy fandanguero",0,4,"ea",-1,0,-1,0,67,67,"3034","",0,"","","",13,0,0,[],""],["frenk_t2-n3035",6,"¿Cómo quieres que yo vaya\na orillas del mar adentro,\nsabiendo que estoy de guardia\ny me regaña mi sargento?",108,2,8,102,"Estrofa suelta",0,4,"eo",-1,0,-1,0,67,67,"3035","",0,"","","",3,0,0,[],""],["frenk_t2-n3037",6,"Sin ti la vida no quiero,\nmejor quisiera la muerte;\nmi cariño es verdadero,\ny cuando dejo de verte,\nmi vida, siento que muero.",112,2,6,102,"Estrofa suelta",7,5,"eo",38,0,-1,0,67,67,"3037","",0,"","","",1,0,0,[],""],["frenk_t2-n3039",6,"Sufro, mi amor, por verte;\nno te doy ya la alegría,\nno te doy tampoco suerte;\nestoy celoso por verte.\n¡Ay, qué pasión, vida mía!\nSufro porque es mi suerte.",106,2,4,102,"El gusto",9,6,"ee",134,0,-1,0,68,68,"3039","",0,"","","",1,0,0,[],""],["frenk_t2-n3040",6,"Ando que me desatinan\ncuando no te veo la cara;\nni la comida me llena,\nni el agua, por ser tan clara.",108,2,8,102,"Estrofa suelta",0,4,"aa",57,0,-1,0,68,68,"3040","",0,"","","",1,0,0,[],""],["frenk_t2-n3041",6,"Ya hace días que no cantaba\nporque gusto no tenía;\ncuando de ti me acordaba\nni el comer me apetecía,\nporque se me revelaba\ntu belleza, vida mía.",106,2,4,102,"Estrofa suelta, El Balajú; Me puse en un espiadero",9,6,"ia",0,0,-1,0,68,68,"3041","",0,"","","",1,0,0,[],""],["frenk_t2-n3042",6,"Yo no sé cuándo es de noche (¡ay, Lloro-\nyo no sé cuándo de día [na!),\nporque no hay luz y no hay sombra (Llo-\nsi no te veo, vida mía. [rona)",108,2,8,102,"La Llorona",3,4,"oa",-1,0,-1,0,68,68,"3042","",0,"","","",1,0,0,[],""],["frenk_t2-n3043",6,"Cada vez que cae la tarde\nse me afigura la muerte,\nsólo de considerar\nque me he de acostar sin verte.",108,2,8,102,"Estrofa suelta",0,4,"ee",134,0,-1,0,68,68,"3043","",0,"","","",4,0,0,[],""],["frenk_t2-n3044a",6,"Cada vez que entra el sol\nse me afigura la muerte;\nlas noches se me hacen largas\npor aquel deseo de verte.",108,2,8,102,"Estrofa suelta",0,4,"ee",134,0,-1,0,68,68,"3044a","",0,"","","",2,0,0,[],""],["frenk_t2-n3045",6,"Por la tarde se me carga\nmás la intención de quererte;\nla noche se me hace larga\ncon el deseo de verte.\n¡Ay, qué suerte tan amarga!\nMejor mándame la muerte.",108,2,8,102,"na!), [La guacamaya",9,6,"ee",134,0,-1,0,68,68,"3045","",0,"","","",1,0,0,[],""],["frenk_t2-n3046",6,"Por todo el orbe terrestre\nte busco, bien de mi vida,\ny si no consigo el verte,\nya me voy, prenda querida;\nme separo de tu lado\na llorar mi triste suerte.",105,2,-1,102,"Ya el águila real voló",9,6,"ee",134,0,-1,0,69,69,"3046","",0,"","","",1,0,0,[],""],["frenk_t2-n3047",6,"Y a la una me levanto,\nporque sueño que te veo;\ny me sirve de quebranto (¡ay, vida mía!),\nporque te tengo en deseo;\ny anegado en tierno llanto.",106,2,4,102,"El pájaro carpintero",7,5,"ao",30,0,-1,0,69,69,"3047","",0,"","","",1,0,0,[],""],["frenk_t2-n3048",6,"Es para mí gran tormento\nno mirar a tu figura;\nla busco en el firmamento,\ninterrogo a la natura,\nporque no tengo contento.",112,2,6,102,"Estrofa suelta",7,5,"eo",94,0,-1,0,69,69,"3048","",0,"","","",1,0,0,[],""],["frenk_t2-n3049",6,"Siento en el alma un suspiro\nel día que dejo de verte,\nporque cuando no te miro\ntriste se encuentra mi suerte.",105,2,-1,102,"Estrofa suelta",1,4,"ee",134,0,-1,0,69,69,"3049","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n3050",6,"Dueña de mi pensamiento\nte nombró mi corazón;\nsi no te miro un momento,\nse apodera la aflicción,\ngrande pena y sentimiento.",112,2,6,102,"Estrofa suelta",7,5,"eo",94,0,-1,0,69,69,"3050","",0,"","","",1,0,0,[],""],["frenk_t2-n3052",6,"Qué bonito cuando llueve,\nque suena la sanjuanera;\ndan las ocho, dan las nueve,\ny yo sin verte siquiera;\nvámonos, si es que te atreves,\na la tierra manzanera.",106,2,4,102,"El pájaro manzanero",9,6,"ea",44,0,-1,0,69,69,"3052","",0,"","","",2,0,0,[],""],["frenk_t2-n3053",6,"¡Ay de mí, Llorona!,\ndéjame llorar;\nla causa de mi llanto\nes que ya no te puedo hablar.",105,2,-1,102,"L a Lloroncita",0,4,"a",21,0,-1,0,69,69,"3053","",0,"","","",35,0,0,[],""],["frenk_t2-n3055",6,"Cuando ausente estoy de ti\nhuye de mí la alegría;\nno hay consuelo para mí:\nsufriendo estoy todavía\ndesde que te conocí.",111,2,1,102,"El ausente; La huazanga; El huerfanito",7,5,"i",23,0,-1,0,70,70,"3055","",0,"","","",1,0,0,[],""],["frenk_t2-n3056",6,"Ando muy apasionado,\nsumamente adolorido;\ncomo no estás a mi lado,\nsiento herido el corazón\nde tanto que te he apreciado.",106,2,4,102,"El apasionado",7,5,"ao",14,0,-1,0,70,70,"3056","",0,"","","",1,0,0,[],""],["frenk_t2-n3058",6,"No tengo hora de contento,\nhuyó de mí la alegría;\ncon tu ausencia nada siento;\nsiento ver la luz del día\ncuando te miro un momento.",105,2,-1,102,"Estrofa suelta",7,5,"eo",94,0,-1,0,70,70,"3058","",0,"","","",2,0,0,[],""],["frenk_t2-n3059",6,"En una mata de ruda\npuse mi amor en audencia.\n¡Ay!, para mí joven pura,\ncorazón, tenme pacencia,\nno me hagas andar sufriendo\npensando sólo en tu ausencia.",115,2,3,102,"La sandía",9,6,"ea",46,0,-1,0,70,70,"3059","",0,"","","",1,0,0,[],""],["frenk_t2-n3060",6,"Mi prieta linda, cómo he sufrido\nteniendo lejos tu amor;\nya jamás podré olvidarte\nsi te quiero con pasión.",105,2,-1,102,"Bonito Montemorelos",3,4,"o",-1,0,-1,0,70,70,"3060","",0,"","","",1,0,0,[],""],["frenk_t2-n3061",6,"Qué bonitas campanitas\nse tocaban en Tepic;\nellas se repican solas\nacordándose de ti.",105,2,-1,102,"Las campanitas",0,4,"i",-1,0,-1,0,70,70,"3061","",0,"","","",6,0,0,[],""],["frenk_t2-n3062",6,"En una redoma de oro\ntengo un amor todavía;\ntodavía suspiro y lloro\npor tu ausencia, vida mía:\n¿dónde estás, bello tesoro,\ndueña de mi idolatría?",121,2,26,102,"La azucena**",9,6,"ia",0,0,-1,0,71,71,"3062","",0,"","","",1,0,0,[],""],["frenk_t2-n3063",6,"Si estoy dormido, te sueño,\ny en mis sueños te deseo;\ndespierto y te siento lejos,\nporque no vienes cuando yo quiero.",105,2,-1,102,"Qué padre es la vida",3,4,"eo",-1,0,-1,0,71,71,"3063","",0,"","","",1,0,0,[],""],["frenk_t2-n3064",6,"Desde que tú te fuiste\nno he visto flores,\nni los pájaros cantan,\nni el agua corre.",108,2,8,102,"Negra del alma; La bamba; El pájaro cú",6,4,"oe",-1,0,-1,0,71,71,"3064","",0,"","","",1,0,0,[],""],["frenk_t2-n3065",6,"Las aves ya no cantan,\nlos astros ya no alumbran,\nlas flores no perfuman,\nporque allí faltó tu amor.",105,2,-1,102,"Canción del Interior",5,4,"o",-1,0,-1,0,71,71,"3065","",0,"","","",1,0,0,[],""],["frenk_t2-n3066",6,"No murmura el arroyuelo\nsi acaso deja de verte;\ntodo es triste desconsuelo,\nno hay placer, nada divierte,\nal no contemplarte el cielo.",112,2,6,102,"Estrofa suelta",7,5,"eo",10,0,-1,0,71,71,"3066","",0,"","","",1,0,0,[],""],["frenk_t2-n3067",6,"Estar ausente es morir\npara quien sabe querer;\nmejor no deseo vivir\nsi ya nunca te he de ver.",105,2,-1,102,"Estrofa suelta",1,4,"e",20,0,-1,0,71,71,"3067","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n3068",6,"Qué tristeza me acompaña\ncuando estoy lejos de ti\nrecordando las caricias\ny los besos que te di.",107,2,11,102,"El pescado nadador**, La Petenera",0,4,"i",23,0,-1,0,71,71,"3068","",0,"","","",1,0,0,[],""],["frenk_t2-n3069",6,"La calle llevo por cama,\nde cabecera un anillo,\nde las paredes me abrazo\npensando que estoy contigo.",105,2,-1,102,"La callejera",0,4,"io",-1,0,-1,0,71,71,"3069","",0,"","","",1,0,0,[],""],["frenk_t2-n3070",6,"Herido de un sentimiento,\nla pasión me dice así:\n“No tengo hora de contento,\nni me puedo hallar sin ti;\nquisiera ser como el viento,\npara estar allá y aquí.”",108,2,8,102,"Estrofa suelta",9,6,"i",23,0,-1,0,72,72,"3070","",0,"","","",1,0,0,[],""],["frenk_t2-n3071",6,"Volar y verte quisiera\ncomo vuela el pensamiento,\npues querer y no poder\nes mi mayor sentimiento.",122,2,13,102,"Estrofa suelta",0,4,"eo",94,0,-1,0,72,72,"3071","",0,"","","",1,0,0,[],""],["frenk_t2-n3072",6,"Toda mi vida he sufrido:\nya me canso de penar;\na mí Dios me ha socorrido,\n¿pero cuándo me irá a dar\nla dicha de estar contigo?",113,2,2,102,"El sacamandú",7,5,"io",-1,0,-1,0,72,72,"3072","",0,"","","",1,0,0,[],""],["frenk_t2-n3073a",6,"Cartas y cartas vienen\npor el correo;\n¿para qué quiero cartas (cielito lindo),\nsi no te veo?",106,2,4,102,"Ciehto Undo",3,4,"eo",66,0,-1,0,72,72,"3073a","",0,"","","",1,0,0,[],""],["frenk_t2-n3074",6,"Entre más cartas me eches,\nsi yo no me ando\npor el correo,\nnada me satisface\nsi no te veo.",106,2,4,102,"El pájaro cú",7,5,"eo",66,0,-1,0,72,72,"3074","",0,"","","",1,0,0,[],""],["frenk_t2-n3075",6,"Cuando te escribí lloré\nde verme en tan gran retiro;\ncuando la carta cerré\nmi corazón dio un suspiro.\n¿Dónde estás que no te ves,\ncorazón, que no te miro?",108,2,8,102,"Estrofa suelta",9,6,"io",222,0,-1,0,72,72,"3075","",0,"","","",1,0,0,[],""],["frenk_t2-n3077",6,"En papel blanco te escribo,\nporque blanca fue mi suerte;\nlos pájaros en el nido\nse quejan amargamente,\ncomo a mí me ha sucedido.",111,2,1,102,"Estrofa suelta",7,5,"io",101,0,-1,0,73,73,"3077","",0,"","","",7,0,0,[],""],["frenk_t2-n3078",6,"Porque vivo en un retiro,\nno puedo yo visitarte;\nhace días que no te miro,\ny me hostiga el preguntarte\nsi no ha llegado un suspire\na tu cama a recordarte.",108,2,8,102,"La morena",9,6,"ae",8,0,-1,0,73,73,"3078","",0,"","","",1,0,0,[],""],["frenk_t2-n3079",6,"A lejana tierra fui,\nbuscando lo que deseaba;\nentre peñascos me vi,\ny no más me consolaba\nel preguntarle por ti\na las aves que me hallaba.",106,2,4,102,"El siquisirí; El Ahualulco",9,6,"aa",28,0,-1,0,73,73,"3079","",0,"","","",1,0,0,[],""],["frenk_t2-n3080",6,"Dame la mano derecha\nque me voy a despedir,\ny si me quieres de cerca,\ndime lo que he de decir:\nque me molesta la ausencia\ny lo que la gente ha de decir.",106,2,4,103,"Corté una calabacita",9,6,"i",-1,0,-1,0,74,74,"3080","",0,"","","",1,0,0,[],""],["frenk_t2-n3081",6,"Ya me vengo a despedir,\nporque me voy y me iré;\nsi no quieres que me vaya,\ncontigo me quedaré.",119,2,12,103,"El cascabel; Chiquitita te vas do...",0,4,"e",77,0,-1,0,74,74,"3081","",0,"","","",3,0,0,[],""],["frenk_t2-n3082",6,"Porque me voy a lo verde,\nya regresaré mañana,\ny acordándome de ti;\nsi no quieres que me vaya,\ncontigo me quedaré.",115,2,3,103,"El veinte",7,5,"e",-1,0,-1,0,74,74,"3082","",0,"","","",2,0,0,[],""],["frenk_t2-n3083",6,"Al cielo doy por testigo\nque yo adorándola estoy;\ntú verás qué haces conmigo:\nme despachas o me voy\no me quedo aquí contigo.",106,2,4,103,"Estrofa suelta",7,5,"io",106,0,-1,0,74,74,"3083","",0,"","","",1,0,0,[],""],["frenk_t2-n3084",6,"Vengo a decirte, bien de mi vida,\nporque comprendo que es mi deber,\nque si tú quieres abandonarme,\ndímelo luego para saber.",106,2,4,103,"Manuelito",3,4,"e",20,0,-1,0,74,74,"3084","",0,"","","",1,0,0,[],""],["frenk_t2-n3085",6,"Ya se reventó el estambre\nde mi columpio lucido.\nSi no quieres que te hable,\nni que me lleve contigo,\nescríbeme lo que sabes\ncon la tinta del olvido.",106,2,4,103,"Estrofa suelta",9,6,"io",-1,0,-1,0,74,74,"3085","",0,"","","",1,0,0,[],""],["frenk_t2-n3086a",6,"El pilar se está cayendo,\nvida mía, detento tú;\nsi me estás aborreciendo,\ndímelo con amplitud.",110,2,10,103,"Estrofa suelta",0,4,"u",-1,0,-1,0,75,75,"3086a","",0,"","","",2,0,0,[],""],["frenk_t2-n3087",6,"Si he de salir desairado,\ndesengáñame diatiro\nporque al mirarme a tu lado\nel corazón me palpita,\nángel, que al mundo has llegado.",105,2,-1,103,"La azucena",7,5,"ao",14,0,-1,0,75,75,"3087","",0,"","","",1,0,0,[],""],["frenk_t2-n3088",6,"Esta flor cautiva la tengo\ny jamás se ha desvirtuado;\nahora resuelto vengo\na saber lo que has pensado\ny saber a qué me atengo.",112,2,6,103,"Estrofa suelta",7,5,"eo",124,0,-1,0,75,75,"3088","",0,"","","",1,0,0,[],""],["frenk_t2-n3089",6,"Yo soy el hombre, mujer,\nque onde quiera te ando espiando;\nyo soy el hombre, mi bien,\nque onde quiera te ando hablando;\ndime si no me has de amar,\npa seguirme emborrachando.\n¡Ay!, no por eso me vayas a abandonar.",112,2,6,103,"Al pie de un árbol",4,7,"a",21,0,-1,0,75,75,"3089","",0,"","","",1,0,0,[],""],["frenk_t2-n3090",6,"En el Banco Mercantil\ntengo dinero ahorrado.\nPor Dios no me hagas sufrir,\nque bastante te he aguantado,\npara irme en ferrocarril\nde Veracruz a Alvarado.",106,2,4,103,"La morena",9,6,"ao",14,0,-1,0,75,75,"3090","",0,"","","",2,0,0,[],""],["frenk_t2-n3092",6,"Vengo a que me desengañes\no a que me des mi retiro,\npara no andarme rodeando,\nsi ha de ser tu amor fingido.",120,2,14,103,"Vengo a que me desengañes",0,4,"io",-1,0,-1,0,75,75,"3092","",0,"","","",1,0,0,[],""],["frenk_t2-n3093",6,"Amorcito consentido,\nyo no más vengo a saber:\ndime si ya no me quieres,\npara no venirte a ver.",105,2,-1,103,"Amorcito consentido",0,4,"e",20,0,-1,0,75,75,"3093","",0,"","","",5,0,0,[],""],["frenk_t2-n3095",6,"Yo no soy tinaja de agua\npara estarme serenando;\ndime si no me has de abrir,\npara irme ya pasando.",126,2,19,103,"El indio mexicano",0,4,"ao",33,0,-1,0,76,76,"3095","",0,"","","",1,0,0,[],""],["frenk_t2-n3096",6,"En esa Hacienda del Trigo\nsembré una mata de arroz;\ndime si ya no me quieres,\nque sea por el amor de Dios.",105,2,-1,103,"Las campanitas",3,4,"o",87,0,-1,0,76,76,"3096","",0,"","","",1,0,0,[],""],["frenk_t2-n3097",6,"Con una de tus amigas\npor áhi te mandé un papel;\nsi lo viste o no lo viste,\nsea por Dios, qué hemos de hacer.",105,2,-1,103,"La chaparrita",0,4,"e",-1,0,-1,0,76,76,"3097","",0,"","","",1,0,0,[],""],["frenk_t2-n3098",6,"El compañero del as\nése es el mentado dos;\ngüerita, si no me quieres,\nchinita, tú lo sabrás.",115,2,3,103,"El dos",5,4,"a",51,0,-1,0,76,76,"3098","",0,"","","",1,0,0,[],""],["frenk_t2-n3099",6,"Si me quieres, dímelo,\ny si no, dame veneno;\nque no es la primera dama\nque muerte le da a su dueño.",106,2,4,103,"El buscapiés",0,4,"eo",-1,0,-1,0,76,76,"3099","",0,"","","",17,0,0,[],""],["frenk_t2-n3100",6,"En medio de tres paredes\nme habla tu amor de repente;\ndime si ya no me quieres:\nno me hables entre los dientes;\npor amor nadie se muere,\nun rato no más se siente.",108,2,8,103,"Estrofa suelta",9,6,"ee",-1,0,-1,0,76,76,"3100","",0,"","","",1,0,0,[],""],["frenk_t2-n3101",6,"Para remediar mi mal\nquiero tu contestación,\nporque sin ese poder\nno podrá mi corazón\npretender a otra mujer.",108,2,8,103,"Traicionera",7,5,"e",20,0,-1,0,76,76,"3101","",0,"","","",1,0,0,[],""],["frenk_t2-n3102",6,"[Oyes], Margarita,\ndime la verdad:\nsi tú no me quieres,\notra me quedrá.",105,2,-1,103,"La güitacocha",0,4,"a",-1,0,-1,0,76,76,"3102","",0,"","","",1,0,0,[],""],["frenk_t2-n3103",6,"Clavelito nacarado,\nnacido de una pared,\ndime si ya no me quieres:\nno faltará a quién querer.",110,2,10,103,"Tanto pasar y pasar",0,4,"e",-1,0,-1,0,77,77,"3103","",0,"","","",1,0,0,[],""],["frenk_t2-n3104",6,"Eres flor de margarita,\nque no se le va el color;\nlo que te encargo, negrita,\nque no manches mi honor:\nes mancha que no se quita,\naunque la pongas al sol.",108,2,8,103,"Estrofa suelta",9,6,"o",-1,0,-1,0,77,77,"3104","",0,"","","",1,0,0,[],""],["frenk_t2-n3105",6,"Tengo un dolor en el alma\nque decírtelo no puedo:\ntengo amor y tengo celos,\ntengo confianza y no tengo.",105,2,-1,103,"Estrofa suelta",0,4,"eo",-1,0,-1,0,77,77,"3105","",0,"","","",4,0,0,[],""],["frenk_t2-n3106",6,"Yo tengo celos del viento,\ntengo celos de la brisa,\ny celos de tu sonrisa,\ncelos de tu pensamiento.",105,2,-1,103,"Estrofa suelta",11,4,"eo",94,0,-1,0,77,77,"3106","",0,"","","",1,0,0,[],""],["frenk_t2-n3107",6,"Las piedras que vas pisando\nvan rodando por la calle,\ny al revés las voy volteando,\npa que no las pise naiden.",105,2,-1,103,"Desde que te vi venir",3,4,"ae",-1,0,-1,0,77,77,"3107","",0,"","","",1,0,0,[],""],["frenk_t2-n3108",6,"Cuando pasas por mi calle (Llorona)\nlas piedras yo voy volteando,\npa que después nadie pise (Llorona)\nlas piedras que vas pisando.",107,2,11,103,"La Llorona",3,4,"ao",33,0,-1,0,77,77,"3108","",0,"","","",1,0,0,[],""],["frenk_t2-n3109",6,"Pensando estoy que te enfermes\ny te quieras confesar:\nque el cura también es hombre\ny te puede enamorar.",115,2,3,103,"El celoso",0,4,"a",21,0,-1,0,77,77,"3109","",0,"","","",1,0,0,[],""],["frenk_t2-n3110",6,"Pensando estoy que te mueras\ny te tenga que enterrar:\nque el pino también es hombre\ny te puede enamorar.",105,2,-1,103,"Estrofa suelta",0,4,"a",21,0,-1,0,77,77,"3110","",0,"","","",1,0,0,[],""],["frenk_t2-n3111",6,"Quisiera hacerte tu caja\nde purito encino roble,\npero me pongo a pensar\nque el roble también es hombre",115,2,3,103,"El celoso",0,4,"oe",-1,0,-1,0,77,77,"3111","",0,"","","",1,0,0,[],""],["frenk_t2-n3113",6,"Tus ojos son dos estrellas\nque brillan por el panteón;\nyo quisiera abrir tu tumba\npara ver tu corazón.",105,2,-1,103,"Canción del Interior*",0,4,"o",31,0,-1,0,78,78,"3113","",0,"","","",2,0,0,[],""],["frenk_t2-n3114",6,"Si el cielo me hiciera un bien,\ny que un rayo te matara,\n¡qué muerte tan a mi gusto\npa que nadie te gozara!",105,2,-1,103,"Vasito de agua de coco",0,4,"aa",57,0,-1,0,78,78,"3114","",0,"","","",1,0,0,[],""],["frenk_t2-n3115",6,"No quiero que a misa vayas,\nni que a los templos te asomes,\nni tomes agua bendita\nde donde toman los hombres.",105,2,-1,103,"El celoso*’",0,4,"oe",-1,0,-1,0,78,78,"3115","",0,"","","",7,0,0,[],""],["frenk_t2-n3116",6,"No quiero que al agua bajes\nal punto dé la oración:\nno sea que alguna viejita\nte traiga alguna razón.",105,2,-1,103,"El celoso",0,4,"o",31,0,-1,0,78,78,"3116","",0,"","","",1,0,0,[],""],["frenk_t2-n3118",6,"Yo no sé qué buscas,\npor qué vas volteando:\nparece que hay alguien\nque te está esperando.",105,2,-1,103,"Los celotes",0,4,"ao",33,0,-1,0,78,78,"3118","",0,"","","",1,0,0,[],""],["frenk_t2-n3119",6,"Tu boquita colorada\n¿a quién le andará sonriendo?\nQuiera Dios que sus besos\nno los ande repartiendo.",105,2,-1,103,"Boquita colorada",0,4,"eo",-1,0,-1,0,78,78,"3119","",0,"","","",1,0,0,[],""],["frenk_t2-n3120",6,"Haciendo currucucú,\ncurrucucú te vas quedando;\n¡ay!, ’ma mía de mi chiquita:\n¿en quén estará pensando?",105,2,-1,103,"La suegra’*",0,4,"ao",33,0,-1,0,78,78,"3120","",0,"","","",1,0,0,[],""],["frenk_t2-n3121",6,"¿Por quién suspiráis\nestando yo aquí?\nEse suspirito\nno será pa mí.",105,2,-1,103,"Por quién suspiráis",0,4,"i",23,0,-1,0,78,78,"3121","",0,"","","",1,0,0,[],""],["frenk_t2-n3122",6,"Del cielo venía una carta,\namorcito consentido,\ny en tu puerta se paró:\ndime quién te escribió.",105,2,-1,103,"Amorcito consentido",5,4,"o",2,0,-1,0,79,79,"3122","",0,"","","",1,0,0,[],""],["frenk_t2-n3123",6,"Que amanece, que amanece,\nválgame que amaneció;\n¿si estarás con otro dueño\ny a mí me dirás que no?",105,2,-1,103,"Las mañanitas",0,4,"o",2,0,-1,0,79,79,"3123","",0,"","","",1,0,0,[],""],["frenk_t2-n3124",6,"Dices que no la quieres,\nni vas a verla,\npero la veredita\nno cría yerba.",122,2,13,103,"Estrofa suelta",6,4,"ea",-1,0,-1,0,79,79,"3124","",0,"rm_t3","","",4,0,0,[],""],["frenk_t2-n3125a",6,"Ya el capire se secó,\nteniendo el agua en el pie;\nasí se seca mi amor\ncuando con otra te ve.",105,2,-1,103,"Estrofa suelta",0,4,"e",77,0,-1,0,79,79,"3125a","",0,"","","",2,0,0,[],""],["frenk_t2-n3125c",6,"El capire se secó,\nteniendo el agua en el pie;\nasí se seca mi amor\ncuando con otra te ve;\ntienen las hojas razón,\npero el capire, ¿por qué?",105,2,-1,103,"El capire",9,6,"e",77,0,-1,0,79,79,"3125c","",0,"","","",1,0,0,[],""],["frenk_t2-n3127",6,"Si tienes amor con otro,\nno hagas recuerdos de mí,\nque yo le pido a mi Dios\nno acordarme más de ti.",105,2,-1,103,"Estrofa suelta",0,4,"i",23,0,-1,0,79,79,"3127","",0,"","","",1,0,0,[],""],["frenk_t2-n3128",6,"Bonitas fuentes son las corrientes\ncuando comienza la tempestad;\ny si tu amor a otro hombre das,\nde puros celos me matarás.",107,2,11,103,"Las fuentes",3,4,"a",51,0,-1,0,79,79,"3128","",0,"","","",2,0,0,[],""],["frenk_t2-n3130",6,"De noche vienes, de día te vas,\ndime, mi vida, con quién estás;\ny si tu amor no me sabes dar,\ntambién mis ojos saben llorar.",105,2,-1,103,"Las fuentes",3,4,"a",21,0,-1,0,80,80,"3130","",0,"","","",3,0,0,[],""],["frenk_t2-n3131",6,"—De noche vienes, de día te vas,\ndime, morena, ¿con quién estas?\n—No estoy con naiden, ven y verás;\nde puros celos me matarás.",107,2,11,103,"Las fuentes",3,4,"a",51,0,-1,0,80,80,"3131","",0,"","","",3,0,0,[],""],["frenk_t2-n3132",6,"Ya con ésta me despido,\npajarillo barranqueño;\nlástima que seas ingrata\ny que tengas otro dueño.",105,2,-1,103,"Pajarillo barranqueño",0,4,"eo",138,0,-1,0,80,80,"3132","",0,"","","",72,0,0,[],""],["frenk_t2-n3133a",6,"En un gajo de grosella\nse sentó un chupasajar,\ny le dijo una doncella:\n“Más constante te he de amar.”",107,2,11,103,"Estrofa suelta",1,4,"a",21,0,-1,0,80,80,"3133a","",0,"","","",2,0,0,[],""],["frenk_t2-n3134a",6,"Del cielo cayó una piedra\ny en tu ventana pegó;\ndime si tienes amores,\npara no meterme yo.",105,2,-1,103,"Amorcito consentido",0,4,"o",2,0,-1,0,80,80,"3134a","",0,"","","",1,0,0,[],""],["frenk_t2-n3134c",6,"Un día te escribí una carta,\nel viento se la llevó;\ndime si estás enredada,\npara no enredarme yo.",105,2,-1,103,"La carta",0,4,"o",2,0,-1,0,80,80,"3134c","",0,"","","",2,0,0,[],""],["frenk_t2-n3135",6,"Ojitos aceitunados,\nhora traigo sentimiento;\nsi tienes nuevos amores,\navísamelo al momento.",105,2,-1,103,"Estrofa suelta",0,4,"eo",94,0,-1,0,81,81,"3135","",0,"","","",4,0,0,[],""],["frenk_t2-n3136",6,"Ya con ésta me despido,\ndeshojando una rosita;\nsi nuevos amores tienes,\ndame un beso en tu boquita.",115,2,3,103,"El tilanguero",0,4,"ia",50,0,-1,0,81,81,"3136","",0,"","","",72,0,0,[],""],["frenk_t2-n3137",6,"Soy de Tampico y Durango,\nde deveras soy de allá.\nYo sé que te andas casando,\nconfiésame la verdad,\npara no seguirte amando,\nni tenerte voluntad.",112,2,6,103,"La leva",9,6,"a",16,0,-1,0,81,81,"3137","",0,"","","",1,0,0,[],""],["frenk_t2-n3138",6,"Sé que ya te vas a casar (¡ay, Llorona!):\nanda con Dios, bien mío;\npor el tiempo que ande ausente (¡ay, Lio-\nno bebas agua del río, [roña!)\nni dejes amor pendiente (¡ay, Llorona!),\ncomo dejaste al mío.",108,2,8,103,"La Llorona",9,6,"io",3,0,-1,0,81,81,"3138","",0,"","","",1,0,0,[],""],["frenk_t2-n3139",6,"De tierras lejanas vengo,\ncansado de caminar,\na conocer al que te ama,\npara no volverte a hablar.",105,2,-1,103,"La sandía; Ei frijolar",0,4,"a",21,0,-1,0,81,81,"3139","",0,"","","",2,0,0,[],""],["frenk_t2-n3140a",6,"Un pajarillo me avisa\nque es otro el que te pretende;\nsi es otro mejor que yo,\nde tu corazón depende,\ny aunque me digas que no.",108,2,8,103,"Traicionera",7,5,"o",2,0,-1,0,81,81,"3140a","",0,"","","",1,0,0,[],""],["frenk_t2-n3142c",6,"Si tienes quien te la lea,\nmándame decir quién es,\npara escribirte una carta\ncon las letras al revés.",127,2,18,103,"Ojitos negros y chinos",0,4,"e",218,0,-1,0,82,82,"3142c","",0,"","","",1,0,0,[],""],["frenk_t2-n3143",6,"Cuando paso por tu casa\npor el barrio del borrego,\nme haces señas y te agachas,\ny luego me echas los perros.",105,2,-1,103,"Nicolasa",0,4,"eo",-1,0,-1,0,82,82,"3143","",0,"","","",7,0,0,[],""],["frenk_t2-n3144",6,"Tiempo ha que te ando diciendo yo,\ny tú no me dices nada:\n¿si me andarás trayendo, sí,\nabajo y arriba del pedregal?.",105,2,-1,103,"El pedregal",3,4,"a",-1,0,-1,0,82,82,"3144","",0,"","","",1,0,0,[],""],["frenk_t2-n3145",6,"Dices que me has de ir a ver\nescondidas de tu mamá:\nasí me andarás trayendo\narriba del pedregal.",105,2,-1,103,"El .pedregal",0,4,"a",-1,0,-1,0,82,82,"3145","",0,"","","",1,0,0,[],""],["frenk_t2-n3147",6,"Ayer me dijiste que ahora,\nahora me dirás que mañana,\ny mañana me dirás:\n“Se me fueron las ganas.”",108,2,8,103,"Estrofa suelta",3,4,"aa",-1,0,-1,0,83,83,"3147","",0,"","","",1,0,0,[],""],["frenk_t2-n3148",6,"Negrita de mis pesares,\nojos de papel volando,\na todos diles que sí,\npero no les digas cuándo;\nasí me dijiste a mí,\npor eso vivo penando.",115,2,3,103,"La negra",9,6,"ao",33,0,-1,0,83,83,"3148","",0,"","","",1,0,0,[],""],["frenk_t2-n3149",6,"Parece que ya va a llover,\nya viene relampagueando;\nno más me das esperanzas,\npero no me dices cuándo.",115,2,3,103,"El relámpago",0,4,"ao",33,0,-1,0,83,83,"3149","",0,"","","",1,0,0,[],""],["frenk_t2-n3151c",6,"En una mesa te puse\nun par de limón con hojas.\nSi me retiro, te enojas,\nsi me acerco, te retiras:\nindita, no seas ansina,\nno me traigas en congojas.",112,2,6,103,"El sombrero",9,6,"oa",364,0,-1,0,84,84,"3151c","",0,"","","",7,0,0,[],""],["frenk_t2-n3152",6,"Cuando te quiero te vas,\ncuando no te quiero vienes;\ndime por qué no te estás\ndonde más cuenta tú tienes.",108,2,8,103,"Que comienzo, que comienzo",1,4,"ee",120,0,-1,0,84,84,"3152","",0,"","","",1,0,0,[],""],["frenk_t2-n3153",6,"¿Por qué te ocultas cuando me miras?,\n¿por qué te ocultas, mi bien, así?\n¿Cuál es el crimen que he cometido\ncon ’berte amado no más a ti?",114,2,17,103,"Indita mía",3,4,"i",23,0,-1,0,84,84,"3153","",0,"","","",1,0,0,[],""],["frenk_t2-n3154",6,"Agua le pido yo al pozo\ndonde beben las palomas;\ndime qué te ha sucedido,\nque ni a la puerta te asomas.",105,2,-1,103,"Estrofa suelta, Pajarillo barranqueño",0,4,"oa",521,0,-1,0,84,84,"3154","",0,"","","",1,0,0,[],""],["frenk_t2-n3155",6,"Anoche soñaba yo\nque dos negros me mataban,\ny eran tus hermosos ojos,\nque enojados me miraban.",105,2,-1,103,"El parreño; La balanza; El jarabe; Lucero de la mañana; La Llorona; Los sueños míos; Estrofa suelta",0,4,"aa",39,0,-1,0,84,84,"3155","",0,"rm_t2, palau_cantares, lafuente_madrid, fernan_caballero","","",9,0,0,[],""],["frenk_t2-n3156",6,"Al acostarme ayer,\ntuve yo un sueño:\nme miraron tus ojos\ncon muy mal ceño.",105,2,-1,103,"Estrofa suelta",6,4,"eo",138,0,-1,0,84,84,"3156","",0,"","","",1,0,0,[],""],["frenk_t2-n3157",6,"Las aguas han de correr\ncuando te sientes conmigo;\ny yo soy del parecer\ny he vivido convencido\nque han de volverse a querer\nlos que antes se han querido.",106,2,4,103,"El totolito",9,6,"io",101,0,-1,0,84,84,"3157","",0,"","","",1,0,0,[],""],["frenk_t2-n3158",6,"Por una cruel ignorancia\nte he visto de esta manera;\npero vivo en la confianza\nque he de hacer lo que yo quiera\ncon el tiempo y la esperanza:\nsolamente que me muera.",108,2,8,103,"Indita del alma",9,6,"ea",44,0,-1,0,85,85,"3158","",0,"","","",1,0,0,[],""],["frenk_t2-n3159",6,"Áhi te envío mi corazón,\nadolorido y marchito;\nlo llevan dos pajaritos\na darte satisfacción.",108,2,8,103,"Estrofa suelta",3,4,"o",-1,0,-1,0,85,85,"3159","",0,"","","",1,0,0,[],""],["frenk_t2-n3160",6,"Sentir de mí no tendrás,\nni mala ausencia ninguna;\nrecapacita y verás\ncuál anda mi cruel fortuna,\ndándose gustos no más,\nlo que no ha hecho con ninguna",108,2,8,103,"El trompito",9,6,"ua",56,0,-1,0,85,85,"3160","",0,"","","",1,0,0,[],""],["frenk_t2-n3161",6,"Me darás una balanza\ndonde quepa todo el mar,\npara poderte explicar\nlo que ignoras y no alcanzas:\nen mí no hallarás mudanza\nni mi entendimiento atroz;\nsabrás que Cristo paró\nen un sepulcro sereno;\ny en este ligero sueño\nla ausencia me recordó.",106,2,4,103,"Estrofa suelta",18,10,"o",2,0,-1,0,85,85,"3161","",0,"","","",1,0,0,[],""],["frenk_t2-n3162",6,"Si supiera que llorando\nse calmarían tus enojos,\nyo me viviría regando\ncon lágrimas de mis ojos\nla tierra que andas pisando.",106,2,4,103,"El aguanieve; La huazanga; La Malagueña; La pasión; Estrofa suelta",7,5,"ao",33,0,-1,0,85,85,"3162","",0,"","","",1,0,0,[],""],["frenk_t2-n3164",6,"¿Quieres verme arrodillado,\npara mal calificarme?\nMorir no me da temor:\nse me hace feo humillarme\nante de un cielo amado.",111,2,1,103,"La madrugada; El ausente",7,5,"ao",14,0,-1,0,85,85,"3164","",0,"","","",1,0,0,[],""],["frenk_t2-n3165",6,"Por no querer perdonarte,\nme está matando el dolor,\ny aunque mi rostro sonría,\nestoy llorando de amor.",105,2,-1,103,"Llora, corazón",0,4,"o",72,0,-1,0,85,85,"3165","",0,"","","",1,0,0,[],""],["frenk_t2-n3167",6,"Dices que tú has padecido,\nque has padecido por mí;\nestamos correspondidos,\nsi también sufro por ti,\nsin haber ningún motivo.",113,2,2,103,"Estrofa suelta",7,5,"io",-1,0,-1,0,86,86,"3167","",0,"","","",1,0,0,[],""],["frenk_t2-n3168",6,"Tú sentida, yo sentido;\na ver quién sentirá más\nyo no te daba motivos,\ntú eres la que me los das.",108,2,8,103,"Estrofa suelta",0,4,"a",51,0,-1,0,86,86,"3168","",0,"","","",1,0,0,[],""],["frenk_t2-n3169",6,"Muy de mañana te fuiste a misa,\nde mala gana yo me vestí,\nel desayuno quedó en la mesa,\nni tú almorzaste, ni yo comí.",105,2,-1,103,"Buscando peces",3,4,"i",23,0,-1,0,86,86,"3169","",0,"","","",1,0,0,[],""],["frenk_t2-n3170",6,"En los carriles del viento\nse me deshojó una flor.\nyo también tengo dolor:\naunque pobre, pero siento\nlos desprecios de tu amor.",106,2,4,103,"Estrofa suelta, La azucena; El caballito; El huerfanito; El siquisirí; Ya no llores, vida mía",7,5,"o",72,0,-1,0,86,86,"3170","",0,"","","",1,0,0,[],""],["frenk_t2-n3171",6,"Si un día te fuiste de mí\ny hoy vuelves, ¡demonios!, ¿qué hago?\nSi te perdono, ¿pa qué?,\nsi te maldigo, ¿qué gano?\nMejor tú sigue feliz,\ny a mí que me lleve el diablo.",105,2,-1,103,"Que me lleve el diablo",9,6,"ao",-1,0,-1,0,86,86,"3171","",0,"","","",1,0,0,[],""],["frenk_t2-n3172",6,"Las flores que tú me diste\nse están muriendo de frío;\nlas que ayer tarde pusiste\nsobre mi pecho, amor mío,\nse están helando de frío.",114,2,17,103,"Estrofa suelta",7,5,"io",3,0,-1,0,86,86,"3172","",0,"","","",2,0,0,[],""],["frenk_t2-n3173",6,"Por abril vuelven las golondrinas\nsus blandos nidos a reconstruir;\npero a mi alma, bien de mi vida,\nquizá ya nunca vuelvas allí.",105,2,-1,103,"Estrofa suelta",3,4,"i",-1,0,-1,0,86,86,"3173","",0,"","","",1,0,0,[],""],["frenk_t2-n3174",6,"Chaparrita de mi vida,\nya mi corazón se une;\nse me hace que no me quieres:\naquí la pluma se sume.",105,2,-1,103,"Jilguero desvanecido",0,4,"ue",-1,0,-1,0,87,87,"3174","",0,"","","",7,0,0,[],""],["frenk_t2-n3175",6,"Dicen que estás enfermo\ndel corazón:\nla enfermedad que tienes (cielito lindo)\nes de pasión.\nMe lo juraste.\n¿Eso es lo que me quieres (cielito lindo)?\n¡Ya te olvidaste!",106,2,4,103,"Cielito lindo",4,7,"ae",212,0,-1,0,87,87,"3175","",0,"","","",1,0,0,[],""],["frenk_t2-n3176",6,"Dices que me quieres mucho,\nes mentira, tú me engañas:\nen un corazón tan chico\nno pueden caber dos almas.",106,2,4,103,"Estrofa suelta",0,4,"aa",-1,0,-1,0,87,87,"3176","",0,"","","",13,0,0,[],""],["frenk_t2-n3177",6,"Si la luna no menguara,\nno se viera desvarío,\ntu cariño no cambiara,\ntodo tu amor fuera mío;\npero por esas volteadas\nsiempre buscas el desvío.",106,2,4,103,"El Balajú",9,6,"io",3,0,-1,0,87,87,"3177","",0,"","","",4,0,0,[],""],["frenk_t2-n3178",6,"A orillas de una laguna,\noí relinchar a un potro:\n¡cómo dices que me quieres,\ny andas con uno y con otro!",108,2,8,103,"Estrofa suelta",3,4,"oo",275,0,-1,0,87,87,"3178","",0,"","","",4,0,0,[],""],["frenk_t2-n3179",6,"Qué bonitos ojos tienes,\npero son engañadores;\n¡cómo dices que me quieres\ny me andas cambiando amores!",108,2,8,103,"Estrofa suelta",0,4,"oe",5,0,-1,0,87,87,"3179","",0,"","","",4,0,0,[],""],["frenk_t2-n3180",6,"Sanluisteca de mi vida,\nSanluisteca de mi amor,\ntus ojos encantadores\nengañan a cuantos ven.",109,2,7,103,"Sanluisteca",5,4,"e",-1,0,-1,0,87,87,"3180","",0,"","","",1,0,0,[],""],["frenk_t2-n3181",6,"Las pitayas y las tunas\ntienen rojo el corazón;\nlas muchachas que no quieren\nson de palo guayacol;\ny si tú eres de madera,\n¡pobrecito de mi amor!",115,2,3,103,"Si supieras, chaparrita",9,6,"o",-1,0,-1,0,87,87,"3181","",0,"","","",1,0,0,[],""],["frenk_t2-n3182",6,"Dormida estaba y te vi\nque tú me dabas la mano;\npero yo te dije a ti:\n“Que si tú juras en vano,\nno hay consuelo para mí.”",106,2,4,103,"El aguanieve",7,5,"i",23,0,-1,0,87,87,"3182","",0,"","","",1,0,0,[],""],["frenk_t2-n3184",6,"Ámapolita morada\nde los llanos de Tepic,\n¿dónde estás, enajenada,\nque no te acuerdas de mí?",110,2,10,103,"Las mañanitas; La guacamaya",0,4,"i",-1,0,-1,0,88,88,"3184","",0,"","","",3,0,0,[],""],["frenk_t2-n3185",6,"Siempre que yo vengo a verte\nme encuentro con que has salido:\npájaro que alza su vuelo\ncasi siempre vuelve herido;\ny yo jamás te pregunto:\n“Chinita, ¿dónde te has ido?”",116,2,15,103,"La voltereta",9,6,"io",101,0,-1,0,88,88,"3185","",0,"","","",1,0,0,[],""],["frenk_t2-n3186",6,"Era china, china, china,\nchinita de las pestañas;\nchinita, si no me quieres,\ndime pues, ¿por qué me engañas?",105,2,-1,103,"Estrofa suelta, La chinita maderista",0,4,"aa",42,0,-1,0,88,88,"3186","",0,"","","",1,0,0,[],""],["frenk_t2-n3187",6,"Mi vida, si no me quieres,\n¿por qué me miras?\n¿No ves que tu mirada\nincendia mi alma? (sic).",105,2,-1,103,"Estrofa suelta",3,4,"i",-1,0,-1,0,88,88,"3187","",0,"","","",1,0,0,[],""],["frenk_t2-n3188",6,"Ven, mi querido dos,\ncompañerito del tres;\nchinita, si no me quieres,\nolvídame de una vez.",115,2,3,103,"El dos",0,4,"e",150,0,-1,0,88,88,"3188","",0,"","","",2,0,0,[],""],["frenk_t2-n3189",6,"Ya las torres se cayeron,\nya se están apolillando;\ndime, negro, la verdad:\n¿o es que me estás engañando?",108,2,8,103,"Estrofa suelta",0,4,"ao",33,0,-1,0,88,88,"3189","",0,"","","",2,0,0,[],""],["frenk_t2-n3190",6,"Andando en el surco arando,\nse me previno el quererte;\nsi me has de andar engañando,\nmejor mándame la muerte:\nno me hagas andar penando.",105,2,-1,103,"Estrofa suelta",7,5,"ao",33,0,-1,0,88,88,"3190","",0,"","","",1,0,0,[],""],["frenk_t2-n3191",6,"Por el ojo de una aguja\nmemorias te estoy mandando;\npor vida tuya, Refugia,\nno me sigas engañando,\nque no soy hijo de bruja.",112,2,6,103,"Estrofa suelta",7,5,"ua",-1,0,-1,0,88,88,"3191","",0,"","","",2,0,0,[],""],["frenk_t2-n3192",6,"O no quere usted\no en su casa no querrán,\nporque no me había contado\nque se iba su quiriquiqui.",105,2,-1,103,"Los papaquis",5,4,"ii",-1,0,-1,0,89,89,"3192","",0,"","","",1,0,0,[],""],["frenk_t2-n3193",6,"—Pasa, paloma, pasa pa dentro,\nque te reciba mi corazón.\n—No entro ni paso, ni paso ni entro,\nporque me juegas una traición.",107,2,11,103,"Las fuentes",3,4,"o",-1,0,-1,0,89,89,"3193","",0,"","","",1,0,0,[],""],["frenk_t2-n3194",6,"Yo quisiera ser un santo,\npero mi genio es veloz;\nsi no has oído mi llanto,\nescucha mi triste voz,\nmariposa del encanto.",105,2,-1,104,"Me puse en un espiadero; Estrofa suelta",7,5,"ao",30,0,-1,0,90,90,"3194","",0,"","","",1,0,0,[],""],["frenk_t2-n3195",6,"Escucha con atención,\nfíjate en mis pensamientos,\nmira si tengo razón;\nescucharás los lamentos\nque abrigan mi corazón.",105,2,-1,104,"El sacamandú",7,5,"o",31,0,-1,0,90,90,"3195","",0,"","","",1,0,0,[],""],["frenk_t2-n3196",6,"Mi corazón te ha escogido,\ny llorar no quiero verlo;\nya el pobre mucho ha sufrido,\ny ahora tienes que quererlo.",105,2,-1,104,"Serenata huasteca",3,4,"eo",203,0,-1,0,90,90,"3196","",0,"","","",1,0,0,[],""],["frenk_t2-n3197",6,"Soy un triste rancherito\nque ahora me vivo cantando,\nporque me encuentro sohto,\ny ahora le estoy suplicando\nque me manden consolito.",106,2,4,104,"El lelito",7,5,"io",119,0,-1,0,90,90,"3197","",0,"","","",1,0,0,[],""],["frenk_t2-n3198",6,"Si el corazón me pidieras,\nte lo diera sin dolor,\ntan sólo por conseguir\nlas caricias de tu amor,\nque son las que hacen sufrir.",105,2,-1,104,"Estrofa suelta",7,5,"i",157,0,-1,0,90,90,"3198","",0,"","","",4,0,0,[],""],["frenk_t2-n3199",6,"Si supieras, chaparrita,\nlo que sufro yo por ti,\ntal vez te compadecieras\nde verme tanto sufrir,\ny entonces tu carita\nno me diera en qué sentir.",115,2,3,104,"Si supieras, chaparrita",9,6,"i",157,0,-1,0,90,90,"3199","",0,"","","",1,0,0,[],""],["frenk_t2-n3200",6,"Corté la flor del candó\ny la rebané en un plato.\nCada vez que sale el sol\nme acuerdo de tu retrato;\nmira lo que hace el amor:\ncorazón, no seas ingrato.",108,2,8,104,"Estrofa suelta",9,6,"ao",19,0,-1,0,90,90,"3200","",0,"","","",1,0,0,[],""],["frenk_t2-n3201",6,"Que no te sirva de enfado,\njoven de mi pretensión;\nmira, tengo el corazón\nde tu mano destrozado.",106,2,4,104,"El fandanguito",11,4,"ao",14,0,-1,0,91,91,"3201","",0,"","","",1,0,0,[],""],["frenk_t2-n3202",6,"Tengo lo menos de mil\npadeceres por tu amor;\ncalma, calma mi dolor,\ncucucha del mes de abril;\n¡hasta cuándo echará flor\ncomo el palo de macuil!",108,2,8,104,"Estrofa suelta",9,6,"i",290,0,-1,0,91,91,"3202","",0,"","","",1,0,0,[],""],["frenk_t2-n3203",6,"Mi vida, yo estoy aquí,\nquien por ti se desespera;\nmi corazón padecer\nparece que se muriera,\nporque es muy triste, mujer,\nquererte y que no te quieran.",105,2,-1,104,"La morena",9,6,"ea",-1,0,-1,0,91,91,"3203","",0,"","","",1,0,0,[],""],["frenk_t2-n3204",6,"El alma tengo llena\nde sinsabores;\narráncame de mi alma\nestos dolores.",105,2,-1,104,"Estrofa suelta",6,4,"oe",5,0,-1,0,91,91,"3204","",0,"","","",3,0,0,[],""],["frenk_t2-n3205",6,"Preso estoy en la cárcel\npor tus quereres;\nno saldré de este sitio\nsi no me quieres.",105,2,-1,104,"Estrofa suelta",6,4,"ee",55,0,-1,0,91,91,"3205","",0,"","","",1,0,0,[],""],["frenk_t2-n3206",6,"Siquiera por compasión,\ndirígeme una mirada;\nfíjate en tu cruel traición,\nque ésta queda compensada\ncon mi cruel separación.",105,2,-1,104,"El sacamandú",7,5,"o",31,0,-1,0,91,91,"3206","",0,"","","",1,0,0,[],""],["frenk_t2-n3207",6,"Me subí por una higuera\na cortar la flor rubí.\n¡Qué suerte tan desgraciada\ntraigo desde que nací!\n¿Es posible, prenda amada,\nque usted no sea para mí?",106,2,4,104,"Estrofa suelta",9,6,"i",23,0,-1,0,91,91,"3207","",0,"","","",1,0,0,[],""],["frenk_t2-n3208",6,"Cada vez que cae la tarde (Llorona)\nme pongo a pensar y digo:\n¿de qué me sirve la cama (¡ay, Llorona!)\nsi tú no duermes conmigo?",108,2,8,104,"La Llorona; La Sanmarqueña; La Zandunga",3,4,"io",106,0,-1,0,91,91,"3208","",0,"","","",1,0,0,[],""],["frenk_t2-n3209",6,"Ya no sé por qué razón\ntú no me quieres a mí;\nte vales de la ocasión\nporque sabes que por ti\nsuspira mi corazón.",113,2,2,104,"La presumida",7,5,"o",31,0,-1,0,91,91,"3209","",0,"","","",1,0,0,[],""],["frenk_t2-n3210",6,"Te quiero y no me arrepiento,\ny yo de coraje te amo,\npero cargo un sentimiento:\nque no vas donde te llamo,\ny por ese sufrimiento\nenfermo estoy y no sano.",106,2,4,104,"La morena",9,6,"ao",-1,0,-1,0,92,92,"3210","",0,"","","",1,0,0,[],""],["frenk_t2-n3211",6,"Un cintillo doble y fuerte\na nuestro amor amarró,\nque es mi pasión tan fuerte;\nal ver parece que no,\npero anda, ingrata, y advierte.",105,2,-1,104,"Estrofa suelta",7,5,"ee",134,0,-1,0,92,92,"3211","",0,"","","",1,0,0,[],""],["frenk_t2-n3212",6,"Porque hasta sueño despierto\nque me quieres con pasión,\ndime por qué, vida mía,\nno me das tu corazón.",105,2,-1,104,"Mal de amores",0,4,"o",31,0,-1,0,92,92,"3212","",0,"","","",1,0,0,[],""],["frenk_t2-n3213",6,"Con tus desdenes me hieres,\nte burlas de mi cariño;\n¡ay, mujer, qué ingrata eres!\nEngáñame como a un niño,\npero dime que me quieres.",106,2,4,104,"Las canastas; La leva",7,5,"ee",55,0,-1,0,92,92,"3213","",0,"","","",1,0,0,[],""],["frenk_t2-n3215",6,"Marieta, no seas coqueta,\nno desprecies mi pasión;\natiende, que hoy no se vende\na peso de oro el corazón.",105,2,-1,104,"Marieta",0,4,"o",31,0,-1,0,92,92,"3215","",0,"","","",2,0,0,[],""],["frenk_t2-n3216",6,"Vamos a tomar café,\nchinita, no seas ingrata,\nque lo tomarás con leche\ny cucharita de plata.",105,2,-1,104,"El café",0,4,"aa",74,0,-1,0,92,92,"3216","",0,"","","",1,0,0,[],""],["frenk_t2-n3217",6,"No tengo el gusto cumplido\nporque no tengo tu amor;\nme tienes en el olvido,\ny eso no tiene perdón.",105,2,-1,104,"Adorado tormento",0,4,"o",-1,0,-1,0,92,92,"3217","",0,"","","",1,0,0,[],""],["frenk_t2-n3218",6,"Mujer, celestial mujer,\nperdona mi atrevimiento;\nvivo en el conocimiento\nque tú no me has de querer;\nsufriré, ¿qué voy a hacer?,\npos soy un decepcionado;\nsé que no soy de tu agrado,\ny me tratas con desvío;\neste atrevimiento mío\nque no te sirva de enfado.",106,2,4,104,"El fandanguito",18,10,"ao",14,0,-1,0,92,92,"3218","",0,"","","",1,0,0,[],""],["frenk_t2-n3219",6,"Labra el agua sin ser dura\na un mármol endurecido;\n¡ay, que yo no haya podido\nablandar a tu hermosura!",106,2,4,104,"Estrofa suelta",11,4,"ua",17,0,-1,0,93,93,"3219","",0,"","","",2,0,0,[],""],["frenk_t2-n3221a",6,"No seas inconstante;\nsi la piedra es dura,\ntú eres un diamante;\nprueba la pimienta,\nquédate al picante.",106,2,4,104,"El coco",7,5,"ae",47,0,-1,0,93,93,"3221a","",0,"","","",3,0,0,[],""],["frenk_t2-n3222",6,"No seas inconstante\ncon el que te adora;\nrosa de Castilla,\nflor de amapola,\nsabe que por ti\nmi corazón llora.",106,2,4,104,"El coco",9,6,"oa",-1,0,-1,0,93,93,"3222","",0,"","","",3,0,0,[],""],["frenk_t2-n3223",6,"No seas inconstante\ncon el que te adora;\nrosa de Castilla,\nflor de azucena,\nsabe que por ti\nmi corazón pena.",106,2,4,104,"El coco",9,6,"ea",59,0,-1,0,93,93,"3223","",0,"","","",3,0,0,[],""],["frenk_t2-n3224",6,"Corté un limoncito tierno,\ny siempre considerando:\ncorazón he visto ingrato,\npero como el tuyo, ¡cuándo!",105,2,-1,104,"Estrofa suelta",0,4,"ao",-1,0,-1,0,93,93,"3224","",0,"","","",1,0,0,[],""],["frenk_t2-n3226",6,"Colás, Colás,\nColás y Nicolás,\nlo mucho que te quiero,\ny el mal pago que me das.",106,2,4,104,"El Colás",3,4,"a",51,0,-1,0,94,94,"3226","",0,"","","",3,0,0,[],""],["frenk_t2-n3227",6,"¡Ay, caray, Paula,\nqué buena estás!\nTanto como te quiero,\ny el mal pago que me das.",105,2,-1,104,"Paula",3,4,"a",51,0,-1,0,94,94,"3227","",0,"","","",1,0,0,[],""],["frenk_t2-n3228",6,"¡Qué de doses, qué de treses,\nqué de malillas y de ases!\nChinita, ¡qué mal me pagas!\nPero tú sabes lo que haces.",114,2,17,104,"El cuatro",0,4,"ae",268,0,-1,0,94,94,"3228","",0,"","","",1,0,0,[],""],["frenk_t2-n3229",6,"Vasito de agua de coco,\nla boca me has endulzado;\n¡malhaya tu amor tan poco\ny el mío tan aquerenciado!",115,2,3,104,"Vasito de agua de coco; Estrofa suelta",3,4,"ao",14,0,-1,0,94,94,"3229","",0,"","","",1,0,0,[],""],["frenk_t2-n3230",6,"Allá va mi corazón\nsobre una viga nadando.\n¿Qué dice ese amor engrido\ncon el que me estás pagando?",114,2,17,104,"Las olas de la laguna",0,4,"ao",33,0,-1,0,95,95,"3230","",0,"","","",4,0,0,[],""],["frenk_t2-n3231",6,"Desde mi casa a la tuya\nno hay más que un paso;\ndesde la tuya a la mía,\n¡ay, qué camino tan largo!",122,2,13,104,"Estrofa suelta",3,4,"ao",-1,0,-1,0,95,95,"3231","",0,"","","",3,0,0,[],""],["frenk_t2-n3232",6,"Una semana sin verte\nun año se me hace a mí;\nmi corazón se desprende\npara llegar hasta ti;\nen cambio, el tuyo\nno se acuerda de mí.",107,2,11,104,"Estrofa suelta",9,6,"i",23,0,-1,0,95,95,"3232","",0,"","","",1,0,0,[],""],["frenk_t2-n3233a",6,"Estoy loco por tu amor,\npero mi amor no comprendes;\nmientras más te quiero yo,\nmucho menos me comprendes.",105,2,-1,104,"Mal de amores",0,4,"ee",-1,0,-1,0,95,95,"3233a","",0,"","","",3,0,0,[],""],["frenk_t2-n3234",6,"Anda, malagradecida,\nque aunque no me puedas ver,\nyo fui tu primer amor\ny el que te enseñó a querer.",105,2,-1,104,"Por lo alto doy cincuenta",0,4,"e",20,0,-1,0,95,95,"3234","",0,"","","",1,0,0,[],""],["frenk_t2-n3235",6,"Alza los ojos, ingrata,\nquizás me conocerás;\npide licencia a tu dueño\ny después los bajarás.",106,2,4,104,"Estrofa suelta",0,4,"a",51,0,-1,0,95,95,"3235","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n3236",6,"Cuando te empecé a tratar\nyo me encontraba orgulloso;\nen un teatro amoroso\nempezaba a delirar:\npensaba contigo estar\nen un edén verdadero,\nmas tu amor no era sincero:\nmuy pronto me lo mostraste\ny por pobre me olvidaste,\nporque no tengo otro pero.",106,2,4,104,"Estrofa suelta",18,10,"eo",38,0,-1,0,95,95,"3236","",0,"","","",1,0,0,[],""],["frenk_t2-n3238",6,"¿Qué culpa tiene el huizache\nde haber nacido en el campo?\n¿Qué culpa tiene mi amor\nde haberte querido tanto?",107,2,11,104,"El huizache; Pajarillo, pajarillo; Estrofa suelta",0,4,"ao",-1,0,-1,0,96,96,"3238","",0,"","","",2,0,0,[],""],["frenk_t2-n3239",6,"Que mi amor te declaré,\nno me lo podrás negar,\npero yo no sé por qué\nla pobreza es un lunar\nque desde lejos se ve.",113,2,2,104,"Estrofa suelta",7,5,"e",77,0,-1,0,96,96,"3239","",0,"","","",1,0,0,[],""],["frenk_t2-n3240",6,"Al pie de un encino roble\nme puse a sestear un rato;\nsi me desprecias por pobre,\nque eso no es de gente noble.",113,2,2,104,"Estrofa suelta",5,4,"oe",-1,0,-1,0,96,96,"3240","",0,"","","",3,0,0,[],""],["frenk_t2-n3241",6,"Al pie de un árbol lloré\nla desgracia que hoy me pasa;\ndime si no me has de amar,\no no quieren en tu casa;\nno porque me ves así,\nvestido de mala traza,\n¡ay!, no por eso me vayas a abandonar.",105,2,-1,104,"Al píe de un árbol",4,7,"a",21,0,-1,0,96,96,"3241","",0,"","","",2,0,0,[],""],["frenk_t2-n3242",6,"El que no tiene dinero,\ncomo yo, es un delincuente:\nsiempre le encuentra la gente\ntoda la clase de pero;\n.........................\n.........................\nYo, haciendo mención de eso,\nhe de seguir y porfiar,\nhasta que te pueda dar\nun pellizco en el pescuezo.",106,2,4,104,"Estrofa suelta",18,10,"eo",345,0,-1,0,96,96,"3242","",0,"","","",1,0,0,[],""],["frenk_t2-n3243",6,"Tu amor, bella Dulcinea,\npor pobre no merecí;\ncuando sufre el que desea,\ny a la que yo pretendí\notro es el que la chiquea:\nno necesita de mí.",106,2,4,104,"El siquisirí",9,6,"i",23,0,-1,0,96,96,"3243","",0,"","","",1,0,0,[],""],["frenk_t2-n3244",6,"Por pobre me despreciaste,\nno hay cariño para mí;\nbusca un amor a tu gusto,\nno hagas recuerdos de mí.",105,2,-1,104,"Alza los ojos’*; Estrofa suelta",0,4,"i",-1,0,-1,0,97,97,"3244","",0,"","","",2,0,0,[],""],["frenk_t2-n3245",6,"......................\nsegún he podido ver,\npues donde quiera, mujer,\nhay un hombre como yo;\nmientras que tú.............\nhallar un adinerado,\nque tenga mucho ganado\ny que nade en la riqueza;\ntú buscas honor y grandeza,\nque yo soy un arrancado.",106,2,4,104,"Estrofa suelta",18,10,"ao",14,0,-1,0,97,97,"3245","",0,"","","",0,0,0,[],""],["frenk_t2-n3246",6,"Tu familia me quiere,\nasegún me lo ha demostrado,\npues tal vez se calculó\nque yo tenía dinero;\ny como pétalo abría\ntu boca........................\nme llamaron embustero,\n........................... y coyón,\ny sin tener un tostón,\ntú sueñas con el dinero.",106,2,4,104,"Estrofa suelta",18,10,"eo",38,0,-1,0,97,97,"3246","",0,"","","",1,0,0,[],""],["frenk_t2-n3247",6,"En la torre de Tampico\ncantaba un águila imperial,\ny le respondió el perico,\ncon una voz muy especial:\n“¿Qué te podrá dar un rico\nque yo no te pueda dar?”",108,2,8,104,"El cascabel; El tinajón",9,6,"a",-1,0,-1,0,97,97,"3247","",0,"","","",1,0,0,[],""],["frenk_t2-n3248",6,"¡Cuántas veces me engañaste\ncon tu negra falsedad!\nY me dijo una señora:\n“La pobreza es un lunar,\nque al mejor hombre desdora\ncuando no tiene que dar.”",105,2,-1,104,"Cielito lindo",9,6,"a",21,0,-1,0,97,97,"3248","",0,"","","",2,0,0,[],""],["frenk_t2-n3249",6,"A tu amor solicité,\nenamorado y rendido;\npensaba formar un nido\nde amor, dicha y fe;\na tu cariño me................\npara ser más desdichado;\nme creías adinerado\ny por eso me quisistes,\ny como plata no vistes,\npor pobre me has olvidado.",106,2,4,104,"Estrofa suelta",18,10,"ao",14,0,-1,0,97,97,"3249","",0,"","","",1,0,0,[],""],["frenk_t2-n3250",6,"En medio de dos iglesias\ntengo toda la alegría.\nSi mis palabras son necias,\nmi corazón te porfía;\nsi por pobre me desprecias,\nanda pronto, vida mía.",113,2,2,104,"El gusto",9,6,"ia",0,0,-1,0,97,97,"3250","",0,"","","",1,0,0,[],""],["frenk_t2-n3251",6,"Por pobre me despreciaste,\npara ti no valgo nada;\nte deslumbró más el oro\nque el amor que yo te daba;\npero el recuerdo que llevas,\neso no lo borra nada.",105,2,-1,104,"Carta abierta",9,6,"aa",-1,0,-1,0,98,98,"3251","",0,"","","",2,0,0,[],""],["frenk_t2-n3252",6,"El amor y el interés\nse fueron al campo un día:\npudo más el interés\nque el amor que te tenía.",106,2,4,104,"El palomo; Estrofa suelta",1,4,"ia",0,0,-1,0,98,98,"3252","",0,"","","",9,0,0,[],""],["frenk_t2-n3253",6,"Si me desprecias por pobre,\nsi por pobre no merezco\nlo que otra por rica alcanza,\nadvierte, trigueño mío:\npobre, pero de importancia.",128,2,30,104,"Me han dicho que tienes otra",7,5,"aa",-1,0,-1,0,98,98,"3253","",0,"","","",1,0,0,[],""],["frenk_t2-n3254",6,"Serenísima corona,\n¿por qué gastas fantasía,\nsi sabes que soy honrado\ny que no me merecías?",105,2,-1,104,"Glosada en décimas",0,4,"ia",-1,0,-1,0,98,98,"3254","",0,"","","",1,0,0,[],""],["frenk_t2-n3256",6,"Dices que no me quieres (cielito lindo),\nporque no iguala\ntu sangre con la mía (prenda querida):\npor no mancharla.",106,2,4,104,"Cielito lindo",3,4,"aa",-1,0,-1,0,98,98,"3256","",0,"","","",1,0,0,[],""],["frenk_t2-n3257",6,"Dime, niña, ¿qué pretendes?,\nque ningún galán te agrada;\nsi pretendes algún rey,\ncuatro tiene la baraja.",117,2,5,104,"Estrofa suelta",0,4,"aa",-1,0,-1,0,98,98,"3257","",0,"","","",1,0,0,[],""],["frenk_t2-n3258",6,"No sé qué pasa contigo,\nque me llenas de tristeza;\ntú tienes como castigo\nmil delirios de grandeza.",105,2,-1,104,"La divina garza",1,4,"ea",108,0,-1,0,98,98,"3258","",0,"","","",1,0,0,[],""],["frenk_t2-n3259",6,"Dicen que tienes orgullo\ny dinero que gastar;\ngástalo poco a poquito:\nno se te vaya a acabar.",105,2,-1,104,"Amorcito consentido",0,4,"a",21,0,-1,0,99,99,"3259","",0,"","","",1,0,0,[],""],["frenk_t2-n3260",6,"Paloma, estás engolfada\nporque tienes qué comer;\nruega a Dios no se te acabe,\nque yo también tuve ayer.",106,2,4,104,"El palomo",0,4,"e",20,0,-1,0,99,99,"3260","",0,"","","",1,0,0,[],""],["frenk_t2-n3261",6,"Mira, no seas presumida,\nporque no te queda bien:\nporque tú fuiste nacida\nentre flores de Belén,\ny también fuiste vendida,\ny no sabes para quién.",112,2,6,104,"La presumida",9,6,"e",242,0,-1,0,99,99,"3261","",0,"","","",1,0,0,[],""],["frenk_t2-n3262",6,"Aunque mi amor se derrumba,\nno olvides a quien te canta,\nporque si el hambre me tumba,\nel orgullo me levanta.",105,2,-1,104,"La divina garza",1,4,"aa",148,0,-1,0,99,99,"3262","",0,"","","",1,0,0,[],""],["frenk_t2-n3263a",6,"Si no me tienes amor,\n¿para qué es tanta grandeza?\n¿No ves que al mejor licor\nse le va la fortaleza?",112,2,6,104,"Estrofa suelta",1,4,"ea",108,0,-1,0,99,99,"3263a","",0,"","","",1,0,0,[],""],["frenk_t2-n3263b",6,"Yo vi repuntar el sol\nen un vaso de cerveza.\nSi no me tienes amor,\n¿para qué es tanta grandeza?\nMira que al mejor licor\nse le va la fortaleza.",112,2,6,104,"La leva; La huazanga",9,6,"ea",108,0,-1,0,99,99,"3263b","",0,"","","",1,0,0,[],""],["frenk_t2-n3263c",6,"Blanca flor, ¿quién te cortó,\nbello clavel del desprecio?\nNo porque tengas otro amor\nte hagas de tanta grandeza:\nmira que al mejor licor\nse le va la fortaleza.",108,2,8,104,"Estrofa suelta, El pájaro carpintero",9,6,"ea",108,0,-1,0,99,99,"3263c","",0,"","","",1,0,0,[],""],["frenk_t2-n3265",6,"Si quieres, si puedes,\nsi no, tú me dirás;\ncon esos ojos negros\nme miras y te vas.",106,2,4,103,"El Colás",0,4,"a",51,0,-1,0,100,100,"3265","",0,"","","",2,0,0,[],""],["frenk_t2-n3266",6,"Sobre la mesa te puse\nun limón corriendo.\nSi te veo, dices que es chanza\ny de mí te vas sonriendo;\nes vanidad que te causa\nver a mi amor padeciendo.",108,2,8,103,"Estrofa suelta",9,6,"eo",52,0,-1,0,100,100,"3266","",0,"","","",3,0,0,[],""],["frenk_t2-n3267",6,"A orillas del Papaloapan\nme estaba bañando ayer;\npasaste por las orillas\ny no me quisiste ver.",105,2,-1,103,"La Zandunga; La Llorona",0,4,"e",20,0,-1,0,100,100,"3267","",0,"","","",2,0,0,[],""],["frenk_t2-n3268",6,"No me gustan los tapados,\nporque no me sé esconder;\ntus ojos no me han mirado,\nporque no me quieren ver.",105,2,-1,103,"Gallo tapado",0,4,"e",20,0,-1,0,100,100,"3268","",0,"","","",1,0,0,[],""],["frenk_t2-n3269",6,"María sé que te llaman,\ny no te han variado el nombre;\ntoda la noche me paso:\n“María”, y no me respondes.",117,2,5,103,"Estrofa suelta",0,4,"oe",-1,0,-1,0,100,100,"3269","",0,"","","",1,0,0,[],""],["frenk_t2-n3270",6,"Chaparrita, vengo a verte\nhasta tu jacal desierto,\ny tú no eres pa mirarme,\ncomo te miro y te siento.",105,2,-1,103,"Estrofa suelta",0,4,"eo",-1,0,-1,0,100,100,"3270","",0,"","","",1,0,0,[],""],["frenk_t2-n3271",6,"Desde aquí te estoy mirando,\ny el sol ya empieza a salir,\npero no eres pa decirme:\n“Chiquito, vente a dormir.”",115,2,3,103,"Margarita",0,4,"i",157,0,-1,0,100,100,"3271","",0,"","","",20,0,0,[],""],["frenk_t2-n3272",6,"Desde aquí te estoy mirando,\ncara a cara, frente a frente;\npero no eres pa decirme:\n“Chiquitito, vente, vente.”",115,2,3,103,"Margarita; Ojitos color de olivo",0,4,"ee",15,0,-1,0,101,101,"3272","",0,"","","",20,0,0,[],""],["frenk_t2-n3273",6,"En la puerta de tu casa\nplaticaba y me reía,\ny no fuiste para decirme:\n“Pásate, José María.”",129,2,9,103,"Estrofa suelta",0,4,"ia",0,0,-1,0,101,101,"3273","",0,"","","",13,0,0,[],""],["frenk_t2-n3274",6,"Andando me tropecé\ny me caí entre las flores;\nesperaba me dijeras:\n“No llores, mi bien, no llores.”",108,2,8,103,"La garbosa’",0,4,"oe",5,0,-1,0,101,101,"3274","",0,"","","",1,0,0,[],""],["frenk_t2-n3275",6,"Ya me estoy cayendo de hambre,\ny no vienes a mi lado\npara decir [te], morena,\nque ya me tienes alelado.",105,2,-1,103,"El chúmbale",0,4,"ao",14,0,-1,0,101,101,"3275","",0,"","","",1,0,0,[],""],["frenk_t2-n3276",6,"Me ofreciste acompañarme\ndesde la iglesia a mi choza,\npero como no llegaste,\ntuve que venirme sola.",105,2,-1,103,"La Zandunga",0,4,"oa",-1,0,-1,0,101,101,"3276","",0,"","","",1,0,0,[],""],["frenk_t2-n3277",6,"Eres como mi yegua:\nrejega y mal entendida;\npor más que te hablo de amores,\nte haces la desentendida.",105,2,-1,103,"La vieja presumida",0,4,"ia",37,0,-1,0,101,101,"3277","",0,"","","",1,0,0,[],""],["frenk_t2-n3278",6,"Me gusta mucho el rebozo\ncuando lo juegan tus brazos;\npor más que me hago el celoso,\ntú no me tiras ni un lazo.",105,2,-1,103,"Gallo tapado",0,4,"ao",-1,0,-1,0,101,101,"3278","",0,"","","",1,0,0,[],""],["frenk_t2-n3279",6,"¿De qué me sirve quererte,\nsi es en vano mi porfía?\nPues cuando trato de verte\nsiempre sales con la tía:\n¡mira qué mala suerte,\npedazo del alma mía!",105,2,-1,103,"El deseoso",9,6,"ia",0,0,-1,0,101,101,"3279","",0,"","","",1,0,0,[],""],["frenk_t2-n3280",6,"Antes que amaneciera (cielito lindo)\nyo te pedía\nun último beso (cielito lindo)\npara la mía.\n¡Qué ingrato fuiste!,\nporque ya amaneció (cielito lindo),\ny no me lo diste.",106,2,4,103,"Cielito lindo",4,7,"ie",153,0,-1,0,101,101,"3280","",0,"","","",1,0,0,[],""],["frenk_t2-n3282",6,"Un día te escribí una carta,\nel viento se la llevó;\nun bien con un mal se paga,\ncomo a mí me sucedió.",105,2,-1,103,"La carta",0,4,"o",2,0,-1,0,102,102,"3282","",0,"","","",2,0,0,[],""],["frenk_t2-n3283",6,"Bajo la sombra de aquella noche\nmis desengaños voy a ocultar,\npara que nadien sepa que te amo\ncuando de amores me oigan cantar.",114,2,17,103,"Indita mía",3,4,"a",21,0,-1,0,102,102,"3283","",0,"","","",1,0,0,[],""],["frenk_t2-n3284",6,"¡Si supieras cuánto te amo\ny sin ser correspondido!\nTe diré cómo me llamo\ny que en Chilpancingo vivo.",105,2,-1,103,"Estrofa suelta",0,4,"io",-1,0,-1,0,102,102,"3284","",0,"","","",1,0,0,[],""],["frenk_t2-n3285",6,"—Si te vieras en el mar,\n¿qué quisieras ver, Cupido?\nque no puedo andar contigo;\nsí se apresta este lugar,\nnada más que no has querido.",106,2,4,103,"Corté una calabacita",7,5,"io",-1,0,-1,0,102,102,"3285","",0,"","","",1,0,0,[],""],["frenk_t2-n3286",6,"Bastante te he pretendido\ncon la intención de quererte,\nno más que tú no has querido\nel sí de tu boca darme,\ny por eso, adolorido,\nrazón tengo de quejarme.",106,2,4,103,"Zapateado",9,6,"ae",35,0,-1,0,102,102,"3286","",0,"","","",1,0,0,[],""],["frenk_t2-n3287",6,"Tú has a mi amor despreciado:\nyo no lo creía de ti;\npero estoy desengañado\nque no me quieres a mí,\npor consejos que te han dado.",105,2,-1,103,"Estrofa suelta",7,5,"ao",14,0,-1,0,102,102,"3287","",0,"","","",1,0,0,[],""],["frenk_t2-n3288",6,"Corté la flor del romero\nporque la encontré florida.\nCumplo con ser verdadero,\ny me hace sufrir la vida;\ny como ves que te quiero,\ntenías que ser grande y fiero.",105,2,-1,103,"El carpintero",9,6,"eo",38,0,-1,0,102,102,"3288","",0,"","","",1,0,0,[],""],["frenk_t2-n3289",6,"Eres como la hoja verde,\nhija de un árbol frondoso,\nque por más que lo sacuden,\ntu hermosura no la gozo.",105,2,-1,103,"Hojita verde",0,4,"oo",156,0,-1,0,102,102,"3289","",0,"","","",4,0,0,[],""],["frenk_t2-n3290",6,"Eres como la hoja verde\nque aguanta los vendavales:\nvientos van y vientos vienen,\ny en las ramas te detienes.",105,2,-1,103,"Hojita verde",5,4,"ee",-1,0,-1,0,103,103,"3290","",0,"","","",4,0,0,[],""],["frenk_t2-n3291",6,"Dices que no me quieres\nporque no tengo\nla nariz afilada\ny los ojos negros.",106,2,4,103,"La bamba; Cielito lindo; El pájaro cú; Estrofa suelta",6,4,"eo",-1,0,-1,0,103,103,"3291","",0,"","","",15,0,0,[],""],["frenk_t2-n3292",6,"En celda gris, ¡ay, Llorona!,\ntriste cantaba un jilguero:\n“Estas rejas son de plata (Llorona),\ny acero las de tu pecho.”",108,2,8,103,"La Llorona",3,4,"eo",-1,0,-1,0,103,103,"3292","",0,"","","",1,0,0,[],""],["frenk_t2-n3293",6,"Tienes corazón de fierro,\ny eso es lo que me aniquila,\nque estoy queriendo un entierro,\ny tu conciencia, tranquila.",118,2,27,103,"En las cumbres de una vid",1,4,"ia",427,0,-1,0,103,103,"3293","",0,"","","",1,0,0,[],""],["frenk_t2-n3294",6,"Tú y yo nos parecemos\nmucho a la nieve:\ntú en lo blanca y lo fría,\nyo en deshacerme.",105,2,-1,103,"Estrofa suelta",6,4,"ee",-1,0,-1,0,103,103,"3294","",0,"rm_t3, palau_cantares, suspiros_amor","","",4,0,0,[],""],["frenk_t2-n3295",6,"Si los cielos escucharan\nque padezco sin delito (¡ay de mí, Lloro-\nai punto que te aprisionaran: [na!),\nque hasta los animalitos (¡ay de mí, Lloro-\nai verme llorar, lloraran. [na!)",106,2,4,103,"La Llorona",7,5,"a",-1,0,-1,0,103,103,"3295","",0,"","","",1,0,0,[],""],["frenk_t2-n3296",6,"Yo no sé por qué lo harás\nde martirizarme tanto,\npero bien comprenderás\nque hasta las aves del campo\nlloran cuando tú te vas.",111,2,1,103,"Estrofa suelta",7,5,"a",51,0,-1,0,103,103,"3296","",0,"","","",1,0,0,[],""],["frenk_t2-n3297",6,"De noche se aleja el sol\npero se acerca la luna;\nen cambio me dejas tú\nsin esperanza ninguna.",105,2,-1,103,"La nube",0,4,"ua",56,0,-1,0,103,103,"3297","",0,"","","",1,0,0,[],""],["frenk_t2-n3298",6,"¡Ay, Dios!, pero qué tristeza\nsufro en el mundo por ti,\nde ver que tú me desprecias\ny no te dueles de mí.",106,2,4,103,"Estrofa suelta",0,4,"i",23,0,-1,0,104,104,"3298","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n3299",6,"Morenita, sin tu amor,\ny no tengo quien me consuele;\n¡que no tengas compasión!\nNo te preocupes, corazón,\ny por tu amor todito muere.",113,2,2,103,"El fandanguito",7,5,"ee",-1,0,-1,0,104,104,"3299","",0,"","","",1,0,0,[],""],["frenk_t2-n3300",6,"Le cantaré a las estrellas\nlo que iba a cantarte a ti;\nno quisiste oír mi queja:\n¡ay, pobrecito de mí!;\nBendito es aquel que ama\ny no te conoce a ti.",105,2,-1,103,"Pena huasteca",9,6,"i",23,0,-1,0,104,104,"3300","",0,"","","",1,0,0,[],""],["frenk_t2-n3301",6,"Traspasada tengo el alma\npor tus negros procederes,\nmas tú disfrutas de calma:\n¡así pagan las mujeres!",105,2,-1,103,"Estrofa suelta",1,4,"ee",55,0,-1,0,104,104,"3301","",0,"","","",1,0,0,[],""],["frenk_t2-n3302",6,"Qué poco le importa al sol\nque el indio no tenga techo;\nqué poco te importa a ti\ntodo el mal que me has hecho.",112,2,6,103,"Estrofa suelta",0,4,"eo",60,0,-1,0,104,104,"3302","",0,"","","",1,0,0,[],""],["frenk_t2-n3303",6,"Las rosas en primavera\ndejan perfumado el viento;\nnuestro amor, cuando se muera,\nmoriré de sentimiento,\ny tú seguirás gozando,\na pesar de mi tormento.",105,2,-1,103,"Canta, corazón, canta",9,6,"eo",94,0,-1,0,104,104,"3303","",0,"","","",1,0,0,[],""],["frenk_t2-n3304",6,"Soy como el árbol caído,\ncomo paloma sin alas;\nahora que me ves vencido,\ncon pisotearme ¿qué ganas?",105,2,-1,103,"Árbol caído",0,4,"aa",-1,0,-1,0,104,104,"3304","",0,"","","",2,0,0,[],""],["frenk_t2-n3305",6,"Te mandé a solicitar\ncon la intención de quererte;\nme mandaste avisar\nque me deseabas la muerte;\ntriste me senté a llorar\nal ver mi tirana suerte.",106,2,4,103,"El siquisirí; La morena",9,6,"ee",134,0,-1,0,104,104,"3305","",0,"","","",1,0,0,[],""],["frenk_t2-n3306",6,"Yo quisiera que en la vida\nme amaras con dulzura,\npero sé que quisieras\nverme cerca de la sepultura.",107,2,11,103,"La Sanmarqueña",3,4,"ua",17,0,-1,0,104,104,"3306","",0,"","","",1,0,0,[],""],["frenk_t2-n3307",6,"El Creador nos ha mandado\na vivir juntos los dos,\npero tú te has apartado\nde las órdenes de Dios.",107,2,11,103,"Estrofa suelta, El coscolino",1,4,"o",87,0,-1,0,105,105,"3307","",0,"","","",1,0,0,[],""],["frenk_t2-n3308",6,"Cuando te vide venir\ncon tu rebozo terciado,\nmi corazón me avisaba\nque me ibas hacer [a] un lado.",127,2,18,103,"Ojitos negros y chinos",0,4,"ao",14,0,-1,0,105,105,"3308","",0,"","","",1,0,0,[],""],["frenk_t2-n3309",6,"Ya se quebró aquí una rama\nal trueno de un sentimiento;\nZandunga, tú eres la rama,\nyo soy el tronco y lo siento.",108,2,8,103,"La Zandunga",1,4,"eo",94,0,-1,0,105,105,"3309","",0,"","","",1,0,0,[],""],["frenk_t2-n3310",6,"Pajarillo, pajarillo,\npajarillo mañanero,\nme despides de tu jaula,\ncuando fui tu amor primero.",105,2,-1,103,"Pajarillo, pajarillo",0,4,"eo",38,0,-1,0,105,105,"3310","",0,"","","",9,0,0,[],""],["frenk_t2-n3311",6,"Blanca rosa de Castilla,\ncortada al amanecer,\napenas te estoy queriendo\ny ya me vas a aborrecer.",105,2,-1,103,"Amorcito Consentido",0,4,"e",20,0,-1,0,105,105,"3311","",0,"","","",5,0,0,[],""],["frenk_t2-n3312",6,"—¿Qué es ’e la dicha? —Acabóse.\n—¿Qué es ’e el gusto? —Ya se fue\n—¿Dónde está el amor? —No sé:\nera de vidrio y quebróse.",105,2,-1,103,"Estrofa suelta",11,4,"oe",553,0,-1,0,105,105,"3312","",0,"","","",1,0,0,[],""],["frenk_t2-n3313",6,"Ya este peine se acabó,\nya no le queda ni un diente;\ncon él te peinabas, chata,\nlos chinitos de tu frente.",105,2,-1,103,"El peine",0,4,"ee",15,0,-1,0,105,105,"3313","",0,"","","",1,0,0,[],""],["frenk_t2-n3314",6,"Sé que te vas y que me dejas,\nsé que te ausentas de mí,\ndejando un alma herida\ny un corazón a sufrir.",105,2,-1,103,"Alza los ojos",0,4,"i",-1,0,-1,0,105,105,"3314","",0,"","","",1,0,0,[],""],["frenk_t2-n3315",6,"Si tu amor me has de quitar,\naunque con modo exquisito,\ny sin poderte rogar,\nescogeré “El fandanguito”\npara poderte llorar.",111,2,1,103,"El fandanguito",7,5,"a",21,0,-1,0,105,105,"3315","",0,"","","",1,0,0,[],""],["frenk_t2-n3316",6,"¡Ay, qué miradas tan serias\ncuándo ya no hay interés!\nLa suerte será la mala,\no el mundo andará al revés.",105,2,-1,103,"Mal correspondido",0,4,"e",218,0,-1,0,106,106,"3316","",0,"","","",1,0,0,[],""],["frenk_t2-n3317",6,"Cada vez que pienso en ti\nse me mueve esa compasión\nde ver que tu querido fui:\nme atormenta esa pasión.\nDime ¿con qué corazón\na tal cosa te atreviste?\n¿No viste, no conociste,\nque esto se había de saber?\nAhora sí me quieres ver\ncon esos ojitos tristes.",105,2,-1,103,"Estrofa suelta",18,10,"ie",-1,0,-1,0,106,106,"3317","",0,"","","",2,0,0,[],""],["frenk_t2-n3318",6,"Oye, negra, ven acá,\nescucha, tirana cruel,\n¿por qué vendiste mi amor?\n¿Cuánto te dieron por él?\n¿Qué no te causó dolor\nhaberte quedado sin él?",108,2,8,103,"Estrofa suelta",9,6,"e",-1,0,-1,0,106,106,"3318","",0,"","","",1,0,0,[],""],["frenk_t2-n3319",6,"Yo jamás creía encontrarme\nen la vida sin abrigo;\nhoy, si quieres encauzarme,\nme dirás, pues, el motivo\nque tratas de separarme.",105,2,-1,103,"La leva",7,5,"ae",35,0,-1,0,106,106,"3319","",0,"","","",1,0,0,[],""],["frenk_t2-n3321",6,"Dicen que ya no me quieres,\nque me has echado al olvido;\ndicen que me has traicionado\ny que tu amor he perdido.",105,2,-1,103,"Árbol caído",0,4,"io",101,0,-1,0,106,106,"3321","",0,"","","",9,0,0,[],""],["frenk_t2-n3322",6,"Me dices que no me quieres,\nque ya tienes nuevo amor,\nque yo soy muy poca cosa,\nno me quieres de pilón.",105,2,-1,103,"Espina traidora",0,4,"o",-1,0,-1,0,106,106,"3322","",0,"","","",6,0,0,[],""],["frenk_t2-n3323",6,"Dicen que ya no me quieres,\ncomo ya antes me querías,\ny por esta enfermedad\na más de esto está la agonía.",106,2,4,103,"Chumba que chumba",0,4,"ia",-1,0,-1,0,106,106,"3323","",0,"","","",9,0,0,[],""],["frenk_t2-n3325",6,"Dices que no me quieres:\nya me has querido (zamba que le da);\nya remedio no tiene\nlo sucedido (zamba que le da).",109,2,7,103,"La zamba; Adiós, Acapulco; La bamba; Cielito lindo; El pájaro cú",3,4,"a",101,0,-1,0,107,107,"3325","",0,"","","",15,0,0,[],""],["frenk_t2-n3326",6,"Ya me lo habían advertido\nque me ibas a abandonar,\npor andar de entrometido\ncon prendas que pagan mal.",105,2,-1,103,"Mal correspondido",0,4,"a",-1,0,-1,0,107,107,"3326","",0,"","","",1,0,0,[],""],["frenk_t2-n3327",6,"Vuela, vuela, vuela,\nvuela, vuela sin abrigo\nonde más cuenta te tengan,\nsi no quieres ’tar conmigo.",106,2,4,103,"La guacamaya",0,4,"io",106,0,-1,0,107,107,"3327","",0,"","","",17,0,0,[],""],["frenk_t2-n3328",6,"Cuando estábamos de novios\nera una vida llena de encanto;\nahora que estamos casados\nes un infierno, que no lo aguanto.",105,2,-1,103,"Antes y después",3,4,"ao",-1,0,-1,0,107,107,"3328","",0,"","","",6,0,0,[],""],["frenk_t2-n3329",6,"Cuando estábamos de novios\nun pañuelito mercaste,\nahora que estamos casados\ndesgarramos el pañuelo.",129,2,9,103,"La indita",5,4,"eo",-1,0,-1,0,107,107,"3329","",0,"","","",6,0,0,[],""],["frenk_t2-n3330",6,"¡Qué puntada te alcanzaste,\npérfida mujer!\nNunca te creí capaz\ncambiar de parecer.",105,2,-1,103,"La puntada",0,4,"e",20,0,-1,0,107,107,"3330","",0,"","","",2,0,0,[],""],["frenk_t2-n3331",6,"¡Qué puntada te alcanzaste,\npérfida mujer!,\nal dejarme abandonado\ntodo mi querer.",105,2,-1,103,"La puntada",0,4,"e",20,0,-1,0,107,107,"3331","",0,"","","",2,0,0,[],""],["frenk_t2-n3332",6,"¡Y ajá, y ajá, y ajá,\nqué risa me da!\nSi quieren, pueden ver\nque tú no me quieres ya.",106,2,4,103,"Cielito lindo",3,4,"a",9,0,-1,0,107,107,"3332","",0,"","","",1,0,0,[],""],["frenk_t2-n3333",6,"Sigue, Mari, la senda que quieras,\nhoy que tienes el mundo a tus pies;\ny más tarde, si no hay quien te quiera,\náhi recuerdas de mí alguna vez.",115,2,3,103,"Qué te falta, mujer",3,4,"e",150,0,-1,0,107,107,"3333","",0,"","","",1,0,0,[],""],["frenk_t2-n3334",6,"¡Ay de mí, Llorona (Llorona)!,\nLlorona del negro potro,\naquí me tienes sufriendo (Llorona)\ndesde que duermes con otro.",107,2,11,103,"La Llorona",3,4,"oo",275,0,-1,0,108,108,"3334","",0,"","","",4,0,0,[],""],["frenk_t2-n3335a",6,"¿De qué me sirve tenerte\ntu cama llena de flores,\nsi conmigo son los celos\ny con otros los amores?",105,2,-1,103,"El pájaro carpintero; Estrofa suelta",0,4,"oe",5,0,-1,0,108,108,"3335a","",0,"","","",1,0,0,[],""],["frenk_t2-n3336",6,"Tanto pasar y pasar,\ntanto pasar por aquí;\nya se acaban mis huaraches,\ny otro gozando de ti.",110,2,10,103,"Tanto pasar y pasar; Chula la mañana; El frijolito; Estrofa suelta",0,4,"i",23,0,-1,0,108,108,"3336","",0,"","","",3,0,0,[],""],["frenk_t2-n3337",6,"Negrita, por ti me vine\ndesde lejos tropezando,\nporque supe que mi amor\ncon otro lo andas cambiando.",108,2,8,103,"Que comienzo, que comienzo; Estrofa suelta",0,4,"ao",33,0,-1,0,108,108,"3337","",0,"","","",1,0,0,[],""],["frenk_t2-n3338",6,"Negrita del alma mía,\ndime quién te lo dijera,\nque yo pusiera el columpio\npara que otro se meciera.",105,2,-1,103,"Las copetonas; Estrofa suelta",0,4,"ea",44,0,-1,0,108,108,"3338","",0,"","","",1,0,0,[],""],["frenk_t2-n3339",6,"Al pie de un verde limón\nle dije a mi amor: “¡Estáte!”\nYo no siento mi colchón,\nlo que siento es mi petate,\nque lo dejé en un rincón,\npa que otro me lo maltrate.",108,2,8,103,"Indita del alma",9,6,"ae",384,0,-1,0,108,108,"3339","",0,"","","",3,0,0,[],""],["frenk_t2-n3340",6,"Me han dicho que tienes otra\nque es más bonita que yo;\nmás bonita sí será,\nconstante como yo, no.",105,2,-1,103,"Me han dicho que tienes otra",0,4,"o",2,0,-1,0,109,109,"3340","",0,"","","",4,0,0,[],""],["frenk_t2-n3341",6,"En Ί ala de mi sombrero\nvide la sombra de un pato.\n¡Ah, qué amor tan lisonjero!,\n¡qué corazón tan ingrato!,\nque desprecias a un jilguero\npor un pájaro mulato.",106,2,4,103,"El Balajú",9,6,"ao",19,0,-1,0,109,109,"3341","",0,"","","",1,0,0,[],""],["frenk_t2-n3342",6,"Eres bonita, no hay duda,\npero tienes tu mal modo:\ndejaste el agua clarita\npor revolearte en el lodo.",108,2,8,103,"María, María",0,4,"oo",261,0,-1,0,109,109,"3342","",0,"","","",1,0,0,[],""],["frenk_t2-n3343a",6,"Yo no siento la cautela,\npero sí me da dolor\nque hayas cambiado canela\npor cáscara sin olor.",108,2,8,103,"Estrofa suelta",1,4,"o",72,0,-1,0,109,109,"3343a","",0,"","","",2,0,0,[],""],["frenk_t2-n3343b",6,"En las alturas del norte\nse me deshojó una flor.\nSi tú tienes sentimiento,\nyo también tengo dolor\nque haigas cambiado camelia\npor cáscara sin olor.",106,2,4,103,"Estrofa suelta",9,6,"o",72,0,-1,0,109,109,"3343b","",0,"","","",1,0,0,[],""],["frenk_t2-n3344",6,"Cupido con su vihuela\npasó el mal del amor;\neso a mí no me desvela,\npero sí me da dolor\nque hayas cambiado con él,\nporque queda sinsabor.",105,2,-1,103,"La leva",9,6,"o",72,0,-1,0,109,109,"3344","",0,"","","",3,0,0,[],""],["frenk_t2-n3345",6,"Al pie de un hermoso roble\nhizo fuego mi fortuna;\ncambiaste oro por cobre,\nel mar por una laguna.",105,2,-1,103,"Me han dicho que tienes otra",0,4,"ua",56,0,-1,0,109,109,"3345","",0,"","","",1,0,0,[],""],["frenk_t2-n3346",6,"Soy Benito entre los buenos,\nsoy de lo mejor que hay;\nsi por otro me haces menos,\nno digas después “¡caray!”.\nEs igualito al terreno,\npero se achagüiscla más.",108,2,8,103,"El siquisirí",9,6,"a",-1,0,-1,0,109,109,"3346","",0,"","","",1,0,0,[],""],["frenk_t2-n3347",6,"Algún día te caerás\nen aquel yerro que hiciste;\ncuando quieras, no podrás\nrecobrar lo que perdiste.",105,2,-1,103,"Estrofa suelta",1,4,"ie",153,0,-1,0,110,110,"3347","",0,"","","",1,0,0,[],""],["frenk_t2-n3348",6,"Cuando te encuentres perdida\npor tu falso proceder,\nirás muy arrepentida,\nqueriendo retroceder;\nes imposible, mi vida,\nque vuelvas a mi poder.",112,2,6,103,"El taconcito",9,6,"e",20,0,-1,0,110,110,"3348","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n3349",6,"Yo me vi dos caballeros\nque estaban jugando albures.\nHora te digo: “te quiero”;\nmi vida, si tú de mí huyes,\ncuando veas que soy sincero,\npos búscame por las nubes.",113,2,2,103,"La pasión",9,6,"ue",-1,0,-1,0,110,110,"3349","",0,"","","",1,0,0,[],""],["frenk_t2-n3350",6,"Para que olvidarme puedas,\nmi amor, tendrás que llorar;\naunque después tú me quieras,\nyo nunca te he de rogar:\nal cabo sola áhi te quedas.",105,2,-1,103,"La madrugada; El ausente",7,5,"ea",-1,0,-1,0,110,110,"3350","",0,"","","",1,0,0,[],""],["frenk_t2-n3352b",6,"¡Y ay, qué triste se ha de ver\ncuando estés sola pensando!\nTe tendrás que convencer:\ntendrás que vivir llorando\nantes de volverte a ver.",106,2,4,103,"Las canastas; El huerfanito",7,5,"e",20,0,-1,0,110,110,"3352b","",0,"","","",1,0,0,[],""],["frenk_t2-n3353",6,"Si sufres, no tengo culpa,\nes que te gusta la libertad;\nsi mi amor no has comprendido,\notro amor igual no encontrarás.",105,2,-1,103,"Te voy a cortar las alas",3,4,"a",-1,0,-1,0,110,110,"3353","",0,"","","",1,0,0,[],""],["frenk_t2-n3354",6,"Traigo mi canasta\nllena de confites;\nte quedaste sola\nporque tú quisites.",114,2,17,103,"Estrofa suelta",0,4,"ie",235,0,-1,0,111,111,"3354","",0,"","","",1,0,0,[],""],["frenk_t2-n3355",6,"¡Ay, laralá, traicionera!\n¡ay, laralá, qué dolor!\nNo encontrarás quien te quiera\nni te dé todo su amor.",108,2,8,103,"Traicionera*",1,4,"o",72,0,-1,0,111,111,"3355","",0,"","","",1,0,0,[],""],["frenk_t2-n3356",6,"De muy lejos yo te veo\nmuy junto con tu adorado;\nque te quiere, no lo creo,\nporque no eres de su agrado;\nno más te cumple deseos\ny te manda hasta Alvarado.",106,2,4,103,"El pájaro cú",9,6,"ao",14,0,-1,0,111,111,"3356","",0,"","","",1,0,0,[],""],["frenk_t2-n3357",6,"Si porque me vites probe\nme tratas de despreciar,\nmire bien con quién comercia,\nno se le vaya a arrancar;\nque hemos visto caer iglesias,\ncuantimás ese jacal.",105,2,-1,103,"Estrofa suelta",9,6,"a",-1,0,-1,0,111,111,"3357","",0,"","","",1,0,0,[],""],["frenk_t2-n3358",6,"Mi bien, protesto quererte,\ny de que pruebas te he dado;\npronto debes convencerte\nque por ponerte en estado\ntú has despreciado tu suerte.",105,2,-1,103,"Estrofa suelta",7,5,"ee",134,0,-1,0,111,111,"3358","",0,"","","",1,0,0,[],""],["frenk_t2-n3359",6,"Tú has despreciado tu suerte\npor consejos que te han dado;\npero anda, ingrata, y advierte:\npor dolo te han engañado,\n¡mejor te dieran la muerte!",105,2,-1,103,"Estrofa suelta",7,5,"ee",134,0,-1,0,111,111,"3359","",0,"","","",1,0,0,[],""],["frenk_t2-n3360",6,"Tú has mi amor engañádo\npor hallarte en la opulencia;\nte juzgo con gran amparo,\nlo siento por tu inocencia:\nque sólo te han engañado.",105,2,-1,103,"Estrofa suelta",7,5,"ao",-1,0,-1,0,111,111,"3360","",0,"","","",1,0,0,[],""],["frenk_t2-n3361",6,"Por el bato que te andas muriendo,\nal que ofreces tu amor verdadero,\ncon mi ropa te anda presumiendo,\nporque nunca tuvo pa un sombrero.",105,2,-1,103,"El Pata Rajada",3,4,"eo",-1,0,-1,0,111,111,"3361","",0,"","","",1,0,0,[],""],["frenk_t2-n3362",6,"En el fondo del mar\nyo vi una garza morena.\nNo lloro porque te vas,\nni lloro porque me dejas;\nalgún día comprenderás\neste amorcito que dejas.",108,2,8,103,"Estrofa suelta",9,6,"ea",-1,0,-1,0,111,111,"3362","",0,"","","",2,0,0,[],""],["frenk_t2-n3363",6,"Cuando quise no quisiste,\nahora que quieres no quiero:\npasarás tu vida triste,\ncual yo lo pasé primero.",108,2,8,103,"Que comienzo, que comienzo",1,4,"eo",38,0,-1,0,112,112,"3363","",0,"","","",8,0,0,[],""],["frenk_t2-n3364",6,"Tú me pediste amor, y yo te quise;\ntú me pediste mi vida, y te la di;\nsi al fin de cuentas te vas,\npos anda y vete:\nque la tristeza\nte lleve igual que a mí.",105,2,-1,103,"Arrieros somos",9,6,"i",23,0,-1,0,112,112,"3364","",0,"","","",1,0,0,[],""],["frenk_t2-n3365",6,"Juraste amarme y fingiste,\ndejándome gran pasión;\náhi llorarás sola y triste\ny sentirás el dolor:\nCecilia, ¡qué ingrata fuiste!",113,2,2,103,"La Cecilia",7,5,"ie",153,0,-1,0,112,112,"3365","",0,"","","",1,0,0,[],""],["frenk_t2-n3366",6,"Ya con ésta me despido,\nya me voy a retirar,\npero al cabo que con otro\ntú has de llegar a pagar.",105,2,-1,103,"Canción del Interior",0,4,"a",21,0,-1,0,112,112,"3366","",0,"","","",72,0,0,[],""],["frenk_t2-n3367",6,"Anda, ingrata, cautelosa,\nlos celos te han de matar,\nque lo que hiciste conmigo\ncon otro lo has de pagar.",115,2,3,103,"El muchacho alegre; Estrofa suelta",0,4,"a",21,0,-1,0,112,112,"3367","",0,"","","",1,0,0,[],""],["frenk_t2-n3368",6,"Pareces vapor volante\npor las calles donde vas;\ncomo hoy tienes nuevo amante,\nni los buenos días me das;\npero anda que allá adelante\ncon otros la pagarás.",108,2,8,103,"Estrofa suelta",9,6,"a",51,0,-1,0,112,112,"3368","",0,"","","",1,0,0,[],""],["frenk_t2-n3369",6,"Si porque me vistes pobre\ndespreciastes a mi amor,\nalgún día te harán la tonta,\ny sabrás lo que es amor.",108,2,8,103,"Que comienzo, que comienzo",0,4,"o",-1,0,-1,0,112,112,"3369","",0,"","","",1,0,0,[],""],["frenk_t2-n3370",6,"Yo quisiera ser herrero,\npara martillar mi amor.\nSi porque me viste fiero\nbuscastes otro mejor,\nalgún día te harán lo mismo,\ny sabrás lo que es dolor.",108,2,8,103,"Estrofa suelta",9,6,"o",72,0,-1,0,112,112,"3370","",0,"","","",1,0,0,[],""],["frenk_t2-n3371",6,"Tú te ríes de mi llanto,\ny puede ser que algún día\nyo te vea a ti llorar\nmás que lloró Jeremías.",105,2,-1,103,"Estrofa suelta",0,4,"ia",-1,0,-1,0,113,113,"3371","",0,"rm_t3","","",2,0,0,[],""],["frenk_t2-n3372",6,"Quiera Dios, falsa enemiga,\npor lo mal que me has pagado,\nque tantas lágrimas llores\ncomo yo por ti he llorado.",105,2,-1,103,"Estrofa suelta",0,4,"ao",14,0,-1,0,113,113,"3372","",0,"","","",1,0,0,[],""],["frenk_t2-n3373",6,"Paséate a tu contento,\nde mí no tengas recelo;\nsólo me queda un consuelo:\nque yo te he de ver regar\ncon tus lágrimas el suelo.",113,2,2,103,"Estrofa suelta",7,5,"eo",10,0,-1,0,113,113,"3373","",0,"","","",1,0,0,[],""],["frenk_t2-n3374",6,"Soy como el árbol caído,\nque quieres partir en dos;\nyo te perdono y olvido;\nno más tu castigo se lo dejo a Dios.",105,2,-1,103,"Arbol caído",3,4,"o",87,0,-1,0,113,113,"3374","",0,"","","",2,0,0,[],""],["frenk_t2-n3375",6,"Dices que ya no me quieres\ncomo de antes me querías;\ndicen que cerca del alma mía\nme ha de tocar a agonía,\nque por ahí te he de ver.",106,2,4,103,"El gavilancito",7,5,"e",-1,0,-1,0,113,113,"3375","",0,"","","",21,0,0,[],""],["frenk_t2-n3376",6,"Marcando con el compás\ncon que he de pasar mi vida,\nalgún día recordarás,\nfalsa, malagradecida;\nque el “mal haya” lo darás\ncuando te encuentres perdida.",112,2,6,103,"El taconcito",9,6,"ia",37,0,-1,0,113,113,"3376","",0,"","","",2,0,0,[],""],["frenk_t2-n3377",6,"Arrieros somos\ny en el camino andamos,\ny cada quien tendrá su merecido;\nya lo verás,\nque al fin de tu camino\nrenegarás hasta de haber nacido.",105,2,-1,103,"Arrieros somos",9,6,"io",-1,0,-1,0,113,113,"3377","",0,"","","",1,0,0,[],""],["frenk_t2-n3378",6,"Quisiera verte pidiendo\namor, por piedad, al mundo,\nmil desdenes recibiendo,\ny que pesar muy profundo\nfuera tu ser consumiendo.",108,2,8,103,"Traicionera; Estrofa suelta",7,5,"eo",52,0,-1,0,113,113,"3378","",0,"","","",1,0,0,[],""],["frenk_t2-n3379",6,"Quisiera que con mi muerte\nlas penas se me acabaran,\npero, en cambio, las tuyas\npor milagro aumentaran.",108,2,8,103,"Estrofa suelta",0,4,"aa",435,0,-1,0,113,113,"3379","",0,"","","",1,0,0,[],""],["frenk_t2-n3382",6,"Y acuérdate desde el tiempo\nque mis ojos no te ven,\ny si no te acuerdas bien,\nrecorre tu pensamiento:\nmira que yo soy aquel\nque adorastes en un tiempo.",106,2,4,105,"La morena",9,6,"eo",-1,0,-1,0,115,115,"3382","",0,"","","",1,0,0,[],""],["frenk_t2-n3383",6,"Y tú tan ingrata que eres,\nque no te acuerdas de mí;\nrecuerda, por tus amores,\nque yo soy quien antes fui.",115,2,3,105,"A todas horas del día",0,4,"i",23,0,-1,0,115,115,"3383","",0,"","","",1,0,0,[],""],["frenk_t2-n3384",6,"¿Qué no te acuerdas, Petrita,\nque en la sombra de un laurel\nse me vino a la memoria\nel escribirte un papel?",116,2,15,105,"El laurel",0,4,"e",32,0,-1,0,115,115,"3384","",0,"","","",1,0,0,[],""],["frenk_t2-n3385",6,"La presumida de Puebla,\nésa la conozco yo.\nMorena, ¿qué no te acuerdas\ncuando te besaba yo\ndebajo de aquella hiedra,\nque hasta la hiedra floreó?",112,2,6,105,"La presumida",9,6,"o",2,0,-1,0,115,115,"3385","",0,"","","",1,0,0,[],""],["frenk_t2-n3386",6,"La conozco hasta en los pasos,\nla presumida de Puebla;\npresumida, ¿no se acuerda\ncuando me tuvo en sus brazos\ndebajo de aquella hiedra,\ny hasta la hicimos pedazos?",112,2,6,105,"La presumida",9,6,"ao",132,0,-1,0,115,115,"3386","",0,"","","",1,0,0,[],""],["frenk_t2-n3387",6,"Siempre mi amor te reclama,\nmi corazón da de gritos,\nmis ojos se llenan de agua:\nme acuerdo de los besitos\nque tu boquita me daba.",106,2,4,105,"La morena",7,5,"aa",-1,0,-1,0,115,115,"3387","",0,"","","",1,0,0,[],""],["frenk_t2-n3388",6,"Petronita de mi vida,\nmorena, ¿qué haré sin ti?\nRecuerdo de tus caricias (Petrona)\ny de tu dulce mirar;\nayer penaba por verte (Petrona)\ny hoy peno porque te vi.",108,2,8,105,"Petrona",9,6,"i",23,0,-1,0,115,115,"3388","",0,"","","",2,0,0,[],""],["frenk_t2-n3390",6,"Yo sé que fue vacilada\ncuando te tuve abrazada\njuntito de aquel nopal;\nsentiste que te besaba,\nya luego que te espinabas\nempezaste a llorar.",105,2,-1,105,"Dos hojas sin rumbo",9,6,"a",-1,0,-1,0,116,116,"3390","",0,"","","",1,0,0,[],""],["frenk_t2-n3391",6,"Cada vez que cae la tarde\nganas me dan de llorar,\nsolamente de acordarme\nde aquel mentado lugar\ndonde solías encontrarme.",113,2,2,105,"La presumida'*",7,5,"ae",35,0,-1,0,116,116,"3391","",0,"","","",4,0,0,[],""],["frenk_t2-n3392",6,"Toda mi alegría se fue\ncuando tú así lo quisiste,\ny por amarte de veras,\nun día a mí me diste.\n¡Ay, linda rosa del alma!,\nte he de volver a ver.",106,2,4,105,"La Rosita",9,6,"e",-1,0,-1,0,116,116,"3392","",0,"","","",1,0,0,[],""],["frenk_t2-n3394",6,"Ingrata, ¿no me decías\nque primero habías de ver\nlas estrellas por el suelo\nque dejarme de querer?",108,2,8,105,"Cuatro esquinas tiene un catre",0,4,"e",20,0,-1,0,116,116,"3394","",0,"","","",1,0,0,[],""],["frenk_t2-n3395",6,"Tú eras la que me decías\ny me querías hacer creer\nque te pasabas los días\nsin comer y sin beber,\nde tanto que me querías.",105,2,-1,105,"La Petenera",7,5,"ia",214,0,-1,0,116,116,"3395","",0,"","","",2,0,0,[],""],["frenk_t2-n3396",6,"Tú me juraste un dichoso día,\ny de testigo pusiste a Dios,\ny me juraste sinceramente\nno separarnos nunca los dos.",105,2,-1,105,"El buque de más potencia’",3,4,"o",87,0,-1,0,116,116,"3396","",0,"","","",2,0,0,[],""],["frenk_t2-n3397",6,"Tú me juraste un dichoso día\nque me amarías a mí no más;\ny me juraste sinceramente\nno separarnos nunca jamás.",105,2,-1,105,"El buque de más potencia",3,4,"a",51,0,-1,0,117,117,"3397","",0,"","","",2,0,0,[],""],["frenk_t2-n3398",6,"¿Te acuerdas cuando estuvimos\nsentados en la escalera,\ny llorando me dijiste:\n“Ya veremos por quién queda”?",105,2,-1,105,"La morena",0,4,"ea",-1,0,-1,0,117,117,"3398","",0,"","","",1,0,0,[],""],["frenk_t2-n3399",6,"Me creí de tus amores,\npensando que eran sinceros,\ny sonriendo me dijiste:\n“Yo sí de veras te quiero.”",105,2,-1,105,"Un beso de amor",0,4,"eo",-1,0,-1,0,117,117,"3399","",0,"","","",1,0,0,[],""],["frenk_t2-n3400",6,"Recuerda de aquellas tardes\nque en tus brazos me dormías,\nque llorando me decías\nque nunca me olvidarías.",114,2,17,105,"Estrofa suelta",0,4,"ia",214,0,-1,0,117,117,"3400","",0,"","","",1,0,0,[],""],["frenk_t2-n3401b",6,"Agua de Tres Pocitos,\nfuentes de Tres Marías.\nRecuerda cuando pusistes\ntus manos sobre las mías\ny llorando me dijiste\nque nunca me olvidarías.",107,2,11,105,"Estrofa suelta",9,6,"ia",214,0,-1,0,117,117,"3401b","",0,"","","",1,0,0,[],""],["frenk_t2-n3401c",6,"Acuérdate que pusiste\ntus manos sobre las mías\ny llorando me dijiste\nque nunca me olvidarías:\n¡y lo primero que hiciste!",108,2,8,105,"El gavilán",7,5,"ie",153,0,-1,0,117,117,"3401c","",0,"","","",2,0,0,[],""],["frenk_t2-n3402",6,"Me dijiste que me amabas,\nque jamás me olvidarías;\ny lo primero que hiciste\nfue olvidar a quien querías.",105,2,-1,105,"Estrofa suelta, Un beso de amor",0,4,"ia",214,0,-1,0,118,118,"3402","",0,"","","",1,0,0,[],""],["frenk_t2-n3403",6,"Yo te dije, vida mía,\nsi de veras me querías,\ny sonriendo me dijiste\nque nunca me olvidarías.",105,2,-1,105,"Un beso de amor",0,4,"ia",214,0,-1,0,118,118,"3403","",0,"","","",1,0,0,[],""],["frenk_t2-n3404",6,"En Málaga tú naciste,\npero aquí te conocí;\nrecordarás que dijiste\nque tú me amabas a mí,\ny ahora vivo solo y triste,\nenamorado de ti.",105,2,-1,105,"Ninguna mujer, ninguna; Dios al formar tu hermosura",9,6,"i",23,0,-1,0,118,118,"3404","",0,"","","",1,0,0,[],""],["frenk_t2-n3406",6,"¿Pa qué te conocería,\nmujer infiel, sin corazón?\nSi no habías de ser tú mía,\n¿pa qué me juraste amor?",115,2,3,105,"Mañana se va tu prieto",0,4,"o",-1,0,-1,0,118,118,"3406","",0,"","","",1,0,0,[],""],["frenk_t2-n3407",6,"Anda, pérfida e inconstante,\ntú de mí te acordarás,\ny después sola dirás,\ncual traidora y falsa amante:\n“Tu mala hidra penetrante,\nsólo tú la reprobaste”.\nPrimero me idolatraste,\ntoda llena de ilusión;\nsi tenías mala intención,\ndime ¿para qué me amaste?",105,2,-1,105,"Estrofa suelta",18,10,"ae",212,0,-1,0,118,118,"3407","",0,"","","",1,0,0,[],""],["frenk_t2-n3408",6,"Cada vez que paso y miro\ndonde usted me salió [a] hablar\nmi corazón da un suspiro,\nsólo le falta llorar:\nno me hubiera usté admitido,\nsi me había de pagar mal.",108,2,8,105,"Estrofa suelta",9,6,"a",-1,0,-1,0,118,118,"3408","",0,"","","",25,0,0,[],""],["frenk_t2-n3409",6,"Me dan ganas de llorar,\nde saber que fuiste tú\nla que me hiciste llamar\ncon tus............................",106,2,4,105,"El sacamandú",3,4,"u",-1,0,-1,0,119,119,"3409","",0,"","","",1,0,0,[],""],["frenk_t2-n3410",6,"Si tú supieras, mi china,\ncómo sufro al recordarte,\nde lo que me propusiste\ny luego no quisiste darme.",105,2,-1,105,"Más allá de la frontera*",0,4,"ae",-1,0,-1,0,119,119,"3410","",0,"","","",3,0,0,[],""],["frenk_t2-n3411",6,"Con los ojos me anunciabas\nque me amabas tiernamente;\ningrata, me traicionabas:\ncuando de ti [estaba] ausente\nde mi pasión te burlabas.",105,2,-1,105,"El caimán; La malagueña",7,5,"aa",204,0,-1,0,119,119,"3411","",0,"","","",1,0,0,[],""],["frenk_t2-n3412",6,"Para tener un consuelo,\n¿adónde está esa amistad\nque antes me manifestabas?\nPues todo era falsedad:\nsolamente me engañabas,\nnada me decías verdad.",113,2,2,105,"Estrofa suelta",9,6,"a",16,0,-1,0,119,119,"3412","",0,"","","",1,0,0,[],""],["frenk_t2-n3413",6,"¿Para qué me dijiste\nque estabas sola?\n¡Estabas con tu amante,\nfalsa y traidora!",106,2,4,105,"La bamba; El pájaro cú",6,4,"oa",-1,0,-1,0,119,119,"3413","",0,"","","",10,0,0,[],""],["frenk_t2-n3414",6,"Felices noches que te soñaba,\nque te soñaba en felicidades,\nsoñaba cosas que me decías,\ny yo sentía tus falsedades.",110,2,10,105,"Estrofa suelta",3,4,"ae",373,0,-1,0,119,119,"3414","",0,"","","",1,0,0,[],""],["frenk_t2-n3415",6,"Cuando me distes entrada\nen el jardín de tu amor\nme ofrecistes una flor\nque estaba ya deshojada.",106,2,4,105,"Estrofa suelta",11,4,"aa",49,0,-1,0,119,119,"3415","",0,"","","",2,0,0,[],""],["frenk_t2-n3416",6,"Cada vez que paso y miro\ndonde tu amor me citó,\nme acuerdo y echo un suspiro\nal ver que ya terminó\nun amor tan consentido.",113,2,2,105,"Estrofa suelta",7,5,"io",-1,0,-1,0,119,119,"3416","",0,"","","",25,0,0,[],""],["frenk_t2-n3418",6,"¿No ves cuán triste dejan sus nidos\nlas golondrinas cuando se van?\nQuedé lloroso y abandonado,\ndespués te fuiste sin volver más.",105,2,-1,105,"Estrofa suelta",3,4,"a",-1,0,-1,0,120,120,"3418","",0,"","","",1,0,0,[],""],["frenk_t2-n3419",6,"Subí al cielo y tomé asiento,\nme coloqué en una nube;\nme quiso llevar el viento,\ny por tu amor me detuve;\n¡qué mala suerte la mía,\nque ni fortuna yo tuve!",108,2,8,105,"Estrofa suelta",9,6,"ue",348,0,-1,0,120,120,"3419","",0,"","","",1,0,0,[],""],["frenk_t2-n3420",6,"Mero me pongo a llorar\nal ver mi tirana suerte (¡ay de mí, Lloro-\npero me mantuve fuerte\ncomo reata de lazar (¡ay de mí, Llorona!),\ncuando la amarran a muerte.",106,2,4,105,"La Llorona",7,5,"ee",134,0,-1,0,120,120,"3420","",0,"","","",1,0,0,[],""],["frenk_t2-n3421",6,"En pensamientos ajenos\nandabas cuando te amé;\ntoda la vida intenté\ndejar lo más por lo menos.",113,2,2,105,"Estrofa suelta",11,4,"eo",365,0,-1,0,120,120,"3421","",0,"","","",1,0,0,[],""],["frenk_t2-n3422",6,"No me vuelvas a mirar\ncon esos ojos tan tristes,\nporque se me representa\nel mal pago que me diste.",130,2,21,105,"Estrofa suelta",0,4,"ie",-1,0,-1,0,120,120,"3422","",0,"","","",1,0,0,[],""],["frenk_t2-n3423",6,"Yo mi amor sacrifiqué\nen las aras de tu templo,\nno acordándome que había\nfortuna, mudanza y tiempo.",105,2,-1,105,"Estrofa suelta",0,4,"eo",-1,0,-1,0,120,120,"3423","",0,"","","",1,0,0,[],""],["frenk_t2-n3425",6,"Te fuistes y me dejastes\ncomo la piedra en el suelo,\ny así que me la pegastes\nme veniste a hacer el duelo:\ningrata, ¡qué bien quedaste!",117,2,5,105,"Estrofa suelta",7,5,"ae",-1,0,-1,0,121,121,"3425","",0,"","","",3,0,0,[],""],["frenk_t2-n3426",6,"Te ofrecí un cariño fiel,\npensando que me querías;\nquisiste jugar con él,\nde mi pasión te burlabas:\n¡qué corazón de mujer!",105,2,-1,105,"Estrofa suelta",7,5,"e",-1,0,-1,0,121,121,"3426","",0,"","","",1,0,0,[],""],["frenk_t2-n3427",6,"A tus plantas me rendí,\nqueriendo ser consolado;\npues tú me pagaste así,\npor eso me causa enfado (güerita),\ndesde que te conocí.",113,2,2,105,"El aguanieve*’",7,5,"i",23,0,-1,0,121,121,"3427","",0,"","","",1,0,0,[],""],["frenk_t2-n3428",6,"Una vez que te dije\nque me quisieras\nte subiste más alto\nque las estrellas.",105,2,-1,105,"La bamba",6,4,"ea",-1,0,-1,0,121,121,"3428","",0,"","","",6,0,0,[],""],["frenk_t2-n3429",6,"¿Qué le hiciste, mujer, qué le hiciste\na la flor que me dabas ayer?\nYo primero conocí a mis padres\ny después a una ingrata mujer.",109,2,7,105,"Vengo a ver unos ojos que tengo",3,4,"e",20,0,-1,0,121,121,"3429","",0,"","","",1,0,0,[],""],["frenk_t2-n3430",6,"¿Recuerdas, bella criatura,\nque las caricias volaron?\nUna prueba de finura:\nla herencia que nos dejaron\nfue una triste sepultura.",113,2,2,105,"Estrofa suelta",7,5,"ua",17,0,-1,0,121,121,"3430","",0,"","","",1,0,0,[],""],["frenk_t2-n3431",6,"Primera amonestación\nen la iglesia que leyeron\nfue la primera puñalada\nque a mi corazón le dieron.",105,2,-1,105,"El apasionado",0,4,"eo",105,0,-1,0,121,121,"3431","",0,"","","",5,0,0,[],""],["frenk_t2-n3433",6,"Que sepa el mundo entero\nque tú me abandonaste,\nque sepa que dijiste:\n“Yo ya no te quiero, no”.",105,2,-1,105,"Olvida que me amaste",5,4,"o",-1,0,-1,0,121,121,"3433","",0,"","","",1,0,0,[],""],["frenk_t2-n3434",6,"Cabrona que mal me pagastes\ncuando yo firme te amaba;\npor ti lloraban mis ojos\ncomo dos veneros de agua.",108,2,8,105,"Estrofa suelta",0,4,"aa",-1,0,-1,0,122,122,"3434","",0,"","","",1,0,0,[],""],["frenk_t2-n3435",6,"No lloro, pero me acuerdo (¡ay, Llorona!)\nde aquellos gustos que tuve;\nme subiste y me bajaste (Llorona)\ncomo el agua entre las nubes.",108,2,8,105,"La Llorona",3,4,"ue",-1,0,-1,0,122,122,"3435","",0,"","","",1,0,0,[],""],["frenk_t2-n3436",6,"Negra, ¿dónde están los lazos\ncon que mi amor se amarró?\nAunque me costara un paso\npero se me concedió.",109,2,7,105,"Costeña; Negra, ¿dónde están los lazos?",0,4,"o",2,0,-1,0,122,122,"3436","",0,"","","",1,0,0,[],""],["frenk_t2-n3437",6,"¿Habrá desdicha en el mundo\ncomo haber sido y no ser,\nhaberme visto querido,\ny hoy no me puedes ver?",108,2,8,105,"Estrofa suelta",0,4,"e",20,0,-1,0,122,122,"3437","",0,"","","",1,0,0,[],""],["frenk_t2-n3438",6,"Por debajo de la arena\ncorre el agua y no la vemos;\n¿por qué nos quisimos tanto,\ny hora nos aborrecemos?",107,2,11,105,"Bonito San Juan del Río",0,4,"eo",127,0,-1,0,122,122,"3438","",0,"","","",6,0,0,[],""],["frenk_t2-n3439",6,"Vámonos por los barrancos,\nenfrente de los sabinos.\n¿Por qué nos queríamos tanto?\nAhora nos aborrecimos:\nseguro por un espanto,\ny una visión que tuvimos.",113,2,2,105,"Estrofa suelta",9,6,"io",329,0,-1,0,122,122,"3439","",0,"","","",1,0,0,[],""],["frenk_t2-n3440",6,"Tú me enseñaste a querer,\ntambién me enseñaste a amar;\ndel tiempo estoy aprendiendo\nel consuelo de olvidar.",105,2,-1,105,"Llora, corazón",0,4,"a",21,0,-1,0,122,122,"3440","",0,"","","",1,0,0,[],""],["frenk_t2-n3441",6,"Al lado, al lado, al ladito,\npor la orillita del mar;\n¿cuándo vendrá el pescadito\nque nos enseñó a olvidar?",108,2,8,105,"María del Carmen",1,4,"a",21,0,-1,0,122,122,"3441","",0,"","","",1,0,0,[],""],["frenk_t2-n3442",6,"Pensabas que iba a rogarte\npara pedirte perdón,\ny así poder humillarme,\npues te faltó el corazón.",105,2,-1,105,"Espina traidora",0,4,"o",31,0,-1,0,122,122,"3442","",0,"","","",1,0,0,[],""],["frenk_t2-n3443",6,"De tu negra decepción\nsólo me queda un consuelo:\nque nunca por tu pasión\nmi rodilla tocó el suelo,\nimplorándote perdón.",113,2,2,105,"Estrofa suelta",7,5,"o",31,0,-1,0,122,122,"3443","",0,"","","",1,0,0,[],""],["frenk_t2-n3444",6,"Tengo una pena tan grande (Llorona),\nque casi puedo decir\nque yo no tengo la pena (Llorona):\nla pena me tiene a mí.",107,2,11,106,"La Llorona",3,4,"i",-1,0,-1,0,125,125,"3444","",0,"","","",1,0,0,[],""],["frenk_t2-n3445",6,"Todos los días que amanece\naumenta más el amor;\nmientras que el cariño crece,\ntodo es un vivo dolor\nque mi corazón padece.",112,2,6,106,"La huazanga; La madrugada",7,5,"ee",64,0,-1,0,125,125,"3445","",0,"","","",4,0,0,[],""],["frenk_t2-n3446",6,"Y dicen que el tiempo borra\nlos pesares del amor,\npero a mí se me afigura\nque con el tiempo estoy peor.",105,2,-1,106,"La mujer ladina",0,4,"o",72,0,-1,0,125,125,"3446","",0,"","","",1,0,0,[],""],["frenk_t2-n3447",6,"Los blancos nardos ya florecieron,\nlas margaritas, las madreselvas;\nlos arrayanes no han florecido,\ny han aumentado mis tristes penas.",105,2,-1,106,"Los arrayanes",3,4,"ea",-1,0,-1,0,125,125,"3447","",0,"","","",1,0,0,[],""],["frenk_t2-n3448",6,"A un Santo Cristo del Istmo (Llorona)\nmis penas le fui a contar;\n¡cuáles no serían mis penas (Llorona),\nque el santo quiso llorar!",107,2,11,106,"La Llorona",3,4,"a",21,0,-1,0,125,125,"3448","",0,"","","",1,0,0,[],""],["frenk_t2-n3449",6,"A un Santo Cristo de acero (¡ay, Llorona!)\nmis penas le conté yo;\n¡cuáles no serían mis penas (Llorona),\nque el Santo Cristo lloró!",108,2,8,106,"La Llorona",3,4,"o",2,0,-1,0,125,125,"3449","",0,"","","",1,0,0,[],""],["frenk_t2-n3450",6,"La capilla está desierta,\nsólo Cristo aquí me ve,\ncon el alma fría y muerta\npor la dicha que dejé.",105,2,-1,106,"Luto negro",1,4,"e",77,0,-1,0,125,125,"3450","",0,"","","",1,0,0,[],""],["frenk_t2-n3452a",6,"De noche siento momentos\nde arrancarme el corazón;\nson tantos mis sufrimientos\nal saber que mi ilusión\nse la llevaron los vientos.",108,2,8,106,"Traicionera",7,5,"eo",234,0,-1,0,126,126,"3452a","",0,"","","",1,0,0,[],""],["frenk_t2-n3453",6,"Como no tengo contento,\nle hablo a la naturaleza;\nse confunde el pensamiento,\nme arrebata la tristeza\ny me mata el sufrimiento.",112,2,6,106,"Estrofa suelta",7,5,"eo",94,0,-1,0,126,126,"3453","",0,"","","",1,0,0,[],""],["frenk_t2-n3455",6,"No me voy arrepentido\nporque sé que tengo honor,\nvoy a ver si encuentro olvido\no me muero de dolor.",105,2,-1,106,"Virgencita de Zapopan",1,4,"o",72,0,-1,0,126,126,"3455","",0,"","","",1,0,0,[],""],["frenk_t2-n3456",6,"Ne le temo a la muerte,\nmás le temo a la vida;\n¡cómo cuesta morirse\ncuando el alma anda herida!",105,2,-1,106,"La muerte**",0,4,"ia",37,0,-1,0,126,126,"3456","",0,"","","",1,0,0,[],""],["frenk_t2-n3457",6,"La estrellita voló\nal este y al estillero;\néchenme tiros al agua,\nque me muero, que me muero",105,2,-1,106,"El estillero",0,4,"eo",38,0,-1,0,126,126,"3457","",0,"","","",2,0,0,[],""],["frenk_t2-n3458",6,"Yo quisiera aborrecer,\npero no hallo cómo hacer,\nque es mi pasión tan fuerte,\nque le pido al Gran Poder\nmejor me mande la muerte.",105,2,-1,106,"La azucena",7,5,"ee",134,0,-1,0,127,127,"3458","",0,"","","",1,0,0,[],""],["frenk_t2-n3459",6,"Dicen que es mala suerte\ntres aguacates plantar;\nsi esto me causa la muerte,\nhasta los voy a regar.",105,2,-1,106,"Los aguacates",1,4,"a",21,0,-1,0,127,127,"3459","",0,"","","",1,0,0,[],""],["frenk_t2-n3460",6,"Pasa un año redondito\nque yo padezco de amor,\ndiciendo: “¡Que muera, muera,\nel que no sepa de amor!”",116,2,15,106,"El pelado’",0,4,"o",-1,0,-1,0,127,127,"3460","",0,"","","",1,0,0,[],""],["frenk_t2-n3461",6,"Todos los pájaros cantan\ncuando cae un aguacero;\na mí me arde la garganta,\nque casi cantar no puedo;\nhay dolores que se aguantan,\npero yo de éste me muero.",105,2,-1,106,"El pájaro cú",9,6,"eo",-1,0,-1,0,127,127,"3461","",0,"","","",1,0,0,[],""],["frenk_t2-n3463",6,"¡Qué pena llevo en la cara,\nque toditos me la ven!\nYo quisiera que la vieran,\npero que la vieran bien;\nentonces verían mi cara:\n¡qué pena tan cara ven!",105,2,-1,106,"Pena huasteca",9,6,"e",242,0,-1,0,127,127,"3463","",0,"","","",1,0,0,[],""],["frenk_t2-n3464",6,"Los que como yo han sufrido\nen terrible Recepción,\nya lo habrán compadecido,\nporque me inspira pasión\nmi semblante adolorido.",105,2,-1,106,"El sacamandú",7,5,"io",101,0,-1,0,127,127,"3464","",0,"","","",1,0,0,[],""],["frenk_t2-n3465",6,"Pobres de esos corazones\nque les pasa lo que a mí:\nme alimentan las pasiones,\npues goces no tengo aquí:\nsólo negras decepciones.",113,2,2,106,"Estrofa suelta",7,5,"oe",34,0,-1,0,127,127,"3465","",0,"","","",1,0,0,[],""],["frenk_t2-n3466a",6,"Cupido, rey del amor,\ndime por qué me maltratas;\nno pareces buen pastor,\npues que tus ovejas matas.",105,2,-1,106,"El Cupido",1,4,"aa",328,0,-1,0,127,127,"3466a","",0,"","","",2,0,0,[],""],["frenk_t2-n3467",6,"La pasión que yo llevo\ndentro del pecho\nha causado ya estragos\na mi existencia.",105,2,-1,106,"Estrofa suelta",6,4,"ea",-1,0,-1,0,128,128,"3467","",0,"","","",1,0,0,[],""],["frenk_t2-n3468",6,"Ya las sombras de la noche\nse tienden sobre mi pecho,\ny mi alma por la tarde\nse va muriendo.",105,2,-1,106,"Atardecer huasteco",3,4,"eo",-1,0,-1,0,128,128,"3468","",0,"","","",1,0,0,[],""],["frenk_t2-n3469",6,"Como el sol de la tarde,\nque va muriendo,\nel sol de mis amores\nme va oprimiendo.",105,2,-1,106,"Atardecer huasteco",6,4,"eo",52,0,-1,0,128,128,"3469","",0,"","","",1,0,0,[],""],["frenk_t2-n3470",6,"En la rama de un olivo\nuna calandria cantó;\ncantó con su pecho herido,\ncomo ahora lo tengo yo.",108,2,8,106,"Estrofa suelta",0,4,"o",2,0,-1,0,128,128,"3470","",0,"","","",3,0,0,[],""],["frenk_t2-n3471",6,"Por las riberas del Pánuco\nyo vi un árbol muy florido:\nes el árbol consentido\nde las que sufren de amor.",105,2,-1,106,"El framboyán",5,4,"o",-1,0,-1,0,128,128,"3471","",0,"","","",1,0,0,[],""],["frenk_t2-n3472",6,"Ahora sí, paloma blanca,\nno tengo quien me consuele;\nel corazón traigo herido,\npor todas partes me duele.",105,2,-1,106,"Estrofa suelta",0,4,"ee",515,0,-1,0,128,128,"3472","",0,"","","",1,0,0,[],""],["frenk_t2-n3473",6,"Cómpreme este corazón,\nse lo doy de conveniencia,\nque sabe lo que es dolor\ny está hecho a tener paciencia,",114,2,17,106,"Estrofa suelta",0,4,"ea",46,0,-1,0,128,128,"3473","",0,"frenk_t4","","",3,0,0,[],""],["frenk_t2-n3474",6,"Es bonito amanecer\npor la calle real cantando,\nporque se tiene un querer;\ny el pobrecito de mí\ncon ese amor batallando.",111,2,1,106,"Estrofa suelta",7,5,"ao",33,0,-1,0,128,128,"3474","",0,"","","",1,0,0,[],""],["frenk_t2-n3475",6,"Quisiera ser como el león,\npara internarme en el bosque\ny llorar mi situación,\ncomo aquel triste cenzontle,\nherido del corazón.",108,2,8,106,"Traicionera",7,5,"o",31,0,-1,0,129,129,"3475","",0,"","","",1,0,0,[],""],["frenk_t2-n3476",6,"De tarde se me hace triste (Llorona),\nde noche, con más razón,\ny llorando me amanece (Llorona),\nllorando se pone el sol.",107,2,11,106,"La Llorona",3,4,"o",-1,0,-1,0,129,129,"3476","",0,"","","",1,0,0,[],""],["frenk_t2-n3477",6,"En oscuros peñascales\ny en los bosques más sombríos\nme puse a llorar mis males\ny también mis desvarios.\n¡Oh, qué tiempos tan fatales!,\n¡qué sufrimientos los míos!",108,2,8,106,"Estrofa suelta",9,6,"io",135,0,-1,0,129,129,"3477","",0,"","","",1,0,0,[],""],["frenk_t2-n3478",6,"Yo fui a pedirle a las olas\nlágrimas para llorar\ny me regresé sin nada:\nse había secado la mar.",108,2,8,106,"María del Carmen",0,4,"a",21,0,-1,0,129,129,"3478","",0,"","","",1,0,0,[],""],["frenk_t2-n3479",6,"Me van a secar el mar\npa regarlo con mi llanto,\nque al cabo yo sé llorar,\npero no más me aguanto.",105,2,-1,106,"No más me aguanto",1,4,"ao",30,0,-1,0,129,129,"3479","",0,"","","",1,0,0,[],""],["frenk_t2-n3480",6,"Los pajaritos y yo\nnos levantamos a un tiempo:\nellos, a cantar el alba,\ny yo, a llorar mi tormento.",106,2,4,106,"El curripití; El jarabe; María del Carmen; El pájaro cú; Estrofa suelta",0,4,"eo",-1,0,-1,0,129,129,"3480","",0,"","","",5,0,0,[],""],["frenk_t2-n3481",6,"Salgo a los campos,\nno encuentro ningún consuelo;\nllego a mi casa,\ny es purito llorar.",105,2,-1,106,"Oyes, Lupita",3,4,"a",-1,0,-1,0,129,129,"3481","",0,"","","",1,0,0,[],""],["frenk_t2-n3482",6,"No hallo en qué disipar\nesta pena que me abruma;\ntodo se me va en llorar\ny lamentar mi fortuna.\nBajo esta pálida luna “\nlloro por el bien perdido,\npidiendo a Dios el auxilio,\nque me dé fuerza y valor\npara sufrir con paciencia\nmi sufrimiento y dolor.",105,2,-1,106,"Tristes lamentos de un huerfanito",18,10,"o",72,0,-1,0,129,129,"3482","",0,"","","",1,0,0,[],""],["frenk_t2-n3484",6,"Ahora acabo de llegar,\nque ni cantar he podido;\nganas de llorar me dan\nde ver lo que ha sucedido.",105,2,-1,106,"Ahora acabo de llegar",0,4,"io",101,0,-1,0,130,130,"3484","",0,"","","",1,0,0,[],""],["frenk_t2-n3485",6,"Mi marido fue a La Habana,\ny le encargué un delantal,\ncon un letrero que diga:\n“Cada vez que me lo pongo\nme dan ganas de llorar.”",105,2,-1,106,"Mi marido fue a La Habana",7,5,"a",-1,0,-1,0,130,130,"3485","",0,"","","",2,0,0,[],""],["frenk_t2-n3486",6,"¡Mira qué limón tan fino\ntengo para madurar!\nVoy a tirar un suspiro,\nporque no puedo llorar.",105,2,-1,106,"Estrofa suelta",0,4,"a",21,0,-1,0,130,130,"3486","",0,"","","",1,0,0,[],""],["frenk_t2-n3487",6,"Como que quiere llover,\ncomo que quiere hacer aire,\ncomo que quiere llorar\neste corazón cobarde.",127,2,18,106,"El tejón; Manuelita",0,4,"ae",-1,0,-1,0,130,130,"3487","",0,"","","",3,0,0,[],""],["frenk_t2-n3488",6,"¡Ay!, corazón,\ndéjame llorar;\nel corazón me duele\nde tanto amar.",109,2,7,106,"Si las flores del campo",6,4,"a",21,0,-1,0,130,130,"3488","",0,"","","",3,0,0,[],""],["frenk_t2-n3489a",6,"Verdes limones del río,\nrosales de la cañada;\n¿qué tienes, corazón mío,\nque no te ¿vierte nada?",108,2,8,106,"Estrofa suelta",1,4,"aa",49,0,-1,0,130,130,"3489a","",0,"","","",1,0,0,[],""],["frenk_t2-n3489b",6,"Aguas azules de un río,\nárboles de una cañada;\n¿qué tienes, corazón mío,\nque no te consuela nada,\ncomo una flor sin rocío?",105,2,-1,106,"El gusto",7,5,"io",3,0,-1,0,130,130,"3489b","",0,"","","",1,0,0,[],""],["frenk_t2-n3489c",6,"Piedras azules del río,\nque viven en la cañada.\n¿Qué tienes, corazón mío,\nque no te consuela nada?\nEs rosita sin rocío,\nque no vive amarchitada.",112,2,6,106,"El fandanguito",9,6,"aa",49,0,-1,0,130,130,"3489c","",0,"","","",1,0,0,[],""],["frenk_t2-n3491",6,"Razón tienes corazón,\nlágrimas el pecho exhale;\nmas, ¡ay qué inútiles son\na quien la razón no vale!",105,2,-1,106,"Estrofa suelta",1,4,"ae",202,0,-1,0,131,131,"3491","",0,"","","",1,0,0,[],""],["frenk_t2-n3492",6,"Ay, corazón,\ncuánto has sufrido\npor haber sido bueno\ny haber querido.\nSigue queriendo,\nque la gloria se alcanza (cielito lindo)\nsólo sufriendo.",106,2,4,106,"Cielito lindo",4,7,"eo",52,0,-1,0,131,131,"3492","",0,"","","",3,0,0,[],""],["frenk_t2-n3493",6,"Corazón, que renaciendo\na las ilusiones vas,\ntu letargo sacudiendo,\n¡sigue, corazón, durmiendo,\ny no despiertes jamás!",108,2,8,106,"Estrofa suelta",7,5,"a",51,0,-1,0,131,131,"3493","",0,"","","",1,0,0,[],""],["frenk_t2-n3494",6,"Corazón, ¿de qué estás triste?,\ndeja de tanto pensar;\nde aquello que me dijiste\nno te debes acordar,\nporque así me lo ofreciste,\nno teniendo ya lugar.",105,2,-1,106,"El jarabe loco",9,6,"a",21,0,-1,0,131,131,"3494","",0,"","","",2,0,0,[],""],["frenk_t2-n3495",6,"Corazón, que tienes callo,\n¡ay!, ya de tanto llorar,\nvolviendo María del Rayo\nun suspiro le has de echar.",108,2,8,106,"La morena",1,4,"a",21,0,-1,0,131,131,"3495","",0,"","","",1,0,0,[],""],["frenk_t2-n3496",6,"¿Qué pajarillo es aquél,\nde los ojos tan bonitos?\nDile que ya no me mire,\nporque estoy adolorido.",105,2,-1,106,"Pajarillo barranqueño",0,4,"io",-1,0,-1,0,131,131,"3496","",0,"","","",8,0,0,[],""],["frenk_t2-n3498",6,"Aquel pajarito, madre,\nque canta en el árbol verde,\ndígale usted que no cante,\nporque su canto me ofende.",105,2,-1,106,"Pajarillo barranqueño",0,4,"ee",-1,0,-1,0,132,132,"3498","",0,"","","",1,0,0,[],""],["frenk_t2-n3499",6,"¿Qué pajarillo es aquél,\nque canta en aquella higuera?\nAnda y dile que no cante,\nque espere a que yo muera.",107,2,11,106,"Pajarillo barranqueño; El pájaro cú",0,4,"ea",44,0,-1,0,132,132,"3499","",0,"","","",8,0,0,[],""],["frenk_t2-n3500",6,"Ya no cantes, pajarillo,\npajarillo barranqueño,\n¿qué no ves que con tu canto\nme estás matando de celos?",105,2,-1,106,"Pajarillo barranqueño",0,4,"eo",-1,0,-1,0,132,132,"3500","",0,"","","",1,0,0,[],""],["frenk_t2-n3501",6,"Pajarillo, pajarillo,\npajarillo de la rama;\nya no me cantes tan triste,\nporque me partes el alma.",105,2,-1,106,"Pajarillo barranqueño",0,4,"aa",-1,0,-1,0,132,132,"3501","",0,"","","",9,0,0,[],""],["frenk_t2-n3502",6,"Yo tenía mi cupidito,\nvestido con seda china;\ny me dijo el pobrecito:\n“No cantes, que me lastimas\nmi pobre corazoncito.”",107,2,11,106,"El Cupido",7,5,"io",119,0,-1,0,132,132,"3502","",0,"","","",1,0,0,[],""],["frenk_t2-n3503",6,"Rueda, carreta de amor,\nsácame de este arenal,\npues ya las olas me tapan,\ny no puedo navegar.",105,2,-1,106,"El carretero; Estrofa suelta",0,4,"a",-1,0,-1,0,133,133,"3503","",0,"","","",1,0,0,[],""],["frenk_t2-n3504",6,"Ya me cansé de soñar,\nel sueño me hace sufrir;\nquisiera que al despertar\nmi sueño fuera verdad,\npara dejar de sufrir.",105,2,-1,106,"El sueño",7,5,"i",-1,0,-1,0,133,133,"3504","",0,"","","",1,0,0,[],""],["frenk_t2-n3505",6,"¡Ay de mí, Llorona!,\nLlorona, llévame a ver\ndonde de amores se olvida (Llorona)\ny se empieza a padecer.",108,2,8,106,"La Llorona",3,4,"e",20,0,-1,0,133,133,"3505","",0,"","","",35,0,0,[],""],["frenk_t2-n3506",6,"En una estrecha prisión\nmi corazón está herido,\nllorando y arrepentido,\npidiendo a Dios confesión;\nmas ya llegó la ocasión\nde que diga su pecado:\ndelante de Dios hincado\npide con gran devoción\nque le den absolución\nen declarando su estado.",105,2,-1,106,"Estrofa suelta",18,10,"ao",14,0,-1,0,133,133,"3506","",0,"","","",1,0,0,[],""],["frenk_t2-n3507",6,"Madre mía de Guadalupe\nlloro por este dolor:\narráncamelo del pecho,\nque es dolor de puro amor.",105,2,-1,106,"Estrofa suelta",0,4,"o",72,0,-1,0,133,133,"3507","",0,"","","",4,0,0,[],""],["frenk_t2-n3508",6,"Si la vida ha de ser dolorosa,\nsi las penas vendrán a amargarla,\npor piedad, Virgen Santa, la calma\ndale al pobre infeliz corazón.",105,2,-1,106,"Desgraciado yo soy, Virgen Santa",3,4,"o",-1,0,-1,0,133,133,"3508","",0,"","","",1,0,0,[],""],["frenk_t2-n3509",6,"Silencio, corazón,\ndeja de llorar;\neste corazón me duele (negra del alma)\nde tanto amar.",108,2,8,106,"Ahora acabo de llegar",3,4,"a",21,0,-1,0,133,133,"3509","",0,"","","",2,0,0,[],""],["frenk_t2-n3510",6,"Sospiro, que dende adentro\nte sales a divertir,\nsi no has de lograr tu intento,\nsospiro, métete adentro,\nno andes dando qué decir.",105,2,-1,106,"Estrofa suelta",7,5,"i",157,0,-1,0,133,133,"3510","",0,"","","",1,0,0,[],""],["frenk_t2-n3511",6,"Acaba, sueño, de dar\nalivio a tanto tormento;\nno aflijas mi pensamiento,\ndéjame ya descansar.",105,2,-1,106,"Canto de Luzbel",11,4,"a",21,0,-1,0,133,133,"3511","",0,"","","",1,0,0,[],""],["frenk_t2-n3513",6,"Muchas veces el enfado\nhace al hombre renegar;\nyo a un ángel le he preguntado\ncon qué se podrá curar\nun corazón lastimado.",112,2,6,106,"La leva; El gusto",7,5,"ao",14,0,-1,0,134,134,"3513","",0,"","","",1,0,0,[],""],["frenk_t2-n3514",6,"No sé qué yerba es el amor,\nque tiene rama de accidente;\nando buscando un doctor,\nque me le ponga un ungüento\npara aplacar mi dolor,\nque lo tengo diariamente.",108,2,8,106,"Estrofa suelta",9,6,"ee",15,0,-1,0,134,134,"3514","",0,"","","",1,0,0,[],""],["frenk_t2-n3515",6,"Si me voy, siento una pena (¡ay, Llorona),\nsi me quedo, siento dos:\npor no sentir ni una pena (¡ay, Llorona!),\nni me quedo ni me voy.",108,2,8,106,"La Llorona",3,4,"o",-1,0,-1,0,134,134,"3515","",0,"","","",1,0,0,[],""],["frenk_t2-n3517",6,"Llorar, corazón, llorar,\nllorar con mucha ternura,\nque no es afrenta en un hombre\nllorar por una hermosura.",105,2,-1,106,"Las mañanitas",0,4,"ua",17,0,-1,0,134,134,"3517","",0,"","","",2,0,0,[],""],["frenk_t2-n3518",6,"Llorar, corazón, llorar,\nllorar sin saber por qué,\nque no es delito llorar\npor querer a una mujer.",105,2,-1,106,"Las mañanitas; Llora, corazón; La Llorona",0,4,"e",-1,0,-1,0,134,134,"3518","",0,"","","",2,0,0,[],""],["frenk_t2-n3520a",6,"¡Ay de mí, Llorona!,\nmi Lloroncita de oro,\nla causa de mi llanto\nes una prenda que adoro.",105,2,-1,106,"La Lloroncita",0,4,"oo",85,0,-1,0,135,135,"3520a","",0,"","","",35,0,0,[],""],["frenk_t2-n3520c",6,"¡Y ay, llorar, Llorona!\nque lloro, que lloro,\ny la causa de mi llanto\nes una prenda que adoro,\ny por eso lloro tanto,\ny por eso tanto lloro.",105,2,-1,106,"La Llorona",9,6,"oo",85,0,-1,0,135,135,"3520c","",0,"","","",2,0,0,[],""],["frenk_t2-n3521",6,"¡Ay de mí, Llorona!,\nque llore, que ría;\nque es la causa de mi llanto,\ny ésa es toda mi alegría.",105,2,-1,106,"La Lloroncita",0,4,"ia",0,0,-1,0,135,135,"3521","",0,"","","",35,0,0,[],""],["frenk_t2-n3522",6,"El alma llora de pena\nsin consuelo en el dolor,\ny ante su imagen serena\nlloro y pido su perdón.",105,2,-1,106,"Luto negro",0,4,"o",-1,0,-1,0,135,135,"3522","",0,"","","",1,0,0,[],""],["frenk_t2-n3523",6,"¡Ay, sí, sí, sí!,\nesto no tiene que ver;\n¡ay, no, no, no!,\nlloro por esta mujer.",115,2,3,106,"roña!) [El triste’",3,4,"e",20,0,-1,0,135,135,"3523","",0,"","","",1,0,0,[],""],["frenk_t2-n3524",6,"Por cuatro caminos ando,\npensando cuál tomaré,\npero siempre imaginando\npor el ángel que adoré,\nque por él vivo penando.",112,2,6,106,"La Malagueña; Estrofa suelta",7,5,"ao",33,0,-1,0,135,135,"3524","",0,"","","",1,0,0,[],""],["frenk_t2-n3526",6,"Cuando canto “La azucena”\nsiento un dolor en el alma;\nes que es tan grande mi pena,\nque me ha robado la calma\nuna preciosa morena.",106,2,4,106,"La azucena",7,5,"ea",59,0,-1,0,136,136,"3526","",0,"","","",1,0,0,[],""],["frenk_t2-n3527",6,"Estando yo recostado\nen lo fresco de la arena,\noí la voz de un pescado,\nque le dijo a la sirena:\n“¡Qué trabajos he pasado\npor amar a una morena!”",109,2,7,106,"La Petenera; El balajú; Me un espiadero; Estrofa suelta",9,6,"ea",59,0,-1,0,136,136,"3527","",0,"","","",2,0,0,[],""],["frenk_t2-n3528",6,"Ya para mí se acabó\nel gusto con que cantaba;\nuna joven que yo amaba,\nqué engañado estaba yo.",112,2,6,106,"El gusto",11,4,"o",2,0,-1,0,136,136,"3528","",0,"","","",2,0,0,[],""],["frenk_t2-n3529",6,"Dicen que me han de matar\ncon una daga muy fría;\nlas heridas que me matan\nme las causa mi María.",105,2,-1,106,"María, María",0,4,"ia",0,0,-1,0,136,136,"3529","",0,"","","",20,0,0,[],""],["frenk_t2-n3530",6,"Yo no soy sauce llorón,\npero a veces ya no aguanto:\nno más pujo y me atraganto\nal pensar en mi María.",105,2,-1,106,"María, María",5,4,"ia",-1,0,-1,0,136,136,"3530","",0,"","","",1,0,0,[],""],["frenk_t2-n3531",6,"Bonita es una pasión\ncuando nos trae a la greña;\nse me rajó el corazón\nal recordar a mi dueña.",105,2,-1,106,"María, María",1,4,"ea",291,0,-1,0,136,136,"3531","",0,"","","",1,0,0,[],""],["frenk_t2-n3533",6,"Un amor me carga loco,\ny no lo acabo de creer:\namor que me quita el sueño\ny las ganas de comer.",108,2,8,106,"Estrofa suelta",0,4,"e",20,0,-1,0,137,137,"3533","",0,"","","",1,0,0,[],""],["frenk_t2-n3534",6,"De las naranjas comí,\nde vino me eché una copa,\ny un hombre a quien conocí\nme dejó como una loca.",115,2,3,106,"Vasito de agua de coco",0,4,"oa",-1,0,-1,0,137,137,"3534","",0,"","","",1,0,0,[],""],["frenk_t2-n3535",6,"Pobrecita de la palma,\nde la palma su Horero;\nasí se marchita mi alma:\nno hay amor como el primero.",108,2,8,106,"San Francisco",1,4,"eo",38,0,-1,0,137,137,"3535","",0,"","","",2,0,0,[],""],["frenk_t2-n3536",6,"Me despido, porque al cabo\na la larga he de perder;\na mi corazón le pago\nporque no me dé a saber.",109,2,7,106,"La Sanmarqueña",0,4,"e",20,0,-1,0,137,137,"3536","",0,"","","",1,0,0,[],""],["frenk_t2-n3537a",6,"Subí al cerro de Diana\na preguntarle a Cupido\nque cuál era la campana\ncon que se toca al olvido,\npara olvidar a una ingrata,\nque olvidarla no he podido.",105,2,-1,106,"El pájaro carpintero; Eres alta y delgadita; Estrofa suelta",9,6,"io",101,0,-1,0,137,137,"3537a","",0,"","","",2,0,0,[],""],["frenk_t2-n3538",6,"Santo Papa de Roma,\n¿por qué consientes\nque los enamorados\nvivan ausentes?",105,2,-1,107,"Estrofa suelta",6,4,"ee",252,0,-1,0,138,138,"3538","",0,"","","",1,0,0,[],""],["frenk_t2-n3539",6,"Dime, Dios, ¿por qué nací,\nsi pronto habías de llamarme?\n¿Pues qué tanto te ofendí,\nque ya quieres separarme\nde la mujer que amo aquí?",105,2,-1,107,"El caimán; La leva; La Malagueña; Estrofa suelta",7,5,"i",23,0,-1,0,138,138,"3539","",0,"","","",1,0,0,[],""],["frenk_t2-n3540",6,"Para irme para mi tierra\nyo no hallo ni cómo hacer;\nno más me pongo a pensar\nque aquí dejo a esta mujer.",105,2,-1,107,"Canción del Interior",0,4,"e",20,0,-1,0,138,138,"3540","",0,"","","",1,0,0,[],""],["frenk_t2-n3541",6,"Para que olvidarme pueda,\nmi alma tiene que llorar;\nes imposible que vuelva\nen la vida yo a encontrar\notro amor tan verdadero\ncomo el que voy a dejar.",113,2,2,107,"Estrofa suelta",9,6,"a",21,0,-1,0,138,138,"3541","",0,"","","",1,0,0,[],""],["frenk_t2-n3542",6,"Me voy para otros caminos,\nme voy para otros lugares,\nme voy para otros senderos,\nsolito por la vereda.\nSi no quieren que la quiera,\npídanle a Dios que me muera.",105,2,-1,107,"No más me aguanto",9,6,"ea",44,0,-1,0,138,138,"3542","",0,"","","",1,0,0,[],""],["frenk_t2-n3543",6,"Ya los arrieros se van,\ny yo me voy con ellos;\nlo que me puede es dejar\nese par de ojitos negros.",105,2,-1,107,"El chúmbale",0,4,"eo",-1,0,-1,0,138,138,"3543","",0,"","","",2,0,0,[],""],["frenk_t2-n3544",6,"¿Qué tienen esos ojitos?,\n¿por qué me miran así?\nNo hallo cómo darles gusto:\nmañana me voy de aquí.",105,2,-1,107,"Adelaida",0,4,"i",23,0,-1,0,138,138,"3544","",0,"","","",2,0,0,[],""],["frenk_t2-n3545",6,"Ayer tomaba de gusto,\nhoy tomo de pesar,\nporque a la joven que yo amaba\nya se la van a llevar.",105,2,-1,107,"Amorcito consentido",0,4,"a",21,0,-1,0,139,139,"3545","",0,"","","",1,0,0,[],""],["frenk_t2-n3546",6,"Mañana por la mañana\nse embarca la vida mía:\n¡mal haya la embarcación\ny el piloto que la guía!",105,2,-1,107,"El curripitf’",3,4,"ia",0,0,-1,0,139,139,"3546","",0,"","","",14,0,0,[],""],["frenk_t2-n3547",6,"Ya se va la embarcación,\nya se va por vía ligera,\nse lleva a mi compañera,\n¡ay!, la dueña de mi amor.",107,2,11,107,"La embarcación",5,4,"o",-1,0,-1,0,139,139,"3547","",0,"","","",1,0,0,[],""],["frenk_t2-n3548",6,"Mi Juanita se embarcó\npara el puerto de San Blas:\n¡adiós, mi Juanita linda!,\n¿hasta cuándo volverás?",114,2,17,107,"El perico loro",0,4,"a",51,0,-1,0,139,139,"3548","",0,"","","",1,0,0,[],""],["frenk_t2-n3549",6,"Detente, maquinista,\nno te lleves a mi amor;\nmira que si te lo llevas,\nqueda herido mi corazón.",118,2,27,107,"La viuda",0,4,"o",-1,0,-1,0,139,139,"3549","",0,"","","",1,0,0,[],""],["frenk_t2-n3550",6,"Una tristeza muy grande\nla que envuelve a mi corazón;\ncamioncito Flecha Roja,\nvuelve pronto con mi amor.",105,2,-1,107,"Camioncito Flecha Roja",0,4,"o",-1,0,-1,0,139,139,"3550","",0,"","","",1,0,0,[],""],["frenk_t2-n3552",6,"Ya no más la polvareda\nle deviso a ese camión;\ncamioncito Flecha Roja,\nvuelve pronto con mi amor.",105,2,-1,107,"Camioncito Flecha Roja",0,4,"o",-1,0,-1,0,139,139,"3552","",0,"","","",1,0,0,[],""],["frenk_t2-n3553a",6,"Yo me subí a un alto pino,\npa ver si la divisaba,\ny sólo devisé el polvo\ndel coche que la llevaba.",107,2,11,107,"La Sanmarqueña",0,4,"aa",28,0,-1,0,140,140,"3553a","",0,"","","",1,0,0,[],""],["frenk_t2-n3554",6,"Espejito compañero,\nmírame qué triste estoy:\nse me fue el hombre que quiero,\ny me muero por su amor.",105,2,-1,107,"Espejito",0,4,"o",-1,0,-1,0,140,140,"3554","",0,"","","",1,0,0,[],""],["frenk_t2-n3555",6,"Allá arriba brama un toro,\ny abajo lo están oyendo;\n¡qué lejos está mi amor,\ny más que se irá poniendo!",105,2,-1,107,"El toro; Estrofa suelta",0,4,"eo",52,0,-1,0,140,140,"3555","",0,"","","",2,0,0,[],""],["frenk_t2-n3556",6,"Cuando salí de Guerrero\nalegre salí cantando:\n“¡ay, costeñita de mi alma,\nqué lejos te vas quedando!”",108,2,8,107,"La Sanmarqueña",0,4,"ao",33,0,-1,0,140,140,"3556","",0,"","","",1,0,0,[],""],["frenk_t2-n3557",6,"¡Qué lejos me considero\nde aquel ángel soberano!\n¡Quién pudiera dar un vuelo\ny darle también la mano\na aquel adorado cielo!",105,2,-1,107,"Estrofa suelta",7,5,"eo",10,0,-1,0,140,140,"3557","",0,"","","",2,0,0,[],""],["frenk_t2-n3558",6,"¡Qué lejos me considero\nde aquel ángel soberano!\nEs que soñé que había muerto\ny esa mujer que yo adoro:\n¡ojalá y que no sea cierto!",112,2,6,107,"El ausente",7,5,"eo",88,0,-1,0,140,140,"3558","",0,"","","",2,0,0,[],""],["frenk_t2-n3559",6,"Por donde quiera que yo ando\nparece que la oigo hablar,\ny hasta el sueño se me quita\nde que me pongo a pensar.",110,2,10,107,"La chata morena",0,4,"a",21,0,-1,0,140,140,"3559","",0,"","","",1,0,0,[],""],["frenk_t2-n3560",6,"Vino el cartero a verme,\nno trajo carta;\nse vistieron de luto\nmis esperanzas.",105,2,-1,107,"Estrofa suelta",6,4,"aa",-1,0,-1,0,140,140,"3560","",0,"","","",1,0,0,[],""],["frenk_t2-n3561",6,"Cada vez que cae la tarde\nganas de llorar me dan;\ncada vez que hago recuerdos,\nmis amores ¿dónde están?",108,2,8,107,"Cada vez que cae la tarde",0,4,"a",147,0,-1,0,141,141,"3561","",0,"","","",4,0,0,[],""],["frenk_t2-n3562",6,"¡Ay, ay, ay, ay!, ¿dónde andarán\nesos ojitos que me hicieron suspirar?\n¡Ay, ay, ay, ay!, ¿dónde estarán\nesos ojitos, que no los puedo olvidar?",105,2,-1,107,"Ojitos verdes",3,4,"a",-1,0,-1,0,141,141,"3562","",0,"","","",1,0,0,[],""],["frenk_t2-n3563",6,"Los sauces de la alameda\nse mecen en el airón;\n¿qué harán mis ojitos negros,\npendientes del corazón?",105,2,-1,107,"Los sauces de la alameda; La palomita**",0,4,"o",31,0,-1,0,141,141,"3563","",0,"","","",2,0,0,[],""],["frenk_t2-n3564",6,"Aquellos ojitos verdes\n¿con quién se andarán paseando?\nOjalá que me recuerden,\naunque sea de vez en cuando.",105,2,-1,107,"Ojitos verdes",0,4,"ao",33,0,-1,0,141,141,"3564","",0,"","","",1,0,0,[],""],["frenk_t2-n3565",6,"Bienvenido, forastero,\nllega pronto a tu guarida:\nque aquí se quedó tu amor\nesperando tu venida.",105,2,-1,107,"Estrofa suelta",0,4,"ia",37,0,-1,0,141,141,"3565","",0,"","","",1,0,0,[],""],["frenk_t2-n3566",6,"Cierro los ojos y miro\nsus ojos resplandecer,\ny en mi plegaria yo pido\nque la vuelva pronto a ver.",105,2,-1,107,"Luto negro",0,4,"e",20,0,-1,0,141,141,"3566","",0,"","","",1,0,0,[],""],["frenk_t2-n3567",6,"Madre mía de Guadalupe,\ndevuélveme a mi querer;\nmira que yo estoy sólito\ny no te puedo ir a ver.",105,2,-1,107,"Estrofa suelta",0,4,"e",20,0,-1,0,141,141,"3567","",0,"","","",4,0,0,[],""],["frenk_t2-n3568",6,"También dejé a mi amorcito,\nque le prometí volver,\npues yo sé que ella me espera,\nque Dios me ha de conceder.",105,2,-1,107,"Mis querencias",0,4,"e",20,0,-1,0,141,141,"3568","",0,"","","",1,0,0,[],""],["frenk_t2-n3569",6,"Yo ya me voy, yo ya me voy,\nporque yo no soy de aquí;\nmis amores son de lejos,\nson de muy lejos de aquí.",105,2,-1,107,"Yo ya me voy",0,4,"i",-1,0,-1,0,141,141,"3569","",0,"","","",1,0,0,[],""],["frenk_t2-n3570",6,"Y vuela, que vuela, vuela,\nvuela, vuela, sin cesar;\nsi se fue para otra tierra,\n¿dónde crees que pueda andar?",108,2,8,107,"La guacamaya",0,4,"a",21,0,-1,0,141,141,"3570","",0,"","","",1,0,0,[],""],["frenk_t2-n3571a",6,"Pavo real, tú que eres correo,\nsi te preguntan qué hago,\npavo real, diles que lloro\nlagrimitas de mis ojos\npor un ángel que yo adoro.",129,2,9,107,"El conejo",7,5,"oo",-1,0,-1,0,142,142,"3571a","",0,"","","",1,0,0,[],""],["frenk_t2-n3571b",6,"Pavo Real, que eres correo\ny que vas a Real del Oro,\nsi te preguntan qué hago,\npavo real, diles que lloro\nlagrimitas de mi sangre\npor una mujer que adoro.",118,2,27,107,"El conejo; Estrofa suelta",9,6,"oo",85,0,-1,0,142,142,"3571b","",0,"","","",1,0,0,[],""],["frenk_t2-n3572",6,"Y águila, levanta el vuelo\ny dile al ángel que adoro\nque en mí no cabe consuelo:\nde día y de noche lloro,\nporque la quise y la quiero.",106,2,4,107,"El pájaro cú",7,5,"eo",-1,0,-1,0,142,142,"3572","",0,"","","",1,0,0,[],""],["frenk_t2-n3573",6,"Lucero de la mañana,\n¡cuánto te diera de albricias\nporque me fueras a traer\nde mi chatita noticias!",105,2,-1,107,"Lucero de la mañana; Palomas que andan volando",0,4,"ia",554,0,-1,0,142,142,"3573","",0,"","","",22,0,0,[],""],["frenk_t2-n3575",6,"Estrellita reluciente,\ndile lo que estoy sufriendo,\ndile que regrese pronto,\nque de amor me estoy muriendo.",105,2,-1,107,"Estrellita reluciente",0,4,"eo",52,0,-1,0,142,142,"3575","",0,"","","",11,0,0,[],""],["frenk_t2-n3576",6,"Madre mía de Guadalupe,\ndile que venga por Dios,\nque no vivo ya sin ella,\nque la vida es de los dos.",105,2,-1,107,"Estrofa suelta",0,4,"o",87,0,-1,0,142,142,"3576","",0,"","","",4,0,0,[],""],["frenk_t2-n3577",6,"Dile que venga aprisa,\nporque me muero,\nque dirá que ya me llevan\nal cementerio.",109,2,7,107,"Pajarillo silguero",6,4,"eo",-1,0,-1,0,142,142,"3577","",0,"","","",1,0,0,[],""],["frenk_t2-n3578",6,"Si la vieres, le dirás\nque no sea ingrata conmigo,\nque el perro en el campo llora\ncuando a su dueño ha perdido.",105,2,-1,107,"Estrofa suelta",0,4,"io",-1,0,-1,0,142,142,"3578","",0,"","","",1,0,0,[],""],["frenk_t2-n3579",6,"Ándale y ándale, que amanece,\ncuando la busco, ya no parece;\nándale y ándale, corre pronto,\nporque no digan que soy tan tonto.",105,2,-1,107,"El tapatío",3,4,"oo",555,0,-1,0,143,143,"3579","",0,"","","",1,0,0,[],""],["frenk_t2-n3581",6,"Estrellita mañanera,\nsi la ves, dile que vuelva,\ny si no quiere volver,\ndéjala, pues, que se vaya;.\n¡qué tonto fui al comprender\nque a mí no más me adoraba!",105,2,-1,107,"Herida de daga",9,6,"aa",-1,0,-1,0,143,143,"3581","",0,"","","",2,0,0,[],""],["frenk_t2-n3582",6,"¡Qué torres tan elevadas,\nque con el aire se mecen!\nAsí está mi corazón\ncuando su amor no aparece.",105,2,-1,108,"Las campanitas",0,4,"ee",-1,0,-1,0,144,144,"3582","",0,"","","",1,0,0,[],""],["frenk_t2-n3583",6,"¡Ay, mal haya el sueño\nque el Señor me da!,\nporque pasó mi chata:\n¿cuándo volverá?",114,2,17,108,"El sueño",0,4,"a",9,0,-1,0,144,144,"3583","",0,"","","",4,0,0,[],""],["frenk_t2-n3584",6,"¡Ay, mal haya el sueño\ncuando me dormí!,\nporque pasó mi chata,\ny yo no la vi.",114,2,17,108,"El sueño",0,4,"i",23,0,-1,0,144,144,"3584","",0,"","","",4,0,0,[],""],["frenk_t2-n3585",6,"¡Ay, mal haya el sueño!,\nbien te lo decía,\nporque pasó mi chata\na las diez del día.",114,2,17,108,"El sueño",0,4,"ia",0,0,-1,0,144,144,"3585","",0,"","","",4,0,0,[],""],["frenk_t2-n3586",6,"¡Ay, mal haya el sueño\nque el Señor me dio!,\nporque pasó mi chata\ny no me dijo adiós.",114,2,17,108,"El sueño",0,4,"o",-1,0,-1,0,144,144,"3586","",0,"","","",4,0,0,[],""],["frenk_t2-n3587",6,"¡Ay, qué airecito tan duro,\nque me tiró hasta el sombrero!\nDime tú donde te escondes\na la mujer que yo quiero.",105,2,-1,108,"La escondida",0,4,"eo",38,0,-1,0,144,144,"3587","",0,"","","",1,0,0,[],""],["frenk_t2-n3588",6,"Tanto pasar y pasar,\ntanto pasar [todo el día];\nlos huaraches se me acaban\nde buscar a mi María.",114,2,17,108,"María, María",0,4,"ia",0,0,-1,0,144,144,"3588","",0,"","","",3,0,0,[],""],["frenk_t2-n3589",6,"Me encuentro sin alegría,\npasando mi vida atroz,\ny busco la vida mía\npa’ vivir juntos los dos,\ny en el nombre de María,\ncomo la madre de Dios.",105,2,-1,108,"La abajeña",9,6,"o",87,0,-1,0,144,144,"3589","",0,"","","",1,0,0,[],""],["frenk_t2-n3591",6,"¡Ay, Soledad, ay, Soledad!,\nSoledad llévame a ver\na la que yo sufro y quiero\ny no me supo querer.",106,2,4,108,"El cascabel",0,4,"e",20,0,-1,0,145,145,"3591","",0,"","","",1,0,0,[],""],["frenk_t2-n3592",6,"Cielo lindo, cielo hermoso,\nmi cielo, ¿dónde estará?\nEstará en los brazos de otro,\ny de mí no se acordará.",108,2,8,108,"Estrofa suelta",0,4,"a",9,0,-1,0,145,145,"3592","",0,"","","",1,0,0,[],""],["frenk_t2-n3593",6,"Hay momentos que quisiera\nmejor quitarme la vida:\n¿con quién se andará paseando\nmi chatita consentida?",105,2,-1,108,"Estrellita reluciente",0,4,"ia",37,0,-1,0,145,145,"3593","",0,"","","",1,0,0,[],""],["frenk_t2-n3595",6,"Limpiándose los ojitos,\nllegó donde estaba yo,\ny le dije: —Lucerito,\n¿qué tu mamá te pegó?\nY me dijo: —No, negrito,\nnada más me regañó.",105,2,-1,108,"El siquisirí; El carpintero",9,6,"o",2,0,-1,0,145,145,"3595","",0,"","","",1,0,0,[],""],["frenk_t2-n3597",6,"Qué bonito corre el agua\ndebajo de las almendras;\nasí corriera mi amor\nsi no hubiera malas lenguas.",108,2,8,108,"Que comienzo, que comienzo; Estrofa suelta",0,4,"ea",-1,0,-1,0,145,145,"3597","",0,"ortiz_ecuador","","",5,0,0,[],""],["frenk_t2-n3598",6,"Qué bonita corre el agua\ndebajo de los sauzales;\nasí corriera mi amor\nsi no fuera por sus males.",105,2,-1,108,"Estrofa suelta",0,4,"ae",26,0,-1,0,145,145,"3598","",0,"","","",1,0,0,[],""],["frenk_t2-n3599",6,"El pedir no es exigir,\ny el dar sí es voluntad;\n¡ay, qué mi suerte tan loca!,\n¿hasta cuándo me cambiará?",105,2,-1,109,"Mal correspondido**",0,4,"a",-1,0,-1,0,146,146,"3599","",0,"","","",1,0,0,[],""],["frenk_t2-n3600",6,"En un verde limonar\nun pajarillo cantó:\ncante quien amores tiene,\nque algún día cantaré yo.",119,2,12,109,"Estrofa suelta",0,4,"o",2,0,-1,0,146,146,"3600","",0,"","","",1,0,0,[],""],["frenk_t2-n3601",6,"Corté una flor en botón,\nque ya mérito se abría,\ny en medio tenía un renglón,\nque clarito me decía:\n“No desmayes, corazón:\nfirme como el primer día.”",105,2,-1,109,"La morena’*, El siquisirí*’; Estrofa suelta",9,6,"ia",0,0,-1,0,146,146,"3601","",0,"","","",1,0,0,[],""],["frenk_t2-n3602",6,"No estés triste, corazón,\nno sientas melancolía,\nque si para ti nació,\ntuyo será algún día.",129,2,9,109,"Estrofa suelta",0,4,"ia",0,0,-1,0,146,146,"3602","",0,"","","",2,0,0,[],""],["frenk_t2-n3603a",6,"Corazón, si sufres, calla,\ndeja de tanto llorar,\ny déjala que se vaya,\nque algún día volverá,\npor mal o bien que le vaya.",105,2,-1,109,"La Rosita",7,5,"aa",-1,0,-1,0,146,146,"3603a","",0,"","","",1,0,0,[],""],["frenk_t2-n3604",6,"En la mañana\ncuando el sol despierta\nrevive en mi alma\nla esperanza muerta.",105,2,-1,109,"Y en la mañana",6,4,"ea",267,0,-1,0,146,146,"3604","",0,"","","",1,0,0,[],""],["frenk_t2-n3605",6,"Con el tiempo y un ganchito\nhasta las verdes se alcanzan,\ny si Dios me da permiso,\nno pierdo las esperanzas.",113,2,2,109,"El gavilán",0,4,"aa",-1,0,-1,0,147,147,"3605","",0,"","","",1,0,0,[],""],["frenk_t2-n3606a",6,"—¿Mariquita estaba aquí?\n—Eso sí yo no lo sé.\n—¡Ah, qué diantre de María,\ncómo me hace padecer!",105,2,-1,109,"¡Ay, qué diantre de María!",0,4,"e",-1,0,-1,0,147,147,"3606a","",0,"","","",1,0,0,[],""],["frenk_t2-n3607",6,"Aquellos ojos verdes\nya no me quieren mirar;\npor ellos todas las tardes\nme pongo triste a llorar.",105,2,-1,109,"Por unos ojitos verdes",0,4,"a",21,0,-1,0,147,147,"3607","",0,"","","",1,0,0,[],""],["frenk_t2-n3608",6,"—¿Qué te ha dado esa mujer,\nque te tiene tan engreído (querido amigo)?\n—Yo no sé lo que me ha dado;\ncuando yo la veo venir,\nse agacha y se va de lado (querido amigo):\nvalía más mejor morir.",105,2,-1,109,"¿Qué te ha dado esa mujer... ?",9,6,"i",157,0,-1,0,147,147,"3608","",0,"","","",1,0,0,[],""],["frenk_t2-n3609",6,"¡Ay!, chivarras coloradas,\nlas que usan los rancheritos;\n¡qué mi amor tan pretencioso!\nNo más me ve lejitos.",105,2,-1,109,"Las chivarras",0,4,"io",254,0,-1,0,147,147,"3609","",0,"","","",3,0,0,[],""],["frenk_t2-n3610",6,"Al pie de una celosía\npartí mi amor con un hacha;\nla mujer que yo tenía\nno más me mira y se agacha:\nparece que no fue mía.",113,2,2,109,"El triunfo",7,5,"ia",0,0,-1,0,147,147,"3610","",0,"","","",2,0,0,[],""],["frenk_t2-n3611",6,"En un corredor azul\nveo a mi amor que retacha;\nel canijo que a mí me quiere\napenas me ve, se agacha.",109,2,7,109,"Estrofa suelta",0,4,"aa",556,0,-1,0,147,147,"3611","",0,"","","",1,0,0,[],""],["frenk_t2-n3612a",6,"De las estrellas del cielo\ntoditas tienen su nombre,\nno sé qué tiene mi amor,\nque le hablo, y no me responde.",108,2,8,109,"Estrofa suelta",0,4,"oe",-1,0,-1,0,147,147,"3612a","",0,"","","",7,0,0,[],""],["frenk_t2-n3613",6,"Anoche soñé tres veces\na la dueña de mi amor;\náhi me dijo: “No me beses,\nporque me queda el sabor:\ncúmpleme lo que me ofreces\na[l] pie del altar mayor.”",112,2,6,109,"La azucena; La Huazanga",9,6,"o",72,0,-1,0,148,148,"3613","",0,"","","",1,0,0,[],""],["frenk_t2-n3614",6,"Pajarito lagunero\nde la laguna del bosque,\nanda, dile a mi lucero\nque si ya no me conoce,\nque yo fui su amor primero.",105,2,-1,109,"El pájaro cú; El pájaro carp",7,5,"eo",38,0,-1,0,148,148,"3614","",0,"","","",1,0,0,[],""],["frenk_t2-n3615",6,"Allá va mi corazón\nsobre una viga nadando.\n¿te harán alguna traición,\no te andarán descolgando?",105,2,-1,109,"Las olas de la laguna",1,4,"ao",33,0,-1,0,148,148,"3615","",0,"","","",4,0,0,[],""],["frenk_t2-n3616",6,"Dicen que los celos matan,\npero yo digo que no,\nque si los celos mataran,\nya me hubiera muerto yo.",115,2,3,109,"El cariño El gusto",0,4,"o",2,0,-1,0,148,148,"3616","",0,"","","",6,0,0,[],""],["frenk_t2-n3617",6,"Parece que sí,\nparece que no;\nestos son los celos\nque conozco yo.",110,2,10,109,"El Jerez",0,4,"o",2,0,-1,0,148,148,"3617","",0,"","","",1,0,0,[],""],["frenk_t2-n3618",6,"Mi chatita anda de luto\nsin haberme muerto yo;\n¡mal haya el vestido negro,\nmal haya quien se murió!",107,2,11,109,"El pescado nadador",0,4,"o",2,0,-1,0,148,148,"3618","",0,"","","",1,0,0,[],""],["frenk_t2-n3619",6,"Ese vestidito negro\ndime quién te lo compró;\nanda de luto mi chata\nsin haberme muerto yo.",105,2,-1,109,"La carta que te mandé",0,4,"o",2,0,-1,0,148,148,"3619","",0,"","","",1,0,0,[],""],["frenk_t2-n3620",6,"A los tres días de casado\nyo le dije a mi mujer:\n“No platiques con los hombres,\nque al cabo lo he de saber.”",115,2,3,109,"El celoso",0,4,"e",20,0,-1,0,149,149,"3620","",0,"","","",3,0,0,[],""],["frenk_t2-n3621",6,"Siempre que la voy a ver\nnunca la puedo encontrar;\nsiempre que la voy a ver\ncon pachucos ha de estar.",105,2,-1,109,"¡Ay, qué diantre de María!",1,4,"a",21,0,-1,0,149,149,"3621","",0,"","","",1,0,0,[],""],["frenk_t2-n3622",6,"—¿Para dónde fue María?\n—Eso sí yo no lo sé.\n—Siempre que la voy a ver\ncon pachucos ha de estar.",105,2,-1,109,"¡Ay, qué diantre de María!",5,4,"a",-1,0,-1,0,149,149,"3622","",0,"","","",1,0,0,[],""],["frenk_t2-n3623",6,"Mi Juanita es una ingrata,\nque yo no puedo olvidar,\nque no más cuando ve plata\nle gusta el vacilar.",105,2,-1,109,"La Juanita",1,4,"a",21,0,-1,0,149,149,"3623","",0,"","","",1,0,0,[],""],["frenk_t2-n3624",6,"¡Pobrecita de la palma,\ncon el sol se marchitó!\nAsí se marchita mi alma\ncuando le dicen que no.",108,2,8,103,"Estrofa suelta, La palma; Que comienzo, que comienzo; San Francisco; Válgame Dios de los cielos",1,4,"o",2,0,-1,0,150,150,"3624","",0,"","","",2,0,0,[],""],["frenk_t2-n3625",6,"¡Ay, qué triste está la palma\na orillas de una laguna!\nAsí se ha quedado mi alma,\nsin esperanza ninguna.",105,2,-1,103,"La palma",1,4,"ua",56,0,-1,0,150,150,"3625","",0,"","","",1,0,0,[],""],["frenk_t2-n3626",6,"Ya me voy para mi casa,\nvoy a hacer el café,\nporque esperanzas de la señora\nhay que perder la fe.",129,2,9,103,"Estrofa suelta",3,4,"e",77,0,-1,0,150,150,"3626","",0,"","","",3,0,0,[],""],["frenk_t2-n3627",6,"Eso sí será dolor,\nde querer y no ¡poder:\nteniendo el agua en la boca\ny no poderla beber.",108,2,8,103,"Estrofa suelta",0,4,"e",20,0,-1,0,150,150,"3627","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t2-n3628",6,"En el patio de San Luis\nestá un becerro jugando;\n¡ah qué corazón tan duro\ntiene la que estoy amando!",108,2,8,103,"Que comienzo, que comienzo",0,4,"ao",33,0,-1,0,150,150,"3628","",0,"","","",1,0,0,[],""],["frenk_t2-n3629",6,"Ella me dijo que sería mía\ncuando florearan los arrayanes,\ny ya florearon todas las flores,\ny no han floreado los arrayanes.",105,2,-1,103,"Los arrayanes",3,4,"ae",-1,0,-1,0,150,150,"3629","",0,"","","",1,0,0,[],""],["frenk_t2-n3630",6,"Yo por Loreto me muero\ny tras de Loreto me ando;\ny aunque no le hablo, la quiero,\nmas que ella me quiera, ¡cuándo!",105,2,-1,103,"Estrofa suelta",1,4,"ao",33,0,-1,0,150,150,"3630","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n3631",6,"Le dije una tarde al sol:\n—¿Por qué estás tan colorado?\n—De mirarla tan ingrata,\ny a ti tan enamorado.",105,2,-1,103,"Las mañanitas",0,4,"ao",14,0,-1,0,151,151,"3631","",0,"","","",1,0,0,[],""],["frenk_t2-n3632",6,"¡Ay, sí, ay, no, ay, sí,\nqué risa me da!\n¿Por qué, por qué, por qué,\nno me quieren ya?",105,2,-1,103,"Cielito lindo",6,4,"a",9,0,-1,0,151,151,"3632","",0,"","","",1,0,0,[],""],["frenk_t2-n3633",6,"Ayer tarde todavía\ntuve la dicha de verla;\n¡ah, qué ingrata suerte mía,\nque no pude convencerla!",112,2,6,103,"La Rosita",1,4,"ea",428,0,-1,0,151,151,"3633","",0,"","","",1,0,0,[],""],["frenk_t2-n3634",6,"Allá en el abismo hondo,\nallá ende la calzada,\nhablamos varios asuntos\ny no quedamos en nada.",108,2,8,103,"La morena",0,4,"aa",49,0,-1,0,151,151,"3634","",0,"","","",1,0,0,[],""],["frenk_t2-n3635",6,"Mucho quiero a mi María,\n¡cómo es linda esa mujer!\nMucho quiero a mi María:\nnunca la puedo tener.",105,2,-1,103,"¡Ay!, qué diantre de María",1,4,"e",20,0,-1,0,151,151,"3635","",0,"","","",1,0,0,[],""],["frenk_t2-n3636",6,"Ya sé lo que relumbra\nen lo profundo del mar:\nson los ojos de mi nena,\nque no me pueden amar.",108,2,8,103,"Estrofa suelta",0,4,"a",21,0,-1,0,151,151,"3636","",0,"","","",1,0,0,[],""],["frenk_t2-n3637",6,"Le pido a mi Dios paciencia,\npaciencia para sufrir:\nsin esos ojitos verdes\nyo no podré ser feliz.",105,2,-1,103,"Por unos ojitos verdes",0,4,"i",-1,0,-1,0,151,151,"3637","",0,"","","",1,0,0,[],""],["frenk_t2-n3638",6,"Rema, nanita, rema,\ny rema, y vamos remando;\nque la dicha que tú tienes\na mí se me está acabando.",105,2,-1,103,"Canción de Morelos",0,4,"ao",33,0,-1,0,151,151,"3638","",0,"","","",2,0,0,[],""],["frenk_t2-n3639",6,"Ya se acabó mi recreo\ndel frondoso abril y mayo.\nYo con gusto me paseo,\nno más miro su pitayó,\npero a nadie le deseo\nque se halle como yo me hallo.",105,2,-1,103,"El gusto",9,6,"ao",2,0,-1,0,151,151,"3639","",0,"","","",1,0,0,[],""],["frenk_t2-n3640",6,"Me subí a la alta higuera\na cortar higo por higo;\ncomo la rama está verde,\nse fue la rama conmigo.",106,2,4,103,"Estrofa suelta",0,4,"io",106,0,-1,0,152,152,"3640","",0,"","","",2,0,0,[],""],["frenk_t2-n3641",6,"En la rama de un olivo\npuse un remo, puse dos,\nvino el fuerte remolino,\nremo de amor se llevó.",105,2,-1,103,"La víbora",0,4,"o",-1,0,-1,0,152,152,"3641","",0,"","","",3,0,0,[],""],["frenk_t2-n3642",6,"Ya no subo yo al cerrito\ncon el gusto que subía,\npues se secó la rosita\nque me daba la alegría.",116,2,15,103,"Cuatro esquinas tiene un catre; Ya no subo a la lomita",0,4,"ia",-1,0,-1,0,152,152,"3642","",0,"","","",1,0,0,[],""],["frenk_t2-n3643",6,"Vi marchitarse una flor\nporque le faltó el rocío;\nperdió todo su color,\nle quedó el cáliz vacío\ny el corazón sin valor,\ncomo se ha quedado el mío.",105,2,-1,103,"La morena; El siquisirí; Estrofa suelta",9,6,"io",3,0,-1,0,152,152,"3643","",0,"","","",2,0,0,[],""],["frenk_t2-n3645",6,"¡Ay, capire de mi vida!,\n¿cuándo reverdecerás?\nYa se fue quien te regaba:\nagora te secarás.",109,2,7,103,"El capire",0,4,"a",51,0,-1,0,152,152,"3645","",0,"","","",1,0,0,[],""],["frenk_t2-n3646",6,"¡Ay de mí, Llorona!,\nLlorona, que sí, que no;\nla luz que me alumbraba (¡Ay, Llorona!)\nen tinieblas me dejó.",108,2,8,103,"La Llorona",3,4,"o",2,0,-1,0,152,152,"3646","",0,"","","",35,0,0,[],""],["frenk_t2-n3647",6,"Pajarillo, pajarillo,\nmi amor, mi dicha y mi anhelo\nya se fueron, ya volaron\npara las cumbres del cielo.",105,2,-1,103,"Estrofa suelta, Pajarillo barranqueño",0,4,"eo",10,0,-1,0,152,152,"3647","",0,"","","",9,0,0,[],""],["frenk_t2-n3648",6,"De luto mi amor se viste\ny se le apaga la voz,\npues su cariño no existe:\nya sólo me queda Dios.",105,2,-1,103,"Luto negro",1,4,"o",87,0,-1,0,152,152,"3648","",0,"","","",1,0,0,[],""],["frenk_t2-n3649",6,"Luto negro, que me agobia\ny me mata de pesar,\nporque ya no tengo novia,\ny no la puedo olvidar.",105,2,-1,103,"Luto negro",1,4,"a",21,0,-1,0,153,153,"3649","",0,"","","",1,0,0,[],""],["frenk_t2-n3650",6,"¡Alza, Lázaro Patricio!,\ntu sombrero va volando;\npor el aire va diciendo\nque tu amor se está acabando.",105,2,-1,103,"El pollo",0,4,"ao",33,0,-1,0,153,153,"3650","",0,"","","",2,0,0,[],""],["frenk_t2-n3651",6,"¡Alza, Lázaro Patricio!,\ntu sombrero ya voló;\npor el aire va diciendo\nque tu amor ya se acabó.",105,2,-1,103,"El pollo",0,4,"o",2,0,-1,0,153,153,"3651","",0,"","","",2,0,0,[],""],["frenk_t2-n3652",6,"Amor como el que perdí\nno lo volveré a encontrar;\nes mucho lo que la quiero:\n¡pos cuándo la he de olvidar!",114,2,17,103,"La chaparrita",0,4,"a",21,0,-1,0,153,153,"3652","",0,"","","",2,0,0,[],""],["frenk_t2-n3653",6,"Amor como el que hoy perdí\nno lo volveré a encontrar;\náhi vendrá cuando ellas quieran\no el tiempo les dé lugar.",105,2,-1,103,"La chaparrita",0,4,"a",21,0,-1,0,153,153,"3653","",0,"","","",1,0,0,[],""],["frenk_t2-n3654",6,"Ahora estoy abandonado,\nme acompaña a mí el dolor,\nporque se murió de celo,\nme destrozó el corazón.",114,2,17,103,"El perico loro",0,4,"o",-1,0,-1,0,153,153,"3654","",0,"","","",1,0,0,[],""],["frenk_t2-n3655",6,"Ya no me importa la milpa\nni lo que dé el frijolar,\nsi al cabo sólo me quedan\nen aquel pobre jacal\nmi perro, que triste llora,\nechado junto al comal.",105,2,-1,103,"La tortolita",9,6,"a",1,0,-1,0,153,153,"3655","",0,"","","",1,0,0,[],""],["frenk_t2-n3656",6,"Oye, pájaro gorrión,\nyo te quisiera decir:\n¿cuánto vale una traición?,\nque no la puedo sufrir.",108,2,8,103,"La calandria",1,4,"i",157,0,-1,0,153,153,"3656","",0,"","","",1,0,0,[],""],["frenk_t2-n3658",6,"A llorar, Llorona,\na llorar, llorar;\nla causa de mi llanto,\nuna hembra que no sabe amar,\ny por eso lloro tanto.",106,2,4,103,"La Lloroncita",7,5,"ao",30,0,-1,0,154,154,"3658","",0,"","","",1,0,0,[],""],["frenk_t2-n3659",6,"Valía más no haber nacido,\npara no sentir ni ver,\nporque triste [es] conocer\nla ilusión de una mujer\ny no ser correspondido.",113,2,2,103,"Estrofa suelta",7,5,"io",101,0,-1,0,154,154,"3659","",0,"","","",1,0,0,[],""],["frenk_t2-n3660",6,"Al mismo Dios desafío\nque me presente otro ser,\npues ya no quiero tener\nla ilusión de esa mujer,\nque es la que me trae perdido.",113,2,2,103,"Estrofa suelta",7,5,"io",-1,0,-1,0,154,154,"3660","",0,"","","",2,0,0,[],""],["frenk_t2-n3661",6,"En un pozo muy profundo\nde amores me andaba hundiendo;\nyo solito me confundo\npor una ingrata en el mundo.",113,2,2,103,"Estrofa suelta",5,4,"uo",179,0,-1,0,154,154,"3661","",0,"","","",5,0,0,[],""],["frenk_t2-n3662",6,"En un pozo muy profundo\nde amores me andaba ahogando;\ny yo solo me confundo\nde ver lo que ando pasando\npor una ingrata del mundo\nque por ella ando penando.",112,2,6,103,"El caimán; Estrofa suelta",9,6,"ao",33,0,-1,0,154,154,"3662","",0,"","","",5,0,0,[],""],["frenk_t2-n3663",6,"Yo vide florear un coco\ny un tamarindo morado.\n¡Mal haya mi amor tan poco\ny tan bien desquerenciado!\nA lo que me vuelvo loco\npor una del otro lado.",112,2,6,103,"Las flores",9,6,"ao",14,0,-1,0,154,154,"3663","",0,"","","",1,0,0,[],""],["frenk_t2-n3664",6,"—Corazón sólido, ¿por qué estás triste?,\n¿qué te remedias con tanto llorar?\n—Pues esa joven que me echó en olvido\nes imposible dejarla de amar.",120,2,14,103,"Corazón sólido",3,4,"a",21,0,-1,0,154,154,"3664","",0,"","","",1,0,0,[],""],["frenk_t2-n3665",6,"Eres flor que entre peñas naciste,\ny naciste para padecer;\nyo primero conocí a mis padres\ny después a una ingrata mujer.",115,2,3,103,"Qué te falta, mujer",3,4,"e",20,0,-1,0,154,154,"3665","",0,"","","",2,0,0,[],""],["frenk_t2-n3666",6,"Virgen santa, yo soy desgraciado,\npor haber adorado a una ingrata:\nmás valiera nunca haber amado:\n¡ay, feliz fuera yo sin amar!",105,2,-1,103,"Desgraciado yo soy, Virgen santa*’",3,4,"a",-1,0,-1,0,155,155,"3666","",0,"","","",1,0,0,[],""],["frenk_t2-n3667",6,"Al pie de un árbol lloré\nhasta que me dio la gana,\nporque pretendo amar\na una mujer ingrata.",115,2,3,103,"El pie de un árbol’’",0,4,"aa",-1,0,-1,0,155,155,"3667","",0,"","","",2,0,0,[],""],["frenk_t2-n3668",6,"—¿Qué tienes, ángel divino,\nque no suspendes tu llanto?\n—¿Qué he de tener, si un desprecio\nme tiene en tanto quebranto?",105,2,-1,103,"Estrofa suelta",0,4,"ao",30,0,-1,0,155,155,"3668","",0,"","","",1,0,0,[],""],["frenk_t2-n3669",6,"En los llanos de Abadejo\ncantaban los horizontes.\nComo de amores padezco,\nde desprecio traigo un...\nNunca falta un mal cabresto,\nque echa la partida al monte.",106,2,4,103,"La guacamaya",9,6,"oe",-1,0,-1,0,155,155,"3669","",0,"","","",1,0,0,[],""],["frenk_t2-n3670b",6,"Debajo de un limón verde\ncorre el agua y no se enfría.\nYo le di mi corazón\na quien no lo merecía,\npor eso no es bueno fiarse\nde los hombres de hoy en día.",105,2,-1,103,"Estrofa suelta",9,6,"ia",0,0,-1,0,155,155,"3670b","",0,"","","",9,0,0,[],""],["frenk_t2-n3671",6,"Yo sembré una yerbabuena\ndonde el agua no corría;\nyo le di mi amor primero\na quien no lo merecía.",107,2,11,103,"La Sanmarqueña**",0,4,"ia",0,0,-1,0,155,155,"3671","",0,"","","",2,0,0,[],""],["frenk_t2-n3672",6,"¡Mal haya el amor, mal haya\nel quien del amor se rí[a]!\nUna vez le di mi amor\na quien no lo merecía.",108,2,8,103,"La guacamaya",5,4,"ia",-1,0,-1,0,155,155,"3672","",0,"","","",7,0,0,[],""],["frenk_t2-n3673",6,"Dicen que los de Jalisco\nno nos sabemos rajar,\npero es tanto lo que me hizo,\nque, aunque soy hombre macizo,\nya no aguanto mi penar.",105,2,-1,103,"Virgencita de Zapopan",7,5,"a",21,0,-1,0,155,155,"3673","",0,"","","",1,0,0,[],""],["frenk_t2-n3674",6,"Ya no llores, corazón,\ndeja de tanto llorar,\nque esta alma ya la perdiste\npor no saber barajar:\nporque en un tiempo quisiste\ncon dos barajas jugar.",111,2,1,103,"Estrofa suelta",9,6,"a",21,0,-1,0,155,155,"3674","",0,"","","",1,0,0,[],""],["frenk_t2-n3675",6,"Corazón apasionado,\ndisimula tu tristeza:\n¡quién te manda a ser brujeado\ndonde no hay correspondencia!\nCorazón, paciencia ten,\ntú quisistes, fue tu gusto.",108,2,8,103,"Estrofa suelta",9,6,"uo",-1,0,-1,0,156,156,"3675","",0,"","","",3,0,0,[],""],["frenk_t2-n3676",6,"Estoy sentido de un desdén,\nme puede costar la vida;\nlas malas correspondencias\nme han dado una fuerte herida;\ncorazón, tenme paciencia:\nDios tarda, pero nunca olvida.",108,2,8,103,"Estrofa suelta",9,6,"ia",37,0,-1,0,156,156,"3676","",0,"","","",1,0,0,[],""],["frenk_t2-n3677",6,"Paloma blanca, me llevas\nal Cerro del Cubilete,\na rezar una novena\npor si me brinca la muerte;\npor culpa de esa morena\nvoy a rifarme mi suerte.",105,2,-1,103,"El valedor",9,6,"ee",134,0,-1,0,156,156,"3677","",0,"","","",1,0,0,[],""],["frenk_t2-n3678",6,"Ya se reventó el alambre\ndonde se mecía Cupido.\nNo vengo porque tengo hambre,\nsólo porque estoy herido;\nvengo a ver correr mi sangre\ndonde estoy comprometido.",114,2,17,103,"Eres alta y delgadita",9,6,"io",101,0,-1,0,156,156,"3678","",0,"","","",2,0,0,[],""],["frenk_t2-n3679",6,"¡Ábranse, que vengo herido,\nno los vaya a salpicar!\nPor culpa de una morena\nme pegaron de verdad.",105,2,-1,103,"Ábranse que vengo herido",0,4,"a",-1,0,-1,0,156,156,"3679","",0,"","","",1,0,0,[],""],["frenk_t2-n3680",6,"Vaya con Dios quien fue causa\nde mi cruel padecimiento;\npero me juzgo sin mancha:\nlo que han dicho no es cierto;\nyo no trato con venganza,\npero me da sentimiento.",108,2,8,103,"Estrofa suelta",9,6,"eo",-1,0,-1,0,156,156,"3680","",0,"","","",1,0,0,[],""],["frenk_t2-n3681",6,"Una rosa de Castilla\nse me deshizo lloviendo.\nVaya con Dios el amor,\nque nada me fue debiendo;\nlo que sí me da dolor\nque de mí se vaya riendo.",108,2,8,103,"Estrofa suelta",9,6,"eo",52,0,-1,0,156,156,"3681","",0,"","","",3,0,0,[],""],["frenk_t2-n3682",6,"Ya me voy de mi Jalisco\npor culpa de una mujer;\ntú sabrás lo que me hizo:\naunque sé que ella me quiso,\nno se puede resolver.",105,2,-1,103,"‘‘Virgencita de Zapopan",7,5,"e",20,0,-1,0,156,156,"3682","",0,"","","",1,0,0,[],""],["frenk_t2-n3683",6,"Soy huasteco, sí, señores,\nhoy acabo de llegar,\npor una linda morena\nque sus amores no me quiere dar.",113,2,2,103,"Estrofa suelta",3,4,"a",21,0,-1,0,157,157,"3683","",0,"","","",1,0,0,[],""],["frenk_t2-n3684",6,"Ya me despido de mi morena,\nya me despido del corazón,\npa que se digan de las mujeres\nque en esta vida juegan traición.",108,2,8,103,"Las gaviotas",3,4,"o",31,0,-1,0,157,157,"3684","",0,"","","",1,0,0,[],""],["frenk_t2-n3685",6,"A las islas más profundas\nque la mar tenga me iré,\npor no ver enajenada\nprenda que tanto estimé.",114,2,17,103,"Estrofa suelta",0,4,"e",77,0,-1,0,157,157,"3685","",0,"","","",1,0,0,[],""],["frenk_t2-n3686",6,"Por una mala mujer\nando yo en la perdición;\nllevo perdida la fe,\nno sé ni quién fui ni quién soy.",105,2,-1,103,"Mala mujer",0,4,"o",-1,0,-1,0,157,157,"3686","",0,"","","",2,0,0,[],""],["frenk_t2-n3687",6,"Voy a tirarme a los vicios,\nvoy a echarme a la desgracia;\npor esa mujer querida\nanda mi amor delirando,\npues ella tiene la culpa\nque yo me ande emborrachando.",105,2,-1,103,"Voy a tirarme a los vicios",9,6,"ao",33,0,-1,0,157,157,"3687","",0,"","","",1,0,0,[],""],["frenk_t2-n3688",6,"Pa mí ya todo acabó,\nnada me queda en la vida,\nmi consuelo es el tequila\npor una mala mujer.",105,2,-1,103,"Mala mujer",5,4,"e",-1,0,-1,0,157,157,"3688","",0,"","","",1,0,0,[],""],["frenk_t2-n3689",6,"Me voy a tomar, me voy a beber\ntres copas de sentimiento,\npara no pensar y para olvidar\na la que fue mi tormento.",105,2,-1,103,"La rogona",3,4,"eo",94,0,-1,0,157,157,"3689","",0,"","","",1,0,0,[],""],["frenk_t2-n3690",6,"Ando ausente del bien que adoré\ny apasionado por una mujer;\nsólo tomando disipo mis penas,\ncon las copas llenas para divagar.",105,2,-1,103,"La mancomadora",3,4,"a",-1,0,-1,0,157,157,"3690","",0,"","","",1,0,0,[],""],["frenk_t2-n3691",6,"¡Qué corazón tan alegre,\nahora que me ando paseando,\ndándole todito el ancho!\nPor una joven que yo amo\npaso la vida borracho.",125,2,28,103,"Qué corazón tan alegre",7,5,"ao",-1,0,-1,0,157,157,"3691","",0,"","","",1,0,0,[],""],["frenk_t2-n3692",6,"¡Ay, ay, ay, qué lindo es el vino\ncuando se bebe para olvidar!\n¡Ay, ay, ay!, que si me emborracho\nes para olvidar, sí, para olvidar\nla pasión de una mujer.",114,2,17,103,"¡Ay, qué bonito es amar!",7,5,"e",-1,0,-1,0,158,158,"3692","",0,"","","",1,0,0,[],""],["frenk_t2-n3693",6,"Este pobre enamorado\nnecesita de licor,\nporque le han enajenado\nlos encantos del amor.",105,2,-1,103,"Los papaquis",1,4,"o",72,0,-1,0,158,158,"3693","",0,"","","",1,0,0,[],""],["frenk_t2-n3694",6,"Yo no sé por qué las güeras\nsiempre me huelen a poleo;\nsi esta noche no la viera,\ntoda me la parrandeo.",105,2,-1,103,"Con un polvo y otro polvo",0,4,"eo",66,0,-1,0,158,158,"3694","",0,"","","",1,0,0,[],""],["frenk_t2-n3695",6,"Bebamos, bebamos\neste buen licor,\nque es bebida buena\npara el amor.",105,2,-1,103,"La botella",6,4,"o",72,0,-1,0,158,158,"3695","",0,"","","",1,0,0,[],""],["frenk_t2-n3696",6,"Vamos, pues, sin sentimiento\nel elixir a apurar;\nolvidemos las mujeres\ny los sueños del amor.",105,2,-1,103,"El chúmbale",5,4,"o",-1,0,-1,0,158,158,"3696","",0,"","","",1,0,0,[],""],["frenk_t2-n3697",6,"Esta china era una hermosa\ncuando la empecé a querer;\nahora se muestra orgullosa\nporque tiene a quien querer.",105,2,-1,103,"Estrofa suelta",1,4,"e",-1,0,-1,0,158,158,"3697","",0,"","","",1,0,0,[],""],["frenk_t2-n3698c",6,"El marinero me dijo:\n“A tu amor no lo verás,\nporque se halla entretenido\ncon otro que quere más.”",109,2,7,103,"Los caracoles",0,4,"a",51,0,-1,0,158,158,"3698c","",0,"","","",1,0,0,[],""],["frenk_t2-n3699",6,"¿De qué te sirve llorar\ny dar vueltas como loco,\nsi tú te mueres por ella,\ny ella se muere por otro?",107,2,11,103,"Estrofa suelta",0,4,"oo",-1,0,-1,0,159,159,"3699","",0,"","","",6,0,0,[],""],["frenk_t2-n3700",6,"¡Ay, Zandunga!,\nZandunga de mis amores;\nla muchacha que más quiero\nes dueña de otros amores.",108,2,8,103,"La Zandunga",3,4,"oe",-1,0,-1,0,159,159,"3700","",0,"","","",3,0,0,[],""],["frenk_t2-n3701",6,"Desgraciado yo soy, Virgen santa,\nporque no me encomiendo en mis cuitas;\nya mi amada me deja por otro:\nVirgen santa, dame resignación.",105,2,-1,103,"Desgraciado yo soy, Virgen santa",3,4,"o",-1,0,-1,0,159,159,"3701","",0,"","","",1,0,0,[],""],["frenk_t2-n3702",6,"Se oye el murmullo\nde una mañana tristona,\nse escuchan nuevos arrullos\nde mi perdida paloma.",109,2,7,103,"Estrofa suelta",3,4,"oa",-1,0,-1,0,159,159,"3702","",0,"","","",1,0,0,[],""],["frenk_t2-n3703",6,"¡Ay, triste de mí!, ¿qué haré?\nVístase el campo de luto:\nque yo para mí sembré,\ny otro dueño goza el fruto.",108,2,8,103,"Estrofa suelta",1,4,"uo",327,0,-1,0,159,159,"3703","",0,"","","",1,0,0,[],""],["frenk_t2-n3704",6,"Vengo de la Huasteca,\ntraigo en el alma una decepción:\nse va a casar mi chata\ncon el teniente de guarnición.",105,2,-1,103,"Lamento huasteco",3,4,"o",31,0,-1,0,159,159,"3704","",0,"","","",1,0,0,[],""],["frenk_t2-n3706",6,"Cupido con su vihuela\nme cantó un canto de amor.\nYo no siento la cautela,\nlo que siento es el dolor\nde ver que cambien canela\npor cáscara sin olor.",106,2,4,103,"El Cupido",9,6,"o",72,0,-1,0,159,159,"3706","",0,"","","",3,0,0,[],""],["frenk_t2-n3707",6,"Estrellita mañanera,\nque brillas durante el alba,\ndime qué rumbo tomó\nla ingrata dueña de mi alma;\naunque de mí se burló,\ntodavía quiero encontrarla.",105,2,-1,103,"Herida de daga",9,6,"aa",-1,0,-1,0,159,159,"3707","",0,"","","",2,0,0,[],""],["frenk_t2-n3709",6,"No seas loco, corazón,\nen querer lo que es ajeno,\nporque al fin te has de quedar\nsin luz, sin vida y sin dueño.",105,2,-1,110,"Estrofa suelta",0,4,"eo",-1,0,-1,0,160,160,"3709","",0,"","","",2,0,0,[],""],["frenk_t2-n3710",6,"Por una loca pasión,\npor un sentimiento necio,\nse ha visto mi corazón\nen brazos de un desprecio.\n¡Mira lo que hace el amor!\nCorazón, no seas tan necio.",108,2,8,110,"Estrofa suelta",9,6,"eo",276,0,-1,0,160,160,"3710","",0,"","","",1,0,0,[],""],["frenk_t2-n3711",6,"Yo no quiero más sufrir (¡ay!, Llorona),\nandar en dos corazones:\nuna ocasión lo sentí,\nlo siento en dos ocasiones.",108,2,8,110,"La Llorona",3,4,"oe",34,0,-1,0,160,160,"3711","",0,"","","",1,0,0,[],""],["frenk_t2-n3712",6,"Soy pájaro cardenal,\nque en las montañas anido;\nel pico pongo en la flor\ny al centro doy un volido,\na buscarme otra mujer\nque no sea ingrata conmigo.",112,2,6,110,"Estrofa suelta",9,6,"io",-1,0,-1,0,160,160,"3712","",0,"","","",1,0,0,[],""],["frenk_t2-n3713",6,"Pronto voy a separarme\nde la joven que yo amé;\naunque sienta lastimarme,\na verla no volveré,\nporque nunca he de humillarme.",111,2,1,110,"Estrofa suelta",7,5,"ae",35,0,-1,0,160,160,"3713","",0,"","","",1,0,0,[],""],["frenk_t2-n3714",6,"Corazón, ¿por qué estás triste?\nLa ausencia todo lo borra:\nhallarás quien te socorra\nmejor que lo que perdiste.",105,2,-1,110,"Estrofa suelta",11,4,"ie",153,0,-1,0,161,161,"3714","",0,"","","",3,0,0,[],""],["frenk_t2-n3715",6,"No estés triste, corazón,\nno llores tu mala suerte,\nque el pájaro que te canta\nno es pájaro que divierte.",105,2,-1,110,"No estés triste corazón; Estrofa suelta",0,4,"ee",134,0,-1,0,161,161,"3715","",0,"","","",2,0,0,[],""],["frenk_t2-n3716",6,"Ya no cantes, jilguerillo,\nni me estés atormentando:\nya lo que pasó voló,\ny ahora te estás acordando.",115,2,3,110,"Mariquita; Estrofa suelta",3,4,"ao",33,0,-1,0,161,161,"3716","",0,"","","",1,0,0,[],""],["frenk_t2-n3717",6,"No te aflijas, corazón,\nni tengas penas por eso,\ndéjalos, que al cabo son\nplátanos del mismo tercio.",105,2,-1,110,"Estrofa suelta",0,4,"eo",-1,0,-1,0,161,161,"3717","",0,"","","",4,0,0,[],""],["frenk_t2-n3718",6,"No suspires, corazón,\nno te dé melancolía,\nque si mal palo te dieron,\ntú lo darás algún día.",108,2,8,110,"Estrofa suelta",0,4,"ia",0,0,-1,0,161,161,"3718","",0,"","","",1,0,0,[],""],["frenk_t2-n3719",6,"Me metí a sacar la perla\nde lo más hondo del mar,\nporque quería conocerla (ay, vida mía),\npero no la pude hallar,\ny me regresé sin verla.",105,2,-1,105,"El pájaro carpintero",7,5,"ea",428,0,-1,0,162,162,"3719","",0,"","","",1,0,0,[],""],["frenk_t2-n3720",6,"Como tú, mi flor silvestre,\ntuve en la sierra un amor;\nnunca supo de la suerte\ny sí mucho del dolor.",105,2,-1,105,"Flor silvestre",0,4,"o",72,0,-1,0,162,162,"3720","",0,"","","",1,0,0,[],""],["frenk_t2-n3721",6,"Antes de llegar al puerto\nempezaba a suspirar,\ny en el suspiro decía:\n“No me vayas a olvidar.”",127,2,18,105,"Margarita",0,4,"a",21,0,-1,0,162,162,"3721","",0,"","","",1,0,0,[],""],["frenk_t2-n3722",6,"Cuando salí de mi tierra\ncuatro suspiros tiré;\nle dije a la vida mía:\n“Sabe Dios si volveré.”",105,2,-1,105,"Los combates de Torreón",0,4,"e",77,0,-1,0,162,162,"3722","",0,"","","",9,0,0,[],""],["frenk_t2-n3723",6,"Hasta el río fui con ella,\ncomunicando los dos;\nallá fueron los suspiros\ncuando ella me dijo adiós.",108,2,8,105,"Estrofa suelta",0,4,"o",87,0,-1,0,162,162,"3723","",0,"","","",1,0,0,[],""],["frenk_t2-n3724",6,"En la orillita del pueblo\nse quedó mi corazón\nclavado en puñal de acero\npor una bella ilusión.",105,2,-1,105,"La cruceñita",0,4,"o",31,0,-1,0,162,162,"3724","",0,"","","",1,0,0,[],""],["frenk_t2-n3725",6,"Cuando me vine de Tuxpan,\nsobre las olas venía,\ny el estrépito del agua\nme recordaba a María.",115,2,3,105,"María, María",0,4,"ia",0,0,-1,0,162,162,"3725","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n3726",6,"Qué bonita moreleña\nera la que yo tenía,\npero la dejé en Las Peñas,\nterritorio tapatío.",106,2,4,105,"El Ahualulco",5,4,"io",-1,0,-1,0,163,163,"3726","",0,"","","",1,0,0,[],""],["frenk_t2-n3727",6,"Los marineros, pues, me decían:\n—¿Por qué abandonas esa mujer?\n—No la abandono ni la desprecio,\nque, si Dios quiere, la vuelvo a ver.",120,2,14,105,"Las once son",3,4,"e",20,0,-1,0,163,163,"3727","",0,"","","",1,0,0,[],""],["frenk_t2-n3728",6,"De las arcas de la fuente (¡ay, Llorona!)\ncorre el agua sin cesar;\nal compás de su corriente (¡ay, Llorona!)\nmi amor empezó a nadar;\ntriste quejaba y ausente (¡ay, Llorona!),\nsin poderlo remediar.",108,2,8,105,"La Llorona",9,6,"a",21,0,-1,0,163,163,"3728","",0,"","","",1,0,0,[],""],["frenk_t2-n3729",6,"Una tarde, estando triste,\nen un cerro me senté\ny a un pájaro carpintero\nllorando le pregunté:\n“De mi amor estoy ausente:\npara hablarle ¿cómo haré?”",108,2,8,105,"Estrofa suelta",9,6,"e",77,0,-1,0,163,163,"3729","",0,"","","",3,0,0,[],""],["frenk_t2-n3730",6,"Fui tras de ella en los sepulcros\na buscarla, y no la hallé;\nle pregunté a los difuntos:\n“¿Adónde la encontraré\npara hacemos polvo juntos?”",107,2,11,105,"La Rosita; La azucena",7,5,"uo",296,0,-1,0,163,163,"3730","",0,"","","",1,0,0,[],""],["frenk_t2-n3731",6,"Del cielo cayó una caja\ncon unas llaves por dentro,\ndonde guardaba yo amores,\ny ahora guardo sentimientos.",108,2,8,105,"Estrofa suelta",3,4,"eo",-1,0,-1,0,163,163,"3731","",0,"","","",2,0,0,[],""],["frenk_t2-n3732",6,"En el jardín de la vida\nvarias flores corté yo;\nla más bella y más querida\npronto se me marchitó,\ndejando a mi alma herida.",113,2,2,105,"Estrofa suelta, La azucena",7,5,"ia",37,0,-1,0,163,163,"3732","",0,"","","",1,0,0,[],""],["frenk_t2-n3733a",6,"Yo me fui de jardinero,\npara ver la suerte mía;\nhora ya perdí el consuelo,\nque la flor que más quería\nse marchitaba primero.",112,2,6,105,"La Rosita",7,5,"eo",-1,0,-1,0,163,163,"3733a","",0,"","","",1,0,0,[],""],["frenk_t2-n3734",6,"Ya dieron fin mis amores,\nya se acabó tanto ardor,\ny en el jardín del amor\nse marchitaron las flores.",105,2,-1,105,"Estrofa suelta",11,4,"oe",5,0,-1,0,164,164,"3734","",0,"","","",1,0,0,[],""],["frenk_t2-n3735",6,"Ya se cayó el arbolito\ndonde yo me divertía,\ndonde pasaba las tardes\nplaticando con María.",115,2,3,105,"María, María",0,4,"ia",0,0,-1,0,164,164,"3735","",0,"","","",3,0,0,[],""],["frenk_t2-n3736",6,"¡Ay, qué pronto terminó\nesa ilusión que tenía!\nYo no sé qué sucedió:\nsin duda no me quería,\n¿o de cuántos se creyó?",105,2,-1,105,"Estrofa suelta",7,5,"o",2,0,-1,0,164,164,"3736","",0,"","","",1,0,0,[],""],["frenk_t2-n3737",6,"¡Currucucú, qué triste estoy!\nY una paloma me dijo así,\ny en su cantido decía:\n“Una esperanza he perdido”.",107,2,11,105,"Currucucú",3,4,"io",-1,0,-1,0,164,164,"3737","",0,"","","",1,0,0,[],""],["frenk_t2-n3739",6,"La luna tuvo la culpa\nque yo con mi bien perdiera;\nsi no fuera por la luna\nyo con mi bien estuviera.",108,2,8,105,"Estrofa suelta",0,4,"ea",44,0,-1,0,164,164,"3739","",0,"","","",1,0,0,[],""],["frenk_t2-n3740",6,"Yo me enamoré de noche,\ny la luna me engañó;\notra vez que me enamore\nserá de día y con sol.",106,2,4,105,"Estrofa suelta",0,4,"o",-1,0,-1,0,164,164,"3740","",0,"rm_t3, palau_cantares, fernan_caballero","","",9,0,0,[],""],["frenk_t2-n3741",6,"Yo me enamoré de noche,\ny la luna me engañó;\nla luna no engaña a nadie:\nel engañado fui yo.",105,2,-1,105,"Estás en la plenitud",0,4,"o",2,0,-1,0,164,164,"3741","",0,"","","",9,0,0,[],""],["frenk_t2-n3742",6,"Un gallo me anunciaba\nlo que me iba a pasar,\npero no lo quise creer,\ny me fui a desengañar.",129,2,9,105,"Estrofa suelta",0,4,"a",21,0,-1,0,165,165,"3742","",0,"","","",1,0,0,[],""],["frenk_t2-n3743",6,"Tristeza para el que espera,\nen una noche de luna,\na la linda mujer que fuera\nsu esperanza y su fortuna.",108,2,8,105,"La Petenera",1,4,"ua",56,0,-1,0,165,165,"3743","",0,"","","",1,0,0,[],""],["frenk_t2-n3744",6,"Cuando vine y no la hallé\nle di la comida a un perro (¡ay de mí, Lio-\nal cielo la encomendé,\nporque la quise y la quiero (¡ay de mí, Lió-\nla lloro y la lloraré.",105,2,-1,105,"La Llorona",7,5,"e",77,0,-1,0,165,165,"3744","",0,"","","",1,0,0,[],""],["frenk_t2-n3745",6,"Cuando me vine de Valles\nme vinieron a dejar;\nausente de Pisaflores,\ntriste me senté a llorar,\npor un par de ojitos negros,\nque no me quisieron dar.",113,2,2,105,"El San Lorenzo",9,6,"a",21,0,-1,0,165,165,"3745","",0,"","","",1,0,0,[],""],["frenk_t2-n3746",6,"Dios a mí no quiso darme\nel amor de esa mujer;\npara no sacrificarme,\nde este tan precioso ser\nhizo bien con separarme.",111,2,1,105,"Estrofa suelta",7,5,"ae",35,0,-1,0,165,165,"3746","",0,"","","",1,0,0,[],""],["frenk_t2-n3747",6,"¡Ay, que sí, válgame Dios!\nY sí, de mí se burló:\nuna muchacha de aquí\nbastante se rió de mí.",105,2,-1,105,"El siquisirí",5,4,"i",23,0,-1,0,165,165,"3747","",0,"","","",1,0,0,[],""],["frenk_t2-n3750",6,"Yo tenía mi tulisana,\nque me la quería robar;\nme dijo que la dejara,\nque ya se iba a presentar.",110,2,10,105,"Los tulises",0,4,"a",21,0,-1,0,166,166,"3750","",0,"","","",1,0,0,[],""],["frenk_t2-n3751",6,"Que una que bien yo quería,\ncuando salía, la encantadora,\nella se me resistía,\ny yo que la enamoraba,\nhasta que por fin un día\nde verme llorar, lloraba.",106,2,4,105,"El siquisirí",9,6,"aa",28,0,-1,0,166,166,"3751","",0,"","","",1,0,0,[],""],["frenk_t2-n3752",6,"La miré y le quise hablar,\npero iba con su marido;\nme vio a mí y quiso llorar\ny luego tiró un suspiro;\nme dijo: “Estáte por áhi,\nque al cabo me he de ir contigo.”",105,2,-1,105,"Corrido de Guanajuato",9,6,"io",-1,0,-1,0,166,166,"3752","",0,"","","",1,0,0,[],""],["frenk_t2-n3754",6,"¡Oh, qué buen chasco llevé\npor querer a una casada!\nDespués de que loco andaba,\ntodito me equivoqué.",105,2,-1,105,"Estrofa suelta",5,4,"e",77,0,-1,0,166,166,"3754","",0,"","","",1,0,0,[],""],["frenk_t2-n3755",6,"En un vaso azul dorado\ntomé el veneno más cruel;\ndespués de haberlo tomado\ntarde vine a comprender\nque el amor más estimado\nno sabe corresponder.",108,2,8,105,"Estrofa suelta, La indita",9,6,"e",20,0,-1,0,166,166,"3755","",0,"","","",2,0,0,[],""],["frenk_t2-n3756",6,"Ni al porvenir atendía\nde pensar en la que amaba;\nyo mil suspiros le hacía;\ncon desprecios me miraba:\nsin duda no me quería.",105,2,-1,105,"Estrofa suelta",7,5,"ia",0,0,-1,0,166,166,"3756","",0,"","","",1,0,0,[],""],["frenk_t2-n3757",6,"Todavía en el mundo existe\nlo que a mí me cautivó;\nella de orgullo se viste,\ny esa es la causa que yo\n.................... siempre triste.",106,2,4,105,"El fandanguito",7,5,"ie",153,0,-1,0,167,167,"3757","",0,"","","",1,0,0,[],""],["frenk_t2-n3758",6,"Me despreció una mujer,\ny traigo ese sentimiento;\nbonito su cascabel,\ncontento mejor me ausento.",108,2,8,105,"El cascabel",0,4,"eo",94,0,-1,0,167,167,"3758","",0,"","","",3,0,0,[],""],["frenk_t2-n3759a",6,"Cuando canto yo “El jarabe’\nme acuerdo de una mujer:\nde mi pecho era la llave,\nahora no me puede ver.",106,2,4,105,"El jarabe loco",1,4,"e",20,0,-1,0,167,167,"3759a","",0,"","","",1,0,0,[],""],["frenk_t2-n3760",6,"Navegando en una balsa\nme quise desvanecer,\ny me agarré de una zarza:\nno me pude detener.\nPor una cuartilla falsa\nme despreció una mujer.",108,2,8,105,"Estrofa suelta",9,6,"e",20,0,-1,0,167,167,"3760","",0,"","","",1,0,0,[],""],["frenk_t2-n3761",6,"Ya me encontré una,\nle conté mis penas\nsin pena ninguna,\ny ella me contesta\nmuy desconsolada:\n“¿Qué voy a querer a un hombre\nque venga mojado,\ncon toda su ropa\napestosa a pescado?”\nY ella viene ya.",106,2,4,105,"El jarabe loco",18,10,"a",-1,0,-1,0,167,167,"3761","",0,"","","",1,0,0,[],""],["frenk_t2-n3762",6,"Mientras tuve algunos pesos\nme hizo caso una mujer;\ncuando ya se me acabaron\nya no la he vuelto a ver.",108,2,8,105,"Estrofa suelta",0,4,"e",20,0,-1,0,167,167,"3762","",0,"","","",1,0,0,[],""],["frenk_t2-n3763",6,"“Cuánto tienes, cuánto vales”,\nlo dicen, y con razón;\nel hacha de mis rivales\nme destrozó el corazón.",105,2,-1,105,"Arbol caído",1,4,"o",31,0,-1,0,167,167,"3763","",0,"","","",1,0,0,[],""],["frenk_t2-n3764",6,"El amor y el interés\nsalieron al campo un día;\n¿y quién ganaría?\nPudo más el interés\nque el amor que le tenía.",126,2,19,105,"Estrofa suelta",7,5,"ia",0,0,-1,0,167,167,"3764","",0,"","","",9,0,0,[],""],["frenk_t2-n3765",6,"Tiré una flor en el viento\ny el aire se la llevó;\nun bien con un mal se paga,\ncomo a mí me sucedió.",105,2,-1,105,"Amorcito consentido",0,4,"o",2,0,-1,0,168,168,"3765","",0,"","","",1,0,0,[],""],["frenk_t2-n3766",6,"Conchita me dio su amor,\npero me salió informal;\npor eso no es bueno engreírse:\ncomprende que pagan mal.",131,2,22,105,"Tuve un amor",0,4,"a",1,0,-1,0,168,168,"3766","",0,"","","",1,0,0,[],""],["frenk_t2-n3767",6,"Ya muy bien comprendía\nque yo en ella me fijaba,\nhasta que por fin un día\nvi que ella me traicionaba:\nsin duda no me quería.",105,2,-1,105,"Estrofa suelta",7,5,"ia",0,0,-1,0,168,168,"3767","",0,"","","",1,0,0,[],""],["frenk_t2-n3768",6,"Se rompió mi tinajero\nde un amor que tanto quise;\ncomo era falsa madera,\nel troncón tomó podrice.\n¡Mal haya la casa ajena!\nPor eso no es bueno engreírse.",105,2,-1,105,"El carpintero",9,6,"ie",-1,0,-1,0,168,168,"3768","",0,"","","",1,0,0,[],""],["frenk_t2-n3769",6,"No fue verdad\nlo que ella me prometió:\ntodo fue una falsedad,\nfalsa moneda con que me pagó.",107,2,11,105,"La cautela’",3,4,"o",2,0,-1,0,168,168,"3769","",0,"","","",1,0,0,[],""],["frenk_t2-n3770",6,"Por una mujer ladina\nperdí la tranquilidad;\nella me clavó una espina,\nque no me puedo arrancar.",105,2,-1,105,"La mujer ladina",0,4,"a",-1,0,-1,0,168,168,"3770","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n3771",6,"Por una mala mujer\nando en el mundo penando;\nella me dijo que sí,\npero no me dijo cuándo.",105,2,-1,105,"Mala mujer",0,4,"ao",33,0,-1,0,168,168,"3771","",0,"","","",2,0,0,[],""],["frenk_t2-n3772",6,"Triste mi amor se quedó\nal pie de un palo de fibra,\npor una mala partida\nque una vieja me jugó;\ny eso sí que no se olvida:\nsólo que me mate yo.",105,2,-1,105,"El carpintero",9,6,"o",2,0,-1,0,168,168,"3772","",0,"","","",1,0,0,[],""],["frenk_t2-n3773",6,"Yo amé una ingrata mujer\ncon frenesí y con pasión;\nla infame me hizo traición:\n¿será araña?, puede ser.",105,2,-1,105,"Estrofa suelta",11,4,"e",20,0,-1,0,168,168,"3773","",0,"","","",1,0,0,[],""],["frenk_t2-n3774",6,"Amigos, yo me casé\ncon una mujer de Tula;\nyo por yegua la compré,\ny me fue saliendo mula.",121,2,26,105,"Estrofa suelta",1,4,"ua",547,0,-1,0,169,169,"3774","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n3775",6,"De un beso nació una ausencia,\nde aquella ausencia, un cariño,\nde aquel cariño, una pena\nde aquella pena, un olvido.",105,2,-1,105,"Estrofa suelta",0,4,"io",-1,0,-1,0,169,169,"3775","",0,"","","",1,0,0,[],""],["frenk_t2-n3776",6,"La mujer por quien sufrí\nno me quisiera acordar;\nyo la amé con frenesí,\npero me fue a olvidar\nla hermosa flor de rubí.",113,2,2,105,"El gusto",7,5,"i",23,0,-1,0,169,169,"3776","",0,"","","",1,0,0,[],""],["frenk_t2-n3777",6,"¡Cucurrucutú, qué triste estoy!\nCuando empezaba a quererla\nella emprendió su volido;\ncuando empezaba a buscarla\nme dijo: “Te echo al olvido.”",107,2,11,105,"Currucucú",7,5,"io",101,0,-1,0,169,169,"3777","",0,"","","",1,0,0,[],""],["frenk_t2-n3778",6,"Décimas de un solterito,\nque hoy se encuentra dolorido,\nporque se fue su amorcito\nsin darle ningún motivo,\ny al encontrarse solito\nHora triste y afligido.",105,2,-1,105,"Estrofa suelta",9,6,"io",-1,0,-1,0,169,169,"3778","",0,"","","",1,0,0,[],""],["frenk_t2-n3779a",6,"Me dicen que no le llore,\nque ella se fue porque quiso;\npero yo digo: “Señores,\nel llorar es preciso.”",107,2,11,105,"El llorar",0,4,"io",92,0,-1,0,169,169,"3779a","",0,"","","",2,0,0,[],""],["frenk_t2-n3779b",6,"Me dicen que no le llore,\nque ella se fue porque quiso (¡ay, mi vi-\nle lloro porque es preciso: [da!);\nme acuerdo de sus amores (¡ay, mi vida!)\ny las caricias que me hizo (¡ay, mi vida!).",112,2,6,105,"El llorar; Estrofa suelta",7,5,"ia",-1,0,-1,0,169,169,"3779b","",0,"","","",2,0,0,[],""],["frenk_t2-n3779c",6,"Dicen que no la llore,\nque ella se fue porque quiso;\ny yo les digo: “Señores,\nel llorar es muy preciso:\nme acuerdo de sus favores\ny sus caricias bendigo.”",106,2,4,105,"La Llorona; La Malagueña",9,6,"io",-1,0,-1,0,169,169,"3779c","",0,"","","",1,0,0,[],""],["frenk_t2-n3782",6,"Hacia esas tierras voló mi primavera,\ncon las industrias del pájaro gurrión;\nmi primavera trató de abandonarme,\nmi primavera se fue y [me] abandonó.",105,2,-1,105,"Las aves",3,4,"o",-1,0,-1,0,170,170,"3782","",0,"","","",1,0,0,[],""],["frenk_t2-n3783",6,"Mariquita se llamaba\nla que a mí me abandonó;\nsu mamá tuvo la culpa,\nporque la desanimó.",114,2,17,105,"Mariquita",0,4,"o",2,0,-1,0,170,170,"3783","",0,"","","",3,0,0,[],""],["frenk_t2-n3784",6,"Cada vez que paso y veo\nla casa donde vivió,\n¿para qué quiero la casa,\nsi la paloma voló\ncon un gavilán pollero,\nque de ella se enamoró?",106,2,4,105,"Estrofa suelta",9,6,"o",2,0,-1,0,170,170,"3784","",0,"","","",3,0,0,[],""],["frenk_t2-n3785",6,"A la sombra de una palma\ntriste me senté a llorar\nde ver a mi palomita\nsentada en otro palmar.",109,2,7,105,"Los caracoles",0,4,"a",21,0,-1,0,170,170,"3785","",0,"","","",1,0,0,[],""],["frenk_t2-n3786",6,"La mujer que me traicionó\npor cierto se llamaba Paula;\nya el pájaro voló,\ny no más me quedó la jaula.",106,2,4,105,"Estrofa suelta",1,4,"aa",557,0,-1,0,170,170,"3786","",0,"","","",1,0,0,[],""],["frenk_t2-n3787",6,"Yo tenía mi camotal,\nque me lo cuidaba un viejo;\ncomo lo cuidé tan mal,\nme lo ha comido un conejo.",105,2,-1,105,"Mi marido fue a La Habana",1,4,"eo",264,0,-1,0,171,171,"3787","",0,"","","",2,0,0,[],""],["frenk_t2-n3788",6,"Yo tenía mi camotal\nen la playa de Alvarado;\ncomo lo cuidé tan mal,\nme lo ha comido el venado.",105,2,-1,105,"Mi marido fue a La Habana",1,4,"ao",14,0,-1,0,171,171,"3788","",0,"","","",2,0,0,[],""],["frenk_t2-n3789",6,"De la marina....................\na la estación de Alvarado,\na una que llegó en el tren\ncon ella me porté bien;\nla paseé por el mercado,\nse me fue, no vi con quién:\nmiel con el dedo me ha dado.",105,2,-1,105,"La tarasca",4,7,"ao",14,0,-1,0,171,171,"3789","",0,"","","",1,0,0,[],""],["frenk_t2-n3790",6,"A los veinte años yo fui casado,\ny abandonado a los veintidós:\nla muy ingrata se fue y me dejó,\nsin duda por otro más hombre que yo.",105,2,-1,105,"Las fuentes",3,4,"o",2,0,-1,0,171,171,"3790","",0,"","","",1,0,0,[],""],["frenk_t2-n3791",6,"Bonitas fuentes son las corrientes,\nlas que dependen del corazón;\nla muy ingrata se fue y me dejó,\nsin duda con otro más hombre que yo",107,2,11,105,"Las fuentes",3,4,"o",2,0,-1,0,171,171,"3791","",0,"","","",2,0,0,[],""],["frenk_t2-n3792",6,"Ya que veniste, pasa pa adentro,\nque aquí te aguarda mi corazón.\nLa muy ingrata se fue y me abandonó,\nse fue con otro más hombre que yo.",110,2,10,105,"Las fuentes",3,4,"o",2,0,-1,0,171,171,"3792","",0,"","","",1,0,0,[],""],["frenk_t2-n3793",6,"En la torre de mis gustos\ndonde tan alto me vi,\npor ser el cimiento falso,\notro subió, yo caí.",105,2,-1,105,"Estrofa suelta",0,4,"i",23,0,-1,0,171,171,"3793","",0,"","","",4,0,0,[],""],["frenk_t2-n3794",6,"“¡Apa, apa!”, me dijo Cupido\nal cortar un mirasol:\n“No lo cortes, atrevido,\nal cabo no es para ti la flor:\nes para otro consentido,\nque ése sí va a ser el dueño del amor.”",113,2,2,105,"Estrofa suelta",9,6,"o",72,0,-1,0,171,171,"3794","",0,"","","",1,0,0,[],""],["frenk_t2-n3796",6,"Dice el dicho: “Caras vemos\n—no me queda ya qué hablar—,\ncorazones no sabemos”:\nno me vuelvo a enamorar.",105,2,-1,105,"Los aguacates",1,4,"a",21,0,-1,0,172,172,"3796","",0,"","","",1,0,0,[],""],["frenk_t2-n3797",6,"Verdad de Dios,\nno vuelvo a amar:\nen medio del corazón\nllevo clavado un puñal.",105,2,-1,105,"Verdad de Dios",3,4,"a",-1,0,-1,0,172,172,"3797","",0,"","","",1,0,0,[],""],["frenk_t2-n3798",6,"Yo tengo un golpe en el pecho,\ny una ingrata me lo dio,\ny me lo dio tan derecho,\nque hasta el alma me dolió;\nno hay cuidado, está bien hecho,\npara que escarmiente yo.",105,2,-1,105,"Corrido de Guanajuato; Estrofa suelta",9,6,"o",2,0,-1,0,172,172,"3798","",0,"","","",1,0,0,[],""],["frenk_t2-n3800",6,"En el corazón tenía\nla espina de una pasión;\nlogré arrancármela un día,\nno la siento en el corazón.",108,2,8,105,"Estrofa suelta",1,4,"o",31,0,-1,0,172,172,"3800","",0,"","","",1,0,0,[],""],["frenk_t2-n3801",6,"Pero fui tan desgraciado\ncon querer a esa mujer,\nque he jurado por el Eterno\nno volverla ya a querer.",105,2,-1,105,"Canción del Interior",0,4,"e",20,0,-1,0,172,172,"3801","",0,"","","",1,0,0,[],""],["frenk_t2-n3802",6,"Preso me encuentro por una cautela\ny abandonado por una mujer;\nmientras yo viva en el mundo y no muera,\nnunca en la vida la vuelvo a querer.",105,2,-1,105,"La cautela",3,4,"e",20,0,-1,0,172,172,"3802","",0,"","","",1,0,0,[],""],["frenk_t2-n3803",6,"Recuerdos de una ingrata,\nque en un tiempo yo la amaba;\npero mi orgullo ha sido\nque no la he vuelto a querer.",105,2,-1,105,"Canción del Interior",5,4,"e",-1,0,-1,0,172,172,"3803","",0,"","","",1,0,0,[],""],["frenk_t2-n3804",6,"¡Ay, pobrecito de mí,\nque doy suspiros al aire!\nEl aire bien se los lleva,\ny no los recoge nadie.",105,2,-1,111,"Estrofa suelta",0,4,"ae",-1,0,-1,0,175,175,"3804","",0,"","","",4,0,0,[],""],["frenk_t2-n3805",6,"Sólito y abandonado,\nsin consuelo y sin amor,\nsiento que muere de pena,\nse marchita el corazón.",114,2,17,111,"El perico loro",0,4,"o",-1,0,-1,0,175,175,"3805","",0,"","","",1,0,0,[],""],["frenk_t2-n3806",6,"Sufrirla es imposible,\nmejor me siento a llorar,\nporque no hallo una joven\nque me venga a consolar.",108,2,8,111,"La calandria",0,4,"a",21,0,-1,0,175,175,"3806","",0,"","","",1,0,0,[],""],["frenk_t2-n3807",6,"Yo quisiera dar y dar,\npero no tengo con qué;\nyo quisiera dar un beso,\npero no hay quién me lo dé.",108,2,8,111,"Estrofa suelta",0,4,"e",77,0,-1,0,175,175,"3807","",0,"","","",1,0,0,[],""],["frenk_t2-n3808",6,"¡Ay, Soledad, Soledad!,\nSoledad de cerro en cerro;\ntodos tienen sus amores,\ny a mí que me muerda un perro.",105,2,-1,111,"La Petenera’",0,4,"eo",379,0,-1,0,175,175,"3808","",0,"","","",18,0,0,[],""],["frenk_t2-n3809",6,"¡Ay, morenita!,\nmorenita del Bajío,\ntodos tienen sus amores,\nsólo a mí me falta el mío.",109,2,7,111,"La morenita",3,4,"io",3,0,-1,0,175,175,"3809","",0,"","","",3,0,0,[],""],["frenk_t2-n3810",6,"Cuando era yo chiquitito\ntodos me mecían en cuna;\nhora que soy grandecito\nno me acaricia ninguna:\nsoy un pobre huerfanito.",113,2,2,111,"El huerfanito",7,5,"io",119,0,-1,0,175,175,"3810","",0,"","","",1,0,0,[],""],["frenk_t2-n3811",6,"Pues recuerdo, cuando era yo niña\nbuen dinero me daban los charros;\nhoy de celos ni me daban cuartilla\npara tan siquiera mis cigarros.",108,2,8,111,"Ay, amigos, pongan atención",3,4,"ao",558,0,-1,0,175,175,"3811","",0,"","","",1,0,0,[],""],["frenk_t2-n3813a",6,"Dichoso el árbol que da\nen cada rama una pera;\nel desgraciado soy yo,\nque no encuentro quién me quiera.",105,2,-1,111,"Estrofa suelta",0,4,"ea",44,0,-1,0,176,176,"3813a","",0,"","","",4,0,0,[],""],["frenk_t2-n3813c",6,"Dichoso el árbol que da\nen cada rama una pera;\nmaldecido lo soy yo,\nque no encuentro quién me quiera:\namor es lo que me sobra,\npero de dientes pa fuera.",105,2,-1,111,"Estrofa suelta",9,6,"ea",44,0,-1,0,176,176,"3813c","",0,"","","",4,0,0,[],""],["frenk_t2-n3814",6,"De las lomas de Agua Blanca\nvide trabajar tus obras;\nni tampoco de malhora;\ncariño es lo que me falta,\nque quien me quiera me sobra.",109,2,7,111,"Soy fandanguero; Estrofa suelta",7,5,"oa",-1,0,-1,0,176,176,"3814","",0,"","","",1,0,0,[],""],["frenk_t2-n3815",6,"Es muy justo que Dios nos castigue,\nque nos lleve a su trono divino.\n¡Ay, chivarras, qué mal me han venido,\npor querer a las bellas amar!",110,2,10,111,"Las chivarras",3,4,"a",-1,0,-1,0,176,176,"3815","",0,"","","",1,0,0,[],""],["frenk_t2-n3816a",6,"“¡Ay, Jerú!”, dijo David\ndebajo de los laureles.\n“¡Qué ingratas son las mujeres\nque no me quieren a mí\npor mis malos procederes!”",105,2,-1,111,"Al pasar por los laureles",7,5,"ee",55,0,-1,0,176,176,"3816a","",0,"","","",2,0,0,[],""],["frenk_t2-n3817",6,"Yo soy el mozo del cura,\nque cargo los cuadernos;\nla mujer que a mí me quiera\nderecho se va al infierno.",108,2,8,111,"Estrofa suelta",0,4,"eo",-1,0,-1,0,176,176,"3817","",0,"","","",2,0,0,[],""],["frenk_t2-n3818",6,"Quiero a todas cuantas veo,\npero a ninguna consigo:\na cuantas miro les digo,\ny me voy con el deseo.",105,2,-1,111,"Estrofa suelta",11,4,"eo",66,0,-1,0,177,177,"3818","",0,"","","",1,0,0,[],""],["frenk_t2-n3819",6,"Ya no vuelvo a enamorarme\nde la que me salga al paso,\nporque no más pierdo el tiempo,\ny al final ni me hacen caso.",105,2,-1,111,"El gato",0,4,"ao",145,0,-1,0,177,177,"3819","",0,"","","",1,0,0,[],""],["frenk_t2-n3820",6,"Me dicen que soy tunero\nporque uso sombrero ancho;\ntunero soy, no lo niego,\npero con las de mi rancho;\nyo a todas las tunas quiero,\npero no alcanza mi gancho.",105,2,-1,111,"Estrofa suelta, La rosita arribeña",9,6,"ao",380,0,-1,0,177,177,"3820","",0,"","","",1,0,0,[],""],["frenk_t2-n3821",6,"Toditas las muchachas\ndicen que no soy de aquí;\ncuando menos, me rechazan,\nme creen como un infeliz.",115,2,3,111,"Soy forastero",0,4,"i",-1,0,-1,0,177,177,"3821","",0,"","","",1,0,0,[],""],["frenk_t2-n3822",6,"¡Ah, mal haya quién pudiera,\ncomo calar un melón!\nAsí fueran las mujeres,\nblanditas del corazón.",108,2,8,111,"Estrofa suelta",0,4,"o",31,0,-1,0,177,177,"3822","",0,"","","",1,0,0,[],""],["frenk_t2-n3823",6,"Al otro lado del río\nme chiflaba un triste león;\nen el chiflido decía:\n“Mujeres, ¿pa cuándo son?”",105,2,-1,111,"El cuervo; El león",0,4,"o",31,0,-1,0,177,177,"3823","",0,"","","",15,0,0,[],""],["frenk_t2-n3824a",6,"¡Ay, quién fuera como el cocuyo!\nHay mujeres con orgullo\nque no me quieren hablar,\nque creen que el mundo es suyo\ny se lo van a llevar.",106,2,4,111,"El siquisirí",7,5,"a",21,0,-1,0,177,177,"3824a","",0,"","","",1,0,0,[],""],["frenk_t2-n3824b",6,"¡Quién fuera como el cocuyo,\nque alumbra para volar!\nHay mujeres como el cuyo,\nque no me quieren hablar,\ncreyendo que el mundo es suyo\ny se lo van a llevar.",106,2,4,111,"El siquisirí",9,6,"a",21,0,-1,0,177,177,"3824b","",0,"","","",2,0,0,[],""],["frenk_t2-n3825",6,"¡Ay, yeguas de mi manada!,\n¡ay, potrancas del rincón!\nCuando no me ven relinchan\ny se van al vacilón;\n¡cómo no relinchan hora,\nque aquí está su garañón!",105,2,-1,111,"El venadito",9,6,"o",31,0,-1,0,177,177,"3825","",0,"","","",1,0,0,[],""],["frenk_t2-n3826",6,"¡Ay, yeguas alazanas\ny color de cera Campeche!,\n¿por qué no relinchan ahora,\nque este jinete trae cuete?",112,2,6,111,"Estrofa suelta",0,4,"ee",-1,0,-1,0,178,178,"3826","",0,"","","",1,0,0,[],""],["frenk_t2-n3827",6,"¡Adentro, mulas del parque,\npezuñas ametaladas!,\n¿por qué no relinchan hora,\nhijas del siete de espadas?",115,2,3,111,"El caballo prieto",0,4,"aa",282,0,-1,0,178,178,"3827","",0,"","","",1,0,0,[],""],["frenk_t2-n3828",6,"¡Ay, víboras pichicuatas\ny víboras chirrioneras!,\n¿por qué no me pican hora\nque traigo mis chaparreras?",110,2,10,111,"Las chivarras",0,4,"ea",103,0,-1,0,178,178,"3828","",0,"","","",1,0,0,[],""],["frenk_t2-n3829",6,"Por nombre te han puesto Luz\ncon muchísima razón,\npero no has de alumbrar bien\ncomo no te encienda yo.",105,2,-1,112,"Estrofa suelta",0,4,"o",-1,0,-1,0,183,183,"3829","",0,"","","",1,0,0,[],""],["frenk_t2-n3830",6,"Adiós cantando les digo,\nme voy cantando y adiós;\ncantando me voy en pos\ntras el amor que persigo,\nque para amamos los dos\na ti te sobra conmigo.",105,2,-1,112,"El huasteco enamorado",9,6,"io",106,0,-1,0,183,183,"3830","",0,"","","",1,0,0,[],""],["frenk_t2-n3831",6,"Eres rosa de Castilla,\nque al pasar me das tu aroma;\ndices que ya no me quieres,\ny hasta a la puerta te asomas.",115,2,3,112,"Mariquita",0,4,"oa",-1,0,-1,0,183,183,"3831","",0,"","","",5,0,0,[],""],["frenk_t2-n3832",6,"Dices que no me quieres:\nme estás queriendo;\nasí son las mujeres:\nsólo mintiendo;\nyo digo esto:\nporque me estás queriendo\nme he descompuesto.",111,2,1,112,"Cielito lindo",4,7,"eo",-1,0,-1,0,183,183,"3832","",0,"","","",15,0,0,[],""],["frenk_t2-n3833",6,"Pídele a Dios que me muera\ny me lleven al panteón,\npara que así tú reces\nla misa con devoción.",105,2,-1,112,"Espina traidora",0,4,"o",31,0,-1,0,183,183,"3833","",0,"","","",1,0,0,[],""],["frenk_t2-n3834",6,"Nací norteño hasta el tope,\nme gusta decir verdades;\nsoy piedra que no se alisa\npor más que talles y talles;\nsoy terco como una muía:\n¿adónde vas que no te halle?",105,2,-1,112,"No soy monedita de oro",9,6,"ae",-1,0,-1,0,183,183,"3834","",0,"","","",1,0,0,[],""],["frenk_t2-n3835",6,"No le temo a los balazos,\ny aunque la sangre me beba;\nsi esta noche se me pone,\nte quito de canelera.",115,2,3,112,"La canelera",0,4,"ea",-1,0,-1,0,183,183,"3835","",0,"","","",1,0,0,[],""],["frenk_t2-n3837",6,"Soy el pájaro perdido,\nel que andaba ausente;\nsi lo has echado en olvido,\nmíralo, que está presente,\ndespierto: no está dormido.",108,2,8,112,"El siquisirí",7,5,"io",101,0,-1,0,184,184,"3837","",0,"","","",1,0,0,[],""],["frenk_t2-n3838",6,"Yo soy coyote de rancho,\npor eso sigo tus pasos;\nme recuadra el zafarrancho,\npa tupirle a los plomazos,\ny en la noche te echo el gancho\npara estrecharte en mis brazos.",105,2,-1,112,"La oveja perdida",9,6,"ao",-1,0,-1,0,184,184,"3838","",0,"","","",1,0,0,[],""],["frenk_t2-n3839",6,"Úrsula, yo soy su gallo\ny su gavilán pollero;\nyo me he de llevar la polla,\ny aunque le rechine el cuero.",108,2,8,112,"Úrsula",0,4,"eo",38,0,-1,0,184,184,"3839","",0,"","","",1,0,0,[],""],["frenk_t2-n3840",6,"La despedida es la seña\nde tu ausencia tan voraz;\n¿pues qué de veras te vas\na los brazos de otro dueño,\npensando que así saldrás?",108,2,8,112,"El trompito",7,5,"a",51,0,-1,0,184,184,"3840","",0,"","","",1,0,0,[],""],["frenk_t2-n3841",6,"Ten en cuenta, bien de mi alma,\nque hay un dicho muy certero:\ntoda muía descarriada\nvuelve al fin al bebedero.",105,2,-1,112,"La puntada",0,4,"eo",38,0,-1,0,184,184,"3841","",0,"","","",1,0,0,[],""],["frenk_t2-n3842",6,"He sabido y me lo han dicho\nque ya tienes compromiso;\nte curo cualquier capricho,\nsi tú me das tu permiso.",105,2,-1,112,"Gallo tapado",1,4,"io",-1,0,-1,0,184,184,"3842","",0,"","","",1,0,0,[],""],["frenk_t2-n3843",6,"Al pie de un verde mezquite\nmi amor te estuve diciendo;\nsi tienes quien te lo quite,\nno me andes comprometiendo;\na mi lado no hay quién chiste:\nsi quieres sal, y vámonos yendo.",119,2,12,112,"La Malagueña",9,6,"eo",52,0,-1,0,184,184,"3843","",0,"","","",3,0,0,[],""],["frenk_t2-n3844",6,"Soy piedra de oro macizo,\nde veinticuatro quilates;\nya ves que no más me aliso\npor los desprecios que me haces,\ny en la tierra que yo piso\npor Dios que ni el pasto nace.",108,2,8,112,"Estrofa suelta, El valedor",9,6,"ae",-1,0,-1,0,184,184,"3844","",0,"","","",1,0,0,[],""],["frenk_t2-n3845",6,"En la medianía del mar\nun baúl se me cayó;\na poco tuve razón,\nque un marino se lo halló;\naunque te pasees con otro,\nel mero dueño soy yo.",108,2,8,112,"Estrofa suelta",9,6,"o",2,0,-1,0,185,185,"3845","",0,"","","",6,0,0,[],""],["frenk_t2-n3846",6,"Si te suelto como un trompo,\ndespués no te quejes de mí:\npaséate con la que quieras,\npero con cuidado, sí.",110,2,10,112,"Si te suelto como un trompo",0,4,"i",23,0,-1,0,185,185,"3846","",0,"","","",1,0,0,[],""],["frenk_t2-n3847",6,"Puedes tener tres o cuatro\npara gozar de la vida,\npero no olvides, ingrata\nque fuiste mi consentida,\ny que soy de los hombres\nde esos que nunca se olvidan.",108,2,8,112,"Estrofa suelta",9,6,"ia",-1,0,-1,0,185,185,"3847","",0,"","","",1,0,0,[],""],["frenk_t2-n3848",6,"Pa que te pasees con otro,\npídele a Dios que me muera,\nque me muera o que me maten\npa que te puedas pasear.",105,2,-1,112,"Te he de amar y te he de amar",5,4,"a",-1,0,-1,0,185,185,"3848","",0,"","","",1,0,0,[],""],["frenk_t2-n3850",6,"Esta noche la dedico\npara llevarte a pasear;\nel que se sienta más hombre\nque me la venga a quitar.",105,2,-1,112,"Te he de amar y te he de amar",0,4,"a",21,0,-1,0,185,185,"3850","",0,"","","",1,0,0,[],""],["frenk_t2-n3851",6,"Esta noche nos paseamos:\na ver quién se pone al brinco;\nyo no le temo a la muerte,\nni a cualquier mono me le hinco.",105,2,-1,112,"Te he de amar y te he de amar",0,4,"io",559,0,-1,0,185,185,"3851","",0,"","","",1,0,0,[],""],["frenk_t2-n3852",6,"Yo sé que tus pretendientes\npresumen de ser matones;\nel miedo que yo les tengo\nlo traigo aquí en los talones.",105,2,-1,112,"El patas blancas",0,4,"oe",34,0,-1,0,185,185,"3852","",0,"","","",1,0,0,[],""],["frenk_t2-n3853",6,"Aunque tengan que rabiar\nlos amigos de tu barrio,\ncon mi machete filoso\na todos los hago un lado.",105,2,-1,112,"La canelera",0,4,"ao",-1,0,-1,0,186,186,"3853","",0,"","","",1,0,0,[],""],["frenk_t2-n3854",6,"Cuando paso por tu casa\ny me paro allá en la esquina,\nlas panteras de tu barrio\nme echan los perros encima.",108,2,8,112,"El valiente",0,4,"ia",-1,0,-1,0,186,186,"3854","",0,"","","",7,0,0,[],""],["frenk_t2-n3855",6,"Ayer tarde que paseaba\npor las calles de tu casa,\nestaba maullando un gato,\npero era de mala raza.",105,2,-1,112,"Del cielo cayó una rosa",0,4,"aa",307,0,-1,0,186,186,"3855","",0,"","","",1,0,0,[],""],["frenk_t2-n3856",6,"Soy tu gavilán pollero\ny tu gallo de pelea;\nando buscando un carnero\npa tenderme su zalea,\nno más pa ver de cuál cuero\nsalen mejores correas.",105,2,-1,112,"El valedor",9,6,"ea",-1,0,-1,0,186,186,"3856","",0,"","","",1,0,0,[],""],["frenk_t2-n3857",6,"Vale más morir peleando\nque yo dejarte de amar;\nque si él carga pistola,\nyo también cargo puñal.",105,2,-1,112,"A los ángeles del cielo",0,4,"a",-1,0,-1,0,186,186,"3857","",0,"","","",1,0,0,[],""],["frenk_t2-n3858",6,"Tu papá carga cuchillo,\nyo también cargo puñal;\nnos tiramos tiro a tiro,\nnos tiramos a matar.",106,2,4,112,"La Rosita; Estrofa suelta",0,4,"a",-1,0,-1,0,186,186,"3858","",0,"","","",1,0,0,[],""],["frenk_t2-n3859",6,"Indita, ¿qué haremos hora?,\nallá viene tu marido;\nél me mata y yo lo mato,\npero yo no me retiro.",115,2,3,112,"La indita",0,4,"io",-1,0,-1,0,186,186,"3859","",0,"","","",2,0,0,[],""],["frenk_t2-n3860",6,"Yo soy un gavilancillo,\nque me la vengo a llevar:\navísele a su marido\nque me la salga a quitar.",114,2,17,112,"El gavilancillo; El riflero; El tigre*",0,4,"a",21,0,-1,0,186,186,"3860","",0,"","","",12,0,0,[],""],["frenk_t2-n3861",6,"Esta noche con la luna\nte vas a pasear conmigo,\naunque le parezca mal\nal chivo de tu marido.",105,2,-1,112,"El distinguido",0,4,"io",-1,0,-1,0,186,186,"3861","",0,"","","",4,0,0,[],""],["frenk_t2-n3862",6,"En el filo de una daga\nse anda paseando la muerte.\nAnda dile a tu marido\nque a la noche vengo a verte,\npa ver si sale un maldito\nque quiera rifar su suerte.",105,2,-1,112,"La culebra pollera’",9,6,"ee",134,0,-1,0,187,187,"3862","",0,"","","",1,0,0,[],""],["frenk_t2-n3863",6,"Dicen que tienes a otro:\nlo quisiera conocer;\naquí le traigo su alfalfa\npara darle de comer.",108,2,8,112,"Estrofa suelta, El palmero",0,4,"e",20,0,-1,0,187,187,"3863","",0,"","","",1,0,0,[],""],["frenk_t2-n3864",6,"Me salí por el potrero\nde las tomas de agua fría.\nDejaste ir mi jilguero\ncon otro que no sabía;\n¡ah, qué pájaro tan fiero!,\nte lo he de apedrear un día.",112,2,6,112,"Las flores",9,6,"ia",0,0,-1,0,187,187,"3864","",0,"","","",1,0,0,[],""],["frenk_t2-n3865",6,"Si tú tienes nuevo amante,\nque me venga a reclamar,\npara damos un tirito\nen qué tanto puedo topar.",105,2,-1,112,"A los ángeles del cielo",0,4,"a",21,0,-1,0,187,187,"3865","",0,"","","",1,0,0,[],""],["frenk_t2-n3866",6,"Al pasar por el corral\nte vi charlar con otro hombre;\ndime quién es ese tal\npara hacerme de renombre;\na ver si me hace cabal,\naunque a Satanás asombre.",105,2,-1,112,"En una hermosa mañana",9,6,"oe",220,0,-1,0,187,187,"3866","",0,"","","",1,0,0,[],""],["frenk_t2-n3867",6,"Dicen que las tapatías\npresumen de pie chiquito;\nal otro que tú tenías\nyo le quito lo maldito.",105,2,-1,112,"Éntrale al toro",1,4,"io",119,0,-1,0,187,187,"3867","",0,"","","",1,0,0,[],""],["frenk_t2-n3868",6,"Ese novio que tú tienes\nme anda reclamando a mí.\n¡Qué tan hombre puede ser,\nsi yo pa morir nací!",120,2,14,112,"Cuando salgo del trabajo",0,4,"i",23,0,-1,0,187,187,"3868","",0,"","","",2,0,0,[],""],["frenk_t2-n3869",6,"Dicen que tu buey es bravo\ny de muy mal corazón;\nque me cite donde quiera\npa quitarle lo agachón,\nque al cabo en el camposanto\nnos pertenece un rincón.",116,2,15,112,"El buey",9,6,"o",31,0,-1,0,187,187,"3869","",0,"","","",3,0,0,[],""],["frenk_t2-n3870",6,"Dicen que tu buey es bravo\ny que carga buen puñal;\nque me cite donde quiera,\nsi quiere ser mi rival;\nno le hace que sean serpientes,\npara mí ha de ser igual.",116,2,15,112,"El buey",9,6,"a",1,0,-1,0,187,187,"3870","",0,"","","",3,0,0,[],""],["frenk_t2-n3871",6,"Dicen que tu buey es bravo\ny presume de novillo;\nque no se las dé de bravo\nni presuma de novillo,\nque en un terreno macizo\nno me llega ni al tobillo.",116,2,15,112,"El buey",9,6,"io",-1,0,-1,0,188,188,"3871","",0,"","","",3,0,0,[],""],["frenk_t2-n3872",6,"Y ese gallo que te canta\nno te volverá a cantar;\npara que de mí se burlen,\nlas plumas le han de volar.",120,2,14,112,"Cuando salgo del trabajo",0,4,"a",21,0,-1,0,188,188,"3872","",0,"","","",1,0,0,[],""],["frenk_t2-n3875",6,"A orillas de una barranca\nsembré un granito de arroz;\nyo te enseñaré, chirriona,\ncómo se mancuernan dos.",115,2,3,113,"La sandía; Estrofa suelta",0,4,"o",87,0,-1,0,189,189,"3875","",0,"","","",1,0,0,[],""],["frenk_t2-n3876",6,"Ya me voy para Laredo (mi bien),\nte vengo a decir adiós;\nde allá te mando decir (mi bien)\ncómo se mancuernan dos.",105,2,-1,113,"Corrido de Laredo",3,4,"o",87,0,-1,0,189,189,"3876","",0,"","","",1,0,0,[],""],["frenk_t2-n3877",6,"Yo también soy libertino,\ny no me hago del rogar;\nvoy por tu mismo camino,\npor si le quieres sesgar.",105,2,-1,113,"Gallo tapado",1,4,"a",21,0,-1,0,189,189,"3877","",0,"","","",1,0,0,[],""],["frenk_t2-n3878",6,"Si saber quieres quién soy,\nvamos jugando un conquián,\na ver si conmigo pierdes\nhasta el modito de andar.",115,2,3,113,"El muchacho alegre; Tú sabías que era borracho",0,4,"a",-1,0,-1,0,189,189,"3878","",0,"","","",1,0,0,[],""],["frenk_t2-n3879",6,"En una baraja nueva\nte quisiera ver jugar;\ntú dices que nunca pierdes,\ntodo se te va en ganar:\na ver si conmigo pierdes\nhasta el modito de andar.",108,2,8,113,"Indita del alma",9,6,"a",21,0,-1,0,189,189,"3879","",0,"","","",1,0,0,[],""],["frenk_t2-n3881",6,"Tú bien sabías que era borracho:\nde las cantinas me fuiste a sacar,\ny ahora cabresteas o te horcas,\npero de mí no te has de burlar.",121,2,26,113,"Él borracho",3,4,"a",21,0,-1,0,190,190,"3881","",0,"","","",1,0,0,[],""],["frenk_t2-n3882",6,"Si crees que vas a burlarte\nde mi cariño sincero,\nantes habré de matarte,\no yo en la raya me muero,\npero tengo que enseñarte\na respetarme primero.",105,2,-1,113,"Tres balas",9,6,"eo",38,0,-1,0,190,190,"3882","",0,"","","",1,0,0,[],""],["frenk_t2-n3884",6,"Ya porque tú andas con tanto garbo\ny los zapatos rechinas,\nconmigo no juegas, conmigo no juegas:\nlo que es conmigo, te espinas.",105,2,-1,113,"La pantera vaciladora",3,4,"ia",243,0,-1,0,190,190,"3884","",0,"","","",1,0,0,[],""],["frenk_t2-n3885",6,"Toda la calle pa arriba\ncorre la agua cristalina;\npise bien, no se resbale,\nporque conmigo se espina.",110,2,10,113,"Toda la calle pa arriba*",0,4,"ia",11,0,-1,0,190,190,"3885","",0,"","","",2,0,0,[],""],["frenk_t2-n3886",6,"En una mesa te puse\nun plato con tres sardinas;\ncon otros habrás jugado,\npero conmigo te espinas.",114,2,17,113,"Bonito San Juan del Río; María, María**, Soy virgencita; Estrofa suelta",0,4,"ia",243,0,-1,0,190,190,"3886","",0,"","","",7,0,0,[],""],["frenk_t2-n3887",6,"En una mesa te puse\nun plato con tres anonas;\ncon otras habrás jugado,\npero conmigo te amólas.",105,2,-1,113,"Bonito San Juan del Río",0,4,"oa",-1,0,-1,0,191,191,"3887","",0,"","","",7,0,0,[],""],["frenk_t2-n3888",6,"El pájaro carpintero\npara trabajar se empina,\ny en llegando al agujero\nhasta el pico le rechina;\ncon otros habrás jugado,\npero conmigo te espinas.",105,2,-1,113,"El pájaro carpintero",9,6,"ia",-1,0,-1,0,191,191,"3888","",0,"","","",9,0,0,[],""],["frenk_t2-n3889",6,"Con muchos habrás jugado\npero conmigo no puedes;\npuedes hacer lo que quieras,\nno más ten mucho cuidado:\ntengo tres balas conmigo\npara cuando tú me falles.",105,2,-1,113,"Tres balas",9,6,"ae",-1,0,-1,0,191,191,"3889","",0,"","","",1,0,0,[],""],["frenk_t2-n3890",6,"En la punta de aquella higuera\nme subí a bajar un higo;\nno bajé ni uno siquiera,\ny por eso te lo digo:\nyo no soy mono de cera,\npara que jueguen conmigo.",108,2,8,113,"Estrofa suelta",9,6,"io",106,0,-1,0,191,191,"3890","",0,"","","",1,0,0,[],""],["frenk_t2-n3891",6,"No soy muñeca de cera,\npara que juegues conmigo;\nvete a jugar con tu abuela,\nla que te cortó el ombligo.",106,2,4,113,"Estrofa suelta",0,4,"io",106,0,-1,0,191,191,"3891","",0,"","","",1,0,0,[],""],["frenk_t2-n3892",6,"Parece que usted no entiende\nel modo con que lo trato;\nasí, pobrecito duende,\nnada de arañar al gato.",105,2,-1,113,"Estrofa suelta",1,4,"ao",19,0,-1,0,191,191,"3892","",0,"","","",1,0,0,[],""],["frenk_t2-n3893",6,"Tú eres un fino metal,\nque en el oro es conocido;\nno intento pagarte mal\nsi te portas bien conmigo,\npero si me pagas mal,\npor Dios, que ni adiós te digo.",105,2,-1,113,"El siquisirí",9,6,"io",106,0,-1,0,191,191,"3893","",0,"","","",1,0,0,[],""],["frenk_t2-n3894",6,"Tengo un vaso de cristal,\nque me regaló Cupido,\ndonde te he de colocar\nsi te portas bien conmigo,\npero si te portas mal,\nsabrás que ni adiós te digo.",108,2,8,113,"Estrofa suelta, El Cupido",9,6,"io",106,0,-1,0,191,191,"3894","",0,"","","",1,0,0,[],""],["frenk_t2-n3896",6,"No te arrejuntes tanto,\nporque mé pones furioso;\nsi me incitas, es lo mismo,\nporque voy a ser celoso.",112,2,6,113,"De mañana en ocho días",0,4,"oo",160,0,-1,0,192,192,"3896","",0,"","","",1,0,0,[],""],["frenk_t2-n3897",6,"Mi vida, tú eres la fuente\ndonde se cuaja la nieve,\n........................ hermoso;\ncuídate como se debe,\nporque mi amor es celoso (¡ay de la rosa,\nya sabes lo que sucede. [rosita!):",105,2,-1,113,"La Rosita",9,6,"ia",-1,0,-1,0,192,192,"3897","",0,"","","",1,0,0,[],""],["frenk_t2-n3898",6,"Te equivocas, te equivocas,\nfresco......... de capullo,\nyo quebrantaré ese orgullo\ncomo Cícero a la roca;\nya la luz ya me provoca,\ndijo el sol: “Voy a alumbrar”;\ntú eres espuma, yo mar,\ny en tu cólera confía:\nsi me haces llorar un día,\nyo también te haré llorar.",106,2,4,113,"Estrofa suelta",18,10,"a",21,0,-1,0,192,192,"3898","",0,"","","",2,0,0,[],""],["frenk_t2-n3899",6,"Vuela, vuela, vuela,\nvolando viene y volando va;\nte voy a cortar las alas\npara que no vueles más.",106,2,4,113,"La guacamaya",3,4,"a",-1,0,-1,0,192,192,"3899","",0,"","","",17,0,0,[],""],["frenk_t2-n3900",6,"Vuela, vuela, vuela, vuela,\nque vuela, vuela, voladora;\nte cortaré las alas\npara que no seas traidora.",106,2,4,113,"La guacamaya",0,4,"oa",107,0,-1,0,192,192,"3900","",0,"","","",1,0,0,[],""],["frenk_t2-n3901",6,"Te voy a cortar las alas\npara que no te vayas de mí;\nya sin alas, ¿dónde vas?,\ntienes que quedarte aquí.",105,2,-1,113,"Te voy a cortar las alas",3,4,"i",23,0,-1,0,192,192,"3901","",0,"","","",1,0,0,[],""],["frenk_t2-n3902",6,"Hora lo verás, paloma,\ncómo contigo quebranto;\nte he de cortar las patitas\npara que no bailes tanto.",109,2,7,113,"El palomo",0,4,"ao",30,0,-1,0,193,193,"3902","",0,"","","",1,0,0,[],""],["frenk_t2-n3903",6,"No te muevas tanto\npara caminar:\nte juro que nunca\nte vuelvo a sacar.",105,2,-1,113,"Los celotes",0,4,"a",21,0,-1,0,193,193,"3903","",0,"","","",1,0,0,[],""],["frenk_t2-n3904",6,"Ingrata, tierna y vil,\nla soga vas arrastrando;\nno te descuides volando (¡ay, Soledad, So-\ny te apague yo el candil\ncon que estás alumbrando.",105,2,-1,113,"La Petenera",7,5,"ao",33,0,-1,0,193,193,"3904","",0,"","","",1,0,0,[],""],["frenk_t2-n3905",6,"No quiero que andes con otro\nni que andes de canelera,\nporque ahorita nos veremos,\nsea por bien o como quiera.",127,2,18,113,"La canelera",0,4,"ea",44,0,-1,0,193,193,"3905","",0,"","","",1,0,0,[],""],["frenk_t2-n3906",6,"Pero vas con la advertencia\nque si yo tengo un rival,\nyo le he de quitar la vida,\naunque sea tu caporal.",105,2,-1,113,"A los ángeles del cielo",0,4,"a",1,0,-1,0,193,193,"3906","",0,"","","",1,0,0,[],""],["frenk_t2-n3907",6,"Tengo tres balas conmigo\npara cuando tú me falles;\nahora no soy tu enemigo,\npero mañana, ¡quién sabe!",105,2,-1,113,"Tres balas",0,4,"ae",-1,0,-1,0,193,193,"3907","",0,"","","",1,0,0,[],""],["frenk_t2-n3908",6,"No me andes jugando contras\nporque te puede pesar;\nrecuerda que en esta vida\ntodo se te ha de cobrar.",105,2,-1,113,"Jugando contras",0,4,"a",21,0,-1,0,193,193,"3908","",0,"","","",1,0,0,[],""],["frenk_t2-n3909",6,"[ledad!),\nMe dice mi corazón\nque tú me estás engañando:\nmientras yo estoy de plantón,\ntú con otro vacilando;\nsi me estás jugando contras,\nte puedes ir confesando.",105,2,-1,113,"Jugando contras",4,7,"ao",33,0,-1,0,193,193,"3909","",0,"","","",0,0,0,[],""],["frenk_t2-n3910",6,"Cecilia, no te has de casar,\nmenos si no has de ser mía;\nCecilia, no te veré casada,\npor bonita y por honrada.\nA mí me gusta la paseada,\nmayormente si es de día.",113,2,2,113,"La Cecilia",9,6,"ia",0,0,-1,0,193,193,"3910","",0,"","","",1,0,0,[],""],["frenk_t2-n3911",6,"Corté la flor de algodón\nporque la vide en capullo.\nNo te llenes de ilusión,\nno es vanidad ni es orgullo:\nyo te doy mi corazón,\npero si me das el tuyo.",105,2,-1,114,"El siquisirí; Estrofa suelta",9,6,"uo",78,0,-1,0,194,194,"3911","",0,"","","",1,0,0,[],""],["frenk_t2-n3912a",6,"Ya me voy a despedir,\npalo de la hoja morada;\nmuéstrame todo tu amor,\nsi no, no me muestres nada.",105,2,-1,114,"Ya te he dicho que no vayas; Por lo doy cincuenta; Estrofa suelta",0,4,"aa",49,0,-1,0,194,194,"3912a","",0,"","","",13,0,0,[],""],["frenk_t2-n3912c",6,"Alto pino del olvido,\npalo de la hoja morada,\nmuéstrame tu amor,\nsi no, no me muestres nada;\npero sí vive divertida:\nque un bien con un mal se paga.",108,2,8,114,"Estrofa suelta",9,6,"aa",-1,0,-1,0,194,194,"3912c","",0,"","","",1,0,0,[],""],["frenk_t2-n3913",6,"Si quieres que yo te quiera\ny que los dos nos queramos,\nnos ha de entrar el amor\ndonde los dos nos miramos,\ndonde nos dimos un beso\ny después nos abrazamos.",105,2,-1,114,"Estrofa suelta",9,6,"ao",116,0,-1,0,194,194,"3913","",0,"","","",23,0,0,[],""],["frenk_t2-n3914a",6,"Si me quieres, sé querer,\nsi me olvidas, sé olvidar,\nsi me la pegas, pegar:\nque amar es corresponder",105,2,-1,114,"Estrofa suelta",11,4,"e",20,0,-1,0,194,194,"3914a","",0,"","","",4,0,0,[],""],["frenk_t2-n3915",6,"¡Y áhi no más y áhi no más!,\ntoda la vida será\nque si me olvidas, te olvido,\nporque me sé desquitar.",105,2,-1,114,"El maracumbé",3,4,"a",-1,0,-1,0,195,195,"3915","",0,"","","",2,0,0,[],""],["frenk_t2-n3916",6,"Dime si ya te enojastes:\nque no me hablas te agradezco;\ndel mismo genio soy yo,\nque cuando quiero aborrezco.",108,2,8,114,"Estrofa suelta",0,4,"eo",355,0,-1,0,195,195,"3916","",0,"","","",1,0,0,[],""],["frenk_t2-n3917",6,"Si acaso, mi amor eterno,\nque no me hables te agradezco,\nporque soy de Cisca yo,\nque como quiero aborrezco\ny quedo como si no.",105,2,-1,114,"El sacamandú",7,5,"o",2,0,-1,0,195,195,"3917","",0,"","","",1,0,0,[],""],["frenk_t2-n3918",6,"¿Para qué son tantos brincos\nestando el piso parejo?\nSépase usted, señorita,\nque antes que me dejen, dejo.",105,2,-1,114,"Estrofa suelta",0,4,"eo",264,0,-1,0,195,195,"3918","",0,"","","",1,0,0,[],""],["frenk_t2-n3919",6,"Soy como la ola del mar\nque antes que dejen, dejo;\nsi a usted le parece bien,\nbusque quien le de un consejo;\npara mí todo es igual:\nsiempre le pego parejo.",108,2,8,114,"Estrofa suelta",9,6,"eo",264,0,-1,0,195,195,"3919","",0,"","","",1,0,0,[],""],["frenk_t2-n3920",6,"Sembré mi milpa de trigo\ny en tiempo de temporil.\nSi quieres, como te digo,\nsi no, para mí es igual:\nlos tratos como enemigo,\nla voluntá en su lugar.",112,2,6,114,"Los chiles verdes",9,6,"a",-1,0,-1,0,195,195,"3920","",0,"","","",1,0,0,[],""],["frenk_t2-n3921a",6,"Una calandria al volar\nse le desplumó el copete;\nsi no me quieres hablar,\nte pago y te doy ribete.",115,2,3,114,"La calandria",1,4,"ee",285,0,-1,0,195,195,"3921a","",0,"","","",1,0,0,[],""],["frenk_t2-n3922",6,"Ellos no me importan,\n[ni] pena me da:\nsi tú no me quieres,\nte mando a volar.",105,2,-1,114,"La vieja presumida",0,4,"a",-1,0,-1,0,196,196,"3922","",0,"","","",1,0,0,[],""],["frenk_t2-n3923",6,"No me busques por vereda (mi bien),\nbúscame por travesía:\nallá encontrarás si quieres (mi bien)\nel amor que te tenía.",115,2,3,114,"Corrido de Laredo",3,4,"ia",0,0,-1,0,196,196,"3923","",0,"","","",1,0,0,[],""],["frenk_t2-n3925",6,"Para que conmigo vuelvas,\nhe de publicar un bando:\nque te he vuelto a recoger,\npero como de antes, ¡cuándo!",105,2,-1,114,"Estrofa suelta",0,4,"ao",33,0,-1,0,196,196,"3925","",0,"","","",1,0,0,[],""],["frenk_t2-n3926",6,"Dices que me quieres mucho:\nno me subas tan arriba,\nque las hojas en el árbol\nno duran toda la vida.",105,2,-1,114,"Las copetonas; Margarita; El tejón; El venadito; Estrofa suelta",0,4,"ia",-1,0,-1,0,196,196,"3926","",0,"","","",13,0,0,[],""],["frenk_t2-n3927",6,"Dices que me quieres mucho:\nno más no lo andes contando;\nno te vayas a quedar,\ncomo los guajes, colgando.",107,2,11,114,"La chinita; La Julia; Estrofa suelta",0,4,"ao",33,0,-1,0,196,196,"3927","",0,"","","",13,0,0,[],""],["frenk_t2-n3928",6,"Debajo de un huizachito\npuso su nido un conejo.\nNo te engrías tanto conmigo,\nporque me voy y te dejo,\ny después te irás contando\nla vida de San Alejo.",107,2,11,114,"El conejo",9,6,"eo",264,0,-1,0,197,197,"3928","",0,"","","",1,0,0,[],""],["frenk_t2-n3929",6,"Corazón humano, ¿adónde vas?,\n¿adónde, hermoso lucero?\nSólo mi Dios paga bien,\ny yo también cuando quiero.",108,2,8,114,"Chilena de Jamiltepec",3,4,"eo",38,0,-1,0,197,197,"3929","",0,"","","",1,0,0,[],""],["frenk_t2-n3930",6,"Como la amo con empeño,\nparece que se me enoja;\nno más la cacha le enseño:\nno piense que toda la hoja.",105,2,-1,114,"Estrofa suelta",1,4,"oa",146,0,-1,0,197,197,"3930","",0,"","","",1,0,0,[],""],["frenk_t2-n3934",6,"Cupido me dijo a mí\nque anduviera alerta, alerta:\nyo no soy como tu muía\nque carga la trompa abierta.",108,2,8,114,"Estrofa suelta",0,4,"ea",267,0,-1,0,197,197,"3934","",0,"","","",3,0,0,[],""],["frenk_t2-n3936",6,"Suca, machuca y maruca,\nsuca, maruca y andando,\ny aunque te mueras de celos,\nyo siempre me ando paseando.",105,2,-1,114,"El Jerez",0,4,"ao",33,0,-1,0,198,198,"3936","",0,"","","",2,0,0,[],""],["frenk_t2-n3938",6,"Ya bien te lo decía,\ny tú no lo querías creer,\nque en saliendo pa la calle\nme tendrías que perder.",105,2,-1,114,"El jarabe",3,4,"e",20,0,-1,0,198,198,"3938","",0,"","","",1,0,0,[],""],["frenk_t2-n3939",6,"Mira, no seas ventajosa,\ntú gozas de lo mejor;\nsupiste que era casado\ny que tenía obligación.",105,2,-1,114,"Canción del Interior",0,4,"o",-1,0,-1,0,198,198,"3939","",0,"","","",1,0,0,[],""],["frenk_t2-n3940",6,"Supiste que era borracho,\nque jugaba en el billar,\nsupiste todos mis vicios:\n¿qué te ganas con llorar?",115,2,3,114,"La chinita; Alza los ojos; Estrofa suelta",0,4,"a",21,0,-1,0,198,198,"3940","",0,"","","",1,0,0,[],""],["frenk_t2-n3941",6,"Tú sabías que era borracho:\n¿qué te ganas con llorar?\n¡Y arriba los siete vicios,\ntambién el juego al billar!",129,2,9,114,"Tú sabías que era borracho",0,4,"a",21,0,-1,0,198,198,"3941","",0,"","","",1,0,0,[],""],["frenk_t2-n3942",6,"Otra cosa le diré\npara que la tome en cuenta:\nque en mi pobre jacalito\nsólo mi sombrero entra.",105,2,-1,112,"Estrofa suelta",0,4,"ea",-1,0,-1,0,201,201,"3942","",0,"","","",1,0,0,[],""],["frenk_t2-n3943",6,"Lo que sí les aseguro\ny no lo tardo en saber:\nque yo soy el único hombre\nque es dueño de esa mujer.",120,2,14,112,"Ámame, bien de mi vida",0,4,"e",20,0,-1,0,201,201,"3943","",0,"","","",5,0,0,[],""],["frenk_t2-n3944",6,"Lo que sí les aseguro\ny ustedes lo van a ver:\nque pronto sé quién es dueño\ndel amor de esa mujer.",120,2,14,112,"Chaparrita de los naranjos",0,4,"e",20,0,-1,0,201,201,"3944","",0,"","","",5,0,0,[],""],["frenk_t2-n3945",6,"Con cuidado, mis amigos,\nno se les vaya a olvidar:\nde esa joven soy el dueño,\nno se vayan a enredar.",105,2,-1,112,"Ojitos negros chinitos",0,4,"a",21,0,-1,0,201,201,"3945","",0,"","","",1,0,0,[],""],["frenk_t2-n3946",6,"De arriba del cielo cayó una pera,\nde una pera, una sandía;\ntodos quieren a la güera,\npero la güera ya es mía.",106,2,4,112,"Estrofa suelta",3,4,"ia",0,0,-1,0,201,201,"3946","",0,"","","",1,0,0,[],""],["frenk_t2-n3947",6,"En esta calle derecha\nhay cien varas de listón;\nonde pasa mi negrita\nno pasa ningún cabrón.",126,2,19,112,"Estrofa suelta",0,4,"o",31,0,-1,0,201,201,"3947","",0,"","","",3,0,0,[],""],["frenk_t2-n3948",6,"Por las calles de mi casa\ncorre sangre de un oso;\npor donde pasa mi amor\nno pasa ningún baboso.",120,2,14,112,"Estrofa suelta",0,4,"oo",160,0,-1,0,201,201,"3948","",0,"","","",1,0,0,[],""],["frenk_t2-n3949",6,"Corre, anda y dile a aquel amigo,\nque anda bailando con aquella joven,\nque si es mi amigo, que no se enrede\ncon los amores con quien estoy engrido.",120,2,14,112,"Corazón sólido",3,4,"io",-1,0,-1,0,201,201,"3949","",0,"","","",1,0,0,[],""],["frenk_t2-n3951",6,"Ya con ésta me despido,\nya me voy para La Joya.\nRetírate gavilán,\nque no es para ti la polla:\nsi acaso, te tocarán\nlos asientos de la olla.",105,2,-1,112,"‘Έ1 venadito; Estrofa suelta",9,6,"oa",453,0,-1,0,202,202,"3951","",0,"","","",72,0,0,[],""],["frenk_t2-n3952",6,"Dice mi amor que si pierde,\nla polvareda levanta,\nque si es buen gallo, le canta,\ny si periquito, es verde.",105,2,-1,112,"El perico",11,4,"ee",154,0,-1,0,202,202,"3952","",0,"","","",1,0,0,[],""],["frenk_t2-n3953",6,"Lo que sí les aseguro,\nporque ya me voy a ir,\nsólo por no verla ir;\nque trayendo aquí pistola\nyo también me sé morir.",115,2,3,112,"Eres alta y delgadita",7,5,"i",157,0,-1,0,202,202,"3953","",0,"","","",5,0,0,[],""],["frenk_t2-n3954",6,"Barrio alegre,\nqué ganas tenía de verte,\ntú me vas a consolar;\ntodavía traigo cartuchos\npara poderles pelear,\nque por una de este barrio\nla vida me han de quitar.",115,2,3,112,"Barrio alegre",4,7,"a",21,0,-1,0,202,202,"3954","",0,"","","",2,0,0,[],""],["frenk_t2-n3955",6,"Las estrellas en el cielo\nbrillan como las espadas;\nyo no le temo al acero,\nni a pistolas preparadas:\npor la hembra que yo quiero,\naunque muera a puñaladas.",105,2,-1,112,"El siquisirí",9,6,"aa",282,0,-1,0,202,202,"3955","",0,"","","",18,0,0,[],""],["frenk_t2-n3956",6,"Nada importa hallar la muerte\nen la reja de una ingrata,\no llevar en la conciencia\notra culpa por matar.",105,2,-1,112,"Jalisco nunca pierde",5,4,"a",-1,0,-1,0,202,202,"3956","",0,"","","",1,0,0,[],""],["frenk_t2-n3957",6,"Y si un amor hace poco\ny no le encuentro salida,\nsi algún amante loco\npiensa quitarme la vida,\nsoy hombre y no me sofoco,\nya tengo la edad cumplida.",106,2,4,112,"Estrofa suelta",9,6,"ia",37,0,-1,0,203,203,"3957","",0,"","","",1,0,0,[],""],["frenk_t2-n3958",6,"Dicen que me han de matar\ncon una daga bonita;\nlas heridas que me den\nme las cura Mariquita.",115,2,3,112,"María, María",0,4,"ia",50,0,-1,0,203,203,"3958","",0,"frenk_t4","","",20,0,0,[],""],["frenk_t2-n3959b",6,"¡Ay, cómo me duele el anca!\n¡Ay, cómo me aprieta el cincho!\nQué vas que brinco esa tranca,\npa ver si del golpe me hincho.\n¡Que habiendo tanta potranca,\nsólo por la mía relincho!",105,2,-1,113,"El pájaro carpintero; Las barrancas",9,6,"io",560,0,-1,0,204,204,"3959b","",0,"","","",1,0,0,[],""],["frenk_t2-n3960",6,"Voy a salir a campear\ncon rumbo pa la Huasteca,\na ver si puedo lazar\nuna novillona prieta,\nque la quiero señalar\nde tarabilla y paleta.",113,2,2,113,"El caballito",9,6,"ea",200,0,-1,0,204,204,"3960","",0,"","","",3,0,0,[],""],["frenk_t2-n3961",6,"Rema, guarecita, rema,\nrema para San Miguel;\nya se reventó la reata,\n¿con qué otra la lazaré?",109,2,7,113,"La guarecita; Canción de Morelos",0,4,"e",-1,0,-1,0,204,204,"3961","",0,"frenk_t4","","",8,0,0,[],""],["frenk_t2-n3962",6,"¡Ay!, corazón bandolero,\nrelincha ya cuando quieras\npor esa potranca fina,\nque amansarás cuando quieras;\ntú y yo no tenemos prisa:\náhi nos quedrá cuando quiera.",105,2,-1,113,"No soy monedita de oro",9,6,"ea",-1,0,-1,0,204,204,"3962","",0,"","","",1,0,0,[],""],["frenk_t2-n3963",6,"La yegua de mi comadre\nyo la voy a jinetear,\na ver si conmigo pierde\nhasta el modito de andar.",115,2,3,113,"La potranquita",0,4,"a",21,0,-1,0,204,204,"3963","",0,"","","",1,0,0,[],""],["frenk_t2-n3965",6,"Ya viene saliendo el sol\nen un arco de colores.\nDéjalo que se pasee,\ndéjalo que corte flores:\nalgún día le enseñaré\ncómo trate a los amores.",112,2,6,113,"Estrofa suelta",9,6,"oe",5,0,-1,0,205,205,"3965","",0,"","","",1,0,0,[],""],["frenk_t2-n3966",6,"Esta noche con la luna,\nmañana con el sereno;\n¿dónde ha de ir esa mujer,\nteniendo mi perro bueno?",108,2,8,113,"La garza; La garbosa",0,4,"eo",76,0,-1,0,205,205,"3966","",0,"","","",4,0,0,[],""],["frenk_t2-n3967",6,"Soy huasteco, no lo niego,\nnací muy cerca del mar;\nel orgullo que yo llevo,\nque nunca le sé rogar;\nme gusta verla pidiendo\nremedio para olvidar.",111,2,1,113,"El gusto; La leva",9,6,"a",21,0,-1,0,205,205,"3967","",0,"","","",1,0,0,[],""],["frenk_t2-n3968",6,"Dicen que Cupido es muerto,\nque lo mató una mujer;\nsi Cupido fuera muerto,\nya me mandarían prender.",106,2,4,115,"El Cupido",1,4,"e",20,0,-1,0,209,209,"3968","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n3969",6,"Ya con ésta me despido,\ncantando con mi guitarra;\nyo soy afecto a Cupido\ny me voy con mi chaparra;\nel hombre que quiere mucho\nsólo del diablo se agarra.",105,2,-1,115,"Los paseos de Santa Anita**",9,6,"aa",308,0,-1,0,209,209,"3969","",0,"","","",72,0,0,[],""],["frenk_t2-n3970",6,"Yo soy un hombre correcto,\npero muy enamorado;\npero ése no es un defecto,\npero es ser desvergonzado.",112,2,6,115,"La huazanga",1,4,"ao",14,0,-1,0,209,209,"3970","",0,"","","",1,0,0,[],""],["frenk_t2-n3971",6,"Soy águila real,\nme subo al nopal,\ndevoro la víbora\ndel amor.",105,2,-1,115,"Pancho Nopales",6,4,"o",-1,0,-1,0,209,209,"3971","",0,"","","",1,0,0,[],""],["frenk_t2-n3972",6,"Yo le fajo a la mujer\nsin saber cómo ni cuándo,\ny si no lo quieren creer,\nya le estamos, dimos, dando.",122,2,13,115,"Estrofa suelta",1,4,"ao",33,0,-1,0,209,209,"3972","",0,"","","",1,0,0,[],""],["frenk_t2-n3973",6,"Ya me voy y me despido\ny pronto daré la vuelta,\nporque mucho me han engrido\nlos jardines de esta huerta.",112,2,6,115,"Estrofa suelta",0,4,"ea",-1,0,-1,0,209,209,"3973","",0,"","","",2,0,0,[],""],["frenk_t2-n3974",6,"Me gusta el amor hermoso,\nel mundo lo puede ver;\nme gusta la siembra de otro\nal tiempo de recoger.",105,2,-1,115,"La Sanmarqueña",0,4,"e",20,0,-1,0,209,209,"3974","",0,"","","",1,0,0,[],""],["frenk_t2-n3976",6,"Soy un triste pajarito,\nque por el monte gorjeo,\ny aunque soy muy pobrecito,\nnada del mundo deseo;\nyo gusto de lo bonito,\nde lo bueno y de lo feo.",105,2,-1,115,"El pájaro cú",9,6,"eo",66,0,-1,0,210,210,"3976","",0,"","","",2,0,0,[],""],["frenk_t2-n3977",6,"Prendió la flor del requemo\nal poder tener la güera;\npor eso yo canto aquí,\nsiendo mujer, a cualquiera.",108,2,8,115,"La guacamaya",0,4,"ea",44,0,-1,0,210,210,"3977","",0,"","","",1,0,0,[],""],["frenk_t2-n3979",6,"Y a la jota, jota,\nsi es soltera, es lo mismo,\nsi es casada, mejor:\nde cualquier manera\narrincónenmela áhi.",105,2,-1,115,"¿Dónde vas, Isabel?",7,5,"ai",-1,0,-1,0,210,210,"3979","",0,"","","",1,0,0,[],""],["frenk_t2-n3980",6,"En la calle del Reloj\nle di cuerda a mi fortuna;\nporque el hombre que es tunante\nno se conforma con una:\nsiempre quiere tener dos,\npor si se enojare alguna.",105,2,-1,115,"El turronero",9,6,"ua",56,0,-1,0,210,210,"3980","",0,"","","",1,0,0,[],""],["frenk_t2-n3981",6,"Querer una no es ninguna,\nquerer dos es necedad,\nquerer unas cuatro o cinco\nes gracia y habilidad.",114,2,17,115,"Estrofa suelta",0,4,"a",16,0,-1,0,210,210,"3981","",0,"frenk_t4","","",7,0,0,[],""],["frenk_t2-n3982",6,"Muchachas, mírenme bien\nmi sombrero apanterado,\nque yo soy hombre de bien;\nyo no soy enamorado\nmientras si no hallo con quién.",106,2,4,115,"El sombrero; El querreque",7,5,"e",242,0,-1,0,211,211,"3982","",0,"","","",1,0,0,[],""],["frenk_t2-n3983",6,"Yo soy de un tiempo que hacía\nlo que me daba la gana;\nvarias sombritas tenía\ny la conciencia muy sana,\nporque entonces me decía:\n“Tres veces a la semana.”",106,2,4,115,"El siquisirf*",9,6,"aa",4,0,-1,0,211,211,"3983","",0,"","","",1,0,0,[],""],["frenk_t2-n3984a",6,"Florearon mis amapolas\nen el mes de abril y mayo;\nsólo le temo a un gallo,\nporque mis gallinas andan solas.",113,2,2,115,"Estrofa suelta",3,4,"oa",317,0,-1,0,211,211,"3984a","",0,"","","",1,0,0,[],""],["frenk_t2-n3985",6,"¡Ay, Soledad, Soledad!,\nponle gracia y tráenos vino,\nque yo para enamorar\nno necesito padrino.",105,2,-1,116,"La Petenera",3,4,"io",199,0,-1,0,212,212,"3985","",0,"","","",18,0,0,[],""],["frenk_t2-n3987",6,"Todos me dicen el negro (Llorona),\nnegro pero cariñoso;\nyo soy como el chile verde (Llorona):\npicante pero sabroso.",105,2,-1,116,"La Llorona; La Zandunga; Estrofa suelta",3,4,"oo",160,0,-1,0,212,212,"3987","",0,"","","",1,0,0,[],""],["frenk_t2-n3988",6,"¡Ay, curras engrandecidas!,\n¡miren cuán serias se van!\nAl cabo yo soy de arroz,\ny me han de comer en pan.",105,2,-1,116,"Estrofa suelta",0,4,"a",147,0,-1,0,212,212,"3988","",0,"","","",1,0,0,[],""],["frenk_t2-n3989",6,"Ya pasó Tío Todosantos,\nse acabaron su pipián;\nyo no soy de los que dicen:\n“Si hay, si sobra, me darán”:\nal cabo yo soy arroz,\ny a mí me comen con pan.",108,2,8,116,"Estrofa suelta",9,6,"a",147,0,-1,0,212,212,"3989","",0,"","","",1,0,0,[],""],["frenk_t2-n3990",6,"Uso sombrero petate\nporque así lo están usando;\nparece flor de aguacate\ncuando ya está madurando;\na mí me sobra mecate\npa seguirlas mancornando.",112,2,6,116,"El sombrerito; El toro requesón",9,6,"ao",33,0,-1,0,212,212,"3990","",0,"","","",1,0,0,[],""],["frenk_t2-n3991",6,"Me cuadra ser decidido\ny eso no voy a negarlo;\nde las mujeres querido,\ny estoy para demostrarlo;\nes mi compadre Cupido,\ny no voy a defraudarlo.",105,2,-1,116,"La oveja perdida",9,6,"ao",236,0,-1,0,213,213,"3991","",0,"","","",1,0,0,[],""],["frenk_t2-n3992",6,"Me llamo Pancho Nopales\ny vivo entre las flores;\nellas son las que se ofrecen,\nrogando con sus amores;\nyo sólito pienso y digo:\n“¿A quién le dan pan que llore?’",105,2,-1,116,"Pancho Nopales",9,6,"oe",-1,0,-1,0,213,213,"3992","",0,"","","",1,0,0,[],""],["frenk_t2-n3993",6,"Las mujeres me persiguen,\npero eso no es cosa mía,\ny si dinero me piden,\nse los doy con alegría,\npara que nunca se olviden\ndel albañil algún día.",105,2,-1,116,"El albañil",9,6,"ia",0,0,-1,0,213,213,"3993","",0,"","","",1,0,0,[],""],["frenk_t2-n3994",6,"A mí me sobran los pesos\ny los medios de carita;\nsi las viejas me desprecian,\nlas muchachas hasta me gritan.",108,2,8,116,"Estrofa suelta",0,4,"ia",-1,0,-1,0,213,213,"3994","",0,"","","",1,0,0,[],""],["frenk_t2-n3996a",6,"Soy caimán altamireño\ndel río de Tantoyuquita;\ncuando miro una sin dueño\nno más le hago una señita,\ny se me arrima con empeño.",113,2,2,116,"El caimán",7,5,"eo",138,0,-1,0,213,213,"3996a","",0,"","","",2,0,0,[],""],["frenk_t2-n3996c",6,"Soy caimán altamireño\nde allá de Tantoyuquita;\nyo estoy aquí satisfecho,\ncántale a tu huastequita;\nno más le hago una señita\ny me arrimo con empeño.",113,2,2,116,"El caimán",9,6,"eo",-1,0,-1,0,213,213,"3996c","",0,"","","",2,0,0,[],""],["frenk_t2-n3997",6,"Soy como la chuparrosa\nque se vive entre las flores;\nla vida quisiera larga,\nque a mí me sobran amores.",105,2,-1,116,"Ojitos color de olivo",0,4,"oe",5,0,-1,0,213,213,"3997","",0,"","","",1,0,0,[],""],["frenk_t2-n3998",6,"Me gustan los animales\nporque no tienen espinas;\ncada vez que veo huacales,\nme acuerdo de mis gallinas.",105,2,-1,116,"El fandanguito",1,4,"ia",243,0,-1,0,214,214,"3998","",0,"","","",1,0,0,[],""],["frenk_t2-n3999",6,"Yo soy el charro alemán,\nque enamoro con fortuna:\ncuatro cargo en el morral,\ny no se me afloja ni una.",105,2,-1,116,"La india",0,4,"ua",56,0,-1,0,214,214,"3999","",0,"","","",1,0,0,[],""],["frenk_t2-n4000",6,"Yo soy como gallo en palenque,\nyo en cualquier gancho me atoro;\nno le aunque que estén casadas:\nme gusta salirle al toro.",105,2,-1,116,"El dicharachero",0,4,"oo",85,0,-1,0,214,214,"4000","",0,"","","",1,0,0,[],""],["frenk_t2-n4001",6,"Todas las mulas están reunidas,\na todas juntas las tengo ya;\nla mula bronca que me faltaba\nleyendo el verso tranquila está.",130,2,21,116,"Estrofa suelta",3,4,"a",9,0,-1,0,214,214,"4001","",0,"","","",1,0,0,[],""],["frenk_t2-n4002",6,"Por una caña habanera\nha habido tantos enojos.\nYa puse mi ratonera,\nahora caerán por manojos;\nno la puse con cautela:\nmuchachos, abran los ojos.",108,2,8,116,"Estrofa suelta",9,6,"oo",99,0,-1,0,214,214,"4002","",0,"","","",1,0,0,[],""],["frenk_t2-n4003",6,"Yo soy aquel que me hallo\ny en cualquier parte del mapa;\ntodavía me sobra gallo\npara llevarme una guapa\ny arriba de mi caballo.",111,2,1,116,"El caballito",7,5,"ao",102,0,-1,0,214,214,"4003","",0,"","","",1,0,0,[],""],["frenk_t2-n4004",6,"Soy charro de Rancho Grande\ny hasta el amor bebo en jarro,\ny no hay potranca matrera\nque me tumbe, si me agarro.\nY ¡ay, qué mi Dios tan pantera\ncuando se viste de charro!",105,2,-1,116,"El caballo palomo",9,6,"ao",392,0,-1,0,214,214,"4004","",0,"","","",1,0,0,[],""],["frenk_t2-n4006",6,"Áhi viene el dicharachero;\nlas suegras se preocuparon\npor cuidar el gallinero,\ny por mucho que cuidaron\nlas pollas ya se escaparon\ny hasta mis brazos llegaron\ncon decirles que las quiero.",105,2,-1,116,"El dicharachero",4,7,"eo",38,0,-1,0,214,214,"4006","",0,"","","",3,0,0,[],""],["frenk_t2-n4007",6,"Por áhi viene el gavilán,\npor áhi viene ya volando;\nno se lo dejen llegar:\npollitas anda buscando.",106,2,4,116,"El gavilán",0,4,"ao",33,0,-1,0,215,215,"4007","",0,"","","",1,0,0,[],""],["frenk_t2-n4008",6,"Corran, corran a esconderse,\npollitas de la parvada,\nque el gavilán cuando baja\nno se levanta sin nada.",113,2,2,116,"El gavilán",0,4,"aa",-1,0,-1,0,215,215,"4008","",0,"","","",1,0,0,[],""],["frenk_t2-n4009",6,"Si tienes gallo, que grite:\n“¡Quiquiriquí, copetonas,\ndéjense de tantas bolas!\n¡Silencio, guapas pelonas!\nYa llegó el gallo mascota\na comerse a las pelonas.”",105,2,-1,116,"El indio",9,6,"oa",-1,0,-1,0,215,215,"4009","",0,"","","",1,0,0,[],""],["frenk_t2-n4010",6,"Ésas son las que me gustan,\nque ponen sobre el nidal.\n¡Asilénciense, aguilillas,\nya llegó su águila real!",116,2,15,116,"Las pollas",0,4,"a",1,0,-1,0,215,215,"4010","",0,"","","",1,0,0,[],""],["frenk_t2-n4011",6,"Ya llegó por quien lloraban,\nya no van a suspirar;\nsé muy bien que hasta extrañaban\ncómo yo puedo besar.",105,2,-1,116,"Chiquita pero picosa",1,4,"a",21,0,-1,0,215,215,"4011","",0,"","","",1,0,0,[],""],["frenk_t2-n4012",6,"Peloncitas guapetonas,\naquí traigo mi camión,\npa llevarlas y pasearlas\nde purito vacilón.",105,2,-1,116,"Ya no lloverá, pelonas",0,4,"o",31,0,-1,0,215,215,"4012","",0,"","","",1,0,0,[],""],["frenk_t2-n4014",6,"Ninguna mujer, ninguna,\nme ha robado el corazón;\ny he amado una por una,\npero a todas con pasión,\npero con amor, ninguna.",105,2,-1,117,"Ninguna mujer, ninguna; La azucena",7,5,"ua",56,0,-1,0,216,216,"4014","",0,"","","",1,0,0,[],""],["frenk_t2-n4015",6,"En este mundo ya no hay quien sobre:\nno ha de faltar quien me sepa querer;\npor la de buenas, que yo soy hombre,\ny no me engrío con ninguna mujer.",125,2,28,117,"Zenaida",3,4,"e",20,0,-1,0,216,216,"4015","",0,"","","",1,0,0,[],""],["frenk_t2-n4016",6,"Yo por eso no me engrío\nni con la más regia dama,\nporque al tiempo de morir\ncada quien muere en su cama.",108,2,8,117,"Estrofa suelta",0,4,"aa",90,0,-1,0,216,216,"4016","",0,"","","",1,0,0,[],""],["frenk_t2-n4017",6,"Yo soy el que siempre he sido\ncomo el caballo pastor,\ncomo con nadie me engrío,\na nadie le pongo amor.",108,2,8,117,"Estrofa suelta",0,4,"o",72,0,-1,0,216,216,"4017","",0,"","","",2,0,0,[],""],["frenk_t2-n4019",6,"Tafetán amarillo,\narroz de leche;\nyo jamás he tenido\ncelos de nadie.",105,2,-1,117,"Estrofa suelta",6,4,"ae",-1,0,-1,0,216,216,"4019","",0,"","","",1,0,0,[],""],["frenk_t2-n4020",6,"Las penas que vienen y van,\nlas penas no me hacen nada,\npa mi las penas son muías\nque no andan en mi manada.",105,2,-1,117,"El mundo es mío**",0,4,"aa",49,0,-1,0,217,217,"4020","",0,"","","",1,0,0,[],""],["frenk_t2-n4021",6,"Hora sí cualquier chata\npuede encontrarme con plata,\nporque mi tiempo llegó;\nque yo sólito me basto,\ny lo que daba de gasto\nhora me lo gasto yo.",105,2,-1,117,"La muía maicera**",9,6,"o",2,0,-1,0,217,217,"4021","",0,"","","",1,0,0,[],""],["frenk_t2-n4022",6,"Al pie de una parota\nyo vi correr un reloj.\nElla anda tan vanota\nporque andan juntos los dos;\nyo, como soy sólita,\nfuerte como el Santo Dios.",108,2,8,117,"Estrofa suelta",9,6,"o",87,0,-1,0,217,217,"4022","",0,"","","",1,0,0,[],""],["frenk_t2-n4023",6,"Soy como la yerbabuena,\nque donde quiera resplandezco;\ncon todos platico y río,\npero a ninguno apetezco.",106,2,4,117,"El ramo; El baulito*’; Estrofa suelta",0,4,"eo",355,0,-1,0,217,217,"4023","",0,"","","",3,0,0,[],""],["frenk_t2-n4024",6,"Dicen que soy presumida\nporque no les hago caso;\nsi me caen a la medida,\nsólo así les echo un lazo.",105,2,-1,117,"Chiquita pero picosa",1,4,"ao",43,0,-1,0,217,217,"4024","",0,"","","",1,0,0,[],""],["frenk_t2-n4025",6,"Tengo a San Antonio\npuesto de cabeza;\nno me busca novio,\nya no me interesa.",130,2,21,117,"Estrofa suelta",0,4,"ea",201,0,-1,0,217,217,"4025","",0,"","","",1,0,0,[],""],["frenk_t2-n4027",6,"Cupido fue el primer hombre\nque con el amor [rió].\nYo soy segundo Cupido:\n¿cómo no he de reírme yo?",105,2,-1,117,"El Cupido",0,4,"o",2,0,-1,0,217,217,"4027","",0,"","","",1,0,0,[],""],["frenk_t2-n4029",6,"Amigos, les contaré\nuna acción particular:\nsi me quieren, sé querer,\nsi me olvidan, sé olvidar.",105,2,-1,117,"La chancla",0,4,"a",21,0,-1,0,218,218,"4029","",0,"","","",3,0,0,[],""],["frenk_t2-n4030",6,"Soy pájaro carpintero,\nque me paro en la canal;\nsi me quieren, sé querer,\nsi me olvidan, sé olvidar,\nsi me las pegan, las pego,\nporque así es lo natural.",105,2,-1,117,"El pájaro carpintero",9,6,"a",-1,0,-1,0,218,218,"4030","",0,"","","",2,0,0,[],""],["frenk_t2-n4031",6,"Navegando en alta mar\nme dejó en pie la marea;\nme gusta verlas penar\ny que yo la causa sea.",105,2,-1,117,"Estrofa suelta",1,4,"ea",54,0,-1,0,218,218,"4031","",0,"","","",2,0,0,[],""],["frenk_t2-n4033",6,"A los solteros nos gustan\nlas linternas tricolor,\ny a las muchachas tarugas\nlas cambiamos de sabor.",105,2,-1,117,"Linternas y linternitas",0,4,"o",72,0,-1,0,218,218,"4033","",0,"","","",1,0,0,[],""],["frenk_t2-n4034",6,"Adiós, me despido, ingratas,\nya no quiero vuestro trato;\n¡ah, qué indinas son las ratas\nque quieren comerse al gato!",105,2,-1,117,"El cubilete",1,4,"ao",19,0,-1,0,218,218,"4034","",0,"","","",1,0,0,[],""],["frenk_t2-n4035",6,"Ya con ésta me despido,\nsubiendo y bajando lomas;\nhe quebrado cristal fino,\ncuantimás ollas terronas.",110,2,10,117,"Estrofa suelta",0,4,"oa",-1,0,-1,0,218,218,"4035","",0,"","","",72,0,0,[],""],["frenk_t2-n4036",6,"Traigo muy bellas mujeres,\nmuy pronto se han de acabar;\npara salir pronto de ellas,\nhoy las pienso rematar.",105,2,-1,117,"Estrofa suelta",0,4,"a",21,0,-1,0,218,218,"4036","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4037a",6,"Voy a hacer una barata\ny una gran realización:\nlas muchachas a tostón,\nlas viejas a seis centavos\ny las suegras de pilón.",108,2,8,117,"El venadito",7,5,"o",31,0,-1,0,219,219,"4037a","",0,"","","",2,0,0,[],""],["frenk_t2-n4037b",6,"Voy a, hacer una barata\ny una gran realización:\nlas viejitas a centavo,\nlas muchachas a tostón,\nlos yernos a seis centavos\ny las suegras de pilón.",107,2,11,117,"El venadito",9,6,"o",31,0,-1,0,219,219,"4037b","",0,"","","",2,0,0,[],""],["frenk_t2-n4038",6,"Desde que caí en la cuna\nme he vuelto muy remolón;\ncomo con nadie me engrío,\nporque al fin soy un cabrón,\nno más les pico la tuna\ny les dejo el cascarón.",108,2,8,117,"Estrofa suelta",9,6,"o",31,0,-1,0,219,219,"4038","",0,"","","",1,0,0,[],""],["frenk_t2-n4039",6,"Soy águila pinta y parda\nque en los tunales me siento;\nlas pico y las picoteo\ny las dejo para otro hambriento,\nque tenga más necesidad,\nque yo ni agravio ni sentimiento.",108,2,8,117,"Estrofa suelta",9,6,"eo",94,0,-1,0,219,219,"4039","",0,"","","",1,0,0,[],""],["frenk_t2-n4040",6,"Soy como tata Berdejo\nen eso de enamorar:\nlas amo, les doy parejo\ny me vuelvo a retirar,\na ver si llega un tontito\nque las venga a levantar.",105,2,-1,117,"Estrofa suelta",9,6,"a",21,0,-1,0,219,219,"4040","",0,"","","",1,0,0,[],""],["frenk_t2-n4041",6,"Soy como el mosco colmena,\nque todito me alboroto;\nla mujer que encuentro buena\ncomo quiera la abodoco:\ntodavía la dejo buena\npa que se vaya con otro.",112,2,6,117,"La presumida",9,6,"oo",-1,0,-1,0,219,219,"4041","",0,"","","",1,0,0,[],""],["frenk_t2-n4042",6,"Soy pollo; pero macizo,\ntengo más plumas que un gallo,\ndestiendo el ala y las piso,\ndespués, que las parta un rayo.",105,2,-1,117,"Estrofa suelta",1,4,"ao",293,0,-1,0,219,219,"4042","",0,"","","",1,0,0,[],""],["frenk_t2-n4043",6,"Voy a comenzar con Bacha\na cantar con mis amigos;\nhoy me gustan las muchachas\nde escasos años cumplidos,\nporque yo de las carcachas\nya estoy bastante aburrido.",106,2,4,117,"El pájaro cú",9,6,"io",-1,0,-1,0,220,220,"4043","",0,"","","",1,0,0,[],""],["frenk_t2-n4045",6,"Vamos haciendo un contrato,\nque ampara la ley moderna:\ncada cual por su camino,\ny la amistad que no se pierda.",107,2,11,118,"La indita",0,4,"ea",-1,0,-1,0,225,225,"4045","",0,"","","",1,0,0,[],""],["frenk_t2-n4046",6,"Ya vengo a darte las gracias\npor los días que nos quisimos;\nya vengo a darte las gracias\npor el tiempo que anduvimos.",112,2,6,118,"Estrofa suelta",1,4,"io",329,0,-1,0,225,225,"4046","",0,"","","",1,0,0,[],""],["frenk_t2-n4047",6,"Por mi parte, muchas gracias\ndel tiempo que nos quisimos;\nque algún día recordarás\nde los gustos que nos dimos.",105,2,-1,118,"Estrofa suelta, De mi parte, muchas gracias; Mariquita",0,4,"io",329,0,-1,0,225,225,"4047","",0,"","","",1,0,0,[],""],["frenk_t2-n4048",6,"Olvida que me amaste,\nolvídalo, te ruego,\nolvida que quisiste\ncon amor verdadero.",105,2,-1,118,"Olvida que me amaste",0,4,"eo",-1,0,-1,0,225,225,"4048","",0,"","","",1,0,0,[],""],["frenk_t2-n4049",6,"No estés triste, bella flor,\náhi retoñará tu guía;\ncuando tengas otro amor\nno digas que fuiste mía;\nsi te dicen: “¿quién te hirió?”,\nfue el aire que te mecía.",105,2,-1,118,"Rosita amarilla",9,6,"ia",0,0,-1,0,225,225,"4049","",0,"","","",1,0,0,[],""],["frenk_t2-n4050",6,"Adiós y adiós,\nadiós, morenita, adiós,\nsi tú me vieras con otra (morena),\ndejarlo en amor de Dios.",119,2,12,118,"La diosa",3,4,"o",87,0,-1,0,225,225,"4050","",0,"","","",3,0,0,[],""],["frenk_t2-n4051",6,"Mucho me engrió tu simpatía, morena,\nhago de cuenta pa mí que fue y no fue,\npero algún día me encontraré otra dueña,\npara cantarle como a ella le canté.",115,2,3,118,"Las aves",3,4,"e",77,0,-1,0,225,225,"4051","",0,"","","",1,0,0,[],""],["frenk_t2-n4052",6,"Que te quise fue verdad,\nque te adoré fue muy cierto,\nque te tuve voluntad,\npero aquél era otro tiempo.",105,2,-1,118,"Estrofa suelta, uPiña madura",0,4,"eo",-1,0,-1,0,226,226,"4052","",0,"","","",1,0,0,[],""],["frenk_t2-n4053",6,"Que te quise, no lo niego,\npero te Uegué a olvidar;\nun consuelo sólo tengo:\nque de mí te has de acordar,\npues te Uevastes mi marca\nen tu modito de andar.",108,2,8,118,"Estrofa suelta, Al pasar por los laureles",9,6,"a",21,0,-1,0,226,226,"4053","",0,"","","",2,0,0,[],""],["frenk_t2-n4054",6,"Ya salió el Carro Volante,\nen medio las Tres Marías.\nHora sí ya no es como antes,\nque en tus brazos me tenías;\nyo soy como el comerciante;\nbajando cada ocho días.",119,2,12,118,"Estrofa suelta, La morena; Ya no llores, vida mía",9,6,"ia",214,0,-1,0,226,226,"4054","",0,"","","",1,0,0,[],""],["frenk_t2-n4055",6,"Soy el mero venadito\nde las montañas umbrías.\nYa no bajo al arroyito\ndonde tú me divertías;\nque en tus brazos me dormías",105,2,-1,118,"El venadito",7,5,"ia",214,0,-1,0,226,226,"4055","",0,"","","",1,0,0,[],""],["frenk_t2-n4056",6,"En la jaula de tu pecho\nun corazón encerré;\ncomo no era de provecho,\nle abrí la puerta y se fue;\ntomó camino derecho,\npero ni a menos lo eché.",108,2,8,118,"Estrofa suelta",9,6,"e",77,0,-1,0,226,226,"4056","",0,"","","",1,0,0,[],""],["frenk_t2-n4057",6,"Con la misma brevedad\nque se deshace una nube\nse deshizo para mí\ntodo el amor que te tuve.",105,2,-1,118,"Estrofa suelta",0,4,"ue",348,0,-1,0,226,226,"4057","",0,"","","",1,0,0,[],""],["frenk_t2-n4058",6,"Fue contigo mi querer,\npor lo fingido y violento,\nuna nube que hizo el viento\ny la volvió a deshacer.",122,2,13,118,"Estrofa suelta",11,4,"e",20,0,-1,0,226,226,"4058","",0,"","","",1,0,0,[],""],["frenk_t2-n4059",6,"El amor que te tenía\nen una rama quedó;\nvino un fuerte remolino,\nrama y amor se llevó.",105,2,-1,118,"Estrofa suelta",0,4,"o",2,0,-1,0,226,226,"4059","",0,"machado_venezuela","","",5,0,0,[],""],["frenk_t2-n4060",6,"Si piensas que te quería,\nera por entretenerte;\nque el amor que te tenía\nya se lo llevó la muerte.",105,2,-1,118,"El turronero; El jarabe tapatío",1,4,"ee",134,0,-1,0,227,227,"4060","",0,"","","",1,0,0,[],""],["frenk_t2-n4061",6,"Antes por ti me moría,\nahora no quiero ni verte;\nel amor que te tenía\nya se lo llevó la muerte.",108,2,8,118,"Estrofa suelta",1,4,"ee",134,0,-1,0,227,227,"4061","",0,"","","",1,0,0,[],""],["frenk_t2-n4062",6,"Si en antes yo te rogaba,\nera porque te quería;\npero quedaste borrada\nde mi lista, vida mía.",105,2,-1,118,"Vieja escalera",0,4,"ia",0,0,-1,0,227,227,"4062","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4063",6,"Antenoche soñé que te amaba,\ncomo se ama una vez en la vida;\ndesperté y todo era mentira:\nni siquiera me acuerdo de ti.",115,2,3,118,"Qué te falta mujer",3,4,"i",-1,0,-1,0,227,227,"4063","",0,"","","",1,0,0,[],""],["frenk_t2-n4064",6,"Aunque yo en tu amor creí,\nde todito me arrepiento;\nnuestro amor llegó hasta aquí,\ntodo se acabó al momento:\nya nada sientas por mí,\nque yo por ti nada siento.",128,2,30,118,"Me han dicho que tienes otra",9,6,"eo",94,0,-1,0,227,227,"4064","",0,"","","",1,0,0,[],""],["frenk_t2-n4065",6,"Es mejor que tú te vayas,\nya nada siento por ti;\nni me quieres, ni te quiero:\n¿qué estamos haciendo así?",105,2,-1,118,"El palo blanco",0,4,"i",23,0,-1,0,227,227,"4065","",0,"","","",1,0,0,[],""],["frenk_t2-n4066",6,"Al pasar por el río Jordán\nyo quise pasar primero.\nEs cierto que yo te quise,\npero ahora ya no te quiero;\nhago de cuenta que tuve\nde mi silla un sudadero.",108,2,8,118,"Estrofa suelta",9,6,"eo",38,0,-1,0,227,227,"4066","",0,"","","",1,0,0,[],""],["frenk_t2-n4067",6,"En el puño de tu mano\nte puede caber mi amor:\nes tan poquito el cariño,\ny es mucho más el rencor.",105,2,-1,118,"El palo blanco",0,4,"o",72,0,-1,0,227,227,"4067","",0,"","","",1,0,0,[],""],["frenk_t2-n4069",6,"Mañana cuando me mires\nal lado de otra mujer,\nno te quejes ni suspires,\nni recuerdes lo de ayer,\nque para mí ya no vives.",106,2,4,118,"La liebre",7,5,"ie",-1,0,-1,0,228,228,"4069","",0,"","","",1,0,0,[],""],["frenk_t2-n4070",6,"No juego gallo tapado,\nporque si pierdo me enojo;\nte aviso que soy casado,\npa que no me hagas mal de ojo.",105,2,-1,118,"Gallo tapado",1,4,"oo",400,0,-1,0,228,228,"4070","",0,"","","",1,0,0,[],""],["frenk_t2-n4071",6,"Paso redoblado,\npaso de marchar,\n¿cómo quieres, mi alma,\nque te vuelva a hablar?",120,2,14,118,"¿Dónde vas, Isabel?",0,4,"a",21,0,-1,0,229,229,"4071","",0,"","","",1,0,0,[],""],["frenk_t2-n4072",6,"Si a darte un sí tú me obligas,\nyo no quiero ser liviana;\npues si no te lo doy ahora,\náhi te lo daré mañana.",105,2,-1,118,"Estrofa suelta",0,4,"aa",4,0,-1,0,229,229,"4072","",0,"","","",1,0,0,[],""],["frenk_t2-n4073",6,"Ya el águila real voló\ndel nopal para la higuera.\n¿Qué se dijera de mí,\nque yo contigo volviera?\nNo habría Dios para mí,\nni amor que me quisiera.",108,2,8,118,"Estrofa suelta",9,6,"ea",44,0,-1,0,229,229,"4073","",0,"","","",5,0,0,[],""],["frenk_t2-n4074",6,"Aunque te vistas de seda,\nsiempre la misma has de ser;\nes imposible que vuelvas\nen persona a merecer.",113,2,2,118,"Estrofa suelta",0,4,"e",20,0,-1,0,229,229,"4074","",0,"","","",1,0,0,[],""],["frenk_t2-n4075",6,"Siempre vienes a rogarme\ncuando me vienes a ver,\na ver si tengo dinero\npa poderte mantener.",105,2,-1,118,"Vieja escalera",0,4,"e",20,0,-1,0,229,229,"4075","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4076",6,"Corté la flor de laurel\nantes que le diera el viento;\ntú no comprendes, mujer,\nque te aguanté mucho tiempo.\nBonito es “El cascabel”\ny cantarlo con aliento.",105,2,-1,118,"El cascabel",9,6,"eo",-1,0,-1,0,229,229,"4076","",0,"","","",1,0,0,[],""],["frenk_t2-n4078",6,"Anda, vete y déjame,\nestoy cansado de amarte;\nno me metas en peligro\nde matar o que me maten.",108,2,8,118,"Estrofa suelta",0,4,"ae",-1,0,-1,0,230,230,"4078","",0,"","","",1,0,0,[],""],["frenk_t2-n4079",6,"Dice el dicho y es verdad:\n“Mucho ayuda el que no estorba”;\npor si lo quieres saber,\ntú ya me caíste gorda.",108,2,8,118,"Estrofa suelta",0,4,"oa",-1,0,-1,0,230,230,"4079","",0,"","","",1,0,0,[],""],["frenk_t2-n4081",6,"De una incubadora vino\nun gallo muy lenguaraz:\n“Serás madre de mis hijos,\npero mi mujer, jamás.”",105,2,-1,118,"El corral",0,4,"a",51,0,-1,0,230,230,"4081","",0,"","","",1,0,0,[],""],["frenk_t2-n4082",6,"Ya no quiero que me quieras, no soy necio,\nni dirijas tus miradas hacia mí;\nlo que quiero para ti es el desprecio;\nvive feliz, como yo vivo sin ti.",105,2,-1,118,"La basura",3,4,"i",23,0,-1,0,230,230,"4082","",0,"","","",1,0,0,[],""],["frenk_t2-n4084",6,"¿Adónde estarán aquellas caricias\nque me hacías con tanto esmero?\nYa no te relujes, ya no te compongas,\nque al cabo ya no te quiero.",105,2,-1,118,"La pantera vaciladora",3,4,"eo",38,0,-1,0,231,231,"4084","",0,"","","",1,0,0,[],""],["frenk_t2-n4085",6,"Ahora sí puedes gozar\ny las puedes vacilar:\n¡quién pudiera!\nYa no quiero de tu amor,\nni me vengas a engañar\ncon caricias traicioneras.",108,2,8,118,"Una paloma al volar",9,6,"ea",-1,0,-1,0,231,231,"4085","",0,"","","",1,0,0,[],""],["frenk_t2-n4086",6,"Cuando yo te quise, tú me abandonaste,\nme diste mis calabazas;\nhoy ya no te quiero, no seas tan rogona,\nconmigo ya no te casas.",105,2,-1,118,"La rogona",3,4,"aa",561,0,-1,0,231,231,"4086","",0,"","","",1,0,0,[],""],["frenk_t2-n4087",6,"Ya no quiero que te metas tú conmigo,\nque me dejes en el mundo vacilar;\nya es mucho tiempo el que tú me abandonaste;\nahora ni modo, yo ya me voy a casar.",105,2,-1,118,"La basura",3,4,"a",21,0,-1,0,231,231,"4087","",0,"","","",1,0,0,[],""],["frenk_t2-n4088",6,"Que vuelvas a mi poder,\ndirás. ¿Con qué corazón\nhe de volver a querer,\nrecordando tu traición?\nEres muy falsa, mujer,\nno quiero tu estimación.",112,2,6,118,"El taconcito",9,6,"o",31,0,-1,0,231,231,"4088","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4089",6,"No quiero tu estimación,\npor tu mal procedimiento;\neres de mala intención,\ntienes muy mal pensamiento;\nheriste a mi corazón,\nlo dejas en sufrimiento.",112,2,6,118,"El taconcito",9,6,"eo",94,0,-1,0,231,231,"4089","",0,"","","",2,0,0,[],""],["frenk_t2-n4090",6,"Amor mal agradecido,\npor tu mal comportamiento\nvengo a terminar contigo:\nbusca otro y no pierdas tiempo.",105,2,-1,118,"Estrofa suelta",0,4,"eo",-1,0,-1,0,231,231,"4090","",0,"","","",1,0,0,[],""],["frenk_t2-n4091",6,"Todo usted es falsedad\ny obra con suma ficción,\nla mentira es su expresión,\ny su norte la maldad.",105,2,-1,118,"Estrofa suelta",11,4,"a",16,0,-1,0,231,231,"4091","",0,"","","",1,0,0,[],""],["frenk_t2-n4092",6,"Ya yo no me creo de usted,\npor falso y engañador;\n¡quién había de creer, señor,\nque tantas tenga a la vez!",105,2,-1,118,"Estrofa suelta",3,4,"e",-1,0,-1,0,231,231,"4092","",0,"","","",1,0,0,[],""],["frenk_t2-n4093",6,"Te quieres hacer valer\ncomo prenda de valor;\npues debes de comprender\nque ya perdiste tu amor,\ny jamás ha de volver.",113,2,2,118,"Estrofa suelta",7,5,"e",20,0,-1,0,232,232,"4093","",0,"","","",2,0,0,[],""],["frenk_t2-n4094",6,"Si te crees que tú me gustas\nporque te miro a la cara,\nmuchos que van a la feria\nmiran y no compran nada.",105,2,-1,118,"Al derecho y al revés; Ya no lloverá, pelonas; Estrofa suelta",0,4,"aa",-1,0,-1,0,232,232,"4094","",0,"","","",1,0,0,[],""],["frenk_t2-n4095",6,"Sobre la mesa te puse\ntiras de papel ardiendo.\nSi porque me río contigo\npiensas que te estoy queriendo,\nya mi modito es así:\nburla es la que te ando haciendo.",108,2,8,118,"Estrofa suelta",9,6,"eo",52,0,-1,0,232,232,"4095","",0,"","","",3,0,0,[],""],["frenk_t2-n4096",6,"Si es que yo te dije “mi alma”,\neso fue de vacilada;\ntoma las cosas con calma\nya que la cosa es calmada.",108,2,8,118,"Estrofa suelta",1,4,"aa",-1,0,-1,0,232,232,"4096","",0,"","","",1,0,0,[],""],["frenk_t2-n4097",6,"Si te quise, no fue que te quise,\nsi te amé, fue por pasar el rato;\náhi te mando tu triste retrato,\npara nunca acordarme de ti.",115,2,3,118,"Qué te falta, mujer",3,4,"i",-1,0,-1,0,232,232,"4097","",0,"","","",1,0,0,[],""],["frenk_t2-n4098",6,"Dices que soy escalera\ny que por ella subiste:\neso es lo que tú deseabas,\n¡y nunca lo conseguiste!",105,2,-1,118,"Vieja escalera",0,4,"ie",153,0,-1,0,232,232,"4098","",0,"","","",2,0,0,[],""],["frenk_t2-n4099",6,"Les dijiste a tus amigos\nque me ibas a mancornar,\nque ibas a juntar tu yunta,\nporque era tiempo de arar.",114,2,17,118,"La mancomadora",0,4,"a",21,0,-1,0,232,232,"4099","",0,"","","",1,0,0,[],""],["frenk_t2-n4100",6,"Dicen que soy forastero\nporque uso mi sombrero ancho;\nsí, señora, soy tunero,\npero no corto en su rancho:\nal fin que yo tengo mi potrero\ndonde retozan mis sanchos.",119,2,12,118,"Estrofa suelta",9,6,"ao",-1,0,-1,0,232,232,"4100","",0,"","","",1,0,0,[],""],["frenk_t2-n4101",6,"La despedida te doy,\nque un clavo saca otro clavo;\nsi pensaste que te quise,\nla felicidad te alabo.",105,2,-1,118,"Estrofa suelta",0,4,"ao",358,0,-1,0,232,232,"4101","",0,"","","",9,0,0,[],""],["frenk_t2-n4103",6,"Amarte no bien quería,\nporque lo habían de saber,\npero tu amor me insistía,\ny tú quisiste, mujer,\ndispertar al que dormía.",112,2,6,118,"Estrofa suelta, La azucena",7,5,"ia",0,0,-1,0,233,233,"4103","",0,"","","",1,0,0,[],""],["frenk_t2-n4104",6,"Tú dices que estoy sentida,\nporque tu amor me dejó;\nsi yo sentida estuviera,\nllorando anduviera yo.",108,2,8,118,"Estrofa suelta",0,4,"o",2,0,-1,0,233,233,"4104","",0,"","","",1,0,0,[],""],["frenk_t2-n4105",6,"Si piensas que estoy sentido\nporque tienes nuevo amor,\nantes vivo agradecido,\npues te debo ese favor.",105,2,-1,118,"Estrofa suelta, Ojitos color de olivo",1,4,"o",72,0,-1,0,233,233,"4105","",0,"","","",1,0,0,[],""],["frenk_t2-n4106",6,"Pensastes hacerme un mal\ncon haberme abandonado;\nesas muías como tú\nyo ya las he desechado:\nte juro que en mi corral\nya no entra de ese ganado.",116,2,15,118,"El buey",9,6,"ao",14,0,-1,0,233,233,"4106","",0,"","","",1,0,0,[],""],["frenk_t2-n4107",6,"No creas que estoy llorando\ntodo el bien que me tenías;\nni yo tampoco te tengo\nel amor que te tenía.",108,2,8,118,"El gavilancito",0,4,"ia",-1,0,-1,0,233,233,"4107","",0,"","","",1,0,0,[],""],["frenk_t2-n4108",6,"Pensarás que a qué he venido,\nsi ya todo ha terminado;\npiensas que cariño pido,\npero te has equivocado.",105,2,-1,118,"Devuélveme el corazón",1,4,"ao",14,0,-1,0,233,233,"4108","",0,"","","",1,0,0,[],""],["frenk_t2-n4109",6,"No digas que de hambre vengo,\nni la necesidad me trae;\nyo todo tengo en mi casa;\nsólo me falta maiz.",108,2,8,118,"Estrofa suelta",5,4,"a",-1,0,-1,0,233,233,"4109","",0,"","","",1,0,0,[],""],["frenk_t2-n4110",6,"¡Ah, qué cipreses tan altos,\ny qué de ramas colgando!\n¿Qué pensarías, Mariquita?,\n¿que yo te estaba rogando?",121,2,26,118,"El frijolito",0,4,"ao",33,0,-1,0,233,233,"4110","",0,"","","",1,0,0,[],""],["frenk_t2-n4111",6,"Aventé una perla fina\npa el otro lado del mar;\n¿qué pensaba el desgraciado?,\n¿que yo le había de rogar?",110,2,10,118,"Si te suelto como un trompo",0,4,"a",21,0,-1,0,234,234,"4111","",0,"","","",1,0,0,[],""],["frenk_t2-n4112",6,"Te pusiste y me dijiste\nque yo te andaba rogando;\ntodos los defectos tengo,\npero que te niegue, ¡cuándo!",105,2,-1,118,"El colimóte",0,4,"ao",33,0,-1,0,234,234,"4112","",0,"","","",1,0,0,[],""],["frenk_t2-n4113",6,"Me subí a la alta higuera,\nque me pegara el verano.\nAunque tú tienes tu güera,\npero no te ando rogando,\naunque yo soy prieta y fea.",106,2,4,118,"Estrofa suelta",7,5,"ea",-1,0,-1,0,234,234,"4113","",0,"","","",2,0,0,[],""],["frenk_t2-n4114",6,"En la puerta de mi casa\ntengo una verde corona,\ncon un letrero que dice:\n“Soy fea, pero no rogona.",110,2,10,118,"Estrofa suelta",0,4,"oa",7,0,-1,0,234,234,"4114","",0,"","","",24,0,0,[],""],["frenk_t2-n4115",6,"—Pensará la tarasquilla\nque le tengo de rogar.\n—Ni yo tengo para qué\nmantener a un haragán.",106,2,4,118,"Los papaquis",0,4,"a",-1,0,-1,0,234,234,"4115","",0,"","","",1,0,0,[],""],["frenk_t2-n4116",6,"Si crees que por tu belleza\nte voy a andar suplicando,\nserá grande mi tristeza\npara que yo me ande humillando.",108,2,8,118,"Estrofa suelta",1,4,"ao",33,0,-1,0,234,234,"4116","",0,"","","",1,0,0,[],""],["frenk_t2-n4118",6,"Árboles de la alameda,\nchiquitos, pero floreando;\nsi unos brazos me desprecian,\notros me están esperando.",115,2,3,118,"La chinita; Estrofa suelta",0,4,"ao",33,0,-1,0,234,234,"4118","",0,"","","",5,0,0,[],""],["frenk_t2-n4120",6,"Creías que no había de hallar\namor como el que perdí:\ntan al pelo lo hallé,\nque ni me acuerdo de ti.",105,2,-1,118,"La chancla",3,4,"i",23,0,-1,0,235,235,"4120","",0,"","","",1,0,0,[],""],["frenk_t2-n4121",6,"Entre cien piedras de alumbre\nyo me puse a descoger;\nsi tú lo llamas costumbre,\nyo lo llamaría placer;\nal cabo que en este mundo\nno no más tú eres mujer.",112,2,6,118,"Estrofa suelta",9,6,"e",20,0,-1,0,235,235,"4121","",0,"","","",1,0,0,[],""],["frenk_t2-n4122",6,"Siembra bien tu naranjito,\nque el mío ya floreció;\nte quiero por apetito,\nno porque a mí me faltó:\nya tengo otro más bonito,\nno vayas a creer que no.",105,2,-1,118,"Estrofa suelta",9,6,"o",2,0,-1,0,235,235,"4122","",0,"","","",1,0,0,[],""],["frenk_t2-n4123",6,"Vamos a ver los laureles\nque sembré al otro lado del río.\nNo sé qué envidia me tienes,\nporque paseo con lo mío:\nesto es que no me mantienes,\no de calor tienes frío.",108,2,8,118,"Estrofa suelta",9,6,"io",3,0,-1,0,235,235,"4123","",0,"","","",1,0,0,[],""],["frenk_t2-n4124",6,"El pájaro carpintero\nle dijo a la chuparrosa:\n“¿A poco porque tienes nuevo amor\nte vas a mostrar orgullosa?\nAl cabo al hombre soltero como yo\ncualquier mujer lo arreboza.”",113,2,2,118,"Estrofa suelta",9,6,"oa",195,0,-1,0,235,235,"4124","",0,"","","",9,0,0,[],""],["frenk_t2-n4125",6,"No te andes haciendo jaula,\nporque tienes nuevo amor;\nno vivas engrandecida:\nyo ya tengo otro mejor.",110,2,10,118,"La jaula",0,4,"o",72,0,-1,0,235,235,"4125","",0,"","","",1,0,0,[],""],["frenk_t2-n4126",6,"Me despreciastes, ingrata,\nporque tenías otro dueño,\npero te aseguro, chata:\nhasta te había de dar sueño\nsi vieras a mi mulata.",105,2,-1,118,"El fandanguito",7,5,"aa",74,0,-1,0,235,235,"4126","",0,"","","",1,0,0,[],""],["frenk_t2-n4128",6,"Dicen que no me quieres,\ny bien no lo entiendo:\nporque no te enamoro\nni te pretendo.",106,2,4,118,"La bamba; El pájaro cú",6,4,"eo",52,0,-1,0,236,236,"4128","",0,"","","",18,0,0,[],""],["frenk_t2-n4129",6,"¿Por qué me echas esos ojos,\ncomo que estás enojada,\nsi sabes que tus enojos\na mí no me importan nada?",114,2,17,118,"El agobiado",1,4,"aa",49,0,-1,0,236,236,"4129","",0,"","","",1,0,0,[],""],["frenk_t2-n4130",6,"Si porque te vi te enojas,\nte enojas porque te vi;\nsi insistes en tus enojos,\nno te enojes, no te vi.",129,2,9,118,"Estrofa suelta",0,4,"i",-1,0,-1,0,236,236,"4130","",0,"","","",1,0,0,[],""],["frenk_t2-n4132",6,"Un chivo pegó un reparo\ny en el viento dio un balido.\nSi no me quieres hablar,\nal cabo ni agua te pido;\nya me cansé de tanteadas,\nya me tienes aburrido.",105,2,-1,118,"La culebra pollera",9,6,"io",101,0,-1,0,236,236,"4132","",0,"","","",2,0,0,[],""],["frenk_t2-n4134",6,"Voy a echar la despedida,\nredondita como un peso;\nno le hace que no me quieras:\n¿qué templo se cae por eso?",105,2,-1,118,"María del Carmen; Que comienzo, que comienzo; Estrofa suelta",0,4,"eo",48,0,-1,0,236,236,"4134","",0,"","","",8,0,0,[],""],["frenk_t2-n4135",6,"Agua de piña,\nagua de coco,\nsi no me quieres,\nme importa poco.",129,2,9,118,"Estrofa suelta",6,4,"oo",152,0,-1,0,237,237,"4135","",0,"","","",1,0,0,[],""],["frenk_t2-n4136",6,"No hay ciego enamorado,\nsé que la vida es prestada;\nno porque me hagas a un lado\nquede mi alma atormentada:\neso no me da cuidado.",112,2,6,118,"Estrofa suelta",7,5,"ao",14,0,-1,0,237,237,"4136","",0,"","","",1,0,0,[],""],["frenk_t2-n4137",6,"No vine, señora, no,\na forzar el que me quieras,\nque el amor que no es de veras\n¿para qué lo quiero yo?",108,2,8,118,"Estrofa suelta",11,4,"o",2,0,-1,0,237,237,"4137","",0,"","","",1,0,0,[],""],["frenk_t2-n4138b",6,"Ya sé que tú no me quieres,\npor consejos que te han dado;\nanda, quiere a quien tú quieras:\nyo no quiero amor comprado;\ncomo soy un pobrecito,\npero no soy despreciado.",112,2,6,118,"La pasión",9,6,"ao",14,0,-1,0,237,237,"4138b","",0,"","","",1,0,0,[],""],["frenk_t2-n4140",6,"Haz de cuenta que sembramos una milpa;\ny esa milpa con la helada se secó;\nhaz de cuenta que los dos fuimos basura,\ny no te fijes, que lo que pasó voló.",105,2,-1,118,"La basura",3,4,"o",2,0,-1,0,237,237,"4140","",0,"","","",1,0,0,[],""],["frenk_t2-n4142",6,"Soy de la opinión del pueblo:\nel mejor gusto del hombre,\n“si te quise, no me acuerdo,\nsi la tuve, no sé dónde”;\nya para mejor decirte,\nni me acuerdo de tu nombre.",105,2,-1,118,"Estrofa suelta",9,6,"oe",-1,0,-1,0,238,238,"4142","",0,"","","",1,0,0,[],""],["frenk_t2-n4143",6,"Sé que andas diciendo\nque no me queréis;\nno me estoy muriendo,\n¿qué le voy a hacer?",105,2,-1,118,"Por quién suspiráis",0,4,"e",-1,0,-1,0,238,238,"4143","",0,"","","",1,0,0,[],""],["frenk_t2-n4144",6,"—A los campos echas lides\nen busca de tus amores;\nme encontré con unas flores,\nque nada me divertían;\ny esta era la pena mía:\nel hallarme yo sin ti\ncuando yo sólita fui\na pasar mis crueles penas.\n—Aquí estoy, nada me sucede,\naunque pienses que morí.",105,2,-1,118,"El fandanguito",18,10,"i",23,0,-1,0,238,238,"4144","",0,"","","",1,0,0,[],""],["frenk_t2-n4146",6,"La tumba que abres en mi alma\nes un ramo de azucenas;\nmi amor sigue en quieta calma,\ny nunca se va a dar penas\npor cosa que no lo valga.",112,2,6,118,"Estrofa suelta",7,5,"aa",-1,0,-1,0,238,238,"4146","",0,"","","",1,0,0,[],""],["frenk_t2-n4147",6,"Vámonos al puente nuevo,\narriba de la calzada.\nNo siento andar pendiente,\ncomo la mala jugada:\nque se haya reído la gente\npor una cosa de nada.",108,2,8,118,"Estrofa suelta",9,6,"aa",49,0,-1,0,238,238,"4147","",0,"","","",1,0,0,[],""],["frenk_t2-n4148",6,"Dices que ya no me quieres\ncomo antes me querías\ny ahora que ya no me quieres\nvan a tocarme agonías:\namores como los tuyos\nme sobran todos los días.",105,2,-1,118,"La Malagueña curreña; Estrofa suelta",9,6,"ia",214,0,-1,0,238,238,"4148","",0,"","","",21,0,0,[],""],["frenk_t2-n4149",6,"Dices que ya no me quieres\ncomo de antes me querías.\nSi estás con el Chu,\nno vengas aquí;\nsi estás con el Chu,\nvete para allá.",106,2,4,118,"El Chu",9,6,"a",-1,0,-1,0,239,239,"4149","",0,"","","",21,0,0,[],""],["frenk_t2-n4150",6,"Me subí al cerro más alto\npara coronar una obra.\nDices que ya no me quieres:\npues no te hago la mala obra,\nque a mí cabestros me faltan\ny a quien marcornar me sobran.",108,2,8,118,"El venadito",9,6,"oa",-1,0,-1,0,239,239,"4150","",0,"","","",3,0,0,[],""],["frenk_t2-n4151",6,"Dices que ya no me quieres\npor consejos que te han dado;\npues quiere bien a quien quieres:\nel mundo no se ha acabado,\nestá lleno de mujeres.",112,2,6,118,"Estrofa suelta",7,5,"ee",55,0,-1,0,239,239,"4151","",0,"","","",21,0,0,[],""],["frenk_t2-n4152",6,"Dices que ya no me quieres\npor lo mal que te han contado;\npara mí, como tú quieras,\nque al cabo ya te hice a un lado;\nmi vida, tengo mi arroz\nen buenas tierras sembrado.",105,2,-1,118,"La Malagueña curreña; Estrofa suelta",9,6,"ao",14,0,-1,0,239,239,"4152","",0,"","","",21,0,0,[],""],["frenk_t2-n4153",6,"De tu lucido jardín\nsobresale una ramilla;\nvoy a cortar otra flor\ny a buscarle la semilla,\ny si la llego a encontrar,\nvoy a echarte pa la orilla.",105,2,-1,118,"Rosita amarilla",9,6,"ia",162,0,-1,0,239,239,"4153","",0,"","","",1,0,0,[],""],["frenk_t2-n4154",6,"Soy pajarito colorado,\nalita de terciopelo;\ny ya que sé que tú no me quieres,\nme tiras a tu basurero:\npara ti seré basura,\ny para otra sería lucero.",119,2,12,118,"Estrofa suelta",9,6,"eo",38,0,-1,0,239,239,"4154","",0,"","","",1,0,0,[],""],["frenk_t2-n4155",6,"La pera que se hace bola\nno sirve para cimiento;\namores como los tuyos\ndonde quiera los encuentro.",105,2,-1,118,"Estrofa suelta",0,4,"eo",-1,0,-1,0,239,239,"4155","",0,"","","",1,0,0,[],""],["frenk_t2-n4156",6,"Negrita, tus ojos son\nlos que me cargan volteando;\namores como los tuyos\npor otros los ando cambiando.",108,2,8,118,"Estrofa suelta",0,4,"ao",33,0,-1,0,239,239,"4156","",0,"","","",3,0,0,[],""],["frenk_t2-n4157",6,"Te juro por mi salud,\nsin que te llames a engaño,\nque me han seguido en el año\notras mejores que tú.",105,2,-1,118,"Estrofa suelta, Mariquita",5,4,"u",-1,0,-1,0,239,239,"4157","",0,"","","",1,0,0,[],""],["frenk_t2-n4159",6,"Ábrete, lirio morado,\nvarita de San José;\nahora me estarán queriendo\notras mejores que usted.",115,2,3,118,"Mariquita",0,4,"e",-1,0,-1,0,240,240,"4159","",0,"","","",1,0,0,[],""],["frenk_t2-n4160",6,"Dices que ya no me quieres:\na mí no me importa nada;\nal cabo tengo mi muía,\nque le echo carga pesada.",105,2,-1,118,"La mulita",0,4,"aa",49,0,-1,0,240,240,"4160","",0,"","","",21,0,0,[],""],["frenk_t2-n4161",6,"Y ahora que te miro, ahora que te encuen-\nte me haces orgullos[a];\nya no te compongas, ya no te relujes:\nal cabo ya tengo a otra.",105,2,-1,118,"La pantera vaciladora",3,4,"oa",-1,0,-1,0,240,240,"4161","",0,"","","",1,0,0,[],""],["frenk_t2-n4162",6,"Andando me voy durmiendo,\ncayéndome voy de sueño;\ndame el amor que te di,\nque me lo pide su dueño.",108,2,8,118,"La garbosa",0,4,"eo",138,0,-1,0,240,240,"4162","",0,"","","",1,0,0,[],""],["frenk_t2-n4164",6,"Mis amigos me decían\nque me ibas hacer [a] un lado;\ntengo un amorcito nuevo,\nque no me hace desgraciado.",127,2,18,118,"Ojitos negros y chinos",0,4,"ao",14,0,-1,0,240,240,"4164","",0,"","","",1,0,0,[],""],["frenk_t2-n4165",6,"Desde que tú me dejaste\ny con risas te burlaste\nde lo grande de mi amor,\nestoy como el zopilote,\nque anda armando su mitote\npor comerse lo mejor.",105,2,-1,118,"La muía maicera] [tro;",9,6,"o",72,0,-1,0,240,240,"4165","",0,"","","",1,0,0,[],""],["frenk_t2-n4166",6,"Yo me encontré este recado\ndetrás de mi Santo Niño:\nque si de ti me olvidaba,\nme llenarían de cariño.",105,2,-1,118,"Los capulines",0,4,"io",176,0,-1,0,240,240,"4166","",0,"","","",1,0,0,[],""],["frenk_t2-n4167",6,"Ya no quiero, ya no quiero\nlas sombras de tu recuerdo;\nya tengo nuevos amores\ny otro espejo en que me veo.",108,2,8,118,"El valiente; Estrofa suelta",0,4,"eo",-1,0,-1,0,241,241,"4167","",0,"","","",4,0,0,[],""],["frenk_t2-n4168",6,"Sembré una mata de yerbabuena,\ny se me volvió quelite;\namor, ya no me atormentes,\nque ya tengo quien me [in]vite.",109,2,7,118,"Estrofa suelta",3,4,"ie",315,0,-1,0,241,241,"4168","",0,"","","",1,0,0,[],""],["frenk_t2-n4169",6,"No creas que mi corazón\nahora estará apenado,\npues una nueva ilusión\nlo tiene bien cautivado:\nno he sufrido decepción.",112,2,6,118,"Estrofa suelta",7,5,"o",31,0,-1,0,241,241,"4169","",0,"","","",1,0,0,[],""],["frenk_t2-n4170",6,"Ya como y bebo sin ti,\nya duermo y no me desvelo,\nya tengo quien me dé gusto\ncada y cuando que yo quiero.",105,2,-1,118,"Estrofa suelta",0,4,"eo",-1,0,-1,0,241,241,"4170","",0,"","","",1,0,0,[],""],["frenk_t2-n4171",6,"Ya no necesito verte,\nque por mi bendita suerte\nse me amontonó el quehacer,\ny en mi rancho tengo viejas\nque saben echar sus nejas\npara darme de comer.",105,2,-1,118,"La muía maicera",9,6,"e",20,0,-1,0,241,241,"4171","",0,"","","",1,0,0,[],""],["frenk_t2-n4172",6,"¡Qué triste estoy!\nquiero llorar;\npero no por esos ojos (güerita):\npor otros que andan por áhi.",114,2,17,118,"El triste",3,4,"ai",-1,0,-1,0,241,241,"4172","",0,"","","",1,0,0,[],""],["frenk_t2-n4173",6,"Ese tiempo se acabó\nen que iba a misa por verte;\nesta estampa se borró:\notra es la que me divierte.",108,2,8,118,"Estrofa suelta",1,4,"ee",134,0,-1,0,241,241,"4173","",0,"","","",1,0,0,[],""],["frenk_t2-n4174",6,"Por más que venía por ti,\nno salías ni a la ventana,\npero ya no estés creyendo:\nsólo vengo por tu hermana.",107,2,11,118,"Estrofa suelta",0,4,"aa",4,0,-1,0,241,241,"4174","",0,"","","",1,0,0,[],""],["frenk_t2-n4175",6,"Si sales a tu ventana\ncreyendo que vengo a verte,\nte quedarás con las ganas:\nyo le canto a la de enfrente.",114,2,17,118,"El agobiado",0,4,"ee",-1,0,-1,0,241,241,"4175","",0,"","","",1,0,0,[],""],["frenk_t2-n4178",6,"En el patio de mi casa\nsembré una mata de carrizo;\ncon mejores he topado,\nno contigo, cacarizo.",119,2,12,118,"Estrofa suelta",0,4,"io",95,0,-1,0,242,242,"4178","",0,"","","",8,0,0,[],""],["frenk_t2-n4179",6,"En la puerta de mi casa\ntengo un palo de cacao;\nme he paseado con mejores,\nno contigo, desmuelado.",119,2,12,118,"Estrofa suelta",0,4,"ao",-1,0,-1,0,242,242,"4179","",0,"","","",24,0,0,[],""],["frenk_t2-n4180",6,"Elegí para mi esposa\na otra de mejor placer;\nsi quieres, irás de moza\nde otra que voy a tener.",106,2,4,118,"Estrofa suelta",1,4,"e",20,0,-1,0,242,242,"4180","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4182",6,"Te voy a dar un retrato\ndel que ocupa tu lugar;\nacuérdate que es tu padre\ny lo tienes que respetar.",105,2,-1,118,"Vieja escalera",0,4,"a",21,0,-1,0,242,242,"4182","",0,"","","",2,0,0,[],""],["frenk_t2-n4183",6,"Al pie de un verde lajunco\nmi amor te andaba buscando:\nyo no soy para ese asunto,\nalegre me ando paseando.",112,2,6,118,"El caimán",0,4,"ao",33,0,-1,0,242,242,"4183","",0,"","","",1,0,0,[],""],["frenk_t2-n4184a",6,"Ahora sí que estoy alegre\ncomo la fresca mañana;\notro día te lloraré\nporque ahora no tengo ganas.",105,2,-1,118,"Estrofa suelta",0,4,"aa",-1,0,-1,0,242,242,"4184a","",0,"","","",1,0,0,[],""],["frenk_t2-n4185a",6,"¡Ajá, ajá, ajá,\nqué risa me da\nen ver, en ver, en ver\ntu tirana falsedad!",105,2,-1,118,"Cielito lindo",3,4,"a",-1,0,-1,0,243,243,"4185a","",0,"","","",1,0,0,[],""],["frenk_t2-n4185c",6,"Cuantas veces yo medito\nen tu negra falsedad,\nme dan ganas de morirme:\n¡ay, ay, ay!, ¿si será verdad?\n¡Ja, ja, ja, qué risa me da!",105,2,-1,118,"Cielito lindo",7,5,"a",-1,0,-1,0,243,243,"4185c","",0,"","","",1,0,0,[],""],["frenk_t2-n4186",6,"Si a ti te duele el tiempo\nque has perdido conmigo,\na mí me está pesando\nmás haberte conocido,\ny no lo ando contando,\naunque me sobren motivos.",105,2,-1,118,"No tiene la culpa el indio",9,6,"io",-1,0,-1,0,243,243,"4186","",0,"","","",1,0,0,[],""],["frenk_t2-n4187",6,"Morena, dices que te vas mañana:\npara mí, que te vas hoy;\npara que te vaya bien, morena,\nlo mismo mañana que hoy.",105,2,-1,118,"El fandanguito",3,4,"o",-1,0,-1,0,243,243,"4187","",0,"","","",1,0,0,[],""],["frenk_t2-n4190",6,"Una paloma torcaz\ncantaba en su blanco nido:\n“No lloro porque te vas,\nlloro porque no te has ido.”",108,2,8,118,"Estrofa suelta",1,4,"io",101,0,-1,0,244,244,"4190","",0,"","","",1,0,0,[],""],["frenk_t2-n4191",6,"Hoy que estoy entristecido,\nhoy que estoy bocabajiado,\nsólo estoy arrepentido\nde no haberte madrugado.",105,2,-1,118,"La puntada; Estrofa suelta",1,4,"ao",14,0,-1,0,244,244,"4191","",0,"","","",1,0,0,[],""],["frenk_t2-n4192",6,"En un vaso azul nevado\nvide a mi amor con firmeza;\nde lo que ha habido me pesa;\nsi me vieras, desgraciada,\npoco y nada te interesa.",112,2,6,118,"La huazanga’*",7,5,"ea",201,0,-1,0,244,244,"4192","",0,"","","",1,0,0,[],""],["frenk_t2-n4193",6,"Se les concedió a tus padres\nel ver mi sangre correr;\na mí se me concedió,\nchina, no volverte a ver.",120,2,14,118,"Cuando salgo del trabajo**",0,4,"e",20,0,-1,0,244,244,"4193","",0,"","","",1,0,0,[],""],["frenk_t2-n4194",6,"Tanto tú como mi suegra\nme aborrecen, ¡vil fortuna!\nAunque yo, desde mi cuna,\nhe visto tu cara negra,\nno me aflige ni me alegra\ntan extraño proceder,\ny sin pena ni placer\nte doy la espalda, ¿qué quieres?\nMe fastidian las mujeres,\ny tú, al fin, eres mujer.",107,2,11,118,"Estrofa suelta",18,10,"e",20,0,-1,0,244,244,"4194","",0,"","","",1,0,0,[],""],["frenk_t2-n4195",6,"—Mariquita, dame un beso,\ntu mamá me lo mandó.\n—Mi mamá mandará en mí,\npero en mi boquita no.",114,2,17,119,"Mariquita; La chinita maderista",0,4,"o",2,0,-1,0,245,245,"4195","",0,"","","",7,0,0,[],""],["frenk_t2-n4196",6,"—Negrita, por tus enojos\nme he de sentar a llorar.\n—Yo no sé quitar enojos,\nasín se pueden quedar.",117,2,5,119,"Estrofa suelta",1,4,"a",21,0,-1,0,245,245,"4196","",0,"","","",1,0,0,[],""],["frenk_t2-n4200",6,"Ya no quiero que me siga,\ndéjeme sola no más;\nváyase adonde viva,\ny aquí quedamos en paz.",107,2,11,119,"La indita",3,4,"a",253,0,-1,0,246,246,"4200","",0,"","","",1,0,0,[],""],["frenk_t2-n4201a",6,"¡Y ay, indita, indita,\nindita, déjame estar!\nSolito yo me divierto\ncuando me salgo a pasear.",106,2,4,119,"La indita",0,4,"a",21,0,-1,0,246,246,"4201a","",0,"","","",1,0,0,[],""],["frenk_t2-n4202",6,"Tanto pasar y pasar:\n¿por qué no pasa de al tiro?\nMe gusta la Valenciana,\nla campana y su sonido.",119,2,12,119,"Estrofa suelta",0,4,"io",-1,0,-1,0,246,246,"4202","",0,"","","",3,0,0,[],""],["frenk_t2-n4203",6,"Si quieres saber de mí,\nve a la casa de correos:\nallí te darán razón\nque me fui pa Guanajuato.",105,2,-1,119,"La tercera carta",5,4,"ao",-1,0,-1,0,246,246,"4203","",0,"","","",1,0,0,[],""],["frenk_t2-n4204",6,"Si quieres que nos casemos,\ndiez años me has de aguardar,\nme has de contar las estrellas,\nme has de enladrillar el mar.",110,2,10,119,"Juliana",0,4,"a",21,0,-1,0,246,246,"4204","",0,"","","",1,0,0,[],""],["frenk_t2-n4205a",6,"Si quieres que yo te quiera,\nmanda enladrillar el mar,\ny después de enladrillado,\nsoy tuya, y puedes mandar.",105,2,-1,119,"Estrofa suelta",0,4,"a",21,0,-1,0,247,247,"4205a","",0,"","","",23,0,0,[],""],["frenk_t2-n4206",6,"Si quieres que yo te quiera,\nmanda enladrillar el mar\ncon botellas de aguardiente\no algo que pueda embriagar.",121,2,26,119,"La enlutadita",0,4,"a",21,0,-1,0,247,247,"4206","",0,"","","",23,0,0,[],""],["frenk_t2-n4207",6,"Si quieres que yo te quiera,\ndos cosas he de decir:\nque me cuentes las estrellas\ny me enladrilles el mar.",121,2,26,119,"La enlutadita",5,4,"a",-1,0,-1,0,247,247,"4207","",0,"","","",23,0,0,[],""],["frenk_t2-n4208a",6,"Para saber si me quieres,\nme has de leer el pensamiento,\nme has de escribir en el agua,\nme has de firmar en el viento.",108,2,8,119,"La Malagueña curreña",0,4,"eo",94,0,-1,0,247,247,"4208a","",0,"","","",1,0,0,[],""],["frenk_t2-n4209",6,"No trate de enamorarme,\nque no es digno de mi amor:\nnunca se ha visto que un cerdo\nse rasque con una flor.",105,2,-1,119,"Donde las dan las toman",0,4,"o",72,0,-1,0,247,247,"4209","",0,"","","",1,0,0,[],""],["frenk_t2-n4210",6,"¡Mira qué hermoso durazno!\npero no lo has de comer,\nporque no se hizo la miel\npara la boca del asno.",105,2,-1,119,"El durazno",5,4,"ao",562,0,-1,0,247,247,"4210","",0,"","","",1,0,0,[],""],["frenk_t2-n4211",6,"Desde la raíz hasta el hueso\nme he de comer un durazno;\ny ya sabes, no es la miel\npara el hocico del asno.",105,2,-1,119,"La suegra",0,4,"ao",562,0,-1,0,247,247,"4211","",0,"","","",1,0,0,[],""],["frenk_t2-n4213",6,"He visto mujeres tontas,\npero como usted no hay dos:\nanda enredándose en pleitos,\na ver si encuentra su amor.",105,2,-1,119,"Donde las dan las toman*",0,4,"o",-1,0,-1,0,248,248,"4213","",0,"","","",1,0,0,[],""],["frenk_t2-n4214",6,"Crece, crece, zacatito,\ncrece como vas creciendo.\nYo creía que eras hombrecito,\ncomo lo andabas diciendo:\nlástima de bigotito\nque ya te viene saliendo.",108,2,8,119,"Estrofa suelta",9,6,"eo",52,0,-1,0,248,248,"4214","",0,"","","",1,0,0,[],""],["frenk_t2-n4215",6,"En una mesa te puse\nlentejas con alverjones.\nSi yo palabra te di,\nfue porque te vi pantalones,\npero ya me convencí\nque son naguas las que te pones.",107,2,11,119,"Estrofa suelta",9,6,"oe",34,0,-1,0,248,248,"4215","",0,"","","",7,0,0,[],""],["frenk_t2-n4216a",6,"Del cielo cayó una rosa,\ndel palo blanco una carta:\n“¿De qué te sirve ser hombre,\nsi la palabra te falta?”",129,2,9,119,"Estrofa suelta",0,4,"aa",-1,0,-1,0,248,248,"4216a","",0,"","","",5,0,0,[],""],["frenk_t2-n4218",6,"Λ1 pasar por una huerta\ncorté una flor de lechuga;\nhe despreciado a la gente:\ncontimás a ti, basura.",129,2,9,119,"Estrofa suelta",0,4,"ua",-1,0,-1,0,248,248,"4218","",0,"","","",1,0,0,[],""],["frenk_t2-n4219",6,"Debajo de un limón verde\nme puse a criar un conejo;\nle di atole con el dedo:\ncuantimás a usted, pendejo.",110,2,10,119,"Estrofa suelta",0,4,"eo",-1,0,-1,0,248,248,"4219","",0,"","","",9,0,0,[],""],["frenk_t2-n4220",6,"Cáscaras de naranja,\nmaduras en la arena;\nde cáscaras como usted\ntengo una bodega llena.",110,2,10,119,"Estrofa suelta",0,4,"ea",59,0,-1,0,249,249,"4220","",0,"","","",1,0,0,[],""],["frenk_t2-n4221",6,"Amores como los tuyos\nησ tienen valor ninguno:\ndespués que todo perdieron,\nno más les queda el orgullo.",105,2,-1,119,"No tiene la culpa el indio",0,4,"uo",-1,0,-1,0,249,249,"4221","",0,"","","",1,0,0,[],""],["frenk_t2-n4222",6,"Y yo te pido por Dios\nque te quites de esa farsa;\ncuando te dicen adiós\nte crees la divina garza.",105,2,-1,119,"La divina garza",1,4,"aa",563,0,-1,0,249,249,"4222","",0,"","","",1,0,0,[],""],["frenk_t2-n4223",6,"Te sientes un pavorreal\ncuando se ensancha y camina;\nse me hace que en el corral\nno has llegado ni a gallina.",105,2,-1,119,"La divina garza",1,4,"ia",11,0,-1,0,249,249,"4223","",0,"","","",1,0,0,[],""],["frenk_t2-n4224",6,"Te das tu importancia,\ncomo si valieras tanto;\nlos años podrás quitarte,\npero las arrugas ¡cuándo!",105,2,-1,119,"La vieja presumida",0,4,"ao",-1,0,-1,0,249,249,"4224","",0,"","","",1,0,0,[],""],["frenk_t2-n4227",6,"Presumes lo que no tienes;\nno más dime a qué te atienes\ncon muchas fanfarronadas,\npara andar echando habladas.",105,2,-1,119,"La divina garza",5,4,"aa",282,0,-1,0,249,249,"4227","",0,"","","",1,0,0,[],""],["frenk_t2-n4228",6,"Ramitas, ramitas verdes,\nhojitas atravesadas;\nallá te mando tus prendas\npa que no andes con habladas.",105,2,-1,119,"El tejón",0,4,"aa",282,0,-1,0,249,249,"4228","",0,"","","",1,0,0,[],""],["frenk_t2-n4230",6,"Me han dicho que eres bonita\ny que tienes linda cara;\ntambién sé que eres hermosa,\nporque tienes linda traza;\nsi no fueras tracalera,\notro gallo te cantara.",105,2,-1,119,"Soy fandanguero",9,6,"aa",-1,0,-1,0,250,250,"4230","",0,"","","",2,0,0,[],""],["frenk_t2-n4231",6,"Me han dicho que eres bonita\ny que tienes linda trenza;\npero lo mejor te falta,\nque es el punto y la vergüenza;\nquédate con tu hermosura,\nyo me iré con mi figura.",105,2,-1,119,"Soy fandanguero",9,6,"ua",17,0,-1,0,250,250,"4231","",0,"","","",2,0,0,[],""],["frenk_t2-n4232",6,"Debajo de un cocotero\nte dije que te esperaba;\ncreí que tenías vergüenza,\ny veo que no tienes nada.",105,2,-1,119,"La Zandunga",0,4,"aa",-1,0,-1,0,250,250,"4232","",0,"","","",1,0,0,[],""],["frenk_t2-n4234",6,"Corté la flor del sesenta\nen el mes de San José.\nNo me hagas tan inocente:\ntoditas tus mañas sé,\naquí las tengo presentes,\nsi quieres te las diré.",108,2,8,119,"Estrofa suelta",9,6,"e",77,0,-1,0,250,250,"4234","",0,"","","",1,0,0,[],""],["frenk_t2-n4235",6,"Ya no soy lo que antes fui,\nde todos vivo olvidado;\nsi antes fui tu general,\nhoy ya no soy ni soldado;\nabandoné tu cuartel (morena),\npor lo mal que te has portado.",108,2,8,119,"Estrofa suelta",9,6,"ao",14,0,-1,0,250,250,"4235","",0,"","","",1,0,0,[],""],["frenk_t2-n4236",6,"Te abandoné por rejega,\npero no para mi mal;\nnunca sobra la que llega\nni falta la que se va.",108,2,8,119,"Estrofa suelta",0,4,"a",-1,0,-1,0,251,251,"4236","",0,"","","",1,0,0,[],""],["frenk_t2-n4237",6,"Ya no vivo en la casita\ndonde usted me conoció:\nahora vivo en la vueltita,\ndonde me calabaceó.",105,2,-1,119,"Estrofa suelta",1,4,"o",2,0,-1,0,251,251,"4237","",0,"","","",1,0,0,[],""],["frenk_t2-n4239",6,"No puedes jugar con una (mi bien),\ny quieres jugar con dos;\ny luego te quedas sin una y sin dos,\nmirando al cielo de Dios.",105,2,-1,119,"Corrido de Laredo; Goza, goza mariposa",3,4,"o",87,0,-1,0,251,251,"4239","",0,"","","",1,0,0,[],""],["frenk_t2-n4240",6,"Eres, mi alma, tan bonita\ncomo la rosa al brotar,\nmas sólo un defecto tienes,\ny es que sabes mancornar.",105,2,-1,119,"Estrofa suelta",0,4,"a",21,0,-1,0,251,251,"4240","",0,"","","",1,0,0,[],""],["frenk_t2-n4241",6,"Eres mujer, no lo niego,\nno se te puede quitar;\nno más un defecto tienes:\nque los sabes mancornar.",105,2,-1,119,"El muchacho alegre",0,4,"a",21,0,-1,0,251,251,"4241","",0,"","","",1,0,0,[],""],["frenk_t2-n4243",6,"Ya no te quiero, ya no,\nporque eres como la cera:\nte derrites con el sol\ny te pegas con cualquiera.",108,2,8,119,"Estrofa suelta",0,4,"ea",44,0,-1,0,252,252,"4243","",0,"","","",1,0,0,[],""],["frenk_t2-n4244",6,"¿Cómo quieres que te quiera\ncon todo mi corazón,\nsi a todos les das entrada,\ncomo si fueras mesón?",115,2,3,119,"El gusano",0,4,"o",31,0,-1,0,252,252,"4244","",0,"","","",16,0,0,[],""],["frenk_t2-n4247",6,"Un pintor, pintando flores,\npintó un hermoso clavel,\ny no le puso colores,\nporque era falso el papel:\nasí serán tus amores\ndespués de tanto querer.",108,2,8,119,"Estrofa suelta",9,6,"e",-1,0,-1,0,252,252,"4247","",0,"","","",1,0,0,[],""],["frenk_t2-n4248",6,"Ya no te quiero por muía,\npor apegada a la ley;\nquerías ajustar tu yunta,\npero yo no fui tan güey.",105,2,-1,119,"La mulita",0,4,"e",133,0,-1,0,252,252,"4248","",0,"","","",2,0,0,[],""],["frenk_t2-n4249",6,"Ya no te quiero por muía,\nya supe tus picardías:\nquerías ajustar tu yunta\ncon el otro que tenías.",105,2,-1,119,"La mulita",0,4,"ia",214,0,-1,0,253,253,"4249","",0,"","","",2,0,0,[],""],["frenk_t2-n4250",6,"Ya no la aguanto por mala,\nya supe sus picardías:\nquería tirarme en la cuesta,\npero yo ya lo sabía.",105,2,-1,119,"La mulita",0,4,"ia",-1,0,-1,0,253,253,"4250","",0,"","","",1,0,0,[],""],["frenk_t2-n4251",6,"Cabrona no debías de ser,\nque puta siempre lo has sido;\nme presumes de honradez,\ncuando nunca la has tenido.",108,2,8,119,"Estrofa suelta",3,4,"io",101,0,-1,0,253,253,"4251","",0,"","","",1,0,0,[],""],["frenk_t2-n4252",6,"En el vientre de tu madre\nte pusiste de manera\nque te cogiera tu padre\nsin que tu madre sintiera.",108,2,8,119,"Estrofa suelta",1,4,"ea",44,0,-1,0,253,253,"4252","",0,"","","",1,0,0,[],""],["frenk_t2-n4253",6,"Λ mí no me la pegas,\nya ese tiempo se acabó;\nanda, mira a quién enredas,\nporque conmigo ya no.",105,2,-1,119,"Estrofa suelta",0,4,"o",2,0,-1,0,253,253,"4253","",0,"","","",1,0,0,[],""],["frenk_t2-n4254",6,"Tú no puedes presumir,\nni para chiflar te fijas;\nconmigo no has de seguir:\nanda a ver a quién enquinas.\n¡Mal haya tu mal dormir,\nque todo me descobijas!",106,2,4,119,"El querreque",9,6,"ia",-1,0,-1,0,253,253,"4254","",0,"","","",1,0,0,[],""],["frenk_t2-n4255",6,"Ya se me quitó la venda\nque cegado me tenía;\nsi hay otro que te pretenda,\nde mejores garantías\n............... la prenda\n........... y otro que te quería.",106,2,4,119,"El Balajú",9,6,"ia",-1,0,-1,0,253,253,"4255","",0,"","","",1,0,0,[],""],["frenk_t2-n4258",6,"Te voy a comprar tu silla (mi bien),\ntu freno y tu buen suadero,\npara que te ensille otro (mi bien),\nque yo no soy tu vaquero.",115,2,3,119,"Corrido de Laredo",3,4,"eo",38,0,-1,0,254,254,"4258","",0,"","","",1,0,0,[],""],["frenk_t2-n4259",6,"Hoy te falló, mariposa,\nme cansaste y áhi te dejo;\nyo estoy joven, mariposa:\nve a engañar a otro más viejo.",105,2,-1,119,"Uy, uy, mariposa",3,4,"eo",264,0,-1,0,254,254,"4259","",0,"","","",1,0,0,[],""],["frenk_t2-n4260",6,"Ya el águila real voló,\nel nopal quedó temblando.\nYa nuestro amor se acabó:\nno te andes atravesando;\nbusca quién te ribetee,\nporque te andas deshilachando.",108,2,8,119,"Estrofa suelta",9,6,"ao",33,0,-1,0,254,254,"4260","",0,"","","",5,0,0,[],""],["frenk_t2-n4261",6,"Ya el águila real voló,\nel nopal quedó temblando.\nYa no te quiero, ya no:\nno te andes atravesando;\nel amor que tú me distes\nno digas que por desprecios:\npor lo bien que ando quedando.",108,2,8,119,"Estrofa suelta",4,7,"ao",33,0,-1,0,254,254,"4261","",0,"","","",5,0,0,[],""],["frenk_t2-n4262",6,"Puede largarse con otras,\nsi es que ansina le parece;\nsoy de pura yerbabuena,\nque sólita reverdece.",105,2,-1,119,"Chula la mañana",0,4,"ee",64,0,-1,0,254,254,"4262","",0,"","","",1,0,0,[],""],["frenk_t2-n4263",6,"Para mí la pulpa es pecho\ny espinazo la cadera;\nsi se larga con cualquiera,\nque les haga buen provecho.",105,2,-1,119,"La puntada",11,4,"eo",60,0,-1,0,254,254,"4263","",0,"","","",1,0,0,[],""],["frenk_t2-n4264",6,"Si tú tienes vacas,\nyo tengo vacas y bueyes;\nsi quieres hacer mancuernas,\nanda y mancorna tus bueyes.",105,2,-1,119,"La pantera vaciladora",0,4,"ee",-1,0,-1,0,254,254,"4264","",0,"","","",1,0,0,[],""],["frenk_t2-n4265",6,"Naranjas y más naranjas\nmaduras con el viento;\nme alegro que hayas hallado\namores a tu contento.",110,2,10,119,"La jaula",0,4,"eo",94,0,-1,0,254,254,"4265","",0,"","","",2,0,0,[],""],["frenk_t2-n4266",6,"Aquí se peló mi grulla,\npero volvió a emplumecer;\nme alegro que hayas cabido\ndonde no podías caber.",112,2,6,119,"El pelado",0,4,"e",20,0,-1,0,255,255,"4266","",0,"","","",2,0,0,[],""],["frenk_t2-n4267",6,"Ya la naranja colgó,\nya cambió temperamento;\nsi hay otro mejor que yo,\nni agravio, ni sentimiento:\nlá culpa la tengo yo,\ny por eso ni lo siento.",108,2,8,119,"Estrofa suelta, Soy fandanguero",9,6,"eo",94,0,-1,0,255,255,"4267","",0,"","","",1,0,0,[],""],["frenk_t2-n4268",6,"No creas que me perjudico,\ningrata, aunque tuyo fui;\nya que te encontraste un rico,\nno lo desprecies por mí.",105,2,-1,119,"Estrofa suelta",1,4,"i",23,0,-1,0,255,255,"4268","",0,"","","",1,0,0,[],""],["frenk_t2-n4269",6,"En una hamaca de alambre\nse mecía un animalito.\nSi tú ya tienes tu bien,\npor Dios, que no te lo quito;\ncuando mi bien yo lo tenga\ndel tuyo no necesito.",108,2,8,119,"Estrofa suelta",9,6,"io",119,0,-1,0,255,255,"4269","",0,"","","",1,0,0,[],""],["frenk_t2-n4270",6,"Del cielo cayó un pañuelo\nde puntas para llorar;\nquédate con la que quieras:\n¿qué envidia me puede dar?",108,2,8,119,"Estrofa suelta",0,4,"a",21,0,-1,0,255,255,"4270","",0,"","","",17,0,0,[],""],["frenk_t2-n4272",6,"Ya no cortan tus tijeras,\nya no empujan tus dedales;\nvacila con la que quieras,\nque ya para mí no vales.",108,2,8,119,"Estrofa suelta",1,4,"ae",26,0,-1,0,255,255,"4272","",0,"","","",1,0,0,[],""],["frenk_t2-n4273",6,"A pesar del mundo entero,\ndigo que tu amante fui;\nsi tú me das un fiero,\n¿qué cuidado me da a mí?\nAl cabo yo fui primero:\n¿qué puedo desear de ti?",105,2,-1,119,"El siquisirí",9,6,"i",23,0,-1,0,255,255,"4273","",0,"","","",1,0,0,[],""],["frenk_t2-n4274",6,"Arbolito, te secastes\ncon el agua en el pie;\nle dirás a quien te riega\nque yo también te regué.",108,2,8,119,"Estrofa suelta",0,4,"e",77,0,-1,0,255,255,"4274","",0,"","","",2,0,0,[],""],["frenk_t2-n4276",6,"Apriétale bien la arcada,\nno le dejes que se aspee\nquítale bien lo taimado,\npícale pa que trotee;\npregúntale a qué le saben\nlas sobras que le dejé.",116,2,15,119,"El buey**",9,6,"e",-1,0,-1,0,256,256,"4276","",0,"","","",1,0,0,[],""],["frenk_t2-n4277",6,"Si porque te vengo a ver\ncrees que te vengo a rogar,\nno más vine a conocer\nal que ocupa mi lugar.",105,2,-1,119,"Vieja escalera; Estrofa suelta",1,4,"a",21,0,-1,0,256,256,"4277","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4279",6,"No me importa que me crezcan los pitones,\ny ni creas que por tu amor me desbarate,\nque lo mismo duermo yo en buenos colchones\nque me tiro en un méndigo petate.",105,2,-1,119,"Estrofa suelta",3,4,"ae",384,0,-1,0,256,256,"4279","",0,"","","",1,0,0,[],""],["frenk_t2-n4280",6,"Me dicen que te vas a casar,\ny no me dicen con quién;\nme dirás quién es tu novio,\npara darle el parabién.",105,2,-1,119,"El apasionado",3,4,"e",242,0,-1,0,256,256,"4280","",0,"","","",1,0,0,[],""],["frenk_t2-n4281",6,"No me debes ni te debo\nde lo que hemos terminado;\ntú con una, y yo con otro,\ny cada quien por su lado.",105,2,-1,119,"Estrofa suelta",0,4,"ao",14,0,-1,0,256,256,"4281","",0,"","","",1,0,0,[],""],["frenk_t2-n4283",6,"Ahora que yo soy el yunque\nme precisa el aguantar,\npara cuando sea martillo\npegar golpes sin cesar.",105,2,-1,120,"Estrofa suelta",0,4,"a",21,0,-1,0,257,257,"4283","",0,"","","",1,0,0,[],""],["frenk_t2-n4284",6,"Las piedras son y se chocan\nen la corriente del río;\npídele a Dios no encontrarte\nalgún día en mi camino.",105,2,-1,120,"Estrofa suelta",0,4,"io",-1,0,-1,0,257,257,"4284","",0,"rm_t3","","",2,0,0,[],""],["frenk_t2-n4285",6,"Le pido a mi Dios\nmejor que te lleve al cielo;\nporque si vivo en el mundo,\nyo te he de llevar:\nde mí no te has de burlar.",105,2,-1,120,"Oyes, Lupita",7,5,"a",21,0,-1,0,257,257,"4285","",0,"","","",1,0,0,[],""],["frenk_t2-n4286",6,"Si mañana o el pasado\npasares tú por aquí,\npero has de llevar un susto,\nque te has de acordar de mí.",110,2,10,120,"Si te suelto como un trompo",0,4,"i",23,0,-1,0,257,257,"4286","",0,"","","",2,0,0,[],""],["frenk_t2-n4287",6,"Ahora es cuando, yerbabuena,\nle has de dar sabor al caldo,\nporque tengo que ir pa abajo\na darte pronto tu saldo.",105,2,-1,120,"El chúmbale; Estrofa suelta",0,4,"ao",-1,0,-1,0,257,257,"4287","",0,"","","",1,0,0,[],""],["frenk_t2-n4288",6,"Mañana me voy (¡caramba!),\ncomo lo verás,\ny a la vuelta de viaje (¡caramba!)\nme la pagarás.",105,2,-1,120,"El caramba",3,4,"a",51,0,-1,0,257,257,"4288","",0,"","","",2,0,0,[],""],["frenk_t2-n4289",6,"Yo te creía mujercita,\npero eres una coqueta;\nbasta que seas chaparrita\ny que sepas tanta treta;\nyo te hallaré muy sólita\ncuando traiga mi chaveta.",105,2,-1,120,"En una hermosa mañana",9,6,"ea",200,0,-1,0,257,257,"4289","",0,"","","",1,0,0,[],""],["frenk_t2-n4290",6,"¡Cuánto padezco, chinita,\nporque te has vuelto muy loca!\nSólo con mi treinta-treinta\nse te quita lo marota.",107,2,11,120,"La chinita",0,4,"oa",-1,0,-1,0,257,257,"4290","",0,"","","",1,0,0,[],""],["frenk_t2-n4291",6,"La traición que me jugaste,\ntraidora mujer ingrata,\nla ha de lavar mi puñal,\nel de puñito de plata.",105,2,-1,120,"Las estrellas del cielo",0,4,"aa",74,0,-1,0,258,258,"4291","",0,"","","",1,0,0,[],""],["frenk_t2-n4292",6,"¡Ay, Dios, cómo no pensé\nque mi engrimiento era en vano!\n¡Qué mal me has pagado tú!\n¡Qué corazón tan tirano!\nAlgún día me vengaré,\ny quedaremos a mano.",108,2,8,120,"Estrofa suelta, Al pasar por los laureles",9,6,"ao",81,0,-1,0,258,258,"4292","",0,"","","",1,0,0,[],""],["frenk_t2-n4293",6,"Con el amor no se juega,\nhay que tenerlo presente;\nsi tú ya estás decidida\na buscar otro suplente,\nes que no aprecias tu vida\no sabes a qué atenerte.",105,2,-1,120,"Tres balas",9,6,"ee",-1,0,-1,0,258,258,"4293","",0,"","","",1,0,0,[],""],["frenk_t2-n4294",6,"Al pie de un encino rojo\nme puse a sombrear un rato.\nY porque me viste pobre\ncon otro amarraste trato,\nahora me la pagarás,\nhija del ochenta y cuatro.",105,2,-1,120,"El pájaro carpintero; Las flores; El venadito; Estrofa suelta",9,6,"ao",-1,0,-1,0,258,258,"4294","",0,"","","",1,0,0,[],""],["frenk_t2-n4295",6,"Cupido con su vihuela\nme tocó valses de amor.\nMe quisiste darme mueca\ncon cáscara sin dolor;\nalgún día te las daré,\ny eso sí será mejor.",108,2,8,120,"Estrofa suelta",9,6,"o",72,0,-1,0,258,258,"4295","",0,"","","",3,0,0,[],""],["frenk_t2-n4297",6,"Dice que sí,\ndice que no:\nde esos amores\nno quiero yo.",106,2,4,121,"El mosquito",6,4,"o",2,0,-1,0,261,261,"4297","",0,"","","",1,0,0,[],""],["frenk_t2-n4298",6,"Corazones partidos\nyo no los quiero,\nque cuando doy el mío (cielito lindo)\nlo doy entero.",107,2,11,121,"Cielito lindo; Estrofa suelta",3,4,"eo",38,0,-1,0,261,261,"4298","",0,"","","",7,0,0,[],""],["frenk_t2-n4299",6,"Tampoco pido limosna\nde amores de medio real:\nlos buenos a mí me sobran\ny hasta me vienen a procurar.",105,2,-1,121,"¡Arriba Sinaloa!",3,4,"a",-1,0,-1,0,261,261,"4299","",0,"","","",1,0,0,[],""],["frenk_t2-n4300",6,"Dile que sí, que sí, que sí,\ndile que no, que no, que no,\nque estando mi amor tan lejos,\n¿para qué lo quiero yo?",110,2,10,121,"Ya no quiero ser arriero",0,4,"o",2,0,-1,0,261,261,"4300","",0,"","","",1,0,0,[],""],["frenk_t2-n4302",6,"Mariquita, dile a Bruna\nque no me mande a buscar,\nque yo ando haciendo fortuna\npor las orillas del mar,\npa mandarle buena cuna\npara acabarla de criar.",112,2,6,121,"El caimán",9,6,"a",21,0,-1,0,261,261,"4302","",0,"","","",1,0,0,[],""],["frenk_t2-n4303",6,"Nada menos noche [me] dijo\nque me fuera desvelando\ny que te olvidara a ti;\nyo le contesté llorando:\n“Pobrecita, infeliz.”",106,2,4,121,"El fandanguito",7,5,"i",-1,0,-1,0,261,261,"4303","",0,"","","",1,0,0,[],""],["frenk_t2-n4305",6,"Quién sabe qué quedrá este hombre,\nque no me deja dormir;\nle he de avisar a mi madre,\nsi acaso vuelve a venir.",105,2,-1,121,"Estrofa suelta",0,4,"i",157,0,-1,0,262,262,"4305","",0,"","","",1,0,0,[],""],["frenk_t2-n4306",6,"Pájaros, pájaros, pájaros,\npájaros de buche verde;\n¡cómo estará aquella gata,\nque hasta la cola se muerde!",110,2,10,121,"Pájaros, pájaros, pájaros",0,4,"ee",154,0,-1,0,262,262,"4306","",0,"","","",1,0,0,[],""],["frenk_t2-n4307",6,"¿Qué dirá la lagañosa?,\n¿que por ella me desvelo?\nGloria al Padre, gloria al Hijo,\ngloria al Espíritu Santo.",110,2,10,121,"Rezos humorísticos",5,4,"ao",-1,0,-1,0,262,262,"4307","",0,"","","",1,0,0,[],""],["frenk_t2-n4308",6,"¿Qué dirá la pescuezona?,\n¿que por ella voy al barrio?\nNi por ella ni por otra,\npescuezo de campanario.",108,2,8,121,"Estrofa suelta, Al pasar por tu ventana",0,4,"ao",-1,0,-1,0,262,262,"4308","",0,"","","",1,0,0,[],""],["frenk_t2-n4309",6,"En el vaso más dorado\nbebí el veneno más cruel.\n¿Qué pensará este idiota?,\n¿que yo me muero por él?\nPero, mas no lo ha sabido\nque tengo otro mejor que él.",109,2,7,121,"Estrofa suelta",9,6,"e",-1,0,-1,0,262,262,"4309","",0,"","","",1,0,0,[],""],["frenk_t2-n4310",6,"He tenido otras mujeres\nque les he pagado mal,\ncuantimás esa lechuza\nque me hallé en el muladar.",112,2,6,121,"La muía de siete cuartas",0,4,"a",-1,0,-1,0,262,262,"4310","",0,"","","",1,0,0,[],""],["frenk_t2-n4311",6,"Voy a echar mi pecho al agua\ny a olvidar esa mujer,\npues, amigos, lo que tiro\nno lo vuelvo a recoger.",132,2,25,121,"Mariquita; Estrofa suelta",0,4,"e",20,0,-1,0,262,262,"4311","",0,"","","",1,0,0,[],""],["frenk_t2-n4312",6,"Un orgullo sólo tengo:\nque a naiden le sé rogar,\nque la chancla que yo tiro\nno la vuelvo a levantar.",107,2,11,121,"La chancla",0,4,"a",21,0,-1,0,262,262,"4312","",0,"","","",1,0,0,[],""],["frenk_t2-n4313",6,"Las estrellas en el cielo\nse retiran del nublado;\nasí me retiro yo\nantes que me hagan a un lado.",108,2,8,121,"Estrofa suelta",0,4,"ao",14,0,-1,0,263,263,"4313","",0,"","","",18,0,0,[],""],["frenk_t2-n4314",6,"Un anillo de oro liso\nque en el mar se me cayó;\nun amor que no me quiso\n¿para qué lo quiero yo?",108,2,8,121,"Estrofa suelta",1,4,"o",2,0,-1,0,263,263,"4314","",0,"","","",1,0,0,[],""],["frenk_t2-n4315",6,"Balajú se fue a la guerra\ny no me quiso llevar;\nvaya con Dios Balajú,\nque él me la ha de pagar.",106,2,4,121,"El Balajú",0,4,"a",21,0,-1,0,263,263,"4315","",0,"","","",3,0,0,[],""],["frenk_t2-n4316",6,"Se oyó el grito de una vieja\ncuando ya voy a llegar;\npero si un día se atraviesa,\nella me la va a pagar.",113,2,2,121,"El gavilán del sur",0,4,"a",21,0,-1,0,263,263,"4316","",0,"","","",1,0,0,[],""],["frenk_t2-n4317",6,"En una bandeja de oro\ncuatro tropezones di.\n¿Qué dirá ese recabrón?,\n¿que se va a burlar de mí?\nLo he de dejar a mi modo,\naunque me vaya de aquí.",108,2,8,121,"Estrofa suelta",9,6,"i",23,0,-1,0,263,263,"4317","",0,"","","",1,0,0,[],""],["frenk_t2-n4318",6,"Una sota y un caballo\nburlarse querían de mí:\n¡mal haya quien dijo miedo,\nsi para morir nací!",105,2,-1,121,"La chancla",0,4,"i",23,0,-1,0,263,263,"4318","",0,"","","",1,0,0,[],""],["frenk_t2-n4319",6,"¡Maldita sea el hombre,\ny quien lo nació!\nMis ojos lo vean\ny en una prisión,\nya hecho cenizas,\ny un..................\nMis ojos lo vean\ny en una picota,\nniño chiquito,\ny azota y azota.",106,2,4,121,"El coco",18,10,"oa",432,0,-1,0,263,263,"4319","",0,"","","",1,0,0,[],""],["frenk_t2-n4320",6,"Yo sé querer como el que sepa amar,\npero en capricho también sé aborrecer;\nmi primavera me trata de olvidar:\nvaya la ingrata, yo ya me vengaré.",115,2,3,121,"Las aves",3,4,"e",-1,0,-1,0,263,263,"4320","",0,"","","",1,0,0,[],""],["frenk_t2-n4321",6,"Yo ya no quiero a mi Juana,\npues no tiene corazón;\nme trataba con desprecio,\nsin tenerme compasión.",105,2,-1,121,"La Juanita",0,4,"o",31,0,-1,0,263,263,"4321","",0,"","","",1,0,0,[],""],["frenk_t2-n4323",6,"Mi chinita no me quiere,\ny me alumbro con un faro;\nfarolito de mi vida,\nalumbrador de la noche,\nlevántame de mañana,\npa oír cantar el huiltacoche.",115,2,3,121,"El vaquero",9,6,"oe",337,0,-1,0,264,264,"4323","",0,"","","",1,0,0,[],""],["frenk_t2-n4324",6,"Ni sentido, ni agraviado,\nni por eso he de llorar,\nque el que me enseñó a querer\ntambién me enseñó a olvidar.",132,2,25,121,"Mariquita; Ojitos aceitunados; Estrofa suelta",0,4,"a",21,0,-1,0,264,264,"4324","",0,"","","",1,0,0,[],""],["frenk_t2-n4325",6,"El amor de mi novia\nes medio loco:\nsi ella ya no me quiere (cielito lindo),\nni yo tampoco;\ncuentas cabales:\nsi ella ya no me quiere (cielito lindo),\nestamos iguales.",112,2,6,121,"Cieüto lindo",4,7,"ae",26,0,-1,0,264,264,"4325","",0,"","","",2,0,0,[],""],["frenk_t2-n4327",6,"Lo mismo que estás sufriendo,\nun amor me hizo sufrir;\nal principio yo lloraba\ny ahora me pongo a reír.",105,2,-1,121,"Pajarito jaralero",3,4,"i",157,0,-1,0,264,264,"4327","",0,"","","",1,0,0,[],""],["frenk_t2-n4328",6,"Una lechuga en el campo\ncon el rocío reverdece;\nun amor grande perdí,\npero ¿qué cuidado es ése?",105,2,-1,121,"La Zandunga",0,4,"ee",65,0,-1,0,264,264,"4328","",0,"","","",1,0,0,[],""],["frenk_t2-n4329",6,"Estoy al vender una ingrata,\nque me pagó con desdén;\náhi la voy a dar muy barata\npor lo primero que den.",115,2,3,121,"Estrofa suelta",3,4,"e",242,0,-1,0,264,264,"4329","",0,"","","",2,0,0,[],""],["frenk_t2-n4330",6,"Amor como el que perdí\nno lo volveré a encontrar;\npasando la Nochebuena\notra me vuelvo a encontrar.",105,2,-1,121,"La chaparrita",0,4,"a",-1,0,-1,0,264,264,"4330","",0,"","","",2,0,0,[],""],["frenk_t2-n4331",6,"¿Y cómo no he de sentir\nque se me fue y me abandonó?\nAhora, para no sentir,\nes buscarme otra mejor.",109,2,7,121,"Amor consentido",3,4,"o",-1,0,-1,0,265,265,"4331","",0,"","","",1,0,0,[],""],["frenk_t2-n4332",6,"Así se acabó la pena:\nanidando otra criatura\ncon una linda morena;\nahora mi alma se cura\npasando una vida buena.",112,2,6,121,"Estrofa suelta",7,5,"ea",59,0,-1,0,265,265,"4332","",0,"","","",1,0,0,[],""],["frenk_t2-n4333a",6,"¡Chingue su madre el amor\nque no me supo querer!\nPor eso puso mi Dios\nmujeres para escoger.",108,2,8,121,"Estrofa suelta",0,4,"e",20,0,-1,0,265,265,"4333a","",0,"","","",1,0,0,[],""],["frenk_t2-n4334",6,"He ganado las tierras que tengo,\nademás de la yegua plateada;\nno las cambio, ni alquilo, ni vendo,\npa comprar una mula ensillada.",105,2,-1,121,"El Pata Rajada",3,4,"aa",49,0,-1,0,265,265,"4334","",0,"","","",1,0,0,[],""],["frenk_t2-n4335",6,"Dicen que rogar no es bueno\na mujer engañadora;\ny digo esto por Antonia,\nque anda con otros amores,\ny muía que masca el freno\nse le quedan los sabores.",111,2,1,121,"Antonia",9,6,"oe",5,0,-1,0,265,265,"4335","",0,"","","",1,0,0,[],""],["frenk_t2-n4336",6,"Amigos de mi camada,\nyo les vengo a noticiar\nque la muía que ensillaba\nya no la vuelvo a ensillar.",105,2,-1,121,"La mulita",0,4,"a",21,0,-1,0,265,265,"4336","",0,"","","",1,0,0,[],""],["frenk_t2-n4337",6,"La muía que yo ensillaba\nla ensilla mi compañero;\nel gusto que a mí me queda,\nque yo la ensillé primero.",105,2,-1,121,"La mulita; Las ventanas; Estrofa suel ta",0,4,"eo",38,0,-1,0,265,265,"4337","",0,"","","",1,0,0,[],""],["frenk_t2-n4338",6,"¡Ay, Dios, de mis algodones,\ncuando yo era algodonero!\nLa tierra que yo sembré\nla siembra mi compañero:\nno me da ningún dolor,\npues yo la sembré primero.",108,2,8,121,"Estrofa suelta",9,6,"eo",38,0,-1,0,266,266,"4338","",0,"","","",1,0,0,[],""],["frenk_t2-n4339",6,"Qué bonitas campanitas\nlas que toca el campanero;\nel consuelo que me queda,\nque yo las toqué primero.",105,2,-1,121,"Las campanitas",0,4,"eo",38,0,-1,0,266,266,"4339","",0,"","","",6,0,0,[],""],["frenk_t2-n4340",6,"Tengo mi par de pistolas\ncon sus tiros de metal:\nuno para mi querida\ny otro para mi rival.",116,2,15,121,"La rielera",0,4,"a",1,0,-1,0,266,266,"4340","",0,"","","",2,0,0,[],""],["frenk_t2-n4341",6,"La buena ocasión bendigo:\nya se fue la que yo amaba;\ny aunque de ella nada digo,\nla verdad, que me chocaba:\nno era muy mala conmigo,\npero sí me regañaba.",105,2,-1,122,"Paula",9,6,"aa",28,0,-1,0,267,267,"4341","",0,"","","",1,0,0,[],""],["frenk_t2-n4342",6,"Yo enamoré una morena,\nque iba para su destino;\ncuando la llegué a querer\nmuy pronto le di el camino,\nporque me quería tener\ncomo plátano en racimo.",105,2,-1,122,"La morena; El gusto; El querreque",9,6,"io",-1,0,-1,0,267,267,"4342","",0,"","","",1,0,0,[],""],["frenk_t2-n4343",6,"Muchas veces se enojaba\nporque yo la consentía;\nhasta que ya me colmaba,\nentonces sí le decía:\n“Paula, mala y despiadada,\nahora sí llegó tu día.”",105,2,-1,122,"Paula",9,6,"ia",0,0,-1,0,267,267,"4343","",0,"","","",1,0,0,[],""],["frenk_t2-n4345",6,"Yo enamoré una mujer\nalta, bonita y delgada;\nla tuve que aborrecer,\nme salió muy descarada;\nparecía puerta de hotel:\na todos les daba entrada.",105,2,-1,122,"La guacamaya; El querreque; El pá jaro carpintero",9,6,"aa",49,0,-1,0,267,267,"4345","",0,"","","",3,0,0,[],""],["frenk_t2-n4346b",6,"Tuve amor y no lo tuve,\ny el que tuve se me fue;\nhago de cuenta que tuve\nuna huerta y la regué,\ny con ella me entretuve\nmientras que nuevo encontré.",108,2,8,122,"Estrofa suelta",9,6,"e",77,0,-1,0,268,268,"4346b","",0,"","","",3,0,0,[],""],["frenk_t2-n4347",6,"Tuve amor y no tuve,\nyo tuve un amor y no;\ny hago de cuenta que tuve\nuna milpa y se perdió,\ny con ella me entretuve\nmientras la otra se llegó.",106,2,4,122,"Estrofa suelta",9,6,"o",2,0,-1,0,268,268,"4347","",0,"","","",1,0,0,[],""],["frenk_t2-n4349",6,"Soy pájaro acagualero,\npero no de los de aquí;\nme nombran “El embustero”\nporque engañé una que vi,\nque le prometí dinero\ny después no se lo di.",106,2,4,122,"El carpintero",9,6,"i",23,0,-1,0,268,268,"4349","",0,"","","",2,0,0,[],""],["frenk_t2-n4350",6,"Soy pájaro acagualero,\nde las alas coloradas;\nmi nombre es “El embustero”,\nporque engañé una casada\nque le prometí dinero\ny después no le di nada.",105,2,-1,122,"El carpintero, Zapateado",9,6,"aa",49,0,-1,0,268,268,"4350","",0,"","","",2,0,0,[],""],["frenk_t2-n4351",6,"No sé qué es amar de veras:\ncomo que entra comezón,\ncomo que nos dan piquetes\nen mitad del corazón.",105,2,-1,123,"Las mañanitas",0,4,"o",31,0,-1,0,273,273,"4351","",0,"","","",1,0,0,[],""],["frenk_t2-n4352",6,"En la postura del sol\ncantaban dos palomitas,\ny decían con gran dolor\nde ellas la más bonita:\n“¿Qué cosa será el amor,\nque todos los miedos quita?”",108,2,8,123,"El siquisirí",9,6,"ia",50,0,-1,0,273,273,"4352","",0,"","","",1,0,0,[],""],["frenk_t2-n4353",6,"Le pregunté a Salomón\nque por favor me dijera\nque cuál es esa impresión\nque del hombre se apodera\ncuando forma su ilusión\ny en una joven soltera.",106,2,4,123,"Yo te quiero y te venero",9,6,"ea",44,0,-1,0,273,273,"4353","",0,"","","",1,0,0,[],""],["frenk_t2-n4354c",6,"En la medianía del mar\nle dijo Cupido a Venus:\n“¿Ya viste relampaguear?\nAhora te faltan los truenos;\ndel diablo te escaparás,\npero de mí, lo veremos.”",106,2,4,123,"La morena",9,6,"eo",-1,0,-1,0,273,273,"4354c","",0,"","","",6,0,0,[],""],["frenk_t2-n4355",6,"En el puente de amatiste\ndicen que tu amor no pasa;\nyo digo que es imposible,\nporque el amor despedaza\nla piedra más invencible.",126,2,19,123,"Estrofa suelta",7,5,"ie",259,0,-1,0,273,273,"4355","",0,"","","",1,0,0,[],""],["frenk_t2-n4357",6,"Para sarapes, Saltillo;\nChihuahua, para soldados;\npara mujeres, Jalisco,\npara amar, toditos lados.",107,2,11,123,"La cucaracha",0,4,"ao",18,0,-1,0,274,274,"4357","",0,"","","",1,0,0,[],""],["frenk_t2-n4358",6,"Compadre, el mundo se acaba,\ntodo viviente es ladrón:\nel que no roba dinero,\npero roba corazón.",108,2,8,123,"Estrofa suelta",0,4,"o",31,0,-1,0,274,274,"4358","",0,"","","",1,0,0,[],""],["frenk_t2-n4359",6,"¡Y áhi nomás, y áhi nomás!,\ntoda la vida así sea:\ncomo se quiere a una bonita,\nasí se quiere a una fea.",105,2,-1,123,"El maracumbé",3,4,"ea",54,0,-1,0,274,274,"4359","",0,"","","",1,0,0,[],""],["frenk_t2-n4361",6,"Dicen que los gavilanes\nnunca pierden una presa\ny que muchos caporales\nquedan de segunda mesa,\nporque hay mujeres fatales\nque los cogen de sorpresa.",105,2,-1,123,"El queretano",9,6,"ea",201,0,-1,0,274,274,"4361","",0,"","","",2,0,0,[],""],["frenk_t2-n4362",6,"El amor es un niño\nque cuando nace\ncon poco que le den\nse satisface;\ny va creciendo,\ny entre más le van dando (cielito lindo),\nmás va queriendo.",111,2,1,123,"Cielito lindo",4,7,"eo",52,0,-1,0,274,274,"4362","",0,"","","",2,0,0,[],""],["frenk_t2-n4363",6,"El amor nos fortalece,\nla separación nos hiere;\ny por más que se padece,\ncuando a una mujer se quiere\ndiariamente el amor crece.",111,2,1,123,"La azucena",7,5,"ee",-1,0,-1,0,274,274,"4363","",0,"","","",1,0,0,[],""],["frenk_t2-n4364",6,"Los amores más bonitos\nson como la verdolaga:\nno más le pones tantito,\ny crecen como una plaga.",105,2,-1,123,"La verdolaga",0,4,"aa",480,0,-1,0,275,275,"4364","",0,"","","",1,0,0,[],""],["frenk_t2-n4366",6,"Es amor una araña,\nque con cautela\nen un rincón del alma\nforma su tela:\ncon tal sigilo,\nque ningún sabio pudo\ncortar el hilo.",105,2,-1,123,"Estrofa suelta",4,7,"io",247,0,-1,0,275,275,"4366","",0,"rm_t4, palau_cantares","","",3,0,0,[],""],["frenk_t2-n4367",6,"El amor, yo te aseguro,\nno tan fácil se desata,\nporque queda tan seguro\ncomo el águila en la plata.",105,2,-1,123,"Mariquita",1,4,"aa",74,0,-1,0,275,275,"4367","",0,"","","",1,0,0,[],""],["frenk_t2-n4368",6,"En las cumbres de una palma\ny en las puertas de un convento\nme puse a pensar con calma,\ny me vino el contratiempo:\nque el amor que llega al alma\nno se borra ni un momento.",105,2,-1,123,"El siquisirí, Zapateado",9,6,"eo",-1,0,-1,0,275,275,"4368","",0,"","","",1,0,0,[],""],["frenk_t2-n4369a",6,"Y estándome columpiando\nse me reventó la reata;\ny el amor que se hace nudo\ncon trabajo se desata.",105,2,-1,123,"La chinita maderista",0,4,"aa",74,0,-1,0,275,275,"4369a","",0,"","","",1,0,0,[],""],["frenk_t2-n4370",6,"Cupido me dio un estudio,\nse lo regalé a mi chata;\nme habló con disimulo:\n“Toma esta concha de plata,\nque el amor que se hace nudo\ncon trabajos se desata.”",108,2,8,123,"Estrofa suelta",9,6,"aa",74,0,-1,0,275,275,"4370","",0,"","","",1,0,0,[],""],["frenk_t2-n4372",6,"Si a pesar de desdenes,\ndura el afecto,\npasión es incurable\ny amor eterno.",105,2,-1,123,"Estrofa suelta",6,4,"eo",-1,0,-1,0,276,276,"4372","",0,"","","",2,0,0,[],""],["frenk_t2-n4373",6,"Si los desdenes crecen\nun hondo afecto,\nes señal muy segura\nde amor eterno.",105,2,-1,123,"Estrofa suelta",6,4,"eo",-1,0,-1,0,276,276,"4373","",0,"","","",1,0,0,[],""],["frenk_t2-n4374",6,"Si los desdenes matan\nuna pasión,\nfue un amor pasajero,\nque se eclipsó.",105,2,-1,123,"Estrofa suelta",6,4,"o",-1,0,-1,0,276,276,"4374","",0,"","","",1,0,0,[],""],["frenk_t2-n4376",6,"En una jaula de plata\nse quejaba un pajarito,\ny en el quejido relata\nde un modo muy exquisito:\n“Dicen que el amor no mata,\npero lastima un poquito.”",106,2,4,123,"Estrofa suelta",9,6,"io",119,0,-1,0,276,276,"4376","",0,"","","",1,0,0,[],""],["frenk_t2-n4377",6,"Hay quereres de despecho,\nhay quereres de ilusiones,\nhay quereres que se alquilan\ncomo las habitaciones.",105,2,-1,123,"Estrofa suelta",0,4,"oe",34,0,-1,0,276,276,"4377","",0,"palau_cantares","","",2,0,0,[],""],["frenk_t2-n4378",6,"Cuatro palomitas blancas\nparadas en un romero,\nunas a las otras dicen:\n“No hay amor como el primero.”",110,2,10,123,"Cuatro palomitas blancas; El jarabe; El palomo; Pregón del ante",0,4,"eo",38,0,-1,0,276,276,"4378","",0,"frenk_t4","","",5,0,0,[],""],["frenk_t2-n4380",6,"Dicen que el primer amor (¡ay, Llorona!)\nes grande y es verdadero,\npero el último es mejor\ny más grande que el primero.",108,2,8,123,"La Llorona",3,4,"eo",38,0,-1,0,277,277,"4380","",0,"","","",1,0,0,[],""],["frenk_t2-n4381",6,"De oro es el primer amor,\nel que le sigue es de plata,\nel tercero y los demás\nse vuelven de pura lata.",112,2,6,123,"Estrofa suelta",0,4,"aa",74,0,-1,0,277,277,"4381","",0,"","","",1,0,0,[],""],["frenk_t2-n4382",6,"Ni sopa recalentada,\nni amor por segunda vez,\nporque ni la sopa es sopa,\nni el amor tampoco lo es.",105,2,-1,123,"Estrofa suelta",0,4,"e",218,0,-1,0,277,277,"4382","",0,"","","",1,0,0,[],""],["frenk_t2-n4383",6,"¡Qué bonito gavilán\ncon sus alitas plateadas!,\npero más bonitas son\nlas solteras y casadas.",106,2,4,123,"El gavilán",0,4,"aa",282,0,-1,0,277,277,"4383","",0,"","","",2,0,0,[],""],["frenk_t2-n4384",6,"El hombre que siempre es hombre\nnada en el mundo le apena;\nes guaje si se condena\na vivir con una sola:\npor eso es bueno tener\nsiquiera media docena.",113,2,2,123,"El cuerudo",9,6,"ea",59,0,-1,0,277,277,"4384","",0,"","","",1,0,0,[],""],["frenk_t2-n4385",6,"Pájaro, ¡qué bien te ves\nen esa jaula que brilla!\nDicen que dichoso no es,\npor más que la jaula briUa:\ngusto del pájaro es\npicar distinta semilla.",108,2,8,123,"El pájaro cú; La morena",9,6,"ia",162,0,-1,0,277,277,"4385","",0,"","","",1,0,0,[],""],["frenk_t2-n4386",6,"¿Quién dice que no se goza\ncon gusto lo que es ajeno?\nBien sabiéndolo gozar,\nse goza mejor que el dueño.",105,2,-1,123,"La Sanmarqueña",0,4,"eo",-1,0,-1,0,277,277,"4386","",0,"","","",4,0,0,[],""],["frenk_t2-n4387",6,"Para el hambre las semitas,\npara las tunas el gancho,\npara las niñas bonitas\nun hombre de sombrero ancho.",105,2,-1,123,"El sombrero ancho",1,4,"ao",380,0,-1,0,277,277,"4387","",0,"","","",1,0,0,[],""],["frenk_t2-n4389",6,"Los toros son los que braman\ndebajo de las higueras;\nlas mujeres son las que aman\na aquellos de calzoneras.",114,2,17,123,"El toro",1,4,"ea",103,0,-1,0,278,278,"4389","",0,"","","",4,0,0,[],""],["frenk_t2-n4390",6,"Los toros son los que braman\nadentro de los potreros;\nlas mujeres son las que aman\na aquellos hombres sinceros,\npalmeros y guitarreros.",105,2,-1,123,"El toro",7,5,"eo",22,0,-1,0,278,278,"4390","",0,"","","",4,0,0,[],""],["frenk_t2-n4391",6,"El ser negro no es afrenta,\nni color que quita fama;\nel zapato negro luce\nal pie de la mejor dama.",108,2,8,123,"Estrofa suelta",0,4,"aa",90,0,-1,0,278,278,"4391","",0,"","","",1,0,0,[],""],["frenk_t2-n4392",6,"Dicen que los ojos negros,\npara platicar de amores,\nen una mirada de ellos\nle dicen a uno primores.",105,2,-1,123,"Los ojos mexicanos",0,4,"oe",5,0,-1,0,278,278,"4392","",0,"","","",1,0,0,[],""],["frenk_t2-n4394",6,"Ojos verdes y azules,\nmala pintura:\ndonde no hay ojos negros\nno hay hermosura.",106,2,4,123,"La bamba",6,4,"ua",17,0,-1,0,278,278,"4394","",0,"","","",1,0,0,[],""],["frenk_t2-n4395",6,"Ojos negros y pardos\nson los comunes,\npero los de mi agrado\nson los azules.",106,2,4,123,"La bamba",6,4,"ue",-1,0,-1,0,278,278,"4395","",0,"","","",4,0,0,[],""],["frenk_t2-n4396",6,"Los ojos verdes son traicioneros,\nlos ojos negros son hechiceros,\ny los cafés no sólo son lindos,\nsino sinceros.",107,2,11,123,"Estrofa suelta",3,4,"eo",22,0,-1,0,278,278,"4396","",0,"","","",1,0,0,[],""],["frenk_t2-n4397",6,"Dicen que los ojos azules,\nlos ojos color de cielo,\nno dicen nada de amores\ny sí mucho de celo.",105,2,-1,123,"Los ojos mexicanos",0,4,"eo",10,0,-1,0,278,278,"4397","",0,"","","",1,0,0,[],""],["frenk_t2-n4398",6,"Dicen que los ojos verdes\nson emblema de olvido,\npues ellos prometen un alma,\ncosa que nunca han tenido.",105,2,-1,123,"Los ojos mexicanos",0,4,"io",101,0,-1,0,279,279,"4398","",0,"","","",1,0,0,[],""],["frenk_t2-n4399",6,"A la mar se parecen\nlos que se aman:\nque hay tempestades fuertes\ny días de calma.",105,2,-1,123,"Estrofa suelta",6,4,"aa",-1,0,-1,0,279,279,"4399","",0,"","","",1,0,0,[],""],["frenk_t2-n4400",6,"Piensan los enamorados,\npiensan y no piensan bien,\npiensan que nadie los mira,\ny todo el mundo los ve.",105,2,-1,123,"Estrofa suelta",0,4,"e",-1,0,-1,0,279,279,"4400","",0,"rm_t4, palau_cantares, andina_t2, lafuente_madrid","","",7,0,0,[],""],["frenk_t2-n4401",6,"Los higos y los duraznos\nen el árbol se maduran;\nlos ojitos que se quieren\ndesde lejos se saludan.",105,2,-1,123,"El durazno; Las ventanas; Bonito San Juan del Río; El jarabe; La Julia; El ramo; La Sanmarqueña; Estrofa suel­",0,4,"ua",-1,0,-1,0,279,279,"4401","",0,"","","",1,0,0,[],""],["frenk_t2-n4402",6,"Si acaso saber quieres\nsi dos se aman,\nmira cómo se miran,\nmejor que cómo se hablan.",105,2,-1,123,"Estrofa suelta",3,4,"aa",-1,0,-1,0,279,279,"4402","",0,"","","",3,0,0,[],""],["frenk_t2-n4403",6,"Las palabras amorosas\nson las cuentas de un collar:\nen saliendo la primera,\nsalen todas las demás.",105,2,-1,123,"Al derecho y al revés; Estrofa suelta",0,4,"a",-1,0,-1,0,279,279,"4403","",0,"palau_cantares","","",5,0,0,[],""],["frenk_t2-n4404",6,"Eres vaso de cristal\nque en la mar andas nadando;\nno hay amor que no se rinda\napretándole la mano.",115,2,3,123,"Mariquita",0,4,"ao",-1,0,-1,0,279,279,"4404","",0,"","","",2,0,0,[],""],["frenk_t2-n4406",6,"Cuando dos quieren a una\ny los dos están presentes,\nel uno cierra los ojos\ny el otro aprieta los dientes.",114,2,17,123,"Yo ya me voy; El novillo despuntado",0,4,"ee",252,0,-1,0,280,280,"4406","",0,"rm_t4, palau_cantares, lafuente_madrid","","",8,0,0,[],""],["frenk_t2-n4407",6,"Todo el que anda parrandeando\nnunca se fija pa atrás;\nla mujer lo está tanteando,\nmirando pa dónde va,\ny otro se está aprovechando:\neso es con seguridad.",106,2,4,123,"El pájaro cú",9,6,"a",-1,0,-1,0,280,280,"4407","",0,"","","",1,0,0,[],""],["frenk_t2-n4408",6,"El que de nuevo se casa\nno goza ningún placer;\ncuando más amor le nace\nnadie lo puede querer,\nporque le estorban los lazos\ny el velo de la mujer.",106,2,4,123,"El Ahualulco",9,6,"e",20,0,-1,0,280,280,"4408","",0,"","","",1,0,0,[],""],["frenk_t2-n4410",6,"Máquina, ¿por qué no andas?,\n¿porque te falta el vapor?\nAsí no andan los hombres\ncuando les falta su amor.",105,2,-1,123,"Las campanitas",0,4,"o",72,0,-1,0,280,280,"4410","",0,"","","",1,0,0,[],""],["frenk_t2-n4411",6,"Del cielo cayó una rosa,\nen el suelo se estrelló;\nasí se estrellan los hombres\ncuando les dicen que no.",129,2,9,123,"Estrofa suelta",0,4,"o",2,0,-1,0,280,280,"4411","",0,"","","",5,0,0,[],""],["frenk_t2-n4412",6,"El hombre desde al nacer\nya no es suyo el corazón:\nse lo entrega a la mujer\nen prueba de su pasión,\naunque sea ingrata en querer.",113,2,2,123,"Estrofa suelta",7,5,"e",20,0,-1,0,280,280,"4412","",0,"","","",1,0,0,[],""],["frenk_t2-n4413",6,"El hombre desde que nace\nnace para padecer;\ncon poco se satisface\ncuando se encuentra una mujer:\nque Dios para eso las hace.",113,2,2,123,"El aguanieve",7,5,"ae",84,0,-1,0,281,281,"4413","",0,"","","",1,0,0,[],""],["frenk_t2-n4414a",6,"El que sabe de pasiones\nno puede morir de espanto,\nni llegan las ocasiones\nque el hombre quiera ser santo,\npues no faltan tentaciones.",106,2,4,123,"El apasionado",7,5,"oe",34,0,-1,0,281,281,"4414a","",0,"","","",2,0,0,[],""],["frenk_t2-n4415",6,"Cuando al mundo bajó Eva,\nAdán placer no tenía;\nsolo se alojó a una higuera,\nviendo un libro que decía:\n“Si la mujer no existiera,\nel hombre no pecaría.”",105,2,-1,123,"Dios a la mujer formó",9,6,"ia",0,0,-1,0,281,281,"4415","",0,"","","",1,0,0,[],""],["frenk_t2-n4416",6,"El que llega a los sesenta\ny de amar no se arrepiente\nes mejor que dos de a treinta\ny mejor que tres de a veinte.",105,2,-1,123,"Estrofa suelta",0,4,"ee",-1,0,-1,0,281,281,"4416","",0,"","","",1,0,0,[],""],["frenk_t2-n4417",6,"Hay hombres que por mujer\ncogen el vicio del robo:\nla vida van a exponer\npor querer tenerle todo\na la reina del placer.",112,2,6,123,"Estrofa suelta",7,5,"e",20,0,-1,0,281,281,"4417","",0,"","","",1,0,0,[],""],["frenk_t2-n4418",6,"Amada mariposita,\n¡cuánto pesa tu cadena!\nEl que ama mujer bonita\ntoda la noche la sueña,\nmayormente si es bonita,\ncon su boquita risueña.",105,2,-1,123,"Estrofa suelta",9,6,"ea",291,0,-1,0,281,281,"4418","",0,"","","",1,0,0,[],""],["frenk_t2-n4419a",6,"Navegando en una tabla\ndonde mi amor desvanece,\ndijo un pajarito en jaula:\n“Él que de amores padece\nhasta con las piedras habla.”",105,2,-1,123,"El feo",7,5,"aa",-1,0,-1,0,281,281,"4419a","",0,"","","",3,0,0,[],""],["frenk_t2-n4420a",6,"La lluvia viene y estremece\nal agua cristalina;\nque el que de amores padece\nse pasa la noche entera\nmirando para la cocina.",112,2,6,123,"Estrofa suelta",7,5,"ia",11,0,-1,0,282,282,"4420a","",0,"","","",1,0,0,[],""],["frenk_t2-n4420b",6,"Aguanieves se entretejen.\nEl que de amores padece\ny en el agua cristalina\ntoda la noche camina,\nen el patio le amanece,\nmirando pa la cocina.",112,2,6,123,"El aguanieve",9,6,"ia",11,0,-1,0,282,282,"4420b","",0,"","","",1,0,0,[],""],["frenk_t2-n4421",6,"Qué pobre es la vida del pobre\npa’l rico el oro es desgracia,\ny el amor de la escondida\nes para el hombre desgracia.",105,2,-1,123,"La escondida",0,4,"aa",-1,0,-1,0,282,282,"4421","",0,"","","",1,0,0,[],""],["frenk_t2-n4422",6,"¡Qué bonita es una banda\ntirada en un campo verde!\nEl que tiene su amor lejos\nse acuesta, pero no duerme.",105,2,-1,123,"La banda; La Juanita; Estrofa suelta",0,4,"ee",-1,0,-1,0,282,282,"4422","",0,"","","",1,0,0,[],""],["frenk_t2-n4423",6,"Por las calles van vendiendo\naguardiente en una taza;\n¡qué cobarde[s] son los hombres\nque cuentan lo que les pasa!",117,2,5,123,"Estrofa suelta",0,4,"aa",123,0,-1,0,282,282,"4423","",0,"","","",2,0,0,[],""],["frenk_t2-n4424",6,"A la guayaba madura\nse le quita la pepita;\nel hombre cuando es celoso\nno busca mujer bonita.",108,2,8,123,"La Sanmarqueña",0,4,"ia",50,0,-1,0,282,282,"4424","",0,"","","",1,0,0,[],""],["frenk_t2-n4425",6,"No más de puro coraje\nmueren todos los celosos;\nviendo moros con tranchetes,\nparecen perros rabiosos:\npobrecitas las mujeres\nque tienen esos esposos.",105,2,-1,123,"Los celotes",9,6,"oo",186,0,-1,0,282,282,"4425","",0,"","","",1,0,0,[],""],["frenk_t2-n4426",6,"¡Canastos, cómo hay celosos,\ny todos desobligados!\nTienen sus pobres mujeres\nbajo los siete candados;\nno les dan ni pa frijoles,\npero a cada rato palos.",105,2,-1,123,"Los celotes",9,6,"ao",-1,0,-1,0,282,282,"4426","",0,"","","",1,0,0,[],""],["frenk_t2-n4427",6,"¿De qué le sirve al celoso\nel andarse desvelando?\nCuando se va a su trabajo\n¿a quién dejará cuidando?",108,2,8,123,"Estrofa suelta",0,4,"ao",-1,0,-1,0,283,283,"4427","",0,"","","",2,0,0,[],""],["frenk_t2-n4428",6,"¿De qué le sirve al celoso\nvivir en cautivo pleito\npor un celo cauteloso,\ny sin saber si será cierto?",108,2,8,123,"Estrofa suelta",0,4,"eo",-1,0,-1,0,283,283,"4428","",0,"","","",2,0,0,[],""],["frenk_t2-n4429",6,"Soy valiente como el oso\ny noble de corazón.\n¿De qué le sirve al celoso\ntener tanta precaución,\nsi el venado, con ser listo,\ncayó en las uñas del león?",114,2,17,123,"Eres alta y delgadita",9,6,"o",31,0,-1,0,283,283,"4429","",0,"","","",1,0,0,[],""],["frenk_t2-n4430",6,"La mujer no está contenta\ncon su marido celoso;\nporque tanto la atormenta,\nen su vida ya no hay gozo:\nsu corazón se impacienta.",112,2,6,123,"Estrofa suelta",7,5,"ea",229,0,-1,0,283,283,"4430","",0,"","","",1,0,0,[],""],["frenk_t2-n4431",6,"Toda la mujer que vean\npachona y encamorrada\nes porque está celosa:\nno le consuela nada.",119,2,12,123,"Celosa",0,4,"aa",49,0,-1,0,283,283,"4431","",0,"","","",1,0,0,[],""],["frenk_t2-n4432",6,"Mira una nube encumbrada\ncómo se la lleva el viento;\nasí es la mujer casada\ncuando tiene un sentimiento,\nque no la divierte nada,\nni tiene horas de contento.",106,2,4,123,"El buscapiés; El pájaro carpintero",9,6,"eo",94,0,-1,0,283,283,"4432","",0,"","","",1,0,0,[],""],["frenk_t2-n4433",6,"Las nubes van por el cielo,\nlos pescados por el agua,\nel oro está bajo el suelo,\ny el amor en las enaguas.",107,2,11,123,"La calandria",0,4,"aa",-1,0,-1,0,283,283,"4433","",0,"","","",1,0,0,[],""],["frenk_t2-n4434",6,"Las mujeres son flores (cielito lindo)\nque Dios cultiva,\ny el hombre es un árbol—que les da som-\ntoda la vida. [bra\nSon florecitas:\nsin la sombra del árbol (cielito lindo)\nviven marchitas.",106,2,4,123,"Cielito lindo",4,7,"ia",258,0,-1,0,283,283,"4434","",0,"","","",1,0,0,[],""],["frenk_t2-n4436",6,"Ya estarán contentas\ntodas las mujeres,\ndando rienda suelta\npara sus quereres.",105,2,-1,123,"La media bamba",0,4,"ee",55,0,-1,0,284,284,"4436","",0,"","","",1,0,0,[],""],["frenk_t2-n4437",6,"Toda mujer costeña\ncuando dice querer quiere:\nes una cosa tan cierta\ncomo que Dios nunca muere.",108,2,8,123,"Estrofa suelta, Al pasar por los laureles",0,4,"ee",115,0,-1,0,284,284,"4437","",0,"","","",1,0,0,[],""],["frenk_t2-n4438",6,"Yo vide una flor morada,\nparecida a la violeta.\nLa mujer enamorada\nno tiene la vista quieta,\nmayormente si es casada:\nla vergüenza la sujeta.",113,2,2,123,"La Rosita",9,6,"ea",200,0,-1,0,284,284,"4438","",0,"","","",1,0,0,[],""],["frenk_t2-n4439",6,"La mujer que tiene amor\nse conoce en el mirar;\nsi no la dejan gozar,\nmorir quisiera mejor.",113,2,2,123,"La huazanga",11,4,"o",72,0,-1,0,284,284,"4439","",0,"","","",1,0,0,[],""],["frenk_t2-n4440",6,"Las muchachas con amor\nse les quita lo cobarde;\nporque dicen que no hay dolor,\nvan y le dicen a la madre:\n“Acuérdese del amor\nque usted le tenía a mi padre.”",105,2,-1,123,"La Malagueña",9,6,"ae",166,0,-1,0,284,284,"4440","",0,"","","",1,0,0,[],""],["frenk_t2-n4441",6,"En los rayos del sol muere\nla mujer comprometida;\nse va con el que ella quiere,\naunque le cueste la vida.",108,2,8,123,"Estrofa suelta",1,4,"ia",37,0,-1,0,284,284,"4441","",0,"","","",1,0,0,[],""],["frenk_t2-n4442",6,"Las rosas y los claveles\nsi no los cortan, se caen;\nlo mismo que las mujeres:\nsi no las casan, se van\ncon el hombre que ellas quieren.",112,2,6,123,"La Rosita",7,5,"ee",-1,0,-1,0,284,284,"4442","",0,"","","",4,0,0,[],""],["frenk_t2-n4443",6,"La mujer es muy liviana\ny de origen cariñosa;\nhablando a tarde y mañana,\naunque peque de juiciosa,\nviene a ver al que la llama.",112,2,6,123,"Estrofa suelta",7,5,"aa",-1,0,-1,0,284,284,"4443","",0,"","","",1,0,0,[],""],["frenk_t2-n4444",6,"Cuando la mujer ansia\ncorresponderle al varón,\nsólita se desespera;\ncomo en la agua el tiburón,\nsólo busca la escollera.",111,2,1,123,"Estrofa suelta",7,5,"ea",44,0,-1,0,285,285,"4444","",0,"","","",1,0,0,[],""],["frenk_t2-n4445",6,"En el rincón de una piedra\nanidan las chuparrosas.\nLa mujer cuando es pequeña\nno sabe lo que le pasa;\ncuando le hacen una seña\nsu corazón le retoza.",113,2,2,123,"La Cecilia",9,6,"oa",-1,0,-1,0,285,285,"4445","",0,"","","",1,0,0,[],""],["frenk_t2-n4446",6,"La mujer que es cariñosa\nsatisface al corazón;\ncuando resulta celosa\nes una prueba y razón\nde su alma tan candorosa.",112,2,6,123,"Estrofa suelta",7,5,"oa",63,0,-1,0,285,285,"4446","",0,"","","",1,0,0,[],""],["frenk_t2-n4447",6,"En la mujer la pasión\ndesenfrenada es ardiente;\nal tocarle el corazón\ntiene que inclinar su frente:\nde amor, no de humillación.",112,2,6,123,"Estrofa suelta",7,5,"o",31,0,-1,0,285,285,"4447","",0,"","","",1,0,0,[],""],["frenk_t2-n4448",6,"La mujer con intención\nsiempre niega su cariño;\npero llega la ocasión,\nmuchas veces hasta a un niño\nella da su corazón.",105,2,-1,123,"La huazanga",7,5,"o",31,0,-1,0,285,285,"4448","",0,"","","",1,0,0,[],""],["frenk_t2-n4449",6,"La mujer es como el niño,\nque se enoja y tira el pan,\ny haciéndole un cariñito,\nlo recoge y pide más.",105,2,-1,123,"Estrofa suelta",0,4,"a",-1,0,-1,0,285,285,"4449","",0,"","","",2,0,0,[],""],["frenk_t2-n4450",6,"La mujer enojada\ny es como el niño:\nhaciéndole un halago,\nvuelve al cariño.",108,2,8,123,"La bamba",6,4,"io",176,0,-1,0,285,285,"4450","",0,"","","",1,0,0,[],""],["frenk_t2-n4451",6,"La mujer que es de vergüenza\nno paga con tiranía;\naunque le quiten la trenza,\nfirme como el primer día.",108,2,8,123,"Estrofa suelta",1,4,"ia",0,0,-1,0,285,285,"4451","",0,"","","",1,0,0,[],""],["frenk_t2-n4452",6,"Toro, tú te pareces\na las mujeres,\nque cuando están enojadas (torito)\na nadien quieren;\nparecen mosquita muerta (torito)\ny traen la suerte (siç).",105,2,-1,123,"El toro relajo",9,6,"i",-1,0,-1,0,285,285,"4452","",0,"","","",1,0,0,[],""],["frenk_t2-n4454a",6,"La mujer es una pera\nallá subida en la altura:\nya revienta de madura\ny de repente se cae,\ny el que menos lo espera\ndisfruta de su hermosura.",106,2,4,123,"Estrofa suelta",9,6,"ua",17,0,-1,0,286,286,"4454a","",0,"","","",2,0,0,[],""],["frenk_t2-n4458",6,"Nunca me digas adiós\ncon esa mirada triste;\nlos amores que se quieren\nnunca deben despedirse.",108,2,8,124,"Estrofa suelta",0,4,"ie",-1,0,-1,0,287,287,"4458","",0,"","","",5,0,0,[],""],["frenk_t2-n4459",6,"Si te vas a enamorar,\nla propiedad siempre cuida,\nque el amor se debe sembrar\ncomo aconseja la vida,\ny tendrá que florecer\ncomo floreció mi amor.",113,2,2,124,"Estrofa suelta",9,6,"o",-1,0,-1,0,287,287,"4459","",0,"","","",1,0,0,[],""],["frenk_t2-n4460a",6,"Ya me voy a retirar\npara el puerto de Tampico.\nPara eso de enamorar\nse necesita un carrizo,\ny hay que poderlo alcanzar.",105,2,-1,124,"El gusto",7,5,"a",21,0,-1,0,287,287,"4460a","",0,"","","",12,0,0,[],""],["frenk_t2-n4460b",6,"Ya me voy a retirar\npara el puerto de Tampico.\nPara eso de enamorar\nse necesita un carrizo;\nhay que poderlo alcanzar\npor esfuerzo de uno mismo.",105,2,-1,124,"El gusto",9,6,"io",-1,0,-1,0,287,287,"4460b","",0,"","","",12,0,0,[],""],["frenk_t2-n4461",6,"Estaba un perico real\ndándofle] consejo a un loro,\ny decía en su relatar\nque en este mundo hay de todo,\nque hasta para enamorar\nbusca el pobre su acomodo.",108,2,8,124,"El pájaro cú; La guacamaya",9,6,"oo",261,0,-1,0,288,288,"4461","",0,"","","",1,0,0,[],""],["frenk_t2-n4462",6,"Para ser enamorado\nse necesita valor,\ny ser un poco porfiado\ny no ser tan hablador.",113,2,2,124,"Estrofa suelta",1,4,"o",72,0,-1,0,288,288,"4462","",0,"","","",1,0,0,[],""],["frenk_t2-n4463",6,"Hay que ser hasta imprudente,\nnecio, tenaz y constante;\nhablándole dulcemente,\ncomo todo fiel amante,\ntiene que inclinar su frente.",112,2,6,124,"Estrofa suelta",7,5,"ee",15,0,-1,0,288,288,"4463","",0,"","","",1,0,0,[],""],["frenk_t2-n4464",6,"Siempre el hombre a la mujer\ndebe amarla con ternura,\nque es dueño de su hermosura,\nde donde nace el placer.",112,2,6,124,"Estrofa suelta",11,4,"e",20,0,-1,0,288,288,"4464","",0,"","","",1,0,0,[],""],["frenk_t2-n4465",6,"La mujer es un timón,\nsabiéndola dirigir;\nes una bella lección\nque el hombre ha de preferir\nla que tenga educación.",106,2,4,124,"Estrofa suelta",7,5,"o",31,0,-1,0,288,288,"4465","",0,"","","",1,0,0,[],""],["frenk_t2-n4466",6,"¡Ay, Soledad, Soledad’.\nSoledad, desde mi cuna;\nmi madre me dijo a solas\nque amara no más a una.",108,2,8,124,"La Petenera*",0,4,"ua",56,0,-1,0,288,288,"4466","",0,"","","",18,0,0,[],""],["frenk_t2-n4467",6,"Una de dos ha de ser,\ny de las dos ha de ser una:\nquerer a la más bonita\no de las dos a ninguna.",108,2,8,124,"Estrofa suelta",0,4,"ua",56,0,-1,0,288,288,"4467","",0,"","","",1,0,0,[],""],["frenk_t2-n4468",6,"Con A ha de comenzar,\ncon O ha de terminar;\nArmando se ha de llamar\nal muchacho que has de amar.",129,2,9,124,"Estrofa suelta",0,4,"a",21,0,-1,0,288,288,"4468","",0,"","","",1,0,0,[],""],["frenk_t2-n4469",6,"Toda mujer bonita\ndebe saber:\nha de tener dos novios (cielito lindo),\npara escoger;\nsi es entendida,\nuna vela se apaga, — pero le queda\nla otra encendida.",113,2,2,124,"Cielito lindo",4,7,"ia",37,0,-1,0,289,289,"4469","",0,"","","",1,0,0,[],""],["frenk_t2-n4470",6,"Por la playa de la mar\nyo me encontré un pescador,\ny me dijo al saludar:\n“La joven que tiene amor\ntemprano se ha de bañar,\naunque no tenga calor.”",106,2,4,124,"El pájaro carpintero",9,6,"o",72,0,-1,0,289,289,"4470","",0,"","","",1,0,0,[],""],["frenk_t2-n4471",6,"Estaba la yerbabuena\nenredada con la zarza;\nvale más ser fea y firme,\ny no ser bonita y falsa.",122,2,13,124,"Estrofa suelta",0,4,"aa",-1,0,-1,0,289,289,"4471","",0,"","","",1,0,0,[],""],["frenk_t2-n4472",6,"Dicen que estás enferma (cielito lindo)\ny del corazón;\nla enfermedad que tienes (cielito lindo)\ny es de pasión.\nMi enamorada,\ntú encontrarás alivio (chiquita)\nsólo casada.",106,2,4,124,"Cielito Undo",4,7,"aa",49,0,-1,0,289,289,"4472","",0,"","","",1,0,0,[],""],["frenk_t2-n4473",6,"Casarse es tomar buen rumbo\ncon una mujer honrada,\nporque es una ley sagrada\ndesde que Dios hizo el mundo.",106,2,4,124,"Estrofa suelta",5,4,"uo",-1,0,-1,0,289,289,"4473","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4474",6,"Primo hermano, si te casas,\nbusca una mujer bonita,\nque tenga caderas grandes,\nque no sea resbaladita.",108,2,8,124,"Estrofa suelta",0,4,"ia",50,0,-1,0,289,289,"4474","",0,"","","",1,0,0,[],""],["frenk_t2-n4476",6,"Ariles y más ariles,\ny ariles del toma y ten;\nmira, no le pagues mal\na quien te ha querido bien.",106,2,4,124,"El Balajú",3,4,"e",242,0,-1,0,289,289,"4476","",0,"","","",24,0,0,[],""],["frenk_t2-n4478",6,"Cuando pases por el puente\nno bebas agua del río,\nni dejes amor pendiente\ncomo tú dejaste el mío.",124,2,16,124,"Bonito San Juan del Río; El frijolito; El indio mexicano; El león; El Quelite; Yo soy aquel oaxaqueño; Estrofa",1,4,"io",3,0,-1,0,290,290,"4478","",0,"","","",2,0,0,[],""],["frenk_t2-n4479",6,"Camino de San Jacinto,\ncamino de San Joaquín,\nno dejes amor pendiente,\ncomo me dejaste a mí.",105,2,-1,124,"El Quelite",3,4,"i",-1,0,-1,0,290,290,"4479","",0,"","","",1,0,0,[],""],["frenk_t2-n4480",6,"Camino de San Ignacio,\ncamino de San Javier,\nno dejes amor pendiente,\ncomo el que dejaste ayer.",119,2,12,124,"El Quelite",0,4,"e",20,0,-1,0,290,290,"4480","",0,"","","",1,0,0,[],""],["frenk_t2-n4482",6,"Cuídense, maripositas,\nno me pierdan la cabeza,\nporque si dan un mal paso,\nse las lleva la tristeza.",105,2,-1,124,"Uy, uy, mariposa",0,4,"ea",108,0,-1,0,290,290,"4482","",0,"","","",1,0,0,[],""],["frenk_t2-n4483",6,"Cuida bien de tu pureza,\nesa joya de valor\ny a nadie des esa flor:\nmira que es una riqueza.",105,2,-1,124,"Estrofa suelta",11,4,"ea",108,0,-1,0,290,290,"4483","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4484",6,"No hagas común el rubor\nde tu rostro soberano,\npues se marchita la flor\nsi pasa de mano en mano.",108,2,8,124,"Estrofa suelta",1,4,"ao",81,0,-1,0,290,290,"4484","",0,"","","",1,0,0,[],""],["frenk_t2-n4487",6,"El alacrán en el viento\ndesparrama su ponzoña;\ncon cuidado, muchachitas,\nque la vida no retoña.",115,2,3,124,"El gusano; El mosquito; Rafaelita",0,4,"oa",566,0,-1,0,291,291,"4487","",0,"","","",1,0,0,[],""],["frenk_t2-n4488",6,"La mujer para adorarse\ndebe tener un deseo,\nporque si deja besarse,\nse precipita el deseo,\ny comienza a marchitarse.",112,2,6,124,"Estrofa suelta",7,5,"ae",250,0,-1,0,291,291,"4488","",0,"","","",1,0,0,[],""],["frenk_t2-n4489",6,"¡Ay, Soledad, Soledad!,\nSoledad, para la estancia;\nque la flor que se marchita\npierde toda su fragancia.",109,2,7,124,"La Petenera",0,4,"aa",340,0,-1,0,291,291,"4489","",0,"","","",18,0,0,[],""],["frenk_t2-n4490",6,"La flor cuando se abre\npierde su mérito y valor;\ncuando está en capullo\nduerme, encerrado, un suave olor,\nque al abrirse se disuelve.",112,2,6,124,"Estrofa suelta",7,5,"ee",-1,0,-1,0,291,291,"4490","",0,"","","",1,0,0,[],""],["frenk_t2-n4491",6,"Cuídate de los uñazos\ndel terrible gavilán:\nsus uñas tienen veneno,\ny no se podrán curar.",105,2,-1,124,"Botón de rosa",0,4,"a",-1,0,-1,0,291,291,"4491","",0,"","","",1,0,0,[],""],["frenk_t2-n4493",6,"No vayas a la tienda\ndel dios Cupido,\nque por cualquier cosa\nlleva un sentido;\nno entres en ella,\nque se te irán los ojos\ntras de sus prendas.",105,2,-1,124,"Estrofa suelta",4,7,"ea",-1,0,-1,0,292,292,"4493","",0,"","","",3,0,0,[],""],["frenk_t2-n4494",6,"No des tu amor al hombre\nque va de paso,\nque el que fuese viajero\nsigue su marcha.",105,2,-1,124,"Estrofa suelta",6,4,"aa",-1,0,-1,0,292,292,"4494","",0,"","","",1,0,0,[],""],["frenk_t2-n4495",6,"Y eres como blanco nardo,\nencamada maravilla;\nsólo una cosa te encargo:\nque las flores en el árbol\nno duran toda la vida.",106,2,4,124,"El pájaro carpintero",7,5,"ia",-1,0,-1,0,292,292,"4495","",0,"","","",1,0,0,[],""],["frenk_t2-n4496",6,"La mujer no debe ser\ncoqueta ni pretenciosa,\nporque debe comprender\nque el hombre siempre la goza,\ny aunque no lo pueda ver.",107,2,11,124,"El gusto; La huazanga; La leva",7,5,"e",20,0,-1,0,292,292,"4496","",0,"","","",1,0,0,[],""],["frenk_t2-n4497",6,"Madúrate, tuna blanca,\nque áhi viene ya la Cardona:\nno te vayas a quedar\ncomo el que chifló en la loma.",110,2,10,124,"El calero",0,4,"oa",-1,0,-1,0,292,292,"4497","",0,"","","",1,0,0,[],""],["frenk_t2-n4498",6,"Eres anillito de oro\nde la joyería de España;\nno te vayas al color,\nque también la vista engaña:\nno te vayas a quedar\ncomo la mazorca en caña.",105,2,-1,124,"El pájaro carpintero; El venadito; Estrofa suelta",9,6,"aa",213,0,-1,0,292,292,"4498","",0,"","","",1,0,0,[],""],["frenk_t2-n4499",6,"Eres clavel encendido\nde los jardines de España;\nno te fijes en vestido,\nque también la vista engaña,\ny me eches en olvido\npor coger otra maña.",108,2,8,124,"Zapateado",9,6,"aa",213,0,-1,0,293,293,"4499","",0,"","","",1,0,0,[],""],["frenk_t2-n4500",6,"Mi pobreza motivó\nque hable de mí tu hermosura;\nno hables de aquel que te amó,\naunque estés en la gran altura,\ny digas: “De esta agua, no”,\nporque la sed siempre apura.",113,2,2,124,"Estrofa suelta",9,6,"ua",17,0,-1,0,293,293,"4500","",0,"","","",1,0,0,[],""],["frenk_t2-n4501",6,"Hoy el cielo ya tronó,\nlas aguas quieren llegar;\nno digas “De esa agua, no”,\nporque en ella te has de ahogar,\nsi el interés te llevó.",113,2,2,124,"Estrofa suelta",7,5,"o",2,0,-1,0,293,293,"4501","",0,"","","",1,0,0,[],""],["frenk_t2-n4502",6,"—Mira qué nubes tan blancas.\n—No voltees tanto pa arriba,\nporque cuando veas pa abajo\nes porque ya estás perdida.",105,2,-1,124,"Botón de rosa",0,4,"ia",-1,0,-1,0,293,293,"4502","",0,"","","",1,0,0,[],""],["frenk_t2-n4503",6,"Toda la mujer que note\nque un hombre la está queriendo\ndebe de seguirle al trote;\nno por andar presumiendo\npierde la caña y elote.",111,2,1,124,"Estrofa suelta",7,5,"oe",292,0,-1,0,293,293,"4503","",0,"","","",1,0,0,[],""],["frenk_t2-n4504",6,"Nunca querrás ver celoso\nal que por tu amor se muere,\nque hasta la paloma es brava\nsi en el corazón se hiere.",105,2,-1,124,"Rosa María",0,4,"ee",115,0,-1,0,293,293,"4504","",0,"","","",1,0,0,[],""],["frenk_t2-n4505",6,"Por las orillas del mar\noí que dijo un Cupido:\n“La mujer que sabe amar\ny quiera bien al marido\nle debe de perdonar\nlas faltas que ha cometido”",106,2,4,124,"El pájaro carpintero; El Cupido; Estrofa suelta",9,6,"io",101,0,-1,0,293,293,"4505","",0,"","","",5,0,0,[],""],["frenk_t2-n4506",6,"Cupido, pintando flores,\npintó un hermoso clavel;\ncomo le faltó papel,\nno lo pintó de colores,\npero lo pintó de amores,\nque lo mismo viene a ser.",112,2,6,123,"Estrofa suelta",9,6,"e",-1,0,-1,0,297,297,"4506","",0,"","","",1,0,0,[],""],["frenk_t2-n4507",6,"Nace la perla en el mar,\nen los jardines la flor,\nentre riscos el diamante,\nentre amantes el amor.",105,2,-1,123,"Estrofa suelta",0,4,"o",72,0,-1,0,297,297,"4507","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["frenk_t2-n4508",6,"¡Ay, flor de changunga!,\n¡ay, qué naranja de dulce!,\n¡ay, qué plátano morado!,\n¡ay, que lo que es amor!.",115,2,3,123,"Flor de changunga",5,4,"o",-1,0,-1,0,297,297,"4508","",0,"","","",1,0,0,[],""],["frenk_t2-n4509",6,"Cantaba el mozo y decía;\n“El querer es cosa buena,\nporque dobla la alegría\ny parte entre dos la pena.”",108,2,8,123,"Estrofa suelta",1,4,"ea",59,0,-1,0,297,297,"4509","",0,"","","",1,0,0,[],""],["frenk_t2-n4510",6,"Me dicen que “El fandanguito”\nes bonito entre los sones;\nlo digo recio y quedito,\nalegrando corazones:\nel amor es muy bonito.",112,2,6,123,"El fandanguito",7,5,"io",119,0,-1,0,297,297,"4510","",0,"","","",1,0,0,[],""],["frenk_t2-n4511",6,"¡Qué bonito es el amor\ncuando empieza a penetrar!\nComo el rocío a la flor,\ncomo la luz en el mar,\nes una gloria, un primor.",112,2,6,123,"Estrofa suelta",7,5,"o",72,0,-1,0,297,297,"4511","",0,"","","",1,0,0,[],""],["frenk_t2-n4512",6,"Una naranja sazona\ny otra está sazonando;\n¡qué bonito es el amor\ncuando se está comenzando!",133,2,23,123,"Ya está la sala regada",0,4,"ao",33,0,-1,0,297,297,"4512","",0,"","","",1,0,0,[],""],["frenk_t2-n4513",6,"Cuando comienza el amor\nse siente el alma dichosa:\ntodo se ve de color,\ntodo está color de rosa\nel cielo, la tierra, el sol.",112,2,6,123,"Estrofa suelta",7,5,"o",-1,0,-1,0,297,297,"4513","",0,"","","",1,0,0,[],""],["frenk_t2-n4515",6,"Al conseguirse el amor\nmuere el alma de contento;\ntodo parece un primor:\nla maleza, el firmamento,\ntodo lo que hace el Creador.",112,2,6,123,"Estrofa suelta",7,5,"o",72,0,-1,0,298,298,"4515","",0,"","","",1,0,0,[],""],["frenk_t2-n4516",6,"¡Con cuánto gozo respira\nel pecho ya apasionado!\nEl cantor abre su lira,\nle da gracias al Increado\nal conseguir lo que aspira.",112,2,6,123,"Estrofa suelta",7,5,"ia",372,0,-1,0,298,298,"4516","",0,"","","",1,0,0,[],""],["frenk_t2-n4517",6,"¡Cómo goza el corazón\nquerido por la elegida!\nTodo es gran satisfacción\nal ver que su consentida\ncorresponde a su pasión.",112,2,6,123,"Estrofa suelta",7,5,"o",31,0,-1,0,298,298,"4517","",0,"","","",1,0,0,[],""],["frenk_t2-n4518",6,"El corazón se contenta\nal verse correspondido;\ntoda su vida se alienta\nviendo que es el consentido\nde la mujer predilecta.",112,2,6,123,"Estrofa suelta",7,5,"ea",-1,0,-1,0,298,298,"4518","",0,"","","",1,0,0,[],""],["frenk_t2-n4520",6,"¡Qué bella satisfacción\nsiente el corazón que adora!\nAl ver la contestación,\ncon más pasión se enamora\nde la que fue su elección.",112,2,6,123,"Estrofa suelta",7,5,"o",31,0,-1,0,298,298,"4520","",0,"","","",1,0,0,[],""],["frenk_t2-n4521",6,"¡Y uy, que la caña verde!,\n¡Y uy, que la caña brava!\n¡Qué bonito es el querer\ncuando el amor no se acaba!",117,2,5,123,"La caña brava",0,4,"aa",28,0,-1,0,298,298,"4521","",0,"","","",1,0,0,[],""],["frenk_t2-n4522",6,"¡Viva el sol, viva la luna,\nviva quien sabe querer!\n¡Viva quien vive sufriendo\npor culpa de una mujer!",105,2,-1,123,"¡Viva quien sabe querer!",0,4,"e",20,0,-1,0,298,298,"4522","",0,"","","",6,0,0,[],""],["frenk_t2-n4523",6,"Salomón, siendo tan sabio,\nque por su saber fue rey,\nme dijo una vez sentado\nen su silla de carey:\n“Para el hombre enamorado\nno lo castiga la ley.”",108,2,8,123,"Estrofa suelta",9,6,"e",133,0,-1,0,298,298,"4523","",0,"","","",2,0,0,[],""],["frenk_t2-n4524",6,"El amar a una mujer\nmuy sabido es que no es delito;\namarla es el deber\ncon un amor infinito\ny cantarle con amor\nel huapango “El bejuquito”.",113,2,2,123,"Estrofa suelta",9,6,"io",119,0,-1,0,299,299,"4524","",0,"","","",1,0,0,[],""],["frenk_t2-n4525",6,"De ladrón traigo la fama,\npero no te descrédito:\nel que se roba una dama\nno tiene ningún delito,\nantes la gloria se gana,\ncomo el mejor angelito.",109,2,7,123,"La Malagueña",9,6,"io",119,0,-1,0,299,299,"4525","",0,"","","",2,0,0,[],""],["frenk_t2-n4527",6,"Bonito braman los toros\ndebajo de los mogotes;\n¡ay, qué bonito es tener\nun amor grandototote!",105,2,-1,123,"Estrofa suelta",0,4,"oe",-1,0,-1,0,299,299,"4527","",0,"","","",1,0,0,[],""],["frenk_t2-n4528",6,"¡Ay, ay, ay, qué bonito es amar\na una mujer que no tenga dueño!\n¡Ay ay ay, qué bonito es amar\na la mujer que sepa lo que es amor!",105,2,-1,123,"¡Ay, qué bonito es amar!",3,4,"o",-1,0,-1,0,299,299,"4528","",0,"","","",1,0,0,[],""],["frenk_t2-n4529",6,"Al tufo de la sardina\nanda un gavilán que vuela;\nla que no sabe de amores\nno sabe de cosa buena.",108,2,8,123,"Estrofa suelta",0,4,"ea",-1,0,-1,0,299,299,"4529","",0,"","","",1,0,0,[],""],["frenk_t2-n4530",6,"Cupido se halla en la sierra\nen traje de cazador,\ndiciendo: “Que muera, muera\nla que no sepa de amor!”",112,2,6,123,"El pelado",0,4,"o",72,0,-1,0,299,299,"4530","",0,"","","",1,0,0,[],""],["frenk_t2-n4531",6,"Yo conozco a gente pobre\ny también a gente rica\nque por no tener amores\nno pueden gozar la vida.",105,2,-1,123,"El fandanguero",0,4,"ia",-1,0,-1,0,299,299,"4531","",0,"","","",1,0,0,[],""],["frenk_t2-n4533a",6,"El amor de las mujeres\nes como lumbre en pajar:\nel trabajo es que se prenda,\nque no se llega a apagar.",105,2,-1,123,"Estrofa suelta",0,4,"a",21,0,-1,0,300,300,"4533a","",0,"","","",18,0,0,[],""],["frenk_t2-n4534",6,"Esto digo, y no sé leer,\nlo digo con amor suave:\nno hay amor que empiece bien\nque con disgusto acabe.",108,2,8,123,"Estrofa suelta",3,4,"ae",131,0,-1,0,300,300,"4534","",0,"","","",1,0,0,[],""],["frenk_t2-n4536",6,"Quien bien quiere nunca olvida\ny si olvida no aborrece;\nmirando lo que ha querido,\nvuelve a querer si se ofrece.",108,2,8,123,"Estrofa suelta",0,4,"ee",64,0,-1,0,300,300,"4536","",0,"","","",2,0,0,[],""],["frenk_t2-n4537",6,"El miércoles de ceniza\nse despiden los amantes\ny el sábado de gloria\nvuelven a lo que eran antes.",107,2,11,123,"Estrofa suelta, Baile de la muñeca",0,4,"ae",262,0,-1,0,300,300,"4537","",0,"","","",2,0,0,[],""],["frenk_t2-n4538",6,"Estoy algo enronquecido\ny malo de la garganta,\npero vivo convencido\nque, estando buena la planta,\ny aunque no le haya llovido,\ncon el sereno levanta.",105,2,-1,123,"El siquisirí",9,6,"aa",148,0,-1,0,300,300,"4538","",0,"","","",1,0,0,[],""],["frenk_t2-n4539",6,"Áhi te va la despedida,\nrecíbela si la entiendes:\nel carbón que ha sido brasa\ncon poco fuego se enciende.",105,2,-1,123,"Las torcazas; La Petenera",0,4,"ee",-1,0,-1,0,301,301,"4539","",0,"","","",6,0,0,[],""],["frenk_t2-n4540",6,"Dicen que la ceniza\nconserva lumbre:\ntu amor, que está distante,\nserá más firme.",105,2,-1,123,"Estrofa suelta",6,4,"ie",-1,0,-1,0,301,301,"4540","",0,"","","",1,0,0,[],""],["frenk_t2-n4541",6,"Si fuere el amor firme,\nla ausencia es lazo\nque ata a los dos amantes\nhasta la muerte.",105,2,-1,123,"Estrofa suelta",6,4,"ee",-1,0,-1,0,301,301,"4541","",0,"","","",1,0,0,[],""],["frenk_t2-n4542",6,"De todos los colores\nme gusta el verde,\nporque las esperanzas\nnunca se pierden.",106,2,4,123,"El pájaro cú; Dicen que no se siente la despedida; Estrofa suelta",6,4,"ee",-1,0,-1,0,301,301,"4542","",0,"","","",5,0,0,[],""],["frenk_t2-n4543",6,"A la mar fui por naranjas,\ncosa que la mar no tiene;\nel que vive de esperanza\nla esperanza lo mantiene.",107,2,11,123,"La Sanmarqueña; María del Carmen; La calandria; Estrofa suelta",0,4,"ee",70,0,-1,0,301,301,"4543","",0,"","","",7,0,0,[],""],["frenk_t2-n4544",6,"Corazón, no estés triste (bien de mi vida),\nten esperanza,\nque en el pozo más hondo\nla agua se alcanza.",105,2,-1,123,"El pájaro cú; El siquisirí",3,4,"aa",163,0,-1,0,301,301,"4544","",0,"","","",1,0,0,[],""],["frenk_t2-n4545",6,"Y vuela, revuela y vuela,\npero vuela sin tardanza;\nmientras que la vida dura\nlugar tiene la esperanza.",106,2,4,123,"La guacamaya",0,4,"aa",163,0,-1,0,301,301,"4545","",0,"","","",2,0,0,[],""],["frenk_t2-n4547",6,"Cantaba de mañanita\nel pájaro ruiseñor,\ny le respondió el Criador,\ncon una voz muy bonita:\n“Y un sentimiento de amor\ncon otro nuevo se quita.”",106,2,4,123,"El pájaro cú",9,6,"ia",50,0,-1,0,302,302,"4547","",0,"","","",1,0,0,[],""],["frenk_t2-n4548",6,"¡Ay de mí, Llorona!,\nLlorona de azul celeste,\nel que tiene nuevo amor (¡ay, Llorona!)\nnuevo mundo le parece.",108,2,8,123,"La Llorona",3,4,"ee",-1,0,-1,0,302,302,"4548","",0,"","","",35,0,0,[],""],["frenk_t2-n4549",6,"¿Para qué son cerrojos\nsi tienen llave?\nSi una puerta se cierra,\ndoscientas se abren.",108,2,8,123,"El pájaro cú",6,4,"ae",-1,0,-1,0,302,302,"4549","",0,"","","",5,0,0,[],""],["frenk_t2-n4550",6,"¡Ay de mí, Llorona!,\nLlorona entre dos caminos;\n¡ay, qué bonito es un beso (Llorona)\nentre dos amantes finos!",108,2,8,123,"La Llorona",3,4,"io",206,0,-1,0,302,302,"4550","",0,"","","",35,0,0,[],""],["frenk_t2-n4551",6,"Al pasar por una huerta\ncorté la ruda y romero.\nEl que no olvida su amor\nno olvida ningún dinero,\ny dándose unos besitos,\nmayormente si el primero.",105,2,-1,123,"Estrofa suelta",9,6,"eo",38,0,-1,0,302,302,"4551","",0,"","","",4,0,0,[],""],["frenk_t2-n4552",6,"Yo soy el mejor doctor,\nque si al curar algo alivia,\nya no vale el alcanfor,\nni baños de agua fría:\nel que padece de amor\nsólo con besos se alivia.",113,2,2,123,"La huazanga; El querreque",9,6,"ia",-1,0,-1,0,302,302,"4552","",0,"","","",1,0,0,[],""],["frenk_t2-n4554",6,"¡Qué bueno es el pan y el queso\ndel que comen en mi rancho!\nPero es más sabroso un beso\ndebajo de un sombrero ancho.",110,2,10,123,"Estrofa suelta, El sombrero ancho",1,4,"ao",380,0,-1,0,303,303,"4554","",0,"","","",1,0,0,[],""],["frenk_t2-n4555",6,"Y entre niñas y niños (bien de mis ojos)\nhay un jueguito,\nque no son de los buenos,\nque es lo bonito.",105,2,-1,123,"El pájaro cú",3,4,"io",119,0,-1,0,303,303,"4555","",0,"","","",1,0,0,[],""],["frenk_t2-n4556",6,"Cansado de padecer\ny sufrir en buen terreno,\ntarde vine a comprender\nque el amor es un veneno\ny la contra es la mujer.",105,2,-1,123,"Los chiles verdes; La azucena; La le va; El lunarcito",7,5,"e",20,0,-1,0,303,303,"4556","",0,"","","",1,0,0,[],""],["frenk_t2-n4557",6,"Al pasar por un reloj\nyo oí resonar mi nombre,\ny me respondió una voz:\n“No te asustes, no te asombres,\nque la mujer la hizo Dios\npara regalo del hombre.”",108,2,8,123,"La morena; El siquisirf’",9,6,"oe",-1,0,-1,0,303,303,"4557","",0,"","","",1,0,0,[],""],["frenk_t2-n4558",6,"Yo me atrevo a comprender\nque lo más lindo en lo creado\nson las hermosas mujeres,\nque para nosotros Dios\nNuestro Señor nos ha dado.",113,2,2,123,"Estrofa suelta",7,5,"ao",14,0,-1,0,303,303,"4558","",0,"","","",1,0,0,[],""],["frenk_t2-n4559",6,"Para endulzar los dolores\nque amargan nuestra existencia\nprodigó la Providencia\nmujeres, aves y flores.",105,2,-1,123,"Estrofa suelta",11,4,"oe",5,0,-1,0,303,303,"4559","",0,"","","",1,0,0,[],""],["frenk_t2-n4560",6,"Las flores y las mujeres\nson cosas que Dios formó:\nunas nos hieren con sus espinas,\notras perfuman el corazón.",105,2,-1,123,"El Chuparrosa",3,4,"o",-1,0,-1,0,303,303,"4560","",0,"","","",1,0,0,[],""],["frenk_t2-n4561",6,"La mujer desde que nace\nnace con mucha hermosura:\n¡Cómo Diosito las hace,\nque les da tanta figura,\nque hasta chinitos les hace!",113,2,2,123,"El huerfanito",7,5,"ae",-1,0,-1,0,303,303,"4561","",0,"","","",1,0,0,[],""],["frenk_t2-n4562",6,"Y en el aire encantador\nse lamentaba una estrella;\ndicen que hablaba el Creador:\nque la mujer es más bella\nque el aroma de una ñor.",106,2,4,123,"Estrofa suelta, La huazanga",7,5,"o",72,0,-1,0,304,304,"4562","",0,"","","",1,0,0,[],""],["frenk_t2-n4563",6,"La mujer que es adorada\nen verdad, de corazón,\nla vemos como sagrada,\nde completa perfección:\nno tiene peros ni nada.",112,2,6,123,"Estrofa suelta",7,5,"aa",49,0,-1,0,304,304,"4563","",0,"","","",1,0,0,[],""],["frenk_t2-n4564",6,"La virgen tendió su manto\nen un conjunto de flores\ny dijo con amor santo\nque allá en la tierra de amores\nla mujer es el encanto.",105,2,-1,123,"Estrofa suelta, La leva",7,5,"ao",30,0,-1,0,304,304,"4564","",0,"","","",1,0,0,[],""],["frenk_t2-n4565",6,"Comprendo que no ha de haber\ncosa más linda en lo que hago,\ny me atrevo a sostener\nque en este suelo sagrado\nel encanto es la mujer.",112,2,6,123,"Las flores; La azucena; El gusto; La Malagueña; La Rosita",7,5,"e",20,0,-1,0,304,304,"4565","",0,"","","",1,0,0,[],""],["frenk_t2-n4566",6,"La mujer tiene razón\npara ser la preferida:\nes la única ilusión\nque tenemos en la vida\namarla de corazón.",112,2,6,123,"La azucena",7,5,"o",31,0,-1,0,304,304,"4566","",0,"","","",1,0,0,[],""],["frenk_t2-n4567",6,"Ya dicen que a la mujer\nDios le ha dado bello nombre;\ncon su modo de querer\nenciende los corazones;\náhi no vale ni el saber:\ntodo se vuelve ilusiones.",105,2,-1,123,"Los chiles verdes",9,6,"oe",34,0,-1,0,304,304,"4567","",0,"","","",1,0,0,[],""],["frenk_t2-n4568",6,"El amor de una mujer\nde nuestro querido suelo,\nsi nunca llega a tener\namor, sentimiento y celo,\ntodo puede merecer.",112,2,6,123,"La azucena",7,5,"e",20,0,-1,0,304,304,"4568","",0,"","","",1,0,0,[],""],["frenk_t2-n4569",6,"No hay placer en el planeta\nque iguale a la mujer;\nla mujer juiciosa y quieta\ntodo debe merecer:\nésta es la opinión de Izeta.",112,2,6,123,"Estrofa suelta",7,5,"ea",200,0,-1,0,304,304,"4569","",0,"","","",1,0,0,[],""],["frenk_t2-n4570",6,"Sólo a la mujer amamos\nen la tierra onde vivimos:\npor su tormenta lloramos,\ny cuando a sus pies caímos\ntoda el alma le entregamos.",113,2,2,123,"La azucena",7,5,"ao",116,0,-1,0,305,305,"4570","",0,"","","",1,0,0,[],""],["frenk_t2-n4571",6,"El íntimo parentesco\nque nuestro corazón anima,\nque gustemos con amor\nde la que más se estima.",118,2,27,123,"Baile de la muñeca",0,4,"ia",302,0,-1,0,305,305,"4571","",0,"","","",1,0,0,[],""],["frenk_t2-n4572",6,"De la arena nace el agua\ny del agua, los pescados,\ny de la mujer bonita\nnacen los enamorados.",105,2,-1,123,"De la arena nace el agua; Cómo quieres que una luz; Pajarillo barranqueño; La Sanmarqueña",0,4,"ao",18,0,-1,0,305,305,"4572","",0,"","","",2,0,0,[],""],["frenk_t2-n4573",6,"De la arena nace el agua\ny del agua, el aguardiente,\ny de la mujer traidora\nnacen los hombres valientes.",105,2,-1,123,"De la arena nace el agua; Válgame Dios de los cielos",0,4,"ee",-1,0,-1,0,305,305,"4573","",0,"","","",2,0,0,[],""],["frenk_t2-n4574",6,"Del cielo cayó una palma\nrodeada de campanitas,\npa coronar a las madres\nque tienen hijas bonitas.",105,2,-1,123,"El cubilete; Pregón del ante; La Sanmarqueña; El súchil; Estrofa suelta",0,4,"ia",258,0,-1,0,305,305,"4574","",0,"","","",2,0,0,[],""],["frenk_t2-n4575",6,"Al volar me dijo una tortolita:\n“Quiero brindar con caña\npor todas las madres\nque tienen hijas bonitas.”",113,2,2,123,"Estrofa suelta",3,4,"ia",-1,0,-1,0,305,305,"4575","",0,"","","",1,0,0,[],""],["frenk_t2-n4576",6,"Ya viene la luna hermosa\nrodeada de campanitas.\n¡Qué dichosas son las madres\nque tienen hijas bonitas!\nQue las encomienden a Dios,\ny a mí, a las ánimas benditas.",108,2,8,123,"Estrofa suelta",9,6,"ia",258,0,-1,0,305,305,"4576","",0,"","","",1,0,0,[],""],["frenk_t2-n4577",6,"Las ventanas a la calle\nson peligrosas\npa los papás que tienen\nhijas hermosas.",108,2,8,123,"Negra del alma; La manta",6,4,"oa",61,0,-1,0,306,306,"4577","",0,"","","",2,0,0,[],""],["frenk_t2-n4578",6,"De lo alto cae la nube,\neso sí, no hay que dudar.\nBonitas son las muchachas,\nacabadas de bañar,\nno pintadas ni polveadas:\ncon su color natural.",116,2,15,123,"Eres alta y delgadita",9,6,"a",-1,0,-1,0,306,306,"4578","",0,"","","",1,0,0,[],""],["frenk_t2-n4579",6,"De lo alto se caen las piedras,\nen eso no hay que dudar.\nBonitas son las muchachas,\nsacándolas a pasear:\ncon dinero, no con señas,\n¡ay, qué rechulo es amar!",114,2,17,123,"Eres alta y delgadita",9,6,"a",21,0,-1,0,306,306,"4579","",0,"","","",1,0,0,[],""],["frenk_t2-n4580",6,"La mujer es más hermosa\ncuando se viste de blanco:\nparece una mariposa\nde esas que andan en el campo\nparada sobre una rosa.",111,2,1,123,"La Rosita",7,5,"oa",63,0,-1,0,306,306,"4580","",0,"","","",1,0,0,[],""],["frenk_t2-n4582",6,"A orillas de una laguna\ntriste se quejaba un león,\ny en el quejido decía:\n“¡Ay, muchachas, cómo son!,\ndelgaditas de cintura,\npero todas corazón.”",105,2,-1,123,"El pájaro carpintero; Ahora pregunto, pregunto; Delgadita de cintura; La Malagueña; El venadito; Estrofa suelta",9,6,"o",31,0,-1,0,306,306,"4582","",0,"","","",4,0,0,[],""],["frenk_t2-n4583",6,"Del corazón de una palma\nnacieron las Isabeles,\ndelgaditas de cintura\ny del corazón alegre.",105,2,-1,123,"Las Isabeles; Estrofa suelta",0,4,"ee",-1,0,-1,0,306,306,"4583","",0,"","","",1,0,0,[],""],["frenk_t2-n4584",6,"¿En dónde nació el quelite,\nque no nazcan los nopales?\n¿En dónde andan las palomas,\nque no andan los gavilanes?\n¿En dónde hay caras bonitas\nque no tengan ojos iguales?",105,2,-1,123,"Pancho Nopales",9,6,"ae",-1,0,-1,0,307,307,"4584","",0,"","","",1,0,0,[],""],["frenk_t2-n4586",6,"No hay gusto como dar gusto,\n¡y qué gusto sabe dar!,\nque es muy bonito tener\nuna trigueña formal.",105,2,-1,123,"La india; Ahora pregunto, pregunto",0,4,"a",-1,0,-1,0,307,307,"4586","",0,"","","",1,0,0,[],""],["frenk_t2-n4587",6,"Todo hombre que se muere\nsin querer una morena\no tomar un chocolate\nno sabe lo que es canela.",105,2,-1,123,"Estrofa suelta",0,4,"ea",-1,0,-1,0,307,307,"4587","",0,"","","",1,0,0,[],""],["frenk_t2-n4588",6,"El que ama a una morena\nle ha tocado buena suerte:\nnada en el mundo le apena,\nni se acuerda de la muerte.",108,2,8,123,"Estrofa suelta",1,4,"ee",134,0,-1,0,307,307,"4588","",0,"","","",1,0,0,[],""],["frenk_t2-n4589",6,"La mujer color moreno,\ncomo costeña muy leal,\nsiempre fiel a su costeño,\nen el pueblo y junto al mar.",105,2,-1,123,"La cruceñita",0,4,"a",-1,0,-1,0,307,307,"4589","",0,"","","",1,0,0,[],""],["frenk_t2-n4590",6,"Una perfumada rosa\nconversó con la azucena,\ny también dijo otra cosa:\nque toda mujer morena\nes simpática y hermosa.",112,2,6,123,"La azucena",7,5,"oa",63,0,-1,0,307,307,"4590","",0,"","","",1,0,0,[],""],["frenk_t2-n4591",6,"Jamiltepec,\nes bien sabido\nque el amor de morena\nnunca es fingido.",108,2,8,123,"Chilena de Jamiltepec",6,4,"io",101,0,-1,0,307,307,"4591","",0,"","","",3,0,0,[],""],["frenk_t2-n4592",6,"De la mar yo recibí (¡ay, Llorona!)\nuna carta de sirena,\ny en la carta me decía: (¡ay, Llorona!)\n“Quien tiene amor tiene pena.”",105,2,-1,123,"La llorona",3,4,"ea",59,0,-1,0,311,311,"4592","",0,"","","",1,0,0,[],""],["frenk_t2-n4593",6,"Donde hay sonrisa hay dolor,\ndonde hay rosas hay espinas,\ndonde hay lirios hay dolor\ny ruedan muy cristalinas\nlágrimas donde hay amor.",105,2,-1,123,"La azucena",7,5,"o",72,0,-1,0,311,311,"4593","",0,"","","",1,0,0,[],""],["frenk_t2-n4594",6,"¡Mal haya quien dijo amor,\npudiendo decir veneno!\n¡Mal haya quien come suyo,\npudiendo comer lo ajeno!",108,2,8,123,"Estrofa suelta",0,4,"eo",76,0,-1,0,311,311,"4594","",0,"","","",1,0,0,[],""],["frenk_t2-n4595",6,"Corren las tribulaciones\npor las montañas de abril;\nel amor es un veneno\npara el que sabe sentir.",108,2,8,123,"Estrofa suelta",0,4,"i",-1,0,-1,0,311,311,"4595","",0,"","","",1,0,0,[],""],["frenk_t2-n4596",6,"¡Ay, scholin tatá celoso!,\n¡ay, scholin naná celosa!,\n¡ay, qué triste sentimiento!,\n¡ay, que lo que es amor!.",115,2,3,123,"Flor de changunga",5,4,"o",-1,0,-1,0,311,311,"4596","",0,"","","",1,0,0,[],""],["frenk_t2-n4597",6,"Gallo, si supieras\nqué cosa es amar,\nno cantarías tanto:\n¡cómo has de cantar!",105,2,-1,123,"Naranjas y limas",0,4,"a",21,0,-1,0,311,311,"4597","",0,"","","",2,0,0,[],""],["frenk_t2-n4598",6,"Gallo, si supieras\nqué cosa es querer,\nno cantarías tanto\nal amanecer.",105,2,-1,123,"Naranjas y limas",0,4,"e",20,0,-1,0,311,311,"4598","",0,"","","",2,0,0,[],""],["frenk_t2-n4600a",6,"¡Ay de mí, Llorona!\nLlorona de un campo lirio;\nel que no sabe de amores (Llorona)\nno sabe lo que es martirio.",108,2,8,123,"La Llorona",3,4,"io",360,0,-1,0,312,312,"4600a","",0,"","","",35,0,0,[],""],["frenk_t2-n4600b",6,"Al pie de un encino roble\nvine a dejarte un lirio;\nel que no sabe de amores\nno sabe lo que es martirio.",115,2,3,123,"El jarabe jaranero; La Malagueña curreña",0,4,"io",360,0,-1,0,312,312,"4600b","",0,"","","",3,0,0,[],""],["frenk_t2-n4601",6,"Frijoles pintos,\nclaveles dorados;\n¡cómo sufren\nlos enamorados!",119,2,12,123,"Estrofa suelta",3,4,"ao",18,0,-1,0,312,312,"4601","",0,"","","",1,0,0,[],""],["frenk_t2-n4602",6,"Yo le pregunté a Cupido\nremedios para olvidar,\n“Remedios no puedo dar;\nde ese mal he padecido\ny no he podido sanar.”",106,2,4,123,"La leva; Estrofa suelta",7,5,"a",21,0,-1,0,312,312,"4602","",0,"","","",8,0,0,[],""],["frenk_t2-n4603",6,"Un corazón malherido (Llorona)\nsólo con llorar descansa;\nel rico, con su dinero (Llorona)\ny el pobre, con su esperanza.",107,2,11,123,"La Llorona",3,4,"aa",163,0,-1,0,312,312,"4603","",0,"","","",1,0,0,[],""],["frenk_t2-n4604",6,"En las concavidades,\nsu pecho herido\nun pájaro extranjero (cielito lindo)\nquiso hacer nido;\nmas no es probable:\nun corazón herido (chiquititita)\nno asiste a nadie.",106,2,4,123,"Cielito lindo",4,7,"ae",-1,0,-1,0,312,312,"4604","",0,"","","",1,0,0,[],""],["frenk_t2-n4605",6,"La dicha más cumplida\nde la existencia\nno iguala, no, las penas\nque da la ausencia.",115,2,3,123,"La despedida; Estrofa suelta",6,4,"ea",-1,0,-1,0,312,312,"4605","",0,"","","",1,0,0,[],""],["frenk_t2-n4606",6,"Que la ausencia nos llena\nde duelo tanto,\nque no alcanza a curarla\nni un mar de llanto.",115,2,3,123,"La despedida*’",6,4,"ao",30,0,-1,0,313,313,"4606","",0,"","","",1,0,0,[],""],["frenk_t2-n4607",6,"¡Ay de los corazones\nque se separan!\nNo haber latido nunca\nmejor desearan.",115,2,3,123,"La despedida; Estrofa suelta",6,4,"aa",435,0,-1,0,313,313,"4607","",0,"","","",1,0,0,[],""],["frenk_t2-n4609",6,"¡Qué tristes quedan los campos\ncuando el sol se está poniendo!\nAsí quedan dos amantes\ncuando se están despidiendo.",105,2,-1,123,"Estrofa suelta",0,4,"eo",52,0,-1,0,313,313,"4609","",0,"","","",1,0,0,[],""],["frenk_t2-n4610",6,"¿A quién volver los ojos\nque el llanto ofusca,\nsi el alma sólo a otra alma\ndoquiera busca?",115,2,3,123,"La despedida",6,4,"ua",416,0,-1,0,313,313,"4610","",0,"","","",1,0,0,[],""],["frenk_t2-n4612",6,"Dos seres que se adoran\ny ausentes viven\nsólo sienten consuelo\ncuando se escriben;\ny es evidente\nque es la pluma el consuelo (cielito lindo)\ndel que está ausente.",106,2,4,123,"Cielito lindo",4,7,"ee",15,0,-1,0,313,313,"4612","",0,"","","",1,0,0,[],""],["frenk_t2-n4613",6,"El que suspira algo siente,\nalgo tiene para sí,\npero de continuamente\nle sucede lo que a mí:\namar y vivir ausente.",113,2,2,123,"El caballito; Estrofa suelta",7,5,"ee",15,0,-1,0,313,313,"4613","",0,"","","",1,0,0,[],""],["frenk_t2-n4614",6,"Dicen que no se siente\nla despedida;\ndile al que te lo cuente\nque se despida\ndel ser que adora,\ny verá que se siente\ny hasta se llora.",107,2,11,123,"CieUto lindo",4,7,"oa",107,0,-1,0,314,314,"4614","",0,"","","",4,0,0,[],""],["frenk_t2-n4615",6,"Cupido estuvo postrado\nen el lecho de dolores;\nque le decía a los cantores:\n“Si dicha es vivir amando,\n¡qué horrible es morir de amores!”",108,2,8,123,"Zapateado",7,5,"oe",5,0,-1,0,314,314,"4615","",0,"","","",1,0,0,[],""],["frenk_t2-n4617",6,"Ni con la ausencia se olvidan\nlas horas que se han gozado;\nlo digo aunque sea mentira,\nlo juro aunque sea pecado,\nque si hay penas en la vida\nes recordar lo pasado.",113,2,2,123,"La Malagueña",9,6,"ao",14,0,-1,0,314,314,"4617","",0,"","","",1,0,0,[],""],["frenk_t2-n4618",6,"Es imposible olvidar\nla joven que se ha querido:\nes más fácil caminar\npor una tumba tendido\ny no dejarla de amar.",113,2,2,123,"El San Lorenzo",7,5,"a",21,0,-1,0,315,315,"4618","",0,"","","",1,0,0,[],""],["frenk_t2-n4619",6,"Las flores al marchitarse\ndejan su aroma esparcida;\nel amor al terminarse\ndeja en el alma una herida,\nque es imposible curarse.",113,2,2,123,"Las flores; El sacamandú; Estrofa suelta",7,5,"ae",250,0,-1,0,315,315,"4619","",0,"","","",1,0,0,[],""],["frenk_t2-n4620",6,"Si acaso alguien te pregunta\nqué fin tienen los amores,\ncontesta como los troncos:\nque el aroma de las flores,\nsi se va, no vuelve nunca.",112,2,6,123,"Las flores; Estrofa suelta",7,5,"ua",-1,0,-1,0,315,315,"4620","",0,"","","",1,0,0,[],""],["frenk_t2-n4621",6,"Cuando la pasión se trunca\nhalla en el olvido calma;\ny mi mente se pregunta:\n¿por qué las flores del alma,\nsi se van, no vuelven nunca?",119,2,12,123,"La huazanga",7,5,"ua",-1,0,-1,0,315,315,"4621","",0,"","","",1,0,0,[],""],["frenk_t2-n4622",6,"En un árbol corpulento\ncantaba un viejo en la selva:\n“Hojas que arrebata el viento\njamás esperes que vuelvan.”",108,2,8,123,"Estrofa suelta",0,4,"ea",-1,0,-1,0,315,315,"4622","",0,"","","",2,0,0,[],""],["frenk_t2-n4624",6,"Hay heridas que son viejas,\nque con remedio no sanan:\nsólo las pueden curar\nlos potitos de lautana.",105,2,-1,123,"El tiburón",0,4,"aa",-1,0,-1,0,315,315,"4624","",0,"","","",1,0,0,[],""],["frenk_t2-n4626",6,"En el monte hay una flor\nque le nombran la cereza.\nBonito fuera el amor\nsi acabara como empieza,\npero acaba con dolor\ny punzadas de cabeza.",106,2,4,123,"El pájaro cú; La guacamaya",9,6,"ea",108,0,-1,0,316,316,"4626","",0,"","","",1,0,0,[],""],["frenk_t2-n4627",6,"En el templo del amor\nme puse a considerar\ncuál sería el mayor dolor:\npara poderme explicar,\ntener celos sin amor,\no amor sin poderle hablar.",108,2,8,123,"Estrofa suelta",9,6,"a",21,0,-1,0,316,316,"4627","",0,"","","",1,0,0,[],""],["frenk_t2-n4628",6,"Triste el mar sin espuma,\ntriste la noche sin luna,\npero más triste es vivir\nsin esperanza ninguna.",129,2,9,123,"Estrofa suelta",0,4,"ua",56,0,-1,0,316,316,"4628","",0,"","","",1,0,0,[],""],["frenk_t2-n4630",6,"Yo no sé qué es la mujer,\nque al hombre apasiona tanto;\nes muy dulce su querer,\npero también es quebranto\ny profundo padecer.",112,2,6,123,"La huazanga; La leva; La pasión; Estrofa suelta",7,5,"e",20,0,-1,0,316,316,"4630","",0,"","","",2,0,0,[],""],["frenk_t2-n4631",6,"Yo no sé qué es la mujer,\nque al hombre apasiona tanto;\nponiéndonos a pensar,\nson ilusiones perdidas\nlas que vamos a cantar.",106,2,4,123,"La presumida",7,5,"a",21,0,-1,0,316,316,"4631","",0,"","","",2,0,0,[],""],["frenk_t2-n4632",6,"Por mujer vienen los males\nal hombre que se propasa;\npor amar pierde su casa,\nsu ser, honor y caudales.",105,2,-1,123,"Estrofa suelta",11,4,"ae",26,0,-1,0,316,316,"4632","",0,"","","",1,0,0,[],""],["frenk_t2-n4633",6,"Para el hombre se hicieron las penas,\npara el hombre se hizo el padecer,\npara el hombre se hicieron cadenas\npor el amor de una ingrata mujer.",109,2,7,123,"Vengo a ver unos ojos que tengo",3,4,"e",20,0,-1,0,317,317,"4633","",0,"","","",1,0,0,[],""],["frenk_t2-n4634",6,"¡Adiós, cárcel de Morelia,\nhecha de cuatro paredes,\ndonde se acaban los hombres\npor las ingratas mujeres!",105,2,-1,123,"Pajarillo, pajarillo; Bonito San Juan del Río; Escaleras de la cárcel; Palomas que andan volando",0,4,"ee",-1,0,-1,0,317,317,"4634","",0,"","","",1,0,0,[],""],["frenk_t2-n4635",6,"Del cielo cayó un pañuelo\nprendido con alfileres;\nla perdición de los hombres\nson las ingratas mujeres.",118,2,27,123,"Ojitos negros y chinos; Estrofa suelta",0,4,"ee",55,0,-1,0,317,317,"4635","",0,"","","",17,0,0,[],""],["frenk_t2-n4636",6,"Áhi te va la despedida,\nchinita, por tus quereres;\nla perdición de los hombres\nson las ingratas mujeres;\ny aquí se acaban cantando\nlos versos de los laureles.",107,2,11,123,"Los laureles",9,6,"ee",-1,0,-1,0,317,317,"4636","",0,"","","",6,0,0,[],""],["frenk_t2-n4637",6,"Eres mi prenda querida,\nmi prenda querida eres;\nla perdición de los hombres\nla causa son las mujeres.",108,2,8,123,"El pájaro cú; El siquisirf’",0,4,"ee",55,0,-1,0,317,317,"4637","",0,"","","",9,0,0,[],""],["frenk_t2-n4638",6,"Aquí va la despedida,\npor las hojas de un encino;\nla perdición de los hombres\nson las mujeres y el vino.",120,2,14,123,"Tus ojitos",0,4,"io",199,0,-1,0,317,317,"4638","",0,"","","",2,0,0,[],""],["frenk_t2-n4639",6,"Sólo amando se comprende\nlo que hiere una traición:\ncuando una mujer ofende\ndeja herido el corazón\ndel hombre que la pretende.",112,2,6,123,"La azucena",7,5,"ee",233,0,-1,0,317,317,"4639","",0,"","","",1,0,0,[],""],["frenk_t2-n4641",6,"En una mansión oscura\noí una voz en la altura,\nque estas expresiones daba:\n“El que ama con más ternura\ncon desprecio se le paga.”",113,2,2,123,"Estrofa suelta",7,5,"aa",-1,0,-1,0,318,318,"4641","",0,"","","",2,0,0,[],""],["frenk_t2-n4642a",6,"Una vela se consume (¡ay, Llorona!)\na fuerza de tanto arder;\nasí se consume el hombre (¡ay, Llorona!)\npor una ingrata mujer.",108,2,8,123,"La Llorona",3,4,"e",20,0,-1,0,318,318,"4642a","",0,"","","",1,0,0,[],""],["frenk_t2-n4643b",6,"¡Qué triste queda la luna\ncuando el sol no la acompaña!,\n¡y qué triste queda el hombre\ncuando la mujer engaña!",107,2,11,123,"La huazanga; Estrofa suelta",0,4,"aa",213,0,-1,0,318,318,"4643b","",0,"","","",1,0,0,[],""],["frenk_t2-n4643c",6,"Ya la luna ya salió,\ny un lucero la acompaña.\n¡Qué triste se queda el hombre\ncuando la mujer lo engaña!\nSe queda como el gusano\ncuando, lo enreda la araña.",109,2,7,123,"Estrofa suelta",9,6,"aa",213,0,-1,0,318,318,"4643c","",0,"","","",1,0,0,[],""],["frenk_t2-n4644",6,"Si de cristales fueran (mi vida),\nlos corazones,\ndesde lejos se vieran\nlas intenciones.",105,2,-1,123,"Estrofa suelta",3,4,"oe",34,0,-1,0,321,321,"4644","",0,"","","",1,0,0,[],""],["frenk_t2-n4645",6,"Una paloma al volar\nquiso vivir a su extremo;\n¡quién pudiese adivinar\nlos pensamientos ajenos!",105,2,-1,123,"La Sanmarqueña",0,4,"eo",-1,0,-1,0,321,321,"4645","",0,"","","",8,0,0,[],""],["frenk_t2-n4646",6,"Vide el sol y vi llover,\nlo claro ponerse oscuro,\ny también vi deshacer\nun amor ’tando seguro.",117,2,5,123,"Estrofa suelta",1,4,"uo",248,0,-1,0,321,321,"4646","",0,"","","",1,0,0,[],""],["frenk_t2-n4647",6,"En la orilla de un estero,\nen donde mi amor bajaba;\nel amor es como el fuego:\nsi no le atizan se apaga.",112,2,6,123,"El jarabe",0,4,"aa",-1,0,-1,0,321,321,"4647","",0,"","","",1,0,0,[],""],["frenk_t2-n4648",6,"Si dos corazones se aman\ny no se fingen querer,\ncuando la pasión es grande\nse empiezan a aborrecer.",106,2,4,123,"Las poblanitas",0,4,"e",20,0,-1,0,321,321,"4648","",0,"","","",1,0,0,[],""],["frenk_t2-n4649",6,"Nadie diga que es querido,\nni de querido se precie,\nque un cordón de oro torcido\nda la vuelta y se destuerce.",105,2,-1,123,"Estrofa suelta",0,4,"ee",-1,0,-1,0,321,321,"4649","",0,"","","",4,0,0,[],""],["frenk_t2-n4650a",6,"Nadie diga que es amado,\naunque lo estén adorando,\npues con un pie en el estribo\nmuchos se quedan colgando.",123,2,20,123,"La leva; Estrofa suelta",0,4,"ao",33,0,-1,0,321,321,"4650a","",0,"","","",1,0,0,[],""],["frenk_t2-n4650c",6,"Nadie diga que es querido,\nni aunque lo estén adorando;\nque un cordón de oro torcido\nsolo va desenredando;\nque hay muchos en el estribo\nse quedan a pie y andando.",105,2,-1,123,"El venadito’",9,6,"ao",33,0,-1,0,322,322,"4650c","",0,"","","",4,0,0,[],""],["frenk_t2-n4651",6,"Todavía no la he mirado\nla que elija para esposa,\nporque estoy desengañado;\npronto se ve mancornado.",112,2,6,123,"El sacamandú",5,4,"ao",14,0,-1,0,322,322,"4651","",0,"","","",1,0,0,[],""],["frenk_t2-n4652",6,"Del cielo cayó un pañuelo\nbordado con alfileres;\n¡ay, qué idiotas son los hombres\nque lloran por las mujeres!",130,2,21,123,"Estrofa suelta",0,4,"ee",55,0,-1,0,322,322,"4652","",0,"","","",17,0,0,[],""],["frenk_t2-n4653",6,"Una rosa boté al agua\ncon veinticinco botones;\nveinticinco puñaladas\nmerece el que tiene amores\ncon una mujer casada.",117,2,5,123,"Estrofa suelta",7,5,"aa",-1,0,-1,0,322,322,"4653","",0,"","","",1,0,0,[],""],["frenk_t2-n4654",6,"Del cielo cayó una caja\nrepleta de alfileres,\npara picar a los hombres\nque engañan a las mujeres.",107,2,11,123,"Estrofa suelta",0,4,"ee",55,0,-1,0,322,322,"4654","",0,"","","",2,0,0,[],""],["frenk_t2-n4655",6,"En la puerta de mi casa\ntengo una mata de ruda,\npara el hombre sinvergüenza\nque se enamore una viuda.",108,2,8,123,"María, María",0,4,"ua",144,0,-1,0,322,322,"4655","",0,"","","",24,0,0,[],""],["frenk_t2-n4656",6,"Pajarito, rito, rito,\npájaro vaquero quero,\nque no hay muchacha bonita\nque no tenga pero pero.",106,2,4,123,"El pájaro cú",0,4,"eo",38,0,-1,0,323,323,"4656","",0,"","","",2,0,0,[],""],["frenk_t2-n4657",6,"Tienen mucha semejanza\nlas mujeres con las rosas,\nque apenas les pega el sol,\ny ya se les caen las hojas.",105,2,-1,123,"Estrofa suelta",0,4,"oa",-1,0,-1,0,323,323,"4657","",0,"","","",1,0,0,[],""],["frenk_t2-n4658",6,"Hay muchas flores bonitas,\npero muy pobres de aroma;\nasí como hay jovencitas\na quien el orgullo doma:\nse quedan las pobrecitas\ncomo una triste paloma.",106,2,4,123,"Las flores",9,6,"oa",86,0,-1,0,323,323,"4658","",0,"","","",1,0,0,[],""],["frenk_t2-n4659",6,"Nació el pino, nació el cedro,\ny también nació el ocote,\nnació la infeliz mujer:\ndespués de tanto escoger\nperdió albur y tecolote.",105,2,-1,123,"Estrofa suelta",7,5,"oe",292,0,-1,0,323,323,"4659","",0,"","","",1,0,0,[],""],["frenk_t2-n4660b",6,"Como la caña hueca\nson las mujeres,\nse llenan todas de viento (cielito lindo)\ncuando las quieren;\nasí son todas:\nno saben que a los hombres (cielito lindo)\nnos gustan todas.",105,2,-1,123,"Cielito lindo",4,7,"oa",-1,0,-1,0,323,323,"4660b","",0,"","","",3,0,0,[],""],["frenk_t2-n4661",6,"Las mujeres desdeñosas\nson como las aceitunas,\nque la que parece verde\nsuele ser la más madura.",105,2,-1,123,"Ya no lloverá, pelonas",0,4,"ua",-1,0,-1,0,323,323,"4661","",0,"","","",2,0,0,[],""],["frenk_t2-n4662",6,"La mujer contenta está\nsi la acarician seguido;\npero con seguridad,\nsi el hombre es desatendido,\nle pierde la voluntad\ny se va con otro amigo.",112,2,6,123,"La leva",9,6,"io",-1,0,-1,0,323,323,"4662","",0,"","","",1,0,0,[],""],["frenk_t2-n4665",6,"Siempre que te enamores,\nmira primero\ndónde pones los ojos (cielito lindo):\nno llores luego.",105,2,-1,124,"Cielito lindo",3,4,"eo",-1,0,-1,0,325,325,"4665","",0,"","","",1,0,0,[],""],["frenk_t2-n4666",6,"Tiene cinturón de raso,\nojos de bello lucero.\nPiénselo bien y despacio,\nno después le ponga pero;\nno eches la culpa al acaso\nasí que no haya remedio.",106,2,4,124,"Estrofa suelta",9,6,"eo",-1,0,-1,0,325,325,"4666","",0,"","","",1,0,0,[],""],["frenk_t2-n4667",6,"Pues, don Diego, no se apene,\nno se muera de pasiones,\npues mire con quién conviene;\nel amor es de razón,\nporque la india sostiene.",106,2,4,124,"La azucena",7,5,"ee",70,0,-1,0,325,325,"4667","",0,"","","",1,0,0,[],""],["frenk_t2-n4668",6,"Si la pasión te domina\no te hace grado el amor,\nte extiende la vista y mira;\nhora estás en la flor:\nno después te cause envidia\ny quedrás otro mejor.",108,2,8,124,"Estrofa suelta",9,6,"o",72,0,-1,0,325,325,"4668","",0,"","","",1,0,0,[],""],["frenk_t2-n4669",6,"Es muy malo apasionarse\nde quien no sabe querer;\npor eso debe estudiarse\ncon cuidado a la mujer,\npara nunca equivocarse.",112,2,6,124,"Estrofa suelta",7,5,"ae",250,0,-1,0,325,325,"4669","",0,"","","",1,0,0,[],""],["frenk_t2-n4670",6,"Un consejo voy a dar,\nconsejo que es de ranchero:\nno te dejes ensillar\nni que te echen el suadero;\npor eso antes de amarrar\ntenia el vidrio, compañero.",105,2,-1,124,"El fuereño",9,6,"eo",38,0,-1,0,325,325,"4670","",0,"","","",1,0,0,[],""],["frenk_t2-n4671",6,"Tienen que ser abusados\npara evitar muchas cosas;\ndeben de abrir bien los ojos\npara escoger sus esposas.",105,2,-1,124,"Los bueyes",0,4,"oa",61,0,-1,0,325,325,"4671","",0,"","","",1,0,0,[],""],["frenk_t2-n4673",6,"Consejo voy a darle\na todo el que sea mi amigo:\nque no se deje engañar,\nque si es falta del descuido,\ny es muy triste pasar\nlo que otro ya se ha comido.",106,2,4,124,"Estrofa suelta",9,6,"io",101,0,-1,0,326,326,"4673","",0,"","","",1,0,0,[],""],["frenk_t2-n4674",6,"Deben tomarlo en cuenta\nlos que se quieren matrimoniar:\nno es lo mismo ver los toros\nque capotearlos en el corral.",105,2,-1,124,"Antes y después",3,4,"a",-1,0,-1,0,326,326,"4674","",0,"","","",1,0,0,[],""],["frenk_t2-n4675",6,"El hombre que se casa\ndebe tener\nnunca ser gobernado (cielito lindo)\npor su mujer;\nporque unas viejas\nse traen a su marido (cielito lindo)\nde las orejas.",112,2,6,124,"Cielito lindo; Estrofa suelta",4,7,"ea",496,0,-1,0,326,326,"4675","",0,"","","",5,0,0,[],""],["frenk_t2-n4677",6,"Cupido me dijo a mí\nque no me malbaratara,\nque primero andara el mundo\ny después que me casara.",106,2,4,124,"El Cupido’",0,4,"aa",57,0,-1,0,326,326,"4677","",0,"frenk_t4","","",3,0,0,[],""],["frenk_t2-n4678",6,"Me dice la chuparrosa\nque no ande de bandolero,\nque no me case tan pronto,\nque mire al mundo primero.",121,2,26,124,"La chuparrosa",0,4,"eo",38,0,-1,0,326,326,"4678","",0,"","","",1,0,0,[],""],["frenk_t2-n4679",6,"Y en las cosas del cariño\nnunca debes de confiar,\ny el querer o ser querido\nno se debe demostrar.",105,2,-1,124,"Tres consejos",0,4,"a",21,0,-1,0,326,326,"4679","",0,"","","",1,0,0,[],""],["frenk_t2-n4680",6,"Si te dicen que te aman,\nno te debes de confiar:\nhay amores muy bonitos\nque les da por traicionar.",105,2,-1,124,"Pajarito jaralero",0,4,"a",21,0,-1,0,327,327,"4680","",0,"","","",1,0,0,[],""],["frenk_t2-n4681",6,"Nunca te fíes de promesas\ny mucho menos de amores,\nque si te dan calabazas,\nverás lo que son ardores.",105,2,-1,124,"Allá en el Rancho Grande",0,4,"oe",5,0,-1,0,327,327,"4681","",0,"","","",1,0,0,[],""],["frenk_t2-n4682",6,"Cuando te pidan amor\ntarda mucho en contestar,\nporque amor que pronto se da\npronto se ha de acabar.",129,2,9,124,"Estrofa suelta",0,4,"a",-1,0,-1,0,327,327,"4682","",0,"","","",1,0,0,[],""],["frenk_t2-n4683",6,"El amor es muy bonito,\nno se le puede negar;\ndalo poquito a poquito,\ny nunca se acabará.",105,2,-1,124,"Tres consejos",0,4,"a",-1,0,-1,0,327,327,"4683","",0,"","","",1,0,0,[],""],["frenk_t2-n4684",6,"Una flor me dijo un día:\n“No entregues todo tu amor;\nsi quieres, pa’ toda la vida\nte roban el corazón.”\nFlorecita tempranera,\nyo sé que tenías razón.",105,2,-1,124,"Pena huasteca",9,6,"o",31,0,-1,0,327,327,"4684","",0,"","","",1,0,0,[],""],["frenk_t2-n4685",6,"No te prodigues en dar,\nporque aquí, como en Cuquío,\nse acostumbra reservar\ntú lo tuyo y yo lo mío.",105,2,-1,124,"El mosco; Estrofa suelta",3,4,"io",3,0,-1,0,327,327,"4685","",0,"","","",1,0,0,[],""],["frenk_t2-n4686",6,"Échale llave a tus puertas\ny aldabas al corazón:\nsi las mantienes abiertas,\n¿qué culpa tiene el ladrón?",108,2,8,124,"Estrofa suelta",1,4,"o",31,0,-1,0,327,327,"4686","",0,"","","",1,0,0,[],""],["frenk_t2-n4687",6,"Si estás enamorada,\nno lo demuestres,\nque puede el hombre que amas,\ndarte la muerte.",105,2,-1,124,"Estrofa suelta",6,4,"ee",-1,0,-1,0,327,327,"4687","",0,"","","",1,0,0,[],""],["frenk_t2-n4689",6,"Si lo quieres, dile “Un poco”,\nnunca digas “Mucho, mucho”,\nporque aquí quien dice “Mucho”\nhabla mucho y quiere poco.",106,2,4,124,"El tuxpefio",11,4,"oo",-1,0,-1,0,328,328,"4689","",0,"","","",1,0,0,[],""],["frenk_t2-n4690",6,"En tu vida te enamores (Llorona)\nde mozo que no ha rondado,\nque el que no ronda de mozo (Llorona)\nronda después de casado.",108,2,8,124,"La Llorona",3,4,"ao",14,0,-1,0,328,328,"4690","",0,"","","",1,0,0,[],""],["frenk_t2-n4691",6,"Saucito sobre saucito\nnacido en la humedad.\nNo es bueno tener amores\ncon jóvenes de poca edad,\nno tienen formalidad.",108,2,8,124,"Estrofa suelta, Que comienzo, que comienzo’",7,5,"a",16,0,-1,0,328,328,"4691","",0,"","","",1,0,0,[],""],["frenk_t2-n4692",6,"Para cuando te cases,\nyo te aconsejo:\ncásate con un joven (cielito lindo),\nno con un viejo;\npues da dolor\nver una rama seca (cielito lindo)\ncon una flor.",105,2,-1,124,"Cielito lindo",4,7,"o",72,0,-1,0,328,328,"4692","",0,"","","",1,0,0,[],""],["frenk_t2-n4693",6,"No te fíes de un casado,\naunque te muestre firmeza,\nporque al cabo vienes siendo\nplato de segunda mesa.",106,2,4,124,"No te fíes de un casado",0,4,"ea",201,0,-1,0,328,328,"4693","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4694",6,"“No quiero amor con casado”\nme lo dijo ya una viuda,\n“que quien de ajeno se viste\nen la calle lo desnudan”.",105,2,-1,124,"Al derecho y al revés",0,4,"ua",-1,0,-1,0,328,328,"4694","",0,"","","",1,0,0,[],""],["frenk_t2-n4695",6,"No te enamores nunca\nde una casada,\nque es fruta vana,\nfruta vedada.",105,2,-1,124,"Estrofa suelta",6,4,"aa",-1,0,-1,0,328,328,"4695","",0,"","","",1,0,0,[],""],["frenk_t2-n4696",6,"Estando yo recostado\nsobre la media arena,\nsale un pescado y me dice:\n“No siembres en tierra ajena,\nporque te ha de costar caro\nel querer a esa morena.”",108,2,8,124,"Estrofa suelta",9,6,"ea",59,0,-1,0,329,329,"4696","",0,"","","",2,0,0,[],""],["frenk_t2-n4697",6,"De tuna y de nopalitos\nestán las laderas llenas;\npor eso no es bueno engreírse\ncon las mujeres ajenas.",115,2,3,124,"El borracho",0,4,"ea",62,0,-1,0,329,329,"4697","",0,"","","",1,0,0,[],""],["frenk_t2-n4698",6,"Ya te he dicho que no siembres\nlas uvas en el camino,\nporque pasa el pasajero\ny se lleva el mejor racimo.",115,2,3,124,"El pasajero; El gusto; Pajarillo barranqueño; La sandía; Estrofa suelta",0,4,"io",-1,0,-1,0,329,329,"4698","",0,"","","",3,0,0,[],""],["frenk_t2-n4699",6,"Ya te he dicho que no siembres\nlas uvas en la barranca,\nporque pasa el pasajero\ny hasta la matita arranca.",105,2,-1,124,"La sandía; Aguilillas; Estrofa suelta",0,4,"aa",75,0,-1,0,329,329,"4699","",0,"","","",3,0,0,[],""],["frenk_t2-n4700",6,"Ya te he dicho que no siembres\nlas uvas en el corral:\nlos arrieros son tan malos,\ny hasta a ti te han de llevar.",105,2,-1,124,"Aguamas",0,4,"a",-1,0,-1,0,329,329,"4700","",0,"","","",3,0,0,[],""],["frenk_t2-n4701",6,"“Aguadores, ¡qué sed traigo!”,\ndijo un infeliz soldado;\nvale más ser apacible,\ny no ser apasionado.",105,2,-1,124,"El aguanieve",0,4,"ao",14,0,-1,0,329,329,"4701","",0,"","","",1,0,0,[],""],["frenk_t2-n4702",6,"Si faltaran las mujeres,\nconvengo el apasionarse,\npero abundan esos seres:\nel hombre debe fijarse\npara gozar de placeres.",112,2,6,124,"Estrofa suelta",7,5,"ee",55,0,-1,0,329,329,"4702","",0,"","","",1,0,0,[],""],["frenk_t2-n4703",6,"Salomón hizo una carta,\nla cual era para Cupido,\ndonde le mandó decir:\n“Mi muy estimado amigo,\nvale más saber sentir\ny no darse por sentido.”",108,2,8,124,"Estrofa suelta",9,6,"io",-1,0,-1,0,329,329,"4703","",0,"","","",1,0,0,[],""],["frenk_t2-n4705",6,"Yo le pregunté a Cupido\ncómo hacía para querer,\ny me contestó el afligido:\n“Por eso es bueno saber\nvivir bien advertido\ny no volverse a meter.”",108,2,8,124,"Estrofa suelta",9,6,"e",20,0,-1,0,330,330,"4705","",0,"","","",8,0,0,[],""],["frenk_t2-n4706",6,"La luna real en su coche,\nconquistando corazones.\nPues no habrá quien me reproche:\nquien no quiera ver visiones\nmejor que no ande de noche.",113,2,2,124,"El gusto",7,5,"oe",-1,0,-1,0,330,330,"4706","",0,"","","",1,0,0,[],""],["frenk_t2-n4707",6,"Corazón que siente agravio\nno puede respirar recio;\nmás vale morderse un labio\ny no sufrir un desprecio.",106,2,4,124,"Estrofa suelta",1,4,"eo",276,0,-1,0,330,330,"4707","",0,"","","",1,0,0,[],""],["frenk_t2-n4708",6,"Se ponen al fuego dos\nadarmes de indiferencia,\ncuarenta gotas de esencia\nde “abur y vaya con Dios”;\nse añade un adarme o dos\nde “no me importa” molido,\ny todo, muy bien cocido\nen agua de la alegría,\nse toma una vez al día\nen la taza del olvido.",105,2,-1,124,"Estrofa suelta",18,10,"io",101,0,-1,0,330,330,"4708","",0,"","","",1,0,0,[],""],["frenk_t2-n4709",6,"Temprano me bajé al baño\npor complacer mi deseo.\nDoy consejo a los extraños,\ny hoy que estoy en mi apogeo,\ny la carne no me hace daño,\nporque nada más la veo.",106,2,4,124,"Estrofa suelta",9,6,"eo",66,0,-1,0,330,330,"4709","",0,"","","",1,0,0,[],""],["frenk_t2-n4710",6,"¿Qué pasó en Puerto Mayore,\nque me pasaron la audiencia?\nAlcaldes y regidores\nse jugaron mi sentencia:\nque nunca tenga yo amores\ndonde no hay correspondencia.",108,2,8,124,"La guacamaya’",9,6,"ea",46,0,-1,0,330,330,"4710","",0,"","","",1,0,0,[],""],["frenk_t2-n4711",6,"En una nube azuleja\náhi vide a mi amor llegar;\nllegando, me dio una queja:\nque no hay que demorar\ncon amor que no empareja.",112,2,6,124,"Estrofa suelta",7,5,"ea",165,0,-1,0,330,330,"4711","",0,"","","",1,0,0,[],""],["frenk_t2-n4712",6,"Si tu amor fuere fingido,\nno lo des a maliciar;\neste clavel salió vano,\nya me voy a separar.",105,2,-1,124,"‘‘Yo ya me voy",0,4,"a",21,0,-1,0,331,331,"4712","",0,"","","",1,0,0,[],""],["frenk_t2-n4713",6,"Si perdiste tu nidito,\nno te pongas a llorar,\nbúscate otra pajarita,\nque te quiera consolar.",105,2,-1,124,"Pajarito jaralero",0,4,"a",21,0,-1,0,331,331,"4713","",0,"","","",1,0,0,[],""],["frenk_t2-n4714",6,"Como amigo te aconsejo\nque olvides la chaparrita,\nque las manchas del amor\nsólo con amor se quitan.",105,2,-1,124,"Al pasar por los laureles; El brinco; Estrofa suelta",0,4,"ia",-1,0,-1,0,331,331,"4714","",0,"","","",2,0,0,[],""],["frenk_t2-n4715",6,"Cupido sacó un pescado\ny luego lo puso en paz;\ncomo era muy desconfiado,\nle dijo: “Hora no te vas;\nun clavo saca otro clavo,\nsi no lo remacha más.”",112,2,6,124,"El caimán; La Petenera",9,6,"a",51,0,-1,0,331,331,"4715","",0,"","","",1,0,0,[],""],["frenk_t2-n4716",6,"Todas las ilusiones\nque el amor fragua\nson como las espumas (cielito lindo)\nque forma el agua:\nsuben y crecen,\ny con el mismo viento (cielito lindo)\ndesaparecen.",107,2,11,123,"Cielito lindo",4,7,"ee",359,0,-1,0,335,335,"4716","",0,"","","",3,0,0,[],""],["frenk_t2-n4717",6,"Los sueños de enamorados\nse tiñen de oro y de plata;\npor más que estén afianzados,\nel viento los desbarata.",105,2,-1,123,"Las estrellas del cielo",1,4,"aa",74,0,-1,0,335,335,"4717","",0,"","","",1,0,0,[],""],["frenk_t2-n4718",6,"Cupido con Salomón\nse puso a tratar un gato;\ncomo le salió rabón,\nno lo quiso ni barato;\ny eso dice la razón:\n“Donde hay amores, no hay trato.",105,2,-1,123,"El feo; Estrofa suelta",9,6,"ao",19,0,-1,0,335,335,"4718","",0,"","","",3,0,0,[],""],["frenk_t2-n4719",6,"Un palomito al volar,\nque llevaba el pecho herido;\nya casi para llorar,\nme dijo muy afligido:\n“Ya me canso de buscar\nun amor correspondido.”",105,2,-1,123,"La cigarra",9,6,"io",101,0,-1,0,335,335,"4719","",0,"","","",1,0,0,[],""],["frenk_t2-n4720",6,"No hay amor correspondido\nen todito el ancho mundo:\ncuando uno está más engreído\ncon el amor más profundo,\nsi es que se siente uno rey,\nlo bajan a vagabundo.",105,2,-1,123,"Canta, corazón, canta",9,6,"uo",179,0,-1,0,335,335,"4720","",0,"","","",1,0,0,[],""],["frenk_t2-n4721",6,"Yo le amé con la existencia,\ny sin ser correspondido,\ny digo con experiencia\nque todo es tiempo perdido\ncuando no hay correspondencia.",105,2,-1,123,"La azucena",7,5,"ea",46,0,-1,0,335,335,"4721","",0,"","","",1,0,0,[],""],["frenk_t2-n4723",6,"Cuando el palo tumba la hoja\nqueda el palo inconocible;\nasí que aquel que se aloja\namar lo que no es posible:\nlo hace porque se le antoja,\npero de nada le sirve.",108,2,8,123,"Estrofa suelta",9,6,"ie",-1,0,-1,0,336,336,"4723","",0,"","","",1,0,0,[],""],["frenk_t2-n4724",6,"A México fui a pasear,\ny anduve tienda por tienda,\ny no he podido encontrar\namor que firmeza tenga,\npara poderme casar\nantes que la guerra venga.",105,2,-1,123,"La guacamaya",9,6,"ea",407,0,-1,0,336,336,"4724","",0,"","","",1,0,0,[],""],["frenk_t2-n4725",6,"Es muy recierto que el que se ausenta\nde sus amores, lo echan en olvido;\nyo se los digo, porque me ha pasado\ncon mis amores que yo he tenido.",120,2,14,123,"Corazón sólido’",3,4,"io",101,0,-1,0,336,336,"4725","",0,"","","",1,0,0,[],""],["frenk_t2-n4727",6,"Los hombres son injustos (cielito lindo)\ncon las mujeres,\npues se creen superiores (cielito lindo)\npor su poder;\nlos quiero ver\nveinte minutos justos (cielito lindo)\ncomo mujer.",105,2,-1,123,"Cielito lindo",4,7,"e",20,0,-1,0,336,336,"4727","",0,"","","",1,0,0,[],""],["frenk_t2-n4728",6,"Pasé por una fragua,\ndije al herrero:\n—Hágame usted un hombre\nde fino acero.\nÉl me responde:\n—¿Cómo quiere sea firme (caramba),\nsi ha de ser hombre?",120,2,14,123,"Mal haya la cocina; Cielito lindo",4,7,"oe",-1,0,-1,0,336,336,"4728","",0,"","","",1,0,0,[],""],["frenk_t2-n4729",6,"De sepulcro en sepulcro\nvoy preguntando\nque si no han visto un hombre\nque murió amando.\nRespondió uno:\n“Mujeres, a millares (cielito lindo)\ny hombres, ninguno.”",107,2,11,123,"CieUto lindo; La primavera",4,7,"uo",230,0,-1,0,336,336,"4729","",0,"","","",5,0,0,[],""],["frenk_t2-n4730",6,"Mal haya la cocina,\nmal haya el humo,\ny la mujer que cree\nen hombre alguno;\nporque son tales,\nporque todos los hombres (caramba)\nson informales.",120,2,14,123,"Mal haya la cocina",4,7,"ae",26,0,-1,0,337,337,"4730","",0,"","","",2,0,0,[],""],["frenk_t2-n4731",6,"La pila le falta el agua,\na un brasero, la lumbre\ny al hombre, la palabra\na la mujer, la costumbre.",108,2,8,123,"Estrofa suelta",0,4,"ue",181,0,-1,0,337,337,"4731","",0,"","","",1,0,0,[],""],["frenk_t2-n4732",6,"La flor de la maravilla\nnació entre los tomates;\nlas palabras de los hombres\nvalen puros cacahuates.",129,2,9,123,"Estrofa suelta",0,4,"ae",283,0,-1,0,337,337,"4732","",0,"","","",3,0,0,[],""],["frenk_t2-n4733",6,"Yo ser casada no quiero:\nsola me he de mantener;\nque el hombre más verdadero\ny de mejor parecer,\nno pasa de un embustero.",105,2,-1,123,"Estrofa suelta",7,5,"eo",38,0,-1,0,337,337,"4733","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4734",6,"Yo no hablo de las mujeres,\ntambién los hombres son malos:\nno cumplen con sus deberes,\ny los que cumplen son raros,\ncon esos divinos seres.",113,2,2,123,"La huazanga",7,5,"ee",55,0,-1,0,337,337,"4734","",0,"","","",1,0,0,[],""],["frenk_t2-n4735",6,"Si son los hombres tan insufribles\nque nunca dicen lo que es verdad;\nsuspiran, lloran, prometen, juran,\ny nada de eso es realidad.",105,2,-1,123,"Estrofa suelta",3,4,"a",16,0,-1,0,337,337,"4735","",0,"","","",1,0,0,[],""],["frenk_t2-n4736",6,"Pájaro que abandona\nsu primer nido\nsi lo encuentra ocupado (cielito lindo),\nmuy merecido.",107,2,11,123,"Cielito lindo; Pajarillo silguero",3,4,"io",101,0,-1,0,337,337,"4736","",0,"","","",2,0,0,[],""],["frenk_t2-n4737",6,"Pájaro que abandona\nsu primer nido\nregresa y ya no encuentra (cielito lindo)\nel bien perdido.",105,2,-1,123,"Cielito lindo",3,4,"io",101,0,-1,0,337,337,"4737","",0,"","","",2,0,0,[],""],["frenk_t2-n4738",6,"De los hombres en la vida\n¡ay, Antonia!, sus traiciones:\nmas cuando alguien los olvida,\ntienen viejas a montones.",111,2,1,123,"Antonia",1,4,"oe",34,0,-1,0,337,337,"4738","",0,"","","",1,0,0,[],""],["frenk_t2-n4740",6,"El hombre que a dos adora\ny las quiere por igual\nalgún día le llega la hora\nde tenerse que cuartear:\nel que a dos amos asiste\ncon alguno queda mal.",105,2,-1,123,"Las rejegas",9,6,"a",-1,0,-1,0,338,338,"4740","",0,"","","",1,0,0,[],""],["frenk_t2-n4743",6,"Dicen que el baile, el cariño,\ny el amor de una mujer\nlo inventó una noche el diablo\ncuando no tenía que hacer.",105,2,-1,123,"Ya no lloverá, pelonas",0,4,"e",20,0,-1,0,338,338,"4743","",0,"","","",1,0,0,[],""],["frenk_t2-n4744",6,"Son ángeles las mujeres,\ndice el apóstol San Pablo,\npero al fin son hijas de Eva\ny valedoras del diablo.",105,2,-1,123,"Estrofa suelta",0,4,"ao",567,0,-1,0,338,338,"4744","",0,"","","",1,0,0,[],""],["frenk_t2-n4745",6,"Las mujeres son el diablo,\nparientes de Lucifer:\nse visten por la cabeza,\nse desnudan por los pies.",105,2,-1,123,"La cucaracha; El mosquito",0,4,"e",-1,0,-1,0,338,338,"4745","",0,"machado_venezuela","","",8,0,0,[],""],["frenk_t2-n4746",6,"Λ una paloma al volar\nse le cayeron las plumas;\nque dispensen las que me oigan,\npero todas se hacen una.",105,2,-1,123,"Cómo quieres que una luz",0,4,"ua",-1,0,-1,0,338,338,"4746","",0,"","","",8,0,0,[],""],["frenk_t2-n4747",6,"¡Mal haya mi amor, mal haya\nel que me enseñó a querer!\nDespués de nacido el niño\nlo domina una mujer.",105,2,-1,123,"El tejón’*",0,4,"e",20,0,-1,0,339,339,"4747","",0,"","","",1,0,0,[],""],["frenk_t2-n4748",6,"La mujer nos satisface\nporque roba nuestro afecto,\ny si hace sufrir, le place;\ncomo se cree con derecho,\nlo que quiere del hombre hace.",111,2,1,123,"La azucena",7,5,"ae",84,0,-1,0,339,339,"4748","",0,"","","",1,0,0,[],""],["frenk_t2-n4749",6,"Las hembras son muy ladinas\npa conseguirse el amor:\nfingiendo que nos desprecian,\nnos roban el corazón.",105,2,-1,123,"Donde las dan las toman",0,4,"o",-1,0,-1,0,339,339,"4749","",0,"","","",1,0,0,[],""],["frenk_t2-n4750",6,"En todo el mundo he andado,\nbuscando pulque de caña,\ny no he podido encontrar\nmujer que no tenga maña.",108,2,8,123,"Estrofa suelta",0,4,"aa",213,0,-1,0,339,339,"4750","",0,"","","",1,0,0,[],""],["frenk_t2-n4751",6,"Dile a tu mamacita,\nsi te regaña,\nque las mujeres — tienen todas\nlas mismas mañas;\nal fin de cuentas,\nlas que no tienen unas — tienen otras\npa estar contentas.",106,2,4,123,"Cielito lindo",4,7,"ea",568,0,-1,0,339,339,"4751","",0,"","","",1,0,0,[],""],["frenk_t2-n4752",6,"El amor es fuego ardiente,\nque como el agua trasmina;\nlo digo sencillamente:\nque aunque la mujer es fina,\ntranquila no está su mente.",111,2,1,123,"Estrofa suelta",7,5,"ee",15,0,-1,0,339,339,"4752","",0,"","","",1,0,0,[],""],["frenk_t2-n4753",6,"Poner amor en mujer\nes escribir en el agua,\nechar nieve en una fragua,\no en el mar un alfiler.",122,2,13,123,"Estrofa suelta",11,4,"e",20,0,-1,0,339,339,"4753","",0,"","","",1,0,0,[],""],["frenk_t2-n4754",6,"Me subí hasta el elemento\na conversar con la luna;\nservirá de escarmiento\nel unirme con ninguna,\nporque se pierde estos tiempos\nla tinta, papel y pluma.",106,2,4,123,"La morena",9,6,"ua",-1,0,-1,0,339,339,"4754","",0,"","","",1,0,0,[],""],["frenk_t2-n4755",6,"No soy moneda de cobre,\nno soy moneda de plata;\ntengo mi orgullo de pobre,\nque ante nadie se abarata;\nel hombre vale por hombre\ny la mujer por ingrata.",105,2,-1,123,"La oveja perdida",9,6,"aa",74,0,-1,0,339,339,"4755","",0,"","","",1,0,0,[],""],["frenk_t2-n4757",6,"¡Qué bonito huele a lima!,\n¡qué fresca estará la mata!\nA que usted no me adivina,\nde una mujer y una gata,\nsi la gata es más indina\no la mujer más ingrata.",115,2,3,123,"‘‘La sandía’",9,6,"aa",74,0,-1,0,340,340,"4757","",0,"","","",2,0,0,[],""],["frenk_t2-n4758",6,"Las plantas a quien las riega\nle manifiestan cariño,\npero la mujer rejega\nquiere más al que le pega\nque al que la viste de armiño.",111,2,1,123,"Las rejegas",7,5,"io",176,0,-1,0,340,340,"4758","",0,"","","",1,0,0,[],""],["frenk_t2-n4759",6,"Una paloma al volar\nse le cayeron las plumas;\nlas mujeres pagan mal,\npero no todas, algunas.",105,2,-1,123,"El palomo",0,4,"ua",-1,0,-1,0,340,340,"4759","",0,"","","",8,0,0,[],""],["frenk_t2-n4760",6,"Papeles son papeles,\ncartas son cartas,\npalabras de mujeres,\ntodas son falsas.",105,2,-1,123,"Estrofa suelta",6,4,"aa",-1,0,-1,0,340,340,"4760","",0,"rm_t4","","",2,0,0,[],""],["frenk_t2-n4762",6,"La mujer que quiere\ndel hombre abusar,\nni el mismo demonio\nla puede cuidar.",105,2,-1,123,"Los celotes",0,4,"a",21,0,-1,0,340,340,"4762","",0,"","","",1,0,0,[],""],["frenk_t2-n4763a",6,"Al formar Dios la mujer,\nluego luego engañó a Adán;\ny si eso hizo la primera,\nlas demás ¡qué más harán!",105,2,-1,123,"El jarabe",0,4,"a",147,0,-1,0,340,340,"4763a","",0,"","","",1,0,0,[],""],["frenk_t2-n4764",6,"Con la mujer de hoy día\nnunca se sabe qué pasa;\npobre el que en ella confía\nllegando tarde a su casa.",107,2,11,123,"La calandria",1,4,"aa",123,0,-1,0,340,340,"4764","",0,"","","",1,0,0,[],""],["frenk_t2-n4765",6,"Los venados son muy listos,\ny las mujeres mucho más:\ncuando uno les pone cuernos\nes porque encornado ya está.",105,2,-1,123,"‘Έ1 nuevo tejón",0,4,"a",-1,0,-1,0,341,341,"4765","",0,"","","",1,0,0,[],""],["frenk_t2-n4766",6,"La mujer la comparo\ncon la veleta:\nal menor vientecito\nda media vuelta.",105,2,-1,123,"Estrofa suelta",6,4,"ea",-1,0,-1,0,341,341,"4766","",0,"","","",1,0,0,[],""],["frenk_t2-n4767",6,"De las mujeres, muy pocas\nson las que saben amar:\nde continuo son muy locas,\ny empiezan a galopar\ncomo el caballo de copas.",106,2,4,123,"El querreque",7,5,"oa",-1,0,-1,0,341,341,"4767","",0,"","","",1,0,0,[],""],["frenk_t2-n4768",6,"Del cielo cayó un clavel\ndeshojando tijeras;\nmujeres habían de ser:\nno locas y mancomeras.",110,2,10,123,"Zapateado",0,4,"ea",103,0,-1,0,341,341,"4768","",0,"","","",1,0,0,[],""],["frenk_t2-n4769",6,"Aquí está un peso dispuesto,\npara poderlo apostar:\nque no hay mujer en el mundo\nque no sepa mancornar.",105,2,-1,123,"El gallerito",0,4,"a",21,0,-1,0,341,341,"4769","",0,"","","",1,0,0,[],""],["frenk_t2-n4770",6,"De estas mujeres de ahora\ntodos tenemos que hablar;\nsea pobre o sea señora,\nbien se pueden rabiatar,\nporque todas tienen cola.",105,2,-1,123,"Estrofa suelta",7,5,"oa",-1,0,-1,0,341,341,"4770","",0,"","","",1,0,0,[],""],["frenk_t2-n4771",6,"Pero también hay mujeres\nque presumen de recato;\nsin faltar a sus deberes,\nsaben pasar bien el rato.",107,2,11,123,"La calandria",1,4,"ao",19,0,-1,0,341,341,"4771","",0,"","","",1,0,0,[],""],["frenk_t2-n4772",6,"Vuela cual la mariposa\nrevoloteando en la flama;\naunque sea muy cuidadosa,\nal fin se quema en la llama,\nporque es débil cual la rosa.",112,2,6,123,"Estrofa suelta",7,5,"oa",63,0,-1,0,341,341,"4772","",0,"","","",1,0,0,[],""],["frenk_t2-n4773",6,"Las maripositas buenas\nse cuentan con una mano;\nlas que tienen un botón\nno se van con otro extraño.",105,2,-1,123,"Uy, uy, mariposa",0,4,"ao",-1,0,-1,0,341,341,"4773","",0,"","","",1,0,0,[],""],["frenk_t2-n4775",6,"La piedra que rueda y rueda\nno sirve para cimiento;\nla mujer que quiere a dos\n¿cuál será su pensamiento?",114,2,17,123,"El huizache",0,4,"eo",94,0,-1,0,342,342,"4775","",0,"","","",1,0,0,[],""],["frenk_t2-n4776",6,"La mujer que quiere a dos\nes porque gusto le sobra:\nuno lo tiene en las sombras,\ny otro a las claras lo mira,\ny en su casa tristemente\npor el ausente suspira.",105,2,-1,123,"Jugando contras",9,6,"ia",372,0,-1,0,342,342,"4776","",0,"","","",12,0,0,[],""],["frenk_t2-n4777",6,"Cuando la mujer es bonita\nsiempre tiene su mal modo:\nsi quieren dejar la pita,\nse largan al cerro gordo;\ndejan el agua clarita\npa revolcarse en el lodo.",108,2,8,123,"La morena",9,6,"oo",-1,0,-1,0,342,342,"4777","",0,"","","",1,0,0,[],""],["frenk_t2-n4778",6,"El diablo la mujer es\nde quien el hombre va en pos,\npues cuando nos engaña a dos\nes porque entretiene a tres.\n“No te amo por interés,\nte dirá, que a ti te quiero,\ntú eres mi delicia”, pero\nno te fíes de la suerte,\nporque la mujer más fuerte\nal fin se rinde al dinero.",105,2,-1,123,"Versos de payaso",18,10,"eo",38,0,-1,0,342,342,"4778","",0,"","","",1,0,0,[],""],["frenk_t2-n4779",6,"Para mentir, las mujeres\nnos enredan bien los pies;\ncuando no pasean con uno,\npasean con otros tres.",105,2,-1,123,"Las chivarras",0,4,"e",218,0,-1,0,342,342,"4779","",0,"","","",1,0,0,[],""],["frenk_t2-n4780",6,"Las muchachas de la playa\nson como la yerbabuena:\nno se consuelan con uno,\nsino con media docena.",105,2,-1,123,"Soy de Zacatula; El novillo despuntado; Estrofa suelta",0,4,"ea",59,0,-1,0,342,342,"4780","",0,"","","",1,0,0,[],""],["frenk_t2-n4782",6,"La mujer que tuvo amores\nno sirve para casada,\nporque dicen los doctores\nque de su vida pasada\nle quedan los borradores.",105,2,-1,123,"Estrofa suelta, El querreque",7,5,"oe",5,0,-1,0,343,343,"4782","",0,"","","",2,0,0,[],""],["frenk_t2-n4784",6,"Corazón, abre las alas\ny dime por quién suspiras:\nsi suspiras por casadas,\nesas son balas perdidas.",108,2,8,123,"Estrofa suelta",0,4,"ia",-1,0,-1,0,343,343,"4784","",0,"","","",1,0,0,[],""],["frenk_t2-n4785c",6,"Ingratas, crueles fortunas,\nhe llegado a comprender\nque al nopal lo van a ver\nsólo cuando tiene tunas.",105,2,-1,123,"Estrofa suelta",11,4,"ua",289,0,-1,0,343,343,"4785c","",0,"","","",2,0,0,[],""],["frenk_t2-n4785d",6,"Ingratas, crueles fortunas,\nhe llegado a comprender\nque al nopal lo van a ver\nsólo cuando tiene tunas:\nmenos ni se acuerdan de él.",105,2,-1,123,"El jarabe tapatío; El bejuquito; Desde que te vi venir; Estrofa suelta",7,5,"e",-1,0,-1,0,343,343,"4785d","",0,"","","",2,0,0,[],""],["frenk_t2-n4787",6,"De la situación actual\nninguna mujer, ninguna,\nama no más por amar,\nsin saber con qué fortuna\nvan a formar el hogar.",105,2,-1,123,"Ninguna mujer, ninguna",7,5,"a",21,0,-1,0,344,344,"4787","",0,"","","",1,0,0,[],""],["frenk_t2-n4788",6,"Rompe el fiel de la balanza\nsi el amor es verdadero,\npero si el amor no pesa,\nhay que ponerle dinero.",105,2,-1,123,"La balanza",0,4,"eo",38,0,-1,0,344,344,"4788","",0,"","","",1,0,0,[],""],["frenk_t2-n4789",6,"Me dijo un catrín del rancho\nque lo amara con esmero:\nal venadito con sancho,\ny a la mujer con dinero.",105,2,-1,123,"La lima",1,4,"eo",38,0,-1,0,344,344,"4789","",0,"","","",1,0,0,[],""],["frenk_t2-n4790",6,"La carga no le hace al burro,\nlo que le hace son los palos;\nlas hembras no ven lo guapo,\nlo que ven son los centavos.",105,2,-1,123,"Pancho Nopales",0,4,"ao",-1,0,-1,0,344,344,"4790","",0,"","","",1,0,0,[],""],["frenk_t2-n4791",6,"Me fui para Guadalupe,\na traer amores formales,\ny por el camino supe\nque ya todas son iguales,\nque no hay una que no le gusten\nlos besos a cuatro reales.",113,2,2,123,"La Malagueña",9,6,"ae",26,0,-1,0,344,344,"4791","",0,"","","",1,0,0,[],""],["frenk_t2-n4793",6,"El que ande de enamorado,\nparándose en las esquinas,\nque se meta al gallinero\ny les cante a las gallinas,\npues si no tienen dinero,\nque no enamore catrinas.",105,2,-1,123,"El conejo",9,6,"ia",243,0,-1,0,344,344,"4793","",0,"","","",1,0,0,[],""],["frenk_t2-n4794",6,"Levántate de mañana\ny échale agua a tu ciprés;\nno le sacudas la rama,\nporque se le cae la nuez,\no te vaya a salir vana\ncomo el amor de interés.",121,2,26,123,"La azucena",9,6,"e",218,0,-1,0,344,344,"4794","",0,"","","",2,0,0,[],""],["frenk_t2-n4796",6,"No hay una vida tan triste\ncomo la del forastero:\ntodas de él piensan reírse\ncuando lo ven sin dinero.",115,2,3,123,"Soy forastero",0,4,"eo",38,0,-1,0,345,345,"4796","",0,"","","",1,0,0,[],""],["frenk_t2-n4797",6,"El hombre sin dinero\nno vale nada en la vida;\nla mujer que es consentida\nvive siempre en su agujero.",105,2,-1,123,"El sargento",11,4,"eo",38,0,-1,0,345,345,"4797","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4798",6,"El pobre con su pobreza\ndondequiera es despreciado;\nel rico con su riqueza\ndondequiera es apreciado\nhasta la mujer honrada.",112,2,6,123,"La azucena",7,5,"aa",-1,0,-1,0,345,345,"4798","",0,"","","",1,0,0,[],""],["frenk_t2-n4799",6,"Llega a salirle el bozo,\nque es la edad de las pasiones,\ny sólo quien tiene doblones\nes fino, amable y buen mozo;\ny aunque el pobre sea juicioso,\nsiempre el pobre desmerece.",105,2,-1,123,"Estrofa suelta",9,6,"ee",-1,0,-1,0,345,345,"4799","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4800",6,"Nunca puede el hombre pobre\npretender mujer bonita,\npues porque de repentito\nviene el rico y se la quita,\ny aunque razón le sobre.",112,2,6,123,"La pasión",7,5,"oe",410,0,-1,0,345,345,"4800","",0,"","","",1,0,0,[],""],["frenk_t2-n4801",6,"El amor del hombre pobre\nes amor inoportuno;\nes como la leña verde:\nllena la cocina de humo.",108,2,8,123,"Estrofa suelta",0,4,"uo",-1,0,-1,0,345,345,"4801","",0,"","","",6,0,0,[],""],["frenk_t2-n4802",6,"La dicha nunca es cabal\ncuando el pobre se enamora;\nese es su sino fatal:\nsufrir por lo que adora.",105,2,-1,123,"Mala mujer",1,4,"oa",107,0,-1,0,345,345,"4802","",0,"","","",1,0,0,[],""],["frenk_t2-n4803",6,"Y aun de buenos procederes\nlo desprecian las mujeres,\ny de ellas todo apetece,\nporque en cualquier ocasión\nsiempre el pobre desmerece.",105,2,-1,123,"Estrofa suelta",7,5,"ee",64,0,-1,0,345,345,"4803","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n4806a",6,"Una rosa de Castilla\nprende y se vuelve a secar;\nno te cases, vida mía,\nno te dejes engañar.",105,2,-1,124,"Estrofa suelta",0,4,"a",21,0,-1,0,347,347,"4806a","",0,"","","",3,0,0,[],""],["frenk_t2-n4806b",6,"Una rosa de Castilla\nprende y se vuelve a secar.\n—No te cases todavía,\nno te dejes engañar;\n—Yo no soy tan armadillo\npara echarme yo a rodar.",105,2,-1,124,"El venadito",9,6,"a",21,0,-1,0,347,347,"4806b","",0,"","","",3,0,0,[],""],["frenk_t2-n4807",6,"Soy gavilán que al volar\nsiempre vuela contra el viento;\nno te vayas a enredar,\nprocura volar con tiento.",107,2,11,124,"Santanón",1,4,"eo",94,0,-1,0,347,347,"4807","",0,"","","",1,0,0,[],""],["frenk_t2-n4808",6,"Frijolito, frijolito,\nfrijolito enredador,\nno te vayas a enredar\ncomo se enredó mi amor.",105,2,-1,124,"El frijolito; El bejuquito; El novillo despuntado",0,4,"o",72,0,-1,0,347,347,"4808","",0,"","","",2,0,0,[],""],["frenk_t2-n4809",6,"Yo les digo a mis amigos:\n“No se dejen enredar,\nporque tarde que temprano\ntienen que pagarles mal.”",105,2,-1,124,"Estrofa suelta",0,4,"a",-1,0,-1,0,347,347,"4809","",0,"","","",3,0,0,[],""],["frenk_t2-n4810",6,"No se dejen enredar\nde una bella viborita:\nno se vayan a quedar\ndesnudos en la lomita.",115,2,3,124,"La viborita",1,4,"ia",50,0,-1,0,347,347,"4810","",0,"","","",1,0,0,[],""],["frenk_t2-n4811",6,"En esta vida prestada\nhay que tener buen cuidado:\nuna víbora arrastrada\na mí me dejó encuerado.",115,2,3,124,"La viborita",1,4,"ao",14,0,-1,0,347,347,"4811","",0,"","","",2,0,0,[],""],["frenk_t2-n4813",6,"Ya me voy, ya me despido,\nanden con mucho cuidado,\nque esas de la frente china\nson las del ganado bravo.",107,2,11,124,"La nopalera",0,4,"ao",-1,0,-1,0,348,348,"4813","",0,"","","",9,0,0,[],""],["frenk_t2-n4814",6,"De las rancheritas\nardientes o frías,\ncuídate, compadre,\ntoditos los días.",115,2,3,124,"Las dos Marías",0,4,"ia",214,0,-1,0,348,348,"4814","",0,"","","",1,0,0,[],""],["frenk_t2-n4815a",6,"No hay que ser adoración\nde las que se andan sonriendo,\nporque se llega la ocasión\nque al hombre lo están engriendo,\ninflado y por dentro ardiendo.",108,2,8,124,"Estrofa suelta",7,5,"eo",52,0,-1,0,348,348,"4815a","",0,"","","",1,0,0,[],""],["frenk_t2-n4816",6,"Yo les digo a mis amigos:\n“No se dejen engañar\nde muías de siete cuartas\nque se zafan del bozal.”",105,2,-1,124,"La muía de siete cuartas",0,4,"a",-1,0,-1,0,348,348,"4816","",0,"","","",3,0,0,[],""],["frenk_t2-n4817",6,"Nunca le creas a un hombre\ncuando lo veas llorar,\nque es como el cocodrilo,\nque llora para engañar.",129,2,9,124,"Estrofa suelta",0,4,"a",21,0,-1,0,348,348,"4817","",0,"","","",1,0,0,[],""],["frenk_t2-n4818",6,"Deja que el viento te guíe tu barca,\npero no des tu corazón a un hombre,\nporque es más de fiar las olas\nque la constancia de un hombre.",130,2,21,124,"Estrofa suelta",3,4,"oe",-1,0,-1,0,348,348,"4818","",0,"","","",1,0,0,[],""],["frenk_t2-n4819",6,"Marieta, no seas coqueta,\nporque los hombres son muy malos;\nprometen muchos regalos,\ny lo que dan son puros palos.",105,2,-1,124,"Marieta",0,4,"ao",569,0,-1,0,348,348,"4819","",0,"","","",2,0,0,[],""],["frenk_t2-n4820",6,"Un sapito generoso\nme dijo cabe una fuente:\n“Fíate de toda la gente,\nmas de las mujeres no.”",107,2,11,124,"Estrofa suelta",5,4,"o",-1,0,-1,0,349,349,"4820","",0,"","","",1,0,0,[],""],["frenk_t2-n4821",6,"Cupido a mí me regaña\nporque a las mujeres quiero;\nme dice: “Deja esa maña,\nprocura tener dinero.”",108,2,8,124,"Estrofa suelta",1,4,"eo",38,0,-1,0,349,349,"4821","",0,"","","",1,0,0,[],""],["frenk_t2-n4822",6,"Cuando veas a una mujer\nno le des el corazón,\nporque puede suceder\nque te juege una traición;\nporque lo saben hacer,\nvalidas de la ocasión.",113,2,2,124,"La huazanga",9,6,"o",31,0,-1,0,349,349,"4822","",0,"","","",1,0,0,[],""],["frenk_t2-n4823",6,"Cupido, antes de morir,\nme dejó escrito en papeles\nque si no quería sufrir\nprisiones entre paredes,\nque me fuera yo a vivir\ndonde no hubiera mujeres.",105,2,-1,124,"El Cupido",9,6,"ee",-1,0,-1,0,349,349,"4823","",0,"","","",1,0,0,[],""],["frenk_t2-n4824",6,"El tejón ya se cansó\nde salir a las laderas.\nNo se metan con casadas,\nni con viudas, ni solteras:\nvale más vivir sólito\nque con viejas argüenderas.",105,2,-1,124,"El nuevo tejón",9,6,"ea",103,0,-1,0,349,349,"4824","",0,"","","",1,0,0,[],""],["frenk_t2-n4825",6,"Les digo yo a mis amigos:\n“No se crean de las mujeres,\nque en tratos de las mujeres\nnadie se puede fijar.”",110,2,10,124,"La chata morena",5,4,"a",-1,0,-1,0,349,349,"4825","",0,"","","",1,0,0,[],""],["frenk_t2-n4826",6,"No hay que creer en las mujeres,\nporque las mujeres son\ncucharas de todas mesas,\ny validas de la ocasión.",108,2,8,124,"Estrofa suelta",0,4,"o",31,0,-1,0,349,349,"4826","",0,"","","",1,0,0,[],""],["frenk_t2-n4827",6,"Un gorrión entre claveles\nme dijo en cierta ocasión:\n“No te creas de las mujeres,\nporque las mujeres son\nredomas de todas mieles\ny amantes de la traición.”",115,2,3,124,"Estrofa suelta, La sandía",9,6,"o",31,0,-1,0,349,349,"4827","",0,"","","",1,0,0,[],""],["frenk_t2-n4830",6,"El cuervo es un animal\nque hay que tenerle cuidado;\ncon las mujeres del mal\nno se puede ser honrado,\npues casi toditas ellas\ntienen su gallo tapado.",111,2,1,124,"El cuervo",9,6,"ao",14,0,-1,0,350,350,"4830","",0,"","","",1,0,0,[],""],["frenk_t2-n4831",6,"Muchachos, tengan recato,\nno echen a perder su vida:\nla mujer es un retrato\nque despinta con la vida;\ncaminan como los gatos,\ncon las uñas escondidas.",105,2,-1,124,"El pájaro carpintero’",9,6,"ia",-1,0,-1,0,350,350,"4831","",0,"","","",1,0,0,[],""],["frenk_t2-n4832",6,"Me dio un consejo Cupido\nantes que fuera [ejrmitaño:\n“Si te vieres abatido,\ndéjalo de ese tamaño,\nque la mujer siempre ha sido\ndel hombre carta de engaño.”",105,2,-1,124,"Estrofa suelta, El Cupido",9,6,"ao",40,0,-1,0,350,350,"4832","",0,"","","",1,0,0,[],""],["frenk_t2-n4834",6,"Las mujeres, quererlas\ny no firmarlas contrato,\npa poder dormir con eüas\ny darles con el plato;\ny también toditas ellas\ntambién no más quieren el rato.",112,2,6,124,"La pasión",9,6,"ao",19,0,-1,0,350,350,"4834","",0,"","","",1,0,0,[],""],["frenk_t2-n4835",6,"A las mujeres, quererlas\ny no darles de comer,\ndarles palos como burras\ny agua caliente a beber.",108,2,8,124,"Estrofa suelta",0,4,"e",20,0,-1,0,350,350,"4835","",0,"","","",7,0,0,[],""],["frenk_t2-n4836",6,"Todo aquel hombre que quiera a una ingra\ncomo la quiera la debe tratar:\ncomo las hojas que el viento arrebata,\ndonde las coge las vuelve a aventar.",107,2,11,124,"La cautela",3,4,"a",21,0,-1,0,350,350,"4836","",0,"","","",1,0,0,[],""],["frenk_t2-n4837",6,"Si tu mujer es celosa,\ndale a beber apazote,\ny si además es chismosa,\npues pégale con garrote.",122,2,13,124,"Estrofa suelta",1,4,"oe",292,0,-1,0,351,351,"4837","",0,"","","",2,0,0,[],""],["frenk_t2-n4838",6,"Dicen que el aguardiente\nsólo en botella;\na la mujer celosa,\npalo con ella.",115,2,3,124,"La peineta**",6,4,"ea",6,0,-1,0,351,351,"4838","",0,"","","",1,0,0,[],""],["frenk_t2-n4839",6,"Entre cortinas blancas\ny azules rejas,\nestaban dos amantes (cielito lindo)\ndándose quejas;\ny se decían\nque sólo con la muerte (cielito lindo)\nse olvidarían.",105,2,-1,125,"Cielito lindo; Estrofa suelta",4,7,"ia",500,0,-1,0,355,355,"4839","",0,"","","",1,0,0,[],""],["frenk_t2-n4841",6,"El indio le dijo a la india\nque en la presa la esperaba,\nque llevara su peineta\npara que allí lo [peinara].",105,2,-1,125,"La indita",0,4,"aa",-1,0,-1,0,355,355,"4841","",0,"","","",1,0,0,[],""],["frenk_t2-n4842",6,"Yo vide un naturalito,\ny una indita lo paró\nen un lugar muy bonito,\nque de amores lo trató.",105,2,-1,125,"La indita",1,4,"o",2,0,-1,0,355,355,"4842","",0,"","","",1,0,0,[],""],["frenk_t2-n4844",6,"Mariquita está dormida,\ny su amor la está arrullando,\ny en su cabecera tiene\ndos jilguerillos cantando.",105,2,-1,125,"Mariquita; Estrofa suelta",0,4,"ao",33,0,-1,0,356,356,"4844","",0,"","","",1,0,0,[],""],["frenk_t2-n4845",6,"Estaba el Maracumbé\ntomándose una copita,\npor el amor que le tiene\na una mujer bonita.",114,2,17,125,"El maracumbé",0,4,"ia",50,0,-1,0,356,356,"4845","",0,"","","",1,0,0,[],""],["frenk_t2-n4846",6,"Y su mama le decía:\n—Hija, anda al agua.\n—Mamacita, yo no voy,\nese hombre me habla.",105,2,-1,125,"La chinita",6,4,"aa",-1,0,-1,0,356,356,"4846","",0,"","","",3,0,0,[],""],["frenk_t2-n4848",6,"Yo vi una garza morena\nmuy altanera volar,\ny después la vi bajar\nmuy mansita a su ribera.",117,2,5,125,"Estrofa suelta",5,4,"ea",-1,0,-1,0,356,356,"4848","",0,"","","",1,0,0,[],""],["frenk_t2-n4849",6,"Debajo de un jericón\nse paseaba una bonita,\ncon su vestido de seda,\ncon sus mangas de jaretita.",114,2,17,125,"El gato",0,4,"ia",50,0,-1,0,356,356,"4849","",0,"","","",1,0,0,[],""],["frenk_t2-n4850",6,"De la Sierra Morena (cielito lindo)\nvienen bajando\nun par de ojitos negros (cielito lindo)\nde contrabando.",106,2,4,125,"Cielito lindo; El pájaro cú; Pregón de Ja nieve; La zamba",3,4,"ao",33,0,-1,0,356,356,"4850","",0,"","","",1,0,0,[],""],["frenk_t2-n4851",6,"Viniendo yo de La Mesa,\nme pasé pa la loma;\nme encontré con la Cereza\nplaticando con Bartola\ny deshojando muy aprisa\nuna rosa de amapola.",113,2,2,125,"Estrofa suelta",9,6,"oa",321,0,-1,0,357,357,"4851","",0,"","","",1,0,0,[],""],["frenk_t2-n4853",6,"Estaba María Chuchena\nsentada en Villa del Mar\ny arrecostada en la arena\nporque se quería bañar.",106,2,4,125,"María Chuchena",1,4,"a",21,0,-1,0,357,357,"4853","",0,"","","",3,0,0,[],""],["frenk_t2-n4858a",6,"A Cecilia sus hermanos\nno la dejaban casar;\nella les decía: “Tiranos,\nlo que no me puedan dar\nno me lo quiten, hermanos.”",113,2,2,126,"La Cecilia",7,5,"ao",318,0,-1,0,359,359,"4858a","",0,"","","",3,0,0,[],""],["frenk_t2-n4859",6,"A Cecilia sus hermanos\nno querían que se casara;\nles dijo: “No sean tiranos,\npues yo ya estoy separada,\ncon el pañuelo en las manos,\nechándome aire en la cara.”",113,2,2,126,"La Cecilia",9,6,"aa",-1,0,-1,0,359,359,"4859","",0,"","","",3,0,0,[],""],["frenk_t2-n4860",6,"En el jardín del amor (¡ay, Petrona!)\nse para un pájaro a ver;\ndespués de picar la flor (¡ay, Petrona!)\nno quiso permanecer.",108,2,8,126,"Petrona; Estrofa suelta",3,4,"e",20,0,-1,0,359,359,"4860","",0,"","","",1,0,0,[],""],["frenk_t2-n4861",6,"La callejera lloraba,\nlloraba de sentimiento,\nporque no podía encontrar,\ndinero pa el casamiento.",105,2,-1,126,"La callejera",0,4,"eo",94,0,-1,0,359,359,"4861","",0,"","","",1,0,0,[],""],["frenk_t2-n4862",6,"En el mar está una palma,\ncon sus ramas hasta el suelo,\ndonde se van a llorar\nlos que no encuentran consuelo.",105,2,-1,126,"La palma; El palmero; Estrofa suelta",0,4,"eo",10,0,-1,0,359,359,"4862","",0,"","","",1,0,0,[],""],["frenk_t2-n4864",6,"En una mansión oscura,\ndonde el silencio reinaba,\noí una voz con ternura:\nuna mujer se quejaba,\nllorando su desventura.",105,2,-1,126,"El perdiguero",7,5,"ua",17,0,-1,0,360,360,"4864","",0,"","","",2,0,0,[],""],["frenk_t2-n4865",6,"Y la hermosa barquillera\nno cesaba de llorar,\nporque ser tan libre quisiera\ncomo las olas del mar.",105,2,-1,126,"La barquillera",1,4,"a",21,0,-1,0,360,360,"4865","",0,"","","",1,0,0,[],""],["frenk_t2-n4866",6,"Una recién casada\nno cesa de llorar,\nde verse enajenada\ny sin remedio hallar.",112,2,6,126,"La recién casada",1,4,"a",21,0,-1,0,360,360,"4866","",0,"","","",4,0,0,[],""],["frenk_t2-n4867",6,"El lucero desde el cielo\nmejor se puso a llorar:\nviviendo entre tanta estrella,\nninguna lo supo amar.",123,2,20,126,"La rubia y la morena",0,4,"a",21,0,-1,0,360,360,"4867","",0,"","","",1,0,0,[],""],["frenk_t2-n4868",6,"Yo vide llorar a un hombre\npreso por una mujer,\ncon unos pesados grillos,\nque no se podía mover.",105,2,-1,126,"Estrofa suelta",0,4,"e",20,0,-1,0,360,360,"4868","",0,"","","",1,0,0,[],""],["frenk_t2-n4869",6,"Yo vide un carro en Argel,\nguarnecido de oro y perlas,\ny también vi dentro de él\nque llevan al dios Cupido\npreso por una mujer.",122,2,13,126,"Estrofa suelta",7,5,"e",-1,0,-1,0,360,360,"4869","",0,"","","",1,0,0,[],""],["frenk_t2-n4870",6,"A Cupido lo prendieron\nporque adoraba en su encanto,\ny de grillos le pusieron\nde las olivas del campo,\nque hasta mis ojos lo vieron.",105,2,-1,126,"El Cupido",7,5,"eo",105,0,-1,0,360,360,"4870","",0,"","","",1,0,0,[],""],["frenk_t2-n4871",6,"Ya se va el ausente,\nya se va llorando,\nporque su chinita\nlo estaba engañando",105,2,-1,126,"El ausente",0,4,"ao",33,0,-1,0,361,361,"4871","",0,"","","",4,0,0,[],""],["frenk_t2-n4873",6,"Ya se va el ausente,\nya se va y se va;\npobre del ausente,\n¿cuándo volverá?",107,2,11,126,"El ausente",1,4,"a",9,0,-1,0,361,361,"4873","",0,"","","",4,0,0,[],""],["frenk_t2-n4874",6,"Tengo que quererla a usted,\ntan solamente por eso:\nque será más hermosa\nque chile verde con queso.",108,2,8,127,"Estrofa suelta",0,4,"eo",48,0,-1,0,367,367,"4874","",0,"","","",1,0,0,[],""],["frenk_t2-n4875",6,"Blanca flor de garambullo,\nhermosa flor de pitaya\nte escribo de Tacubaya:\npunto, punto, raya, raya.",107,2,11,127,"Estrofa suelta",0,4,"aa",404,0,-1,0,367,367,"4875","",0,"","","",1,0,0,[],""],["frenk_t2-n4876",6,"Blanca flor de chapopote,\nque vives en Tacubaya,\n¿quieres que te vaya a ver?\n¡Vaya, vaya, vaya, vaya!",107,2,11,127,"Estrofa suelta",0,4,"aa",404,0,-1,0,367,367,"4876","",0,"","","",1,0,0,[],""],["frenk_t2-n4877",6,"A las gallinas de mi casa\nlas persiguen los corucos,\ny a ti por tus lindos ojos\nte persiguen los pachucos.",129,2,9,127,"Estrofa suelta",0,4,"uo",570,0,-1,0,367,367,"4877","",0,"","","",1,0,0,[],""],["frenk_t2-n4878",6,"Asco les tengo a los pesos\ny también a los tostones,\npero más asco a tus ojos,\nque son tan sinvergüenzones.",105,2,-1,127,"Estrofa suelta",0,4,"oe",34,0,-1,0,367,367,"4878","",0,"","","",2,0,0,[],""],["frenk_t2-n4879",6,"Cuando estaba yo chiquito\nme gustaban tus tortillas;\nahora que estoy grandecito\nme gustan tus pantorrillas.",105,2,-1,127,"Que comienzo, que comienzo; La Sanmarqueña",1,4,"ia",294,0,-1,0,367,367,"4879","",0,"","","",1,0,0,[],""],["frenk_t2-n4880",6,"¡Mira qué piernas tan gordas!,\n¿me las podrías regalar?\nParecen lechugas verdes\nacabadas de cortar.",110,2,10,127,"La Jesusita",0,4,"a",21,0,-1,0,367,367,"4880","",0,"","","",1,0,0,[],""],["frenk_t2-n4882",6,"Quisiera pegar un brinco\npa llegar a tu ventana;\nuno, dos, tres, cuatro, cinco,\nya me voy, hasta mañana.",107,2,11,127,"Estrofa suelta",1,4,"aa",4,0,-1,0,368,368,"4882","",0,"","","",1,0,0,[],""],["frenk_t2-n4883",6,"Me falta un ojo para mirarte,\nsólo dos dedos tengo en un pie;\nun ojo basta para mirarte,\nal fin los dedos no se me ven.",105,2,-1,127,"Me falta un ojo",3,4,"e",-1,0,-1,0,368,368,"4883","",0,"","","",1,0,0,[],""],["frenk_t2-n4884",6,"Me subí en un alto pino,\npor ver si te devisaba;\ncomo no soy tan ladino,\ncon paciencia yo esperaba,\ny con tanto remolino\nhasta se me cae la baba.",107,2,11,127,"El venadito’",9,6,"aa",28,0,-1,0,368,368,"4884","",0,"","","",3,0,0,[],""],["frenk_t2-n4886",6,"“Yes, yes”, en inglés,\n“oui, oui”, en francés,\n“piano, piano”, en italiano\ny “yo te quiero”, en castellano.",107,2,11,127,"Estrofa suelta",3,4,"ao",81,0,-1,0,368,368,"4886","",0,"","","",1,0,0,[],""],["frenk_t2-n4887",6,"Eres, vida mía, la bamba,\na quien amo con empeño,\npero allí en mi pecho clamo\nque adonde me rinde el sueño\nla calle cojo de cama\ny de cabecera un leño.",106,2,4,127,"El pájaro carpintero",9,6,"eo",138,0,-1,0,368,368,"4887","",0,"","","",1,0,0,[],""],["frenk_t2-n4888",6,"A ti te quiero,\npor ti me muero,\npor ti estoy flaca\ncomo un plumero.",107,2,11,127,"Estrofa suelta",6,4,"eo",38,0,-1,0,369,369,"4888","",0,"","","",1,0,0,[],""],["frenk_t2-n4889",6,"Por ti no tengo camisa,\npor ti no tengo capote,\npor ti no he cantado misa,\npor ti no soy sacerdote.",105,2,-1,127,"Estrofa suelta",1,4,"oe",292,0,-1,0,369,369,"4889","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],""],["frenk_t2-n4890",6,"No duermo por adorarte,\ny porque verte me despero,\nque te estimo hasta en el sueño,\npero cuando la rana críe pelo.",108,2,8,127,"Estrofa suelta",3,4,"eo",-1,0,-1,0,369,369,"4890","",0,"","","",2,0,0,[],""],["frenk_t2-n4891",6,"Cuando yo me muera\ntú irás a mi tumba,\ny luego yo salgo\nbailando la rumba.",130,2,21,127,"Estrofa suelta",0,4,"ua",514,0,-1,0,369,369,"4891","",0,"","","",3,0,0,[],""],["frenk_t2-n4892",6,"Me ando muriendo, mi alma:\neso es tan cierto\ncomo sacarse un ojo\ny quedarse tuerto.",105,2,-1,127,"Estrofa suelta",6,4,"eo",88,0,-1,0,369,369,"4892","",0,"","","",1,0,0,[],""],["frenk_t2-n4893",6,"Para cuando te mueras (bien de mi vida)\ndigo y redigo\nque si la tumba es grande (cielito lindo),\nme voy contigo.",108,2,8,127,"El pájaro cú",3,4,"io",106,0,-1,0,369,369,"4893","",0,"","","",1,0,0,[],""],["frenk_t2-n4894",6,"En el marco de tu casa\nenterré mis ilusiones;\nsi no las sacas pronto,\nse las comerán los ratones.",130,2,21,127,"Estrofa suelta",0,4,"oe",34,0,-1,0,369,369,"4894","",0,"","","",1,0,0,[],""],["frenk_t2-n4895",6,"Ya que me diste un besito,\nbésame toda la tarde,\nporque por el mismo precio\nme van a romper la — boca.",107,2,11,127,"La Sanmarqueña",5,4,"oa",-1,0,-1,0,369,369,"4895","",0,"","","",1,0,0,[],""],["frenk_t2-n4896",6,"Dame lo que yo te pido,\nque no te pido la vida:\nde la nariz para abajo,\nde la barbilla pa arriba.",107,2,11,127,"La Sanmarqueña",0,4,"ia",-1,0,-1,0,369,369,"4896","",0,"","","",3,0,0,[],""],["frenk_t2-n4898",6,"Ya ven, deja de moler,\nya no muelas nixtamal;\nvamos a Estados Unidos,\nque allá iremos a gozar.",113,2,2,127,"De las tres que vienen áhi",0,4,"a",-1,0,-1,0,370,370,"4898","",0,"","","",1,0,0,[],""],["frenk_t2-n4899",6,"Y hasta el martes, vida mía,\nporque el miércoles nos vamos;\naprevén tu sabanita,\nporque ¿con qué nos tapamos?",108,2,8,127,"La indita",0,4,"ao",116,0,-1,0,370,370,"4899","",0,"","","",1,0,0,[],""],["frenk_t2-n4900",6,"Ahora que estoy más fregado\nme ha salido una chambita;\ntú quieres que yo te lleve:\n¿con qué te tapas si llueve?",105,2,-1,127,"La burra elotera",5,4,"ee",474,0,-1,0,370,370,"4900","",0,"","","",1,0,0,[],""],["frenk_t2-n4901",6,"Yo te llevara conmigo,\n¿pero con qué, Mariquita?\nSólo que vayas andando\ny en ratitos cargadita.",105,2,-1,127,"María, María",0,4,"ia",50,0,-1,0,370,370,"4901","",0,"","","",1,0,0,[],""],["frenk_t2-n4902",6,"Verá usted lo que es ternura,\njunto a este calabazate;\nya parece que la veo\nagachada en su metate.",105,2,-1,127,"Estrofa suelta",0,4,"ae",384,0,-1,0,370,370,"4902","",0,"","","",1,0,0,[],""],["frenk_t2-n4903",6,"Si es que me amas con verdad,\ncomo te escucho decir,\nno me lleves a vivir\nen casa de vecindad.",105,2,-1,127,"Estrofa suelta",11,4,"a",16,0,-1,0,370,370,"4903","",0,"","","",1,0,0,[],""],["frenk_t2-n4905",6,"Apenas amaneció\ny cantaron los gorriones\ncuando tu rostro asomó,\nbuscándome entre los peones;\nasí tu alma me evitó\nde muy buenos descolones.",105,2,-1,127,"En una hermosa mañana",9,6,"oe",34,0,-1,0,371,371,"4905","",0,"","","",1,0,0,[],""],["frenk_t2-n4906",6,"Yo soy la carnita,\ntú eres el arroz:\n¡qué buena sopita\nharemos los dos!",105,2,-1,127,"Estrofa suelta",1,4,"o",87,0,-1,0,371,371,"4906","",0,"","","",1,0,0,[],""],["frenk_t2-n4907",6,"Hablé con tu papacito\ny le dije lo que había,\ny tu hermano, el más chiquito,\ncon el gusto que decía:\n“Ya tengo mi cuñadito,\nque es lo que yo quería.”",105,2,-1,127,"El siquisirí",9,6,"ia",0,0,-1,0,371,371,"4907","",0,"","","",1,0,0,[],""],["frenk_t2-n4908",6,"Cuando paso por tu casa\nvoy sonando mi dinero,\npara que diga tu mama:\n“Áhi va el príncipe heredero.”",107,2,11,127,"El palmero; El príncipe heredero; Estrofa suelta",0,4,"eo",38,0,-1,0,371,371,"4908","",0,"","","",7,0,0,[],""],["frenk_t2-n4909",6,"Cuando paso por tu casa\nvoy muy serio y no me río,\npa ver si dice tu mama:\n“Se va riendo por el frío.”",105,2,-1,127,"El príncipe heredero",0,4,"io",3,0,-1,0,371,371,"4909","",0,"","","",7,0,0,[],""],["frenk_t2-n4910",6,"Cuando pasé por tu casa\ntiré un limón a rodar:\nno vaya a creer tu mamacita\nque te pasé a enamorar.",122,2,13,127,"Estrofa suelta",3,4,"a",21,0,-1,0,371,371,"4910","",0,"","","",6,0,0,[],""],["frenk_t2-n4911a",6,"Cuando paso por tu casa (Llorona)\ncompro pan y voy comiendo,\npa que no diga tu madre (Llorona)\nque de hambre me estoy muriendo.",107,2,11,127,"La Llorona; El príncipe heredero",3,4,"eo",52,0,-1,0,371,371,"4911a","",0,"","","",1,0,0,[],""],["frenk_t2-n4913",6,"Yo no te culpo ni riño:\nla verdad es que te quiero;\npero si te hago algún guiño,\ntú papá me ve primero.\nEl que ha de nacer lampiño\naunque el padre sea barbero.",105,2,-1,127,"El deseoso",9,6,"eo",38,0,-1,0,372,372,"4913","",0,"","","",1,0,0,[],""],["frenk_t2-n4914",6,"—Señora, yo ya me voy,\nno vaya a venir su esposo.\n—Quítese de aquí, miedoso,\n¿qué nos ha de suceder?\nSan Caralampio es buen santo,\nnos ha de favorecer.",114,2,17,127,"Las barrancas",9,6,"e",20,0,-1,0,372,372,"4914","",0,"","","",1,0,0,[],""],["frenk_t2-n4915",6,"Para tenerte bajo mis plantas\nnecesito yo ser rey,\npero antes de que eso pase\nviviré bajo tu ley.",107,2,11,127,"Estrofa suelta",3,4,"e",-1,0,-1,0,372,372,"4915","",0,"","","",1,0,0,[],""],["frenk_t2-n4916",6,"Esta noche fui a tu casa\ny me dieron de cenar\nlas tortillas amarillas\ny el atole sin colar.",114,2,17,127,"Los papaquis",0,4,"a",21,0,-1,0,372,372,"4916","",0,"","","",1,0,0,[],""],["frenk_t2-n4917",6,"Antenoche fui a tu casa,\nme asomé por la ventana;\nla malvada de tu hermana\nme aventó la porcelana.",107,2,11,127,"Estrofa suelta",0,4,"aa",4,0,-1,0,372,372,"4917","",0,"","","",8,0,0,[],""],["frenk_t2-n4918",6,"Antenoche fui a tu casa,\nme resbalé sin querer\ncon cáscaras de unas tunas\nque otro día me fui a comer.",107,2,11,127,"Estrofa suelta",0,4,"e",20,0,-1,0,372,372,"4918","",0,"","","",8,0,0,[],""],["frenk_t2-n4919",6,"Anoche fui a tu casa,\nme quedé junto del cuche,\npero el malvado cuche,\nque me rompe mi tacuche.",108,2,8,127,"Estrofa suelta",0,4,"ue",571,0,-1,0,372,372,"4919","",0,"","","",1,0,0,[],""],["frenk_t2-n4920",6,"Antenoche fui a tu casa\ny me paré en el gallinero;\ntu maldito gallo güero\nme cuachó en el sombrero.",108,2,8,127,"Estrofa suelta",0,4,"eo",38,0,-1,0,373,373,"4920","",0,"","","",8,0,0,[],""],["frenk_t2-n4921",6,"Antenoche fui a tu casa,\ny me ladraron los perros;\nquise agarrar una piedra,\ny me embarré los dedos.",107,2,11,127,"Estrofa suelta, El caimán viejo’*",0,4,"eo",-1,0,-1,0,373,373,"4921","",0,"","","",8,0,0,[],""],["frenk_t2-n4922",6,"Antenoche tuve un sueño,\nque ya me moría de risa:\nsoñé que estaba en tus brazos,\ny amanecí en la ceniza.",108,2,8,127,"María, María; Anoche soñaba; Estrofa suelta",0,4,"ia",420,0,-1,0,373,373,"4922","",0,"","","",3,0,0,[],""],["frenk_t2-n4923",6,"Antenoche tuve un sueño,\nque ya me moría de risa:\nlos piojos de tus enaguas\nse cargaban mi camisa.",108,2,8,127,"María, María; Marieta; El vacilón; Estrofa suelta",0,4,"ia",68,0,-1,0,373,373,"4923","",0,"","","",3,0,0,[],""],["frenk_t2-n4924",6,"No me importa que el destino\ncon fiero rigor me trate,\npues, aunque me muerda mi suegra,\nyo no te suelto el mecate.",122,2,13,127,"Estrofa suelta",0,4,"ae",384,0,-1,0,373,373,"4924","",0,"","","",1,0,0,[],""],["frenk_t2-n4925",6,"La suerte a los dos nos toca,\npiensa sólo en mi querer;\ntu marido ya no sopla:\ntú irás a ser mi mujer.",105,2,-1,127,"Por una mujer casada",0,4,"e",20,0,-1,0,373,373,"4925","",0,"","","",1,0,0,[],""],["frenk_t2-n4926",6,"Ya con ésta me despido,\nal pie de la nopalera;\nme voy cantando el corrido\nde “La culebra pollera”,\na ver si así tu marido\nse hace más a mi manera.",105,2,-1,127,"La culebra pollera",9,6,"ea",44,0,-1,0,373,373,"4926","",0,"","","",72,0,0,[],""],["frenk_t2-n4929",6,"Dicen los de tu casa\nque me han de matar mañana\nun guajolote muy bueno\npa almorzar con tu hermana.",105,2,-1,127,"El caballo lucero",0,4,"aa",4,0,-1,0,374,374,"4929","",0,"","","",1,0,0,[],""],["frenk_t2-n4930",6,"Todos dicen que tus ojos\nparecen dos capulines;\na mí me parecen moras\nde noche y a todas horas,\nse me hace que no le atoras.",116,2,15,127,"La voltereta",7,5,"oa",198,0,-1,0,374,374,"4930","",0,"","","",1,0,0,[],""],["frenk_t2-n4931",6,"Por ahí se soltó el borlote\nque me tienes embrujado,\nque siempre me traes al trote\npor algo que tú me has dado.",105,2,-1,127,"El embrujado",1,4,"ao",14,0,-1,0,374,374,"4931","",0,"","","",1,0,0,[],""],["frenk_t2-n4932",6,"Pa mí que estoy embrujado:\nme da de vueltas la choya;\nme tienes bien amolado,\nya estoy adentro de la olla.",105,2,-1,127,"El embrujado",1,4,"oa",453,0,-1,0,374,374,"4932","",0,"","","",1,0,0,[],""],["frenk_t2-n4933",6,"Estoy muy desesperado,\nme traes como vuelto loco,\ny pa tenerme amarrado\nme diste mi agua de coco.",105,2,-1,127,"El embrujado",1,4,"oo",152,0,-1,0,374,374,"4933","",0,"","","",1,0,0,[],""],["frenk_t2-n4935",6,"Garraleta de mi vida,\ngarraleta de mi amor,\ncuando estés en tus requiebros\nno sepultes mi pasión.",114,2,17,127,"La coqueta",0,4,"o",-1,0,-1,0,375,375,"4935","",0,"","","",1,0,0,[],""],["frenk_t2-n4936",6,"Yo quisiera que me amaras\ny que no me aborrecieras\ny traición no me jugaras\ny que siempre me quisieras\ny que nunca te encelaras,\naunque con otra me vieras,",106,2,4,127,"El Balajú",9,6,"ea",103,0,-1,0,375,375,"4936","",0,"","","",1,0,0,[],""],["frenk_t2-n4937",6,"Ariles y más ariles,\nariles de la ladera;\nsi te vas con Balajú,\ndame un consuelo siquiera",106,2,4,127,"El Balajú",0,4,"ea",44,0,-1,0,375,375,"4937","",0,"","","",24,0,0,[],""],["frenk_t2-n4938",6,"Por esta calle me he andado,\nde Chiñiñú y a Yutacata;\ndime si me has de querer,\npara no meter la pata.",108,2,8,127,"Estrofa suelta",3,4,"aa",74,0,-1,0,375,375,"4938","",0,"","","",1,0,0,[],""],["frenk_t2-n4939",6,"En un árbol muy frondoso\nyo vi la Virgen del Carmen.\nTe aseguro, ángel hermoso,\nque si no llegas a amarme,\nme echo de cabeza a un pozo,\npero siempre a no matarme.",105,2,-1,127,"El Balajú; La morena; El siquisirí",9,6,"ae",35,0,-1,0,375,375,"4939","",0,"","","",1,0,0,[],""],["frenk_t2-n4940",6,"Eres flor de Rosalía,\nde jardines de Belén.\nTe suplico, vida mía,\nque si no me quieres bien,\npongo el pescuezo en la vía,\ndespués de que pase el tren.",106,2,4,127,"El siquisirí",9,6,"e",242,0,-1,0,375,375,"4940","",0,"","","",1,0,0,[],""],["frenk_t2-n4941",6,"Al cabo de tanto andar\nse gastan las herraduras;\nchinita, si no me quieres,\n¿pa qué me das gordas duras?",105,2,-1,127,"Estrofa suelta",0,4,"ua",238,0,-1,0,375,375,"4941","",0,"","","",4,0,0,[],""],["frenk_t2-n4942",6,"Si no me quieres, mujer,\ndímelo, no te de pena,\nque agua que no has de beber,\njala mejor la cadena.",122,2,13,127,"Estrofa suelta",1,4,"ea",59,0,-1,0,375,375,"4942","",0,"","","",1,0,0,[],""],["frenk_t2-n4943",6,"Si nunca me has de querer,\nsi tú has de ser mi condena,\nagua que no has de beber\nmejor jala la cadena.",107,2,11,127,"Estrofa suelta",1,4,"ea",59,0,-1,0,375,375,"4943","",0,"","","",1,0,0,[],""],["frenk_t2-n4945",6,"¿Qué te han hecho mis calzones,\nque tanto mal hablas de ellos?\n¿No te acuerdas, picarona,\ncuando jugabas con ellos?",105,2,-1,127,"Estrofa suelta, El pastelero",0,4,"eo",-1,0,-1,0,376,376,"4945","",0,"","","",1,0,0,[],""],["frenk_t2-n4946",6,"Nicolasa, Nicolasa,\n¿por qué na más me entretienes?\nYa no me des calabazas:\n¡mira qué flaco me tienes!",106,2,4,127,"La Nicolasa",0,4,"ee",120,0,-1,0,376,376,"4946","",0,"","","",1,0,0,[],""],["frenk_t2-n4947",6,"Como que te vas,\ncomo que te vienes,\npero vida mía,\n¡cómo me entretienes!",115,2,3,127,"El palmero",0,4,"ee",120,0,-1,0,376,376,"4947","",0,"","","",1,0,0,[],""],["frenk_t2-n4949",6,"Mariquita, quita, quita,\nquítame de amor de penas,\npara ver si me quitan\nestos dolores de muela.",109,2,7,127,"Mariquita quita, quita",0,4,"ea",-1,0,-1,0,376,376,"4949","",0,"","","",5,0,0,[],""],["frenk_t2-n4950",6,"Traigo puritos deseos\nde decirte la verdad:\n¿por qué es que cuando yo te veo\nvolteas la cara pa atrás?\nSi lo haces porque estoy feo,\nreclámale a mi papá.",106,2,4,127,"El siquisirf’",9,6,"a",-1,0,-1,0,376,376,"4950","",0,"","","",1,0,0,[],""],["frenk_t2-n4951",6,"Si porque me vites feo,\npiensas que no soy celoso,\nadvierte que si me enojo,\npuedo convertirme en oso.",105,2,-1,127,"Estrofa suelta",0,4,"oo",-1,0,-1,0,376,376,"4951","",0,"","","",1,0,0,[],""],["frenk_t2-n4952",6,"Si porque me ves tan pobre,\nno te lo hago con salero,\nalgún día tendré dinero,\ny entonces te pago doble.",105,2,-1,127,"El colimóte",5,4,"oe",-1,0,-1,0,376,376,"4952","",0,"","","",2,0,0,[],""],["frenk_t2-n4953",6,"¡Ay, cocol!,\n¿Ya no te acuerdas cuando eras chimiz-\nYa porque tienes tu ajonjolí,\nya no te quieres acordar de mí.",119,2,12,127,"Los chimizclanes",3,4,"i",23,0,-1,0,377,377,"4953","",0,"","","",1,0,0,[],""],["frenk_t2-n4954",6,"Toda la noche estuve\nde centinela en tu cama;\nno fuiste para decirme:\n“Ten, toma la chiche, y mama.”",108,2,8,127,"Estrofa suelta",0,4,"aa",90,0,-1,0,377,377,"4954","",0,"","","",1,0,0,[],""],["frenk_t2-n4955",6,"Ahí me puse a cantar\nen medio de mis amigas,\ny no fue para decirme:\n“¡Ay, te pican las hormigas!”",129,2,9,127,"Estrofa suelta",0,4,"ia",114,0,-1,0,377,377,"4955","",0,"","","",1,0,0,[],""],["frenk_t2-n4956",6,"Dices que ya no me quieres\nporque tengo aquí un granito;\nno pienses, mi bien, que es sarna:\nes picada de un mosquito.",106,2,4,127,"La sarna",0,4,"io",119,0,-1,0,377,377,"4956","",0,"","","",21,0,0,[],""],["frenk_t2-n4957",6,"Y dice que no me quiere\nporque tengo aquí un granote;\nno pienses, mi bien, que es sarna:\nes picada de un jicote.",106,2,4,127,"La sama] [clán?",0,4,"oe",292,0,-1,0,377,377,"4957","",0,"","","",1,0,0,[],""],["frenk_t2-n4958",6,"Dices que ya no me quieres\nporque tengo una verruga;\nno pienses, mi bien, que es sarna:\ny es mordida de tortuga.",106,2,4,127,"La sama",0,4,"ua",468,0,-1,0,377,377,"4958","",0,"","","",21,0,0,[],""],["frenk_t2-n4959",6,"Dices que ya no me quieres\nporque tengo una samita;\nno pienses, mi bien, que es sarna\nque me arrulle mi damita.",106,2,4,127,"La sarna",0,4,"ia",50,0,-1,0,377,377,"4959","",0,"","","",21,0,0,[],""],["frenk_t2-n4960",6,"¡Qué desgraciada es mi suerte\ny qué negra es mi fortuna!\nSiempre que yo vengó a verte\nhay un pato en la laguna.",105,2,-1,127,"La chinita",1,4,"ua",56,0,-1,0,377,377,"4960","",0,"","","",1,0,0,[],""],["frenk_t2-n4961",6,"Me dijiste que fue un gato\nel que entró por tu balcón:\nyo no he visto gato prieto\ncon sombrero y pantalón.",105,2,-1,127,"Estrofa suelta",0,4,"o",31,0,-1,0,377,377,"4961","",0,"","","",1,0,0,[],""],["frenk_t2-n4963",6,"¡Ay, indita, indita, indita!,\nindita de la otra orilla,\n¿dónde dormiste esta noche,\nque traes la barriga fría?",105,2,-1,127,"La indita",0,4,"ia",-1,0,-1,0,378,378,"4963","",0,"","","",2,0,0,[],""],["frenk_t2-n4964",6,"¡Ay, indita, indita, indita!,\nindita del otro lado,\n¿dónde dormiste esta noche,\nque traes el pelo mojado?",105,2,-1,127,"La indita",0,4,"ao",14,0,-1,0,378,378,"4964","",0,"","","",2,0,0,[],""],["frenk_t2-n4965",6,"Cuando yo te enamorétique\n¡quién a mí me lo dijérica\nque había de poner colúmpico\npara que otro se meciérica!",105,2,-1,127,"El tagarno",0,4,"ea",572,0,-1,0,378,378,"4965","",0,"","","",1,0,0,[],""],["frenk_t2-n4966",6,"Una tarde por paseo,\n.................... su huerta de caña;\n¿cómo conmigo no quieres,\ny con otros tienes maña?",105,2,-1,127,"La víbora’.’",3,4,"aa",213,0,-1,0,378,378,"4966","",0,"","","",1,0,0,[],""],["frenk_t2-n4967",6,"De la pila sale el agua,\ny de allí el zacate nace;\n¿cómo dice que no escribe,\ny hasta con la zurda le hace?",105,2,-1,127,"Estrofa suelta, Ya está la sala regada",0,4,"ae",84,0,-1,0,378,378,"4967","",0,"","","",1,0,0,[],""],["frenk_t2-n4972",6,"Me pintates un violín\nporque no te la he pegado:\npos ¡cómo había de engañarte,\ncuando estoy enamorado!",105,2,-1,127,"La violinera",0,4,"ao",14,0,-1,0,379,379,"4972","",0,"","","",6,0,0,[],""],["frenk_t2-n4973",6,"Me pintates un violín\npor creído y por bien pensado:\n¡quén me manda haber nacido\nhonesto y bien educado!",105,2,-1,127,"La violinera",3,4,"ao",14,0,-1,0,379,379,"4973","",0,"","","",6,0,0,[],""],["frenk_t2-n4974",6,"Me pintates un violín\nporque nunca te he paseado:\nPos ¡cómo había de pasearte,\nsi no soy acaudalado!",105,2,-1,127,"La violinera",3,4,"ao",14,0,-1,0,379,379,"4974","",0,"","","",6,0,0,[],""],["frenk_t2-n4975",6,"Me pintates un violín\nporque nunca te había obsequiado:\npos ¡cómo había de obsequiarte,\nsi yo no más he robado!",105,2,-1,127,"La violinera",3,4,"ao",14,0,-1,0,379,379,"4975","",0,"","","",6,0,0,[],""],["frenk_t2-n4976",6,"Me pintates un violín\nporque nunca te he golpeado:\npos ¡cómo había de golpearte,\nsi yo no soy un malvado!",105,2,-1,127,"La violinera",3,4,"ao",14,0,-1,0,379,379,"4976","",0,"","","",6,0,0,[],""],["frenk_t2-n4977",6,"Al pie de un verde nogal\ndurmiendo me acoronates;\ncon la erre, con la i, con la á,\ncon la erre me la pegates\ncon mucha facilidad;\nmi vida, ¡qué bien quedates!",112,2,6,127,"Estrofa suelta",9,6,"ae",283,0,-1,0,379,379,"4977","",0,"","","",1,0,0,[],""],["frenk_t2-n4978",6,"Del cielo cayó una rosa\ny en tu pelo se prendió,\ny no se te ha caído\nporque no te has sacudido.",107,2,11,127,"Estrofa suelta",5,4,"io",101,0,-1,0,379,379,"4978","",0,"","","",5,0,0,[],""],["frenk_t2-n4979",6,"Tienes unos ojos de paloma,\nuna boca de grana,\nunos dientes de perla,\ntienes un cutis de coral;\n¿no tienes cinco pesos?.",115,2,3,127,"Estrofa suelta",7,5,"eo",-1,0,-1,0,379,379,"4979","",0,"","","",1,0,0,[],""],["frenk_t2-n4980",6,"Te traigo en mi corazón,\n¡no he visto cosa tan bella!\nPero dice la canción:\n“mamá, no puedo con ella.”",108,2,8,127,"El pájaro cú",1,4,"ea",6,0,-1,0,379,379,"4980","",0,"","","",1,0,0,[],""],["frenk_t2-n4982",6,"Corté la flor de sandía\ny la puse a madurar;\náhi sigo con mi porfía:\nconmigo puedes contar\nhasta que amanezca el día.",106,2,4,127,"María Chuchena",7,5,"ia",0,0,-1,0,380,380,"4982","",0,"","","",1,0,0,[],""],["frenk_t2-n4983",6,"Traigo una carta firmada\ndestinada para ti;\npor Dios, que no tengo nada\ncon las muchachas de aquí,\npero si me dan entrada,\npues, entonces, pues que sí.",112,2,6,127,"La leva",9,6,"i",23,0,-1,0,380,380,"4983","",0,"","","",1,0,0,[],""],["frenk_t2-n4984",6,"Y aquí llegué, chiquita,\npa entregarte mi cariño;\npero si eres casada,\nno, porque me llora el niño.",105,2,-1,127,"Amores con falsete; Estrofa suelta",0,4,"io",176,0,-1,0,380,380,"4984","",0,"","","",1,0,0,[],""],["frenk_t2-n4986",6,"Ese lunar que tienes (cielito lindo)\njunto a la boca\nno se lo des a nadie (cielito lindo),\nque a mí me toca;\ny si lo dieres —por tan taruga,\nquiera Dios y se te vuelva (cielito 1\nprieta verruga.",105,2,-1,127,"Estrofa suelta",4,7,"ua",468,0,-1,0,380,380,"4986","",0,"","","",3,0,0,[],""],["frenk_t2-n4987",6,"Dicen que van a asustarme,\nque abandone tu presencia;\nsi estás dormida, mi vida,\nes natural si despiertas.",105,2,-1,127,"La muerte",0,4,"ea",-1,0,-1,0,380,380,"4987","",0,"","","",1,0,0,[],""],["frenk_t2-n4988",6,"Si porque te quiero, quieres\nque yo la muerte reciba,\neso sí que no haré yo:\nmorirme porque otro viva.",108,2,8,127,"La Sanmarqueña; Que comienzo, que comienzo",0,4,"ia",53,0,-1,0,380,380,"4988","",0,"","","",11,0,0,[],""],["frenk_t2-n4989",6,"Casi, casi, me quisistes;\ncasi, casi, te he querido;\nsi no fuera por el casi,\ncasi me caso contigo.",108,2,8,127,"Estrofa suelta",0,4,"io",-1,0,-1,0,381,381,"4989","",0,"","","",2,0,0,[],""],["frenk_t2-n4990",6,"Si mi sangre fuera tinta\ny mi corazón tintero,\nte diría lo mucho que te quiero.\nPero como mi sangre no es tinta\nni mi corazón tintero,\nno te quiero, lero, lero.",107,2,11,127,"Estrofa suelta",9,6,"eo",38,0,-1,0,381,381,"4990","",0,"","","",1,0,0,[],""],["frenk_t2-n4991",6,"Si cuatro vidas tuviera,\nyo te regalaría una;\npero como tengo una,\nno te regalo ninguna.",107,2,11,127,"Estrofa suelta",0,4,"ua",56,0,-1,0,381,381,"4991","",0,"","","",1,0,0,[],""],["frenk_t2-n4992",6,"Carita de requesón,\nnarices de mantequilla,\náhi te mando mi corazón\nenvuelto en una tortilla.",129,2,9,127,"Estrofa suelta",3,4,"ia",162,0,-1,0,381,381,"4992","",0,"","","",1,0,0,[],""],["frenk_t2-n4993",6,"Si yo fuera rey,\nte regalaría un trono;\npero como no lo soy,\nte regalo este mono.",107,2,11,127,"Estrofa suelta",0,4,"oo",530,0,-1,0,381,381,"4993","",0,"","","",1,0,0,[],""],["frenk_t2-n4994",6,"Ya me voy para la sierra\na que me coman los mapaches,\ny te dejo de recuerdo\nlas correas de mis huaraches.",112,2,6,127,"Estrofa suelta",0,4,"ae",526,0,-1,0,381,381,"4994","",0,"","","",1,0,0,[],""],["frenk_t2-n4995",6,"No traigo arquitos de oro,\nni una estrella matutina;\nsólo vengo aquí a tus puertas\na colgarte esta cortina.",105,2,-1,127,"Las mañanitas*’",0,4,"ia",11,0,-1,0,381,381,"4995","",0,"","","",1,0,0,[],""],["frenk_t2-n4996",6,"Yo quisiera uno guacare\nde purito tijocoti\npara dártelo, siñori,\ncon un plato guajolote;\npus ya no hay, pus ya se acabó.",115,2,3,127,"Felicitación indígena*’",7,5,"o",-1,0,-1,0,381,381,"4996","",0,"","","",1,0,0,[],""],["frenk_t2-n4997",6,"Si quieres ser mi mujer,\nte tienes que acostumbrar:\nno a dejar de trabajar,\nsino a dejar de comer.",122,2,13,127,"Estrofa suelta",11,4,"e",20,0,-1,0,381,381,"4997","",0,"","","",1,0,0,[],""],["frenk_t2-n4998",6,"Áhi te traigo un frijolítico\npa toda tu semanítica;\npor Dios no lo gastes tódico:\nno seas tan desperdiciádica.",110,2,10,127,"El tagarno",5,4,"aa",-1,0,-1,0,382,382,"4998","",0,"","","",1,0,0,[],""],["frenk_t2-n4999",6,"Por lo que yático\nle dije a ustétique:\nno quiero trático\ncon su mercétique.",105,2,-1,127,"El tagarno",6,4,"ee",575,0,-1,0,382,382,"4999","",0,"","","",1,0,0,[],""],["frenk_t2-n5000",6,"Calabazas me pediste,\ncalabazas te he de dar;\nsi quieres más calabazas,\nvoy a mandarte un costal.",105,2,-1,127,"Estrofa suelta",0,4,"a",-1,0,-1,0,382,382,"5000","",0,"","","",1,0,0,[],""],["frenk_t2-n5001",6,"Ya no te quiero, pelona,\nporque no me da la gana,\npues tú me quieres tener\nborracho de marihuana.",107,2,11,127,"La chinita; Los papaquis",0,4,"aa",4,0,-1,0,382,382,"5001","",0,"","","",1,0,0,[],""],["frenk_t2-n5003",6,"Se dice que el matrimonio\ntiene su luna de miel;\nmas la luna tiene cuernos,\nconque así, dispense usted.",105,2,-1,127,"Estrofa suelta",0,4,"e",-1,0,-1,0,382,382,"5003","",0,"","","",1,0,0,[],""],["frenk_t2-n5004",6,"Adiós, espejo lucido,\nya se va tu claridad:\nla jaula para tu consuelo\nporque el pájaro se va.",108,2,8,127,"Estrofa suelta",0,4,"a",-1,0,-1,0,382,382,"5004","",0,"","","",1,0,0,[],""],["frenk_t2-n5005",6,"Siempre que me emborracho,\npalabra que algo me pasa:\nvoy derechito a verte,\ny me equivoco de casa.",105,2,-1,127,"Siempre, siempre",0,4,"aa",123,0,-1,0,382,382,"5005","",0,"","","",2,0,0,[],""],["frenk_t2-n5006",6,"Al ir a la cita\nque me dio usted,\nme di un resbalón\ny me quebré un pie.",105,2,-1,127,"El cojo",6,4,"e",-1,0,-1,0,382,382,"5006","",0,"","","",1,0,0,[],""],["frenk_t2-n5007",6,"De tu ventana a la mía\nsólo hay un paso;\ntrata de darlo,\n¡y verás qué trancazo!",105,2,-1,127,"Estrofa suelta",3,4,"ao",-1,0,-1,0,383,383,"5007","",0,"","","",10,0,0,[],""],["frenk_t2-n5008",6,"De mi ventana a la tuya\nhay un espacio;\nda un paso,\n¡y verás que changazo!",107,2,11,127,"Estrofa suelta",3,4,"ao",43,0,-1,0,383,383,"5008","",0,"","","",2,0,0,[],""],["frenk_t2-n5009",6,"De tu ventana a la mía\nme mandaste muchos besos;\nvete a besar a tu tía,\ny aviéntame cinco pesos.",107,2,11,127,"Estrofa suelta",1,4,"eo",529,0,-1,0,383,383,"5009","",0,"","","",10,0,0,[],""],["frenk_t2-n5010",6,"Áhi te traigo unos zapatos,\nque en el aire los cogí;\nno digas que son robados:\narañados, eso sí.",105,2,-1,127,"Estrofa suelta",0,4,"i",23,0,-1,0,383,383,"5010","",0,"","","",1,0,0,[],""],["frenk_t2-n5011",6,"De por allí abajo vengo,\npero no te traigo nada:\nsólo un besito de amor\nque me enseñó una casada.",108,2,8,127,"María, María",0,4,"aa",49,0,-1,0,383,383,"5011","",0,"","","",1,0,0,[],""],["frenk_t2-n5012",6,"Eres florecita amarilla,\ncortada de la otra banda;\ntú eres mi consentidita,\npero la otra es la que manda.",108,2,8,127,"Estrofa suelta",0,4,"aa",502,0,-1,0,383,383,"5012","",0,"","","",1,0,0,[],""],["frenk_t2-n5013",6,"Pero si después de todo\nquieres tú que me contente,\ntendrás que quererme mucho,\nmucho más que la de enfrente.",114,2,17,127,"El agobiado",0,4,"ee",15,0,-1,0,383,383,"5013","",0,"","","",1,0,0,[],""],["frenk_t2-n5014",6,"Yo tenía mi cascabel,\npero andando lo perdí.\nTe debes de condoler\ny compadecer de mí,\nque no por esa mujer\nquiera quedarme sin ti.",105,2,-1,127,"El cascabel",9,6,"i",23,0,-1,0,383,383,"5014","",0,"","","",10,0,0,[],""],["frenk_t2-n5015",6,"Antenoche fui a tu casa,\ntres golpes le di al candado:\ntú no sirves para amores,\ntienes el sueño pesado.",108,2,8,127,"La Zandunga; La Zandunga (La surianita), Mi hamaca es de pura seda; Las torcazas",0,4,"ao",14,0,-1,0,383,383,"5015","",0,"","","",8,0,0,[],""],["frenk_t2-n5017",6,"—Amada Margarita,\nmamá de San Mateo.\n—Yo no me mando sola\nNicolás me manotea.",108,2,8,127,"El Colás",5,4,"ea",-1,0,-1,0,384,384,"5017","",0,"","","",4,0,0,[],""],["frenk_t2-n5018",6,"—Tan, tan, ¿quién toca la puerta?,\n¿quién viene a dormir conmigo?\nSi no trae los cinco pesos,\n¡váyase, señor, le digo!",110,2,10,127,"Tan, tan",0,4,"io",106,0,-1,0,384,384,"5018","",0,"","","",1,0,0,[],""],["frenk_t2-n5019",6,"—Dime, niña bonita,\n¿quién te mantiene?\n—Veinticinco doblones\nque van y vienen.",106,2,4,127,"La bamba",6,4,"ee",-1,0,-1,0,384,384,"5019","",0,"","","",2,0,0,[],""],["frenk_t2-n5021",6,"—Indita, ¿no me decías:\n“Ay, señor, cuánto lo quiero”?\n—Sí, señor, se lo decía,\nmientras tenía dinero.",105,2,-1,127,"La indita",0,4,"eo",38,0,-1,0,384,384,"5021","",0,"","","",3,0,0,[],""],["frenk_t2-n5026",6,"Esta tilma es muy mía,\nme la tejió mi papá,\npa que yo la ande cargando:\ny tú me la quieres quitar.",106,2,4,127,"Estrofa suelta",0,4,"a",-1,0,-1,0,385,385,"5026","",0,"","","",1,0,0,[],""],["frenk_t2-n5027",6,"Yo me casé con usted\npor tomar buen chocolate,\ny ahora me va usted saliendo\ncon machiguas del metate.",105,2,-1,127,"Estrofa suelta",3,4,"ae",384,0,-1,0,385,385,"5027","",0,"","","",7,0,0,[],""],["frenk_t2-n5028",6,"Medio de queso te di\nen prueba de matrimonio;\nsi no te casas conmigo,\ndame mi [queso], demonio.",107,2,11,127,"Estrofa suelta",0,4,"oo",169,0,-1,0,385,385,"5028","",0,"","","",1,0,0,[],""],["frenk_t2-n5030",6,"Cuando te busco la cara\nte das importancia padre;\nte pareces a tu mami\ncon su cara de vinagre.",107,2,11,127,"Estrofa suelta",0,4,"ae",-1,0,-1,0,386,386,"5030","",0,"","","",1,0,0,[],""],["frenk_t2-n5031",6,"Ya me tiene usté enfadada,\nya no quiero su donoso;\ndeme usted mi periquito,\nmis enaguas y rebozo.",118,2,27,127,"Estrofa suelta",0,4,"oo",156,0,-1,0,386,386,"5031","",0,"","","",1,0,0,[],""],["frenk_t2-n5032",6,"Tú nunca escuchas consejos\ny a todos ves sin razones;\ncomo Dios a los conejos:\nchiquitos y orejones.",105,2,-1,127,"La divina garza",1,4,"oe",34,0,-1,0,386,386,"5032","",0,"","","",1,0,0,[],""],["frenk_t2-n5033",6,"Las chivarras que yo tengo\nson de cuero de venado,\ny el genio que tú tienes\nes de un diablo condenado.",105,2,-1,127,"Las chivarras",0,4,"ao",14,0,-1,0,386,386,"5033","",0,"","","",1,0,0,[],""],["frenk_t2-n5034",6,"Permita el cielo divino,\npor lo mal que me has pagado,\nte trate un indio mal criado,\nbrujo, nagual y hechicero.",105,2,-1,127,"Estrofa suelta",5,4,"eo",-1,0,-1,0,386,386,"5034","",0,"","","",2,0,0,[],""],["frenk_t2-n5035",6,"Yo no quiero que te mueras,\nque se acueste a los difuntos;\nyo no quiero que te mueras,\nsino llevarte al panteón.",105,2,-1,127,"Estrofa suelta",5,4,"o",-1,0,-1,0,386,386,"5035","",0,"","","",1,0,0,[],""],["frenk_t2-n5036",6,"A Medellín\nte he de llevar\npara hacerte una tumba (chatita)\nmuy particular.",108,2,8,127,"El pájaro cú",3,4,"a",21,0,-1,0,386,386,"5036","",0,"","","",2,0,0,[],""],["frenk_t2-n5037",6,"Para cuando te mueras\ntengo pensado\nel vestirte la tumba\nde azul morado.",106,2,4,127,"El pájaro cú",6,4,"ao",14,0,-1,0,386,386,"5037","",0,"","","",1,0,0,[],""],["frenk_t2-n5038",6,"Ya subió la luna llena,\nalumbrando el callejón;\nya viene mi linda chata\nsaltando como un tejón.",108,2,8,127,"Estrofa suelta",0,4,"o",31,0,-1,0,387,387,"5038","",0,"","","",1,0,0,[],""],["frenk_t2-n5039",6,"De las aves del campo\nme gusta el ganso,\nque la joven que adoro\nviste de blanco.\n¿Y en qué consiste?\nTambién algunas veces\nde negro visten.",119,2,12,127,"CieHto lindo (El butaquito)",4,7,"ie",-1,0,-1,0,387,387,"5039","",0,"","","",3,0,0,[],""],["frenk_t2-n5041",6,"Vuela, vuela, vuela,\nvuela palomita;\nno le hace que yo sea feo,\nsi la que quiero es bonita.",106,2,4,127,"La guacamaya",0,4,"ia",50,0,-1,0,387,387,"5041","",0,"","","",17,0,0,[],""],["frenk_t2-n5042",6,"Cuando yo era chiquito\nme engañaban con panela;\nahora que ya voy creciendo\nme engañan con la cadera.",108,2,8,127,"La Sanmarqueña",0,4,"ea",-1,0,-1,0,387,387,"5042","",0,"","","",2,0,0,[],""],["frenk_t2-n5043",6,"Si la niña de la caja\nmoviera más su grupa,\nme sacaran con mortaja\ndiciendo: “¡Upa, upa!”",108,2,8,127,"Estrofa suelta",3,4,"ua",576,0,-1,0,387,387,"5043","",0,"","","",1,0,0,[],""],["frenk_t2-n5045",6,"Cuando se llegue la Nochebuena,\nvoy a pedirles con gran dolor,\nvoy a decirles a las morenas\nque, si se puede, me traigan dos.",115,2,3,127,"Las morenitas",3,4,"o",-1,0,-1,0,388,388,"5045","",0,"","","",1,0,0,[],""],["frenk_t2-n5046",6,"Pasé por el cementerio\nen busca de las bonitas;\nrae responde el muerto serio:\n“Búscalas, que están sólitas,\nque las hijas de Eleuterio\nhan quedado huerfanitas.”",112,2,6,127,"El huerfanito",9,6,"ia",258,0,-1,0,388,388,"5046","",0,"","","",1,0,0,[],""],["frenk_t2-n5047a",6,"Yo no me llamo Jesús,\nyo me llamo Canela;\nacostándome con Luz,\naunque no me enciendan vela.",108,2,8,127,"Estrofa suelta",1,4,"ea",167,0,-1,0,388,388,"5047a","",0,"","","",1,0,0,[],""],["frenk_t2-n5048",6,"¡Y hora sí, sacamandú,\nvámonos haciendo'bola;\nanoche dormí con Luz,\nahora dormiré con Pola!",105,2,-1,127,"El sacamandú",0,4,"oa",321,0,-1,0,388,388,"5048","",0,"","","",1,0,0,[],""],["frenk_t2-n5049",6,"Y ya no siembro yerbabuena,\nporque me salió cilantro;\nesta noche duermo en medio,\nporque, en la orilla me espanto.",105,2,-1,127,"Con un polvo y otro polvo",0,4,"ao",-1,0,-1,0,388,388,"5049","",0,"","","",1,0,0,[],""],["frenk_t2-n5050",6,"Ariles y más ariles,\nariles del camposanto;\nyo me acuesto en el rincón,\nporque en la orilla me espanto.",105,2,-1,127,"El Balajú",0,4,"ao",30,0,-1,0,388,388,"5050","",0,"","","",24,0,0,[],""],["frenk_t2-n5051",6,"Pobre del zopilotito,\nque come carne que empacha:\nsi yo fuera zopilote,\nme comería una muchacha.",109,2,7,127,"El zopilote",0,4,"aa",556,0,-1,0,389,389,"5051","",0,"","","",2,0,0,[],""],["frenk_t2-n5052",6,"Miraba el agua de un charco\ny me paseé en derredor,\ny le dije a una de un barco\ny al otro que iba en vapor:\n“Mojarrilla de este charco,\nya llegó tu pescador.”",105,2,-1,127,"Estrofa suelta",9,6,"o",72,0,-1,0,389,389,"5052","",0,"","","",1,0,0,[],""],["frenk_t2-n5053",6,"Y dile que baje al agua,\ntrayendo su roja enagua;\nquien quita y yo me eche al rato,\npara ver si me hago pato.",105,2,-1,127,"El palmero",5,4,"ao",19,0,-1,0,389,389,"5053","",0,"","","",1,0,0,[],""],["frenk_t2-n5054",6,"Andando se saben tierras\ny se experimentan amores:\n¡ay, qué dolores de piernas!,\n¡ay, qué piernas de Dolores!",108,2,8,127,"Estrofa suelta",0,4,"oe",5,0,-1,0,389,389,"5054","",0,"","","",1,0,0,[],""],["frenk_t2-n5055a",6,"Una mujer me cambió\nperas por racimo de uvas;\nentonces le dije yo:\n“Lo veremos, por las dudas.”",105,2,-1,127,"Estrofa suelta, Me puse en un espiadero",0,4,"ua",-1,0,-1,0,389,389,"5055a","",0,"","","",1,0,0,[],""],["frenk_t2-n5056",6,"El señor que está ahí,\nde la camiseta blanca,\npero más blanquitas son\nlas piernitas de su hermana.",107,2,11,127,"Estrofa suelta",0,4,"aa",-1,0,-1,0,389,389,"5056","",0,"","","",1,0,0,[],""],["frenk_t2-n5057",6,"Yo vengo de La Habana,\ndel puerto de San Blas;\nahí conocí una hermana\nque tiene Nicolás.",106,2,4,127,"El Colás",1,4,"a",51,0,-1,0,389,389,"5057","",0,"","","",1,0,0,[],""],["frenk_t2-n5058",6,"Colás, Colás,\nColás y Nicolás,\nsi tienes una hermana,\n¿por qué no me la das?",105,2,-1,127,"El Colás",3,4,"a",51,0,-1,0,389,389,"5058","",0,"","","",3,0,0,[],""],["frenk_t2-n5059",6,"Para ser mi cuñado\nse necesita\nque me des a tu hermana\nla más chiquita.",106,2,4,127,"La bamba",6,4,"ia",50,0,-1,0,390,390,"5059","",0,"","","",1,0,0,[],""],["frenk_t2-n5060",6,"Para ser tu cuñado\ndebe de ser,\nque me des a tu hermana\npara mujer.",106,2,4,127,"La bamba",6,4,"e",20,0,-1,0,390,390,"5060","",0,"","","",1,0,0,[],""],["frenk_t2-n5061",6,"Al pasar por tu casa\nme aventaron una manzana;\npara otra vez que pase,\nque me avienten a tu hermana.",107,2,11,127,"Estrofa suelta",0,4,"aa",4,0,-1,0,390,390,"5061","",0,"","","",1,0,0,[],""],["frenk_t2-n5062",6,"Al pasar por tu ventana\nme aventastes una caña,\nahora quiero que me avientes\na tu hermana la mediana.",107,2,11,127,"La Sanmarqueña",0,4,"aa",-1,0,-1,0,390,390,"5062","",0,"","","",8,0,0,[],""],["frenk_t2-n5063",6,"Al pasar por tu ventana\nme aventaste un limón;\nahora aviéntame a tu hermana,\ny verás qué vacilón.",107,2,11,127,"Estrofa suelta",1,4,"o",31,0,-1,0,390,390,"5063","",0,"","","",8,0,0,[],""],["frenk_t2-n5064",6,"Cuando pase por tu casa,\nno me avientes un limón,\naviéntame a tu hermano,\naunque sea de vacilón.",107,2,11,127,"Estrofa suelta",0,4,"o",31,0,-1,0,390,390,"5064","",0,"","","",6,0,0,[],""],["frenk_t2-n5065",6,"Por arriba corre el agua,\npor abajo zacatito;\n¿cómo quieres que te olvide,\nsi tienes un hermanito?",107,2,11,127,"Estrofa suelta",0,4,"io",119,0,-1,0,390,390,"5065","",0,"","","",1,0,0,[],""],["frenk_t2-n5066",6,"Me cae peseta,\nme cae tostón,\nme cae tu hermano\nen el corazón.",105,2,-1,127,"Estrofa suelta",0,4,"o",31,0,-1,0,390,390,"5066","",0,"","","",1,0,0,[],""],["frenk_t2-n5067",6,"Entre tu casa y la mía\nestá plantado un clavel;\n¡cómo me gusta tu hermano\npara casarme con él!",107,2,11,127,"Estrofa suelta",0,4,"e",32,0,-1,0,391,391,"5067","",0,"","","",1,0,0,[],""],["frenk_t2-n5068",6,"Me he de comer un durazno\nde corazón colorado;\nme he de casar con tu hermano,\npara que seas mi cuñado.",107,2,11,127,"Estrofa suelta",0,4,"ao",-1,0,-1,0,391,391,"5068","",0,"","","",3,0,0,[],""],["frenk_t2-n5069",6,"Quisiera ser labrador\npara cosechar la uva.\nYo me embarqué en un vapor,\ncon dirección a la Cuba,\nporque se ha visto a mi amor\nentre coles y lechugas.",108,2,8,127,"Zapateado, La guacamaya",9,6,"ua",-1,0,-1,0,391,391,"5069","",0,"","","",1,0,0,[],""],["frenk_t2-n5070",6,"Este cuamecate, mi alma,\nque pongo yo a la oración,\npara que tienda sus trapos\nla alma mía de Concepción.",114,2,17,127,"El cuamecate",0,4,"o",31,0,-1,0,391,391,"5070","",0,"","","",8,0,0,[],""],["frenk_t2-n5071",6,"Este cuamecate, mi alma,\nque tiendo en la mañanita,\npara que tienda sus trapos\nalma mía de mi Juanita.",114,2,17,127,"El cuamecate",0,4,"ia",50,0,-1,0,391,391,"5071","",0,"frenk_t4","","",8,0,0,[],""],["frenk_t2-n5072",6,"Este cuamecate, mi alma,\nque tiendo de todo el día,\npara que tienda sus trapos\nla dueña del alma mía.",114,2,17,127,"El cuamecate",0,4,"ia",0,0,-1,0,391,391,"5072","",0,"frenk_t4","","",8,0,0,[],""],["frenk_t2-n5073",6,"Antenoche con la luna\nfui a pasearme a la retreta,\nllevaba con buen agrado\ndel brazo a mi garraleta.",105,2,-1,127,"La coqueta",0,4,"ea",200,0,-1,0,391,391,"5073","",0,"","","",1,0,0,[],""],["frenk_t2-n5074a",6,"Mi dijo una presumida\nde la Colonia Mainero\nque la llevara a Altamira\ny luego a su Ciudad Madero,\nigual que el primer día.",105,2,-1,127,"La presumida",7,5,"ia",-1,0,-1,0,391,391,"5074a","",0,"","","",1,0,0,[],""],["frenk_t2-n5075",6,"Y ahora lo verá\nlo que [a mí me pasa]\ncon cuatro muchachas\nque tengo en mi casa:\nya una me besa,\nya otra me abraza,\nla otra me mece,\nla otra me mete\nla mano en el seno,\ny la otra me dice",106,2,4,127,"que eso sí está bueno]. [El jarabe loco, ‘Έ1 coco",18,10,"ie",-1,0,-1,0,392,392,"5075","",0,"","","",1,0,0,[],""],["frenk_t2-n5076",6,"Mi madre me dio una pela\nporque me halló enamorando;\nle dije que no la amuela,\nque apenas me ando enseñando,\npara el día que ella se muera,\nque no me anden engañando.",112,2,6,127,"El huerfanito; El querreque",9,6,"ao",33,0,-1,0,392,392,"5076","",0,"","","",2,0,0,[],""],["frenk_t2-n5077",6,"Mi madre me dio una zurra\nporque enamoré a Chabela,\ny al son de los palos dije:\n“¡Ay, mamá, si esto es canela!,\ny aunque me sigas pegando,\nyo no dejaré a Chabela.”",105,2,-1,127,"El conejo",9,6,"ea",167,0,-1,0,392,392,"5077","",0,"","","",1,0,0,[],""],["frenk_t2-n5079",6,"A Cupido le dieron fama,\ny yo no había nacido;\nme la regañó su mama\nporque un hijo había tenido.",108,2,8,127,"El Cupido",1,4,"io",101,0,-1,0,392,392,"5079","",0,"","","",1,0,0,[],""],["frenk_t2-n5080",6,"Por un tropezón que di,\ntodo el mundo se admiró;\ntodas tropiezan y paren,\ny de eso no me admiro yo.",108,2,8,127,"Estrofa suelta",0,4,"o",2,0,-1,0,392,392,"5080","",0,"","","",2,0,0,[],""],["frenk_t2-n5081",6,"Y su mamá le decía:\n“Cierra ese cuarto”;\nyo hago ruido al candado:\ntate otro rato.",105,2,-1,127,"La chinita",6,4,"ao",-1,0,-1,0,392,392,"5081","",0,"","","",3,0,0,[],""],["frenk_t2-n5082",6,"Sale su papá de adentro,\ntirándome de balazos,\nporque me encontró con Julia\nestrechadita en mis brazos.",105,2,-1,127,"La Julia",0,4,"ao",132,0,-1,0,392,392,"5082","",0,"","","",3,0,0,[],""],["frenk_t2-n5083",6,"Sale su papá de adentro,\ntratándome de grosero,\nporque me encontró con Julia,\naventándole el sombrero.",114,2,17,127,"La Julia",0,4,"eo",38,0,-1,0,393,393,"5083","",0,"","","",3,0,0,[],""],["frenk_t2-n5084",6,"Y sale su mamá de adentro,\ntratándome de grosero,\npero al punto yo le digo\nque soy ferrocarrilero.",105,2,-1,127,"Serían las dos",0,4,"eo",38,0,-1,0,393,393,"5084","",0,"","","",1,0,0,[],""],["frenk_t2-n5085",6,"Sale su papá de adentro,\ndiciéndome: “¡Sinvergüenza!”,\nporque me encontró con Julia,\nalisándole la trenza.",105,2,-1,127,"Estrofa suelta, La Julia",0,4,"ea",578,0,-1,0,393,393,"5085","",0,"","","",3,0,0,[],""],["frenk_t2-n5086",6,"Y sale su papá de adentro,\ntirándome de balazos,\ny a la vuelta de su casa\nnos dimos de catorrazos.",105,2,-1,127,"Serían las dos",0,4,"ao",132,0,-1,0,393,393,"5086","",0,"","","",1,0,0,[],""],["frenk_t2-n5087",6,"Mi madre me dio una pela\nporque le pedí marido:\n“Madre, dame dos pelas,\npero dame lo que te pido.”",129,2,9,127,"Estrofa suelta",0,4,"io",101,0,-1,0,393,393,"5087","",0,"","","",2,0,0,[],""],["frenk_t2-n5088",6,"Una paloma al volar,\nvolando perdió su nido,\ny me dijo acongojada:\n“Viejito, busco marido.”",107,2,11,127,"La Sanmarqueña",0,4,"io",101,0,-1,0,393,393,"5088","",0,"","","",8,0,0,[],""],["frenk_t2-n5089",6,"San Antonio milagroso,\nyo te suplico llorando\nque me des un buen esposo\nporque ya me estoy pasando.",105,2,-1,127,"Estrofa suelta",1,4,"ao",33,0,-1,0,393,393,"5089","",0,"","","",2,0,0,[],""],["frenk_t2-n5090",6,"Mi novia se portó fiel\ncuando llegué por aquí;\ncumpliendo con su papel,\nsu mamá le dijo así:\n“Hija, te casas con él,\no me lo dejas a mí.”",113,2,2,127,"El pica, pica",9,6,"i",23,0,-1,0,393,393,"5090","",0,"","","",1,0,0,[],""],["frenk_t2-n5091",6,"Te voy a hacer tu casita (mamá),\ncon piedritas de hormiguero,\npara que vivas solita (¡ay, mamá!),\ny yo con el carbonero.",124,2,16,127,"El carbonero",3,4,"eo",38,0,-1,0,393,393,"5091","",0,"","","",1,0,0,[],""],["frenk_t2-n5092",6,"Santa Rita de mi vida,\nque junto a Dios has de estat,\nintercede por este hombre,\nque no se puede casar.",105,2,-1,127,"Estrofa suelta",0,4,"a",-1,0,-1,0,394,394,"5092","",0,"","","",1,0,0,[],""],["frenk_t2-n5093",6,"La vida de ser soltero\nvarios líos acarrea;\npor eso casarme quiero\ncon una rica, esta idea:\npara que de un mismo cuero\nsalgan huarache y correa.",105,2,-1,127,"El buscapiés",9,6,"ea",54,0,-1,0,394,394,"5093","",0,"","","",1,0,0,[],""],["frenk_t2-n5094",6,"¡Cuándo llegará ese cuándo,\nque tanto mi alma desea,\ncasarme con una fea\npara estarla pellizcando!",107,2,11,127,"Estrofa suelta",11,4,"ao",33,0,-1,0,394,394,"5094","",0,"","","",5,0,0,[],""],["frenk_t2-n5095",6,"Dicen que el que es casado\napesta a muerto,\ny yo les aseguro (cielito lindo)\nque eso no es cierto:\neso no es cierto,\nporque yo soy casado (cielito lindo),\npero no apesto.",107,2,11,127,"Estrofa suelta",4,7,"eo",-1,0,-1,0,394,394,"5095","",0,"","","",1,0,0,[],""],["frenk_t2-n5096",6,"Amigo, si usted es mi amigo,\nemprésteme a su mujer;\nque, por ser usted mi amigo,\nyo nadita le he de hacer.",105,2,-1,127,"Estrofa suelta",1,4,"e",20,0,-1,0,394,394,"5096","",0,"","","",2,0,0,[],""],["frenk_t2-n5097",6,"Y al pasar por su ventana,\nme dijo una capireña:\n“cuando esté con mi marido\nno me haga ninguna seña.”",105,2,-1,127,"El capire",0,4,"ea",291,0,-1,0,394,394,"5097","",0,"","","",1,0,0,[],""],["frenk_t2-n5098",6,"¡Ay!, que me miraba,\n¡ay!, me sonreía,\n¡ay!, y me decía:\n“Pero, hombre, ¡caramba!,\npos si soy casada.”",114,2,17,127,"El sombrero ancho",7,5,"aa",-1,0,-1,0,394,394,"5098","",0,"","","",1,0,0,[],""],["frenk_t2-n5100",6,"Ya el doctor se está muriendo,\nya la tos se le pegó,\ny ojalá que se muriera:\nla viuda la heredo yo.",105,2,-1,127,"La tos",0,4,"o",2,0,-1,0,394,394,"5100","",0,"","","",1,0,0,[],""],["frenk_t2-n5101c",6,"Si me levanto temprano\na cortar la flor de ruda,\nme ando siempre imaginando,\ny siempre ando con la duda:\n¡qué ojos me pelara el muerto\nsi me viera con la viuda!",112,2,6,127,"La leva",9,6,"ua",144,0,-1,0,395,395,"5101c","",0,"","","",1,0,0,[],""],["frenk_t2-n5102",6,"Aunque no soy sacristán,\nprocuro el agua bendita,\npa que no me asuste el muerto\npor ganarle a su viudita.",105,2,-1,127,"Amores con falsete; Estrofa suelta",0,4,"ia",50,0,-1,0,395,395,"5102","",0,"","","",1,0,0,[],""],["frenk_t2-n5103",6,"A un Santo Cristo de fierro\nmis penas yo le conté.\nY el Santo Cristo me dijo:\n“¿Y a mí qué me cuenta usted?”",105,2,-1,127,"Estrofa suelta, El pastelero; La Sanmarqueña",0,4,"e",-1,0,-1,0,395,395,"5103","",0,"","","",1,0,0,[],""],["frenk_t2-n5104",6,"Yo le pregunté a un amigo\nsi no la vido pasar:\n“Por aquí sólo ha pasado\nel Ferrocarril Central.”",105,2,-1,127,"La Julia",0,4,"a",-1,0,-1,0,395,395,"5104","",0,"","","",1,0,0,[],""],["frenk_t2-n5105",6,"Subí al hospital del amor,\ncalma le pedí a Cupido,\ny me recetó el doctor\ncataplasmas del olvido,\ncáustico de un nuevo amor,\npero seguido, seguido.",108,2,8,127,"Estrofa suelta",9,6,"io",101,0,-1,0,395,395,"5105","",0,"","","",1,0,0,[],""],["frenk_t2-n5106",6,"Mariquita ya no quiere\nlavarme ese pañuelito:\nahora está lava que lava\nlos pañales del chiquito.",105,2,-1,127,"Mariquita",0,4,"io",119,0,-1,0,395,395,"5106","",0,"","","",1,0,0,[],""],["frenk_t2-n5107",6,"Los caminos ’stán muy malos,\nlas vacas los han batido:\nmi chinita no me quiere\nporque ando muy definido.",115,2,3,127,"El vaquero",0,4,"io",101,0,-1,0,396,396,"5107","",0,"","","",1,0,0,[],""],["frenk_t2-n5108",6,"Andan más recio las vacas\nque el caballo del vaquero;\nmi chinita no me quiere\nporque ando en atascadero.",115,2,3,127,"El vaquero",0,4,"eo",38,0,-1,0,396,396,"5108","",0,"","","",1,0,0,[],""],["frenk_t2-n5109",6,"Ya la higuera se secó,\ntiene la raíz de fuera;\nmi prietita no me quere\nporque ando en la borrachera.",105,2,-1,127,"La higuera",0,4,"ea",44,0,-1,0,396,396,"5109","",0,"","","",1,0,0,[],""],["frenk_t2-n5110",6,"La pobreza no me ayuda,\npara ser bien atendido:\nyo enamoré a una viuda;\nno fui correspondido\npor una maldita cruda.",113,2,2,127,"El querreque",7,5,"ua",144,0,-1,0,396,396,"5110","",0,"","","",1,0,0,[],""],["frenk_t2-n5111",6,"Siempre que me emborracho,\nyo nada más pienso en ella,\ny no me tranquilizo\nhasta acabar la botella.",105,2,-1,127,"Siempre, siempre",0,4,"ea",6,0,-1,0,396,396,"5111","",0,"","","",2,0,0,[],""],["frenk_t2-n5112",6,"Poderoso San Bernárdico,\nsolivíame estas cadénicas,\nporque me ando emborrachándico\ncon las muchachas ajénicas.",105,2,-1,127,"El tagarno",0,4,"ea",579,0,-1,0,396,396,"5112","",0,"","","",1,0,0,[],""],["frenk_t2-n5113",6,"Yo sufrí por un amor\ntodita una noche entera,\ny me decía: “No, señor,\n¿qué es fuerza el que yo le quiera?”",105,2,-1,127,"Estrofa suelta",1,4,"ea",44,0,-1,0,396,396,"5113","",0,"","","",1,0,0,[],""],["frenk_t2-n5114",6,"Cuando tuve una novia,\ny era una güera,\nella dormía por dentro (cielito lindo),\ny yo por fuera:\n¡qué desconsuelo!,\nella dormía en la cama (cielito lindo),\ny yo en el suelo.",113,2,2,127,"Cielito lindo",4,7,"eo",10,0,-1,0,396,396,"5114","",0,"","","",1,0,0,[],""],["frenk_t2-n5115a",6,"Cupido me dio su espada\npara entrar en su aposento;\ny me dijo el camarada:\n“No procure usted su intento,\nno se puede, que es casada.”",105,2,-1,127,"El Cupido",7,5,"aa",49,0,-1,0,396,396,"5115a","",0,"","","",2,0,0,[],""],["frenk_t2-n5116a",6,"Me enamoré de una monja\npor tener amor bendito;\nla monja se condenó,\ny a mí me faltó poquito.",105,2,-1,127,"La Sanmarqueña; El borrachito",0,4,"io",119,0,-1,0,397,397,"5116a","",0,"","","",2,0,0,[],""],["frenk_t2-n5117a",6,"Me enamoré estando preso\nde una que vide pasar;\nme quiso chillar un beso,\npero me puse a pensar.",105,2,-1,127,"El conejo",1,4,"a",21,0,-1,0,397,397,"5117a","",0,"","","",2,0,0,[],""],["frenk_t2-n5118",6,"Yo me quería casar\ncon una muchacha tierna,\npero me he puesto a pensar\nque si no me sale buena,\nque el diablo nos va a llevar,\no le arranco las melenas.",106,2,4,127,"El siquisirí; El Balajú",9,6,"ea",-1,0,-1,0,397,397,"5118","",0,"","","",2,0,0,[],""],["frenk_t2-n5120",6,"A la una yo nací,\na las dos me bauticé,\na las tres me enamoré,\ny a las cuatro me casé.",107,2,11,127,"Estrofa suelta",0,4,"e",77,0,-1,0,397,397,"5120","",0,"","","",2,0,0,[],""],["frenk_t2-n5122",6,"Y a una india muy regular\nle dije mi sentimiento;\nporque yo le daba un real,\ndijo que era yo un hambriento:\n¡pos cuánto le había de dar,\nmirando cómo está el tiempo!",105,2,-1,127,"La indita; El turronero; Estrofa suelta",9,6,"eo",-1,0,-1,0,398,398,"5122","",0,"","","",1,0,0,[],""],["frenk_t2-n5123",6,"Yo pretendí a una mujer,\nde esas que usan el copete,\ny al llegarla a pretender\nme despachó como un cohete,\ny me dice al responder:\n“No hay pan, muchachito, vete.”",105,2,-1,127,"El siquisirf’",9,6,"ee",285,0,-1,0,398,398,"5123","",0,"","","",4,0,0,[],""],["frenk_t2-n5124a",6,"Yo enamoré una catrina,\nde esas que usan polizón;\nme dijo la muy indina:\n“Yo no lo quiero pelón,\nyo lo quiero de leontina,\nde chaqueta y pantalón.”",105,2,-1,127,"Zapateado",9,6,"o",31,0,-1,0,398,398,"5124a","",0,"","","",1,0,0,[],""],["frenk_t2-n5125",6,"Me despreció una mujer\nporque me vio mal vestido,\npero al punto le hice ver\nque en este mundo aburrido\ntenemos que fallecer\nasí como hemos nacido.",108,2,8,127,"El siquisirí; La morena; Estrofa suelta",9,6,"io",101,0,-1,0,398,398,"5125","",0,"","","",3,0,0,[],""],["frenk_t2-n5126",6,"Me despreció una catrina\nandando en mi borrachera,\ny me contestó la indina:\n“Déjese usted de tonteras,\nque ahora la ropa fina\nno se la pone cualquiera.”",105,2,-1,127,"El siquisirí",9,6,"ea",-1,0,-1,0,398,398,"5126","",0,"","","",1,0,0,[],""],["frenk_t2-n5127",6,"Andando en mi borrachera\nme pretendió una mujer,\nme dijo: “Déjese usted de tonteras,\nque acaba de amanecer,\nque ahora la ropa fina\nno se puede ya coser.”",105,2,-1,127,"El siquisirí",9,6,"e",20,0,-1,0,398,398,"5127","",0,"","","",1,0,0,[],""],["frenk_t2-n5128",6,"Con frecuencia me paseo\npor las calles de mi chata,\ny no alcanzo ese deseo\nque me traigo con la ingrata:\nme dicen que soy muy feo\ny no le cuadro a su tata.",105,2,-1,127,"Paula",9,6,"aa",74,0,-1,0,399,399,"5128","",0,"","","",1,0,0,[],""],["frenk_t2-n5129b",6,"Me dijo un día una mujer\nque por feo no me quería;\nal momento le hice ver\nque sería una tontería:\n¡me hubiera mandado a hacer,\ny a su gusto me tendría!",105,2,-1,127,"El siquisirí; El Balajú; La guacamaya; La morena, Zapateado",9,6,"ia",0,0,-1,0,399,399,"5129b","",0,"","","",1,0,0,[],""],["frenk_t2-n5130",6,"La viuda que yo tenía\náhi nomás se queja y se queja;\nque cuando más la quería\náhi nomás se va y me deja:\n¡maldita mi suerte mía!",112,2,6,127,"La leva",7,5,"ia",0,0,-1,0,399,399,"5130","",0,"","","",1,0,0,[],""],["frenk_t2-n5131",6,"Me gustan las calabazas,\nde las que produce el suelo,\npues calabazas de amor\nni me gustan, ni las quiero.",105,2,-1,127,"Las calabazas**",0,4,"eo",-1,0,-1,0,399,399,"5131","",0,"","","",1,0,0,[],""],["frenk_t2-n5132",6,"La otra tarde encontré a don Ignacio\ny me dijo se iba a bañar;\nyo le dije que estaba indispuesta,\ny que no lo podía acompañar.",105,2,-1,127,"Los baños*’",3,4,"a",21,0,-1,0,399,399,"5132","",0,"","","",1,0,0,[],""],["frenk_t2-n5133",6,"Allá va la que le digo,\nla que le digo, allá va:\nla que mancuerna a los hombres\ncon poca facilidad.",108,2,8,127,"Estrofa suelta, La víbora**",0,4,"a",-1,0,-1,0,399,399,"5133","",0,"","","",1,0,0,[],""],["frenk_t2-n5134",6,"Pero áhi no más, que una tarde\nde mi labor regresaba,\ncuando en brazos de otro amante,\n¡qué columpiadas se daba!",107,2,11,127,"La nopalera",0,4,"aa",28,0,-1,0,399,399,"5134","",0,"","","",1,0,0,[],""],["frenk_t2-n5135",6,"Yo vide crecer la milpa,\npa que otro comiera elotes;\nme madrugó con la miel,\ny yo toreé los jicotes.",107,2,11,127,"La nopalera",0,4,"oe",565,0,-1,0,399,399,"5135","",0,"","","",1,0,0,[],""],["frenk_t2-n5137",6,"No le hace que se me arranquen\ncuando yo me esté muriendo;\nlo que siento es dejar ’maca\npa que otro se esté meciendo.",108,2,8,127,"Estrofa suelta",0,4,"eo",52,0,-1,0,400,400,"5137","",0,"","","",1,0,0,[],""],["frenk_t2-n5138",6,"Subí a la torre más alta,\na ver si la divisaba;\nnada más vi el polvo\ndel hijo de la chingada\nque se la llevaba.",108,2,8,127,"Estrofa suelta",7,5,"aa",-1,0,-1,0,400,400,"5138","",0,"","","",1,0,0,[],""],["frenk_t2-n5139",6,"Me dio un perro una mordida,\nun burro me dio una coz,\nmi mujer se fue con otro:\n¡sea por el amor de Dios!",105,2,-1,127,"Estrofa suelta",0,4,"o",87,0,-1,0,400,400,"5139","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5140",6,"El pájaro carpintero\nsiempre vive apasionado;\náhi le responde el jilguero:\n“Hombre, vive con cuidado,\nque siendo yo carbonero\nuna mujer me ha tiznado.”",106,2,4,127,"El pájaro carpintero; El curripití; El querreque; Estrofa suelta",9,6,"ao",14,0,-1,0,400,400,"5140","",0,"","","",9,0,0,[],""],["frenk_t2-n5141",6,"¡Quién a mí me lo dijera,\nlo que me iba a suceder!\nQue siendo yo carbonero,\nuna mujer me tiznó.",105,2,-1,127,"El carbonero",5,4,"o",-1,0,-1,0,400,400,"5141","",0,"","","",1,0,0,[],""],["frenk_t2-n5142",6,"Pa cuando se casen, les cuento este cuento,\njóvenes y viejos, oigan lo que siento:\nMaría la que ardía y María la fría\nme hicieron tamales de chivo y lejía.",115,2,3,127,"Las dos Marías",3,4,"ia",0,0,-1,0,401,401,"5142","",0,"","","",1,0,0,[],""],["frenk_t2-n5143",6,"Aquí se acaban los versos\nde “El amor y el desafío”;\nla niña se fue con otro,\ny yo me quedé chiflando:\nfío, fío, fío, fío, fío.",105,2,-1,127,"El amor y el desafío",7,5,"io",3,0,-1,0,401,401,"5143","",0,"","","",3,0,0,[],""],["frenk_t2-n5144",6,"Al salir de Guadalajara\nme traje una taparía,\npero la muy picarona\nme abandonó al otro día.",105,2,-1,127,"El tapatío",0,4,"ia",0,0,-1,0,401,401,"5144","",0,"","","",1,0,0,[],""],["frenk_t2-n5145",6,"¡Ah, qué ingrata fue Juanita!,\nsin motivo me largó;\nse pronunció mi güerita\npor tres días que no comió.",105,2,-1,127,"Estrofa suelta",1,4,"o",2,0,-1,0,401,401,"5145","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5146",6,"Amigo, voy a contarte\nlo que me pasó en Morelia:\nque ya me corrió Silveria\na echar pulgas a otra parte.",105,2,-1,127,"Estrofa suelta",5,4,"ae",8,0,-1,0,401,401,"5146","",0,"","","",1,0,0,[],""],["frenk_t2-n5147",6,"Yo me quiero enamorar\ncon un amor verdadero;\nla preciosa se logró\nllevarse todito mi dinero.",113,2,2,127,"Estrofa suelta",3,4,"eo",38,0,-1,0,401,401,"5147","",0,"","","",1,0,0,[],""],["frenk_t2-n5148",6,"Me enamoré de un güerito\npor verlo tan lindo mozo,\npero ¡ay, qué tal de güerito!,\nme dejó hasta sin rebozo.",105,2,-1,127,"Los papaquis",1,4,"oo",156,0,-1,0,401,401,"5148","",0,"","","",1,0,0,[],""],["frenk_t2-n5149",6,"Me enamoré de un catrín\npor ver si me remediaba,\npero ¡ay, qué pobre catrín!,\ntodos los crías ayunaba.",114,2,17,127,"Los papaquis",1,4,"aa",28,0,-1,0,401,401,"5149","",0,"","","",1,0,0,[],""],["frenk_t2-n5150",6,"Me enamoré de un ranchero\npor ver si me daba elotes,\npero el ingrato ranchero\nme daba puros azotes.",105,2,-1,127,"Allá en el Rancho Grande; Los papaquis",1,4,"oe",565,0,-1,0,401,401,"5150","",0,"","","",1,0,0,[],""],["frenk_t2-n5151",6,"Cuando estábamos de novios,\ntoda mi vida era un juguete;\nahora que estamos casados,\nya no podemos con el paquete.",105,2,-1,127,"Antes y después",3,4,"ee",285,0,-1,0,402,402,"5151","",0,"","","",6,0,0,[],""],["frenk_t2-n5152",6,"Cuando estábamos de novios,\nlingo lilingo, ¡cuántos abrazos!\nAhora que estamos casados,\nno más me runfan los zapatazos.",105,2,-1,127,"Antes y después",3,4,"ao",-1,0,-1,0,402,402,"5152","",0,"","","",6,0,0,[],""],["frenk_t2-n5153",6,"Cuando estábamos de novios,\n¡qué de listones, qué de mascadas!\nAhora que estamos casados,\n¡qué de moquetes, qué de patadas!",105,2,-1,127,"Antes y después’",3,4,"aa",282,0,-1,0,402,402,"5153","",0,"","","",6,0,0,[],""],["frenk_t2-n5154",6,"Cuando estábamos de novios,\n¡qué de besitos, qué de apretones!\nAhora que estamos casados,\n¡qué maltratadas, qué moretones!",105,2,-1,127,"Antes y después",3,4,"oe",34,0,-1,0,402,402,"5154","",0,"","","",6,0,0,[],""],["frenk_t2-n5155",6,"Cuando yo me casé,\n¡qué de ramos, qué de flores!,\ny ahora que ya estoy casada,\n¡qué empujones, qué aventones!",110,2,10,127,"La recién casada",3,4,"oe",-1,0,-1,0,402,402,"5155","",0,"","","",4,0,0,[],""],["frenk_t2-n5156",6,"¿Para qué quiero cruces\nen mi rosario (¡zamba, que le da!),\nsi con mi negra tengo\ncruz y calvario? (¡zamba, que le da!).",109,2,7,127,"La zamba; Anda, niña, nada, niña.. Negra del alma; Estrofa suelta",3,4,"a",25,0,-1,0,402,402,"5156","",0,"","","",1,0,0,[],""],["frenk_t2-n5157",6,"—¡Qué bonita está la plaza!,\nviejito, ¿me dejas ir?\n—Esté fea o esté bonita,\ntú a la plaza no me has de ir.",115,2,3,127,"El matrimonio desigual",0,4,"i",-1,0,-1,0,402,402,"5157","",0,"","","",1,0,0,[],""],["frenk_t2-n5158",6,"—Viejito, vamos a misa,\nque la acaban de llamar.\n—No las quiero tan devotas:\nsiéntese ahí a remendar.",115,2,3,127,"El matrimonio desigual",0,4,"a",21,0,-1,0,402,402,"5158","",0,"","","",1,0,0,[],""],["frenk_t2-n5159",6,"—¡Válgame Dios de los cielos!,\n¿qué haré yo con este viejo?\n—Me ha de amar, me ha de querer,\ny me ha de ver como un espejo.",115,2,3,127,"El matrimonio desigual",0,4,"eo",264,0,-1,0,402,402,"5159","",0,"","","",33,0,0,[],""],["frenk_t2-n5160",6,"Cuando yo me casé\nmi madre dijo así:\n“Hija, ya te casaste,\n¡ay, infeliz de ti!”",112,2,6,127,"La recién casada",0,4,"i",23,0,-1,0,403,403,"5160","",0,"","","",4,0,0,[],""],["frenk_t2-n5162",6,"Ya se reventó el alambre\ndonde se mecía Cupido;\ncómo haré para olvidarla,\nsi amarla no he podido.",108,2,8,127,"Estrofa suelta",0,4,"io",101,0,-1,0,403,403,"5162","",0,"","","",2,0,0,[],""],["frenk_t2-n5163",6,"Una muchacha de aquí\nme dijo que me la lleve;\npero yo le digo así:\n“¿Con qué te tapo si llueve?,\nque hasta el jorongo perdí,\npor andar entre la plebe.”",113,2,2,127,"La Malagueña; El borracho; Estrofa suelta",9,6,"ee",82,0,-1,0,403,403,"5163","",0,"","","",1,0,0,[],""],["frenk_t2-n5164a",6,"Me dijo una presumida\nque la llevara a pasear,\ny yo le dije: “Mi vida,\nprimero vete a pintar,\nque estás muy descolorida.”",106,2,4,127,"La presumida",7,5,"ia",37,0,-1,0,403,403,"5164a","",0,"","","",5,0,0,[],""],["frenk_t2-n5164b",6,"Me dijo una presumida\nque la llevara a pasear,\ny yo le dije: “Mi vida,\nprimero vete a pintar,\npues ya sabes, vida mía,\nque a la gente vas a espantar.”",106,2,4,127,"La presumida",9,6,"a",21,0,-1,0,403,403,"5164b","",0,"","","",5,0,0,[],""],["frenk_t2-n5165",6,"Me dijo una presumida\nque por cuánto la paseaba;\ny yo le dije: “Mi vida”,\nque no le costaba nada,\nque se echara agua florida\npara que se perfumara.",112,2,6,127,"La presumida",9,6,"aa",-1,0,-1,0,403,403,"5165","",0,"","","",5,0,0,[],""],["frenk_t2-n5167",6,"Yo pretendía a una morena\nque le gustaba el mal trato;\nque decían que era muy buena,\nque no quebraba ni un plato:\nlos quebraba por docena,\ny decía que eran los gatos.",106,2,4,127,"La morena",9,6,"ao",-1,0,-1,0,404,404,"5167","",0,"","","",1,0,0,[],""],["frenk_t2-n5168",6,"Yo pretendí a una casada\ncon palabras muy sencillas,\ny me dice la malvada:\n“Mis piernas de vello brillan”,\ny las tenía más peladas\nque chicote de Castilla.",108,2,8,127,"El siquisirí",9,6,"ia",-1,0,-1,0,404,404,"5168","",0,"","","",2,0,0,[],""],["frenk_t2-n5169",6,"Me creí de una pelona\nen momentos de torpeza,\ny en la noche me picaban\nlos bichos de su cabeza.",105,2,-1,127,"El vacilón",0,4,"ea",108,0,-1,0,404,404,"5169","",0,"","","",1,0,0,[],""],["frenk_t2-n5170",6,"Que me gusta esa mujer:\nvoy a ver si la consigo,\nporque me haga de comer,\naunque no duerma conmigo:\nque al llegar yo, esté servido.",106,2,4,127,"El lelito",7,5,"io",-1,0,-1,0,404,404,"5170","",0,"","","",2,0,0,[],""],["frenk_t2-n5171",6,"Yo me quisiera casar\ncon una que no comiera,\nque no supiera guisar,\nni tampoco se vistiera,\nque no saliera a pasear\ncuando la gente la viera.",106,2,4,127,"El Balajú",9,6,"ea",44,0,-1,0,404,404,"5171","",0,"","","",3,0,0,[],""],["frenk_t2-n5172",6,"Viniendo del otro lado,\ncorté una flor de pimienta.\nYo no quiero ser casado,\nporque no me tiene cuenta:\nquiero vivir solterito,\naunque yo pague la cuenta.",112,2,6,127,"La rosita arribeña",9,6,"ea",-1,0,-1,0,404,404,"5172","",0,"","","",3,0,0,[],""],["frenk_t2-n5173",6,"Quisiera tener la dicha,\nla dicha que el gallo tiene,\nde tener muchas gallinas,\ny a ninguna la mantiene.",106,2,4,127,"La bamba",0,4,"ee",70,0,-1,0,404,404,"5173","",0,"","","",1,0,0,[],""],["frenk_t2-n5174a",6,"Yo tuve una mujer (cielito lindo),\nque me decía\nque cuando la olvidara\nse moriría;\nmas no fue cierto,\nporque yo la olvidé (cielito lindo),\ny no se ha muerto.",106,2,4,127,"Cielito lindo",4,7,"eo",88,0,-1,0,404,404,"5174a","",0,"","","",1,0,0,[],""],["frenk_t2-n5176",6,"Iba yo en una barca\ncon una cesta;\nmi madre me pregunta:\n—¿Qué fruta es ésta?\nY yo le digo:\n—Son unas calabazas (¡caramba!)\npara un amigo.",120,2,14,127,"Mal haya la cocina",4,7,"io",106,0,-1,0,405,405,"5176","",0,"","","",1,0,0,[],""],["frenk_t2-n5177",6,"Triste y desolada estoy\npor tener un novio tuerto,\nporque más me convendría\nque fuera del todo ciego.",105,2,-1,127,"Estrofa suelta",0,4,"eo",-1,0,-1,0,405,405,"5177","",0,"","","",1,0,0,[],""],["frenk_t2-n5178",6,"Mi marido está bendito,\ndesde San Antonio Abad;\npienso que ya no será\ntan zaragate y maldito.",105,2,-1,127,"Estrofa suelta",5,4,"io",119,0,-1,0,405,405,"5178","",0,"","","",1,0,0,[],""],["frenk_t2-n5179",6,"Mi marido se murió,\nel diablo se lo llevó;\nallá debe estar pagando\nlas mondas que aquí me dio.",110,2,10,127,"La viuda; Mi comadre; Estrofa suelta",0,4,"o",2,0,-1,0,405,405,"5179","",0,"frenk_t4","","",12,0,0,[],""],["frenk_t2-n5180",6,"Mi negrito se fue al monte,\nsabe si no volverá:\npor vida tuya, coyote,\ncómetelo por allá.",110,2,10,127,"Por vida tuya, coyote",0,4,"a",9,0,-1,0,405,405,"5180","",0,"","","",1,0,0,[],""],["frenk_t2-n5181",6,"A la salida de misa\nte vi en la acera de enfrente;\nen tu agradable sonrisa\nte vi un frijol en el diente.",107,2,11,127,"Estrofa suelta",1,4,"ee",15,0,-1,0,406,406,"5181","",0,"","","",5,0,0,[],""],["frenk_t2-n5182",6,"Mestiza, diosa de Oriente,\nmestiza reina del sol,\npara que te veas decente,\nquita ese dzuc de frijol\nque te cubre todo el diente.",122,2,13,127,"Estrofa suelta",7,5,"ee",15,0,-1,0,406,406,"5182","",0,"","","",1,0,0,[],""],["frenk_t2-n5183",6,"Mestiza de cutis fino,\ncontigo sería feliz,\nsi arrancaras esos pelos de cochino\nque salen por tu nariz.",122,2,13,127,"Estrofa suelta",3,4,"i",335,0,-1,0,406,406,"5183","",0,"","","",1,0,0,[],""],["frenk_t2-n5184",6,"Del cielo cayó un pintor\npara pintar tu hermosura,\npero al verte tan greñuda\nse le cayó la pintura.",107,2,11,127,"Estrofa suelta",0,4,"ua",-1,0,-1,0,406,406,"5184","",0,"","","",1,0,0,[],""],["frenk_t2-n5185",6,"Quisiera ser pajarito\npara entrar por tu ventana\ny decirte muy quedito\nque tienes cara de rana.",107,2,11,127,"Estrofa suelta",1,4,"aa",4,0,-1,0,406,406,"5185","",0,"","","",4,0,0,[],""],["frenk_t2-n5186",6,"Al pasar por tu ventana\nme dijeron adiós;\nvolteé, y era un chango,\ny ese chango eras tú.",107,2,11,127,"Estrofa suelta",5,4,"u",-1,0,-1,0,406,406,"5186","",0,"","","",8,0,0,[],""],["frenk_t2-n5187",6,"Si a tu ventana llega\nun burro flaco,\ntrátalo con ternura,\nque es tu retrato.",114,2,17,127,"Estrofa suelta",6,4,"ao",-1,0,-1,0,406,406,"5187","",0,"","","",3,0,0,[],""],["frenk_t2-n5188",6,"Si a tu balcón llega\nun tecolote,\nráspale las narices\ncon un olote.",113,2,2,127,"Estrofa suelta",6,4,"oe",292,0,-1,0,407,407,"5188","",0,"","","",1,0,0,[],""],["frenk_t2-n5189",6,"El día que tú naciste\nnacieron los chicalotes\ny en la pila del bautizo\ncantaron los zopilotes.",107,2,11,127,"Las mañanitas",0,4,"oe",565,0,-1,0,407,407,"5189","",0,"","","",16,0,0,[],""],["frenk_t2-n5190",6,"Eres mi dulce panela,\neres mi deleite vino,\ntu frente sirve de suela,\ntu cuerpo para el molino.",105,2,-1,127,"Las mañanitas",1,4,"io",199,0,-1,0,407,407,"5190","",0,"","","",1,0,0,[],""],["frenk_t2-n5191",6,"Desde por allá abajo vengo,\narrastrando mi cobija;\ndale memorias a tu madre,\npatitas de lagartija.",108,2,8,127,"Estrofa suelta",0,4,"ia",219,0,-1,0,407,407,"5191","",0,"","","",1,0,0,[],""],["frenk_t2-n5192",6,"Una vez que te dije\nque iba a llover\nse te puso la cara\ncomo mujer.",106,2,4,127,"La bamba",6,4,"e",20,0,-1,0,407,407,"5192","",0,"","","",6,0,0,[],""],["frenk_t2-n5193",6,"Una vez que [te] dije\nque eras muy fea,\nse te puso la cara\ncomo batea.",106,2,4,127,"La bamba",6,4,"ea",54,0,-1,0,407,407,"5193","",0,"","","",6,0,0,[],""],["frenk_t2-n5194",6,"Cada vez que te miro\nme da un calambre,\nde verte yo esa cara\nde muerto de hambre.",105,2,-1,127,"La bamba",6,4,"ae",288,0,-1,0,407,407,"5194","",0,"","","",3,0,0,[],""],["frenk_t2-n5195",6,"Dicen que hueles a rosa,\nque hueles a follaje,\nmas al pasar por mi lado\nolías a puro drenaje.",107,2,11,127,"Estrofa suelta",0,4,"ae",231,0,-1,0,407,407,"5195","",0,"","","",1,0,0,[],""],["frenk_t2-n5196a",6,"No te lo pongo de rosa,\nporque no eres hermosa,\nte lo pongo de amarillo,\nporque hueles a zorrillo.",107,2,11,127,"Estrofa suelta",5,4,"io",228,0,-1,0,407,407,"5196a","",0,"","","",1,0,0,[],""],["frenk_t2-n5196c",6,"No te escribo en el azul\nporque no eres un baúl;\nno te escribo en el rosa\nporque no eres hermosa;\nte escribo en el amarillo\nporque hueles a zorrillo.",107,2,11,127,"Estrofa suelta",9,6,"io",228,0,-1,0,408,408,"5196c","",0,"","","",2,0,0,[],""],["frenk_t2-n5197",6,"Dime qué cosa te echaste,\nque te veo tan colorada;\nse me hace que te peinaste\ncon aceite de guayaba:\nque cuando te me acercaste\nmérito destornudaba.",108,2,8,127,"El siquisirí",9,6,"aa",28,0,-1,0,408,408,"5197","",0,"","","",3,0,0,[],""],["frenk_t2-n5199a",6,"Tus labios piden un beso,\ntus ojos una ilusión,\npero tu lindo pescuezo\npide estropajo y jabón.",130,2,21,127,"Estrofa suelta",1,4,"o",31,0,-1,0,408,408,"5199a","",0,"","","",1,0,0,[],""],["frenk_t2-n5200",6,"Desde aquí te estoy mirando,\nde adentro de la cocina;\ntu boquita como cuchi,\ny tus ojos de gallina.",108,2,8,127,"Estrofa suelta",0,4,"ia",11,0,-1,0,408,408,"5200","",0,"","","",20,0,0,[],""],["frenk_t2-n5201",6,"Tienes ojos de becerro,\nboca de coral,\nfuistes bajada del cielo\npor bruta y animal.",119,2,12,127,"Estrofa suelta",0,4,"a",1,0,-1,0,408,408,"5201","",0,"","","",1,0,0,[],""],["frenk_t2-n5202",6,"Ayer tarde fui a tu casa,\nme asomé por la ventana,\ny estabas haciendo gestos,\nsentada en la borcelana.",113,2,2,127,"El caimán viejo; Estrofa suelta",0,4,"aa",4,0,-1,0,408,408,"5202","",0,"","","",1,0,0,[],""],["frenk_t2-n5203",6,"Con los chinos de tu frente\nme mandastes a atar;\nsi esos chinos se revientan,\na tus nalgas voy a dar.",108,2,8,127,"Estrofa suelta",0,4,"a",21,0,-1,0,409,409,"5203","",0,"","","",5,0,0,[],""],["frenk_t2-n5204",6,"No me gustas por bonita,\nsino por tus ojos morenos;\nen teniendo buenas nalgas,\nlo demás es lo de menos.",128,2,30,127,"Estrofa suelta",0,4,"eo",365,0,-1,0,409,409,"5204","",0,"","","",1,0,0,[],""],["frenk_t2-n5205",6,"No te quiero por bonita,\nni tampoco por mujer,\nsólo por tus carretones:\nque me quiero mantener.",110,2,10,127,"Los carretones",0,4,"e",20,0,-1,0,409,409,"5205","",0,"","","",4,0,0,[],""],["frenk_t2-n5206a",6,"Yo me casara contigo,\npero ¿con qué te mantengo?\nSólo que comas zacate,\ncomo una burra que tengo.",105,2,-1,127,"El novillo despuntado; La burra elotera; María, María; La Sanmarqueña; Estrofa suelta",0,4,"eo",124,0,-1,0,409,409,"5206a","",0,"","","",1,0,0,[],""],["frenk_t2-n5207",6,"Ya con ésta me despido,\ny si escuchas un chiflido,\nno te vayas a asustar;\nándale, muía maicera,\nmétete pa la tranquera,\nque te quiero jinetear.",105,2,-1,127,"La muía maicera",9,6,"a",21,0,-1,0,409,409,"5207","",0,"","","",72,0,0,[],""],["frenk_t2-n5208",6,"Cuando yo te enamoré,\n¡quién sabe cómo sería!\nEl diablo se soltaría,\npues como ni batallé.",112,2,6,127,"El jarabe",11,4,"e",77,0,-1,0,409,409,"5208","",0,"","","",1,0,0,[],""],["frenk_t2-n5209",6,"Tú presumes de que eres bonita\nporque traes tu carita pintada:\nyo no puedo comprar una casa\nnada más con mirar la fachada.",105,2,-1,127,"El Pata Rajada",3,4,"aa",-1,0,-1,0,409,409,"5209","",0,"","","",1,0,0,[],""],["frenk_t2-n5210",6,"Yo no sé qué pedirte, de veras,\npa poder apreciar lo que vales;\nya no compro más costaleras\nsin saber lo que traen los costales.",105,2,-1,127,"El Pata Rajada",3,4,"ae",26,0,-1,0,409,409,"5210","",0,"","","",1,0,0,[],""],["frenk_t2-n5212",6,"Antes, que no te hablaba,\nme llenaba de pasión,\nahora que te conozco\nhasta te veo en mi televisión.",129,2,9,127,"Estrofa suelta",3,4,"o",31,0,-1,0,410,410,"5212","",0,"","","",1,0,0,[],""],["frenk_t2-n5213",6,"Cuando te conocí\nparecías una amapola;\nahora que estás aquí\npareces gato sin cola.",129,2,9,127,"Estrofa suelta",1,4,"oa",321,0,-1,0,410,410,"5213","",0,"","","",1,0,0,[],""],["frenk_t2-n5215",6,"Cuando te vi venir\nparecías Pedro Infante,\nahora que estás aquí\npareces un elefante.",129,2,9,127,"Estrofa suelta",0,4,"ae",47,0,-1,0,410,410,"5215","",0,"","","",2,0,0,[],""],["frenk_t2-n5217",6,"Áhi vienen los mecos,\nvienen de Tepí,\ny el meco más grande\nse parece a ti.",110,2,10,127,"Estrofa suelta, Los mecos",0,4,"i",23,0,-1,0,410,410,"5217","",0,"","","",1,0,0,[],""],["frenk_t2-n5218",6,"Enfrente de tu casa\nhay una enredadera;\n¿cómo quieres que te quiera,\nsi pareces calavera?",129,2,9,127,"Estrofa suelta",0,4,"ea",44,0,-1,0,410,410,"5218","",0,"","","",1,0,0,[],""],["frenk_t2-n5219",6,"Cuando me vengas a ver\nvente a gatas por el llano,\nque mi mama es cegatona\ny creerá que eres marrano",105,2,-1,127,"La suegra",0,4,"ao",81,0,-1,0,410,410,"5219","",0,"","","",1,0,0,[],""],["frenk_t2-n5220",6,"Me subí a un alto pino,\npor ver si te devisaba;\nno más alcancé a ver\nque el diablo te cargaba.",105,2,-1,127,"Estrofa suelta",0,4,"aa",28,0,-1,0,411,411,"5220","",0,"","","",2,0,0,[],""],["frenk_t2-n5221",6,"¡Mestiza, mestiza!,\na pesar de ser bonita,\ntú morirás señorita,\nporque no has tenido amores:\ncero hit, cero carreras, cero errores.",122,2,13,127,"Estrofa suelta",7,5,"oe",5,0,-1,0,411,411,"5221","",0,"","","",1,0,0,[],""],["frenk_t2-n5222",6,"—¿Para qué y para cuándo\nquieres el virgo?\n—Para cuando me case\ncon mi marido.",108,2,8,127,"Negra del alma",6,4,"io",-1,0,-1,0,411,411,"5222","",0,"","","",1,0,0,[],""],["frenk_t2-n5223",6,"Muchachas, ¿qué cosa piensan,\nque no se quieren casar?\nYa ven que cuando están viejas\nya no la pueden pegar:\nse jalan de las orejas\ny empiezan a repegar.",109,2,7,127,"Indita del alma",9,6,"a",21,0,-1,0,411,411,"5223","",0,"","","",1,0,0,[],""],["frenk_t2-n5224",6,"Señora, barra su patio\ny sacuda su guayabo,\nno se olvide que soy\nahora yo su esclavo.",105,2,-1,127,"La zamba",0,4,"ao",580,0,-1,0,411,411,"5224","",0,"","","",1,0,0,[],""],["frenk_t2-n5225",6,"Estás como mi vaca,\nreñaca, y no lo sabías,\npero si tú me quisieras,\nconmigo hasta engordarías.",105,2,-1,127,"La vieja presumida",0,4,"ia",214,0,-1,0,411,411,"5225","",0,"","","",1,0,0,[],""],["frenk_t2-n5226",6,"Hora lo verás, indita,\nyo te quitaré el ardid:\nque llegando a la garita,\nte he de cargar el fusil.",105,2,-1,127,"Estrofa suelta, La paloma",0,4,"i",-1,0,-1,0,411,411,"5226","",0,"","","",2,0,0,[],""],["frenk_t2-n5227",6,"Señora, su malacate\ntodo el hilo me enmaraña;\ncon un poco de cuidado\nse le quitará la maña.",105,2,-1,127,"El malacate",0,4,"aa",213,0,-1,0,411,411,"5227","",0,"","","",1,0,0,[],""],["frenk_t2-n5228",6,"¡Ay, madre, qué pan tan duro,\ny la manteca tan cara!\nSi yo fuera panadero,\na cogidas te lo ablandara.",108,2,8,127,"Estrofa suelta",0,4,"aa",57,0,-1,0,411,411,"5228","",0,"","","",1,0,0,[],""],["frenk_t2-n5230",6,"Aunque tu padre me diera\nlas mulas y el carretón,\nno me casara contigo,\nzancas de burro pelón.",110,2,10,127,"Estrofa suelta, La chicharra",0,4,"o",31,0,-1,0,412,412,"5230","",0,"","","",7,0,0,[],""],["frenk_t2-n5231",6,"Si tu mama no me quiere\nporque juego en los billares,\n¡si de allí sacó tu padre\npa llevarla a los altares!",105,2,-1,127,"El príncipe heredero",0,4,"ae",-1,0,-1,0,412,412,"5231","",0,"","","",2,0,0,[],""],["frenk_t2-n5232",6,"Si tu mama no me quiere\nporque tomo en las cantinas,\nque se acuerde que tu padre\nse caía en cada esquina.",105,2,-1,127,"El príncipe heredero",0,4,"ia",-1,0,-1,0,412,412,"5232","",0,"","","",2,0,0,[],""],["frenk_t2-n5233",6,"De arriba cayó una carta\nprendida con alfiler;\nno ganas ni pa cigarros,\ny ya quieres tener mujer.",106,2,4,127,"Estrofa suelta",0,4,"e",20,0,-1,0,412,412,"5233","",0,"","","",1,0,0,[],""],["frenk_t2-n5235",6,"No tienes ni pa'l tranvía (¡ay, mi bien!),\ny quieres tu Cadillac;\nno sabes tomar tequila,\ny quieres tomar coñac.",105,2,-1,127,"Goza, goza, mariposa",3,4,"a",581,0,-1,0,412,412,"5235","",0,"","","",1,0,0,[],""],["frenk_t2-n5236",6,"No sabes tocar guitarra (¡ay, mi bien!),\ny quieres tocar violín;\nno sabes “La cucaracha”,\ny quieres tocar Chopin.",105,2,-1,127,"Goza, goza, mariposa",3,4,"oi",-1,0,-1,0,412,412,"5236","",0,"","","",1,0,0,[],""],["frenk_t2-n5237",6,"Ya estará cebolla,\nya estará cilantro,\nya estará epazote:\n¡ni que olieras tanto!",105,2,-1,127,"Goza, goza, mariposa",0,4,"ao",-1,0,-1,0,412,412,"5237","",0,"","","",1,0,0,[],""],["frenk_t2-n5238",6,"¿Qué pensarías que soy tu jitomate?,\n¿qué pensarías que soy tu salsa verde?,\n¿Y qué diría ese infeliz tomate?,\n¿que aguacate le pido de pilón?",105,2,-1,127,"Las calabazas",3,4,"o",-1,0,-1,0,412,412,"5238","",0,"","","",1,0,0,[],""],["frenk_t2-n5239",6,"Ya no quiero de amor calabazas,\nporque a mi pecho le hiciste un chayote;\n¡y qué dirá ese infeliz ejote!,\n¿que un elote te pedía de pilón?",107,2,11,127,"Las calabazas",3,4,"o",-1,0,-1,0,413,413,"5239","",0,"","","",1,0,0,[],""],["frenk_t2-n5240",6,"Me pintates un violín,\nbien pintado y afinado:\nfilarmónica nacites,\ny eso mismo te has quedado.",105,2,-1,127,"La violinera",0,4,"ao",14,0,-1,0,413,413,"5240","",0,"","","",6,0,0,[],""],["frenk_t2-n5243",6,"¡Ah, qué chula eres Pachita!,\nme dan ganas de besarte;\nno más no quieras platita,\nporque puedo hasta patearte,\ny te irás con tu manita\ne echar pulgas a otra parte.",105,2,-1,127,"Estrofa suelta",9,6,"ae",8,0,-1,0,413,413,"5243","",0,"","","",1,0,0,[],""],["frenk_t2-n5244",6,"Si tú me haces tepeguaje,\nyo te hago tecomasuche;\ntú pensaste hacerme guaje,\npero yo te hice guamuche.",108,2,8,127,"Que comienzo, que comienzo",1,4,"ue",571,0,-1,0,413,413,"5244","",0,"","","",1,0,0,[],""],["frenk_t2-n5245",6,"Dices que ya no me quieres\nporque no traigo sombrero;\ntú tampoco traes fondo,\nmás que el puro tilanguero.",115,2,3,127,"El tilanguero",0,4,"eo",38,0,-1,0,413,413,"5245","",0,"frenk_t4","","",21,0,0,[],""],["frenk_t2-n5246",6,"Dices que ya no me quieres\nporque no traigo huaraches;\ntú tampoco no traes naguas,\nmás que dos puritos parches.",105,2,-1,127,"El tilanguero",0,4,"ae",-1,0,-1,0,413,413,"5246","",0,"","","",21,0,0,[],""],["frenk_t2-n5247",6,"Dices que ya no me quieres\nporque no traigo camisa;\ntú tampoco echas gordas,\ntodo está eso de mestiza.",115,2,3,127,"El tilanguero",0,4,"ia",420,0,-1,0,413,413,"5247","",0,"frenk_t4","","",21,0,0,[],""],["frenk_t2-n5249",6,"Asómate a la ventana,\nverás lo que andan vendiendo:\nlos calzones de tu novio,\nque son un puro remiendo.",105,2,-1,127,"Estrofa suelta",0,4,"eo",52,0,-1,0,414,414,"5249","",0,"","","",14,0,0,[],""],["frenk_t2-n5250",6,"Ese novio que tú tienes\nno puede llevarte a España,\nporque es tan pobre el muchacho,\nque hasta sin jabón se baña.",122,2,13,127,"Estrofa suelta",0,4,"aa",213,0,-1,0,414,414,"5250","",0,"","","",2,0,0,[],""],["frenk_t2-n5251",6,"Con este bueicito no aras:\nde veras, de veras no,\nporque un cuerno tiene gacho\ny el otro se le cayó.",114,2,17,127,"La mancomadora; La mulita; ro",0,4,"o",2,0,-1,0,414,414,"5251","",0,"","","",1,0,0,[],""],["frenk_t2-n5253",6,"¿Quién te llevó en las noches\npor las laderas,\nque te raspó con maña\nlas sentaderas?",105,2,-1,127,"El tamarindo",6,4,"ea",103,0,-1,0,414,414,"5253","",0,"","","",1,0,0,[],""],["frenk_t2-n5254",6,"¿Quién te puso los cuernos,\ncuernos de chivo,\npa que no se los quiten\na tu marido?",105,2,-1,127,"El tamarindo",6,4,"io",-1,0,-1,0,414,414,"5254","",0,"","","",1,0,0,[],""],["frenk_t2-n5255",6,"Anda, dile a tu marido\nque lo quiero conocer,\npa quitarle las de chivo\ny ponerle los de buey.",107,2,11,127,"El huizache",0,4,"e",-1,0,-1,0,414,414,"5255","",0,"","","",1,0,0,[],""],["frenk_t2-n5256",6,"En tu corral me cagué\ncreyendo que me querías;\npuesto que tú no me quieres,\nvenga la mierda, que es mía.",114,2,17,127,"Ahi te dejo ese davel",0,4,"ia",-1,0,-1,0,415,415,"5256","",0,"","","",1,0,0,[],""],["frenk_t2-n5257",6,"En tu puerta me cagué\nporque me pegó la gana;\náhi te dejo ese clavel\npa que lo huelas mañana.",114,2,17,127,"Ahi te dejo ese clavel; Estrofa suelta",0,4,"aa",4,0,-1,0,415,415,"5257","",0,"","","",1,0,0,[],""],["frenk_t2-n5258",6,"En el pueblo de Ocotlán\nme ha salido casamiento\ncon una muchacha guapa\ncon su cara de jumento.",105,2,-1,128,"La potranca",0,4,"eo",94,0,-1,0,416,416,"5258","",0,"","","",1,0,0,[],""],["frenk_t2-n5259",6,"Tiene sus dientes de oro,\ny con su brillo me engaña;\nyo la quiero abrazar,\npero se me hace que nunca se baña.",113,2,2,128,"Estrofa suelta",3,4,"aa",213,0,-1,0,416,416,"5259","",0,"","","",1,0,0,[],""],["frenk_t2-n5260",6,"En la orilla de un río\noyó una sirena trovar,\ny en su trovido decía:\n“Mi vieja apesta a zorrillo\npor no quererse bañar.”",113,2,2,128,"Estrofa suelta",7,5,"a",21,0,-1,0,416,416,"5260","",0,"","","",1,0,0,[],""],["frenk_t2-n5261",6,"Dile que sí, dile que sí,\ndile que cuando se bañe\nque se corte bien las uñas (negrita)\npara que ya no me arañe.",105,2,-1,128,"La guacamaya; El durazno",3,4,"ae",582,0,-1,0,416,416,"5261","",0,"","","",2,0,0,[],""],["frenk_t2-n5262",6,"Del cielo cayó un pañuelo\nbordado de corazones,\ny de uno de ellos venía\nLuisa colgada de sus calzones.",107,2,11,128,"Estrofa suelta",3,4,"oe",34,0,-1,0,416,416,"5262","",0,"","","",17,0,0,[],""],["frenk_t2-n5263",6,"Toda la calle pa’bajo\ntengo un espejo tendido,\nporque se mire mi chata\nlos cuernos que le han salido.",110,2,10,128,"Estrofa suelta, Cómo quieres que una luz",0,4,"io",101,0,-1,0,416,416,"5263","",0,"","","",1,0,0,[],""],["frenk_t2-n5265",6,"¿Por qué rechinas carreta?,\n¿porque te falta tu aceite?\nAsí rechina mi chata\ncuando toma su aguardiente.",114,2,17,128,"La carreta",0,4,"ee",-1,0,-1,0,417,417,"5265","",0,"","","",2,0,0,[],""],["frenk_t2-n5266",6,"Una novia que yo tuve\ntodas la efes tenía:\nera fea, flaca, floja,\nfrágil y fregona y fría.",105,2,-1,128,"Estrofa suelta",0,4,"ia",0,0,-1,0,417,417,"5266","",0,"","","",3,0,0,[],""],["frenk_t2-n5267",6,"Tuve una María, tan fría, tan fría,\nque parecía hielo de noche y de día;\ntuve otra María que ardía, que ardía,\nya hasta mantequita creo que le escurría.",115,2,3,128,"Las dos Marías",3,4,"ia",0,0,-1,0,417,417,"5267","",0,"","","",1,0,0,[],""],["frenk_t2-n5268",6,"Una morena me dijo\nque la llevara a Jalapa,\ny yo le dije: “Morena,\nanda y ve que te lleve tu tata.”",106,2,4,128,"La morena",3,4,"aa",-1,0,-1,0,417,417,"5268","",0,"","","",3,0,0,[],""],["frenk_t2-n5269",6,"Una morena me dijo\nque la llevara allá abajo,\ny yo le dije: “Morena,\nque te lleve quien te trajo.”",105,2,-1,128,"La morena; La Lloroncita",0,4,"ao",168,0,-1,0,417,417,"5269","",0,"","","",3,0,0,[],""],["frenk_t2-n5270",6,"Me casé con una ciega\npa ver si me la tanteaba,\npero la maldita ciega\nno veía, pero tentaba.",105,2,-1,128,"Estrofa suelta",1,4,"aa",28,0,-1,0,417,417,"5270","",0,"","","",1,0,0,[],""],["frenk_t2-n5272",6,"Cuando yo tenga mil pesetillas,\ncompro un terreno, cuatro vaquillas\ny una mujer;\ncon todos estos animalitos,\n¿qué más pudiera yo apetecer?",107,2,11,128,"Estrofa suelta",7,5,"e",20,0,-1,0,417,417,"5272","",0,"","","",1,0,0,[],""],["frenk_t2-n5273b",6,"Mi mujer y mi caballo\nse me perdieron a un tiempo;\nmi mujer, Dios la perdone\n—¡qué mujer, ni qué demonio!—:\nmi caballo es lo que siento.",105,2,-1,128,"Estrofa suelta",7,5,"eo",-1,0,-1,0,418,418,"5273b","",0,"","","",9,0,0,[],""],["frenk_t2-n5274b",6,"Al primer trueno de mayo\nse quedó mi casa sola;\nmi mujer y mi caballo\nlos dos pararon la cola:\nmi caballo es lo que siento,\nmi mujer es de la bola.",108,2,8,128,"Estrofa suelta",9,6,"oa",321,0,-1,0,418,418,"5274b","",0,"","","",2,0,0,[],""],["frenk_t2-n5275",6,"Ahora son tres guacamayas\nque se han quedado viudas,\nque cuando uno las pretende\nparece que les habla Judas.",106,2,4,128,"La guacamaya",0,4,"ua",577,0,-1,0,418,418,"5275","",0,"","","",1,0,0,[],""],["frenk_t2-n5276",6,"Hora que la vengo a ver,\ntoditas están en su luna:\nserá de tanto agarrar\npatitos en la laguna.",105,2,-1,128,"La india",0,4,"ua",56,0,-1,0,418,418,"5276","",0,"","","",1,0,0,[],""],["frenk_t2-n5277",6,"Al pasar por El Mocambo\nme salió una tamalera:\n“Mariachito, vales madre,\nsiquiera me la metieras.”",129,2,9,128,"Estrofa suelta",0,4,"ea",-1,0,-1,0,418,418,"5277","",0,"","","",1,0,0,[],""],["frenk_t2-n5278",6,"Yo ya no quiero esta vieja,\nporque es como la gata lora:\nsi se la meto, grita\ny si se la saco, llora.",108,2,8,128,"Estrofa suelta",0,4,"oa",107,0,-1,0,418,418,"5278","",0,"","","",1,0,0,[],""],["frenk_t2-n5279",6,"Esta sí ya es pendejada\ny sobrada car ajera:\nella cogiendo en su cama,\ny tú pendejeando afuera.",108,2,8,128,"Estrofa suelta",0,4,"ea",44,0,-1,0,418,418,"5279","",0,"","","",1,0,0,[],""],["frenk_t2-n5280",6,"Con las barbas de Carranza\nvoy a hacer un estropajo,\npara lavarle a las viejas\nde la cintura pa abajo.",107,2,11,128,"La Sanmarqueña; Estrofa suelta",0,4,"ao",168,0,-1,0,419,419,"5280","",0,"","","",2,0,0,[],""],["frenk_t2-n5281",6,"Toda la noche he soñado\nen el sabio Salomón,\nque reunió sus mil mujeres\nsin darles un bofetón.",115,2,3,128,"La chinita",0,4,"o",31,0,-1,0,419,419,"5281","",0,"","","",1,0,0,[],""],["frenk_t2-n5282a",6,"Ya me voy a despedir,\npara que se acabe el son;\nyo a la que le agarro tiña,\ny hasta verla con bordón.",105,2,-1,128,"Los maderistas",0,4,"o",31,0,-1,0,419,419,"5282a","",0,"","","",13,0,0,[],""],["frenk_t2-n5283",6,"Ya el águila real voló\na los campos más estrechos,\ny el gorrión le respondió:\n“¿De quién serán esos pechos?\nEsos me los mamo yo,\naunque pague los derechos.”",105,2,-1,129,"Ya el águila real voló; El huerfanito",9,6,"eo",583,0,-1,0,420,420,"5283","",0,"","","",5,0,0,[],""],["frenk_t2-n5284",6,"La primera vez que aquí\nen esta casita canto:\n¡ay, lástima de ese pecho!,\n¿quién se lo estará chupando?",105,2,-1,129,"Soy de Zacatula",0,4,"ao",-1,0,-1,0,420,420,"5284","",0,"","","",1,0,0,[],""],["frenk_t2-n5285",6,"Mujeres, ¿pa dónde van,\nque aquí yo las voy siguiendo?\n¡Ay, lástima de ese pan!,\n¿quién se lo estará comiendo?",105,2,-1,129,"Soy de Zacatula",1,4,"eo",52,0,-1,0,420,420,"5285","",0,"","","",1,0,0,[],""],["frenk_t2-n5286",6,"Y al subir una escalera\nte vi las medias azules,\ny más arriba te vi\nsábado, domingo y lunes.",108,2,8,129,"La Sanmarqueña; Estrofa suelta",0,4,"ue",-1,0,-1,0,420,420,"5286","",0,"","","",1,0,0,[],""],["frenk_t2-n5287",6,"Cada vez que te miro\nse me endereza\nla pupila del ojo\npor tu belleza.",106,2,4,129,"La bamba",6,4,"ea",108,0,-1,0,420,420,"5287","",0,"huambachano","","",3,0,0,[],""],["frenk_t2-n5288",6,"En esta calle derecha\nestá un espejo tendido\npara poderte ver la cara\ny tus chinos que te han crecido.",112,2,6,129,"Estrofa suelta",0,4,"io",101,0,-1,0,420,420,"5288","",0,"","","",3,0,0,[],""],["frenk_t2-n5289",6,"Con tu cuerpo de turix\neres linda cual ninguna;\nsólo falta una laguna\npa remojarte el pirix.",122,2,13,129,"Estrofa suelta",11,4,"i",584,0,-1,0,420,420,"5289","",0,"","","",1,0,0,[],""],["frenk_t2-n5290",6,"Por abajo corre el agua,\npor arriba la corriente;\nmuchachas de tierra fría,\nvamos a tierra caliente.",109,2,7,129,"Por abajo corre el agua’*",0,4,"ee",15,0,-1,0,421,421,"5290","",0,"","","",1,0,0,[],""],["frenk_t2-n5291",6,"Yo soy de tierra caliente;\nsi quieres darle un quemón,\nvamos a darnos un entre,\npero sin obligación.",105,2,-1,129,"La buna elotera",0,4,"o",31,0,-1,0,421,421,"5291","",0,"","","",1,0,0,[],""],["frenk_t2-n5292",6,"Me llamaste viejo y soy\nde lo mero del Bajío;\nmuy caliente es lo que estoy:\nsi quieres, me voy al río.",105,2,-1,129,"Los vaqueros",1,4,"io",3,0,-1,0,421,421,"5292","",0,"","","",1,0,0,[],""],["frenk_t2-n5293",6,"¡Ay, Soledad, Soledad!,\nSoledad, llévame al río,\na lavarme la cabeza,\ny me darás lo que es mío.",105,2,-1,129,"La Petenera",0,4,"io",3,0,-1,0,421,421,"5293","",0,"","","",18,0,0,[],""],["frenk_t2-n5294",6,"Negrita, tus ojos son\nlos que me ponen mal modo;\nsi algo te han dicho de mí,\n¿por qué no me das de todo?",105,2,-1,129,"La calandria; La Sanmarqueña",0,4,"oo",261,0,-1,0,421,421,"5294","",0,"","","",3,0,0,[],""],["frenk_t2-n5295",6,"Señora, su periquito\nme quiere llevar al río,\ny yo le digo que fio,\nporque me muero de frío.",114,2,17,129,"El perico; La cachucha; El jarabe",0,4,"io",3,0,-1,0,421,421,"5295","",0,"","","",8,0,0,[],""],["frenk_t2-n5296",6,"Señora, su periquito\nme quiere llevar al mar;\nyo ya le dije que no,\nporque yo no sé nadar.",105,2,-1,129,"El perico",0,4,"a",21,0,-1,0,421,421,"5296","",0,"","","",8,0,0,[],""],["frenk_t2-n5297",6,"Ya están tocando la queda:\n¿qué hace usted, que no se va?\nNo sea que entre mi marido\ny encuentre abierto el zaguán.",105,2,-1,129,"Chula la mañana",0,4,"a",-1,0,-1,0,421,421,"5297","",0,"","","",1,0,0,[],""],["frenk_t2-n5298",6,"Morena, venme a rascar:\nme picó un mosco en el río;\ny vamos a disfrutar\nyo lo tuyo y tú lo mío,\ncomo en Cuquío.",105,2,-1,129,"El mosco",7,5,"io",3,0,-1,0,421,421,"5298","",0,"","","",1,0,0,[],""],["frenk_t2-n5300",6,"A mí me picó un mosquito\nmás abajo de la ceja;\nno siento tanto el piquete,\nsino la roncha que deja.",105,2,-1,129,"El turronero; Estrofa suelta",0,4,"ea",165,0,-1,0,422,422,"5300","",0,"","","",2,0,0,[],""],["frenk_t2-n5301",6,"—¿Qué de veras, Miramón?\n—Como te lo digo, Concha:\nque en Veracruz hay un mosco\nque cuando pica hace roncha.",105,2,-1,129,"Estrofa suelta",0,4,"oa",532,0,-1,0,422,422,"5301","",0,"","","",1,0,0,[],""],["frenk_t2-n5302",6,"¡Y ay, Soledad, que te pica el bicho!,\n¡ay, Soledad, que te pica el mosco!;\n¡y ay, Soledad, que me pones loco!,\n¡ay, Soledad, que te pica el...!",106,2,4,129,"Los artilleros",3,4,"e",-1,0,-1,0,422,422,"5302","",0,"","","",1,0,0,[],""],["frenk_t2-n5303",6,"Si te pica el pica pica,\nel polvito no lo vendo:\nque el remedio yo lo tengo;\nte diré cómo se aplica,\npa que vayas aprendiendo.",113,2,2,129,"El pica, pica",7,5,"eo",-1,0,-1,0,422,422,"5303","",0,"","","",1,0,0,[],""],["frenk_t2-n5304",6,"¡Cuidado, señora,\nno meta la mano!\nporque si la mete,\nle pica el gusano.",115,2,3,129,"El gusano’",0,4,"ao",81,0,-1,0,422,422,"5304","",0,"","","",1,0,0,[],""],["frenk_t2-n5306",6,"Un pescador pescaba un día,\npescaba el pez y no lo cogía;\nasí tú, vida mía,\nsi fueras pescado,\nnunca te cogería.",108,2,8,129,"Estrofa suelta",7,5,"ia",0,0,-1,0,422,422,"5306","",0,"","","",1,0,0,[],""],["frenk_t2-n5307",6,"Y esta noche es cuando\nte he de experimentar:\nsi sabes querer,\nsi sabes amar.",106,2,4,129,"Los arrieros",0,4,"a",21,0,-1,0,423,423,"5307","",0,"","","",1,0,0,[],""],["frenk_t2-n5308",6,"Dame lo que yo te pido,\nque no te pido la vida:\nde la cintura pa abajo,\nde las rodillas pa arriba.",107,2,11,129,"La Sanmarqueña; Soy de Zacatula; Estrofa suelta",0,4,"ia",-1,0,-1,0,423,423,"5308","",0,"","","",3,0,0,[],""],["frenk_t2-n5309",6,"Soy viejo, y me atrevería\na regar tu linda huerta;\nentonces ya quedaría\nmi alma satisfecha.",108,2,8,129,"Estrofa suelta",0,4,"ea",-1,0,-1,0,423,423,"5309","",0,"","","",1,0,0,[],""],["frenk_t2-n5310",6,"Las flores de tu jardín\nse empiezan a marchitar:\n¿quieres darme el trabajo\nde que las vaya a regar?",107,2,11,129,"Estrofa suelta",0,4,"a",21,0,-1,0,423,423,"5310","",0,"","","",1,0,0,[],""],["frenk_t2-n5311",6,"Señora, su palo verde\nya se le estaba secando;\ny anoche se lo regué,\ny hoy le amaneció floreando.",114,2,17,129,"El palo verde",3,4,"ao",33,0,-1,0,423,423,"5311","",0,"","","",1,0,0,[],""],["frenk_t2-n5312",6,"Señora, de su sandía\nle daré una rebanada,\nque agua se me hace la boca\nal verla tan colorada.",105,2,-1,129,"El jarabe",0,4,"aa",49,0,-1,0,423,423,"5312","",0,"","","",1,0,0,[],""],["frenk_t2-n5313",6,"Yo no soy hombre bizarro,\npretendo mujer bonita;\nprésteme usted su lumbrita\npara encender mi cigarro.",112,2,6,129,"La presumida",11,4,"ao",392,0,-1,0,423,423,"5313","",0,"","","",1,0,0,[],""],["frenk_t2-n5314",6,"Indita, por un trabajo\nme cobraste cuatro reales;\nindita, no seas tan cara:\nyo puse los materiales.",105,2,-1,129,"La indita; Limoncito",0,4,"ae",26,0,-1,0,423,423,"5314","",0,"","","",1,0,0,[],""],["frenk_t2-n5315",6,"Señora, su periquito\nme gusta por colorado:\náhi verá si me lo vende\no me lo da regalado.",114,2,17,129,"El perico",0,4,"ao",14,0,-1,0,423,423,"5315","",0,"frenk_t4","","",8,0,0,[],""],["frenk_t2-n5317",6,"María, tero, lero, lé,\nel chocolatito con pan francés;\nen mi casa no lo tomo\nporque no tengo con qué,\npero si usted me lo bate,\ncon gusto lo tomaré.",106,2,4,129,"La tarasca",9,6,"e",77,0,-1,0,424,424,"5317","",0,"","","",1,0,0,[],""],["frenk_t2-n5318",6,"María, lero, lero, lina,\nchocolatito con masa fina;\nen mi casa no lo tomo\nporque no quiere mi china,\npero si usted me lo bate,\ny a tomar me determina.",106,2,4,129,"La tarasca",9,6,"ia",11,0,-1,0,424,424,"5318","",0,"","","",1,0,0,[],""],["frenk_t2-n5319",6,"Mande usté a su servicial,\nque me sirva el chocolate;\ncaliente me lo ha de dar:\nno se lo pido de gratis;\nno es culpa de quien lo bate.",106,2,4,129,"La tarasca",7,5,"ae",384,0,-1,0,424,424,"5319","",0,"","","",1,0,0,[],""],["frenk_t2-n5320",6,"Señora, su conejito\nya no le gusta el zacate;\nsólo quiere chocolate:\n¡qué animal tan picudito!",118,2,27,129,"Estrofa suelta",11,4,"io",119,0,-1,0,424,424,"5320","",0,"","","",1,0,0,[],""],["frenk_t2-n5321",6,"Hazme mi choco, choco,\nhazme mi chocolate,\ny corre la caldereta\ny bate que bate.",106,2,4,129,"El cuervito",0,4,"ae",384,0,-1,0,424,424,"5321","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5322",6,"Y hazte pa allá,\ny hazte pa acá,\n¡ay, qué caramba,\nqué bueno está!",105,2,-1,129,"Los panaderos",6,4,"a",9,0,-1,0,424,424,"5322","",0,"","","",1,0,0,[],""],["frenk_t2-n5323",6,"¡Arriba la panadera,\narriba y a trabajar!\nComo la harina sea buena,\nbuenos molletes saldrán.",117,2,5,129,"La panadera",0,4,"a",-1,0,-1,0,424,424,"5323","",0,"","","",1,0,0,[],""],["frenk_t2-n5324",6,"Estoy que de frío reniego\ny de un colchón tengo gana;\ntrasquila, mi alma, al borrego,\nque yo varearé la lana,\ny verás la obra que entriego.",105,2,-1,129,"Estrofa suelta",7,5,"eo",29,0,-1,0,425,425,"5324","",0,"","","",1,0,0,[],""],["frenk_t2-n5325",6,"Ciérrate, bonita,\ncomo yo me cierro:\ntú serás la vaca,\nyo seré el becerro.",108,2,8,129,"La Malagueña curreña; Estrofa",0,4,"eo",379,0,-1,0,425,425,"5325","",0,"","","",1,0,0,[],""],["frenk_t2-n5326",6,"Date gusto, vida mía,\nque yo me daré otro tanto:\nno vaya a ser que algún día\nel gusto se vuelva llanto.",115,2,3,129,"El gusto",1,4,"ao",30,0,-1,0,425,425,"5326","",0,"","","",1,0,0,[],""],["frenk_t2-n5327",6,"En este mundo de broza\ntodo se convierte en nada.\nUsted no me sea miedosa,\nque en esta vida apretada\nes un tonto el que no goza.",108,2,8,129,"La guacamaya",7,5,"oa",195,0,-1,0,425,425,"5327","",0,"","","",1,0,0,[],""],["frenk_t2-n5328",6,"No se haga rosca, preciosa,\nque al cabo sernos paisanos;\n¿ya no se acuerda del maíz\nque juntitos cultivamos?",105,2,-1,129,"Estrofa suelta",0,4,"ao",-1,0,-1,0,425,425,"5328","",0,"","","",1,0,0,[],""],["frenk_t2-n5329",6,"No se atarante, mi prieta,\nni cierre tanto los ojos,\nque ya sabe que aquí estoy\npa cumplirle sus antojos.",105,2,-1,129,"Las calabazas",0,4,"oo",99,0,-1,0,425,425,"5329","",0,"","","",1,0,0,[],""],["frenk_t2-n5330a",6,"No te enojes, Mariquita,\n¿qué no sabes de chancear?\nQue al cabo que no es jabón:\n¿para qué se va a gastar?",105,2,-1,129,"La indita",0,4,"a",21,0,-1,0,425,425,"5330a","",0,"","","",1,0,0,[],""],["frenk_t2-n5332",6,"Cuando ibas para el santuario,\nindita, ¿no me decías\nque de vuelta me traerías\nlas ensartas del rosario\ny mi madrina serías?",106,2,4,129,"La indita",7,5,"ia",214,0,-1,0,426,426,"5332","",0,"","","",1,0,0,[],""],["frenk_t2-n5333",6,"Oye, chata, ¿oyes, oyes?\nTú de veras no oyes nada;\nno ha de ser la primera india\nque me mojen la cebada.",114,2,17,129,"Yo ya me voy",0,4,"aa",49,0,-1,0,426,426,"5333","",0,"","","",1,0,0,[],""],["frenk_t2-n5334a",6,"Por el camino derecho\nviene un gavilán volando:\n“Señora, no compre huevos,\nque aquí los traigo colgando.”",129,2,9,129,"Estrofa suelta",0,4,"ao",33,0,-1,0,426,426,"5334a","",0,"","","",1,0,0,[],""],["frenk_t2-n5334b",6,"De lo alto de un espino\nsalió un gavilán chiflado,\ny en su chiflido decía:\n“Mujeres, no compre [n] huevos,\naquí los traigo colgando.”",108,2,8,129,"Estrofa suelta",7,5,"ao",-1,0,-1,0,426,426,"5334b","",0,"","","",1,0,0,[],""],["frenk_t2-n5336",6,"En el otro lado del río\noí cantar una ranita\ny en suspiros decía:\n“Enséñame la pepita.”",108,2,8,129,"Estrofa suelta",0,4,"ia",-1,0,-1,0,426,426,"5336","",0,"","","",1,0,0,[],""],["frenk_t2-n5337",6,"Yo quisiera ser un sapo\npara andar en pinganilla,\npara alzarte tu refajo\ny olerte la semilla.",108,2,8,129,"Estrofa suelta",0,4,"ia",162,0,-1,0,426,426,"5337","",0,"","","",1,0,0,[],""],["frenk_t2-n5338",6,"¡Dele, dele, dele, mi alma,\nmi vida, para la cumbre!\nMujer enaguas de llama,\nya Úégó calzón de lumbre.",105,2,-1,129,"Estrofa suelta",0,4,"ue",181,0,-1,0,426,426,"5338","",0,"","","",4,0,0,[],""],["frenk_t2-n5339",6,"¡Dele, dele, dele, mi alma,\nmi vida, pa la Angostura!\nPresénteme bien la orquesta,\nque traigo la estaca dura.",105,2,-1,129,"Estrofa suelta",0,4,"ua",17,0,-1,0,426,426,"5339","",0,"","","",4,0,0,[],""],["frenk_t2-n5340",6,"En la punta de aquel cerro\ntengo un limón colorado;\nalza las piernas, negrita,\nque ya lo tengo parado.",108,2,8,129,"Estrofa suelta",0,4,"ao",14,0,-1,0,427,427,"5340","",0,"","","",21,0,0,[],""],["frenk_t2-n5341",6,"En la punta de aquel cerro\nhay un barril de cerveza,\nabre las patas, Teresa,\npa' meterte la cabeza.",105,2,-1,129,"Estrofa suelta",0,4,"ea",108,0,-1,0,427,427,"5341","",0,"","","",21,0,0,[],""],["frenk_t2-n5342",6,"Mujeres culo con sangre,\nen la puerta un cuajarón,\nempréstenme su peludo\npara meter mi pelón.",108,2,8,129,"Estrofa suelta",0,4,"o",31,0,-1,0,427,427,"5342","",0,"","","",1,0,0,[],""],["frenk_t2-n5343",6,"Si quieres que te haga casa,\nte arrimaré la madera;\nlas piernas van en los hombros\ny el huevo va en la cadera.",108,2,8,129,"Estrofa suelta",0,4,"ea",44,0,-1,0,427,427,"5343","",0,"","","",1,0,0,[],""],["frenk_t2-n5344",6,"Me subí por la garita\na tomar peras y peras;\nsi usted me hace la mulita,\nyo le hago la muía entera,\ncon toda su campanita,\na orilla de la ribera.",105,2,-1,129,"La india; El toro; La víbora",9,6,"ea",44,0,-1,0,427,427,"5344","",0,"","","",1,0,0,[],""],["frenk_t2-n5345",6,"Me embarqué en una fragata negra\npara ingresar al desfile\ny con el tufo de tu culo\nse me está parando el chile.",108,2,8,129,"Estrofa suelta",3,4,"ie",585,0,-1,0,427,427,"5345","",0,"","","",1,0,0,[],""],["frenk_t2-n5346",6,"Conmigo mi crucifijo\nmuy sagrado y religioso.\nQue yo con esta cosa\nte voy a formar un hijo;\n¡pero mira qué frondoso!\nPor eso cantando vivo.",108,2,8,129,"La morena",9,6,"io",-1,0,-1,0,427,427,"5346","",0,"","","",1,0,0,[],""],["frenk_t2-n5347",6,"Doblado como alcayata,\nyo sobre ti me coloco;\nen tu agujero, hasta el centro,\nte meto toda la reata,\ny pujando poco a poco\nextraigo lo que hay adentro.",105,2,-1,129,"Estrofa suelta",9,6,"eo",185,0,-1,0,427,427,"5347","",0,"","","",1,0,0,[],""],["frenk_t2-n5348",6,"Ya mi huevo se murió,\nmis talegas están de luto;\nya lo llevan a enterrar\ncerca de tu enduto.",108,2,8,129,"Estrofa suelta",0,4,"uo",327,0,-1,0,427,427,"5348","",0,"","","",1,0,0,[],""],["frenk_t2-n5349",6,"Cuando era de buen tamaño\nya cumplía con mi deber,\ncuando tenía yo quince años\nya empezaba yo a coger\na las mujeres del paño.",105,2,-1,129,"La indita",7,5,"ao",-1,0,-1,0,428,428,"5349","",0,"","","",1,0,0,[],""],["frenk_t2-n5350",6,"Cupido me enseñó a leer\nlos versos de buen tamaño,\ny me dijo: “Es de comprender,\nesto te Ueva un año,\ndesde que yo empecé a coger\na las mujeres por el paño.”",108,2,8,129,"El Cupido",9,6,"ao",40,0,-1,0,428,428,"5350","",0,"","","",2,0,0,[],""],["frenk_t2-n5351",6,"¡Cupido, Cupido, Cupido,\nCupido, no seas traidor!,\ny préstame tu abanico,\nque me muero de calor.",108,2,8,129,"El Cupido",0,4,"o",72,0,-1,0,428,428,"5351","",0,"","","",1,0,0,[],""],["frenk_t2-n5353",6,"—Toda la agua, regadores,\nque se seca la sandía,\n—Échele agua usté a la suya,\nque yo regaré la mía.",105,2,-1,129,"La sandía; La ensalada",0,4,"ia",0,0,-1,0,428,428,"5353","",0,"","","",1,0,0,[],""],["frenk_t2-n5354",6,"Yo no soy de aquí,\nsoy de El arenal;\nsolo me divierto\ncon mi pito real.",110,2,10,129,"El pito real",0,4,"a",1,0,-1,0,428,428,"5354","",0,"","","",5,0,0,[],""],["frenk_t2-n5355",6,"¡Y dale, que dale, dale!,\n¡y dale con la rodilla!,\nque está ese trompo que baila\ncon las muchachas de esta orilla.",105,2,-1,129,"El trompo",0,4,"ia",162,0,-1,0,428,428,"5355","",0,"","","",4,0,0,[],""],["frenk_t2-n5357",6,"Mi caballo se cansó,\nvoy a cortar una vara;\ncomo anoche no cenó,\ndondequiera se me para.",115,2,3,129,"Estrofa suelta, Negra, ¿dónde están los lazos?",1,4,"aa",57,0,-1,0,429,429,"5357","",0,"","","",1,0,0,[],""],["frenk_t2-n5358",6,"La cuera se me hizo dura\ny no la puedo ablandar;\nando buscando un charquito\npara echarla a remojar.",109,2,7,129,"La cuera",0,4,"a",21,0,-1,0,429,429,"5358","",0,"","","",1,0,0,[],""],["frenk_t2-n5359",6,"El amor de mi novia\nes un juguete;\ncuando la voy a ver\n’ta como cuete;\nno es cosa buena,\nque si le meten lumbre,\ncapaz que truena.",112,2,6,129,"Cielito lindo",4,7,"ea",59,0,-1,0,429,429,"5359","",0,"","","",2,0,0,[],""],["frenk_t2-n5360",6,"Mi mujer es chaparrita,\nporque nació en un verano,\npero tiene una cosita\nque no me cabe en la mano.",129,2,9,129,"Estrofa suelta",1,4,"ao",81,0,-1,0,429,429,"5360","",0,"","","",1,0,0,[],""],["frenk_t2-n5361",6,"Me acompaña la Lupita:\nlleva chico animal,\nvestido de carrancista;\n¡ay, ay, ay, que vete a bañar!",115,2,3,129,"El caimán",0,4,"a",-1,0,-1,0,429,429,"5361","",0,"","","",1,0,0,[],""],["frenk_t2-n5362",6,"Yo acompaño a la Teresa:\nlleva chico animal\ndomándose de cabeza;\n¡ay, ay, ay, que vete a bañar!",115,2,3,129,"El caimán",0,4,"a",-1,0,-1,0,429,429,"5362","",0,"","","",1,0,0,[],""],["frenk_t2-n5363",6,"Con mi querida y amante\nestaba chico animal,\ndomándose de adelante;\n¡ay, ay, ay, que vete a bañar!,\nte acompaño más pa alante.",115,2,3,129,"El caimán",7,5,"ae",47,0,-1,0,429,429,"5363","",0,"","","",1,0,0,[],""],["frenk_t2-n5364",6,"Si fueres a Coahuayana,\nme traerás una trigueña,\nque tenga chico alfajor,\npero con tamaña greña.",105,2,-1,129,"Coahuayana",0,4,"ea",291,0,-1,0,430,430,"5364","",0,"frenk_t4","","",5,0,0,[],""],["frenk_t2-n5365",6,"Este cuamecate, mi alma,\nque tiendo toda la tarde,\n¡qué bonito se enredaba\ncon mi querida comadre!",114,2,17,129,"El cuamecate",0,4,"ae",-1,0,-1,0,430,430,"5365","",0,"frenk_t4","","",8,0,0,[],""],["frenk_t2-n5366",6,"La vecina de allá enfrente\nse peleó con mi mujer,\nporque le andaba diciendo\nque me la quería comer.",105,2,-1,129,"El totolito",0,4,"e",20,0,-1,0,430,430,"5366","",0,"","","",3,0,0,[],""],["frenk_t2-n5367",6,"Anda, dile a tu hermana\nque no sea boba:\nque me atranque la puerta\ncon una escoba.",105,2,-1,129,"La bamba",6,4,"oa",298,0,-1,0,430,430,"5367","",0,"","","",1,0,0,[],""],["frenk_t2-n5368a",6,"Tu marido fue a las Indias,\nle encargué un conejito;\nyo se lo encargué pintito,\ny me lo trajo blanquito.",105,2,-1,129,"El conejo",0,4,"io",119,0,-1,0,430,430,"5368a","",0,"","","",1,0,0,[],""],["frenk_t2-n5369",6,"Mi marido se fue a viaje\ny me trajo un conejito;\nde gusto que me lo trajo,\nlo puse en el jardincito.",116,2,15,129,"Mi marido se fue a viaje",0,4,"io",119,0,-1,0,430,430,"5369","",0,"","","",6,0,0,[],""],["frenk_t2-n5370",6,"Mi marido se fue a viaje\ny me trajo una frazada;\nde gusto que me la trajo,\nla tapo en la madrugada.",116,2,15,129,"Mi marido se fue a viaje",0,4,"aa",49,0,-1,0,430,430,"5370","",0,"","","",6,0,0,[],""],["frenk_t2-n5371",6,"Mi marido se fue a viaje\ny me trajo una batea,\ny del gusto que la trajo,\nya se sube, ya se apea.",105,2,-1,129,"Mi marido se fue a viaje",0,4,"ea",54,0,-1,0,430,430,"5371","",0,"frenk_t4","","",6,0,0,[],""],["frenk_t2-n5372",6,"Mi marido se fue a viaje\ny me trajo un molcajete;\ndel gusto que me lo trajo,\nya lo saca, ya lo mete.",105,2,-1,129,"Mi marido se fue a viaje; La Sanmarqueña",0,4,"ee",285,0,-1,0,430,430,"5372","",0,"","","",6,0,0,[],""],["frenk_t2-n5373",6,"Señor Alcalde, yo no sabía\nque él entra y sale todito el día.\nSeñor Alcalde, yo no sé nada,\nque él entra y sale a la madrugada.",114,2,17,129,"Mañana yo me levanto",3,4,"aa",49,0,-1,0,431,431,"5373","",0,"","","",1,0,0,[],""],["frenk_t2-n5374",6,"Al pie de una malva en rosa\na una viuda enamoré,\ny me dijo la graciosa:\n“No puedo, me duele un pie;\npero si es para esa cosa,\naunque sea cojeando iré.”",107,2,11,129,"La leva; Estrofa suelta",9,6,"e",77,0,-1,0,431,431,"5374","",0,"","","",1,0,0,[],""],["frenk_t2-n5375",6,"Mamacita, este chocolate\nlo traía cierto mercader;\nel convoy que viene hoy de Oaxaca\ntrae el modo de saberlo hacer.",128,2,30,129,"El chocolate",3,4,"e",20,0,-1,0,431,431,"5375","",0,"","","",1,0,0,[],""],["frenk_t2-n5376",6,"Señor alcalde mayor,\nyo soy una pobre viuda,\nque, por no ofender a Dios,\nbusco quien me lo sacuda.",114,2,17,129,"Los panaderos",0,4,"ua",144,0,-1,0,431,431,"5376","",0,"","","",8,0,0,[],""],["frenk_t2-n5377",6,"El que quiera ser mi esposo\ndos cosas debe tener:\nuna verga bien grandota,\nbuenas formas de coger.",129,2,9,129,"Estrofa suelta",0,4,"e",20,0,-1,0,431,431,"5377","",0,"","","",1,0,0,[],""],["frenk_t2-n5378",6,"Señora del campanario,\npóngale cuidado a su hija,\nque no me ande preguntando\nsi tiene hueso la pija.",108,2,8,129,"Estrofa suelta",0,4,"ia",219,0,-1,0,431,431,"5378","",0,"","","",1,0,0,[],""],["frenk_t2-n5379",6,"¡Alma mía de Santa Anita\ny de San Miguel el Grande!\nMe dijo una chaparrita:\n“¡Qué cuerpo de usted tan grande!”",105,2,-1,129,"Corrido de Guanajuato",1,4,"ae",-1,0,-1,0,431,431,"5379","",0,"","","",1,0,0,[],""],["frenk_t2-n5380",6,"Yo pretendí a una mujer,\nque era muy simpaticona;\nya llegué áhi pa resolverme,\nme dice la muy cabrona:\n“Usted la ha de tener\nlarga, gruesa y cabezona.”",106,2,4,129,"El siquisirí",9,6,"oa",7,0,-1,0,431,431,"5380","",0,"","","",4,0,0,[],""],["frenk_t2-n5381",6,"Andándome yo paseando\nme encontré a una muy muchacha;\nme preguntó del cuchillo,\nno más le enseñé la cacha:\n“Présteme para empeñarla,\nle damos vuelo a la hilacha.”",114,2,17,129,"Las barrancas’ La culebra pollera",9,6,"aa",-1,0,-1,0,431,431,"5381","",0,"","","",8,0,0,[],""],["frenk_t2-n5383",6,"Andándome yo paseando\nme encontré una mujer sola;\nme dijo: “¡Cómo me gustan\nlos tiros de su pistola!\nPréstemela pa empeñarla\ny darle vuelo a la bola.”",107,2,11,129,"Estrofa suelta",9,6,"oa",321,0,-1,0,432,432,"5383","",0,"","","",8,0,0,[],""],["frenk_t2-n5384",6,"Yo enamoré a una mujer\nque se llamaba Consuelo;\ntanto me llegó a querer,\nque guardaba mucho anhelo\ny me daba de comer\npura tortuga con pelo.",106,2,4,129,"El siquisirí",9,6,"eo",10,0,-1,0,432,432,"5384","",0,"","","",1,0,0,[],""],["frenk_t2-n5385",6,"Al pasar por la garita\nme dijo una garbancera:\n“Por favor me hace una arpita,\ndándole yo la madera:\narriba sus dos patitas\ny abajo su templadera.”",107,2,11,129,"El venadito; El pájaro carpintero",9,6,"ea",44,0,-1,0,432,432,"5385","",0,"","","",1,0,0,[],""],["frenk_t2-n5387",6,"Me enamoré otra ranchera\npor verle su crinolina,\ny me dijo la catrina:\n“Vámonos pa la cocina;\nno le temas a la reata,\nel fuste es el que rechina.”",112,2,6,129,"El caballito",9,6,"ia",11,0,-1,0,432,432,"5387","",0,"","","",1,0,0,[],""],["frenk_t2-n5388",6,"En ese Guadalajara,\nme dijo una taparía:\n“No me meta mano al seno,\nporque la tiene muy fría;\nmétala más abajito,\náhi está la panadería.”",105,2,-1,129,"Los panaderos",9,6,"ia",0,0,-1,0,432,432,"5388","",0,"","","",1,0,0,[],""],["frenk_t2-n5389",6,"En una panadería\nme dijo una muy ingrata:\n“Si me agarra la semita,\nhora se la doy barata,\npero con la condición\nque no me ha de alzar la pata.”",114,2,17,129,"Los panaderos",9,6,"aa",74,0,-1,0,432,432,"5389","",0,"","","",1,0,0,[],""],["frenk_t2-n5390",6,"En la puerta de mi casa\nhay una piedra bendita:\nla señora que se sienta\nse levanta señorita.",107,2,11,129,"La Sanmarqueña",0,4,"ia",50,0,-1,0,433,433,"5390","",0,"","","",24,0,0,[],""],["frenk_t2-n5391",6,"Mujeres, si venden tunas,\nvéndanme de las moradas:\nquiero medio con capinas\ny dos reales de peladas,\npara darle a mis vecinas,\nesas que están entrompadas.",105,2,-1,129,"La Malagueña curreña",9,6,"aa",282,0,-1,0,433,433,"5391","",0,"","","",1,0,0,[],""],["frenk_t2-n5392",6,"Soy amante de las indias,\nprincipalmente las muchachas,\nporque me ponen las piernas\ndonde el indio carga su hacha.",108,2,8,129,"Estrofa suelta",0,4,"aa",-1,0,-1,0,433,433,"5392","",0,"","","",1,0,0,[],""],["frenk_t2-n5393",6,"Y en un árbol muy erguido\nquise cortar una guaya;\nme subí sin hacer ruido\ny cogí una guacamaya\nque estaba echada en su nido.",105,2,-1,129,"La guacamaya",7,5,"io",101,0,-1,0,433,433,"5393","",0,"","","",1,0,0,[],""],["frenk_t2-n5394",6,"Llegué a la panadería\ny hallé a la maestra durmiendo,\ny en la boquita tenía\nun bizcochito comiendo:\nya mero se lo pedía\npara estarme divirtiendo.",105,2,-1,129,"Los panaderos",9,6,"eo",52,0,-1,0,433,433,"5394","",0,"","","",1,0,0,[],""],["frenk_t2-n5395",6,"Más atrás les echo un verso\ny adelante un refrán;\nya mero me subo al homo\npa aprovecharme del pan.",108,2,8,129,"Estrofa suelta",0,4,"a",147,0,-1,0,433,433,"5395","",0,"","","",1,0,0,[],""],["frenk_t2-n5396",6,"Un favor le pido al cielo,\ny el Señor me lo conceda:\nuna tela y un telar\ny una buena tejendera,\nque me lo sepa menear\ncon lo ancho de la cadera.",108,2,8,129,"Estrofa suelta",9,6,"ea",44,0,-1,0,433,433,"5396","",0,"","","",1,0,0,[],""],["frenk_t2-n5397",6,"Estando de matancero\nuna mujer me dio un beso;\nhora que vengo de arriero\nquiero que me dé un pedazo,\naunque se le rompa el cuero\ny quede fuera el espinazo.",105,2,-1,129,"La víbora; Ahora pregunto, pregunto; El toro",9,6,"ao",43,0,-1,0,433,433,"5397","",0,"","","",1,0,0,[],""],["frenk_t2-n5398",6,"Una india muy regular\nyo le serví de rodillas,\ny era tan grande el comal,\nque yo le palmeé la tortilla\ny se la ayudé a virar.",105,2,-1,129,"La indita",7,5,"a",-1,0,-1,0,433,433,"5398","",0,"","","",1,0,0,[],""],["frenk_t2-n5400",6,"Pa sacarle el agua al coco\nse le hace un agujerito;\nyo se lo hice a una mujer,\npero le quedó chiquito.",108,2,8,129,"La Sanmarqueña",0,4,"io",119,0,-1,0,434,434,"5400","",0,"","","",3,0,0,[],""],["frenk_t2-n5401",6,"Pa sacar el agua al coco\nse le hace un agujerito;\nhágale otro al otro lado,\npa ajustar un parecito.",114,2,17,129,"El palmero",0,4,"io",119,0,-1,0,434,434,"5401","",0,"","","",2,0,0,[],""],["frenk_t2-n5403a",6,"El pájaro carpintero\npara trabajar se empina;\ncuando llega al agujero\ny hasta el pico le rechina.",105,2,-1,129,"El pájaro carpintero",1,4,"ia",11,0,-1,0,434,434,"5403a","",0,"","","",9,0,0,[],""],["frenk_t2-n5403c",6,"El pájaro carpintero\npara trabajar se empina;\ncuando llega al agujero\ny hasta el pico le rechina:\nése sí era carpintero,\ntrabaja en madera fina.",106,2,4,129,"El pájaro carpintero",9,6,"ia",11,0,-1,0,434,434,"5403c","",0,"","","",9,0,0,[],""],["frenk_t2-n5404",6,"El pájaro carpintero\npara trabajar se agacha;\ncuando llega al agujero\nhasta el pico le retacha.",105,2,-1,129,"El pájaro carpintero; Estrofa suelta",1,4,"aa",556,0,-1,0,435,435,"5404","",0,"","","",9,0,0,[],""],["frenk_t2-n5404c",6,"El pájaro carpintero\npara trabajar se agacha:\nyo también soy carpintero\ncuando estoy con mi muchacha,\ny si me quito el sombrero,\ndondequiera me apapacha.",105,2,-1,129,"Estrofa suelta",9,6,"aa",556,0,-1,0,435,435,"5404c","",0,"","","",9,0,0,[],""],["frenk_t2-n5405",6,"Una señora tenía\nen su jaula un cardenal,\ncomo se iba y se venía,\nyo se lo pedía a comprar:\n“Eso, no”, me dijo un día.",117,2,5,129,"Estrofa suelta",7,5,"ia",0,0,-1,0,435,435,"5405","",0,"","","",1,0,0,[],""],["frenk_t2-n5406",6,"Al pasar por Tizapán\nme dijo una santaneca:\n“No me moje todo el pan,\nporque ¿a qué horas se me seca?,\ny en mi casa ¿qué dirán?”",105,2,-1,129,"Los panaderos",7,5,"a",147,0,-1,0,435,435,"5406","",0,"","","",1,0,0,[],""],["frenk_t2-n5407",6,"Cuando pensé ser casado\ny no se me concedió:\nla novia se arrepintió\nmérito el día del peinado.",106,2,4,129,"Estrofa suelta",11,4,"ao",14,0,-1,0,435,435,"5407","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5408",6,"Ni favores con los Juárez\nni menos con Federico:\nel que me dé cinco pesos\nserá dueño de mi perico.",108,2,8,129,"Estrofa suelta",0,4,"io",141,0,-1,0,435,435,"5408","",0,"","","",1,0,0,[],""],["frenk_t2-n5409",6,"Entré al jardín de Cupido\na cortar de sus rosales,\ny allí mi chata me puso\nel maíz a veinte reales\ny me dijo que no fiaba\nni prestaba los costales.",107,2,11,129,"El venadito",9,6,"ae",26,0,-1,0,435,435,"5409","",0,"","","",1,0,0,[],""],["frenk_t2-n5410",6,"Viniendo de la argarita\nhice mis cuentas cabales;\nle dije a mi morenita:\n“Bien vale sus veinte reales\nun beso por la boquita\ny lo demás doce reales.”",112,2,6,129,"La azucena",9,6,"ae",-1,0,-1,0,435,435,"5410","",0,"","","",1,0,0,[],""],["frenk_t2-n5411",6,"La vecina de allá enfrente\nle pegó a mi gallo fino,\nporque le andaba comiendo\nlas hojitas al pepino.",105,2,-1,129,"El totolito*’",0,4,"io",199,0,-1,0,436,436,"5411","",0,"","","",3,0,0,[],""],["frenk_t2-n5412",6,"La vecina de allá enfrente\nle pegó un palo a mi gallo,\nporque le andaba picando\nlas hojitas al papayo.",105,2,-1,129,"El totolito",0,4,"ao",-1,0,-1,0,436,436,"5412","",0,"","","",3,0,0,[],""],["frenk_t2-n5413",6,"La vecina de allí enfrente\nme mató mi gallo blanco,\nporque le andaba escarbando\nla semilla del cilantro.",105,2,-1,129,"La gallina; El chúmbale",0,4,"ao",-1,0,-1,0,436,436,"5413","",0,"","","",2,0,0,[],""],["frenk_t2-n5414",6,"En la sombra de un café\npuse mi amor de avanzada;\nluego que desembarqué\nme tocaron retirada:\ncausa de que no avancé\nsobre de la tropa armada.",108,2,8,129,"Zapateado",9,6,"aa",49,0,-1,0,436,436,"5414","",0,"","","",1,0,0,[],""],["frenk_t2-n5415",6,"Señores, no soy de aquí,\npues yo soy del Arenal;\npor andar de parrandero,\nse perdió mi pito real.",119,2,12,129,"El pito real",0,4,"a",1,0,-1,0,436,436,"5415","",0,"","","",4,0,0,[],""],["frenk_t2-n5416",6,"Yo tenía mi cascabel,\nque lo tenían los del norte;\nse lo regalé a Isabel (mamá),\na la dueña del consorte;\ncon tanto jugar con él,\nse le reventó el resorte.",105,2,-1,129,"El cascabel",9,6,"oe",402,0,-1,0,436,436,"5416","",0,"","","",10,0,0,[],""],["frenk_t2-n5417a",6,"¡Y dale que dale, dale!,\n¡y dale que dale sí!,\npor falta de una pitita\nmi trompo no baila aquí.",105,2,-1,129,"El trompo",0,4,"i",23,0,-1,0,436,436,"5417a","",0,"","","",4,0,0,[],""],["frenk_t2-n5418",6,"¡Y dale, que dale, dale!,\n¡y dale que dale, no!;\npor falta de una pitita\nmi trompo no bailo yo.",106,2,4,129,"El trompo; El trompito",0,4,"o",2,0,-1,0,436,436,"5418","",0,"","","",4,0,0,[],""],["frenk_t2-n5419",6,"¡Y dale que dale, dale!,\n¡y dale que dale, cuándo!;\npor falta de una pitita\nmi trompo no está bailando.",106,2,4,129,"El trompo",0,4,"ao",33,0,-1,0,437,437,"5419","",0,"","","",4,0,0,[],""],["frenk_t2-n5420",6,"A mis palomas les dije\nque ya no las mato yo;\npero lo que más me aflige\nes que, aunque quiera yo, ya no:\nse me descompuso el rifle,\nya el parque se me acabó.",109,2,7,129,"Estrofa suelta",9,6,"o",2,0,-1,0,437,437,"5420","",0,"","","",1,0,0,[],""],["frenk_t2-n5421",6,"Nunca juegues al amor\nque es cosa sagrada;\nmejor juega volibol,\nque es pura vacilada.",107,2,11,130,"Estrofa suelta",0,4,"aa",49,0,-1,0,441,441,"5421","",0,"","","",1,0,0,[],""],["frenk_t2-n5422",6,"¡Ay!, voy a echar mi despedida\npor el ojo de una aguja;\n¡ay!, la que es mujer se sostiene\ny el que es hombre no más puja.",115,2,3,130,"Valona de las juinas",0,4,"ua",586,0,-1,0,441,441,"5422","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5423",6,"Celotes y más celotes,\ncelotes que son fatales;\nen solteros y casados\npara todos son iguales;\nfíjense bien, mis cuatachos,\nen lo que voy a contarles.",105,2,-1,130,"Los celotes",9,6,"ae",-1,0,-1,0,441,441,"5423","",0,"","","",1,0,0,[],""],["frenk_t2-n5424",6,"¿Quieres que te diga\nlo que son celos?\nUna cosa redonda\ncomo buñuelos.",105,2,-1,130,"La bamba",6,4,"eo",192,0,-1,0,441,441,"5424","",0,"","","",1,0,0,[],""],["frenk_t2-n5425",6,"Ariles y más ariles,\nariles de Cuernavaca;\na las mujeres celosas\nse les ven las piernas flacas.",106,2,4,130,"El Balajú",0,4,"aa",-1,0,-1,0,441,441,"5425","",0,"","","",24,0,0,[],""],["frenk_t2-n5426",6,"Hasta la barranca se oyen\nlos gritos del calzón verde;\nla mujer cuando es celosa\nhasta la cola se muerde.",108,2,8,130,"Estrofa suelta, Al pasar por los laureles; La guacamaya; La Petenera",0,4,"ee",154,0,-1,0,441,441,"5426","",0,"","","",1,0,0,[],""],["frenk_t2-n5427",6,"Los muchachos de la flota\nson como la tuna verde;\nlas mujeres que los bajan\nse pican, pero los muerden.",107,2,11,130,"La Sanmarqueña",0,4,"ee",-1,0,-1,0,441,441,"5427","",0,"","","",1,0,0,[],""],["frenk_t2-n5429",6,"¡Ay, cuchillito de palo,\nlastimas más que una lija!\nEl que a buen palo se arrima\nbuena sombra lo cobija,\nel que se acuesta temprano\nsu vieja lo descobija.",108,2,8,130,"Estrofa suelta",9,6,"ia",219,0,-1,0,442,442,"5429","",0,"","","",1,0,0,[],""],["frenk_t2-n5431",6,"A casadas y solteras\nles gusta la nueva moda,\nsiendo ya raro encontrar\nquien no quiera estar pelona.",105,2,-1,130,"El vacilón",0,4,"oa",-1,0,-1,0,442,442,"5431","",0,"","","",1,0,0,[],""],["frenk_t2-n5432",6,"Pobres de los mariditos\ncon las que usan crinolinas,\npues que parecen gallinas\nque están tapando pollitos.",105,2,-1,130,"Estrofa suelta",11,4,"io",254,0,-1,0,442,442,"5432","",0,"","","",1,0,0,[],""],["frenk_t2-n5433",6,"Las muchachas son de oro,\nlas casadas son de plata,\nlas viudas son de cobre,\nlas viejas de hoja de lata.",105,2,-1,130,"Estrofa suelta, El jarabe",0,4,"aa",74,0,-1,0,442,442,"5433","",0,"","","",1,0,0,[],""],["frenk_t2-n5434",6,"La mujer enamorada\nse conoce caminando,\nporque mueve la colita\ncomo chivito mamando.",107,2,11,130,"La Sanmarqueña",0,4,"ao",33,0,-1,0,442,442,"5434","",0,"","","",4,0,0,[],""],["frenk_t2-n5435",6,"Cuando la mujer empieza\na estar mira y mira afuera\nes que tiene a su chivito\ndetrás de la nopalera.",107,2,11,130,"El huizache",0,4,"ea",44,0,-1,0,442,442,"5435","",0,"","","",2,0,0,[],""],["frenk_t2-n5436",6,"Cuando la mujer empieza\na hacer bolitas la masa\nes que tiene a su chivito\nmuy cerquita de la casa.",107,2,11,130,"El huizache",0,4,"aa",123,0,-1,0,443,443,"5436","",0,"","","",2,0,0,[],""],["frenk_t2-n5438",6,"Las muchachas de mi tierra\ngozan de mucho placer,\nporque no tienen doce años,\ny ya empiezan a querer;\nde nada sirve el tamaño:\nles contrapesa el quehacer.",106,2,4,130,"El cascabel",9,6,"e",20,0,-1,0,443,443,"5438","",0,"","","",7,0,0,[],""],["frenk_t2-n5439",6,"La planta para nacer\nsiempre nace para arriba;\nigualito es la mujer,\ncuando se halla sin salida\nluego empieza a poner\nplanes en una subida.",108,2,8,130,"Zapateado",9,6,"ia",37,0,-1,0,443,443,"5439","",0,"","","",2,0,0,[],""],["frenk_t2-n5440",6,"La planta para nacer\nsiempre nace revolcada;\nes lo mismo la mujer,\ncuando se halla maltratada\nluego empiezan a poner,\nplanes en una bajada.",108,2,8,130,"Zapateado",9,6,"aa",49,0,-1,0,443,443,"5440","",0,"","","",2,0,0,[],""],["frenk_t2-n5441",6,"Las muchachas de hoy en día\nla que menos corre vuela;\nestudian la picardía\ncomo si van a la escuela;\nhacen cobarde a su tía,\na su madre y a su abuela.",105,2,-1,130,"La guacamaya; La morena",9,6,"ea",167,0,-1,0,443,443,"5441","",0,"","","",14,0,0,[],""],["frenk_t2-n5442",6,"Las muchachas de hoy en día\nno estudian la biología,\npero en cambio van al cine\ny estudian besología.",107,2,11,130,"Estrofa suelta, La Sanmarqueña",0,4,"ia",0,0,-1,0,443,443,"5442","",0,"","","",14,0,0,[],""],["frenk_t2-n5444",6,"Las niñas del salón\nno saben inglés,\npero si les dices: Kiss\nellas te dicen: Yes.",107,2,11,130,"Estrofa suelta",0,4,"e",218,0,-1,0,444,444,"5444","",0,"","","",1,0,0,[],""],["frenk_t2-n5445",6,"Las muchachas de este tiempo\nson como pina madura:\nluego que les dan un beso\nles sube la calentura.",108,2,8,130,"El novillo despuntado",0,4,"ua",17,0,-1,0,444,444,"5445","",0,"","","",9,0,0,[],""],["frenk_t2-n5447",6,"Cuando te busques un novio\nno te lo busques muy alto,\nporque para darle un beso\ntienes que pegar un salto.",122,2,13,130,"Estrofa suelta",0,4,"ao",417,0,-1,0,444,444,"5447","",0,"","","",1,0,0,[],""],["frenk_t2-n5448",6,"Segunda despedidita\nle voy a echar a Rufina:\nla mujer que es chaparrita,\ncuando no alcanza, se empina.",108,2,8,130,"Chilena de Jamiltepec; La Malagueña curreña",1,4,"ia",-1,0,-1,0,444,444,"5448","",0,"","","",1,0,0,[],""],["frenk_t2-n5449",6,"La mujer agachadita\npinta ser buena persona;\nentre sus agachaditas\na nadie se la perdona;\nes como vaca bañista:\nno brinca, pero se asoma.",109,2,7,130,"Indita del alma**",9,6,"oa",-1,0,-1,0,445,445,"5449","",0,"","","",1,0,0,[],""],["frenk_t2-n5450",6,"Cuando beses a tu novio\nno lo beses en la puerta;\nporque el amor es ciego\npero las vecinas no.",107,2,11,130,"Estrofa suelta",5,4,"o",-1,0,-1,0,445,445,"5450","",0,"","","",1,0,0,[],""],["frenk_t2-n5451",6,"Las muchachas nacoreñas\nse visten de azul y verde;\nde las ocho en adelante\nla que no pellizca, muerde.",105,2,-1,130,"La iguana’’, La Sanmarqueña; Estrofa suelta",0,4,"ee",154,0,-1,0,445,445,"5451","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5452",6,"Las muchachas de ahora\nno bailan sones,\npor andar abrazadas\ncon los varones;\nandan felices,\nbailando el rocanrol — el chachachá\ny también el tuise.",112,2,6,130,"Cielito lindo",4,7,"ie",-1,0,-1,0,445,445,"5452","",0,"","","",1,0,0,[],""],["frenk_t2-n5454",6,"Las muchachas del rincón\nson como la calabaza;\napenas pasan sus novios:\n“Mamá, me voy pa la plaza.”",105,2,-1,130,"Soy de Zacatula",0,4,"aa",307,0,-1,0,445,445,"5454","",0,"","","",1,0,0,[],""],["frenk_t2-n5455",6,"Las muchachas de hoy en día\nson como la longaniza;\napenitas ven al novio:\n“Mamacita, voy a misa.”",107,2,11,130,"La Sanmarqueña; Estrofa suelta",0,4,"ia",68,0,-1,0,445,445,"5455","",0,"","","",14,0,0,[],""],["frenk_t2-n5456",6,"El templo de Solimán,\ndonde va toda la gente:\nunas van con devoción,\ny otras a pelar los dientes.",106,2,4,130,"Estrofa suelta",0,4,"ee",-1,0,-1,0,445,445,"5456","",0,"","","",1,0,0,[],""],["frenk_t2-n5458",6,"Las muchachas alamenses\nya no saben ni qué hacer:\npiden a Dios que haya un hombre\nque las sepa bien querer.",105,2,-1,130,"La iguana",0,4,"e",20,0,-1,0,446,446,"5458","",0,"","","",2,0,0,[],""],["frenk_t2-n5459",6,"Las chicas de Rancho Verde\npasan la vida en la plaza,\nmirando por todas partes,\na ver si un marido pasa.",105,2,-1,130,"Estrofa suelta, La iguana",0,4,"aa",123,0,-1,0,446,446,"5459","",0,"","","",1,0,0,[],""],["frenk_t2-n5460",6,"Si quieres casarte a gusto,\nbusca, niña, un carbonero,\ny así tendrás dos maridos:\nuno blanco y otro negro.",114,2,17,130,"No sabes, china del alma",0,4,"eo",-1,0,-1,0,446,446,"5460","",0,"","","",1,0,0,[],""],["frenk_t2-n5461",6,"La que se casa con negro\nnegro tiene el corazón,\nporque el amor de los negros\nes negro como el carbón.",109,2,7,130,"¡Ay, milongo!",0,4,"o",31,0,-1,0,446,446,"5461","",0,"","","",1,0,0,[],""],["frenk_t2-n5463",6,"El amor veracruzano\nes como el del jicotito;\nsi quieren saber cómo es,\nhagan la prueba tantito.",105,2,-1,130,"El as de los huapangos",0,4,"io",119,0,-1,0,446,446,"5463","",0,"","","",1,0,0,[],""],["frenk_t2-n5464",6,"De la vista nace el amor,\ndel amor nace la dicha;\npero más sabrosa es\nla torta con salchicha.",107,2,11,130,"Estrofa suelta",0,4,"ia",357,0,-1,0,446,446,"5464","",0,"","","",1,0,0,[],""],["frenk_t2-n5465",6,"El que se acuesta en petate,\ngoza de muchos favores,\nporque se acuesta con Tules\ny amanece con Dolores.",105,2,-1,130,"Estrofa suelta",0,4,"oe",5,0,-1,0,446,446,"5465","",0,"","","",1,0,0,[],""],["frenk_t2-n5466",6,"Su anzuelito y su carnada\ntambién lo atarantarán;\nun besito aquí no es nada,\naquí por docenas dan.",106,2,4,130,"El tuxpeño",1,4,"a",147,0,-1,0,447,447,"5466","",0,"","","",1,0,0,[],""],["frenk_t2-n5467",6,"Sólo de los hombres no hay que desconfiar,\npues lo que ellos hacen no lo hacen por [mal\nsuelen como el gato también halagar,\ny a la pasadita tan, darín, darán.",105,2,-1,130,"La pasadita",3,4,"a",-1,0,-1,0,447,447,"5467","",0,"","","",1,0,0,[],""],["frenk_t2-n5469",6,"Dicen que el hombre casado\nal baile no ha de volver;\npero se han equivocado:\nsiempre tiene que volver,\npues para verlo a tu lado.",113,2,2,130,"El huerfanito",7,5,"ao",14,0,-1,0,447,447,"5469","",0,"","","",3,0,0,[],""],["frenk_t2-n5470",6,"No hay que estar comprometido\nen las cosas del querer;\nsolteras o con marido,\nsiempre es buena la mujer.",105,2,-1,130,"mal [La verdolaga",1,4,"e",20,0,-1,0,447,447,"5470","",0,"","","",1,0,0,[],""],["frenk_t2-n5471",6,"Todo me gusta en la vida,\npor eso nada me apena;\nno hay comida más sabrosa\nque la mujer ajena.",115,2,3,130,"La chinita",0,4,"ea",59,0,-1,0,447,447,"5471","",0,"","","",1,0,0,[],""],["frenk_t2-n5472a",6,"Yo vide pelear un oso\ncon una garza morena;\nno hay bocado tan sabroso\ncomo la mujer ajena.",105,2,-1,130,"El teneque",1,4,"ea",59,0,-1,0,447,447,"5472a","",0,"","","",2,0,0,[],""],["frenk_t2-n5474",6,"Yo le pregunté a Cupido\nque si pretendía casadas,\ny me contestó afligido:\n“Ésas son las más amadas,\nporque tienen su marido\ny no son interesadas.”",107,2,11,130,"El Cupido; La Rosita; Estrofa suelta",9,6,"aa",282,0,-1,0,448,448,"5474","",0,"","","",8,0,0,[],""],["frenk_t2-n5475",6,"Ya te he dicho que no vayas\nal agua a la Presa Larga,\nque el amor es como el frío,\nque al más pobre se le carga.",110,2,10,130,"Ya te he dicho que no vayas",0,4,"aa",512,0,-1,0,448,448,"5475","",0,"","","",6,0,0,[],""],["frenk_t2-n5476",6,"Ya te he dicho que no vayas\nde San Martín a la mina,\nporque allí perdió su quinto\nla pobre de Josefina.",108,2,8,130,"La Sanmarqueña",0,4,"ia",11,0,-1,0,449,449,"5476","",0,"","","",6,0,0,[],""],["frenk_t2-n5477",6,"Ya te he dicho que no vayas\na traer agua al pozo jondo,\nporque áhi andan los muchachos:\nte pueden brincar al chongo.",105,2,-1,130,"Costeña",0,4,"oo",-1,0,-1,0,449,449,"5477","",0,"","","",6,0,0,[],""],["frenk_t2-n5478",6,"Carolina, Carolina,\nno te vayas a pelar,\nsi no un viejo se te arrima\ny te lleva a vacilar.",105,2,-1,130,"El vacilón",0,4,"a",21,0,-1,0,449,449,"5478","",0,"","","",4,0,0,[],""],["frenk_t2-n5479",6,"Cuando un viejo te pida un beso\nno se lo vayas a dar,\nporque los besos de viejo\napestan a huevo sin sal.",129,2,9,130,"Estrofa suelta",0,4,"a",-1,0,-1,0,449,449,"5479","",0,"","","",1,0,0,[],""],["frenk_t2-n5480",6,"Cuando un músico te pida la mano\nnunca le digas que sí,\nporque te dará de comer\ndo, re, mi, fa, sol, la, si.",107,2,11,130,"Estrofa suelta",3,4,"i",-1,0,-1,0,449,449,"5480","",0,"","","",1,0,0,[],""],["frenk_t2-n5481",6,"¡Qué tonta es la que se casa\ny quiere tener marido!\nQuien no da de enamorado\nmenos da de arrepentido.",105,2,-1,130,"Estrofa suelta",0,4,"io",101,0,-1,0,449,449,"5481","",0,"","","",1,0,0,[],""],["frenk_t2-n5482",6,"La que se casa con calvo\ntiene su pasión entera:\nde día tiene su calvario,\nde noche su calavera.",105,2,-1,130,"Las ventanas; El palmero",0,4,"ea",44,0,-1,0,449,449,"5482","",0,"","","",2,0,0,[],""],["frenk_t2-n5483a",6,"No te cases con viejo\npor la moneda:\nel dinero se gasta,\ny el viejo queda.",105,2,-1,130,"Estrofa suelta",6,4,"ea",266,0,-1,0,449,449,"5483a","",0,"","","",5,0,0,[],""],["frenk_t2-n5485",6,"Cuatro güeyes jalando la yunta\nmuchas veces no sirven pa nada;\nla mujer que con bueyes se junta\nnunca puede evitar la cornada.",105,2,-1,130,"El Pata Rajada",3,4,"aa",49,0,-1,0,450,450,"5485","",0,"","","",1,0,0,[],""],["frenk_t2-n5487",6,"Si sueñas en matrimonio,\nhaz realidad tu quimera;\nsi está fría tu chequera,\nno pienses en San Antonio,\nporque te carga el demonio.",122,2,13,130,"Estrofa suelta",7,5,"oo",169,0,-1,0,450,450,"5487","",0,"","","",1,0,0,[],""],["frenk_t2-n5488a",6,"¡Qué bonito es ser casado,\ntener hijos y mujer!\nPero a la hora de comer\ntuerce la puerca el rabo\ny lo vuelve a retorcer.",105,2,-1,130,"La leva",7,5,"e",20,0,-1,0,450,450,"5488a","",0,"","","",2,0,0,[],""],["frenk_t2-n5489",6,"¡Qué bonito es ir al templo\ncon una joven al lado,\ntoda vestida de blanco,\nsu zapatito ajustado!\nY después, ¡ah, qué amargura!,\nun año de noviciado.",108,2,8,130,"Estrofa suelta",9,6,"ao",14,0,-1,0,451,451,"5489","",0,"","","",1,0,0,[],""],["frenk_t2-n5490",6,"Es muy preciso advertir,\npara ponerse en estado,\nnecesita el que es casado\nhasta cama en que dormir.",106,2,4,130,"Estrofa suelta",11,4,"i",157,0,-1,0,451,451,"5490","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5491",6,"Ya me despido, mis cuates,\ndejándoles mis consejos:\nvale más ser solterones\nantes que los hagan [pendejos].",105,2,-1,130,"Los bueyes",0,4,"eo",149,0,-1,0,451,451,"5491","",0,"","","",1,0,0,[],""],["frenk_t2-n5492",6,"Si miras algún nopal,\ncuenta las tunas que tiene;\nno te metas con mujeres,\nporque ya no te conviene.",105,2,-1,130,"El nuevo tejón",0,4,"ee",-1,0,-1,0,451,451,"5492","",0,"","","",1,0,0,[],""],["frenk_t2-n5493",6,"Al fin, en esta vida ingrata\ntodo empieza y todo acaba;\nen cuestión de las mujeres\nunas vienen y otras van.",115,2,3,130,"El Águila Negra",0,4,"a",-1,0,-1,0,451,451,"5493","",0,"","","",1,0,0,[],""],["frenk_t2-n5494",6,"Con ella no quiere más,\nsarandina de la Juana;\nel que ama mujer bonita\npor el berrinche no gana.",105,2,-1,130,"La cucaracha*",0,4,"aa",4,0,-1,0,451,451,"5494","",0,"","","",1,0,0,[],""],["frenk_t2-n5495",6,"Todo aquel que sabe andar\ny de su casa se aleja\nno es fácil que vuelva a hallar\nsu mujer como la deja:\nsólo que sea muy legal\no enteramente muy vieja.",105,2,-1,130,"Estrofa suelta, El pájaro carpintero’*",9,6,"ea",165,0,-1,0,451,451,"5495","",0,"","","",1,0,0,[],""],["frenk_t2-n5496",6,"Doce gallinas y un gallo\ncasi siempre están conformes,\ny casi nunca lo están\nuna mujer con un hombre.",107,2,11,130,"Estrofa suelta",0,4,"oe",-1,0,-1,0,451,451,"5496","",0,"","","",3,0,0,[],""],["frenk_t2-n5497",6,"El demonio son los hombres\ncuando empiezan a querer,\ny el diablo son las pelonas\nsi empiezan a aborrecer.",105,2,-1,130,"Ya no lloverá, pelonas",0,4,"e",20,0,-1,0,451,451,"5497","",0,"","","",7,0,0,[],""],["frenk_t2-n5498c",6,"El amor es un bicho (cielito lindo)\nque, cuando pica,\nno se encuentra remedio (cielito lindo)\nni en la botica;\nesto es tan cierto\ncomo sacarse un ojo (cielito lindo)\ny quedarse tuerto.",106,2,4,130,"Cielito lindo",4,7,"eo",88,0,-1,0,452,452,"5498c","",0,"","","",1,0,0,[],""],["frenk_t2-n5499",6,"En toda la Costa Chica\nse baila “El toro rabón”.\nSi una víbora te pica,\nte queda la comezón:\nno hallarás en la botica\nremedio ni curación.",109,2,7,130,"El toro",9,6,"o",31,0,-1,0,452,452,"5499","",0,"","","",1,0,0,[],""],["frenk_t2-n5501",6,"Cuando uno quiere a una,\ny ella a uno no lo quier[e],\nviene a ser como algún calvo\nque en la calle se halla un peine.",114,2,17,130,"No sabes, china del alma",5,4,"ee",-1,0,-1,0,452,452,"5501","",0,"","","",5,0,0,[],""],["frenk_t2-n5502",6,"¡Qué triste es amar\nsin ser amado!\nPero es más triste acostarse\nsin haber cenado.",130,2,21,130,"Estrofa suelta",6,4,"ao",14,0,-1,0,452,452,"5502","",0,"","","",1,0,0,[],""],["frenk_t2-n5503",6,"Si quieres aborrecer\na la que estás adorando,\nconsidérala llorando,\narrimada a la pared.",105,2,-1,130,"Estrofa suelta",5,4,"e",-1,0,-1,0,452,452,"5503","",0,"","","",2,0,0,[],""],["frenk_t2-n5504",6,"Pobre del que se enamora\nde una muchacha decente:\nes como la carne dura\npara el que no tiene dientes.",108,2,8,130,"La Malagueña curreña; El pastelero; Estrofa suelta",0,4,"ee",-1,0,-1,0,452,452,"5504","",0,"","","",1,0,0,[],""],["frenk_t2-n5505",6,"El amor del hombre pobre\nes como el del gallo enano:\nen querer y no alcanzar\nse le pasa todo el año.",105,2,-1,130,"Estrofa suelta, El huizache; Soy de Zacatula; Al derecho y al revés",0,4,"ao",-1,0,-1,0,453,453,"5505","",0,"","","",6,0,0,[],""],["frenk_t2-n5506",6,"Pregúntale al sacamuelas (Llorona)\ncuál es el mayor dolor:\nsi al que le sacan la muela (Llorona)\no al que le roban su amor.",108,2,8,130,"La Llorona",3,4,"o",72,0,-1,0,453,453,"5506","",0,"","","",1,0,0,[],""],["frenk_t2-n5508",6,"Despedida te compuso\nun marinero en la arena:\n“Y el que siembra en tepetate\nni la semilla pepena.”",105,2,-1,130,"Los maderistas",0,4,"ea",59,0,-1,0,453,453,"5508","",0,"","","",1,0,0,[],""],["frenk_t2-n5509a",6,"El que enamora a las casadas\nsiempre anda descolorido:\nserá por las desveladas,\no por miedo del marido.",105,2,-1,130,"María, María; Bonito San Juan del Río",1,4,"io",101,0,-1,0,453,453,"5509a","",0,"","","",1,0,0,[],""],["frenk_t2-n5509b",6,"El que enamora casada\nsiempre anda descolorido:\nserá por la desvelada,\no por el miedo al marido;\nde eso yo no sé nada,\npero ya me ha sucedido.",105,2,-1,130,"El caballo; Estrofa suelta",9,6,"io",101,0,-1,0,453,453,"5509b","",0,"","","",1,0,0,[],""],["frenk_t2-n5511",6,"Todo aquel que se casa\ncon una viuda\nen la noche se espanta (cielito lindo):\nde eso no hay duda;\nesto es muy cierto:\ndebajo de la almohada (cielito lindo)\nle ronca el muerto.",113,2,2,130,"Cielito lindo",4,7,"eo",88,0,-1,0,454,454,"5511","",0,"","","",2,0,0,[],""],["frenk_t2-n5512",6,"El que enamora a una viuda\nmuy poco del mundo goza;\ncomo el que vendió una muía,\nque la vendía por mañosa:\ncuando no patea, recula,\ny sale la mesma cosa.",113,2,2,130,"El San Lorenzo",9,6,"oa",63,0,-1,0,454,454,"5512","",0,"","","",1,0,0,[],""],["frenk_t2-n5513",6,"¡Desdichado del que emplea\nsu voluntad y apetito,\nsiquiera por un ratito,\nen el amor de una fea!",114,2,17,130,"Estrofa suelta",11,4,"ea",54,0,-1,0,454,454,"5513","",0,"","","",1,0,0,[],""],["frenk_t2-n5514",6,"Si tú te enamoras\nde una jamona,\npronto verás que agarras\ntamaña mona.",105,2,-1,130,"Estrofa suelta",6,4,"oa",7,0,-1,0,454,454,"5514","",0,"","","",1,0,0,[],""],["frenk_t2-n5515",6,"Buen tonto es el que se casa\ny quiere tener mujer:\nse busca ama a quien servir\ny floja a quien mantener.",108,2,8,130,"Estrofa suelta",0,4,"e",20,0,-1,0,454,454,"5515","",0,"","","",2,0,0,[],""],["frenk_t2-n5516",6,"Todo el hombre que se casa\nsin tomar buen parecer\nno sabe lo que le pasa,\ntampoco lo que va a hacer:\nque lleva un diablo a su casa,\nque tiene que mantener.",106,2,4,130,"El siquisirí",9,6,"e",20,0,-1,0,454,454,"5516","",0,"","","",5,0,0,[],""],["frenk_t2-n5517a",6,"El hombre que tiene\nmujer celosa\nsiempre va por la calle\nmás que rabiosa.\nPues ¡qué cariño!\nElla va presumiendo —y el pobre viejo\nle carga el niño.",113,2,2,130,"Cielito lindo",4,7,"io",176,0,-1,0,454,454,"5517a","",0,"","","",1,0,0,[],""],["frenk_t2-n5518",6,"Y a mi Dios le envío las quejas\npor lo que hoy se ha decretado;\ny hoy mi corazón refleja,\ny sé que estoy bien escarmentado:\nque el que enamore a una vieja\ndebe de morir ahorcado.",106,2,4,130,"El siquisirí",9,6,"ao",14,0,-1,0,455,455,"5518","",0,"","","",1,0,0,[],""],["frenk_t2-n5519",6,"Por el hueco de un carrizo\ncorre el agua y no la vemos;\n¡para qué queremos viejas,\nsi con muchachas tenemos!",108,2,8,130,"Estrofa suelta",0,4,"eo",127,0,-1,0,455,455,"5519","",0,"","","",1,0,0,[],""],["frenk_t2-n5520",6,"Ya no pintan a Cupido\nvendado y niño chiquito:\nahora ya lo pintan viejo,\ncon anteojos y piquito.",105,2,-1,130,"Estrofa suelta",0,4,"io",119,0,-1,0,455,455,"5520","",0,"","","",1,0,0,[],""],["frenk_t2-n5521",6,"“El amor en la vejez\nes puritita tanteada”:\neso dice un japonés,\nllamado Noqueda Nada.",122,2,13,130,"Estrofa suelta",1,4,"aa",49,0,-1,0,455,455,"5521","",0,"","","",1,0,0,[],""],["frenk_t2-n5522",6,"Yo a los hombres comparo (cielito lindo)\ncon el mosquito:\ndonde dan el piquete (cielito lindo)\ndan el brinquito;\ny son fatales,\ny hasta en el mismo infierno (cielito lindo)\nson informales.",106,2,4,130,"Cielito lindo",4,7,"ae",26,0,-1,0,455,455,"5522","",0,"","","",1,0,0,[],""],["frenk_t2-n5523",6,"A los casados les gusta\nlinternitas carmesí;\na su mujer la hacen guaje\ny le dan en qué sentir.",105,2,-1,130,"Linternas y linternitas",0,4,"i",-1,0,-1,0,455,455,"5523","",0,"","","",1,0,0,[],""],["frenk_t2-n5524",6,"Alacrán de Durango,\ncola de cuatro cañutos,\n¿qué me les das a los hombres,\nque me los vuelves tan brutos?",107,2,11,130,"Estrofa suelta",0,4,"uo",587,0,-1,0,455,455,"5524","",0,"","","",1,0,0,[],""],["frenk_t2-n5525",6,"¿De qué le sirve a los hombres\npresumir de valentones,\nsi cuando están en su casa\nse les caen los pantalones?",107,2,11,130,"La calandria",0,4,"oe",34,0,-1,0,455,455,"5525","",0,"","","",1,0,0,[],""],["frenk_t2-n5527",6,"Ya con ésta me despido,\npor la sombra del rastrojo,\nque por falta de dinero\nno se casa tanto flojo.",115,2,3,130,"Vasito de agua de coco",0,4,"oo",400,0,-1,0,456,456,"5527","",0,"","","",72,0,0,[],""],["frenk_t2-n5528",6,"¡Ah, qué vacilada con tanto celoso!\nNi comen, ni duermen, ni tienen reposo;\nse ven al espejo al amanecer:\nno sea que la frente les vaya a crecer.",105,2,-1,130,"Los celotes",3,4,"e",20,0,-1,0,456,456,"5528","",0,"","","",1,0,0,[],""],["frenk_t2-n5529",6,"Los hombres y los naranjos\nparientes habían de ser:\nsi no se les ponen cuernos,\nno pueden reverdecer.",105,2,-1,130,"María, María",0,4,"e",20,0,-1,0,456,456,"5529","",0,"","","",1,0,0,[],""],["frenk_t2-n5530",6,"Las muchachas de mi tierra\nson como las avellanas:\nuna que otra salen buenas,\ny las demás salen vanas.",105,2,-1,130,"Por abajo cone el agua; Estrofa suelta",0,4,"aa",263,0,-1,0,456,456,"5530","",0,"","","",7,0,0,[],""],["frenk_t2-n5531",6,"Bonitas son las estrellas:\nparecen artificiales;\ntambién hay mujeres bellas,\ny entre ellas unas formales:\nel trabajo es dar con ellas.",105,2,-1,130,"La leva; Soy hijo de padecer",7,5,"ea",89,0,-1,0,456,456,"5531","",0,"","","",1,0,0,[],""],["frenk_t2-n5532",6,"Las mujeres de estos tiempos\nson como las alcachofas,\nque ostentan poca sustancia\ny todas se vuelven hojas.",105,2,-1,130,"Estrofa suelta",0,4,"oa",-1,0,-1,0,456,456,"5532","",0,"","","",4,0,0,[],""],["frenk_t2-n5533",6,"Ya se acabaron las feas,\nahora todas son bonitas:\nlas prietas y cacarizas\nse miran hoy exquisitas.",105,2,-1,130,"Estrofa suelta",0,4,"ia",-1,0,-1,0,456,456,"5533","",0,"","","",1,0,0,[],""],["frenk_t2-n5534",6,"Por más agua que caiga\nde la alta peña,\nnunça podrá ser blanca\nla que es trigueña.",105,2,-1,130,"Estrofa suelta, Anoche yo soñaba; La bamba; Con ésta y no más con ésta; El león; El pájaro cú; La zamba",6,4,"ea",291,0,-1,0,456,456,"5534","",0,"","","",1,0,0,[],""],["frenk_t2-n5536",6,"Las muchachas de hoy en día\nson como la flor de otate;\nligeritas para el baile,\npero flojas pa el metate.",119,2,12,130,"Estrofa suelta, La Sanmarqueña",0,4,"ae",-1,0,-1,0,457,457,"5536","",0,"","","",14,0,0,[],""],["frenk_t2-n5537",6,"¡Baila, baila, bailadora,\npiececitos de malacate!\nSon buenas para bailar,\ny flojas para el metate.",108,2,8,130,"Estrofa suelta",0,4,"ae",384,0,-1,0,457,457,"5537","",0,"","","",1,0,0,[],""],["frenk_t2-n5539",6,"Las mujeres de mi tierra\nson como el café molido;\nno saben guisar frijoles\ny quieren tener marido.",105,2,-1,130,"María, María; Estrofa suelta",0,4,"io",101,0,-1,0,457,457,"5539","",0,"","","",2,0,0,[],""],["frenk_t2-n5540",6,"Muchas no saben guisar\ntantito chile con queso,\ny ya se quieren casar:\n¿de qué taconean tan recio?",105,2,-1,130,"Estrofa suelta",0,4,"eo",-1,0,-1,0,457,457,"5540","",0,"","","",1,0,0,[],""],["frenk_t2-n5541",6,"Voy a hablar de las casadas,\naunque les parezca mal:\nporque no hacen ni un costal,\naunque estén desocupadas.",112,2,6,130,"Estrofa suelta",11,4,"aa",282,0,-1,0,457,457,"5541","",0,"","","",2,0,0,[],""],["frenk_t2-n5542",6,"¡Cuándo llegará este cuándo\nque tanto el hombre desea,\nque a la mujer floja vea\nen su casa trabajando!",105,2,-1,130,"Estrofa suelta",11,4,"ao",33,0,-1,0,457,457,"5542","",0,"","","",1,0,0,[],""],["frenk_t2-n5544",6,"Dos Collantes a la Boquilla\nse me pegó una conchuda;\nestas muchachas de ahora\nse quieren casar joyudas.",108,2,8,130,"Estrofa suelta",0,4,"ua",-1,0,-1,0,458,458,"5544","",0,"","","",1,0,0,[],""],["frenk_t2-n5545",6,"Hay unas mujeres\nrete mitoteras,\nque apenas las tientan,\ny se vuelven fieras.",129,2,9,130,"Estrofa suelta",0,4,"ea",-1,0,-1,0,458,458,"5545","",0,"","","",1,0,0,[],""],["frenk_t2-n5546",6,"¡Dios me libre de una honrada,\nde esas que se santifican,\nque son como la pimienta:\ncuando no amargan, pican!",108,2,8,130,"Estrofa suelta",0,4,"ia",588,0,-1,0,458,458,"5546","",0,"","","",1,0,0,[],""],["frenk_t2-n5548",6,"A orillas de una laguna\nse quejaba una tortuga,\nen sus quejidos decía:\n“La más bonita se arruga.”",108,2,8,130,"La Sanmarqueña; Por lo alto doy cincuenta",0,4,"ua",468,0,-1,0,458,458,"5548","",0,"","","",4,0,0,[],""],["frenk_t2-n5549",6,"“El demonio son los hombres”:\neso dicen las mujeres,\npero siempre están deseando\nque el demonio se las lleve.",107,2,11,130,"Estrofa suelta",0,4,"ee",-1,0,-1,0,458,458,"5549","",0,"","","",7,0,0,[],""],["frenk_t2-n5550",6,"Al pasar el Río Jordán\noí que estaban diciendo;\neran las hijas de Adán:\nno quieren, pero pariendo.",108,2,8,130,"Estrofa suelta",1,4,"eo",52,0,-1,0,459,459,"5550","",0,"","","",1,0,0,[],""],["frenk_t2-n5551",6,"Hay mujeres en el mundo\nque nos presumen de doncellas;\nllevan un hijo en el brazo,\ny dicen que no son de ellas.",113,2,2,130,"Estrofa suelta",0,4,"ea",89,0,-1,0,459,459,"5551","",0,"","","",1,0,0,[],""],["frenk_t2-n5552",6,"Las mujeres más baratas\nse les conoce al momento:\na cualquiera le dan entrada,\nsin tener conocimiento,\ny después de embarazadas,\nson los suspiros al viento.",106,2,4,130,"La morena",9,6,"eo",94,0,-1,0,459,459,"5552","",0,"","","",1,0,0,[],""],["frenk_t2-n5553",6,"Las mujeres de hoy en día\nson como la tuna mansa;\napenas cumplen quince años,\ny ya traen tamaña — trenza.",107,2,11,130,"La Sanmarqueña; Yo ya me voy; Estrofa suelta",5,4,"ea",-1,0,-1,0,459,459,"5553","",0,"","","",7,0,0,[],""],["frenk_t2-n5554b",6,"La mujer en el amor\nse parece a la gallina:\ncuando se le muere el gallo\ny a cualquier pollo se arrima;\ncon otras habrán jugado,\npero conmigo se espina[n].",113,2,2,130,"La leva",9,6,"",-1,0,-1,0,459,459,"5554b","",0,"","","",2,0,0,[],""],["frenk_t2-n5555",6,"Las muchachas casaderas\nque ya se dan al demonio\ninvocan a San Antonio,\npidiendo las marrulleras:\n“Matrimonio, matrimonio.”",105,2,-1,130,"Estrofa suelta",7,5,"oo",169,0,-1,0,459,459,"5555","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5556",6,"Las muchachas de hoy en día\nson como el mismo demonio:\ncon unas tijeras mochas\npelaron a San Antonio.",124,2,16,130,"La vecina de allí enfrente; Estrofa suelta",0,4,"oo",169,0,-1,0,459,459,"5556","",0,"","","",14,0,0,[],""],["frenk_t2-n5558",6,"Las mujeres al querer\ntienen de más un sentido;\nquerellan a sus marido [s]\ncomo potro apersogado:\nrelinchido y relinchido.",108,2,8,130,"Estrofa suelta",7,5,"io",101,0,-1,0,460,460,"5558","",0,"","","",1,0,0,[],""],["frenk_t2-n5559",6,"Las mujeres son el diablo,\nsegún lo tengo entendido,\ny cuando quieren a otro hombre\nhacen guaje a su marido.",115,2,3,130,"La chinita",0,4,"io",101,0,-1,0,460,460,"5559","",0,"","","",8,0,0,[],""],["frenk_t2-n5560",6,"La mujer que se casa\nle pide a Dios\nque le dé un buen marido (cielito lindo),\npa tener dos;\ntan cierto es,\nque la que menos tiene (cielito lindo)\ntiene de a tres.",112,2,6,130,"Cielito lindo",4,7,"e",218,0,-1,0,460,460,"5560","",0,"","","",1,0,0,[],""],["frenk_t2-n5561c",6,"La mujer que quiere a dos\nlos quiere como hermanitos:\na uno le pone los cuernos\ny al otro los pitoncitos;\nuno le carga la jaula\ny [el] otro los pajaritos.",105,2,-1,130,"El venadito",9,6,"io",254,0,-1,0,460,460,"5561c","",0,"","","",12,0,0,[],""],["frenk_t2-n5562",6,"La mujer que quiere a dos\nvive sin ninguna pena:\na uno le hace el desayuno\ny al otro le hace la cena,\npa que la perdone Dios\ny le acomplete la docena.",113,2,2,130,"El triunfo’*",9,6,"ea",59,0,-1,0,460,460,"5562","",0,"","","",12,0,0,[],""],["frenk_t2-n5563",6,"Las mujeres y los gatos\nson de la misma opinión:\nque teniendo carne en casa,\nsalen a buscar ratón.",107,2,11,130,"La Sanmarqueña; El huizache; Marieta; El tejón",0,4,"o",31,0,-1,0,461,461,"5563","",0,"","","",4,0,0,[],""],["frenk_t2-n5564",6,"Pelonas de mala raza,\nson como gatos tragones:\nteniendo carne en su casa,\nsalen a buscar ratones.",105,2,-1,130,"El vacilón",1,4,"oe",34,0,-1,0,461,461,"5564","",0,"","","",1,0,0,[],""],["frenk_t2-n5565",6,"Una novia engaña,\ndos hacen tarugo,\ntres enseñan mañas,\ncuatro hacen dos yugos.",115,2,3,130,"Las dos Marías",0,4,"uo",-1,0,-1,0,461,461,"5565","",0,"","","",1,0,0,[],""],["frenk_t2-n5566",6,"Las mujeres son el diablo,\nparientes del alacrán:\ncuando ven al hombre pobre\nparan la cola y se van.",105,2,-1,130,"María, María; Al derecho y al revés; El gusano; El mosquito; Soy de Zacatula; El toro; Estrofa suelta",0,4,"a",147,0,-1,0,461,461,"5566","",0,"","","",8,0,0,[],""],["frenk_t2-n5567",6,"Las muchachas de hoy en día\nson como la tuna blanca;\ncuando ven un peso duro,\n“Vámonos pa la barranca.”",105,2,-1,130,"Serían las dos; La Sanmarqueña",0,4,"aa",75,0,-1,0,461,461,"5567","",0,"","","",14,0,0,[],""],["frenk_t2-n5568",6,"“¡Ave María Purísima,\ndice una beata,\nqué bonitos son los hombres (mi vida)\ngastando plata!”",115,2,3,130,"El tamarindo",3,4,"aa",74,0,-1,0,461,461,"5568","",0,"","","",1,0,0,[],""],["frenk_t2-n5570",6,"Mujer que pide dinero\nlibera nos Dominé,\ny hombre feo y arrancado\nrequiescat in pace, amén.",106,2,4,130,"Los papaquis",3,4,"e",-1,0,-1,0,461,461,"5570","",0,"","","",1,0,0,[],""],["frenk_t2-n5571",6,"Dijo el sabio Salomón\nque el que engaña a una mujer\nno tiene perdón de Dios —\nsi no la engaña otra vez.",106,2,4,130,"Estrofa suelta",0,4,"e",-1,0,-1,0,462,462,"5571","",0,"","","",3,0,0,[],""],["frenk_t2-n5572",6,"No tiene perdón de Dios\nquien le pega a una mujer;\nno tiene perdón de Dios,\nsi no le pega otra vez.",105,2,-1,130,"El Balajú; Estrofa suelta",0,4,"e",-1,0,-1,0,462,462,"5572","",0,"","","",1,0,0,[],""],["frenk_t2-n5573",6,"Yo le pregunté a Cupido\nel valor de una catrina,\ny me respondió afligido\nque el valor de una gallina\nno pasa de real y medio,\naunque la pluma sea fina.",108,2,8,130,"Estrofa suelta",9,6,"ia",11,0,-1,0,462,462,"5573","",0,"","","",8,0,0,[],""],["frenk_t2-n5574",6,"En el huerto de mi casa\ntengo sembrado un romero;\nel que pierde una mujer\nno pierde ningún dinero:\nes como si uno perdiera\nde su caballo el suadero.",105,2,-1,130,"El venadito; Estrofa suelta",9,6,"eo",38,0,-1,0,462,462,"5574","",0,"","","",1,0,0,[],""],["frenk_t2-n5575",6,"Del otro lado del río\nsonaron las campanitas;\n¡qué bonitos son los hombres\nque dejan mujeres bonitas!",106,2,4,130,"El ramo",0,4,"ia",258,0,-1,0,462,462,"5575","",0,"","","",1,0,0,[],""],["frenk_t2-n5576",6,"Toda mujer casada (lindo cielito)\nse da paquete,\ncon la cara pintada (lindo cielito)\nde colorete;\ny se reluja,\naunque [al] pobre marido (lindo cielito)\nlo deje bruja.",113,2,2,130,"Cielito lindo",4,7,"ua",586,0,-1,0,462,462,"5576","",0,"","","",1,0,0,[],""],["frenk_t2-n5577",6,"La mujer que se pinta (cielito lindo)\nse le afigura\nque se ve más bonita (cielito lindo)\ncon la pintura;\ny es un fracaso,\npues se le ve la cara (cielito lindo),\ncomo un payaso.",112,2,6,130,"Cielito lindo",4,7,"ao",145,0,-1,0,463,463,"5577","",0,"","","",2,0,0,[],""],["frenk_t2-n5578",6,"La mujer que se pinta (cielito lindo)\nparece al queso,\ncon la cara pintada — pero la mugre\nen el pescuezo;\nmirando en eso,\nno me fijo en la mugre (cielito lindo):\nme gusta el queso.",113,2,2,130,"Cielito lindo",4,7,"eo",48,0,-1,0,463,463,"5578","",0,"","","",2,0,0,[],""],["frenk_t2-n5579",6,"Las muchachas de hoy en día\nson como el pan y el queso;\nmuy pintadas de la cara,\npero véanles el pescuezo.",107,2,11,130,"La Sanmarqueña; Estrofa suelta",0,4,"eo",345,0,-1,0,463,463,"5579","",0,"","","",14,0,0,[],""],["frenk_t2-n5580",6,"Todos dicen “Qué bonita”,\nporque la ven muy pintada:\nsi les cae un aguacero,\nquedan toditas chorreadas.",114,2,17,130,"Yo ya me voy",0,4,"aa",-1,0,-1,0,463,463,"5580","",0,"","","",1,0,0,[],""],["frenk_t2-n5581",6,"Las mujeres de hoy en día\ndeslumbran al pasar;\npero las ves recién bañadas,\ny no te quieres casar.",107,2,11,130,"Estrofa suelta",0,4,"a",21,0,-1,0,463,463,"5581","",0,"","","",7,0,0,[],""],["frenk_t2-n5582",6,"Quien se crea de una pelona\nes un tonto verdadero,\nporque en la noche lo desvelan\nlos piojos de su mechero.",105,2,-1,130,"El vacilón",0,4,"eo",38,0,-1,0,463,463,"5582","",0,"","","",1,0,0,[],""],["frenk_t2-n5583",6,"Las damas en la ocasión\nson puercas y revoltosas;\nson de mala condición:\nflojas, borrachas, chismosas,\ny celosas de pilón.",105,2,-1,130,"Estrofa suelta",7,5,"o",31,0,-1,0,463,463,"5583","",0,"","","",1,0,0,[],""],["frenk_t2-n5584",6,"La mujer que ya es casada\nse devisa en el semblante;\ntrae la camisa zafada\npor detrás y por delante,\nla cabeza enmarañada,\ncon riesgo de que me espante.",113,2,2,130,"El bejuquito",9,6,"ae",47,0,-1,0,463,463,"5584","",0,"","","",1,0,0,[],""],["frenk_t2-n5585",6,"Las mujeres a los quince\nson preciosas, es muy cierto,\npero cuando tienen hijos\napestan a perro muerto.",115,2,3,130,"La chinita",0,4,"eo",88,0,-1,0,463,463,"5585","",0,"","","",3,0,0,[],""],["frenk_t2-n5587",6,"Las mujeres ya maduras\nquieren linternas violeta;\ncomo son grullas baleadas,\nesas nos rompen la jeta.",105,2,-1,130,"Linternas y lintemitas",0,4,"ea",200,0,-1,0,464,464,"5587","",0,"","","",1,0,0,[],""],["frenk_t2-n5589",6,"Toda mujer mundana\nque no hace hoyo donde mea\ntiene la cresta doblada\ny floja la chimenea.",108,2,8,130,"Estrofa suelta",0,4,"ea",54,0,-1,0,464,464,"5589","",0,"","","",1,0,0,[],""],["frenk_t2-n5590",6,"La mujer en el amor\nes cual mula de alquiler:\nempieza a todo correr,\ny se para en lo mejor.",122,2,13,130,"Estrofa suelta",11,4,"o",72,0,-1,0,464,464,"5590","",0,"","","",2,0,0,[],""],["frenk_t2-n5591",6,"Dicen que las muías no oyen\nporque son muy orejonas,\npero las pegan al carro,\ny hasta chiflan, las chirrionas.",105,2,-1,130,"El gato",0,4,"oa",549,0,-1,0,464,464,"5591","",0,"","","",1,0,0,[],""],["frenk_t2-n5592",6,"Las muchachas de la zona\nya no guisan con manteca:\nahora guisan con el sebo\nque se quitan de la horqueta.",129,2,9,130,"El tarachi; El pato",0,4,"ea",-1,0,-1,0,464,464,"5592","",0,"","","",1,0,0,[],""],["frenk_t2-n5593",6,"Las putas de Hermosillo\nya no cogen en colchón:\nahora cogen en el suelo,\nporque tienen purgación.",129,2,9,130,"Estrofa suelta",0,4,"o",31,0,-1,0,464,464,"5593","",0,"","","",1,0,0,[],""],["frenk_t2-n5594",6,"Pues las putas de hoy en día\nya no lavan con jabón:\nhora lavan con los mecos,\npues, de tanto recabrón.",134,2,31,130,"El pato",0,4,"o",31,0,-1,0,464,464,"5594","",0,"","","",1,0,0,[],""],["frenk_t2-n5595",6,"No hay ferrocarril sin curvas,\nni camino real con yerbas,\nni camisón de mujer\nque no haya limpiado vergas.",108,2,8,130,"Estrofa suelta",0,4,"ea",-1,0,-1,0,464,464,"5595","",0,"","","",1,0,0,[],""],["frenk_t2-n5596",6,"Las muchachas de mi tierra\nson como la yerbabuena;\narriba tienen la fama\ny abajo la cosa buena.",108,2,8,131,"La Sanmarqueña",0,4,"ea",59,0,-1,0,465,465,"5596","",0,"","","",7,0,0,[],""],["frenk_t2-n5597",6,"Todas las mujeres tienen\nen el pecho una aceituna,\npero más abajo tienen\nla rueda de la fortuna.",107,2,11,131,"La Sanmarqueña",1,4,"ua",56,0,-1,0,465,465,"5597","",0,"","","",11,0,0,[],""],["frenk_t2-n5598",6,"Todas las mujeres tienen\nen el pecho dos melones,\npero más abajo tienen\nel cuartel de los pelones.",105,2,-1,131,"Estrofa suelta, La Sanmarqueña",1,4,"oe",34,0,-1,0,465,465,"5598","",0,"","","",11,0,0,[],""],["frenk_t2-n5599",6,"Todas las mujeres tienen\nen el pecho una esperanza,\npero más abajo tienen\nel retrato de Carranza.",107,2,11,131,"La cucaracha",1,4,"aa",163,0,-1,0,465,465,"5599","",0,"","","",11,0,0,[],""],["frenk_t2-n5600",6,"Todas las mujeres tienen\nen el pecho una amapola,\npero más abajo tienen\nla funda de mi pistola.",108,2,8,131,"Estrofa suelta, La cucaracha; La Sanmarqueña",1,4,"oa",321,0,-1,0,465,465,"5600","",0,"","","",11,0,0,[],""],["frenk_t2-n5601",6,"Las muchachas de hoy en día\nse parecen mucho al pato:\nde la cintura pa abajo\nno más tiran caderazos.",115,2,3,131,"La Sanmarqueña",0,4,"ao",-1,0,-1,0,465,465,"5601","",0,"","","",14,0,0,[],""],["frenk_t2-n5602",6,"“La que es trigueña (mi alma),\ndecía un torero,\nen la puerta le aguarda\ndel coleadero.”",105,2,-1,131,"Estrofa suelta",0,4,"eo",38,0,-1,0,465,465,"5602","",0,"","","",1,0,0,[],""],["frenk_t2-n5603",6,"Las muchachas de hoy en día\nusan las faldas tan altas;\nsi quieren, te dan un beso,\ny si no, te dan las gracias.",107,2,11,131,"La Sanmarqueña",0,4,"aa",-1,0,-1,0,465,465,"5603","",0,"","","",14,0,0,[],""],["frenk_t2-n5605",6,"Las muchachas de este tiempo\nson como la carne frita;\napenas dejan un baile,\nemprestan su semillita.",108,2,8,131,"Estrofa suelta",0,4,"ia",50,0,-1,0,466,466,"5605","",0,"","","",9,0,0,[],""],["frenk_t2-n5606",6,"La mujer coge el juguete,\nlo que cuelga queda abajo,\ny en su agujero lo mete,\ncon poco o mucho trabajo.",105,2,-1,131,"Estrofa suelta",1,4,"ao",168,0,-1,0,466,466,"5606","",0,"","","",1,0,0,[],""],["frenk_t2-n5607",6,"No te creas de un zapatero\nporque lo veas con dinero,\nporque te da de comer\npuros pedazos de cuero.",105,2,-1,131,"Corrido de los destinos",0,4,"eo",38,0,-1,0,466,466,"5607","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5608",6,"No te creas de un arrierito,\naunque lo veas con corbata,\nporque te dará de comer\npuros pedazos de reata.",105,2,-1,131,"Corrido de los destinos",0,4,"aa",74,0,-1,0,466,466,"5608","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5610",6,"No te creas de un carnicero,\naunque te dé muchos besos,\nporque te dará de comer\nun montonote de huesos.",105,2,-1,131,"Corrido de los destinos",0,4,"eo",529,0,-1,0,466,466,"5610","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5611",6,"No te creas de un peluquero,\nporque luego anda con celos,\ny te dará de comer\nuna baraña de pelos.",105,2,-1,131,"Corrido de los destinos",0,4,"eo",192,0,-1,0,466,466,"5611","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5612",6,"No te creas de un maquinista,\naunque te diga “Grandota”,\nporque te da de comer\npuros hilos de la estopa.",105,2,-1,131,"Corrido de los destinos",0,4,"oa",-1,0,-1,0,466,466,"5612","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5613",6,"No te creas de un soldadito,\naunque te hable en la cocina,\nporque te dará de comer\npuritita carabina.",105,2,-1,131,"Corrido de los destinos",0,4,"ia",11,0,-1,0,466,466,"5613","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5614",6,"No te creas de un gendarmito,\naunque lo veas muy bonito,\nporque unos dan de comer\npistola, garrote y pito.",105,2,-1,131,"Corrido de los destinos",0,4,"io",119,0,-1,0,467,467,"5614","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5615",6,"Una pregunta curiosa\nquiero hacerle a una mujer:\n“¿Qué fruta es la más sabrosa,\nla que un hombre ha de comer?”",105,2,-1,131,"Estrofa suelta",1,4,"e",20,0,-1,0,467,467,"5615","",0,"","","",1,0,0,[],""],["frenk_t2-n5616",6,"Ya viene la luna nueva,\nrodeada de cucarachas;\n¡qué bonitos son los hombres\narriba de las muchachas!",108,2,8,131,"Estrofa suelta",0,4,"aa",589,0,-1,0,467,467,"5616","",0,"","","",2,0,0,[],""],["frenk_t2-n5617",6,"Del cielo cayó un pañuelito\nclaveteado de alfileres;\n¡qué uso dan los hombres\nencima de las mujeres!",119,2,12,131,"Estrofa suelta",0,4,"ee",55,0,-1,0,467,467,"5617","",0,"","","",1,0,0,[],""],["frenk_t2-n5618",6,"¡Quién dice que no es bonito\ntener una chichonota,\nestando mamándole una\ny de cabecera la otra!",108,2,8,131,"Estrofa suelta",0,4,"oa",-1,0,-1,0,467,467,"5618","",0,"","","",2,0,0,[],""],["frenk_t2-n5619",6,"Una verga bien templada\nhace bonita figura,\ncon la cabeza pelada\ny el cuero hasta la cintura.",108,2,8,131,"Estrofa suelta",1,4,"ua",17,0,-1,0,467,467,"5619","",0,"","","",1,0,0,[],""],["frenk_t2-n5620",6,"Mujeres, ¿de qué se admiran,\nsabiéndolo claramente?\nLa leche que echan los hombres\nse cuaja y se vuelve gente.",108,2,8,131,"Estrofa suelta",0,4,"ee",15,0,-1,0,467,467,"5620","",0,"","","",1,0,0,[],""],["frenk_t2-n5621",6,"A los técnicos les gustan\nlinternas con mucha luz,\ny con las gatas se ponen\nchangos como un arcabuz.",105,2,-1,131,"Linternas y linternitas",0,4,"u",109,0,-1,0,467,467,"5621","",0,"","","",1,0,0,[],""],["frenk_t2-n5622",6,"Albañiles, carpinteros,\nzapateros y boleros\ntraen linternas descompuestas\npor los golpes de sus cueros.",105,2,-1,131,"Linternas y linternitas",0,4,"eo",22,0,-1,0,467,467,"5622","",0,"","","",1,0,0,[],""],["frenk_t2-n5624",6,"En un callejón\ncorren limas y limones;\nhay muchachas bonitas,\npero no para los huevones.",130,2,21,132,"Estrofa suelta",0,4,"oe",34,0,-1,0,471,471,"5624","",0,"","","",1,0,0,[],""],["frenk_t2-n5625",6,"Allí viene el cojo\npor la ventana,\nhaciéndole señas\na doña Juana.",121,2,26,132,"Estrofa suelta",6,4,"aa",4,0,-1,0,471,471,"5625","",0,"","","",1,0,0,[],""],["frenk_t2-n5626",6,"El amo corrió a su criado\na palos por el zaguán,\nporque quería con la niña\ndizque bailar el can-can.",105,2,-1,132,"El can-can",0,4,"a",147,0,-1,0,471,471,"5626","",0,"","","",1,0,0,[],""],["frenk_t2-n5627",6,"Yo vide bajar un indio,\nabrazando a su comadre;\nyo no me admiro del indio,\nsino quien lo hizo compadre.",115,2,3,132,"La indita",1,4,"ae",166,0,-1,0,471,471,"5627","",0,"","","",2,0,0,[],""],["frenk_t2-n5628",6,"Su mamá le dijo a Julia:\n—¿Qué te dijo ese señor?\n—Mamá, no me dijo nada,\nno más me trató de amor.",124,2,16,132,"La vecina de allí enfrente; La Julia",0,4,"o",72,0,-1,0,471,471,"5628","",0,"","","",1,0,0,[],""],["frenk_t2-n5629",6,"La Marieta fue a los toros,\nsu mamá no lo sabía,\nporque andaba de coqueta\ncon los de caballería.",105,2,-1,132,"Marieta",0,4,"ia",0,0,-1,0,471,471,"5629","",0,"","","",1,0,0,[],""],["frenk_t2-n5630",6,"Marieta se fue a los toros,\nla llevó su querido,\npero al ver salir al toro\ncreyó que era su marido.",105,2,-1,132,"Marieta",0,4,"io",101,0,-1,0,471,471,"5630","",0,"","","",1,0,0,[],""],["frenk_t2-n5632",6,"Yo miré a una presumida\nbailando con un soltero,\ndisfrutando de la vida,\ny le sonaba el dinero;\nle decía la presumida:\n“¡Ay, señor, cuánto lo quiero!”",112,2,6,132,"La presumida",9,6,"eo",38,0,-1,0,472,472,"5632","",0,"","","",1,0,0,[],""],["frenk_t2-n5633",6,"Juana la chunca se quiere casar,\nquiere zapatos de raso,\nquiere enaguas de satín\ny quiere rebozo a la polca,\npero de puro esmerín.",109,2,7,132,"Versos del casamiento",7,5,"i",211,0,-1,0,472,472,"5633","",0,"","","",1,0,0,[],""],["frenk_t2-n5634",6,"Churripampli se casa\ncon la torera,\ny por eso le dicen\nchurripampliera.",106,2,4,132,"Churripampli se casa",6,4,"ea",44,0,-1,0,472,472,"5634","",0,"","","",1,0,0,[],""],["frenk_t2-n5635",6,"El pipiólo y la pipióla\nun día se querían casar;\nque se iban a condenar.\nLa pipiolita decía,\nmuy llena de mal humor:\n“Pos ningún pecado hicieron\nni Eva, ni Adán con su amor.",115,2,3,132,"La pipiolita",4,7,"o",72,0,-1,0,472,472,"5635","",0,"","","",1,0,0,[],""],["frenk_t2-n5636",6,"Los pipiólos se han casado,\nsu mamá los regañó,\npero el cura está contento\npor los “fierros” que cobró.",115,2,3,132,"La pipiolita",0,4,"o",2,0,-1,0,472,472,"5636","",0,"","","",1,0,0,[],""],["frenk_t2-n5637",6,"Una negra se casó\ncon un negro colorín,\ny los hijitos salieron\nal color del aserrín.",109,2,7,132,"¡Ay, milongo!",0,4,"i",211,0,-1,0,472,472,"5637","",0,"","","",1,0,0,[],""],["frenk_t2-n5638",6,"Pobrecito, lo casaron,\ny era muy buena persona;\nlo casaron a traición:\n¡ay, hijo de su pelona!",107,2,11,132,"El jarabe loco",0,4,"oa",7,0,-1,0,472,472,"5638","",0,"","","",1,0,0,[],""],["frenk_t2-n5639",6,"Vaya un pleito divertido\nentre dos recién casados:\nque apenas tienen un mes,\ny están todos arañados.",105,2,-1,132,"Estrofa suelta",0,4,"ao",18,0,-1,0,472,472,"5639","",0,"","","",1,0,0,[],""],["frenk_t2-n5640",6,"Gran escándalo y alarma\nhay en este matrimonio:\nel hombre de rigor se arma,\ny la mujer, del demonio,\nporque llora, chilla y brama\ncomo los del manicomio.",105,2,-1,132,"Los casados",9,6,"oo",-1,0,-1,0,473,473,"5640","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5641",6,"Su mujer se lo decía:\n“Ciro, no andes paseando;\nyo te doy este consejo,\nno digas porque te mando.”",109,2,7,132,"Estrofa suelta",0,4,"ao",33,0,-1,0,473,473,"5641","",0,"","","",1,0,0,[],""],["frenk_t2-n5642",6,"Y estaba el indio muy malo,\ny la india a su cabecera,\ncon un rosario en la mano,\nrogando a Dios que muriera.",105,2,-1,132,"La indita; Estrofa suelta",0,4,"ea",44,0,-1,0,473,473,"5642","",0,"","","",1,0,0,[],""],["frenk_t2-n5643",6,"Una vez una señora\nvio a su esposo fenecer;\nle negó la cantimplora,\ny se le murió de sed.",105,2,-1,132,"La cantimplora",0,4,"e",-1,0,-1,0,473,473,"5643","",0,"","","",1,0,0,[],""],["frenk_t2-n5644",6,"Y lloraba una casada\nla muerte de su marido;\nlloraba y se consolaba:\nque otro le quedaba vivo.",105,2,-1,132,"La Lloroncita",0,4,"io",-1,0,-1,0,473,473,"5644","",0,"","","",1,0,0,[],""],["frenk_t2-n5645",6,"Una mujer, por supuesto,\nse le murió su marido;\npero yo digo: ¿qué es esto?,\nel llorar es muy fingido:\nno llora porque está muerto,\nsino por el que está vivo.",112,2,6,132,"La leva",9,6,"io",-1,0,-1,0,473,473,"5645","",0,"","","",1,0,0,[],""],["frenk_t2-n5646",6,"Ahora si les cantara\nlo que a mí me ha sucedido:\nque una Llorona lloraba\nla muerte de su marido,\nque si no se hubiera muerto,\nLlorona, estuviera vivo.",105,2,-1,132,"La Llorona",9,6,"io",-1,0,-1,0,473,473,"5646","",0,"","","",1,0,0,[],""],["frenk_t2-n5647",6,"Don Ferruco en la alameda\nestá que se cae de risa,\nporque a su fiel cocinera\nse le cayó la camisa.",108,2,8,132,"Don Ferruco; Estrofa suelta",0,4,"ia",68,0,-1,0,473,473,"5647","",0,"","","",1,0,0,[],""],["frenk_t2-n5648",6,"Doña Pepa y don Simón\nse fueron juntos a misa;\nde la prisa que llevaban\nolvidaron la camisa,\ny a la hora del Evangelio,\nya no aguantaban la risa.",107,2,11,132,"El venadito",9,6,"ia",68,0,-1,0,473,473,"5648","",0,"","","",1,0,0,[],""],["frenk_t2-n5651",6,"De los cincuenta pesos\nque dio una viuda\npara saltar la verja\ndel señor cura.",106,2,4,132,"La bamba",6,4,"ua",-1,0,-1,0,474,474,"5651","",0,"","","",1,0,0,[],""],["frenk_t2-n5652",6,"Ciento cincuenta pesos (cielito lindo)\npor una viuda,\nal señor cura.\nSe los pusieron:\ncomo ya estaba viejo (cielito lindo),\nse le cayeron.",112,2,6,132,"Estrofa suelta",9,6,"eo",-1,0,-1,0,474,474,"5652","",0,"","","",1,0,0,[],""],["frenk_t2-n5653",6,"Una monja y un fraile\ndurmieron juntos,\nporque les tenían miedo\na los difuntos.",105,2,-1,132,"Estrofa suelta, Cielito lindo",6,4,"uo",296,0,-1,0,474,474,"5653","",0,"","","",1,0,0,[],""],["frenk_t2-n5654",6,"Estaba la Lloroncita\nplaticándole a su tío:\n“Las penas con mis amores,\nlas penas que no son míos.”",106,2,4,132,"La Lloroncita",0,4,"io",-1,0,-1,0,474,474,"5654","",0,"","","",10,0,0,[],""],["frenk_t2-n5655",6,"¡Ay!, qué Severiana,\nse muere de amor,\ny por eso toma\nbastante licor.",105,2,-1,132,"Coplas de la Severiana",0,4,"o",72,0,-1,0,474,474,"5655","",0,"","","",4,0,0,[],""],["frenk_t2-n5656",6,"Una india se está bañando,\ny dicen que ya es mujer;\ny el que la estaba mirando\nse consolaba con ver,\npero que la goce, ¡cuándo!",117,2,5,132,"Estrofa suelta",7,5,"ao",33,0,-1,0,474,474,"5656","",0,"","","",1,0,0,[],""],["frenk_t2-n5657",6,"Una muchacha muy honrada,\nla pretendía un muchacho;\nlo quiso una temporada,\ny lo dejó por borracho;\ny después de la estocada\nse quiso poner borracho.",108,2,8,132,"El tinajón",9,6,"ao",-1,0,-1,0,475,475,"5657","",0,"","","",1,0,0,[],""],["frenk_t2-n5658",6,"Cuando quiso, ya no pudo,\nya halló a otro en su lugar,\nde jorongo colorado,\nporque lo supo granjear.",110,2,10,132,"Si te suelto como un trompo",0,4,"a",21,0,-1,0,475,475,"5658","",0,"","","",1,0,0,[],""],["frenk_t2-n5659",6,"Señores, la Petenera\nes una mujer honrada,\nque se sale a media noche (¡niña de mi corazón!),\ny vuelve en la madrugada.",105,2,-1,132,"Estrofa suelta",3,4,"aa",49,0,-1,0,475,475,"5659","",0,"","","",1,0,0,[],""],["frenk_t2-n5661",6,"Salomón, siendo tan sabio,\nuna mujer lo engañó;\ny le dice: “Gran salvaje,\n¿qué no sabes quién soy yo?”\nY después que lo hizo guaje,\nde los tientos lo colgó.",105,2,-1,132,"Estrofa suelta",9,6,"o",2,0,-1,0,475,475,"5661","",0,"","","",2,0,0,[],""],["frenk_t2-n5662",6,"A Pan Siringa rehusó,\nporque, como es bien sabido,\nera cornudo y no vio\nque se sale a media noche (¡niña de mi co-\ny vuelve en la madrugada.",105,2,-1,132,"La Petenera; Estrofa suelta",7,5,"aa",-1,0,-1,0,475,475,"5662","",0,"","","",1,0,0,[],""],["frenk_t2-n5663",6,"El viento voló el vestido\nde una muchacha en la playa,\ny de repente se vio\nen el pecho una medalla.",107,2,11,133,"La Sanmarqueña",0,4,"aa",249,0,-1,0,476,476,"5663","",0,"","","",1,0,0,[],""],["frenk_t2-n5665",6,"Una niña en un baile\nse sujetaba\nzapatito de raso\nque le apretaba.",105,2,-1,133,"La bamba; La zamba",6,4,"aa",28,0,-1,0,476,476,"5665","",0,"","","",6,0,0,[],""],["frenk_t2-n5666",6,"Una niña en un baile\nvendió un perico,\npor entrar a la moda\ndel abanico.",108,2,8,133,"La bamba; Cielito lindo",6,4,"io",141,0,-1,0,476,476,"5666","",0,"","","",6,0,0,[],""],["frenk_t2-n5667",6,"Una niña en un baile\nvendió su loro,\npor entrar a la rifa\ndel peine de oro.",105,2,-1,133,"La bamba; Cielito lindo",6,4,"oo",85,0,-1,0,476,476,"5667","",0,"","","",6,0,0,[],""],["frenk_t2-n5668",6,"Una niña en un carro\ncarne vendía:\n¡cuándo se ha visto un carro\ncarnicería!",105,2,-1,133,"La bamba",6,4,"ia",0,0,-1,0,476,476,"5668","",0,"","","",1,0,0,[],""],["frenk_t2-n5669",6,"La vecina de allí enfrente\ntiene una panadería:\na los casados les vende\ny a los solteros les fía.",114,2,17,133,"El huizache; Los panaderos",0,4,"ia",0,0,-1,0,477,477,"5669","",0,"","","",2,0,0,[],""],["frenk_t2-n5670",6,"La mujer del panadero\nya anda pidiendo el divorcio;\nse busca uno jovencito,\npara meterlo de socio,\nporque el marido es viejito\ny no le atiende al negocio.",108,2,8,133,"El siquisirí; Los panaderos",9,6,"oo",590,0,-1,0,477,477,"5670","",0,"","","",1,0,0,[],""],["frenk_t2-n5671",6,"A la pobre de Marieta\nse le quemó el delantal,\ny si no lo apaga pronto,\n¡la quemada que se da!",105,2,-1,133,"Marieta; El vacilón",0,4,"a",-1,0,-1,0,477,477,"5671","",0,"","","",1,0,0,[],""],["frenk_t2-n5672",6,"Una niña se embarcó\nen el vapor de Colón;\nel contramaestre le dice:\n“Cuidado con el fogón.”",106,2,4,133,"La candela",0,4,"o",31,0,-1,0,477,477,"5672","",0,"frenk_t4","","",6,0,0,[],""],["frenk_t2-n5673",6,"Una niña se embarcó\nen los vapores de guerra;\nel contramaestre le dice:\n“Cuidado con la candela.”",106,2,4,133,"La candela",0,4,"ea",-1,0,-1,0,477,477,"5673","",0,"frenk_t4","","",6,0,0,[],""],["frenk_t2-n5674",6,"Una niña se embarcó\nen los vapores de Venus;\nel contramaestre le dice:\n“Sólo a Jesucristo temo”.",106,2,4,133,"La candela",5,4,"eo",-1,0,-1,0,477,477,"5674","",0,"frenk_t4","","",6,0,0,[],""],["frenk_t2-n5675",6,"“Hazte arco, María Joleana”,\nle dice la vieja a su hija.\n“¿Qué ño me miras, pues, nana,\nque estoy como lagartija?”",108,2,8,133,"festrofa suelta",3,4,"ia",219,0,-1,0,477,477,"5675","",0,"","","",1,0,0,[],""],["frenk_t2-n5676",6,"Ya salió la niña puta,\nla que tenían por doncella;\nal punto de la media noche\nsalía a contar las estrellas;\nsu madre ya lo sabía,\nalcahueta que era ella.",108,2,8,133,"Estrofa suelta",9,6,"ea",-1,0,-1,0,477,477,"5676","",0,"","","",1,0,0,[],""],["frenk_t2-n5677",6,"No digo de la señora,\nsólo de la cocinera,\nque tenía su tecolote,\ncantándole en la tronera.",114,2,17,133,"El tecolote",0,4,"ea",44,0,-1,0,477,477,"5677","",0,"","","",1,0,0,[],""],["frenk_t2-n5679",6,"No lo digo por usted,\nyo lo digo porque Andrea,\nque tiene su tecolote,\nque le chifle cuando vea.",105,2,-1,133,"Ahora pregunto, pregunto",0,4,"ea",54,0,-1,0,478,478,"5679","",0,"","","",2,0,0,[],""],["frenk_t2-n5681",6,"Señora, la chica no vino\nporque se quedó ordeñando;\ncomo las vacas son de ella,\ntoda la leche anda dando.",109,2,7,133,"Válgame Dios de los cielos’*",0,4,"ao",33,0,-1,0,478,478,"5681","",0,"","","",1,0,0,[],""],["frenk_t2-n5682",6,"¡Pobrecito del chilero!,\ntenía su huerta en la orilla,\nporque la pobre chilera\nle arrimaba la semilla,\nchile ancho y chile pasilla.",114,2,17,133,"El chilero",7,5,"ia",162,0,-1,0,478,478,"5682","",0,"","","",5,0,0,[],""],["frenk_t2-n5683",6,"¡Pobrecito del chilero!,\nse fue pa Guadalajara,\nporque la pobre chilera\npurito chile le enviaba,\nporque todavía el tomate,\ntodavía no maduraba.",114,2,17,133,"El chilero",9,6,"aa",28,0,-1,0,478,478,"5683","",0,"","","",5,0,0,[],""],["frenk_t2-n5684",6,"¡Pobrecito del chilero!,\nse fue para Santa Clara,\nporque la pobre chilera\nquería que se lo ensartara;\nseguro que en un tompeate,\ntodito se lo tomaba.",114,2,17,133,"El chilero",9,6,"aa",-1,0,-1,0,478,478,"5684","",0,"","","",5,0,0,[],""],["frenk_t2-n5685",6,"¡Pobrecito del chilero!,\ntenía su chile entrojado;\ncomo caía una gotera,\nlo sacó todo mojado.",114,2,17,133,"El chilero",0,4,"ao",14,0,-1,0,478,478,"5685","",0,"","","",5,0,0,[],""],["frenk_t2-n5686",6,"¡Pobrecito del chilero!,\ntodo se le va en llorar,\nporque se le está cayendo\nla fruta de su chilar;\npa que no se le cayera,\npuso el suyo de puntal.",114,2,17,133,"El chilero",9,6,"a",-1,0,-1,0,478,478,"5686","",0,"","","",5,0,0,[],""],["frenk_t2-n5687",6,"El chilero y la chilera\nse cayeron en el río;\nla chilera le decía:\n“¡Ya te estás quedando frío!”",114,2,17,133,"El chilero",0,4,"io",3,0,-1,0,479,479,"5687","",0,"","","",2,0,0,[],""],["frenk_t2-n5688",6,"El chilero y la chilera\nse cayeron en un charco;\nle chilera le decía:\n“Ya te estás quedando zarco.”",114,2,17,133,"El chilero",0,4,"ao",591,0,-1,0,479,479,"5688","",0,"","","",2,0,0,[],""],["frenk_t2-n5689",6,"Los mecos cuando se casan\nsiempre cargan su borrego:\nla meca carga la carne,\ny el meco se carga el cuero.",112,2,6,133,"Estrofa suelta",0,4,"eo",-1,0,-1,0,479,479,"5689","",0,"","","",1,0,0,[],""],["frenk_t2-n5690",6,"Cuando los mecos se casan\ntambién matan su borrego:\nellas se comen la came,\ny los mequitos el sebo.",110,2,10,133,"Los mecos; Canción de un indito",0,4,"eo",-1,0,-1,0,479,479,"5690","",0,"","","",1,0,0,[],""],["frenk_t2-n5691",6,"Oí a la mujer de Chucho\nplaticar con el mariachi;\ndice que le gusta mucho,\naunque traiga su huarache:\n“No le hace que ande como ande,\npero no más que se agache.”",105,2,-1,133,"Huapango de huapangos",9,6,"ae",-1,0,-1,0,479,479,"5691","",0,"","","",1,0,0,[],""],["frenk_t2-n5692",6,"“Echa pedazos, marchante”,\nle dijo un indio a una indiana,\nporque le estaba enseñando\nla estrella de la mañana.",108,2,8,133,"Estrofa suelta",0,4,"aa",4,0,-1,0,479,479,"5692","",0,"","","",1,0,0,[],""],["frenk_t2-n5693",6,"Una indita muy bonita\ntraía su tercio de ocote;\nel indio, con su guadaña,\nno más le servía de olote.",107,2,11,133,"La indita",0,4,"oe",292,0,-1,0,479,479,"5693","",0,"","","",2,0,0,[],""],["frenk_t2-n5694",6,"Un pajarito voló\nal interior de un convento,\ny las monjitas gozaban\ncon el pajarito adentro.",108,2,8,133,"Úrsula; La Sanmarqueña",0,4,"eo",-1,0,-1,0,479,479,"5694","",0,"","","",2,0,0,[],""],["frenk_t2-n5695",6,"Una monja se empachó\npor beber agua bendita,\ny del empacho salió\nuna monja chiquitita.",108,2,8,133,"La Petenera",1,4,"ia",50,0,-1,0,479,479,"5695","",0,"","","",2,0,0,[],""],["frenk_t2-n5697",6,"Lo que nunca habíamos visto\npor todito este contorno:\nque el pan de huevo y manteca\nse volviera gordas de homo.",105,2,-1,133,"La cucaracha",0,4,"oo",-1,0,-1,0,480,480,"5697","",0,"","","",1,0,0,[],""],["frenk_t2-n5698",6,"Mi comadre está muy gorda,\nyo no sé por qué será;\nserá por los alimentos\nque mi compadre le da.",115,2,3,133,"Mi comadre",0,4,"a",9,0,-1,0,480,480,"5698","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t2-n5699",6,"Mi comadre está enojada,\nyo no sé por qué será;\nla hallaron con mi compadre,\nhaciéndole una maldad.",115,2,3,133,"Mi comadre",0,4,"a",-1,0,-1,0,480,480,"5699","",0,"frenk_t4","","",6,0,0,[],""],["frenk_t2-n5701",6,"Mi comadre está enojada:\nno sé cuál será su intento;\nserá porque mi compadre\nno pasaba para dentro.",115,2,3,133,"Mi comadre",0,4,"eo",-1,0,-1,0,480,480,"5701","",0,"","","",6,0,0,[],""],["frenk_t2-n5702",6,"Ándale, que anoche sí,\nándale, que anoche no,\nporque se quedó dormido,\ny hasta la cena perdió\npor estar entretenido.",105,2,-1,133,"La trigueña",7,5,"io",101,0,-1,0,480,480,"5702","",0,"","","",1,0,0,[],""],["frenk_t2-n5703",6,"Yo no sé qué tiene Pancha,\nque llora toda la noche:\n¿si le picarán las pulgas\no le rozará el guangoche?",105,2,-1,133,"Yo no sé qué tiene Pancha",0,4,"oe",337,0,-1,0,480,480,"5703","",0,"","","",1,0,0,[],""],["frenk_t2-n5704",6,"Una india se fue a leñar\ny se le enterró una espina,\ny no se la pudo sacar\nporque tenía el indio encima\ny el pecho en el mecapal.",106,2,4,133,"La indita",7,5,"a",-1,0,-1,0,480,480,"5704","",0,"","","",1,0,0,[],""],["frenk_t2-n5705",6,"La primer noche de novios\nyo no sé lo que sintió:\nera un gato negro, negro,\nque las barbas le metió.",122,2,13,133,"Estrofa suelta",0,4,"o",2,0,-1,0,481,481,"5705","",0,"","","",1,0,0,[],""],["frenk_t2-n5706",6,"¡Qué dices del palomón,\ncómo se llevó a Josefa,\ny en la esquina del portal\nla dejó pelona y vieja!",106,2,4,133,"El palomo’",0,4,"ea",-1,0,-1,0,481,481,"5706","",0,"","","",1,0,0,[],""],["frenk_t2-n5707",6,"La muchacha en la bocana\nya no bajó al humador,\nporque ahí andan los ralitos\ncon tamaño cerrojote.",105,2,-1,133,"Las torcazas",5,4,"oe",-1,0,-1,0,481,481,"5707","",0,"","","",1,0,0,[],""],["frenk_t2-n5708",6,"“Sácamela, que me cago”,\ndijo la negra Francisca:\n“Ah, negro tan rechingado,\nque me revolvió las tripas.”",108,2,8,133,"Estrofa suelta",0,4,"ia",-1,0,-1,0,481,481,"5708","",0,"","","",1,0,0,[],""],["frenk_t2-n5709",6,"Lo lleva el hombre por delante,\nlo saca con mucho recelo,\nse le para de vez en cuando,\ntiene cabeza y también pelo.",105,2,-1,133,"Estrofa suelta",3,4,"eo",10,0,-1,0,481,481,"5709","",0,"","","",1,0,0,[],""],["frenk_t2-n5710",6,"Maldito el hombre\ncon tanto grito:\nque ya la tira,\nque ya la agarra,\ncon su manito.",105,2,-1,133,"Estrofa suelta",7,5,"io",119,0,-1,0,481,481,"5710","",0,"","","",1,0,0,[],""],["frenk_t2-n5712",6,"Carretas, ¿por qué rechinan?,\n¿porque les falta la untura?,\nAsí rechinan las beatas\nen las pajuelas del cura.",108,2,8,133,"Estrofa suelta",0,4,"ua",17,0,-1,0,481,481,"5712","",0,"","","",1,0,0,[],""],["frenk_t2-n5715",6,"Cupido con Salomón\nse hallan en grande orgía:\nSalomón porque era sabio,\nCupido porque lo sabía.",108,2,8,133,"Estrofa suelta",0,4,"ia",0,0,-1,0,482,482,"5715","",0,"","","",3,0,0,[],""],["frenk_t2-n5716",6,"Cupido con Salomón\ntuvieron sus damas juntas;\nSalomón, por ser tan sabio,\na Cupido le pregunta:\n“De tantas vueltas que dimos,\n¿dónde quedaría la punta?”",108,2,8,133,"Estrofa suelta",9,6,"ua",455,0,-1,0,482,482,"5716","",0,"","","",3,0,0,[],""],["frenk_t3-n5717",7,"El corral es un serrallo,\ndonde el gallo es un sultán,\ny un gallo con otro gallo\npeleando, peleando están.",135,2,-1,134,"El corral",3,4,"a",147,0,-1,0,28,28,"5717","",0,"","","",1,0,0,[],""],["frenk_t3-n5719",7,"En los cerros se dan tunas\ny en las barrancas pitayas;\nen los huecos de los palos\nanidan las guacamayas.",136,2,4,134,"La guacamaya; El cubilete",0,4,"aa",592,0,-1,0,28,28,"5719","",0,"","","",1,0,0,[],""],["frenk_t3-n5721",7,"Estando pescando un negro\nen un estero alcahuete,\ny le digo a los muchachos:\n“Éste es el mero cuateque,\nque se agarra con anzuelo\ny se guisa en el cajete”.",135,2,-1,134,"Ahora pregunto, pregunto",9,6,"ee",-1,0,-1,0,29,29,"5721","",0,"","","",1,0,0,[],""],["frenk_t3-n5722",7,"El huitlacoche de cerro\nse mantiene de la tuna,\ntambién le gusta pitaya\ny bolitas de aceituna.",137,2,3,134,"El vaquero",0,4,"ua",56,0,-1,0,29,29,"5722","",0,"","","",1,0,0,[],""],["frenk_t3-n5723",7,"Hay huitlacoches de cerro\ny huitlacoches de casa;\nel que vive en su jaulita\nsólo está comiendo masa.",137,2,3,134,"El vaquero",0,4,"aa",123,0,-1,0,29,29,"5723","",0,"","","",1,0,0,[],""],["frenk_t3-n5725",7,"Cuando las aguas se van\nqueda terrible el calor,\ny entonces sale el caimán\na darse baños de sol\na orillas del río Jordán.",138,2,6,134,"El caimán",7,5,"a",147,0,-1,0,29,29,"5725","",0,"","","",1,0,0,[],""],["frenk_t3-n5726",7,"El caimán es engañoso,\npues le gusta sorprender;\nes un animal mañoso:\ncuando mira una mujer,\nsale de lo pantanoso,\nle dan ganas de comer.",139,2,2,134,"El caimán",9,6,"e",20,0,-1,0,29,29,"5726","",0,"","","",1,0,0,[],""],["frenk_t3-n5727",7,"Cuando las palomitas\nbajan al agua,\ntodas juntan sus piquitos\ny tienden ’l ala.",140,2,12,134,"Las palomitas",6,4,"aa",-1,0,-1,0,29,29,"5727","",0,"","","",1,0,0,[],""],["frenk_t3-n5728",7,"Cuando me vine del valle\nme vine por los esteros,\ndonde se van a pasear\nlos pericos embusteros.",135,2,-1,134,"El Cihualteco",0,4,"eo",22,0,-1,0,29,29,"5728","",0,"","","",1,0,0,[],""],["frenk_t3-n5729",7,"Dicen que el gavilancito\nvolando viene y volando va;\nse pasa la mar de un vuelo:\ngavilancito, no vuele más.",135,2,-1,134,"El gavilancito",3,4,"a",-1,0,-1,0,30,30,"5729","",0,"","","",2,0,0,[],""],["frenk_t3-n5731",7,"¡Ay!, qué chispas son los cangrejos\npor su modito de caminar,\npor Dios que no aguanto la risa:\njajajajajá, jajajajá.",135,2,-1,134,"El cangrejo",3,4,"a",-1,0,-1,0,30,30,"5731","",0,"","","",1,0,0,[],""],["frenk_t3-n5732",7,"El cangrejo se va,\ncómo camina, miren no más;\nen vez de irse para delante,\nel pobrecito se va pa atrás.",135,2,-1,134,"El cangrejo",3,4,"a",51,0,-1,0,30,30,"5732","",0,"","","",1,0,0,[],""],["frenk_t3-n5734",7,"Se hacen chiquitos,\nse hacen grandotes;\nhacen la rueda\nlos guajolotes.",141,2,1,134,"Los enanos",6,4,"oe",565,0,-1,0,30,30,"5734","",0,"","","",1,0,0,[],""],["frenk_t3-n5735",7,"Al amigo mono (canelo)\npóngale cuidado:\ncómo hace maromas (canelo)\ncon el aro del rabo.",136,2,4,134,"El Canelo",0,4,"ao",-1,0,-1,0,30,30,"5735","",0,"","","",1,0,0,[],""],["frenk_t3-n5736",7,"Si buscares al tejón,\nbúscalo por los arroyos:\nno lo busques en las casas,\nque no es gallina con pollos.",135,2,-1,134,"El tejón",0,4,"oo",593,0,-1,0,30,30,"5736","",0,"","","",1,0,0,[],""],["frenk_t3-n5737",7,"Si buscaras al tejón,\nbúscalo por las playitas:\nno lo busques en las casas,\nque no es muchacha bonita.",135,2,-1,134,"El tejón",0,4,"ia",-1,0,-1,0,30,30,"5737","",0,"","","",1,0,0,[],""],["frenk_t3-n5738a",7,"Este torito que traigo\nno es prieto ni colorado:\nes un torito barroso,\nde los cuernos recortado.",136,2,4,134,"‘‘El torito; El toro",0,4,"ao",14,0,-1,0,31,31,"5738a","",0,"","","",10,0,0,[],""],["frenk_t3-n5738b",7,"Este torito que traigo\nde los llanos de Alvarado\nno es pinto ni es colorado:\nes un torito barroco,\nde los cuernos recortado.",136,2,4,134,"El torito",7,5,"ao",14,0,-1,0,31,31,"5738b","",0,"","","",10,0,0,[],""],["frenk_t3-n5739",7,"Pájaros, pájaros,\npájaros negros,\ntápalos, tápalos,\nno se te fueron.",140,2,12,134,"Pájaros negros",6,4,"eo",-1,0,-1,0,31,31,"5739","",0,"","","",1,0,0,[],""],["frenk_t3-n5740",7,"En un palomar sentada\nvi una guacamaya pura,\nde seis colores pintada,\nde muy bonita figura,\nverde, blanca y colorada,\nmorada, pinta y oscura.",136,2,4,134,"La guacamaya",9,6,"ua",17,0,-1,0,31,31,"5740","",0,"","","",1,0,0,[],""],["frenk_t3-n5741",7,"Vuela, vuela, guacamaya,\nque en el campo me la hallé,\nque aquí está esta guacamaya;\nde la manera que estaba\neso sí no lo diré.",142,2,8,134,"La guacamaya",7,5,"e",77,0,-1,0,31,31,"5741","",0,"","","",1,0,0,[],""],["frenk_t3-n5742a",7,"Estaba la guacamaya\nparada en un carrizuelo,\nsacudiéndose las alas\npara levantar el vuelo.",136,2,4,134,"La guacamaya",0,4,"eo",10,0,-1,0,31,31,"5742a","",0,"frenk_t4","","",9,0,0,[],""],["frenk_t3-n5742b",7,"Estaba la guacamaya\nparada en un comizuelo,\nsacudiéndose las alas\npara levantar el vuelo\ncuando tú mismo te vayas.",136,2,4,134,"La guacamaya",7,5,"aa",-1,0,-1,0,31,31,"5742b","",0,"","","",9,0,0,[],""],["frenk_t3-n5743",7,"Estaba la guacamaya\nparada en un platanar,\nsacudiéndose las alas\npara empezar a volar.",135,2,-1,134,"La guacamaya",0,4,"a",21,0,-1,0,31,31,"5743","",0,"","","",9,0,0,[],""],["frenk_t3-n5744",7,"Estaba la guacamaya\nparada en un tepozonte,\nsacudiéndose las alas\npara volar a otro monte.",136,2,4,134,"La guacamaya",0,4,"oe",325,0,-1,0,32,32,"5744","",0,"","","",9,0,0,[],""],["frenk_t3-n5745",7,"Estaba la guacamaya\nparada en un frijolillo,\nsacudiéndose las alas\nporque tenía pinolillo.",136,2,4,134,"La guacamaya",0,4,"io",228,0,-1,0,32,32,"5745","",0,"","","",9,0,0,[],""],["frenk_t3-n5746",7,"Estaba la guacamaya\nparada en un guachilote,\nsacudiéndose las alas\nporque tenía pepeyotes.",136,2,4,134,"La guacamaya",0,4,"oe",-1,0,-1,0,32,32,"5746","",0,"frenk_t4","","",9,0,0,[],""],["frenk_t3-n5747",7,"Y en un almendro florido\ny un pájaro se paró,\ny antes de entrar a su nido\nlas alas se sacudió;\n¡ay!, un pájaro advertido,\ncomo a la barrada dio.",136,2,4,134,"El pájaro cú",9,6,"o",2,0,-1,0,32,32,"5747","",0,"","","",1,0,0,[],""],["frenk_t3-n5748",7,"Señores, aquí está el guaco,\n¿quién lo quiere conocer?\nEs prietito, callejero,\ncomo el que lo supo hacer.",143,2,18,134,"‘‘El guaco Chano",0,4,"e",20,0,-1,0,32,32,"5748","",0,"","","",1,0,0,[],""],["frenk_t3-n5749",7,"Señora, su lagartijo\nparece que está enojado\nya tiene la panza verde\ny el pescuezo colorado.",135,2,-1,134,"El lagartijo",0,4,"ao",14,0,-1,0,32,32,"5749","",0,"","","",1,0,0,[],""],["frenk_t3-n5750",7,"¡Eho, eho, eho!,\n¡ah, qué gallina tan fea!\nque cuando se sube al palo\ntodita se zarandea.",135,2,-1,134,"‘‘Yo quise una china, china",3,4,"ea",54,0,-1,0,32,32,"5750","",0,"","","",2,0,0,[],""],["frenk_t3-n5751",7,"¡Eho, eho, eho!,\n¡ah, qué gallina tan loca!,\nque cuando se sube al palo\ntodos los gallos provoca.",135,2,-1,134,"Yo quise una china, china",3,4,"oa",178,0,-1,0,32,32,"5751","",0,"","","",2,0,0,[],""],["frenk_t3-n5752",7,"Una polla pinta\ny una colorada\nponen sus huevitos\nen la madrugada.",141,2,1,134,"‘‘La polla pinta",0,4,"aa",49,0,-1,0,32,32,"5752","",0,"","","",1,0,0,[],""],["frenk_t3-n5753",7,"Coire, muchacho,\ncorre corriendo,\nque la gallina\nya está poniendo.",136,2,4,134,"Estrofa suelta",6,4,"eo",52,0,-1,0,32,32,"5753","",0,"","","",1,0,0,[],""],["frenk_t3-n5754",7,"La pitacocha\nquiere poner;\ncorre, muchacho,\npor la pader.",144,2,10,134,"La güitacocha",6,4,"e",20,0,-1,0,33,33,"5754","",0,"","","",2,0,0,[],""],["frenk_t3-n5755",7,"Corre, muchacho,\npor la azotea,\nque la gallina\ncacaraquea.",136,2,4,134,"El trompito",6,4,"ea",54,0,-1,0,33,33,"5755","",0,"","","",2,0,0,[],""],["frenk_t3-n5756",7,"Corre, muchacho,\ncorre a caballo,\nque la gallina\ntiene otro gallo.",136,2,4,134,"Estrofa suelta",6,4,"ao",102,0,-1,0,33,33,"5756","",0,"","","",2,0,0,[],""],["frenk_t3-n5758",7,"Válgame Dios, ¿qué será esto?,\nválgame Dios, ¿qué será?\nUn pinacate salido\ndel fondo de la humedad.",145,2,17,134,"El pinacate",0,4,"a",-1,0,-1,0,33,33,"5758","",0,"","","",3,0,0,[],""],["frenk_t3-n5759",7,"¿Qué es aquello que verdea\ny en medio de la sabana?\nYo creía que era zacate,\ny era la malvada iguana.",136,2,4,134,"La iguana",0,4,"aa",4,0,-1,0,33,33,"5759","",0,"","","",1,0,0,[],""],["frenk_t3-n5760",7,"¿Qué pajarillo es aquel\nque se ha venido volando?\nNo lo puedo conocer\nsobre la tierra andando.",138,2,6,134,"Pajarillo barranqueño",0,4,"ao",33,0,-1,0,33,33,"5760","",0,"","","",8,0,0,[],""],["frenk_t3-n5761",7,"Ven, que la lluvia\nde invierno se fue;\narrulla su nido\nla paloma fiel.",135,2,-1,134,"Pastorcita virgen",6,4,"e",-1,0,-1,0,33,33,"5761","",0,"","","",1,0,0,[],""],["frenk_t3-n5762",7,"Volaron cuatro palomas\ndel trigo pa’ la cebada;\nvolaron de loma en loma\npara la Sierra Mojada.",135,2,-1,134,"Bonito San Juan del Río",0,4,"aa",49,0,-1,0,33,33,"5762","",0,"","","",3,0,0,[],""],["frenk_t3-n5763",7,"Allá va el guaquito Chano,\nvolando por las barrancas,\n¿Cómo quieres que me quede,\nsi soy de la Tierra Blanca?",143,2,18,134,"El guaco Chano",0,4,"aa",-1,0,-1,0,34,34,"5763","",0,"","","",1,0,0,[],""],["frenk_t3-n5764",7,"Por áhi va la garza,\ndéjenla volar,\nva tomando viento\npara doblegar.",142,2,8,134,"La garza",0,4,"a",21,0,-1,0,34,34,"5764","",0,"","","",1,0,0,[],""],["frenk_t3-n5765",7,"No hablo con el tecolote,\nhablo con el caporal;\n¿qué tiene su tecolote,\nque lo encontró en el corral?",137,2,3,134,"El tecolote",1,4,"a",1,0,-1,0,34,34,"5765","",0,"","","",1,0,0,[],""],["frenk_t3-n5766",7,"Yo me embarqué en un chalán\npa saber a la Huasteca,\ny al pasar el río Jordán\nme dijo una chichimeca:\n“Por aquí pasó el caimán\ncon una patita chueca”.",141,2,1,134,"El caimán",9,6,"ea",594,0,-1,0,34,34,"5766","",0,"","","",3,0,0,[],""],["frenk_t3-n5767",7,"Se va el caimán, se va el caimán,\nse va para la otra orilla,\nse va el caimán, se va el caimán,\nse va para Barranquilla.",139,2,2,134,"El caimán viejo",1,4,"ia",162,0,-1,0,34,34,"5767","",0,"","","",2,0,0,[],""],["frenk_t3-n5768",7,"Se va el caimán, se va el caimán,\nse va para Veracruz;\nse va el caimán, se va el caimán,\npero [le faltó] su luz.",139,2,2,134,"El caimán viejo",1,4,"u",109,0,-1,0,34,34,"5768","",0,"","","",2,0,0,[],""],["frenk_t3-n5769",7,"Suni, suni, suni,\nla zopilotita,\nsuni, suni, suni,\nse fue para el puerto.",146,2,7,134,"El zopilote",5,4,"eo",-1,0,-1,0,34,34,"5769","",0,"","","",2,0,0,[],""],["frenk_t3-n5770",7,"Suni, suni, suni,\nla zopilotita,\nsuni, suni, suni,\nse fue pa el potrero.",146,2,7,134,"El zopilote",5,4,"eo",-1,0,-1,0,34,34,"5770","",0,"","","",2,0,0,[],""],["frenk_t3-n5771",7,"Una vaquilla barrosa,\njunta con el toro prieto,\nse fue del país donde agosta\nhace muy poquito tiempo.",145,2,17,134,"Estrofa suelta",0,4,"eo",-1,0,-1,0,34,34,"5771","",0,"","","",1,0,0,[],""],["frenk_t3-n5772",7,"Áhi viene la vaca mora\nbramando por los jarales,\nya viene pasando el río\njunto con los caporales;\nesa indina vaca mora\nse cortó a los tecorrales.",135,2,-1,134,"La vaca mora",9,6,"ae",26,0,-1,0,34,34,"5772","",0,"","","",1,0,0,[],""],["frenk_t3-n5773",7,"¡Ay, qué torito que brama,\nmuy rico y muy sabrosón!,\neste torito baboso\nque llegó de Apatzingán.",137,2,3,134,"El torito",5,4,"a",-1,0,-1,0,35,35,"5773","",0,"","","",2,0,0,[],""],["frenk_t3-n5774",7,"En la loma brama un toro,\ny abajo lo están oyendo,\nlas vacas en el corral\nremolino están haciendo.",145,2,17,134,"Estrofa suelta",0,4,"eo",52,0,-1,0,35,35,"5774","",0,"","","",1,0,0,[],""],["frenk_t3-n5775",7,"Las muchachas de mi tierra\nremolino están haciendo;\nlas vacas en el corral\nno más las están oyendo.",145,2,17,134,"Estrofa suelta",0,4,"eo",52,0,-1,0,35,35,"5775","",0,"","","",7,0,0,[],""],["frenk_t3-n5776",7,"Éste es un burrito sabio,\nque viene a buscar destino;\ncomo aquí no es conocido,\nno pudo encontrar padrino.",135,2,-1,134,"El burrito",0,4,"io",-1,0,-1,0,35,35,"5776","",0,"","","",2,0,0,[],""],["frenk_t3-n5778",7,"Por la orilla, ¡ay!, por la orilla\nanda la vaca amarilla;\npor la orilla de un potrero,\ncon su becerrito güero.",138,2,6,134,"La rosita arribeña",5,4,"eo",38,0,-1,0,35,35,"5778","",0,"","","",1,0,0,[],""],["frenk_t3-n5779",7,"Dicen que la vaca mora\ntiene un ternero que es pinto,\nque ese ternero es el hijo\ndel toro de Don Jacinto.",135,2,-1,134,"La vaca mora",0,4,"io",-1,0,-1,0,35,35,"5779","",0,"","","",1,0,0,[],""],["frenk_t3-n5780",7,"La vaca era colorada\ny el becerrito era moro,\ny el vaquero sospechaba\nque era hijo de otro toro.",135,2,-1,134,"El toro; Estrofa suelta",0,4,"oo",85,0,-1,0,35,35,"5780","",0,"","","",1,0,0,[],""],["frenk_t3-n5781",7,"La vaquilla tuvo cuates\nel día primero del mes;\nuno le mama al derecho,\ny otro le mama al revés.",143,2,18,134,"La vaquilla; Al derecho y al revés; Estrofa suelta",0,4,"e",218,0,-1,0,36,36,"5781","",0,"","","",2,0,0,[],""],["frenk_t3-n5782",7,"La vaquilla tuvo cuates,\ny uno de ellos está sordo;\nmientras uno está durmiendo,\n’l otro está mamando gordo.",135,2,-1,134,"La vaquilla",0,4,"oo",595,0,-1,0,36,36,"5782","",0,"","","",2,0,0,[],""],["frenk_t3-n5783",7,"La puerca no quiere el maíz,\nni los puerquitos la leche;\nno quieren comer parados:\nhasta que la puerca se eche.",142,2,8,134,"Indita del alma; El palmero",0,4,"ee",180,0,-1,0,36,36,"5783","",0,"","","",1,0,0,[],""],["frenk_t3-n5784",7,"Una gallina variada\nempolló un guajolotito;\neso sucede a menudo\ncon cualquier animalito.",135,2,-1,134,"Con un polvo y otro polvo",0,4,"io",119,0,-1,0,36,36,"5784","",0,"","","",1,0,0,[],""],["frenk_t3-n5785",7,"Una gallina con pollos\na sus hijos mantenía\ncon el pico y las uñitas,\nporque chiches no tenía.",147,2,11,134,"El gallo",0,4,"ia",-1,0,-1,0,36,36,"5785","",0,"","","",2,0,0,[],""],["frenk_t3-n5786",7,"Una gallina echada\ncon once huevos\nsacó diez pollos blancos (cielito lindo)\ny un pollo negro.\nLa cuidaremos,\npa que cuando te cases (mi vida)\nla mataremos.",138,2,6,134,"Cielito lindo",4,7,"eo",127,0,-1,0,36,36,"5786","",0,"","","",1,0,0,[],""],["frenk_t3-n5787",7,"Los cenzontles con sus cantos\nalegran los corazones;\nencerrados en sus jaulas,\ncantan sus dulces canciones.",135,2,-1,134,"El pajarerito",0,4,"oe",34,0,-1,0,36,36,"5787","",0,"frenk_t4","","",2,0,0,[],""],["frenk_t3-n5788",7,"Un marinero al pasar,\nallá por el mes de enero\ndicen que se oyó gorjear\nel pájaro carpintero.",135,2,-1,134,"Estrofa suelta",1,4,"eo",38,0,-1,0,36,36,"5788","",0,"","","",1,0,0,[],""],["frenk_t3-n5789",7,"De los pájaros primero\nque en este mundo han gorjeado,\nel cinzontle y el jilguero,\ny de lo más apreciado,\nel pájaro carpintero.",136,2,4,134,"El pájaro carpintero",7,5,"eo",38,0,-1,0,37,37,"5789","",0,"","","",1,0,0,[],""]]);
